A.bhH=new B.cM("\uc5c5\ubb34\uac00 \ub108\ubb34 \ub9ce\uc544\uc11c \ud798\ub4e4 \ub54c \ud300\uc7a5\uc5d0\uac8c \uc5b4\ub5bb\uac8c \ub9d0\ud558\uaca0\uc2b5\ub2c8\uae4c?",A.iX8,"\ud300\uc7a5\ub2d8, \ud604\uc7ac \uc5c5\ubb34 \uc9c4\ud589 \uc0c1\ud669\uc5d0 \ub300\ud574 \ub9d0\uc500\ub4dc\ub9ac\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \uc774\ubc88 \uc8fc\uc5d0 \ucc98\ub9ac\ud574\uc57c \ud560 \uc5c5\ubb34\uac00 \uc5ec\ub7ec \uac1c \uacb9\uccd0 \uc788\uc5b4\uc11c \ubaa8\ub450 \ub9c8\uac10 \uc2dc\uac04 \uc548\uc5d0 \ub05d\ub0b4\uae30 \uc5b4\ub824\uc6b8 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \ud2b9\ud788 A\uc5c5\ubb34\uc640 B\uc5c5\ubb34\ub97c \ub3d9\uc2dc\uc5d0 \uc9c4\ud589\ud558\ub294 \uac83\uc774 \uc870\uae08 \ubd80\ub2f4\uc2a4\ub7fd\uc2b5\ub2c8\ub2e4. \uc5b4\ub5a4 \uc5c5\ubb34\ub97c \uba3c\uc800 \ucc98\ub9ac\ud574\uc57c \ud558\ub294\uc9c0 \uc6b0\uc120\uc21c\uc704\ub97c \ub2e4\uc2dc \ud655\uc778\ud574 \uc8fc\uc2e4 \uc218 \uc788\uc744\uae4c\uc694? \ud544\uc694\ud558\ub2e4\uba74 \uc77c\ubd80 \uc5c5\ubb34\uc5d0 \ub3c4\uc6c0\uc744 \uc694\uccad\ud558\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.")
A.iDp=s(["\uacf5\uac10","\ud798\ub4e4\ub2e4","\uc18d\uc0c1\ud558\ub2e4","\uaca9\ub824","\ub3c4\uc6c0"],t.s)
A.bhx=new B.cM("\ud798\ub4e4\uc5b4\ud558\ub294 \uce5c\uad6c\ub97c \uc704\ub85c\ud574 \ubcf4\uc138\uc694.",A.iDp,"\uadf8\ub3d9\uc548 \uc815\ub9d0 \ub9ce\uc774 \ud798\ub4e4\uc5c8\uaca0\uc5b4. \uc5f4\uc2ec\ud788 \ud588\ub294\ub370 \uc6d0\ud558\ub294 \uacb0\uacfc\uac00 \ub098\uc624\uc9c0 \uc54a\uc73c\uba74 \ub204\uad6c\ub77c\ub3c4 \uc18d\uc0c1\ud560 \uac83 \uac19\uc544. \uadf8\ub807\uc9c0\ub9cc \uc774\ubc88 \uacb0\uacfc \ud558\ub098\ub9cc\uc73c\ub85c \ub124\uac00 \ubd80\uc871\ud558\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\uc558\uc73c\uba74 \uc88b\uaca0\uc5b4. \uc870\uae08 \uc26c\uace0 \ub098\uc11c \ub2e4\uc2dc \uc900\ube44\ud558\ub2e4 \ubcf4\uba74 \ubd84\uba85\ud788 \ub354 \uc88b\uc544\uc9c8 \uac70\uc57c. \ub0b4\uac00 \ub3c4\uc6b8 \uc218 \uc788\ub294 \uc77c\uc774 \uc788\uc73c\uba74 \uc5b8\uc81c\ub4e0\uc9c0 \ub9d0\ud574.")
A.hdF=s([A.bhv,A.bhH,A.bhx],t.Pe)
A.khH=s(["\ubb34\uc5c7\uc744 \uace0\ubbfc\ud558\uace0 \uc788\ub294\uc9c0 \uc4f0\uc138\uc694.","\uc65c \uac71\uc815\ub418\ub294\uc9c0 \uc4f0\uc138\uc694.","\uc5b4\ub5a4 \uc120\ud0dd\uc774 \uc788\ub294\uc9c0 \uc4f0\uc138\uc694.","\uc5b4\ub5bb\uac8c \ud574\uacb0\ud558\ub824\uace0 \ud558\ub294\uc9c0 \uc4f0\uc138\uc694.","V-(\uc73c)\u3139\uae4c \ubd10\uc640 V-\uc544/\uc5b4\uc57c \ud560\uc9c0 \ubaa8\ub974\uaca0\ub2e4\ub97c \uc0ac\uc6a9\ud574 \ubcf4\uc138\uc694."],t.s)
A.bqP=new B.dO("\ucd5c\uadfc\uc758 \uace0\ubbfc\uacfc \ud574\uacb0 \ubc29\ubc95\uc5d0 \ub300\ud574 \uc368 \ubcf4\uc138\uc694.","\uc694\uc998 \uc800\ub294 \uc0c8\ub85c\uc6b4 \uc9c1\uc7a5\uc5d0 \uc9c0\uc6d0\ud574\uc57c \ud560\uc9c0 \uacc4\uc18d \uace0\ubbfc\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc9c0\uae08 \ud68c\uc0ac\uc5d0\uc11c\ub3c4 \uc77c\uc744 \ud560 \uc218 \uc788\uc9c0\ub9cc \uc55e\uc73c\ub85c \ub354 \ubc1c\uc804\ud560 \uc218 \uc788\ub294 \uc77c\uc744 \ud574 \ubcf4\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc0c8\ub85c\uc6b4 \ud68c\uc0ac\uc5d0 \uac00\uba74 \uc5c5\ubb34\uc640 \ud658\uacbd\uc5d0 \uc798 \uc801\uc751\ud558\uc9c0 \ubabb\ud560\uae4c \ubd10 \uac71\uc815\ub429\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc9c0\uae08 \ubc14\ub85c \ud68c\uc0ac\ub97c \uadf8\ub9cc\ub450\uae30\ubcf4\ub2e4\ub294 \uba3c\uc800 \uc81c\uac00 \uc6d0\ud558\ub294 \uc9c1\ubb34\uc640 \uc870\uac74\uc744 \uc815\ub9ac\ud558\ub824\uace0 \ud569\ub2c8\ub2e4. \uadf8\ub9ac\uace0 \uc5ec\ub7ec \ud68c\uc0ac\uc758 \ucc44\uc6a9 \uc815\ubcf4\ub97c \ube44\uad50\ud55c \ud6c4 \uc5b4\ub5a4 \uc120\ud0dd\uc744 \ud574\uc57c \ud560\uc9c0 \uacb0\uc815\ud558\ub824\uace0 \ud569\ub2c8\ub2e4.")
A.ki2=s(["\uc5b8\uc81c \uc2a4\ud2b8\ub808\uc2a4\ub97c \ubc1b\ub294\uc9c0 \uc4f0\uc138\uc694.","\uadf8\ub54c \uc5b4\ub5a4 \uac10\uc815\uc744 \ub290\ub07c\ub294\uc9c0 \uc4f0\uc138\uc694.","\uc2a4\ud2b8\ub808\uc2a4\ub97c \ud478\ub294 \ubc29\ubc95\uc744 \uc4f0\uc138\uc694.","\uc8fc\ubcc0 \uc0ac\ub78c\uc758 \ub3c4\uc6c0\uc5d0 \ub300\ud574 \uc4f0\uc138\uc694.","V-\ub2e4 \ubcf4\uba74\uacfc V/A-\ub354\ub77c\ub3c4\ub97c \uc0ac\uc6a9\ud574 \ubcf4\uc138\uc694."],t.s)
A.bqZ=new B.dO("\uc2a4\ud2b8\ub808\uc2a4\ub97c \ubc1b\uc744 \ub54c \uc790\uc2e0\uc758 \ud574\uacb0 \ubc29\ubc95\uc744 \uc368 \ubcf4\uc138\uc694.","\uc800\ub294 \uc77c\uc774 \ud55c\uaebc\ubc88\uc5d0 \ub9ce\uc544\uc9c0\uac70\ub098 \uacc4\ud68d\ub300\ub85c \uc9c4\ud589\ub418\uc9c0 \uc54a\uc744 \ub54c \uc2a4\ud2b8\ub808\uc2a4\ub97c \ub9ce\uc774 \ubc1b\uc2b5\ub2c8\ub2e4. \ud2b9\ud788 \ud574\uc57c \ud560 \uc77c\uc774 \uacc4\uc18d \uc313\uc774\uba74 \ub9c8\uc74c\uc774 \ub2f5\ub2f5\ud558\uace0 \uc2e4\uc218\ud560\uae4c \ubd10 \uac71\uc815\ub429\ub2c8\ub2e4. \uadf8\ub7f4 \ub54c\ub294 \uba3c\uc800 \ud574\uc57c \ud560 \uc77c\uc744 \ud558\ub098\uc529 \uc815\ub9ac\ud558\uace0 \uc6b0\uc120\uc21c\uc704\ub97c \uc815\ud569\ub2c8\ub2e4. \uc2dc\uac04\uc774 \uc788\uc73c\uba74 \uc0b0\ucc45\uc744 \ud558\uac70\ub098 \uc6b4\ub3d9\uc744 \ud558\uba74\uc11c \uc2a4\ud2b8\ub808\uc2a4\ub97c \ud489\ub2c8\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ubb38\uc81c\uac00 \ub108\ubb34 \ud06c\uac8c \ub290\uaef4\uc9c0\ub354\ub77c\ub3c4 \ud558\ub098\uc529 \ucc98\ub9ac\ud558\ub2e4 \ubcf4\uba74 \uc0c1\ud669\uc774 \uc870\uae08\uc529 \uc88b\uc544\uc9c8 \ub54c\uac00 \ub9ce\uc2b5\ub2c8\ub2e4. \ud63c\uc790 \ud574\uacb0\ud558\uae30 \uc5b4\ub824\uc6b4 \ubb38\uc81c\ub294 \ub3d9\ub8cc\ub098 \uce5c\uad6c\uc5d0\uac8c \uc774\uc57c\uae30\ud558\uace0 \ub3c4\uc6c0\uc744 \uc694\uccad\ud558\uae30\ub3c4 \ud569\ub2c8\ub2e4.")
