A.bgZ=new B.cM("\uc81c\ud488 \ubd88\ub7c9\uc744 \ubc1c\uacac\ud588\uc744 \ub54c \ud300\uc7a5\uc5d0\uac8c \ubcf4\uace0\ud574 \ubcf4\uc138\uc694.",A.hxd,"\ud300\uc7a5\ub2d8, \ud604\uc7ac \uc0dd\uc0b0 \uc911\uc778 \uc81c\ud488\uc5d0\uc11c \ubd88\ub7c9\uc774 \ubc1c\uc0dd\ud574\uc11c \ubcf4\uace0\ub4dc\ub9bd\ub2c8\ub2e4. \uc57d 20\ubd84 \uc804\ubd80\ud130 \uc81c\ud488 \ud45c\uba74 \uac19\uc740 \uc704\uce58\uc5d0 \ud760\uc9d1\uc774 \ubc18\ubcf5\ud574\uc11c \ub098\uc624\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc9c0\uae08\uae4c\uc9c0 \ubd88\ub7c9\ud488\uc740 \uc5ec\uc12f \uac1c \ud655\uc778\ub410\uc2b5\ub2c8\ub2e4. \uc815\ud655\ud55c \uc6d0\uc778\uc740 \uc544\uc9c1 \ud30c\uc545\ud558\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4. \uc6b0\uc120 \ucd94\uac00 \ubd88\ub7c9\uc774 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub3c4\ub85d \uc791\uc5c5\uc744 \uc7a0\uc2dc \uc911\uc9c0\ud558\uace0 \ubd88\ub7c9\ud488\uc744 \ub530\ub85c \ubd84\ub9ac\ud588\uc2b5\ub2c8\ub2e4. \uc9c0\uae08 \uc7a5\ube44 \uc0c1\ud0dc\uc640 \uc791\uc5c5 \uc870\uac74\uc744 \ud655\uc778\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.")
A.fG2=s(["\uc810\uac80 \uacb0\uacfc","\uc6d0\uc778","\uc870\uc815","\uc2dc\ud5d8 \uc0dd\uc0b0","\uacb0\uacfc"],t.s)
A.bhA=new B.cM("\uc6d0\uc778\uc744 \ud655\uc778\ud55c \ud6c4 \uc870\uce58 \ub0b4\uc6a9\uc744 \ubcf4\uace0\ud574 \ubcf4\uc138\uc694.",A.fG2,"\uc7a5\ube44\ub97c \uc810\uac80\ud55c \uacb0\uacfc \uc81c\ud488\uc744 \uace0\uc815\ud558\ub294 \uac00\uc774\ub4dc \uc704\uce58\uac00 \uae30\uc900\ubcf4\ub2e4 \uc57d\uac04 \ud2c0\uc5b4\uc9c4 \uac83\uc744 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4. \uc774 \ubd80\ubd84\uc774 \uc81c\ud488 \ud45c\uba74\uc5d0 \ud760\uc9d1\uc774 \ubc1c\uc0dd\ud55c \uc8fc\uc694 \uc6d0\uc778\uc778 \uac83\uc73c\ub85c \ubcf4\uc785\ub2c8\ub2e4. \uac00\uc774\ub4dc \uc704\uce58\ub97c \uae30\uc900\uc5d0 \ub9de\uac8c \ub2e4\uc2dc \uc870\uc815\ud55c \ud6c4 \uc2dc\ud5d8 \uc0dd\uc0b0\uc744 \uc9c4\ud589\ud588\uc2b5\ub2c8\ub2e4. \uc2dc\ud5d8 \uc0dd\uc0b0\ud55c \uc5f4 \uac1c \uc81c\ud488\uc5d0\uc11c\ub294 \uac19\uc740 \ubd88\ub7c9\uc774 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. \ud604\uc7ac\ub294 \uc815\uc0c1\uc801\uc73c\ub85c \uc0dd\uc0b0\uc744 \uc7ac\uac1c\ud55c \uc0c1\ud0dc\uc785\ub2c8\ub2e4.")
