A.bdL=new B.a6("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\ubbfc\uc218 \uc528\ub294 \ub450 \ud68c\uc0ac \uc911 \uc5b4\ub514\uc5d0 \uac08\uc9c0 \uace0\ubbfc\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. A\ud68c\uc0ac\ub294 \uae09\uc5ec\uac00 \ub192\uc9c0\ub9cc \uc9d1\uc5d0\uc11c \uba40\uace0 \uc57c\uadfc\uc774 \ub9ce\uc2b5\ub2c8\ub2e4. B\ud68c\uc0ac\ub294 \uae09\uc5ec\ub294 \uc870\uae08 \ub0ae\uc9c0\ub9cc \uc9d1\uc5d0\uc11c \uac00\uae5d\uace0 \ubc30\uc6b0\uace0 \uc2f6\uc740 \uc77c\uc744 \ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubbfc\uc218 \uc528\ub294 \uae09\uc5ec\ubfd0\ub9cc \uc544\ub2c8\ub77c \uadfc\ubb34 \ud658\uacbd\uacfc \ubc1c\uc804 \uac00\ub2a5\uc131\ub3c4 \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud569\ub2c8\ub2e4.",A.hsE,2,"\uc77d\uae30")
A.h4H=s(["\ub300\uc548","\uac10\uc815","\uc11c\ub958","\uc218\uc218\ub8cc"],t.s)
A.bfk=new B.a6("\ud604\uc7ac \ubc29\ubc95\uc774 \uc5b4\ub824\uc6b8 \ub54c \ub300\uc2e0 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \ub2e4\ub978 \ubc29\ubc95\uc740?",A.h4H,0,"\uc5b4\ud718")
A.iMb=s(["\uadfc\ubb34 \ud658\uacbd","\uae09\uc5ec","\ubc1c\uc804 \uac00\ub2a5\uc131","\uba74\uc811\uad00\uc758 \uc2e0\ubc1c \uc0c9\uae54"],t.s)
A.bbE=new B.a6("\uc9c1\uc7a5\uc744 \uc120\ud0dd\ud560 \ub54c \uace0\ub824\ud560 \uc218 \uc788\ub294 \uae30\uc900\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud558\uc9c0 \uc54a\uc740 \uac83\uc740?",A.iMb,3,"\uc120\ud0dd")
A.h0C=s(["\uc870\uae08 \ube44\uc2f8\ub354\ub77c\ub3c4 B\uc548\uc744 \uc120\ud0dd\ud558\ub294 \uac83\uc774 \ub098\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4.","\ubb34\uc870\uac74 \uc2fc \uac83\uc774 \ucd5c\uace0\uc785\ub2c8\ub2e4.","\uc544\ubb34 \uc81c\ud488\uc774\ub098 \uc120\ud0dd\ud558\uba74 \ub429\ub2c8\ub2e4.","\uac00\uaca9\uacfc \ud488\uc9c8\uc740 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc5c6\uc2b5\ub2c8\ub2e4."],t.s)
A.bcc=new B.a6("A\uc548\uc740 \uc2f8\uc9c0\ub9cc \ud488\uc9c8\uc774 \ub0ae\uace0 B\uc548\uc740 \uc870\uae08 \ube44\uc2f8\uc9c0\ub9cc \uc624\ub798 \uc0ac\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc7a5\uae30 \uc0ac\uc6a9\uc774 \uc911\uc694\ud558\ub2e4\uba74 \uac00\uc7a5 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \uc758\uacac\uc740?",A.h0C,0,"\uc2e4\uc81c \uc0c1\ud669")
A.hk6=s(["\ud55c \uac00\uc9c0 \uc815\ubcf4\ub9cc \ubcf4\uace0 \ubc14\ub85c \uacb0\uc815\ud55c\ub2e4.","\uac10\uc815\uc774 \uac00\uc7a5 \uac15\ud560 \ub54c \uacb0\uc815\ud55c\ub2e4.","\uc7a5\ub2e8\uc810\uacfc \uc5ec\ub7ec \uc870\uac74\uc744 \ube44\uad50\ud558\uace0 \uc6b0\uc120\uc21c\uc704\ub97c \uc0dd\uac01\ud55c\ub2e4.","\ub2e4\ub978 \uc0ac\ub78c\uc758 \uc120\ud0dd\uc744 \ubb34\uc870\uac74 \ub530\ub77c \ud55c\ub2e4."],t.s)
A.bde=new B.a6("\uc88b\uc740 \uacb0\uc815\uc744 \ub0b4\ub9ac\ub294 \ubc29\ubc95\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",A.hk6,2,"\uc885\ud569")
