A.i4W=s(["\uc81c \uc0dd\uac01\uc5d0\ub294","\uc774\uc720","\uc7a5\uc810","\ube44\uc6a9","\ud6a8\uc728","\uc81c\uc548"],t.s)
A.bhm=new B.cM("\ud68c\uc758\uc5d0\uc11c \uc790\uc2e0\uc758 \uc758\uacac\uc744 \ub9d0\ud574 \ubcf4\uc138\uc694.",A.i4W,"\uc81c \uc0dd\uac01\uc5d0\ub294 \ud604\uc7ac \uc791\uc5c5 \ubc29\uc2dd\uc744 \uc870\uae08 \ubcc0\uacbd\ud558\ub294 \uac83\uc774 \uc88b\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \uc9c0\uae08 \ubc29\ubc95\uc740 \uc548\uc815\uc801\uc774\ub77c\ub294 \uc7a5\uc810\uc774 \uc788\uc9c0\ub9cc \uc791\uc5c5 \uc2dc\uac04\uc774 \ub108\ubb34 \uc624\ub798 \uac78\ub9bd\ub2c8\ub2e4. \uc0c8\ub85c\uc6b4 \ubc29\ubc95\uc744 \uc0ac\uc6a9\ud558\uba74 \ucd08\uae30 \uc900\ube44\uac00 \ud544\uc694\ud558\uc9c0\ub9cc \uc791\uc5c5 \uc2dc\uac04\uc744 \uc904\uc77c \uc218 \uc788\uc744 \ubfd0\ub9cc \uc544\ub2c8\ub77c \uc778\uc6d0\ub3c4 \ud6a8\uc728\uc801\uc73c\ub85c \ubc30\uce58\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \uba3c\uc800 \uc77c\ubd80 \uacf5\uc815\uc5d0\uc11c \uc2dc\ud5d8\ud574 \ubcf4\ub294 \ubc29\ubc95\uc744 \uc81c\uc548\ud558\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.")
A.hT6=s(["\uae09\uc5ec","\uadfc\ubb34 \uc2dc\uac04","\uac70\ub9ac","\uc5c5\ubb34 \ub0b4\uc6a9","\ubc1c\uc804 \uac00\ub2a5\uc131","\uc120\ud0dd \uae30\uc900"],t.s)
A.bhC=new B.cM("\ub450 \uc9c1\uc7a5 \uc911 \ud558\ub098\ub97c \uc120\ud0dd\ud55c\ub2e4\uace0 \uc0dd\uac01\ud558\uace0 \ube44\uad50\ud574 \ubcf4\uc138\uc694.",A.hT6,"A\ud68c\uc0ac\ub294 \uae09\uc5ec\uac00 \ub192\uc740 \ubc18\uba74\uc5d0 \ucd9c\ud1f4\uadfc \uc2dc\uac04\uc774 \uae38\uace0 \uc57c\uadfc\ub3c4 \ub9ce\uc740 \ud3b8\uc785\ub2c8\ub2e4. B\ud68c\uc0ac\ub294 \uae09\uc5ec\ub294 \uc870\uae08 \ub0ae\uc9c0\ub9cc \uc9d1\uc5d0\uc11c \uac00\uae5d\uace0 \uc81c\uac00 \ubc30\uc6b0\uace0 \uc2f6\uc740 \uc5c5\ubb34\ub97c \ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc800\ub294 \uae09\uc5ec\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc7a5\uae30\uc801\uc778 \ubc1c\uc804 \uac00\ub2a5\uc131\uacfc \uc0dd\ud65c \uc2dc\uac04\uc744 \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud558\ub294 \ud3b8\uc785\ub2c8\ub2e4. \uadf8\ub798\uc11c \ud604\uc7ac \uc870\uac74\uc774\ub77c\uba74 B\ud68c\uc0ac\ub97c \uc120\ud0dd\ud558\ub294 \uac83\uc774 \uc800\uc5d0\uac8c \ub354 \uc801\ud569\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.")
A.hqZ=s(["\uc774\ud574\ud558\ub2e4","\ub2e4\ub978 \uc758\uacac","\uc774\uc720","\ubb38\uc81c\uc810","\ub300\uc548"],t.s)
A.bhL=new B.cM("\ub2e4\ub978 \uc0ac\ub78c\uc758 \uc758\uacac\uc5d0 \ubc18\ub300\ud560 \ub54c \ubd80\ub4dc\ub7fd\uac8c \ub9d0\ud574 \ubcf4\uc138\uc694.",A.hqZ,"\ub9d0\uc500\ud558\uc2e0 \ubc29\ubc95\uc758 \uc7a5\uc810\uc740 \uc774\ud574\ud569\ub2c8\ub2e4. \ub2e4\ub9cc \ud604\uc7ac \uc778\uc6d0\uc73c\ub85c \ubaa8\ub4e0 \uc791\uc5c5\uc744 \ub3d9\uc2dc\uc5d0 \uc9c4\ud589\ud558\ub294 \uac83\uc740 \uc870\uae08 \uc5b4\ub824\uc6b8 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \uc791\uc5c5\ub7c9\uc774 \ub9ce\uc544\uc9c0\uba74 \uc2e4\uc218\uac00 \ub298\uc5b4\ub0a0 \uac00\ub2a5\uc131\ub3c4 \uc788\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \uadf8\ub798\uc11c \uba3c\uc800 \uc911\uc694\ud55c \uc791\uc5c5\ubd80\ud130 \ucc98\ub9ac\ud558\uace0 \ub098\uba38\uc9c0\ub294 \ub2e4\uc74c \ub2e8\uacc4\ub85c \uc9c4\ud589\ud558\ub294 \ubc29\ubc95\uc744 \ub300\uc548\uc73c\ub85c \uac80\ud1a0\ud558\uba74 \uc5b4\ub5a8\uae4c\uc694?")
A.h8U=s([A.bhm,A.bhC,A.bhL],t.Pe)
A.ki_=s(["\uc790\uc2e0\uc758 \uc120\ud0dd \uae30\uc900\uc744 \uc4f0\uc138\uc694.","\uae09\uc5ec\uc5d0 \ub300\ud55c \uc0dd\uac01\uc744 \uc4f0\uc138\uc694.","\uadfc\ubb34 \ud658\uacbd\uc774\ub098 \uc2dc\uac04\uc5d0 \ub300\ud574 \uc4f0\uc138\uc694.","\ubc1c\uc804 \uac00\ub2a5\uc131\uc5d0 \ub300\ud574 \uc4f0\uc138\uc694.","N\uc5d0 \ube44\ud574\uc11c\uc640 V/A-(\uc73c)\u3139 \ubfd0\ub9cc \uc544\ub2c8\ub77c\ub97c \uc0ac\uc6a9\ud574 \ubcf4\uc138\uc694."],t.s)
A.bqw=new B.dO("\uc9c1\uc7a5\uc744 \uc120\ud0dd\ud560 \ub54c \uc911\uc694\ud55c \uae30\uc900\uc5d0 \ub300\ud574 \uc368 \ubcf4\uc138\uc694.","\uc800\ub294 \uc9c1\uc7a5\uc744 \uc120\ud0dd\ud560 \ub54c \uae09\uc5ec\ub9cc \ubcf4\ub294 \uac83\uc740 \uc88b\uc9c0 \uc54a\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ubb3c\ub860 \uae09\uc5ec\ub3c4 \uc911\uc694\ud55c \uc870\uac74\uc774\uc9c0\ub9cc \uadfc\ubb34 \uc2dc\uac04, \ucd9c\ud1f4\uadfc \uac70\ub9ac, \uc5c5\ubb34 \ub0b4\uc6a9\uacfc \ubc1c\uc804 \uac00\ub2a5\uc131\ub3c4 \ud568\uaed8 \uace0\ub824\ud574\uc57c \ud569\ub2c8\ub2e4. \uc5b4\ub5a4 \ud68c\uc0ac\ub294 \ub2e4\ub978 \ud68c\uc0ac\uc5d0 \ube44\ud574\uc11c \uae09\uc5ec\uac00 \ub192\uc9c0\ub9cc \uc57c\uadfc\uc774 \ub9ce\uac70\ub098 \ucd9c\ud1f4\uadfc \uc2dc\uac04\uc774 \uae38 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubc18\ub300\ub85c \uae09\uc5ec\ub294 \uc870\uae08 \ub0ae\ub354\ub77c\ub3c4 \ubc30\uc6b0\uace0 \uc2f6\uc740 \uc77c\uc744 \ud560 \uc218 \uc788\uace0 \uc0dd\ud65c \uc2dc\uac04\uc744 \ud655\ubcf4\ud560 \uc218 \uc788\ub294 \ud68c\uc0ac\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uc800\ub294 \ud604\uc7ac \uae09\uc5ec\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc7a5\uae30\uc801\uc73c\ub85c \uc5b4\ub5a4 \uacbd\ud5d8\uc744 \uc313\uc744 \uc218 \uc788\ub294\uc9c0\ub97c \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud558\ub294 \ud3b8\uc785\ub2c8\ub2e4.")
A.khQ=s(["A\uc548\uacfc B\uc548\uc744 \uc18c\uac1c\ud558\uc138\uc694.","\uac01 \ubc29\ubc95\uc758 \uc7a5\uc810\uacfc \ub2e8\uc810\uc744 \uc4f0\uc138\uc694.","\uc790\uc2e0\uc758 \uc120\ud0dd \uae30\uc900\uc744 \uc4f0\uc138\uc694.","\uc5b4\ub290 \ubc29\ubc95\uc744 \uc120\ud0dd\ud560\uc9c0 \uc4f0\uc138\uc694.","V/A-(\uc73c)\u3134/\ub294 \ubc18\uba74\uc5d0\uc640 V-\ub294 \uac83\uc774 \ub0ab\ub2e4\ub97c \uc0ac\uc6a9\ud574 \ubcf4\uc138\uc694."],t.s)
A.bqO=new B.dO("\ub450 \uac00\uc9c0 \ubc29\ubc95\uc744 \ube44\uad50\ud558\uace0 \uc790\uc2e0\uc758 \uc758\uacac\uc744 \uc368 \ubcf4\uc138\uc694.","\ud68c\uc0ac\uc5d0\uc11c \uc0c8\ub85c\uc6b4 \uc7a5\ube44\ub97c \uad6c\uc785\ud55c\ub2e4\uace0 \uac00\uc815\ud558\uba74 \ub450 \uac00\uc9c0 \uc120\ud0dd\uc774 \uc788\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. A\uc81c\ud488\uc740 \uac00\uaca9\uc774 \uc800\ub834\ud55c \ubc18\uba74\uc5d0 \uae30\ub2a5\uc774 \uc801\uace0 \uc720\uc9c0 \uad00\ub9ac\uac00 \uc790\uc8fc \ud544\uc694\ud569\ub2c8\ub2e4. B\uc81c\ud488\uc740 \uac00\uaca9\uc774 \uc870\uae08 \ube44\uc2f8\uc9c0\ub9cc \uc791\uc5c5 \uc18d\ub3c4\uac00 \ube60\ub974\uace0 \uace0\uc7a5\uc774 \uc801\ub2e4\ub294 \uc7a5\uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4. \ucd08\uae30 \ube44\uc6a9\ub9cc \uc0dd\uac01\ud558\uba74 A\uc81c\ud488\uc774 \ub354 \uacbd\uc81c\uc801\uc73c\ub85c \ubcf4\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \uc7a5\uae30\uac04 \uc0ac\uc6a9\ud560 \uc7a5\ube44\ub77c\uba74 \uc720\uc9c0\ube44\uc640 \uc0dd\uc0b0\uc131\ub3c4 \uace0\ub824\ud574\uc57c \ud569\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc800\ub294 \ucd08\uae30 \ube44\uc6a9\uc774 \uc870\uae08 \ub354 \ub4e4\ub354\ub77c\ub3c4 B\uc81c\ud488\uc744 \uc120\ud0dd\ud558\ub294 \uac83\uc774 \ub0ab\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.")
A.hCX=s([A.bqw,A.bqO],t.vH)
