A.bhb=new B.cM("\ud68c\uc0ac\uc5d0\uc11c \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud588\uc744 \ub54c \ubcf4\uace0\ubd80\ud130 \uc7ac\ubc1c \ubc29\uc9c0\uae4c\uc9c0 \uc124\uba85\ud574 \ubcf4\uc138\uc694.",A.hGH,"\ud68c\uc0ac\uc5d0\uc11c \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud558\uba74 \uba3c\uc800 \ud604\uc7ac \uc0c1\ud669\uacfc \uc601\ud5a5 \ubc94\uc704\ub97c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \ucd94\uac00 \ubb38\uc81c\uac00 \uc0dd\uae38 \uc218 \uc788\ub2e4\uba74 \ud544\uc694\ud55c \uacbd\uc6b0 \uc791\uc5c5\uc744 \uc911\uc9c0\ud558\uace0 \ub2f4\ub2f9\uc790\ub098 \ud300\uc7a5\uc5d0\uac8c \ubc14\ub85c \ubcf4\uace0\ud569\ub2c8\ub2e4. \uadf8\ub2e4\uc74c \uc7a5\ube44, \uc791\uc5c5 \uc870\uac74\uacfc \uae30\ub85d\uc744 \ud655\uc778\ud574\uc11c \uc6d0\uc778\uc744 \ubd84\uc11d\ud569\ub2c8\ub2e4. \uc6d0\uc778\uc774 \ud655\uc778\ub418\uba74 \ud544\uc694\ud55c \uc870\uce58\ub97c \ud558\uace0 \uc2dc\ud5d8 \uc791\uc5c5\uc774\ub098 \uac80\uc0ac\ub97c \ud1b5\ud574 \uacb0\uacfc\ub97c \ub2e4\uc2dc \ud655\uc778\ud569\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9\uc73c\ub85c \uac19\uc740 \ubb38\uc81c\uac00 \uc7ac\ubc1c\ud558\uc9c0 \uc54a\ub3c4\ub85d \uccb4\ud06c\ub9ac\uc2a4\ud2b8\ub97c \ucd94\uac00\ud558\uac70\ub098 \uc791\uc5c5\uc790\ub97c \uad50\uc721\ud558\ub294 \ub4f1 \uc7ac\ubc1c \ubc29\uc9c0 \ub300\ucc45\uc744 \ub9c8\ub828\ud574\uc57c \ud569\ub2c8\ub2e4.")
A.i8P=s(["\uc7a5\uc810","\ub2e8\uc810","\uc120\ud0dd \uae30\uc900","\ube44\uad50","\uc7a5\uae30\uc801\uc778 \uc870\uac74","\uacb0\uc815"],t.s)
A.bhu=new B.cM("\ub450 \uac00\uc9c0 \uc120\ud0dd \uc911 \ud558\ub098\ub97c \uacb0\uc815\ud558\ub294 \ubc29\ubc95\uc744 \ub9d0\ud574 \ubcf4\uc138\uc694.",A.i8P,"\uc800\ub294 \uc911\uc694\ud55c \uc120\ud0dd\uc744 \ud560 \ub54c \ud55c \uac00\uc9c0 \uc870\uac74\ub9cc \ubcf4\uace0 \uacb0\uc815\ud558\uc9c0 \uc54a\ub294 \ud3b8\uc785\ub2c8\ub2e4. \uba3c\uc800 \ub450 \uc120\ud0dd\uc758 \uc7a5\uc810\uacfc \ub2e8\uc810\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4. \uc9c1\uc7a5\uc744 \uc120\ud0dd\ud55c\ub2e4\uba74 \uae09\uc5ec, \uadfc\ubb34 \uc2dc\uac04, \ucd9c\ud1f4\uadfc \uac70\ub9ac, \uc5c5\ubb34 \ub0b4\uc6a9\uacfc \ubc1c\uc804 \uac00\ub2a5\uc131\uc744 \ube44\uad50\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub2e4\uc74c \uc800\uc5d0\uac8c \uac00\uc7a5 \uc911\uc694\ud55c \uc120\ud0dd \uae30\uc900\uc774 \ubb34\uc5c7\uc778\uc9c0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ud544\uc694\ud558\uba74 \uacbd\ud5d8\uc774 \uc788\ub294 \uc0ac\ub78c\uc5d0\uac8c \uc870\uc5b8\ub3c4 \uad6c\ud569\ub2c8\ub2e4. \uc5ec\ub7ec \uc870\uac74\uc744 \ucda9\ubd84\ud788 \uace0\ub824\ud55c \ud6c4 \uc7a5\uae30\uc801\uc73c\ub85c \ub354 \uc801\ud569\ud55c \uc120\ud0dd\uc744 \ud558\ub824\uace0 \ud569\ub2c8\ub2e4.")
A.iLN=s(["\ucd9c\ucc98","\ub0a0\uc9dc","\uacf5\uc2dd \uc815\ubcf4","\uac80\uc99d","\ub2e4\ub978 \uc790\ub8cc","\uacf5\uc720"],t.s)
A.bhd=new B.cM("\uc778\ud130\ub137\uc5d0\uc11c \ubcf8 \uc911\uc694\ud55c \uc815\ubcf4\ub97c \uc5b4\ub5bb\uac8c \ud310\ub2e8\ud558\ub294\uc9c0 \ub9d0\ud574 \ubcf4\uc138\uc694.",A.iLN,"\uc778\ud130\ub137\uc5d0\uc11c \uc911\uc694\ud55c \uc815\ubcf4\ub97c \ubcf4\uba74 \ubc14\ub85c \ubbff\uae30\ubcf4\ub2e4\ub294 \uba3c\uc800 \ucd9c\ucc98\ub97c \ud655\uc778\ud569\ub2c8\ub2e4. \ub204\uac00 \uc791\uc131\ud588\ub294\uc9c0, \uc5b8\uc81c \uc791\uc131\ub41c \uc815\ubcf4\uc778\uc9c0\ub3c4 \ubd05\ub2c8\ub2e4. \ud2b9\ud788 \ube44\uc790, \ud589\uc815, \ucde8\uc5c5\uc774\ub098 \ud68c\uc0ac \uaddc\uc815\ucc98\ub7fc \uc911\uc694\ud55c \ub0b4\uc6a9\uc740 \uacf5\uc2dd \uae30\uad00\uc774\ub098 \ud68c\uc0ac \ud648\ud398\uc774\uc9c0\uc5d0 \uac19\uc740 \ub0b4\uc6a9\uc774 \uc788\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4. \ud55c \uacf3\uc758 \uc815\ubcf4\ub9cc \ubcf4\uae30\ubcf4\ub2e4 \ub2e4\ub978 \uc790\ub8cc\uc640\ub3c4 \ube44\uad50\ud569\ub2c8\ub2e4. \uc0ac\uc2e4\uc778\uc9c0 \ucda9\ubd84\ud788 \uac80\uc99d\ub418\uc9c0 \uc54a\uc740 \uc815\ubcf4\ub77c\uba74 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ubc14\ub85c \uacf5\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.")
A.hGa=s([A.bhc,A.bhb,A.bhu,A.bhd],t.Pe)
A.khI=s(["\ucc98\uc74c \uc5b4\ub824\uc6e0\ub358 \uc810\uc744 \uc4f0\uc138\uc694.","\uc5b4\ub5bb\uac8c \ub178\ub825\ud588\ub294\uc9c0 \uc4f0\uc138\uc694.","\ud604\uc7ac \ub2ec\ub77c\uc9c4 \uc810\uc744 \uc4f0\uc138\uc694.","\ubc30\uc6b4 \uc810\uc744 \uc4f0\uc138\uc694.","V-\ub2e4 \ubcf4\ub2c8\uc640 V-(\uc73c)\u3139\uae4c \ubd10\ub97c \uc0ac\uc6a9\ud574 \ubcf4\uc138\uc694."],t.s)
A.bqA=new B.dO("\ud55c\uad6d \uc0dd\ud65c\uc5d0\uc11c \uac00\uc7a5 \ub9ce\uc774 \ubc1c\uc804\ud55c \uc810\uc744 \uc368 \ubcf4\uc138\uc694.","\ud55c\uad6d \uc0dd\ud65c\uc744 \uc2dc\uc791\ud588\uc744 \ub54c \uc81c\uac00 \uac00\uc7a5 \uc5b4\ub824\uc6cc\ud588\ub358 \uac83\uc740 \uc758\uc0ac\uc18c\ud1b5\uc774\uc5c8\uc2b5\ub2c8\ub2e4. \ud68c\uc0ac\uc5d0\uc11c \uc5c5\ubb34 \uc9c0\uc2dc\ub97c \uc798\ubabb \uc774\ud574\ud560\uae4c \ubd10 \ud56d\uc0c1 \uae34\uc7a5\ud588\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \ubaa8\ub974\ub294 \ub2e8\uc5b4\ub098 \ud45c\ud604\uc774 \ub098\uc624\uba74 \ubc14\ub85c \ubb3c\uc5b4\ubcf4\uace0 \uc911\uc694\ud55c \ub0b4\uc6a9\uc740 \uba54\ubaa8\ud588\uc2b5\ub2c8\ub2e4. \ud1f4\uadfc \ud6c4\uc5d0\ub294 \uadf8\ub0a0 \ub4e4\uc5c8\ub358 \ud45c\ud604\uc744 \ub2e4\uc2dc \ucc3e\uc544\ubcf4\uace0 \uc608\ubb38\ub3c4 \ub9cc\ub4e4\uc5b4 \ubd24\uc2b5\ub2c8\ub2e4. \uc774\ub7f0 \uc5f0\uc2b5\uc744 \uacc4\uc18d\ud558\ub2e4 \ubcf4\ub2c8 \uc608\uc804\ubcf4\ub2e4 \uc9c1\uc7a5\uc5d0\uc11c \uc774\uc57c\uae30\ud558\ub294 \uac83\uc774 \ud6e8\uc52c \ud3b8\ud574\uc84c\uc2b5\ub2c8\ub2e4. \uc9c0\uae08\ub3c4 \ubaa8\ub974\ub294 \ud45c\ud604\uc740 \ub9ce\uc9c0\ub9cc \ubaa8\ub974\ub294 \uac83\uc744 \ubd80\ub044\ub7ec\uc6cc\ud558\uae30\ubcf4\ub2e4\ub294 \uc815\ud655\ud558\uac8c \ud655\uc778\ud558\ub294 \uc2b5\uad00\uc774 \uc0dd\uacbc\uc2b5\ub2c8\ub2e4.")
A.khp=s(["\ubb38\uc81c \uc0c1\ud669\uc744 \uc4f0\uc138\uc694.","\uc6d0\uc778\uc744 \uc4f0\uc138\uc694.","\uc870\uce58 \ubc29\ubc95\uc744 \uc4f0\uc138\uc694.","\uacb0\uacfc\ub97c \uc4f0\uc138\uc694.","\uc7ac\ubc1c \ubc29\uc9c0 \ub300\ucc45\uc744 \uc4f0\uc138\uc694.","V-(\uc73c)\u3134 \uacb0\uacfc\uc640 V-\uc9c0 \uc54a\ub3c4\ub85d\uc744 \uc0ac\uc6a9\ud574 \ubcf4\uc138\uc694."],t.s)
A.bqY=new B.dO("\ud68c\uc0ac\uc5d0\uc11c \ubc1c\uc0dd\ud55c \ubb38\uc81c\uc640 \ud574\uacb0 \uacfc\uc815\uc744 \uc885\ud569\uc801\uc73c\ub85c \uc368 \ubcf4\uc138\uc694.","\uc9c0\ub09c\uc8fc \uc0dd\uc0b0 \uc911 \uc81c\ud488 \ud45c\uba74\uc5d0 \uac19\uc740 \ud760\uc9d1\uc774 \ubc18\ubcf5\ud574\uc11c \ubc1c\uc0dd\ud588\uc2b5\ub2c8\ub2e4. \uc791\uc5c5\uc790\ub294 \ucd94\uac00 \ubd88\ub7c9\uc774 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub3c4\ub85d \uc0dd\uc0b0\uc744 \uc7a0\uc2dc \uc911\uc9c0\ud558\uace0 \ubd88\ub7c9\ud488\uc744 \uc815\uc0c1 \uc81c\ud488\uacfc \ubd84\ub9ac\ud588\uc2b5\ub2c8\ub2e4. \uadf8 \ud6c4 \uc7a5\ube44\uc640 \uc791\uc5c5 \uc870\uac74\uc744 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4. \uc7a5\ube44\ub97c \uc810\uac80\ud55c \uacb0\uacfc \uc81c\ud488\uc744 \uace0\uc815\ud558\ub294 \uac00\uc774\ub4dc \uc704\uce58\uac00 \uae30\uc900\ubcf4\ub2e4 \uc870\uae08 \ud2c0\uc5b4\uc838 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uc704\uce58\ub97c \uc815\uc0c1 \uae30\uc900\uc73c\ub85c \uc870\uc815\ud55c \ud6c4 \uc2dc\ud5d8 \uc0dd\uc0b0\uc744 \uc9c4\ud589\ud588\uace0 \uc5f4 \uac1c \uc81c\ud488\uc5d0\uc11c\ub294 \uac19\uc740 \ubd88\ub7c9\uc774 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. \uc774\ud6c4 \uc815\uc0c1 \uc0dd\uc0b0\uc744 \uc7ac\uac1c\ud588\uc2b5\ub2c8\ub2e4. \uac19\uc740 \ubb38\uc81c\uac00 \uc7ac\ubc1c\ud558\uc9c0 \uc54a\ub3c4\ub85d \uc791\uc5c5 \uc2dc\uc791 \uc804 \uac00\uc774\ub4dc \uc704\uce58\ub97c \ud655\uc778\ud558\ub294 \ud56d\ubaa9\uc744 \uccb4\ud06c\ub9ac\uc2a4\ud2b8\uc5d0 \ucd94\uac00\ud588\uace0 \uc791\uc5c5\uc790\ub4e4\uc5d0\uac8c \ubcc0\uacbd\ub41c \uc810\uac80 \uae30\uc900\ub3c4 \ub2e4\uc2dc \uad50\uc721\ud588\uc2b5\ub2c8\ub2e4.")
A.khW=s(["\uc9c1\uc7a5 \ud55c\uad6d\uc5b4\uc5d0 \ub300\ud574 \uc4f0\uc138\uc694.","\uc0dd\ud65c \ud55c\uad6d\uc5b4\uc5d0 \ub300\ud574 \uc4f0\uc138\uc694.","\ubb38\uc81c \ud574\uacb0\uc5d0 \ub300\ud574 \uc4f0\uc138\uc694.","\ubb38\ud654\uc640 \uc815\ubcf4 \ud655\uc778\uc5d0 \ub300\ud574 \uc4f0\uc138\uc694.","\uc55e\uc73c\ub85c\uc758 \ubaa9\ud45c\ub97c \uc4f0\uc138\uc694."],t.s)
A.bqT=new B.dO("HANLINK 3\uc5d0\uc11c \ubc30\uc6b4 \ub0b4\uc6a9\uc744 \uc55e\uc73c\ub85c \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud560\uc9c0 \uc368 \ubcf4\uc138\uc694.","HANLINK 3\uc5d0\uc11c \ubc30\uc6b4 \ub0b4\uc6a9\uc740 \uc2dc\ud5d8\uc744 \uc704\ud55c \ud55c\uad6d\uc5b4\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc2e4\uc81c \uc0dd\ud65c\uacfc \uc9c1\uc7a5\uc5d0\uc11c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \ud45c\ud604\uc774 \ub9ce\uc2b5\ub2c8\ub2e4. \uc55e\uc73c\ub85c \ud68c\uc0ac\uc5d0\uc11c\ub294 \uc9c0\uc2dc \ub0b4\uc6a9\uc744 \uc815\ud655\ud788 \ud655\uc778\ud558\uace0 \ubb38\uc81c\uac00 \uc0dd\uae30\uba74 \uc0c1\ud669, \uc6d0\uc778\uacfc \uc870\uce58 \ub0b4\uc6a9\uc744 \uc21c\uc11c\ub300\ub85c \ubcf4\uace0\ud558\ub294 \uc5f0\uc2b5\uc744 \ud558\ub824\uace0 \ud569\ub2c8\ub2e4. \ubcd1\uc6d0, \uc9d1 \uacc4\uc57d, \uc77c\uc815 \ubcc0\uacbd\uacfc \uac19\uc740 \uc0dd\ud65c \uc0c1\ud669\uc5d0\uc11c\ub3c4 \ud544\uc694\ud55c \ud45c\ud604\uc744 \uc9c1\uc811 \uc0ac\uc6a9\ud574 \ubcf4\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \ub610\ud55c \ub2e4\ub978 \uc0ac\ub78c\uacfc \uc758\uacac\uc774 \ub2e4\ub974\ub354\ub77c\ub3c4 \uc874\uc911\ud558\uba74\uc11c \uc774\uc57c\uae30\ud558\uace0 \ubb38\ud654 \ucc28\uc774\ub85c \uc624\ud574\uac00 \uc0dd\uae30\uba74 \ubc14\ub85c \ud310\ub2e8\ud558\uae30\ubcf4\ub2e4\ub294 \uba3c\uc800 \ud655\uc778\ud558\ub824\uace0 \ud569\ub2c8\ub2e4. \uc778\ud130\ub137\uc5d0\uc11c \uc911\uc694\ud55c \uc815\ubcf4\ub97c \ubcfc \ub54c\ub3c4 \ucd9c\ucc98\uc640 \uacf5\uc2dd \uc790\ub8cc\ub97c \ud655\uc778\ud558\ub294 \uc2b5\uad00\uc744 \uacc4\uc18d \uc720\uc9c0\ud558\uaca0\uc2b5\ub2c8\ub2e4.")
A.h39=s([A.bqA,A.bqY,A.bqT],t.vH)
