A.bh4=new B.cM("\uc2e0\uc785 \uc9c1\uc6d0\uc5d0\uac8c \uc791\uc5c5\uc7a5 \uc548\uc804 \uaddc\uce59\uc744 \uc124\uba85\ud574 \ubcf4\uc138\uc694.",A.fKo,"\uc791\uc5c5\uc744 \uc2dc\uc791\ud558\uae30 \uc804\uc5d0 \uba87 \uac00\uc9c0 \uc548\uc804 \uaddc\uce59\uc744 \uaf2d \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \uba3c\uc800 \ud604\uc7a5\uc5d0\uc11c\ub294 \uc548\uc804\ubaa8\uc640 \ubcf4\uc548\uacbd \ub4f1 \ud544\uc694\ud55c \ubcf4\ud638\uad6c\ub97c \ubc18\ub4dc\uc2dc \ucc29\uc6a9\ud574\uc57c \ud569\ub2c8\ub2e4. \uc791\uc5c5 \uc2dc\uc791 \uc804\uc5d0\ub294 \uc7a5\ube44 \uc0c1\ud0dc\ub97c \uc810\uac80\ud558\ub3c4\ub85d \ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4. \uae30\uacc4\uac00 \uc791\ub3d9 \uc911\uc77c \ub54c \uc704\ud5d8 \uad6c\uc5ed\uc5d0 \uc190\uc744 \ub123\uac70\ub098 \ud5c8\uac00 \uc5c6\uc774 \uc124\uc815\uc744 \ubcc0\uacbd\ud558\uba74 \uc548 \ub429\ub2c8\ub2e4. \uc7a5\ube44\uc5d0 \uc774\uc0c1\uc774 \uc788\uac70\ub098 \uc704\ud5d8\ud55c \uc0c1\ud669\uc774 \ubc1c\uc0dd\ud558\uba74 \uc989\uc2dc \uc791\uc5c5\uc744 \uc911\uc9c0\ud558\uace0 \ub2f4\ub2f9\uc790\uc5d0\uac8c \ubcf4\uace0\ud574\uc57c \ud569\ub2c8\ub2e4.")
A.ilo=s(["\uc2e4\uc218","\uc6d0\uc778","\uc601\ud5a5","\ucc45\uc784","\uc870\uce58","\uc7ac\ubc1c \ubc29\uc9c0"],t.s)
A.bhs=new B.cM("\uc790\uc2e0\uc758 \uc2e4\uc218\ub85c \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud588\uc744 \ub54c \ud300\uc7a5\uc5d0\uac8c \ubcf4\uace0\ud574 \ubcf4\uc138\uc694.",A.ilo,"\ud300\uc7a5\ub2d8, \uc624\ub298 \uac80\uc0ac \uae30\ub85d\uc774 \ud558\ub098 \ub204\ub77d\ub41c \ubd80\ubd84\uc5d0 \ub300\ud574 \ubcf4\uace0\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9 \uc81c\ud488\uc744 \uac80\uc0ac\ud55c \ud6c4 \uc81c\uac00 \uae30\ub85d \ub0b4\uc6a9\uc744 \ub2e4\uc2dc \ud655\uc778\ud558\uc9c0 \ubabb\ud574\uc11c \ud55c \ud56d\ubaa9\uc774 \ube60\uc84c\uc2b5\ub2c8\ub2e4. \uc774 \ubd80\ubd84\uc740 \uc81c\uac00 \ud655\uc778\ud558\uc9c0 \ubabb\ud55c \uac83\uc774\uae30 \ub54c\ubb38\uc5d0 \uc81c \ucc45\uc784\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ud604\uc7ac \ud574\ub2f9 \uc81c\ud488\uc758 \uac80\uc0ac \uacb0\uacfc\ub97c \ub2e4\uc2dc \ud655\uc778\ud558\uace0 \uae30\ub85d\uc744 \ubcf4\uc644\ud588\uc2b5\ub2c8\ub2e4. \uc55e\uc73c\ub85c \uac19\uc740 \uc2e4\uc218\uac00 \ubc18\ubcf5\ub418\uc9c0 \uc54a\ub3c4\ub85d \uc791\uc5c5 \uc885\ub8cc \uc804\uc5d0 \uccb4\ud06c\ub9ac\uc2a4\ud2b8\ub97c \ub05d\uae4c\uc9c0 \ud655\uc778\ud558\ub3c4\ub85d \ud558\uaca0\uc2b5\ub2c8\ub2e4.")
A.iJ1=s(["\uc0c8 \uaddc\uc815","\uc801\uc6a9","\ud5c8\uac00","\uc791\uc5c5 \ubc29\ubc95","\ud655\uc778"],t.s)
A.bhI=new B.cM("\ud68c\uc0ac \uaddc\uc815\uc744 \uc774\ud574\ud558\uc9c0 \ubabb\ud588\uc744 \ub54c \ub2f4\ub2f9\uc790\uc5d0\uac8c \uc9c8\ubb38\ud574 \ubcf4\uc138\uc694.",A.iJ1,"\uc8c4\uc1a1\ud558\uc9c0\ub9cc \uc0c8\ub85c \ubcc0\uacbd\ub41c \uaddc\uc815\uc5d0 \ub300\ud574 \uba87 \uac00\uc9c0 \ud655\uc778\ud558\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \uc774 \uaddc\uc815\uc774 \uc624\ub298\ubd80\ud130 \ubc14\ub85c \uc801\uc6a9\ub418\ub294 \uac74\uac00\uc694? \uadf8\ub9ac\uace0 \uc774 \uc791\uc5c5\uc744 \ud560 \ub54c\ub294 \uc774\uc804\uacfc \ub2ec\ub9ac \ub2f4\ub2f9\uc790\uc758 \ud5c8\uac00\ub97c \uba3c\uc800 \ubc1b\uc544\uc57c \ud558\ub294\uc9c0 \uad81\uae08\ud569\ub2c8\ub2e4. \uc81c\uac00 \uc798\ubabb \uc774\ud574\ud558\uace0 \uc791\uc5c5\ud558\uc9c0 \uc54a\ub3c4\ub85d \ubcc0\uacbd\ub41c \ubd80\ubd84\uc744 \ub2e4\uc2dc \ud55c\ubc88 \uc124\uba85\ud574 \uc8fc\uc2e4 \uc218 \uc788\uc744\uae4c\uc694?")
A.fys=s([A.bh4,A.bhs,A.bhI],t.Pe)
A.khw=s(["\ubcf4\ud638\uad6c \ucc29\uc6a9\uc5d0 \ub300\ud574 \uc4f0\uc138\uc694.","\uc791\uc5c5 \uc804 \uc810\uac80\uc5d0 \ub300\ud574 \uc4f0\uc138\uc694.","\uae08\uc9c0\ub418\ub294 \ud589\ub3d9\uc744 \uc4f0\uc138\uc694.","\ubb38\uc81c\uac00 \uc0dd\uacbc\uc744 \ub54c \ubcf4\uace0 \ubc29\ubc95\uc744 \uc4f0\uc138\uc694.","V-\uc544/\uc5b4\uc57c \ud558\ub2e4\uc640 V-(\uc73c)\uba74 \uc548 \ub418\ub2e4\ub97c \uc0ac\uc6a9\ud574 \ubcf4\uc138\uc694."],t.s)
A.bqt=new B.dO("\uc9c1\uc7a5\uc5d0\uc11c \uc9c0\ucf1c\uc57c \ud560 \uc548\uc804 \uaddc\uce59\uc5d0 \ub300\ud574 \uc368 \ubcf4\uc138\uc694.","\ud604\uc7a5\uc5d0\uc11c \uc548\uc804\ud558\uac8c \uc77c\ud558\ub824\uba74 \uae30\ubcf8\uc801\uc778 \uc548\uc804 \uaddc\uce59\uc744 \ubc18\ub4dc\uc2dc \uc9c0\ucf1c\uc57c \ud569\ub2c8\ub2e4. \uc791\uc5c5\uc744 \uc2dc\uc791\ud558\uae30 \uc804\uc5d0 \uc548\uc804\ubaa8, \ubcf4\uc548\uacbd\uacfc \uac19\uc740 \ud544\uc694\ud55c \ubcf4\ud638\uad6c\ub97c \ucc29\uc6a9\ud574\uc57c \ud569\ub2c8\ub2e4. \ub610\ud55c \uae30\uacc4\uc640 \uc8fc\ubcc0 \uc791\uc5c5 \ud658\uacbd\uc5d0 \uc774\uc0c1\uc774 \uc5c6\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \uae30\uacc4\uac00 \uc791\ub3d9\ud558\uace0 \uc788\uc744 \ub54c \uc704\ud5d8 \uad6c\uc5ed\uc5d0 \uc190\uc744 \ub123\uac70\ub098 \uc548\uc804 \uc7a5\uce58\ub97c \uc784\uc758\ub85c \ud574\uc81c\ud558\uba74 \uc548 \ub429\ub2c8\ub2e4. \uc791\uc5c5 \uc911 \uc774\uc0c1\uc774 \ubc1c\uc0dd\ud558\uba74 \ud63c\uc790 \ud574\uacb0\ud558\ub824\uace0 \ud558\uc9c0 \ub9d0\uace0 \uc791\uc5c5\uc744 \uc911\uc9c0\ud55c \ud6c4 \ub2f4\ub2f9\uc790\uc5d0\uac8c \uc989\uc2dc \ubcf4\uace0\ud574\uc57c \ud569\ub2c8\ub2e4. \uc791\uc740 \uaddc\uce59\uc774\ub77c\ub3c4 \uacc4\uc18d \uc900\uc218\ud558\ub294 \uac83\uc774 \ud070 \uc0ac\uace0\ub97c \uc608\ubc29\ud558\ub294 \ub370 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.khJ=s(["\ub2f4\ub2f9 \uc5c5\ubb34\uc5d0 \ub300\ud574 \uc4f0\uc138\uc694.","\uaddc\uc815 \uc900\uc218\uc5d0 \ub300\ud574 \uc4f0\uc138\uc694.","\uc2e4\uc218\ud588\uc744 \ub54c \ud0dc\ub3c4\ub97c \uc4f0\uc138\uc694.","\ubcf4\uace0\uc640 \ud611\uc5c5\uc5d0 \ub300\ud574 \uc4f0\uc138\uc694.","N\uc5d0 \ub530\ub77c\uc640 V-\ub294 \ud55c\uc744 \uc0ac\uc6a9\ud574 \ubcf4\uc138\uc694."],t.s)
A.bqI=new B.dO("\ucc45\uc784\uac10 \uc788\ub294 \uc9c1\uc7a5\uc778\uc774\ub780 \uc5b4\ub5a4 \uc0ac\ub78c\uc778\uc9c0 \uc368 \ubcf4\uc138\uc694.","\ucc45\uc784\uac10 \uc788\ub294 \uc9c1\uc7a5\uc778\uc740 \uc790\uc2e0\uc774 \ub9e1\uc740 \uc77c\uc744 \ub2e8\uc21c\ud788 \ub05d\ub0b4\ub294 \uc0ac\ub78c\ub9cc\uc744 \uc758\ubbf8\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ud68c\uc0ac \uaddc\uc815\uacfc \uc791\uc5c5 \uae30\uc900\uc5d0 \ub530\ub77c \uc815\ud655\ud558\uac8c \uc5c5\ubb34\ub97c \ucc98\ub9ac\ud558\uace0 \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud558\uba74 \ud544\uc694\ud55c \ub0b4\uc6a9\uc744 \uc989\uc2dc \ubcf4\uace0\ud560 \uc218 \uc788\uc5b4\uc57c \ud569\ub2c8\ub2e4. \uc790\uc2e0\uc758 \uc2e4\uc218\ub85c \ubb38\uc81c\uac00 \uc0dd\uacbc\uc744 \ub54c \ucc45\uc784\uc744 \ud68c\ud53c\ud558\uc9c0 \uc54a\uace0 \uc798\ubabb\uc744 \uc778\uc815\ud55c \ud6c4 \ud574\uacb0 \ubc29\ubc95\uc744 \ucc3e\ub294 \ud0dc\ub3c4\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4. \ub610\ud55c \ud63c\uc790 \ucc98\ub9ac\ud560 \uc218 \uc5c6\ub294 \ubb38\uc81c\ub294 \ub3d9\ub8cc\ub098 \ub2f4\ub2f9\uc790\uc640 \ud611\ub825\ud574\uc57c \ud569\ub2c8\ub2e4. \uc790\uc2e0\uc774 \uc5b4\ub5a4 \uc5c5\ubb34\ub97c \ub2f4\ub2f9\ud558\ub294 \ud55c \uadf8 \uc5c5\ubb34\uc758 \uc9c4\ud589 \uc0c1\ud0dc\uc640 \uacb0\uacfc\ub97c \ub05d\uae4c\uc9c0 \ud655\uc778\ud558\ub824\ub294 \uc790\uc138\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.")
A.hI8=s([A.bqt,A.bqI],t.vH)
