A.iMS=s(["\ub3cc\uc774\ucf1c\ubcf4\ub2e4","\uc785\uae08\ud558\ub2e4","\uacac\uc778\ud558\ub2e4","\uc608\uc57d\ud558\ub2e4"],t.s)
A.bce=new B.a6("\uacfc\uac70\uc758 \uc77c\uc744 \ub2e4\uc2dc \uc0dd\uac01\ud574 \ubcf4\ub294 \uac83\uc744 \uac00\uc7a5 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ud45c\ud604\ud55c \uac83\uc740?",A.iMS,0,"\uc5b4\ud718")
A.i9s=s(["\uc0c1\ud669 \u2192 \ub0b4\uac00 \ud55c \ud589\ub3d9 \u2192 \uacb0\uacfc \u2192 \ubc30\uc6b4 \uc810","\ubc30\uc6b4 \uc810 \u2192 \uc544\ubb34 \uc774\uc720 \uc5c6\ub294 \uacb0\ub860","\uacb0\uacfc\ub9cc \ub9d0\ud55c\ub2e4.","\ub2e4\ub978 \uc0ac\ub78c \uc774\uc57c\uae30\ub9cc \ud55c\ub2e4."],t.s)
A.bfu=new B.a6("\uba74\uc811\uc5d0\uc11c \uc790\uc2e0\uc758 \uacbd\ud5d8\uc744 \uc124\uba85\ud558\ub294 \uc21c\uc11c\ub85c \uac00\uc7a5 \uc88b\uc740 \uac83\uc740?",A.i9s,0,"\uc2e4\uc81c \uc0c1\ud669")
A.ixr=s(["\uac19\uc740 \uc2e4\uc218\ub97c \uacc4\uc18d \ubc18\ubcf5\ud55c\ub2e4.","\uacfc\uac70\ub9cc \uc0dd\uac01\ud558\uace0 \uc544\ubb34\uac83\ub3c4 \ud558\uc9c0 \uc54a\ub294\ub2e4.","\uacbd\ud5d8\uc5d0\uc11c \ubc30\uc6b4 \uc810\uc744 \ucc3e\uc544 \ub2e4\uc74c \ud589\ub3d9\uc744 \ubc14\uafbc\ub2e4.","\uc2e4\uc218\ub97c \ubaa8\ub450 \ub2e4\ub978 \uc0ac\ub78c \ud0d3\uc73c\ub85c \ub3cc\ub9b0\ub2e4."],t.s)
A.bdv=new B.a6("\ud6c4\ud68c\uc5d0 \ub300\ud55c \ud0dc\ub3c4\ub85c \uac00\uc7a5 \ubc14\ub78c\uc9c1\ud55c \uac83\uc740?",A.ixr,2,"\uc885\ud569")
A.fPC=s([A.bdd,A.bcf,A.beJ,A.bcD,A.bfN,A.bfs,A.bbP,A.bbZ,A.bca,A.bbV,A.bfa,A.bbD,A.bce,A.bfu,A.bdv],t.Nf)
A.hks=s(["\uc5b8\uc81c","\uc5b4\ub514\uc5d0\uc11c","\ubb34\uc5c7\uc744 \ud588\ub294\uc9c0","\uc5b4\ub824\uc6c0","\ub290\ub080 \uc810","\ubc30\uc6b4 \uc810"],t.s)
A.bgW=new B.cM("\ud55c\uad6d\uc5d0\uc11c \uac00\uc7a5 \uae30\uc5b5\uc5d0 \ub0a8\ub294 \uacbd\ud5d8\uc744 \ub9d0\ud574 \ubcf4\uc138\uc694.",A.hks,"\uc81c\uac00 \ud55c\uad6d\uc5d0\uc11c \uac00\uc7a5 \uae30\uc5b5\uc5d0 \ub0a8\ub294 \uacbd\ud5d8\uc740 \ucc98\uc74c \ud68c\uc0ac\uc5d0 \ucde8\uc5c5\ud588\uc744 \ub54c\uc785\ub2c8\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ud55c\uad6d\uc5b4\ub3c4 \ubd80\uc871\ud588\uace0 \uc5c5\ubb34 \ubc29\uc2dd\ub3c4 \uc775\uc219\ud558\uc9c0 \uc54a\uc544\uc11c \uc2e4\uc218\ub97c \ub9ce\uc774 \ud588\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \ub3d9\ub8cc\ub4e4\uc5d0\uac8c \uacc4\uc18d \ubb3c\uc5b4\ubcf4\uace0 \uba54\ubaa8\ud558\uba74\uc11c \uc77c\uc744 \ubc30\uc6b0\ub2e4 \ubcf4\ub2c8 \uc810\uc810 \uc801\uc751\ud560 \uc218 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uadf8 \uacbd\ud5d8\uc744 \ud1b5\ud574 \ubaa8\ub974\ub294 \uac83\uc740 \ubc14\ub85c \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4\ub294 \uac83\uc744 \ubc30\uc6e0\uc2b5\ub2c8\ub2e4.")
A.hs7=s(["\ud6c4\ud68c","\uc120\ud0dd","\uae30\ud68c","-\u3139\uac78 \uadf8\ub7ac\ub2e4","\ubc30\uc6b4 \uc810"],t.s)
A.bgT=new B.cM("\uacfc\uac70\uc5d0 \ud6c4\ud68c\ud588\ub358 \uc77c\uc744 \ud558\ub098 \ub9d0\ud574 \ubcf4\uc138\uc694.",A.hs7,"\uc800\ub294 \ud55c\uad6d\uc5d0 \ucc98\uc74c \uc654\uc744 \ub54c \ud55c\uad6d\uc5b4 \uacf5\ubd80\ub97c \ub354 \uc5f4\uc2ec\ud788 \ud558\uc9c0 \uc54a\uc740 \uac83\uc744 \ud6c4\ud68c\ud569\ub2c8\ub2e4. \uc0dd\ud65c\uc774 \ubc14\uc058\ub2e4\ub294 \uc774\uc720\ub85c \uacf5\ubd80\ub97c \uc790\uc8fc \ubbf8\ub918\uc2b5\ub2c8\ub2e4. \ub098\uc911\uc5d0 \ud68c\uc0ac \uc0dd\ud65c\uc744 \ud558\uba74\uc11c \ud55c\uad6d\uc5b4\uac00 \uc5bc\ub9c8\ub098 \uc911\uc694\ud55c\uc9c0 \uae68\ub2ec\uc558\uc2b5\ub2c8\ub2e4. \uadf8\ub54c\ubd80\ud130 \ub9e4\uc77c \uc870\uae08\uc529\uc774\ub77c\ub3c4 \uacf5\ubd80\ud560\uac78 \uadf8\ub7ac\ub2e4\ub294 \uc0dd\uac01\uc774 \ub4e4\uc5c8\uc2b5\ub2c8\ub2e4. \uc9c0\uae08\uc740 \uac19\uc740 \ud6c4\ud68c\ub97c \ud558\uc9c0 \uc54a\uc73c\ub824\uace0 \uafb8\uc900\ud788 \uacf5\ubd80\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.")
A.hVg=s(["\uc2e4\ud328","\uc6d0\uc778","\uc900\ube44","\uad50\ud6c8","\ub2e4\uc2dc \ub3c4\uc804"],t.s)
A.bhB=new B.cM("\uc2e4\ud328\ud55c \uacbd\ud5d8\uc744 \ud1b5\ud574 \ubb34\uc5c7\uc744 \ubc30\uc6e0\uc2b5\ub2c8\uae4c?",A.hVg,"\uc608\uc804\uc5d0 \uc2dc\ud5d8\uc744 \uc81c\ub300\ub85c \uc900\ube44\ud558\uc9c0 \ubabb\ud574\uc11c \uc6d0\ud558\ub294 \uacb0\uacfc\ub97c \uc5bb\uc9c0 \ubabb\ud55c \uc801\uc774 \uc788\uc2b5\ub2c8\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uacb0\uacfc\uac00 \uc544\uc26c\uc6e0\uc9c0\ub9cc \uc65c \uc2e4\ud328\ud588\ub294\uc9c0 \uc0dd\uac01\ud574 \ubd24\uc2b5\ub2c8\ub2e4. \uacc4\ud68d \uc5c6\uc774 \uacf5\ubd80\ud588\uace0 \ubd80\uc871\ud55c \ubd80\ubd84\uc744 \uc81c\ub300\ub85c \ud655\uc778\ud558\uc9c0 \uc54a\uc558\ub358 \uac83\uc774 \ubb38\uc81c\uc600\uc2b5\ub2c8\ub2e4. \uadf8 \uacbd\ud5d8\uc744 \ud1b5\ud574 \uacc4\ud68d\uc744 \uc138\uc6b0\uace0 \uc57d\uc810\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4\ub294 \uad50\ud6c8\uc744 \uc5bb\uc5c8\uc2b5\ub2c8\ub2e4. \uc774\ud6c4\uc5d0\ub294 \uacf5\ubd80 \ubc29\ubc95\uc744 \ubc14\uafb8\uace0 \ub2e4\uc2dc \ub3c4\uc804\ud588\uc2b5\ub2c8\ub2e4.")
A.fWg=s([A.bgW,A.bgT,A.bhB],t.Pe)
A.khC=s(["\uc5b8\uc81c \uc788\uc5c8\ub358 \uc77c\uc778\uc9c0 \uc4f0\uc138\uc694.","\ubb34\uc2a8 \uc77c\uc774 \uc788\uc5c8\ub294\uc9c0 \uc4f0\uc138\uc694.","\uc65c \ud6c4\ud68c\ud558\ub294\uc9c0 \uc4f0\uc138\uc694.","\uadf8 \uacbd\ud5d8\uc5d0\uc11c \ubb34\uc5c7\uc744 \ubc30\uc6e0\ub294\uc9c0 \uc4f0\uc138\uc694.","V-(\uc73c)\u3139\uac78 \uadf8\ub7ac\ub2e4\uc640 V-\ub2e4 \ubcf4\ub2c8\ub97c \uc0ac\uc6a9\ud574 \ubcf4\uc138\uc694."],t.s)
A.bqW=new B.dO("\ud6c4\ud68c\ub418\ub294 \uacbd\ud5d8\uacfc \ubc30\uc6b4 \uc810\uc744 \uc368 \ubcf4\uc138\uc694.","\uba87 \ub144 \uc804\uc5d0 \uc911\uc694\ud55c \uba74\uc811 \uae30\ud68c\uac00 \uc788\uc5c8\ub294\ub370 \uc900\ube44\uac00 \ubd80\uc871\ud55c \uc0c1\ud0dc\ub85c \uba74\uc811\uc744 \ubcf8 \uc801\uc774 \uc788\uc2b5\ub2c8\ub2e4. \ud68c\uc0ac\uc5d0 \ub300\ud574 \ucda9\ubd84\ud788 \uc54c\uc544\ubcf4\uc9c0 \uc54a\uc558\uace0 \uc608\uc0c1 \uc9c8\ubb38\ub3c4 \uc900\ube44\ud558\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. \uba74\uc811\uc5d0\uc11c \uc9c8\ubb38\uc744 \uc81c\ub300\ub85c \uc774\ud574\ud558\uc9c0 \ubabb\ud574 \ub300\ub2f5\uc744 \uc798\ud558\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4. \uba74\uc811\uc774 \ub05d\ub09c \ud6c4 \uc870\uae08 \ub354 \uc900\ube44\ud560\uac78 \uadf8\ub7ac\ub2e4\ub294 \uc0dd\uac01\uc774 \ub9ce\uc774 \ub4e4\uc5c8\uc2b5\ub2c8\ub2e4. \uadf8 \ud6c4 \uc5ec\ub7ec \ubc88 \uba74\uc811\uc744 \uc900\ube44\ud558\ub2e4 \ubcf4\ub2c8 \uc0ac\uc804\uc5d0 \ud68c\uc0ac \uc815\ubcf4\uc640 \uc9c1\ubb34 \ub0b4\uc6a9\uc744 \uc815\ub9ac\ud558\ub294 \uac83\uc774 \ub9e4\uc6b0 \uc911\uc694\ud558\ub2e4\ub294 \uac83\uc744 \uc54c\uac8c \ub410\uc2b5\ub2c8\ub2e4. \uc9c0\uae08\uc740 \uc911\uc694\ud55c \uba74\uc811\uc774 \uc788\uc73c\uba74 \uc608\uc0c1 \uc9c8\ubb38\uacfc \ub2f5\ubcc0\uc744 \ubbf8\ub9ac \uc900\ube44\ud569\ub2c8\ub2e4.")
A.khM=s(["\uacfc\uac70 \uacbd\ud5d8\uc744 \uc18c\uac1c\ud558\uc138\uc694.","\ucc98\uc74c\uc5d0 \uc5b4\ub824\uc6e0\ub358 \uc810\uc744 \uc4f0\uc138\uc694.","\uc5b4\ub5bb\uac8c \uadf9\ubcf5\ud588\ub294\uc9c0 \uc4f0\uc138\uc694.","\ud604\uc7ac \uc5b4\ub5a4 \ub3c4\uc6c0\uc774 \ub418\ub294\uc9c0 \uc4f0\uc138\uc694.","V-(\uc73c)\u3134 \uc801\uc774 \uc788\ub2e4\uc640 V-\uc544/\uc5b4 \ubcf4\ub2e4\ub97c \uc0ac\uc6a9\ud574 \ubcf4\uc138\uc694."],t.s)
A.bqM=new B.dO("\uc790\uc2e0\uc758 \uacbd\ud5d8\uc774 \ud604\uc7ac \uc0dd\ud65c\uc5d0 \uc5b4\ub5a4 \ub3c4\uc6c0\uc774 \ub418\uc5c8\ub294\uc9c0 \uc368 \ubcf4\uc138\uc694.","\uc800\ub294 \uc774\uc804 \uc9c1\uc7a5\uc5d0\uc11c \uc0c8\ub85c\uc6b4 \uae30\uacc4\ub97c \ucc98\uc74c \ubc30\uc6b4 \uc801\uc774 \uc788\uc2b5\ub2c8\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc870\uc791 \ubc29\ubc95\uc774 \uc775\uc219\ud558\uc9c0 \uc54a\uc544\uc11c \uc2e4\uc218\ud560\uae4c \ubd10 \ub9ce\uc774 \uae34\uc7a5\ud588\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc120\ubc30\uc5d0\uac8c \ubaa8\ub974\ub294 \ubd80\ubd84\uc744 \ubb3c\uc5b4\ubcf4\uace0 \uc791\uc5c5 \uc21c\uc11c\ub97c \uba54\ubaa8\ud588\uc2b5\ub2c8\ub2e4. \uc26c\uc6b4 \uc791\uc5c5\ubd80\ud130 \uc9c1\uc811 \ud574 \ubcf4\uba74\uc11c \uc870\uae08\uc529 \uc775\uc219\ud574\uc84c\uc2b5\ub2c8\ub2e4. \uadf8 \uacbd\ud5d8 \ub355\ubd84\uc5d0 \uc9c0\uae08\uc740 \uc0c8\ub85c\uc6b4 \uc5c5\ubb34\ub97c \ubc30\uc6b8 \ub54c \ubb34\uc870\uac74 \ub450\ub824\uc6cc\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \uc124\uba85\uc744 \ub4e3\uace0 \uc9c1\uc811 \ud574 \ubcf4\uba74\uc11c \ubd80\uc871\ud55c \ubd80\ubd84\uc744 \ud655\uc778\ud558\ub294 \uc2b5\uad00\uc774 \uc0dd\uacbc\uc2b5\ub2c8\ub2e4.")
A.fTZ=s([A.bqW,A.bqM],t.vH)
A.iie=s(["\uacbd\ud5d8","\uacbd\ud5d8\ud558\ub2e4","\uacbd\ud5d8\uc744 \uc313\ub2e4","\uae30\uc5b5","\uae30\uc5b5\uc5d0 \ub0a8\ub2e4","\uc2e4\uc218","\uc2e4\uc218\ud558\ub2e4","\uc798\ubabb\ud558\ub2e4","\ud6c4\ud68c\ud558\ub2e4","\uc544\uc27d\ub2e4","\uc548\ud0c0\uae5d\ub2e4","\ub193\uce58\ub2e4","\uae30\ud68c","\uae30\ud68c\ub97c \uc7a1\ub2e4","\uc120\ud0dd","\uacb0\uc815","\ub3c4\uc804\ud558\ub2e4","\uc2e4\ud328\ud558\ub2e4","\uc131\uacf5\ud558\ub2e4","\ud3ec\uae30\ud558\ub2e4","\ubc30\uc6b0\ub2e4","\uad50\ud6c8","\uad50\ud6c8\uc744 \uc5bb\ub2e4","\uae68\ub2eb\ub2e4","\ub3cc\uc774\ucf1c\ubcf4\ub2e4","\uc131\uae09\ud558\ub2e4","\ubbf8\ub9ac","\ub2e4\uc2dc \ub3c4\uc804\ud558\ub2e4"],t.s)
