A.hrs=s(["\ud68c\uc2dd \uc2eb\uc5b4\uc11c \uc548 \uac11\ub2c8\ub2e4.","\uac1c\uc778 \uc77c\uc815\uc774 \uc788\uc5b4\uc11c \uc774\ubc88 \ud68c\uc2dd\uc5d0\ub294 \ucc38\uc11d\ud558\uae30 \uc5b4\ub824\uc6b8 \uac83 \uac19\uc2b5\ub2c8\ub2e4.","\ub098\ub294 \uc548 \uac00\uc694. \uc774\uc720 \uc5c6\uc5b4\uc694.","\uc544\ubb34 \uc5f0\ub77d \uc5c6\uc774 \uac00\uc9c0 \uc54a\ub294\ub2e4."],t.s)
A.bcv=new B.a6("\uac1c\uc778 \uc0ac\uc815\uc73c\ub85c \ud68c\uc2dd \ucc38\uc11d\uc774 \uc5b4\ub835\uc2b5\ub2c8\ub2e4. \uac00\uc7a5 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \ud45c\ud604\uc740?",A.hrs,1,"\ud68c\uc2dd")
A.fS0=s(["\ubaa8\ub974\ub294 \uaddc\uce59\uc774\ub098 \ud638\uce6d\uc740 \ubb3c\uc5b4\ubcf8\ub2e4.","\ub2e4\ub978 \uc0ac\ub78c\uc758 \ud589\ub3d9\uc744 \ubc14\ub85c \ub098\uc058\ub2e4\uace0 \ud310\ub2e8\ud55c\ub2e4.","\uc0c1\ud669\uc5d0 \ub9de\ub294 \ub9d0\ud22c\ub97c \ubc30\uc6b0\ub824\uace0 \ud55c\ub2e4.","\ubb38\ud654 \ucc28\uc774\ub85c \uc624\ud574\uac00 \uc0dd\uae30\uba74 \ub300\ud654\ub85c \ud655\uc778\ud55c\ub2e4."],t.s)
A.bd0=new B.a6("\ud55c\uad6d \uc9c1\uc7a5 \ubb38\ud654\uc5d0 \uc801\uc751\ud558\ub294 \ubc29\ubc95\uc73c\ub85c \uc54c\ub9de\uc9c0 \uc54a\uc740 \uac83\uc740?",A.fS0,1,"\uc885\ud569")
