A.iec=s(["N\uc5d0 \ub530\ub974\uba74","V/A-\ub2e4\ub294 \uc810\uc5d0\uc11c","V/A-\ub2e4\uace0 \ubcfc \uc218 \uc788\ub2e4","V/A-(\uc73c)\u3134/\ub294 \ubc18\uba74\uc5d0","V/A-\ub2e4\uace0 \ud574\uc11c \ubc18\ub4dc\uc2dc V/A-(\uc73c)\u3134/\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4","V/A-\ub354\ub77c\ub3c4","V-\uae30 \uc704\ud574\uc11c\ub294","V-\ub294 \uadfc\uac70\ub85c","V-\uae30\ubcf4\ub2e4\ub294","V-(\uc73c)\u3139 \uac00\ub2a5\uc131\uc774 \uc788\ub2e4","V/A-(\uc73c)\u3134/\ub294 \ub9cc\ud07c","V-\ub294 \uac83\uc73c\ub85c \ub098\ud0c0\ub098\ub2e4"],t.s)
A.fYj=s(["\uc8fc\uc7a5 = l\u1eadp lu\u1eadn","\uc758\uacac = \xfd ki\u1ebfn","\uc785\uc7a5 = l\u1eadp tr\u01b0\u1eddng","\ucc2c\uc131 = t\xe1n th\xe0nh","\ubc18\ub300 = ph\u1ea3n \u0111\u1ed1i","\uadfc\uac70 = c\u0103n c\u1ee9","\uc774\uc720 = l\xfd do","\uc608\uc2dc = v\xed d\u1ee5","\uc0ac\ub840 = tr\u01b0\u1eddng h\u1ee3p th\u1ef1c t\u1ebf","\uc790\ub8cc = d\u1eef li\u1ec7u","\ud1b5\uacc4 = th\u1ed1ng k\xea","\uac1d\uad00\uc801\uc774\ub2e4 = kh\xe1ch quan","\uc8fc\uad00\uc801\uc774\ub2e4 = ch\u1ee7 quan","\ub17c\ub9ac = logic","\ub17c\ub9ac\uc801\uc774\ub2e4 = c\xf3 t\xednh logic","\uc124\ub4dd\ub825 = s\u1ee9c thuy\u1ebft ph\u1ee5c","\ud1a0\ub860 = th\u1ea3o lu\u1eadn","\ub17c\uc7c1 = tranh lu\u1eadn/tranh c\xe3i","\uc7c1\uc810 = v\u1ea5n \u0111\u1ec1 tr\u1ecdng t\xe2m","\ubc18\ub860 = ph\u1ea3n bi\u1ec7n","\ubc18\ubc15\ud558\ub2e4 = ph\u1ea3n b\xe1c","\uc7ac\ubc18\ub860 = ph\u1ea3n bi\u1ec7n l\u1ea1i","\ub3d9\uc758\ud558\ub2e4 = \u0111\u1ed3ng \xfd","\uc778\uc815\ud558\ub2e4 = c\xf4ng nh\u1eadn","\ud0c0\ub2f9\ud558\ub2e4 = h\u1ee3p l\xfd","\ud569\ub9ac\uc801\uc774\ub2e4 = h\u1ee3p l\xfd","\ubaa8\uc21c = m\xe2u thu\u1eabn logic","\uc804\uc81c = ti\u1ec1n \u0111\u1ec1","\uacb0\ub860 = k\u1ebft lu\u1eadn","\ub300\uc548 = ph\u01b0\u01a1ng \xe1n thay th\u1ebf","\uacf5\ud1b5\uc810 = \u0111i\u1ec3m chung","\ucc28\uc774\uc810 = \u0111i\u1ec3m kh\xe1c","\ud569\uc758 = s\u1ef1 th\u1ed1ng nh\u1ea5t","N\uc5d0 \ub530\ub974\uba74 = theo N...","V/A-\ub2e4\ub294 \uc810\uc5d0\uc11c = x\xe9t \u1edf \u0111i\u1ec3m r\u1eb1ng...","V/A-\ub2e4\uace0 \ubcfc \uc218 \uc788\ub2e4 = c\xf3 th\u1ec3 xem l\xe0...","V/A-(\uc73c)\u3134/\ub294 \ubc18\uba74\uc5d0 = trong khi/tr\xe1i l\u1ea1i...",u.C,"V/A-\ub354\ub77c\ub3c4 = d\xf9... th\xec v\u1eabn...","V-\uae30 \uc704\ud574\uc11c\ub294 = \u0111\u1ec3... th\xec c\u1ea7n...","\ucd5c\uadfc \uc870\uc0ac\uc5d0 \ub530\ub974\uba74 \uc774\uc6a9\uc790 \ub9cc\uc871\ub3c4\uac00 \ub192\uc544\uc84c\uc2b5\ub2c8\ub2e4.","\uc2dc\uac04\uc744 \uc904\uc77c \uc218 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c \uc774 \ubc29\ubc95\uc740 \uc7a5\uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4.","\uc5ec\ub7ec \uc790\ub8cc\ub97c \uc885\ud569\ud558\uba74 \uc77c\uc815\ud55c \ud6a8\uacfc\uac00 \uc788\ub2e4\uace0 \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.",u.cL,"\ub9ce\uc740 \uc0ac\ub78c\uc774 \ucc2c\uc131\ud55c\ub2e4\uace0 \ud574\uc11c \ubc18\ub4dc\uc2dc \uac00\uc7a5 \uc88b\uc740 \ubc29\ubc95\uc778 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.","\uc758\uacac\uc774 \ub2e4\ub974\ub354\ub77c\ub3c4 \uc0c1\ub300\ubc29\uc758 \ub9d0\uc744 \ub05d\uae4c\uc9c0 \ub4e4\uc5b4\uc57c \ud569\ub2c8\ub2e4.","\uc88b\uc740 \uacb0\ub860\uc744 \ub0b4\ub9ac\uae30 \uc704\ud574\uc11c\ub294 \ucc2c\uc131\uacfc \ubc18\ub300 \uadfc\uac70\ub97c \ubaa8\ub450 \uac80\ud1a0\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc8fc\uc7a5\uacfc \uc758\uacac\uc740 \ube44\uc2b7\ud574 \ubcf4\uc774\uc9c0\ub9cc \uc88b\uc740 \uc8fc\uc7a5\uc740 \uc774\uc720\uc640 \uadfc\uac70\ub97c \ud1b5\ud574 \uc790\uc2e0\uc758 \uacb0\ub860\uc744 \uc124\uba85\ud55c\ub2e4\ub294 \ucc28\uc774\uac00 \uc788\uc2b5\ub2c8\ub2e4.","\ud1a0\ub860\uc5d0\uc11c \uc0c1\ub300\ubc29\uc758 \uc8fc\uc7a5\uc744 \ubc18\ubc15\ud560 \ub54c\ub294 \uc0ac\ub78c\uc744 \uacf5\uaca9\ud558\uc9c0 \ub9d0\uace0 \uc8fc\uc7a5, \uc804\uc81c, \uc790\ub8cc\uc640 \ub17c\ub9ac \uc0ac\uc774\uc5d0 \ubb38\uc81c\uac00 \uc788\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc790\uc2e0\uc758 \uae30\uc874 \uc8fc\uc7a5\uacfc \ub2e4\ub978 \uc790\ub8cc\uac00 \ub098\uc654\uc744 \ub54c \uc758\uacac\uc744 \uc218\uc815\ud558\ub294 \uac83\uc740 \ud328\ubc30\uac00 \uc544\ub2c8\ub77c \ub354 \uc815\ud655\ud55c \ud310\ub2e8\uc744 \uc704\ud55c \uacfc\uc815\uc785\ub2c8\ub2e4.","\ubc18\ub300 \uc758\uacac\uc744 \ub0bc \ub54c \ubb38\uc81c\uc810\ub9cc \uc9c0\uc801\ud558\uae30\ubcf4\ub2e4 \uac00\ub2a5\ud55c \ub300\uc548\uae4c\uc9c0 \uc81c\uc2dc\ud558\uba74 \ud1a0\ub860\uc758 \uac00\uce58\uac00 \ub192\uc544\uc9d1\ub2c8\ub2e4.","\ud575\uc2ec \uad6c\uc870: \uc8fc\uc81c \ud655\uc778 \u2192 \uc790\uc2e0\uc758 \uc785\uc7a5 \u2192 \uc774\uc720 \u2192 \uadfc\uac70 \u2192 \uad6c\uccb4\uc801 \uc0ac\ub840 \u2192 \uc0c1\ub300\ubc29 \ubc18\ub860 \u2192 \ubc18\ub860 \uac80\ud1a0 \u2192 \uc7ac\ubc18\ub860 \u2192 \uacf5\ud1b5\uc810 \u2192 \ub300\uc548 \u2192 \uacb0\ub860."],t.s)
A.Hn=new B.fT(19,"\uc8fc\uc7a5\uacfc \ud1a0\ub860","L\u1eadp lu\u1eadn v\xe0 th\u1ea3o lu\u1eadn",A.hMF,A.i4q,A.fE9,A.j0T,A.fDo,A.i6d,A.h3A,A.irS,A.iJe,A.hnc,A.iec,A.fYj)
A.iKz=s(["\uc791\uc5c5\uc7a5 \uc548\uc804\uacfc \uad00\ub828\ub41c \uae30\ubcf8 \ubc0f \uc911\uace0\uae09 \uc5b4\ud718\ub97c \ud559\uc2b5\ud569\ub2c8\ub2e4.","\uc0ac\uace0\uac00 \ubc1c\uc0dd\ud558\uae30 \uc804\uc5d0 \uc704\ud5d8 \uc694\uc18c\uc640 \uc774\uc0c1 \uc9d5\ud6c4\ub97c \ud30c\uc545\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc704\ud5d8\ud55c \uc0c1\ud669\uc744 \ub2f4\ub2f9\uc790\uc5d0\uac8c \ubcf4\uace0\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\ubcf4\ud638\uad6c\uc640 \ubcf4\ud638 \uc7a5\ube44\ub97c \uc62c\ubc14\ub974\uac8c \uc0ac\uc6a9\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc124\ube44\ub098 \uc791\uc5c5 \uad6c\uc5ed\uc774 \uc548\uc804\ud558\uc9c0 \uc54a\uc744 \ub54c \ub300\ucc98\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc0ac\uace0, \ubd80\uc0c1, \uc704\ud5d8, \uc774\uc0c1, \uace0\uc7a5\uacfc \uc751\uae09 \uc0c1\ud669\uc744 \uad6c\ubd84\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc0ac\uace0\uc758 \uc9c1\uc811 \uc6d0\uc778\uacfc \uc7a0\uc7ac \uc6d0\uc778\uc744 \uc124\uba85\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc608\ubc29 \uc870\uce58\uc640 \uc7ac\ubc1c \ubc29\uc9c0 \ub300\ucc45\uc5d0 \ub300\ud574 \ub9d0\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc791\uc5c5\uc744 \uc911\uc9c0\ud558\uace0 \uc548\uc804\uc744 \ud655\uc778\ud55c \ub4a4 \ub2e4\uc2dc \uc2dc\uc791\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uadfc\ubb34\uc870 \uac04\uc5d0 \uc548\uc804 \uc815\ubcf4\ub97c \uc778\uacc4\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc0ac\uace0 \ubc1c\uc0dd \uc2dc \uc2dc\uac04, \uc7a5\uc18c, \uc0c1\ud0dc\uc640 \uc870\uce58 \ub0b4\uc6a9\uc744 \uae30\ub85d\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\ub3d9\ub8cc\uc5d0\uac8c \uc704\ud5d8\uc744 \uba85\ud655\ud558\uace0 \uc815\uc911\ud558\uac8c \uc54c\ub9ac\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc548\uc804 \uad50\uc721\uc5d0 \ucc38\uc5ec\ud558\uace0 \uc791\uc5c5 \uc808\ucc28\uc758 \uc758\ubbf8\ub97c \uc774\ud574\ud569\ub2c8\ub2e4.","\uc704\ud5d8 \ubc1c\uacac \u2192 \uc791\uc5c5 \uc911\uc9c0 \u2192 \ubcf4\uace0 \u2192 \ud655\uc778 \u2192 \uc870\uce58 \u2192 \uc7ac\ud655\uc778 \u2192 \uc791\uc5c5 \uc7ac\uac1c\uc758 \uc548\uc804 \uc808\ucc28\ub97c \uc775\ud799\ub2c8\ub2e4."],t.s)
A.bES=new B.b("\uc791\uc5c5 \uc18d\ub3c4\ubcf4\ub2e4 \uc548\uc804\uc774 \ub354 \uc911\uc694\ud569\ub2c8\ub2e4.","An to\xe0n quan tr\u1ecdng h\u01a1n t\u1ed1c \u0111\u1ed9 l\xe0m vi\u1ec7c.")
A.c3s=new B.b("\uc791\uc5c5\uc744 \uc2dc\uc791\ud558\uae30 \uc804\uc5d0 \uc548\uc804 \uc0c1\ud0dc\ub97c \uba3c\uc800 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.","Tr\u01b0\u1edbc khi b\u1eaft \u0111\u1ea7u c\xf4ng vi\u1ec7c c\u1ea7n ki\u1ec3m tra t\xecnh tr\u1ea1ng an to\xe0n tr\u01b0\u1edbc.")
A.fJm=s([A.bES,A.c3s],t.R)
