A.fwG=s(["\ubbfc\uc9c0 \uc528\ub294 \uacf5\uc720 \uc218\uac00 \ub9ce\uc544\uc11c \ubc14\ub85c \ubbff\uc5c8\uc2b5\ub2c8\ub2e4.","\ubbfc\uc9c0 \uc528\ub294 \uc774\ubbf8 \uc9c0\uc6d0\uae08\uc744 \ubc1b\uc558\uc2b5\ub2c8\ub2e4.","\ubbfc\uc9c0 \uc528\ub294 \ucd9c\ucc98\uc640 \uacf5\uc2dd \uc548\ub0b4\ub97c \ud655\uc778\ud558\uace0 \uacf5\uc720\ub97c \ubcf4\ub958\ud588\uc2b5\ub2c8\ub2e4.","\ubbfc\uc9c0 \uc528\ub294 \uac8c\uc2dc \ub0a0\uc9dc\ub9cc \ud655\uc778\ud558\uace0 \ubc14\ub85c \uacf5\uc720\ud588\uc2b5\ub2c8\ub2e4."],t.s)
A.ce1=new B.a7("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\ubbfc\uc9c0 \uc528\ub294 SNS\uc5d0\uc11c \u201c\ub2e4\uc74c \ub2ec\ubd80\ud130 \ubaa8\ub4e0 \uc678\uad6d\uc778\uc5d0\uac8c \uc0c8\ub85c\uc6b4 \uc9c0\uc6d0\uae08\uc774 \uc9c0\uae09\ub41c\ub2e4\u201d\ub294 \uac8c\uc2dc\ubb3c\uc744 \ubd24\uc2b5\ub2c8\ub2e4. \uac8c\uc2dc\ubb3c\uc740 \ub9ce\uc774 \uacf5\uc720\ub418\uace0 \uc788\uc5c8\uc9c0\ub9cc \ucd9c\ucc98\uac00 \ud45c\uc2dc\ub418\uc5b4 \uc788\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. \ubbfc\uc9c0 \uc528\ub294 \uad00\ub828 \uae30\uad00\uc758 \ud648\ud398\uc774\uc9c0\ub97c \uac80\uc0c9\ud588\uc9c0\ub9cc \uac19\uc740 \ub0b4\uc6a9\uc758 \uacf5\uc2dd \uc548\ub0b4\ub97c \ucc3e\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \uac8c\uc2dc\ubb3c\uc744 \ubc14\ub85c \uce5c\uad6c\ub4e4\uc5d0\uac8c \ubcf4\ub0b4\uc9c0 \uc54a\uace0 \ucd94\uac00\ub85c \ud655\uc778\ud558\uae30\ub85c \ud588\uc2b5\ub2c8\ub2e4.",A.fwG,2,"\uc77d\uae30")
A.hoe=s(["\ud6c4\uae30 \ud558\ub098\ub9cc \ubcf4\uace0 \ubaa8\ub4e0 \uc0ac\ub78c\uc5d0\uac8c \uac19\uc740 \uacb0\uacfc\uac00 \uc788\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4.","\uc5ec\ub7ec \ud6c4\uae30\ub97c \ube44\uad50\ud558\uace0 \uc790\uc2e0\uc758 \uc0ac\uc6a9 \uc870\uac74\uacfc \ube44\uc2b7\ud55c \uc0ac\ub840\ub97c \ucc38\uace0\ud55c\ub2e4.","\ubcc4\uc810\uc774 \ub192\uc73c\uba74 \uc81c\ud488 \uc124\uba85\uc740 \ubcfc \ud544\uc694\uac00 \uc5c6\ub2e4.","\uad11\uace0\uc131 \uc5ec\ubd80\ub294 \uc804\ud600 \ud655\uc778\ud558\uc9c0 \uc54a\ub294\ub2e4."],t.s)
A.cfk=new B.a7("\uc628\ub77c\uc778 \ud6c4\uae30\ub97c \ud65c\uc6a9\ud558\ub294 \ubc29\ubc95\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",A.hoe,1,"\uc815\ubcf4 \ud65c\uc6a9")
A.hSy=s(["\ucd9c\ucc98\uc640 \ub0a0\uc9dc\ub97c \ud655\uc778\ud55c\ub2e4.","\uc0ac\uc2e4\uacfc \uc758\uacac\uc744 \uad6c\ubd84\ud55c\ub2e4.","\uc911\uc694\ud55c \ub0b4\uc6a9\uc740 \uc5ec\ub7ec \uc790\ub8cc\uc640 \ube44\uad50\ud55c\ub2e4.","\ucda9\uaca9\uc801\uc778 \ub0b4\uc6a9\uc774\uba74 \ud655\uc778 \uc5c6\uc774 \ucd5c\ub300\ud55c \ube68\ub9ac \uacf5\uc720\ud55c\ub2e4."],t.s)
A.ceo=new B.a7("\uc815\ubcf4\ub97c \ucc45\uc784 \uc788\uac8c \ud65c\uc6a9\ud558\ub294 \ubc29\ubc95\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud558\uc9c0 \uc54a\uc740 \uac83\uc740?",A.hSy,3,"\uc885\ud569")
