A.fGN=s(["\ucd9c\ucc98","\uac8c\uc2dc \ub0a0\uc9dc","\uc791\uc131\uc790","\uacf5\uc2dd \uc790\ub8cc","\ub2e4\ub978 \ucd9c\ucc98","\ud310\ub2e8"],t.s)
A.ch7=new B.c7("\uc778\ud130\ub137\uc5d0\uc11c \uc911\uc694\ud55c \uc815\ubcf4\ub97c \ubc1c\uacac\ud588\uc744 \ub54c \uc5b4\ub5bb\uac8c \ud655\uc778\ud558\ub294\uc9c0 \uc124\uba85\ud574 \ubcf4\uc138\uc694.",A.fGN,"\uc778\ud130\ub137\uc5d0\uc11c \uc911\uc694\ud55c \uc815\ubcf4\ub97c \ubc1c\uacac\ud558\uba74 \ubc14\ub85c \ubbff\uae30\ubcf4\ub2e4\ub294 \uba87 \uac00\uc9c0\ub97c \uba3c\uc800 \ud655\uc778\ud558\ub824\uace0 \ud569\ub2c8\ub2e4. \uac00\uc7a5 \uba3c\uc800 \uc815\ubcf4\uc758 \ucd9c\ucc98\uc640 \uac8c\uc2dc \ub0a0\uc9dc\ub97c \ud655\uc778\ud558\uace0 \ub204\uac00 \uc791\uc131\ud55c \uae00\uc778\uc9c0 \ubd05\ub2c8\ub2e4. \ud2b9\ud788 \ud589\uc815\uc774\ub098 \uc81c\ub3c4\ucc98\ub7fc \ub0b4\uc6a9\uc774 \ubc14\ub014 \uc218 \uc788\ub294 \uc815\ubcf4\ub294 \uad00\ub828 \uae30\uad00\uc758 \ucd5c\uc2e0 \uacf5\uc2dd \uc548\ub0b4\uc640 \ube44\uad50\ud569\ub2c8\ub2e4. \uadf8\ub2e4\uc74c \ub2e4\ub978 \ub9e4\uccb4\uc5d0\uc11c\ub3c4 \uac19\uc740 \ub0b4\uc6a9\uc774 \ud655\uc778\ub418\ub294\uc9c0 \ucc3e\uc544\ubd05\ub2c8\ub2e4. \uc5ec\ub7ec \ucd9c\ucc98\uc5d0\uc11c \ub0b4\uc6a9\uc774 \uc77c\uce58\ud558\uace0 \ucda9\ubd84\ud55c \uadfc\uac70\uac00 \uc788\uc744 \ub54c \uc2e0\ub8b0\ud560 \uc218 \uc788\ub294 \uc815\ubcf4\uc778\uc9c0 \ud310\ub2e8\ud569\ub2c8\ub2e4.")
A.iwW=s(["\uc6d0\ubcf8","\ub9e5\ub77d","\ucd2c\uc601 \ub0a0\uc9dc","\ud3b8\uc9d1","\ub2e4\ub978 \ucd9c\ucc98","\uacf5\uc720"],t.s)
A.chv=new B.c7("SNS\uc5d0\uc11c \ucda9\uaca9\uc801\uc778 \uc601\uc0c1\uc744 \ubd24\uc744 \ub54c \uc5b4\ub5bb\uac8c \ud310\ub2e8\ud560\uc9c0 \ub9d0\ud574 \ubcf4\uc138\uc694.",A.iwW,"SNS\uc5d0\uc11c \ucda9\uaca9\uc801\uc778 \uc601\uc0c1\uc744 \ubcf4\uba74 \uac10\uc815\uc801\uc73c\ub85c \ubc14\ub85c \ubc18\uc751\ud558\uc9c0 \uc54a\uc73c\ub824\uace0 \ud569\ub2c8\ub2e4. \uba3c\uc800 \uc601\uc0c1\uc758 \uc6d0\ubcf8\uc774 \uc788\ub294\uc9c0 \ud655\uc778\ud558\uace0 \uc5b8\uc81c \uc5b4\ub514\uc5d0\uc11c \ucd2c\uc601\ub41c \uac83\uc778\uc9c0 \ucc3e\uc544\ubd05\ub2c8\ub2e4. \uc601\uc0c1\uc774 \uc9e7\uac8c \ud3b8\uc9d1\ub41c \uacbd\uc6b0\uc5d0\ub294 \uc55e\ub4a4 \ub9e5\ub77d\uc774 \uc0dd\ub7b5\ub410\uc744 \uac00\ub2a5\uc131\uc774 \uc788\uae30 \ub54c\ubb38\uc5d0 \uc804\uccb4 \uc601\uc0c1\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \ub610\ud55c \ub2e4\ub978 \ub9e4\uccb4\ub098 \uacf5\uc2dd \uc790\ub8cc\uc5d0\uc11c\ub3c4 \uac19\uc740 \uc0ac\uac74\uc774 \ud655\uc778\ub418\ub294\uc9c0 \ube44\uad50\ud569\ub2c8\ub2e4. \uc0ac\uc2e4\uad00\uacc4\uac00 \ucda9\ubd84\ud788 \ud655\uc778\ub418\uc9c0 \uc54a\uc558\ub2e4\uba74 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ubc14\ub85c \uacf5\uc720\ud558\uc9c0 \uc54a\uaca0\uc2b5\ub2c8\ub2e4.")
A.fWI=s(["\uc870\ud68c \uc218","\uad00\uc2ec","\uc790\uadf9\uc801\uc778 \uc81c\ubaa9","\uc0ac\uc2e4 \uc5ec\ubd80","\uadfc\uac70","\ucd9c\ucc98"],t.s)
A.ch1=new B.c7("\uc870\ud68c \uc218\uac00 \ub9ce\uc740 \uc815\ubcf4\uac00 \ubc18\ub4dc\uc2dc \uc815\ud655\ud558\uc9c0 \uc54a\uc740 \uc774\uc720\ub97c \uc124\uba85\ud574 \ubcf4\uc138\uc694.",A.fWI,"\uc870\ud68c \uc218\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc5bc\ub9c8\ub098 \ub9ce\uc774 \ubd24\ub294\uc9c0\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc218\uce58\uc774\uc9c0 \uc815\ubcf4\uac00 \uc815\ud655\ud55c\uc9c0\ub97c \uc9c1\uc811 \ubcf4\uc5ec \uc8fc\ub294 \uc218\uce58\ub294 \uc544\ub2d9\ub2c8\ub2e4. \uc790\uadf9\uc801\uc778 \uc81c\ubaa9\uc774\ub098 \ud765\ubbf8\ub85c\uc6b4 \uc601\uc0c1\uc740 \uc0ac\uc2e4 \uc5ec\ubd80\uc640 \uad00\uacc4\uc5c6\uc774 \ub9ce\uc740 \uad00\uc2ec\uc744 \ubc1b\uc744 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc870\ud68c \uc218\uac00 \ub9ce\ub2e4\uace0 \ud574\uc11c \ubc18\ub4dc\uc2dc \ubbff\uc744 \uc218 \uc788\ub294 \uc815\ubcf4\uc778 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4. \uc815\ud655\uc131\uc744 \ud310\ub2e8\ud558\ub824\uba74 \ucd9c\ucc98, \uc791\uc131 \ub0a0\uc9dc\uc640 \uadfc\uac70\ub97c \ud655\uc778\ud558\uace0 \ub2e4\ub978 \uc790\ub8cc\uc640 \ube44\uad50\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.")
A.i9V=s(["\uc911\uc694\ub3c4","\ucd9c\ucc98","\uc6d0\ubb38","\uacf5\uc2dd \ud655\uc778","\uc0ac\uc2e4\uacfc \uc758\uacac","\uacf5\uc720 \uc5ec\ubd80"],t.s)
A.chN=new B.c7("\ud655\uc778\ub418\uc9c0 \uc54a\uc740 \uc815\ubcf4\ub97c \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uacf5\uc720\ud558\uae30 \uc804\uc5d0 \ubb34\uc5c7\uc744 \ud560\uc9c0 \ub9d0\ud574 \ubcf4\uc138\uc694.",A.i9V,"\uc815\ubcf4\ub97c \uc27d\uac8c \uacf5\uc720\ud560 \uc218 \uc788\ub294 \ub9cc\ud07c \uacf5\uc720 \uc804\uc5d0 \ud655\uc778\ud560 \ucc45\uc784\ub3c4 \uc788\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ud2b9\ud788 \ube44\uc790, \ucde8\uc5c5, \ub3c8\uc774\ub098 \uacf5\uacf5\uc11c\ube44\uc2a4\ucc98\ub7fc \ub2e4\ub978 \uc0ac\ub78c\uc758 \ud589\ub3d9\uc5d0 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub294 \uc815\ubcf4\ub294 \ub354 \uc2e0\uc911\ud558\uac8c \ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \uc6d0\ub798 \ucd9c\ucc98\uc640 \uc6d0\ubb38\uc744 \ud655\uc778\ud558\uace0 \ud604\uc7ac\ub3c4 \uc801\uc6a9\ub418\ub294 \uc815\ubcf4\uc778\uc9c0 \ud655\uc778\ud558\uaca0\uc2b5\ub2c8\ub2e4. \uc0ac\uc2e4\uacfc \uac1c\uc778\uc801\uc778 \uc758\uacac\uc774 \uc11e\uc5ec \uc788\ub2e4\uba74 \uad6c\ubd84\ud574\uc11c \ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \ucda9\ubd84\ud788 \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \ub0b4\uc6a9\uc774\ub77c\uba74 \u201c\ud655\uc2e4\ud558\uc9c0 \uc54a\ub2e4\u201d\uace0 \ud45c\uc2dc\ud558\uac70\ub098 \uc544\uc608 \uacf5\uc720\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.")
A.hkK=s([A.ch7,A.chv,A.ch1,A.chN],t.uf)
A.i21=s(["\ucd9c\ucc98\ub97c \uc4f0\uc138\uc694.","\uac8c\uc2dc \ub0a0\uc9dc\ub97c \uc4f0\uc138\uc694.","\uc791\uc131\uc790\ub97c \uc4f0\uc138\uc694.","\uadfc\uac70\ub97c \uc4f0\uc138\uc694.","\ub2e4\ub978 \uc790\ub8cc\uc640 \ube44\uad50\ud558\uc138\uc694.","V-\ub294\uc9c0 \ud655\uc778\ud558\ub2e4\uc640 V-\uae30\ubcf4\ub2e4\ub294\uc744 \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cv2=new B.cN("\uc778\ud130\ub137 \uc815\ubcf4\uc758 \uc2e0\ub8b0\uc131\uc744 \ud310\ub2e8\ud558\ub294 \ubc29\ubc95\uc744 \uc368 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft c\xe1ch \u0111\xe1nh gi\xe1 \u0111\u1ed9 tin c\u1eady c\u1ee7a th\xf4ng tin tr\xean Internet.",A.i21,"\uc778\ud130\ub137 \uc815\ubcf4\uc758 \uc2e0\ub8b0\uc131\uc744 \ud310\ub2e8\ud560 \ub54c\ub294 \ub0b4\uc6a9\ub9cc \uc77d\uae30\ubcf4\ub2e4 \uba3c\uc800 \ucd9c\ucc98\uac00 \uc5b4\ub514\uc778\uc9c0 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \ud2b9\ud788 \uc624\ub798\ub41c \uc815\ubcf4\uc77c \uc218 \uc788\uc73c\ubbc0\ub85c \uac8c\uc2dc \ub0a0\uc9dc\ub3c4 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4. \uc791\uc131\uc790\uac00 \ub204\uad6c\uc778\uc9c0\uc640 \ud574\ub2f9 \uc8fc\uc81c\uc5d0 \ub300\ud55c \uc804\ubb38\uc131\uc774 \uc788\ub294\uc9c0\ub3c4 \ucc38\uace0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uac15\ud55c \ud45c\ud604\uc774\ub098 \ub9ce\uc740 \uc870\ud68c \uc218\ub9cc \ubcf4\uace0 \ud310\ub2e8\ud558\uae30\ubcf4\ub2e4\ub294 \uc8fc\uc7a5\uc744 \ub4b7\ubc1b\uce68\ud558\ub294 \uc790\ub8cc\uc640 \uadfc\uac70\uac00 \uc788\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \ub610\ud55c \uc911\uc694\ud55c \uc815\ubcf4\ub77c\uba74 \ud55c \uacf3\ub9cc \ubcf4\uc9c0 \uc54a\uace0 \ub2e4\ub978 \uc2e0\ub8b0\ud560 \uc218 \uc788\ub294 \uc790\ub8cc\uc640 \ube44\uad50\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","Khi \u0111\xe1nh gi\xe1 \u0111\u1ed9 tin c\u1eady c\u1ee7a th\xf4ng tin tr\xean Internet, thay v\xec ch\u1ec9 \u0111\u1ecdc n\u1ed9i dung c\u1ea7n ki\u1ec3m tra tr\u01b0\u1edbc ngu\u1ed3n \u1edf \u0111\xe2u. V\xec c\xf3 th\u1ec3 l\xe0 th\xf4ng tin c\u0169 n\xean ng\xe0y \u0111\u0103ng c\u0169ng r\u1ea5t quan tr\u1ecdng. C\xf3 th\u1ec3 tham kh\u1ea3o ai l\xe0 ng\u01b0\u1eddi vi\u1ebft v\xe0 h\u1ecd c\xf3 chuy\xean m\xf4n li\xean quan \u0111\u1ebfn ch\u1ee7 \u0111\u1ec1 kh\xf4ng. Thay v\xec ph\xe1n \u0111o\xe1n ch\u1ec9 v\xec c\xe1ch di\u1ec5n \u0111\u1ea1t m\u1ea1nh ho\u1eb7c nhi\u1ec1u l\u01b0\u1ee3t xem, c\u1ea7n ki\u1ec3m tra c\xf3 d\u1eef li\u1ec7u v\xe0 c\u0103n c\u1ee9 h\u1ed7 tr\u1ee3 l\u1eadp lu\u1eadn hay kh\xf4ng. Ngo\xe0i ra n\u1ebfu l\xe0 th\xf4ng tin quan tr\u1ecdng th\xec n\xean so s\xe1nh v\u1edbi nh\u1eefng ngu\u1ed3n \u0111\xe1ng tin kh\xe1c thay v\xec ch\u1ec9 xem m\u1ed9t n\u01a1i.")
A.fKy=s(["\uacf5\uc720 \uc18d\ub3c4\ub97c \uc4f0\uc138\uc694.","\uc790\uadf9\uc801\uc778 \ub0b4\uc6a9\ub3c4 \uc4f0\uc138\uc694.","\uc870\ud68c \uc218\ub97c \uc4f0\uc138\uc694.","\uac80\uc99d\uc744 \uc4f0\uc138\uc694.","\uacf5\uc720 \ucc45\uc784\uc744 \uc4f0\uc138\uc694.","V/A-(\uc73c)\u3134/\ub294 \ubc18\uba74\uc5d0\uc640 V-\ub294 \ub9cc\ud07c\uc744 \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cuu=new B.cN("SNS\uc5d0\uc11c \uc798\ubabb\ub41c \uc815\ubcf4\uac00 \ube60\ub974\uac8c \ud655\uc0b0\ub420 \uc218 \uc788\ub294 \uc774\uc720\uc640 \ub300\uc751 \ubc29\ubc95\uc744 \uc368 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft l\xfd do th\xf4ng tin sai c\xf3 th\u1ec3 lan nhanh tr\xean m\u1ea1ng x\xe3 h\u1ed9i v\xe0 c\xe1ch \u1ee9ng ph\xf3.",A.fKy,"SNS\ub294 \ub204\uad6c\ub098 \uc815\ubcf4\ub97c \ube60\ub974\uac8c \uc62c\ub9ac\uace0 \uacf5\uc720\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c \ub9e4\uc6b0 \ud3b8\ub9ac\ud569\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \uc815\ubcf4\uac00 \ube60\ub974\uac8c \uc804\ub2ec\ub418\ub294 \ubc18\uba74\uc5d0 \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \ub0b4\uc6a9\ub3c4 \uc9e7\uc740 \uc2dc\uac04\uc5d0 \ub110\ub9ac \ud655\uc0b0\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ud2b9\ud788 \uc790\uadf9\uc801\uc778 \uc81c\ubaa9\uc774\ub098 \ucda9\uaca9\uc801\uc778 \uc601\uc0c1\uc740 \ub9ce\uc740 \uc0ac\ub78c\uc758 \uad00\uc2ec\uc744 \ubc1b\uc544 \uc870\ud68c \uc218\uc640 \uacf5\uc720 \uc218\uac00 \ube60\ub974\uac8c \uc99d\uac00\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \ub9ce\uc740 \uc0ac\ub78c\uc774 \ubd24\ub2e4\uace0 \ud574\uc11c \ubc18\ub4dc\uc2dc \uc0ac\uc2e4\uc778 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4. \uc815\ubcf4\ub97c \uc27d\uac8c \uacf5\uc720\ud560 \uc218 \uc788\ub294 \ub9cc\ud07c \uc0ac\uc6a9\uc790\ub294 \ucd9c\ucc98\uc640 \uc0ac\uc2e4 \uc5ec\ubd80\ub97c \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \ud655\uc2e4\ud558\uc9c0 \uc54a\uc740 \uc815\ubcf4\ub294 \ubc14\ub85c \uc804\ub2ec\ud558\uc9c0 \uc54a\uace0 \uc6d0\ubcf8\uacfc \uacf5\uc2dd \uc790\ub8cc\ub97c \ud655\uc778\ud55c \ud6c4 \uacf5\uc720\ud558\ub294 \ud0dc\ub3c4\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.","M\u1ea1ng x\xe3 h\u1ed9i r\u1ea5t ti\u1ec7n v\xec b\u1ea5t k\u1ef3 ai c\u0169ng c\xf3 th\u1ec3 \u0111\u0103ng v\xe0 chia s\u1ebb th\xf4ng tin nhanh ch\xf3ng. Tuy nhi\xean, trong khi th\xf4ng tin \u0111\u01b0\u1ee3c truy\u1ec1n r\u1ea5t nhanh th\xec n\u1ed9i dung ch\u01b0a \u0111\u01b0\u1ee3c x\xe1c minh c\u0169ng c\xf3 th\u1ec3 lan r\u1ed9ng trong th\u1eddi gian ng\u1eafn. \u0110\u1eb7c bi\u1ec7t ti\xeau \u0111\u1ec1 gi\u1eadt g\xe2n ho\u1eb7c video g\xe2y s\u1ed1c c\xf3 th\u1ec3 thu h\xfat s\u1ef1 ch\xfa \xfd v\xe0 l\xe0m l\u01b0\u1ee3t xem, l\u01b0\u1ee3t chia s\u1ebb t\u0103ng nhanh. Nh\u01b0ng kh\xf4ng ph\u1ea3i c\u1ee9 nhi\u1ec1u ng\u01b0\u1eddi xem th\xec nh\u1ea5t \u0111\u1ecbnh l\xe0 s\u1ef1 th\u1eadt. V\xec c\xf3 th\u1ec3 chia s\u1ebb th\xf4ng tin r\u1ea5t d\u1ec5 d\xe0ng n\xean ng\u01b0\u1eddi d\xf9ng c\u1ea7n ki\u1ec3m tra ngu\u1ed3n v\xe0 t\xednh x\xe1c th\u1ef1c. V\u1edbi th\xf4ng tin ch\u01b0a ch\u1eafc ch\u1eafn, \u0111i\u1ec1u quan tr\u1ecdng l\xe0 kh\xf4ng chuy\u1ec3n ti\u1ebfp ngay m\xe0 ki\u1ec3m tra b\u1ea3n g\u1ed1c v\xe0 ngu\u1ed3n ch\xednh th\u1ee9c tr\u01b0\u1edbc.")
A.fZj=s(["\uc0ac\uc2e4\uacfc \uc758\uacac\uc744 \uad6c\ubd84\ud558\uc138\uc694.","\ub9e5\ub77d\uc744 \uc4f0\uc138\uc694.","\uad11\uace0\ub97c \uc4f0\uc138\uc694.","\uc624\ub798\ub41c \uc815\ubcf4\ub97c \uc4f0\uc138\uc694.","\uacf5\uc720\ub97c \uc4f0\uc138\uc694.","V/A-\ub2e4\uace0 \ud574\uc11c \ubc18\ub4dc\uc2dc ... \uac83\uc740 \uc544\ub2c8\ub2e4\uc640 V-(\uc73c)\u3139 \uac00\ub2a5\uc131\uc774 \uc788\ub2e4\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cuF=new B.cN("\ubbf8\ub514\uc5b4\ub97c \ucc45\uc784 \uc788\uac8c \ud65c\uc6a9\ud558\uae30 \uc704\ud574 \ud544\uc694\ud55c \ud0dc\ub3c4\uc5d0 \ub300\ud574 \uc368 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft th\xe1i \u0111\u1ed9 c\u1ea7n thi\u1ebft \u0111\u1ec3 s\u1eed d\u1ee5ng truy\u1ec1n th\xf4ng c\xf3 tr\xe1ch nhi\u1ec7m.",A.fZj,"\ubbf8\ub514\uc5b4\ub97c \ucc45\uc784 \uc788\uac8c \ud65c\uc6a9\ud558\ub824\uba74 \uc815\ubcf4\ub97c \ub9ce\uc774 \ubcf4\ub294 \uac83\ubcf4\ub2e4 \uc815\ubcf4\ub97c \uc5b4\ub5bb\uac8c \ud310\ub2e8\ud558\ub294\uc9c0\uac00 \ub354 \uc911\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uba3c\uc800 \uc0ac\uc2e4, \uc758\uacac\uacfc \ucd94\uce21\uc744 \uad6c\ubd84\ud574\uc11c \uc77d\uc5b4\uc57c \ud569\ub2c8\ub2e4. \uc870\ud68c \uc218\uac00 \ub9ce\ub2e4\uace0 \ud574\uc11c \ubc18\ub4dc\uc2dc \uc815\ud655\ud55c \uc815\ubcf4\uc778 \uac83\uc740 \uc544\ub2c8\ubbc0\ub85c \ucd9c\ucc98\uc640 \uadfc\uac70\ub97c \ud568\uaed8 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \uc9e7\uc740 \uc601\uc0c1\uc774\ub098 \uc778\uc6a9\ubb38\uc740 \uc804\uccb4 \ub9e5\ub77d\uc774 \uc0dd\ub7b5\ub410\uc744 \uac00\ub2a5\uc131\uc774 \uc788\uae30 \ub54c\ubb38\uc5d0 \uac00\ub2a5\ud55c \uacbd\uc6b0 \uc6d0\ubcf8\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \ub610\ud55c \uc815\ubcf4\uc131 \uae00\ucc98\ub7fc \ubcf4\uc774\ub294 \ucf58\ud150\uce20\ub77c\ub3c4 \uad11\uace0 \ubaa9\uc801\uc774 \uc788\ub294\uc9c0 \uc0dd\uac01\ud574 \ubcfc \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uc624\ub798\ub41c \uc815\ubcf4\uac00 \ud604\uc7ac\ub3c4 \ub9de\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \ub9d0\uace0 \ub0a0\uc9dc\ub97c \ud655\uc778\ud574\uc57c \ud558\uba70, \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uacf5\uc720\ud558\uae30 \uc804\uc5d0\ub294 \uc0ac\uc2e4 \uc5ec\ubd80\ub97c \ud55c \ubc88 \ub354 \ud655\uc778\ud558\ub294 \ud0dc\ub3c4\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.","\u0110\u1ec3 s\u1eed d\u1ee5ng truy\u1ec1n th\xf4ng c\xf3 tr\xe1ch nhi\u1ec7m, t\xf4i ngh\u0129 quan tr\u1ecdng h\u01a1n vi\u1ec7c xem nhi\u1ec1u th\xf4ng tin l\xe0 c\xe1ch m\xecnh \u0111\xe1nh gi\xe1 th\xf4ng tin \u0111\xf3. Tr\u01b0\u1edbc ti\xean c\u1ea7n ph\xe2n bi\u1ec7t s\u1ef1 th\u1eadt, \xfd ki\u1ebfn v\xe0 suy \u0111o\xe1n. Kh\xf4ng ph\u1ea3i c\u1ee9 nhi\u1ec1u l\u01b0\u1ee3t xem th\xec nh\u1ea5t \u0111\u1ecbnh l\xe0 th\xf4ng tin ch\xednh x\xe1c, v\xec v\u1eady c\u1ea7n ki\u1ec3m tra c\u1ea3 ngu\u1ed3n v\xe0 c\u0103n c\u1ee9. Video ng\u1eafn ho\u1eb7c c\xe2u tr\xedch c\xf3 kh\u1ea3 n\u0103ng b\u1ecb l\u01b0\u1ee3c b\u1ecf ng\u1eef c\u1ea3nh \u0111\u1ea7y \u0111\u1ee7 n\xean n\u1ebfu c\xf3 th\u1ec3 n\xean ki\u1ec3m tra b\u1ea3n g\u1ed1c. Ngo\xe0i ra ngay c\u1ea3 n\u1ed9i dung tr\xf4ng gi\u1ed1ng b\xe0i cung c\u1ea5p th\xf4ng tin c\u0169ng c\u1ea7n xem c\xf3 m\u1ee5c \u0111\xedch qu\u1ea3ng c\xe1o hay kh\xf4ng. Kh\xf4ng n\xean ngh\u0129 th\xf4ng tin c\u0169 v\u1eabn \u0111\xfang hi\u1ec7n t\u1ea1i m\xe0 c\u1ea7n ki\u1ec3m tra ng\xe0y th\xe1ng, v\xe0 tr\u01b0\u1edbc khi chia s\u1ebb cho ng\u01b0\u1eddi kh\xe1c c\u1ea7n x\xe1c minh th\xeam m\u1ed9t l\u1ea7n.")
A.iyl=s([A.cv2,A.cuu,A.cuF],t.l5)
A.hp9=s(["\uc815\ubcf4","\ubbf8\ub514\uc5b4","\ub9e4\uccb4","\ucd9c\ucc98","\uacf5\uc2dd \ucd9c\ucc98","\uc791\uc131\uc790","\uac8c\uc2dc\ud558\ub2e4","\uac8c\uc2dc\ubb3c","\uac8c\uc2dc \ub0a0\uc9dc","\uc0ac\uc2e4","\uc758\uacac","\uc8fc\uc7a5","\ucd94\uce21","\uadfc\uac70","\uc790\ub8cc","\uc6d0\ubb38","\uc778\uc6a9\ud558\ub2e4","\ub9e5\ub77d","\uc65c\uace1\ud558\ub2e4","\uc815\ubcf4 \uc65c\uace1","\uacfc\uc7a5\ud558\ub2e4","\uc624\ud574\ub97c \ubd88\ub7ec\uc77c\uc73c\ud0a4\ub2e4","\uac00\uc9dc \ub274\uc2a4","\ud5c8\uc704 \uc815\ubcf4","\uc798\ubabb\ub41c \uc815\ubcf4","\uc624\ub798\ub41c \uc815\ubcf4","\ucd5c\uc2e0 \uc815\ubcf4","\uc81c\ubaa9","\uc790\uadf9\uc801\uc774\ub2e4","\ud074\ub9ad\uc744 \uc720\ub3c4\ud558\ub2e4","\ub313\uae00","\uc870\ud68c \uc218","\uacf5\uc720\ud558\ub2e4","\ud655\uc0b0\ub418\ub2e4","\uad11\uace0","\uad11\uace0\uc131 \uc815\ubcf4","\uc2e0\ub8b0\ud558\ub2e4","\uc2e0\ub8b0\uc131","\uac80\uc99d\ud558\ub2e4"],t.s)
A.il7=s(["V/A-\ub2e4\uace0 \ud574\uc11c \ubc18\ub4dc\uc2dc V/A-(\uc73c)\u3134/\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4","V-\ub294\uc9c0 \ud655\uc778\ud558\ub2e4","V-\uae30\ubcf4\ub2e4\ub294","V/A-(\uc73c)\u3139 \uac00\ub2a5\uc131\uc774 \uc788\ub2e4","V-\ub294 \uac83\uc73c\ub85c \ud655\uc778\ub418\ub2e4","V/A-(\uc73c)\u3134/\ub294 \ubc18\uba74\uc5d0","V-\ub294 \ub9cc\ud07c","V/A-(\uc73c)\u3134/\ub294 \uac83\uc73c\ub85c \ub098\ud0c0\ub098\ub2e4","N\uc5d0 \ub530\ub974\uba74","V-\uae30 \uc804\uc5d0","V-\uc9c0 \uc54a\uc740 \ucc44","V-\ub294 \ub370 \ube44\ud574"],t.s)
A.isI=s(["\uc815\ubcf4 = th\xf4ng tin","\ubbf8\ub514\uc5b4 = truy\u1ec1n th\xf4ng","\ub9e4\uccb4 = ph\u01b0\u01a1ng ti\u1ec7n truy\u1ec1n th\xf4ng","\ucd9c\ucc98 = ngu\u1ed3n","\uacf5\uc2dd \ucd9c\ucc98 = ngu\u1ed3n ch\xednh th\u1ee9c","\uc791\uc131\uc790 = t\xe1c gi\u1ea3","\uac8c\uc2dc\ubb3c = b\xe0i \u0111\u0103ng","\uac8c\uc2dc \ub0a0\uc9dc = ng\xe0y \u0111\u0103ng","\uc0ac\uc2e4 = s\u1ef1 th\u1eadt/d\u1eef ki\u1ec7n","\uc758\uacac = \xfd ki\u1ebfn","\uc8fc\uc7a5 = l\u1eadp lu\u1eadn","\ucd94\uce21 = suy \u0111o\xe1n","\uadfc\uac70 = c\u0103n c\u1ee9","\uc790\ub8cc = t\xe0i li\u1ec7u/d\u1eef li\u1ec7u","\uc6d0\ubb38 = b\u1ea3n g\u1ed1c","\uc778\uc6a9\ud558\ub2e4 = tr\xedch d\u1eabn","\ub9e5\ub77d = ng\u1eef c\u1ea3nh","\uc65c\uace1\ud558\ub2e4 = b\xf3p m\xe9o","\uacfc\uc7a5\ud558\ub2e4 = ph\xf3ng \u0111\u1ea1i","\uac00\uc9dc \ub274\uc2a4 = tin gi\u1ea3","\ud5c8\uc704 \uc815\ubcf4 = th\xf4ng tin sai s\u1ef1 th\u1eadt","\uc798\ubabb\ub41c \uc815\ubcf4 = th\xf4ng tin sai","\uc624\ub798\ub41c \uc815\ubcf4 = th\xf4ng tin c\u0169","\ucd5c\uc2e0 \uc815\ubcf4 = th\xf4ng tin m\u1edbi nh\u1ea5t","\uc790\uadf9\uc801\uc774\ub2e4 = gi\u1eadt g\xe2n","\ub313\uae00 = b\xecnh lu\u1eadn","\uc870\ud68c \uc218 = l\u01b0\u1ee3t xem","\uacf5\uc720\ud558\ub2e4 = chia s\u1ebb","\ud655\uc0b0\ub418\ub2e4 = lan truy\u1ec1n","\uad11\uace0\uc131 \uc815\ubcf4 = th\xf4ng tin qu\u1ea3ng c\xe1o","\uc2e0\ub8b0\uc131 = \u0111\u1ed9 tin c\u1eady","\uac80\uc99d\ud558\ub2e4 = ki\u1ec3m ch\u1ee9ng","\uc870\ud68c \uc218\uac00 \ub9ce\ub2e4\uace0 \ud574\uc11c \ubc18\ub4dc\uc2dc \uc815\ud655\ud55c \uc815\ubcf4\uc778 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.","\uc815\ubcf4\uac00 \uc5b4\ub514\uc5d0\uc11c \ub098\uc628 \uac83\uc778\uc9c0 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc81c\ubaa9\ub9cc \ubcf4\uace0 \ud310\ub2e8\ud558\uae30\ubcf4\ub2e4\ub294 \ubcf8\ubb38\uc744 \uc9c1\uc811 \uc77d\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","\uc601\uc0c1\uc774 \uc6d0\ub798 \ub9e5\ub77d\uacfc \ub2e4\ub974\uac8c \ud3b8\uc9d1\ub410\uc744 \uac00\ub2a5\uc131\uc774 \uc788\uc2b5\ub2c8\ub2e4.","\ud655\uc778 \uacb0\uacfc \uc624\ub798\ub41c \uc0ac\uc9c4\uc778 \uac83\uc73c\ub85c \ud655\uc778\ub410\uc2b5\ub2c8\ub2e4.","SNS\ub294 \uc815\ubcf4\uac00 \ube60\ub978 \ubc18\uba74\uc5d0 \uc798\ubabb\ub41c \uc815\ubcf4\ub3c4 \ube60\ub974\uac8c \ud37c\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc815\ubcf4\ub97c \uc27d\uac8c \uacf5\uc720\ud560 \uc218 \uc788\ub294 \ub9cc\ud07c \ud655\uc778\ud560 \ucc45\uc784\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.","\uc0ac\uc2e4\uacfc \uc758\uacac\uc740 \uc11c\ub85c \ub2e4\ub985\ub2c8\ub2e4. \uc758\uacac\uc774 \ub9ce\uc544\ub3c4 \uc0ac\uc2e4\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.","\ucd9c\ucc98\uac00 \uc788\ub2e4\uace0 \ub05d\ub098\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ucd9c\ucc98 \uc790\uccb4\uac00 \ubb34\uc5c7\uc778\uc9c0, \uc5bc\ub9c8\ub098 \ucd5c\uc2e0\uc778\uc9c0\uc640 \uc6d0\uc790\ub8cc\uac00 \uc2e4\uc81c \uc8fc\uc7a5\uc744 \ub4b7\ubc1b\uce68\ud558\ub294\uc9c0\ub3c4 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc0ac\uc9c4\uacfc \uc601\uc0c1\uc740 \uac15\ud55c \uc778\uc0c1\uc744 \uc904 \uc218 \uc788\uc9c0\ub9cc \ucd2c\uc601 \uc2dc\uc810, \uc7a5\uc18c\uc640 \uc55e\ub4a4 \ub9e5\ub77d\uc774 \ube60\uc9c0\uba74 \uc6d0\ub798 \uc758\ubbf8\uc640 \ub2e4\ub974\uac8c \ubc1b\uc544\ub4e4\uc5ec\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc624\ub798\ub41c \uc815\ubcf4\ub294 \ub2f9\uc2dc\uc5d0\ub294 \ub9de\uc558\uc744 \uc218\ub3c4 \uc788\uae30 \ub54c\ubb38\uc5d0 \ud5c8\uc704 \uc815\ubcf4\uc640 \uad6c\ubd84\ud574\uc11c \uc774\ud574\ud574\uc57c \ud569\ub2c8\ub2e4.","\ud575\uc2ec \ud750\ub984: \uc815\ubcf4 \ubc1c\uacac \u2192 \ucd9c\ucc98 \ud655\uc778 \u2192 \uac8c\uc2dc \ub0a0\uc9dc \ud655\uc778 \u2192 \uc791\uc131\uc790 \ud655\uc778 \u2192 \uc6d0\ubb38\xb7\uadfc\uac70 \ud655\uc778 \u2192 \ub2e4\ub978 \uc790\ub8cc \ube44\uad50 \u2192 \uc0ac\uc2e4\xb7\uc758\uacac\xb7\ucd94\uce21 \uad6c\ubd84 \u2192 \ud604\uc7ac \uc801\uc6a9 \uc5ec\ubd80 \ud310\ub2e8 \u2192 \uacf5\uc720 \uc5ec\ubd80 \uacb0\uc815."],t.s)
A.Hp=new B.fT(18,"\uc815\ubcf4 \ud310\ub2e8\uacfc \ubbf8\ub514\uc5b4 \ud65c\uc6a9",u.Q,A.hTB,A.h3a,A.iY9,A.hvX,A.ihb,A.itV,A.fOK,A.hkK,A.iyl,A.hp9,A.il7,A.isI)
A.fQV=s(["\ud55c\uad6d \uc0dd\ud65c\uc5d0\uc11c \ud544\uc694\ud55c \uc81c\ub3c4, \ud589\uc815 \uc808\ucc28\uc640 \uacf5\uacf5\uc11c\ube44\uc2a4\uc5d0 \ub300\ud574 \ub9d0\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc81c\ub3c4, \uc815\ucc45, \ud589\uc815, \uacf5\uacf5\uc11c\ube44\uc2a4\uc640 \ubbfc\uc6d0\uc744 \uad6c\ubd84\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\ud55c \uc808\ucc28\ub97c \ub2f4\ub2f9\ud558\ub294 \uae30\uad00\uc774\ub098 \ubd80\uc11c\ub97c \uc815\ud655\ud788 \ucc3e\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc2e0\uccad \uc804\uc5d0 \uc870\uac74, \ub300\uc0c1, \ud544\uc694 \uc11c\ub958\uc640 \uc808\ucc28\ub97c \ud655\uc778\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc2e0\uccad, \uc811\uc218, \uc2ec\uc0ac, \uc2b9\uc778, \ubc1c\uae09\uacfc \ucc98\ub9ac\ub97c \uad6c\ubd84\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\ucc98\ub9ac \uae30\uac04\uc744 \uc784\uc758\ub85c \ucd94\uce21\ud558\uc9c0 \uc54a\uace0 \uc815\ud655\ud788 \ubb38\uc758\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc11c\ub958 \ub204\ub77d, \ucd94\uac00 \uc790\ub8cc \uc81c\ucd9c\uacfc \uc815\ubcf4 \uc218\uc815\uc5d0 \ub300\ud574 \ub9d0\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc2e0\uccad\uc11c, \uc811\uc218 \ucc3d\uad6c\uc640 \uc628\ub77c\uc778 \ud589\uc815 \uc11c\ube44\uc2a4\ub97c \uc774\uc6a9\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc18c\ubb38\uc5d0\ub9cc \uc758\uc874\ud558\uc9c0 \uc54a\uace0 \uacf5\uc2dd \uc815\ubcf4\ub97c \ud655\uc778\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\ud589\uc815 \uc548\ub0b4\ubb38\uc5d0\uc11c \ub300\uc0c1, \uae30\uac04, \uc870\uac74\uacfc \uc2e0\uccad \ubc29\ubc95\uc744 \ucc3e\uc544 \uc77d\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\ubb38\uc81c\ub97c \uc81c\uae30\ud558\uac70\ub098 \ucc98\ub9ac \uc0c1\ud669\uc744 \uc815\uc911\ud558\uac8c \ubb38\uc758\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\ubaa8\ub450\uc5d0\uac8c \uc801\uc6a9\ub418\ub294 \uc11c\ube44\uc2a4\uc640 \ud2b9\uc815 \uc870\uac74\uc744 \ucda9\uc871\ud574\uc57c \uc774\uc6a9\ud560 \uc218 \uc788\ub294 \uc11c\ube44\uc2a4\ub97c \uad6c\ubd84\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\ub098\uc911\uc5d0 \ud655\uc778\ud560 \uc218 \uc788\ub3c4\ub85d \uc811\uc218\ubc88\ud638, \ud655\uc778\uc11c\uc640 \uad00\ub828 \uc790\ub8cc\ub97c \ubcf4\uad00\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\ud544\uc694\ud55c \uc11c\ube44\uc2a4 \ud655\uc778 \u2192 \ub2f4\ub2f9 \uae30\uad00 \ucc3e\uae30 \u2192 \uacf5\uc2dd \uc815\ubcf4 \ud655\uc778 \u2192 \ud544\uc694 \uc11c\ub958 \uc900\ube44 \u2192 \uc2e0\uccad\xb7\uc811\uc218 \u2192 \uc9c4\ud589 \uc0c1\ud669 \ud655\uc778 \u2192 \uacb0\uacfc \ud655\uc778 \u2192 \uc790\ub8cc \ubcf4\uad00\uc758 \uc774\uc6a9 \uc808\ucc28\ub97c \uc775\ud799\ub2c8\ub2e4."],t.s)
A.bQ9=new B.b("\ud544\uc694\ud55c \uc9c0\uc6d0 \uc81c\ub3c4\uac00 \uc788\ub294\uc9c0 \uba3c\uc800 \ud655\uc778\ud574 \ubd24\uc2b5\ub2c8\ub2e4.","T\xf4i \u0111\xe3 ki\u1ec3m tra tr\u01b0\u1edbc xem c\xf3 ch\u1ebf \u0111\u1ed9 h\u1ed7 tr\u1ee3 ph\xf9 h\u1ee3p hay kh\xf4ng.")
