A.cht=new B.c7("\ucc98\uc74c \uc124\uba85\ubc1b\uc740 \uadfc\ubb34 \uc870\uac74\uacfc \ud604\uc7ac \ub0b4\uc6a9\uc774 \ub2e4\ub97c \ub54c \ud655\uc778\ud574 \ubcf4\uc138\uc694.",A.hpU,"\ud300\uc7a5\ub2d8, \uadfc\ubb34 \uc870\uac74\uc5d0 \ub300\ud574 \ud655\uc778\ud558\uace0 \uc2f6\uc740 \ubd80\ubd84\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uc785\uc0ac \uc804\uc5d0\ub294 \uc8fc\uac04 \uadfc\ubb34\ub77c\uace0 \uc548\ub0b4\ubc1b\uc558\ub294\ub370 \uc774\ubc88\uc5d0 \ubc1b\uc740 \uc77c\uc815\uc5d0\ub294 \uc57c\uac04 \uadfc\ubb34\uac00 \ud3ec\ud568\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4. \uc81c\uac00 \uc798\ubabb \uc774\ud574\ud55c \uac83\uc778\uc9c0 \uc544\ub2c8\uba74 \uadfc\ubb34 \ud615\ud0dc\uac00 \ubcc0\uacbd\ub41c \uac83\uc778\uc9c0 \ud655\uc778\ud558\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \ub9cc\uc57d \ubcc0\uacbd\ub41c \ub0b4\uc6a9\uc774\ub77c\uba74 \uc5b8\uc81c\ubd80\ud130 \uc801\uc6a9\ub418\ub294\uc9c0\uc640 \uc55e\uc73c\ub85c\uc758 \uadfc\ubb34 \uc77c\uc815\ub3c4 \uac19\uc774 \uc124\uba85\ud574 \uc8fc\uc2e4 \uc218 \uc788\uc744\uae4c\uc694?")
A.iBo=s(["\uae09\uc5ec \uba85\uc138","\uacf5\uc81c \ud56d\ubaa9","\uae08\uc561","\uacc4\uc0b0 \uae30\uc900","\ud655\uc778"],t.s)
A.ch2=new B.c7("\uae09\uc5ec \uba85\uc138\uc5d0\uc11c \ubaa8\ub974\ub294 \ud56d\ubaa9\uc744 \ub2f4\ub2f9\uc790\uc5d0\uac8c \ubb38\uc758\ud574 \ubcf4\uc138\uc694.",A.iBo,"\uc774\ubc88 \uae09\uc5ec \uba85\uc138\ub97c \ud655\uc778\ud558\ub2e4\uac00 \uad81\uae08\ud55c \ubd80\ubd84\uc774 \uc788\uc5b4\uc11c \ubb38\uc758\ub4dc\ub9ac\ub824\uace0 \ud569\ub2c8\ub2e4. \uc5ec\uae30 \ud45c\uc2dc\ub41c \uacf5\uc81c \ud56d\ubaa9\uc758 \uae08\uc561\uc774 \uc5b4\ub5a4 \uae30\uc900\uc73c\ub85c \uacc4\uc0b0\ub41c \uac83\uc778\uc9c0 \uc798 \uc774\ud574\ud558\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4. \uc81c\uac00 \uc54c\uace0 \uc788\ub294 \ub0b4\uc6a9\uacfc \uc870\uae08 \ub2e4\ub978 \uac83 \uac19\uc544\uc11c \uc815\ud655\ud55c \ud56d\ubaa9\uba85\uacfc \uacc4\uc0b0 \uae30\uc900\uc744 \uc124\uba85\ud574 \uc8fc\uc2e4 \uc218 \uc788\uc744\uae4c\uc694? \uc81c\uac00 \uc798\ubabb \uc774\ud574\ud55c \ubd80\ubd84\uc774 \uc788\ub2e4\uba74 \uac19\uc774 \uc54c\ub824 \uc8fc\uc2dc\uba74 \uac10\uc0ac\ud558\uaca0\uc2b5\ub2c8\ub2e4.")
A.fZc=s(["\ub2f4\ub2f9 \uc5c5\ubb34","\uadfc\ubb34 \uc2dc\uac04","\uadfc\ubb34 \ud615\ud0dc","\uae09\uc5ec","\uac70\ub9ac","\uacbd\ub825 \ubaa9\ud45c"],t.s)
A.cgS=new B.c7("\ub450 \ud68c\uc0ac\uc758 \uadfc\ubb34 \uc870\uac74\uc744 \ube44\uad50\ud574\uc11c \uc790\uc2e0\uc758 \uc120\ud0dd\uc744 \uc124\uba85\ud574 \ubcf4\uc138\uc694.",A.fZc,"A \ud68c\uc0ac\ub294 \uc9d1\uc5d0\uc11c \uac00\uae4c\uc6cc\uc11c \ucd9c\ud1f4\uadfc\uc774 \ud3b8\ud55c \ubc18\uba74\uc5d0 \uc81c\uac00 \uc6d0\ud558\ub294 \uc9c1\ubb34\uc640\ub294 \uc870\uae08 \ub2e4\ub985\ub2c8\ub2e4. B \ud68c\uc0ac\ub294 \uac70\ub9ac\uac00 \ub354 \uba40\uace0 \uad50\ub300 \uadfc\ubb34\uac00 \uc788\uc9c0\ub9cc \uc81c\uac00 \uc9c0\uae08\uae4c\uc9c0 \uc313\uc740 \uc0dd\uc0b0 \uacbd\ud5d8\uc744 \ud65c\uc6a9\ud558\uba74\uc11c \ud488\uc9c8 \uc5c5\ubb34\ub3c4 \ubc30\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uae09\uc5ec \uc870\uac74\ub9cc \ubcf4\uba74 \ub450 \ud68c\uc0ac\uc758 \ucc28\uc774\uac00 \ud06c\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc800\ub294 \uc7a5\uae30\uc801\uc73c\ub85c \ud488\uc9c8 \ubd84\uc57c\uc758 \uacbd\ub825\uc744 \uc313\uace0 \uc2f6\uae30 \ub54c\ubb38\uc5d0 \uadfc\ubb34 \ud615\ud0dc\uc640 \uc2e4\uc81c \ub2f4\ub2f9 \uc5c5\ubb34\ub97c \ub354 \ud655\uc778\ud55c \ud6c4 B \ud68c\uc0ac\ub97c \uc6b0\uc120\uc801\uc73c\ub85c \uac80\ud1a0\ud558\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.")
A.hHK=s([A.cgD,A.cht,A.ch2,A.cgS],t.uf)
A.fUz=s(["\ub2f4\ub2f9 \uc5c5\ubb34\ub97c \uc4f0\uc138\uc694.","\uadfc\ubb34 \uc7a5\uc18c\ub97c \uc4f0\uc138\uc694.","\uadfc\ubb34 \uc2dc\uac04\uacfc \uadfc\ubb34 \ud615\ud0dc\ub97c \uc4f0\uc138\uc694.","\uae09\uc5ec \uad00\ub828 \ub0b4\uc6a9\uc744 \uc4f0\uc138\uc694.","\ubcc0\uacbd \uc870\uac74\uc744 \uc4f0\uc138\uc694.","\uc11c\uba85 \uc804 \ud655\uc778\uc758 \uc911\uc694\uc131\uc744 \uc4f0\uc138\uc694.","V-\uae30 \uc804\uc5d0\uc640 V-\ub294\uc9c0 \ud655\uc778\ud558\ub2e4\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cuS=new B.cN("\uadfc\ub85c\uacc4\uc57d\uc11c\ub97c \ud655\uc778\ud560 \ub54c \uc911\uc694\ud558\uac8c \ubcfc \ub0b4\uc6a9\uc744 \uc368 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft nh\u1eefng n\u1ed9i dung quan tr\u1ecdng c\u1ea7n ki\u1ec3m tra khi \u0111\u1ecdc h\u1ee3p \u0111\u1ed3ng lao \u0111\u1ed9ng.",A.fUz,"\uadfc\ub85c\uacc4\uc57d\uc11c\ub97c \ud655\uc778\ud560 \ub54c\ub294 \uae09\uc5ec\ub9cc \ubcf4\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \uc77c\uc744 \ud558\uac8c \ub418\ub294\uc9c0 \uc804\uccb4\uc801\uc778 \uadfc\ub85c \uc870\uac74\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4. \uba3c\uc800 \ub2f4\ub2f9 \uc5c5\ubb34\uc640 \uadfc\ubb34 \uc7a5\uc18c\uac00 \ucc44\uc6a9 \uacfc\uc815\uc5d0\uc11c \uc124\uba85\ubc1b\uc740 \ub0b4\uc6a9\uacfc \uac19\uc740\uc9c0 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \ub610\ud55c \uae30\ubcf8 \uadfc\ubb34 \uc2dc\uac04, \ud734\uac8c \uc2dc\uac04\uacfc \uadfc\ubb34 \ud615\ud0dc\ub3c4 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \uae09\uc5ec \ubd80\ubd84\uc5d0\uc11c\ub294 \uc5b4\ub5a4 \ud56d\ubaa9\uc73c\ub85c \uad6c\uc131\ub418\uc5b4 \uc788\ub294\uc9c0\uc640 \uc9c0\uae09 \uad00\ub828 \ub0b4\uc6a9\ub3c4 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ud574\ub418\uc9c0 \uc54a\ub294 \uc870\ud56d\uc774 \uc788\ub2e4\uba74 \uc11c\uba85\ud558\uae30 \uc804\uc5d0 \ub2f4\ub2f9\uc790\uc5d0\uac8c \uc9c8\ubb38\ud574\uc57c \ud569\ub2c8\ub2e4. \ud2b9\ud788 \uad6c\ub450\ub85c \uc124\uba85\ubc1b\uc740 \uc911\uc694\ud55c \ub0b4\uc6a9\uc774 \uacc4\uc57d\uc11c\uc5d0\ub3c4 \ud3ec\ud568\ub418\uc5b4 \uc788\ub294\uc9c0 \ud655\uc778\ud558\uace0 \uad00\ub828 \uc11c\ub958\ub97c \ub098\uc911\uc5d0 \ub2e4\uc2dc \ubcfc \uc218 \uc788\ub3c4\ub85d \ubcf4\uad00\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","Khi ki\u1ec3m tra h\u1ee3p \u0111\u1ed3ng lao \u0111\u1ed9ng, \u0111i\u1ec1u quan tr\u1ecdng kh\xf4ng ph\u1ea3i ch\u1ec9 xem l\u01b0\u01a1ng m\xe0 c\u1ea7n ki\u1ec3m tra to\xe0n b\u1ed9 \u0111i\u1ec1u ki\u1ec7n l\xe0m vi\u1ec7c, bao g\u1ed3m th\u1ef1c t\u1ebf m\xecnh s\u1ebd l\xe0m c\xf4ng vi\u1ec7c g\xec. Tr\u01b0\u1edbc ti\xean c\u1ea7n x\xe1c nh\u1eadn c\xf4ng vi\u1ec7c ph\u1ee5 tr\xe1ch v\xe0 \u0111\u1ecba \u0111i\u1ec3m l\xe0m vi\u1ec7c c\xf3 gi\u1ed1ng n\u1ed9i dung \u0111\u01b0\u1ee3c gi\u1ea3i th\xedch trong qu\xe1 tr\xecnh tuy\u1ec3n d\u1ee5ng kh\xf4ng. Ngo\xe0i ra c\u0169ng n\xean ki\u1ec3m tra th\u1eddi gian l\xe0m vi\u1ec7c c\u01a1 b\u1ea3n, th\u1eddi gian ngh\u1ec9 v\xe0 h\xecnh th\u1ee9c l\xe0m vi\u1ec7c. V\u1ec1 ti\u1ec1n l\u01b0\u01a1ng c\u1ea7n x\xe1c nh\u1eadn ti\u1ec1n l\u01b0\u01a1ng g\u1ed3m nh\u1eefng kho\u1ea3n n\xe0o v\xe0 n\u1ed9i dung li\xean quan \u0111\u1ebfn chi tr\u1ea3. N\u1ebfu c\xf3 \u0111i\u1ec1u kho\u1ea3n ch\u01b0a hi\u1ec3u th\xec c\u1ea7n h\u1ecfi ng\u01b0\u1eddi ph\u1ee5 tr\xe1ch tr\u01b0\u1edbc khi k\xfd. \u0110\u1eb7c bi\u1ec7t n\xean ki\u1ec3m tra n\u1ed9i dung quan tr\u1ecdng \u0111\u01b0\u1ee3c gi\u1ea3i th\xedch b\u1eb1ng l\u1eddi c\xf3 n\u1eb1m trong h\u1ee3p \u0111\u1ed3ng hay kh\xf4ng v\xe0 l\u01b0u gi\u1eef gi\u1ea5y t\u1edd li\xean quan \u0111\u1ec3 sau n\xe0y c\xf3 th\u1ec3 xem l\u1ea1i.")
A.hna=s(["\uae30\uc874 \uc870\uac74\uc744 \uc4f0\uc138\uc694.","\ubcc0\uacbd\ub41c \ub0b4\uc6a9\uc744 \uc4f0\uc138\uc694.","\uc801\uc6a9 \uc2dc\uc810\uc744 \ud655\uc778\ud558\uc138\uc694.","\ub2f4\ub2f9\uc790\uc5d0\uac8c \uc9c8\ubb38\ud558\uc138\uc694.","\uc11c\uba74 \ud655\uc778\uc744 \ud3ec\ud568\ud558\uc138\uc694.","V-(\uc73c)\u3139 \uacbd\uc6b0\uc5d0\ub294\uacfc N\uc5d0 \ub530\ub77c\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cv1=new B.cN("\uadfc\ubb34 \uc870\uac74\uc774 \ubcc0\uacbd\ub410\uc744 \ub54c \uc5b4\ub5bb\uac8c \ud655\uc778\ud558\uba74 \uc88b\uc740\uc9c0 \uc368 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft c\xe1ch x\xe1c nh\u1eadn khi \u0111i\u1ec1u ki\u1ec7n l\xe0m vi\u1ec7c thay \u0111\u1ed5i.",A.hna,"\uadfc\ubb34 \uc870\uac74\uc774 \ubcc0\uacbd\ub410\ub2e4\ub294 \uc548\ub0b4\ub97c \ubc1b\uc558\uc744 \uacbd\uc6b0\uc5d0\ub294 \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0 \uad6c\uccb4\uc801\uc73c\ub85c \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uae30\uc874\uc5d0\ub294 \uc8fc\uac04 \uadfc\ubb34\uc600\ub294\ub370 \uad50\ub300 \uadfc\ubb34\ub85c \ubcc0\uacbd\ub41c\ub2e4\uace0 \ud55c\ub2e4\uba74 \uc0c8\ub85c\uc6b4 \uadfc\ubb34 \ud615\ud0dc\uac00 \uc5b8\uc81c\ubd80\ud130 \uc801\uc6a9\ub418\ub294\uc9c0\uc640 \uc77c\uc815\uc774 \uc5b4\ub5bb\uac8c \uc6b4\uc601\ub418\ub294\uc9c0 \uc9c8\ubb38\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubd80\uc11c\uc5d0 \ub530\ub77c \uc870\uac74\uc774 \ub2e4\ub97c \uc218 \uc788\uae30 \ub54c\ubb38\uc5d0 \uc790\uc2e0\uc758 \ubc30\uce58 \ubd80\uc11c\uc5d0 \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \uc870\uac74\uc774 \uc801\uc6a9\ub418\ub294\uc9c0\ub3c4 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \uc911\uc694\ud55c \ubcc0\uacbd \uc0ac\ud56d\uc740 \uad6c\ub450 \uc124\uba85\ub9cc \ub4e3\uae30\ubcf4\ub2e4 \uad00\ub828 \uc548\ub0b4\ub098 \ubb38\uc11c\uac00 \uc788\ub294\uc9c0\ub3c4 \ud655\uc778\ud574 \ub450\uba74 \ub098\uc911\uc5d0 \ub0b4\uc6a9\uc744 \ub2e4\uc2dc \ud655\uc778\ud558\uae30 \uc27d\uc2b5\ub2c8\ub2e4.","Khi nh\u1eadn th\xf4ng b\xe1o r\u1eb1ng \u0111i\u1ec1u ki\u1ec7n l\xe0m vi\u1ec7c thay \u0111\u1ed5i, n\xean x\xe1c nh\u1eadn c\u1ee5 th\u1ec3 n\u1ed9i dung n\xe0o \u0111\xe3 thay \u0111\u1ed5i. V\xed d\u1ee5 n\u1ebfu tr\u01b0\u1edbc \u0111\xe2y l\xe0m ca ng\xe0y nh\u01b0ng \u0111\u01b0\u1ee3c th\xf4ng b\xe1o chuy\u1ec3n sang l\xe0m theo ca, c\xf3 th\u1ec3 h\u1ecfi h\xecnh th\u1ee9c m\u1edbi \xe1p d\u1ee5ng t\u1eeb khi n\xe0o v\xe0 l\u1ecbch \u0111\u01b0\u1ee3c v\u1eadn h\xe0nh th\u1ebf n\xe0o. V\xec \u0111i\u1ec1u ki\u1ec7n c\xf3 th\u1ec3 kh\xe1c t\xf9y b\u1ed9 ph\u1eadn n\xean c\u0169ng c\u1ea7n x\xe1c nh\u1eadn \u0111i\u1ec1u ki\u1ec7n n\xe0o th\u1ef1c t\u1ebf \xe1p d\u1ee5ng cho b\u1ed9 ph\u1eadn m\xecnh \u0111\u01b0\u1ee3c b\u1ed1 tr\xed. V\u1edbi thay \u0111\u1ed5i quan tr\u1ecdng, thay v\xec ch\u1ec9 nghe gi\u1ea3i th\xedch b\u1eb1ng l\u1eddi n\xean ki\u1ec3m tra xem c\xf3 th\xf4ng b\xe1o ho\u1eb7c v\u0103n b\u1ea3n li\xean quan hay kh\xf4ng \u0111\u1ec3 sau n\xe0y d\u1ec5 x\xe1c nh\u1eadn l\u1ea1i.")
A.iJR=s(["\uae09\uc5ec\ub97c \uc4f0\uc138\uc694.","\ub2f4\ub2f9 \uc5c5\ubb34\ub97c \uc4f0\uc138\uc694.","\uadfc\ubb34 \uc2dc\uac04\uacfc \ud615\ud0dc\ub97c \uc4f0\uc138\uc694.","\ud1b5\uadfc\uc744 \uc4f0\uc138\uc694.","\uacbd\ub825 \ubaa9\ud45c\ub97c \uc4f0\uc138\uc694.","\ub450 \uc870\uac74\uc744 \ube44\uad50\ud558\uc138\uc694.","V/A-(\uc73c)\u3134/\ub294 \ubc18\uba74\uc5d0\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cue=new B.cN("\uc9c1\uc7a5\uc744 \uc120\ud0dd\ud560 \ub54c \uc5b4\ub5a4 \uadfc\ub85c \uc870\uac74\uc744 \uace0\ub824\ud574\uc57c \ud558\ub294\uc9c0 \uc368 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft nh\u1eefng \u0111i\u1ec1u ki\u1ec7n l\xe0m vi\u1ec7c c\u1ea7n c\xe2n nh\u1eafc khi l\u1ef1a ch\u1ecdn c\xf4ng vi\u1ec7c.",A.iJR,"\uc9c1\uc7a5\uc744 \uc120\ud0dd\ud560 \ub54c\ub294 \uae09\uc5ec\ub9cc \ube44\uad50\ud558\uae30\ubcf4\ub2e4 \uc790\uc2e0\uc758 \uc0dd\ud65c\uacfc \uacbd\ub825 \ubaa9\ud45c\uc5d0 \ub9de\ub294\uc9c0\ub97c \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud569\ub2c8\ub2e4. \uc5b4\ub5a4 \ud68c\uc0ac\ub294 \uc9d1\uc5d0\uc11c \uac00\uae4c\uc6cc \ucd9c\ud1f4\uadfc\uc774 \ud3b8\ud55c \ubc18\uba74\uc5d0 \uc6d0\ud558\ub294 \uc9c1\ubb34\ub97c \uacbd\ud5d8\ud558\uae30 \uc5b4\ub824\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubc18\ub300\ub85c \uac70\ub9ac\ub294 \uc870\uae08 \uba40\uc9c0\ub9cc \uad00\uc2ec \uc788\ub294 \ubd84\uc57c\uc758 \uc5c5\ubb34\ub97c \ubc30\uc6b0\uace0 \uacbd\ub825\uc744 \uc313\uc744 \uc218 \uc788\ub294 \ud68c\uc0ac\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ub610\ud55c \uadfc\ubb34 \uc2dc\uac04, \uad50\ub300 \uadfc\ubb34 \uc5ec\ubd80\uc640 \uc2e4\uc81c \ub2f4\ub2f9 \uc5c5\ubb34\ub97c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \uc790\uc2e0\uc5d0\uac8c \uc911\uc694\ud55c \uc870\uac74\uc758 \uc6b0\uc120\uc21c\uc704\ub97c \uc815\ud55c \ud6c4 \uc5ec\ub7ec \uc870\uac74\uc744 \ud568\uaed8 \ube44\uad50\ud558\uba74 \uc7a5\uae30\uc801\uc73c\ub85c \ub354 \uc801\uc808\ud55c \uc120\ud0dd\uc744 \ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.","Khi l\u1ef1a ch\u1ecdn c\xf4ng vi\u1ec7c, thay v\xec ch\u1ec9 so s\xe1nh l\u01b0\u01a1ng c\u1ea7n c\xe2n nh\u1eafc li\u1ec7u c\xf4ng vi\u1ec7c c\xf3 ph\xf9 h\u1ee3p v\u1edbi cu\u1ed9c s\u1ed1ng v\xe0 m\u1ee5c ti\xeau ngh\u1ec1 nghi\u1ec7p c\u1ee7a m\xecnh hay kh\xf4ng. C\xf3 c\xf4ng ty g\u1ea7n nh\xe0 n\xean \u0111i l\xe0m thu\u1eadn ti\u1ec7n, nh\u01b0ng ng\u01b0\u1ee3c l\u1ea1i kh\xf3 c\xf3 kinh nghi\u1ec7m \u1edf v\u1ecb tr\xed mong mu\u1ed1n. Ng\u01b0\u1ee3c l\u1ea1i c\u0169ng c\xf3 c\xf4ng ty xa h\u01a1n m\u1ed9t ch\xfat nh\u01b0ng c\xf3 th\u1ec3 h\u1ecdc c\xf4ng vi\u1ec7c thu\u1ed9c l\u0129nh v\u1ef1c m\xecnh quan t\xe2m v\xe0 t\xedch l\u0169y s\u1ef1 nghi\u1ec7p. Ngo\xe0i ra c\u1ea7n ki\u1ec3m tra th\u1eddi gian l\xe0m vi\u1ec7c, c\xf3 l\xe0m theo ca hay kh\xf4ng v\xe0 c\xf4ng vi\u1ec7c th\u1ef1c t\u1ebf ph\u1ee5 tr\xe1ch. N\u1ebfu x\xe1c \u0111\u1ecbnh th\u1ee9 t\u1ef1 \u01b0u ti\xean c\u1ee7a nh\u1eefng \u0111i\u1ec1u ki\u1ec7n quan tr\u1ecdng v\u1edbi b\u1ea3n th\xe2n r\u1ed3i so s\xe1nh nhi\u1ec1u \u0111i\u1ec1u ki\u1ec7n c\xf9ng nhau th\xec s\u1ebd gi\xfap \u0111\u01b0a ra l\u1ef1a ch\u1ecdn ph\xf9 h\u1ee3p h\u01a1n v\u1ec1 l\xe2u d\xe0i.")
A.ixS=s([A.cuS,A.cv1,A.cue],t.l5)
