A.izo=s(["\ubbfc\uc218 \uc528\ub294 \ucc98\uc74c\ubd80\ud130 \uc7a5\ube44 \uc0ac\uc6a9\uc5d0 \ub2a5\uc219\ud588\uc2b5\ub2c8\ub2e4.","\ubbfc\uc218 \uc528\ub294 \uc2e4\uc218\ub97c \uae30\ub85d\ud558\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.","\ubbfc\uc218 \uc528\ub294 \uacbd\ud5d8\uc774 \uc313\uc774\uba74\uc11c \uc5c5\ubb34 \ub2a5\ub825\uc774 \ud5a5\uc0c1\ub410\uc2b5\ub2c8\ub2e4.","\ubbfc\uc218 \uc528\ub294 \ud604\uc7ac \uc77c\uc744 \uadf8\ub9cc\ub450\uc5c8\uc2b5\ub2c8\ub2e4."],t.s)
A.cc4=new B.a7("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\ubbfc\uc218 \uc528\ub294 \uc785\uc0ac \ucd08\uae30\uc5d0\ub294 \uc7a5\ube44 \uc870\uc791\uc774 \uc775\uc219\ud558\uc9c0 \uc54a\uc544 \uc791\uc5c5 \uc18d\ub3c4\uac00 \ub290\ub838\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc120\ubc30\uc5d0\uac8c \ubaa8\ub974\ub294 \ubd80\ubd84\uc744 \ubb3c\uc5b4\ubcf4\uace0 \uc791\uc5c5 \ud6c4\uc5d0\ub294 \uc2e4\uc218\ud55c \ub0b4\uc6a9\uc744 \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4. 6\uac1c\uc6d4 \uc815\ub3c4 \uc9c0\ub098\uc790 \uc791\uc5c5 \uc18d\ub3c4\uac00 \ube68\ub77c\uc84c\uc744 \ubfd0\ub9cc \uc544\ub2c8\ub77c \uac19\uc740 \uc2e4\uc218\ub3c4 \ud06c\uac8c \uc904\uc5c8\uc2b5\ub2c8\ub2e4. \ucd5c\uadfc\uc5d0\ub294 \uc2e0\uaddc \uc9c1\uc6d0\uc5d0\uac8c \uae30\ubcf8 \uc791\uc5c5 \ubc29\ubc95\uc744 \uc124\uba85\ud574 \uc8fc\uae30\ub3c4 \ud569\ub2c8\ub2e4.",A.izo,2,"\uc77d\uae30")
A.hlC=s(["\uc798\ud558\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.","\uc62c\ud574 \uc548\uc5d0 \ud604\uc7ac \uacf5\uc815\uc744 \ub3c5\ub9bd\uc801\uc73c\ub85c \uc218\ud589\ud560 \uc218 \uc788\ub3c4\ub85d \uc775\ud788\uaca0\uc2b5\ub2c8\ub2e4.","\uc131\uacf5\ud558\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.","\uc5f4\uc2ec\ud788 \ud558\uaca0\uc2b5\ub2c8\ub2e4."],t.s)
A.cdr=new B.a7("\ub2e4\uc74c \uc911 \uac00\uc7a5 \uad6c\uccb4\uc801\uc778 \uc9c1\ubb34 \ubaa9\ud45c\ub294?",A.hlC,1,"\ubaa9\ud45c")
A.ip4=s(["\ubd80\uc871\ud55c \ubd80\ubd84\uc744 \ud655\uc778\ud55c\ub2e4.","\ud544\uc694\ud55c \uae30\uc220\uc744 \uafb8\uc900\ud788 \ubc30\uc6b4\ub2e4.","\ud53c\ub4dc\ubc31\uc744 \uc5c5\ubb34\uc5d0 \ubc18\uc601\ud55c\ub2e4.","\uc2e4\uc218\ub294 \ubb34\uc870\uac74 \uc228\uae30\uace0 \uc0c8\ub85c\uc6b4 \uc5c5\ubb34\ub294 \ud53c\ud55c\ub2e4."],t.s)
