A.cgX=new B.c7("\ub450 \uc81c\ud488\uc744 \ube44\uad50\ud574\uc11c \uc5b4\ub5a4 \uc81c\ud488\uc744 \uc120\ud0dd\ud560\uc9c0 \uc124\uba85\ud574 \ubcf4\uc138\uc694.",A.hLf,"A \uc81c\ud488\uc740 \uac00\uaca9\uc774 \ub354 \uc2fc \ubc18\uba74\uc5d0 \ub0b4\uad6c\uc131\uc774 \ub0ae\uace0 \ud544\uc694\ud55c \uae30\ub2a5\uc774 \ud55c \uac00\uc9c0 \ube60\uc838 \uc788\uc2b5\ub2c8\ub2e4. B \uc81c\ud488\uc740 \ucc98\uc74c \uac00\uaca9\uc774 5\ub9cc \uc6d0 \ub354 \ube44\uc2f8\uc9c0\ub9cc \uc81c\uac00 \ud544\uc694\ud55c \uae30\ub2a5\uc774 \ubaa8\ub450 \uc788\uace0 \ubcf4\uc99d \uae30\uac04\ub3c4 \ub354 \uae41\ub2c8\ub2e4. \uc800\ub294 \uc774 \uc81c\ud488\uc744 3\ub144 \uc774\uc0c1 \uc0ac\uc6a9\ud560 \uacc4\ud68d\uc774\uae30 \ub54c\ubb38\uc5d0 \ucc98\uc74c \uac00\uaca9\ub9cc \ubcf4\uae30\ubcf4\ub2e4\ub294 \uc0ac\uc6a9 \uae30\uac04\uacfc \uc720\uc9c0 \ube44\uc6a9\uc744 \ud568\uaed8 \uc0dd\uac01\ud558\ub294 \uac83\uc774 \uc88b\ub2e4\uace0 \ud310\ub2e8\ud588\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \ucd1d\ube44\uc6a9 \ucc28\uc774\uac00 \ud06c\uc9c0 \uc54a\ub2e4\uba74 B \uc81c\ud488\uc744 \uc120\ud0dd\ud560 \uac83 \uac19\uc2b5\ub2c8\ub2e4.")
A.iDm=s(["\uad11\uace0","\ud544\uc694","24\uc2dc\uac04","\uc608\uc0b0","\ube44\uc2b7\ud55c \uc81c\ud488","\uae30\ub85d"],t.s)
A.chs=new B.c7("\ucda9\ub3d9\uad6c\ub9e4\ub97c \uc904\uc774\uae30 \uc704\ud55c \uc790\uc2e0\uc758 \ubc29\ubc95\uc744 \ub9d0\ud574 \ubcf4\uc138\uc694.",A.iDm,"\uc800\ub294 \uad11\uace0\ub97c \ubcf4\uace0 \uc0ac\uace0 \uc2f6\uc740 \ubb3c\uac74\uc774 \uc0dd\uaca8\ub3c4 \ubc14\ub85c \uacb0\uc81c\ud558\uc9c0 \uc54a\uc73c\ub824\uace0 \ud569\ub2c8\ub2e4. \uba3c\uc800 \uc815\ub9d0 \ud544\uc694\ud55c \uc81c\ud488\uc778\uc9c0 \uc0dd\uac01\ud558\uace0 \uc9d1\uc5d0 \ube44\uc2b7\ud55c \ubb3c\uac74\uc774 \uc788\ub294\uc9c0\ub3c4 \ud655\uc778\ud569\ub2c8\ub2e4. \uac00\uaca9\uc774 \uc870\uae08 \ub192\uc740 \uc81c\ud488\uc740 \ucd5c\uc18c \ud558\ub8e8 \uc815\ub3c4 \uad6c\ub9e4\ub97c \ubbf8\ub8e8\uace0 \ub2e4\uc74c \ub0a0\uc5d0\ub3c4 \ud544\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ub418\uba74 \ub2e4\uc2dc \uac80\ud1a0\ud569\ub2c8\ub2e4. \ub610\ud55c \uc774\ubc88 \ub2ec \uc608\uc0b0 \uc548\uc5d0\uc11c \uc0b4 \uc218 \uc788\ub294\uc9c0\ub3c4 \ud655\uc778\ud569\ub2c8\ub2e4. \uc774\ub807\uac8c \ud558\ub2e4 \ubcf4\ub2c8 \ud560\uc778 \ub54c\ubb38\uc5d0 \ud544\uc694\ud558\uc9c0 \uc54a\uc740 \ubb3c\uac74\uc744 \uc0ac\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc774 \uc904\uc5c8\uc2b5\ub2c8\ub2e4.")
A.iZ6=s(["\uc608\uc0b0","\ucd08\uacfc","\uc9c0\ucd9c \ub0b4\uc5ed","\uc6d0\uc778","\uc870\uc815","\ubaa9\ud45c"],t.s)
A.cgC=new B.c7("\uc774\ubc88 \ub2ec \uc608\uc0b0\uc744 \ucd08\uacfc\ud55c \uc774\uc720\uc640 \ub2e4\uc74c \ub2ec \uac1c\uc120 \uacc4\ud68d\uc744 \uc124\uba85\ud574 \ubcf4\uc138\uc694.",A.iZ6,"\uc774\ubc88 \ub2ec\uc5d0\ub294 \uc0dd\ud65c\ube44 \uc608\uc0b0\uc744 \uc57d 12\ub9cc \uc6d0 \ucd08\uacfc\ud588\uc2b5\ub2c8\ub2e4. \uc9c0\ucd9c \ub0b4\uc5ed\uc744 \ud655\uc778\ud574 \ubcf4\ub2c8 \ubc30\ub2ec \uc74c\uc2dd\uacfc \uc628\ub77c\uc778 \uc1fc\ud551 \ube44\uc6a9\uc774 \uc608\uc0c1\ubcf4\ub2e4 \ub9ce\uc774 \ub298\uc5c8\uc2b5\ub2c8\ub2e4. \ud070 \uae08\uc561\uc744 \ud55c \ubc88\uc5d0 \uc4f4 \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc \uc791\uc740 \uae08\uc561\uc744 \uc790\uc8fc \uacb0\uc81c\ud558\ub2e4 \ubcf4\ub2c8 \uc804\uccb4 \uc9c0\ucd9c\uc774 \ucee4\uc84c\uc2b5\ub2c8\ub2e4. \ub2e4\uc74c \ub2ec\uc5d0\ub294 \ubc30\ub2ec \uc74c\uc2dd \uc608\uc0b0\uc744 \ub530\ub85c \uc815\ud558\uace0 \uc628\ub77c\uc778 \uc1fc\ud551\uc740 \uad6c\ub9e4 \uc804\uc5d0 \ud558\ub8e8 \uc815\ub3c4 \uae30\ub2e4\ub9ac\ub294 \uaddc\uce59\uc744 \uc801\uc6a9\ud574 \ubcf4\ub824\uace0 \ud569\ub2c8\ub2e4. \ud55c \ub2ec \ud6c4 \uc2e4\uc81c\ub85c \ubcc0\ub3d9 \uc9c0\ucd9c\uc774 \uc5bc\ub9c8\ub098 \uc904\uc5c8\ub294\uc9c0 \ub2e4\uc2dc \ud655\uc778\ud558\uaca0\uc2b5\ub2c8\ub2e4.")
A.hd3=s([A.cgH,A.cgX,A.chs,A.cgC],t.uf)
A.icI=s(["\ud544\uc694 \uc5ec\ubd80\ub97c \uc4f0\uc138\uc694.","\uac00\uaca9 \ube44\uad50\ub97c \uc4f0\uc138\uc694.","\ud488\uc9c8\uacfc \ub0b4\uad6c\uc131\uc744 \uc4f0\uc138\uc694.","\ucd94\uac00 \ube44\uc6a9\uc744 \uc4f0\uc138\uc694.","\uad11\uace0\uc640 \ud6c4\uae30\ub97c \uc4f0\uc138\uc694.","V-\uae30\ubcf4\ub2e4\ub294\uc744 \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cux=new B.cN("\ud569\ub9ac\uc801\uc778 \uc18c\ube44\ub97c \uc704\ud574 \uace0\ub824\ud574\uc57c \ud560 \ub0b4\uc6a9\uc744 \uc368 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft nh\u1eefng \u0111i\u1ec1u c\u1ea7n c\xe2n nh\u1eafc \u0111\u1ec3 ti\xeau d\xf9ng h\u1ee3p l\xfd.",A.icI,"\ud569\ub9ac\uc801\uc778 \uc18c\ube44\ub97c \ud558\ub824\uba74 \uac00\uc7a5 \uba3c\uc800 \uadf8 \uc81c\ud488\uc774 \uc2e4\uc81c\ub85c \ud544\uc694\ud55c\uc9c0 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4. \uac00\uaca9\uc774 \uc2f8\uac70\ub098 \ud560\uc778\uc728\uc774 \ub192\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \uad6c\ub9e4\ud558\uae30\ubcf4\ub2e4\ub294 \uc5ec\ub7ec \ud310\ub9e4\ucc98\uc758 \uc2e4\uc81c \uacb0\uc81c \uae08\uc561\uc744 \ube44\uad50\ud574\uc57c \ud569\ub2c8\ub2e4. \uc624\ub798 \uc0ac\uc6a9\ud560 \uc81c\ud488\uc774\ub77c\uba74 \ud488\uc9c8, \ub0b4\uad6c\uc131\uacfc \uc720\uc9c0 \ube44\uc6a9\ub3c4 \ud568\uaed8 \uace0\ub824\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \ub610\ud55c \ubc30\uc1a1\ube44\ub098 \ucd94\uac00 \ubd80\ud488 \ube44\uc6a9\ucc98\ub7fc \uad6c\ub9e4 \ud6c4 \ubc1c\uc0dd\ud560 \uc218 \uc788\ub294 \ube44\uc6a9\ub3c4 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \uad11\uace0\uc640 \uc0ac\uc6a9 \ud6c4\uae30\ub294 \ucc38\uace0\ud560 \uc218 \uc788\uc9c0\ub9cc \ud55c \uac00\uc9c0 \uc815\ubcf4\ub9cc \ubbff\uae30\ubcf4\ub2e4 \uc5ec\ub7ec \uc790\ub8cc\ub97c \ube44\uad50\ud55c \ud6c4 \uc790\uc2e0\uc758 \ud544\uc694\uc640 \uc608\uc0b0\uc5d0 \ub9de\ub294\uc9c0 \ud310\ub2e8\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","\u0110\u1ec3 ti\xeau d\xf9ng h\u1ee3p l\xfd, tr\u01b0\u1edbc ti\xean \u0111i\u1ec1u quan tr\u1ecdng l\xe0 x\xe1c nh\u1eadn s\u1ea3n ph\u1ea9m \u0111\xf3 c\xf3 th\u1ef1c s\u1ef1 c\u1ea7n thi\u1ebft hay kh\xf4ng. Thay v\xec mua ch\u1ec9 v\xec gi\xe1 r\u1ebb ho\u1eb7c t\u1ef7 l\u1ec7 gi\u1ea3m gi\xe1 cao, c\u1ea7n so s\xe1nh s\u1ed1 ti\u1ec1n thanh to\xe1n th\u1ef1c t\u1ebf \u1edf nhi\u1ec1u n\u01a1i b\xe1n. N\u1ebfu l\xe0 s\u1ea3n ph\u1ea9m d\xf9ng l\xe2u, c\u1ea7n c\xe2n nh\u1eafc c\u1ea3 ch\u1ea5t l\u01b0\u1ee3ng, \u0111\u1ed9 b\u1ec1n v\xe0 chi ph\xed duy tr\xec. Ngo\xe0i ra c\u0169ng ph\u1ea3i ki\u1ec3m tra nh\u1eefng chi ph\xed c\xf3 th\u1ec3 ph\xe1t sinh sau mua nh\u01b0 ph\xed giao h\xe0ng ho\u1eb7c ph\u1ee5 ki\u1ec7n. Qu\u1ea3ng c\xe1o v\xe0 \u0111\xe1nh gi\xe1 ng\u01b0\u1eddi d\xf9ng c\xf3 th\u1ec3 \u0111\u01b0\u1ee3c tham kh\u1ea3o, nh\u01b0ng n\xean so s\xe1nh nhi\u1ec1u ngu\u1ed3n r\u1ed3i quy\u1ebft \u0111\u1ecbnh xem c\xf3 ph\xf9 h\u1ee3p nhu c\u1ea7u v\xe0 ng\xe2n s\xe1ch c\u1ee7a m\xecnh kh\xf4ng.")
A.ifU=s(["\ud604\uc7ac \uc2b5\uad00\uc744 \uc4f0\uc138\uc694.","\ubb38\uc81c\ub97c \uc4f0\uc138\uc694.","\uc9c0\ucd9c \uae30\ub85d\uc744 \uc4f0\uc138\uc694.","\uac1c\uc120 \ubc29\ubc95\uc744 \uc4f0\uc138\uc694.","\ud655\uc778 \uae30\uac04\uc744 \uc4f0\uc138\uc694.","V-\ub2e4 \ubcf4\ub2c8\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cuE=new B.cN("\uc790\uc2e0\uc758 \uc18c\ube44 \uc2b5\uad00\uc5d0\uc11c \uac1c\uc120\ud558\uace0 \uc2f6\uc740 \uc810\uc744 \uc368 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft \u0111i\u1ec3m b\u1ea1n mu\u1ed1n c\u1ea3i thi\u1ec7n trong th\xf3i quen ti\xeau d\xf9ng c\u1ee7a m\xecnh.",A.ifU,"\uc800\ub294 \ud070 \ubb3c\uac74\uc744 \uc790\uc8fc \uc0ac\ub294 \ud3b8\uc740 \uc544\ub2c8\uc9c0\ub9cc \uc791\uc740 \uae08\uc561\uc758 \uc628\ub77c\uc778 \uacb0\uc81c\ub97c \uc790\uc8fc \ud558\ub294 \uc2b5\uad00\uc774 \uc788\uc2b5\ub2c8\ub2e4. \ud55c \ubc88\uc5d0 \uc4f0\ub294 \uae08\uc561\uc774 \ud06c\uc9c0 \uc54a\ub2e4\uace0 \uc0dd\uac01\ud558\ub2e4 \ubcf4\ub2c8 \uc6d4\ub9d0\uc5d0 \ud655\uc778\ud558\uba74 \uc0dd\uac01\ubcf4\ub2e4 \uc9c0\ucd9c\uc774 \ub9ce\uc774 \ub298\uc5b4 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc55e\uc73c\ub85c \ud55c \ub2ec \ub3d9\uc548 \ubaa8\ub4e0 \ubcc0\ub3d9 \uc9c0\ucd9c\uc744 \ud56d\ubaa9\ubcc4\ub85c \uae30\ub85d\ud558\ub824\uace0 \ud569\ub2c8\ub2e4. \ud2b9\ud788 \uc628\ub77c\uc778 \uc1fc\ud551\uc740 \ubc14\ub85c \uacb0\uc81c\ud558\uc9c0 \uc54a\uace0 \ud558\ub8e8 \ub4a4\uc5d0\ub3c4 \ud544\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ub420 \ub54c\ub9cc \uad6c\ub9e4\ud560 \uacc4\ud68d\uc785\ub2c8\ub2e4. \ud55c \ub2ec \ud6c4 \uc9c0\ucd9c \ub0b4\uc5ed\uc744 \ub2e4\uc2dc \ud655\uc778\ud574\uc11c \uc2e4\uc81c\ub85c \ucda9\ub3d9\uad6c\ub9e4\uc640 \ubd88\ud544\uc694\ud55c \uc18c\ube44\uac00 \uc5bc\ub9c8\ub098 \uc904\uc5c8\ub294\uc9c0 \ube44\uad50\ud574 \ubcf4\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.","T\xf4i kh\xf4ng th\u01b0\u1eddng mua nh\u1eefng m\xf3n \u0111\u1ed3 l\u1edbn nh\u01b0ng c\xf3 th\xf3i quen thanh to\xe1n online c\xe1c kho\u1ea3n nh\u1ecf th\u01b0\u1eddng xuy\xean. V\xec ngh\u0129 m\u1ed7i l\u1ea7n kh\xf4ng t\u1ed1n nhi\u1ec1u n\xean \u0111\u1ebfn cu\u1ed1i th\xe1ng ki\u1ec3m tra th\xec chi ti\xeau t\u0103ng nhi\u1ec1u h\u01a1n t\u01b0\u1edfng t\u01b0\u1ee3ng. V\xec v\u1eady trong m\u1ed9t th\xe1ng t\u1edbi t\xf4i s\u1ebd ghi l\u1ea1i to\xe0n b\u1ed9 chi bi\u1ebfn \u0111\u1ed9ng theo t\u1eebng h\u1ea1ng m\u1ee5c. \u0110\u1eb7c bi\u1ec7t v\u1edbi mua s\u1eafm online, t\xf4i s\u1ebd kh\xf4ng thanh to\xe1n ngay m\xe0 ch\u1ec9 mua n\u1ebfu sau m\u1ed9t ng\xe0y v\u1eabn th\u1ea5y c\u1ea7n. Sau m\u1ed9t th\xe1ng t\xf4i mu\u1ed1n ki\u1ec3m tra l\u1ea1i l\u1ecbch s\u1eed chi ti\xeau v\xe0 so s\xe1nh xem mua b\u1ed1c \u0111\u1ed3ng c\xf9ng ti\xeau d\xf9ng kh\xf4ng c\u1ea7n thi\u1ebft \u0111\xe3 gi\u1ea3m bao nhi\xeau.")
A.i6O=s(["\uac00\uaca9\uc744 \uc4f0\uc138\uc694.","\uc0ac\uc6a9 \uae30\uac04\uc744 \uc4f0\uc138\uc694.","\uc131\ub2a5\uc744 \uc4f0\uc138\uc694.","\ub0b4\uad6c\uc131\uc744 \uc4f0\uc138\uc694.","\uc720\uc9c0 \ube44\uc6a9\uc744 \uc4f0\uc138\uc694.","V/A-(\uc73c)\u3134/\ub294 \ubc18\uba74\uc5d0\uc640 V/A-(\uc73c)\u3139\uc218\ub85d\uc744 \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cuh=new B.cN("\uc2fc \uc81c\ud488\uacfc \ube44\uc2fc \uc81c\ud488 \uc911 \ubb34\uc5c7\uc744 \uc120\ud0dd\ud560\uc9c0 \ud310\ub2e8\ud558\ub294 \uae30\uc900\uc744 \uc368 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft ti\xeau ch\xed \u0111\u1ec3 quy\u1ebft \u0111\u1ecbnh gi\u1eefa s\u1ea3n ph\u1ea9m r\u1ebb v\xe0 s\u1ea3n ph\u1ea9m \u0111\u1eaft.",A.i6O,"\uc81c\ud488\uc744 \uc120\ud0dd\ud560 \ub54c \ubb34\uc870\uac74 \uc2fc \uc81c\ud488\uc774\ub098 \ube44\uc2fc \uc81c\ud488\uc774 \ub354 \uc88b\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0\ub294 \uc54a\uc2b5\ub2c8\ub2e4. \uc2fc \uc81c\ud488\uc740 \ucc98\uc74c \ubd80\ub2f4\uc774 \uc801\uc740 \ubc18\uba74\uc5d0 \ub0b4\uad6c\uc131\uc774 \ub0ae\uac70\ub098 \ud544\uc694\ud55c \uae30\ub2a5\uc774 \ubd80\uc871\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubc18\ub300\ub85c \ube44\uc2fc \uc81c\ud488\ub3c4 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 \uae30\ub2a5\uc774 \ub108\ubb34 \ub9ce\ub2e4\uba74 \uc800\uc5d0\uac8c\ub294 \ud569\ub9ac\uc801\uc778 \uc120\ud0dd\uc774 \uc544\ub2d0 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc624\ub798 \uc0ac\uc6a9\ud560\uc218\ub85d \ucc98\uc74c \uad6c\ub9e4 \uac00\uaca9\ubcf4\ub2e4 \ub0b4\uad6c\uc131, \uc720\uc9c0 \ube44\uc6a9\uacfc \uc2e4\uc81c \ud544\uc694\ud55c \uc131\ub2a5\uc774 \ub354 \uc911\uc694\ud574\uc9d1\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc790\uc2e0\uc774 \uc5bc\ub9c8\ub098 \uc790\uc8fc, \uc5bc\ub9c8\ub098 \uc624\ub798 \uc0ac\uc6a9\ud560\uc9c0\ub97c \uba3c\uc800 \uc0dd\uac01\ud55c \ud6c4 \ucd1d\ube44\uc6a9\uacfc \uae30\ub2a5\uc744 \ube44\uad50\ud574\uc11c \uacb0\uc815\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","Khi ch\u1ecdn s\u1ea3n ph\u1ea9m, t\xf4i kh\xf4ng ngh\u0129 c\u1ee9 s\u1ea3n ph\u1ea9m r\u1ebb ho\u1eb7c \u0111\u1eaft h\u01a1n l\xe0 t\u1ed1t h\u01a1n. S\u1ea3n ph\u1ea9m r\u1ebb c\xf3 g\xe1nh n\u1eb7ng ban \u0111\u1ea7u th\u1ea5p nh\u01b0ng c\xf3 th\u1ec3 \u0111\u1ed9 b\u1ec1n th\u1ea5p ho\u1eb7c thi\u1ebfu t\xednh n\u0103ng c\u1ea7n thi\u1ebft. Ng\u01b0\u1ee3c l\u1ea1i s\u1ea3n ph\u1ea9m \u0111\u1eaft n\u1ebfu c\xf3 qu\xe1 nhi\u1ec1u t\xednh n\u0103ng m\xecnh kh\xf4ng s\u1eed d\u1ee5ng th\xec c\u0169ng c\xf3 th\u1ec3 kh\xf4ng ph\u1ea3i l\u1ef1a ch\u1ecdn h\u1ee3p l\xfd. C\xe0ng s\u1eed d\u1ee5ng l\xe2u th\xec \u0111\u1ed9 b\u1ec1n, chi ph\xed duy tr\xec v\xe0 hi\u1ec7u n\u0103ng th\u1ef1c s\u1ef1 c\u1ea7n c\xe0ng quan tr\u1ecdng h\u01a1n gi\xe1 mua ban \u0111\u1ea7u. V\xec v\u1eady n\xean ngh\u0129 tr\u01b0\u1edbc m\xecnh s\u1ebd d\xf9ng th\u01b0\u1eddng xuy\xean v\xe0 l\xe2u \u0111\u1ebfn m\u1ee9c n\xe0o r\u1ed3i so s\xe1nh t\u1ed5ng chi ph\xed c\xf9ng ch\u1ee9c n\u0103ng \u0111\u1ec3 quy\u1ebft \u0111\u1ecbnh.")
A.hmd=s([A.cux,A.cuE,A.cuh],t.l5)
