A.cbz=new B.a7("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\uc218\uc9c4 \uc528\ub294 \u201c\uacc4\uc88c \uc0ac\uc6a9\uc774 \uace7 \uc81c\ud55c\ub429\ub2c8\ub2e4. \uc9c0\uae08 \ub9c1\ud06c\ub97c \ub20c\ub7ec \ubcf8\uc778 \uc778\uc99d\uc744 \ud558\uc138\uc694.\u201d\ub77c\ub294 \ubb38\uc790\ub97c \ubc1b\uc558\uc2b5\ub2c8\ub2e4. \ubb38\uc790\uc5d0\ub294 \ud3c9\uc18c \uc774\uc6a9\ud558\ub294 \uae08\uc735 \uae30\uad00\uc758 \uc774\ub984\uc774 \uc801\ud600 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \uc218\uc9c4 \uc528\ub294 \ub9c1\ud06c\ub97c \ub204\ub974\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. \ub300\uc2e0 \ud3c9\uc18c \uc0ac\uc6a9\ud558\ub358 \uacf5\uc2dd \uc571\uc744 \uc9c1\uc811 \uc5f4\uc5b4 \uacf5\uc9c0 \uc0ac\ud56d\uc744 \ud655\uc778\ud588\uace0 \uc774\uc0c1\uc774 \uc5c6\ub2e4\ub294 \uac83\uc744 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.",A.iYQ,2,"\uc77d\uae30")
A.fJ9=s(["\uba54\uc2dc\uc9c0\uc5d0 \uc801\ud78c \uacc4\uc88c\ub85c \uc989\uc2dc \uc1a1\uae08\ud55c\ub2e4.","\uae30\uc874\uc5d0 \uc54c\uace0 \uc788\ub358 \uc5f0\ub77d\ucc98\ub97c \ud1b5\ud574 \ubcc0\uacbd \uc0ac\uc2e4\uacfc \uacc4\uc88c \uc815\ubcf4\ub97c \ubcc4\ub3c4\ub85c \ud655\uc778\ud55c\ub2e4.","\uc608\uae08\uc8fc\uac00 \ub2ec\ub77c\ub3c4 \uadf8\ub0e5 \ubcf4\ub0b8\ub2e4.","\uacc4\uc88c \ubc88\ud638\ub97c \ub2e4\ub978 \uc5c5\uccb4\uc5d0\ub3c4 \uacf5\uc720\ud55c\ub2e4."],t.s)
A.cf4=new B.a7("\ud68c\uc0ac \uac70\ub798\ucc98\uc5d0\uc11c \uac11\uc790\uae30 \u201c\uacc4\uc88c\uac00 \ubc14\ub00c\uc5c8\uc73c\ub2c8 \uc0c8 \uacc4\uc88c\ub85c \ubcf4\ub0b4 \ub2ec\ub77c\u201d\ub294 \uba54\uc2dc\uc9c0\ub97c \ubcf4\ub0c8\uc2b5\ub2c8\ub2e4. \uac00\uc7a5 \uc801\uc808\ud55c \ud589\ub3d9\uc740?",A.fJ9,1,"\uc2e4\uc81c \uc0c1\ud669")
A.hJn=s(["\uc911\uc694\ud55c \uac70\ub798 \uc804 \uae08\uc561\uacfc \uc0c1\ub300\ubc29 \uc815\ubcf4\ub97c \ud655\uc778\ud55c\ub2e4.","\uac70\ub798 \ub0b4\uc5ed\uc744 \uc8fc\uae30\uc801\uc73c\ub85c \ud655\uc778\ud55c\ub2e4.","\ucd9c\ucc98\uac00 \ubd88\ubd84\uba85\ud55c \uc694\uccad\uc740 \ucd94\uac00\ub85c \ud655\uc778\ud55c\ub2e4.","\ud55c \ubc88 \ubbff\uc740 \uc0c1\ub300\ubc29\uc774\uba74 \uacc4\uc88c \uc815\ubcf4\uac00 \ubc14\ub00c\uc5b4\ub3c4 \ud655\uc778 \uc5c6\uc774 \uacc4\uc18d \uc1a1\uae08\ud55c\ub2e4."],t.s)
A.cdi=new B.a7("\uae08\uc735 \uac70\ub798\ub97c \uc548\uc804\ud558\uac8c \uad00\ub9ac\ud558\ub294 \ud0dc\ub3c4\ub85c \uac00\uc7a5 \uc801\uc808\ud558\uc9c0 \uc54a\uc740 \uac83\uc740?",A.hJn,3,"\uc885\ud569")
A.hmU=s([A.cdO,A.cc7,A.cbO,A.cbC,A.ccQ,A.cea,A.cbe,A.cbv,A.cd8,A.ce5,A.ccZ,A.cf7,A.cbz,A.cf4,A.cdi],t.VX)
A.hd0=s(["\uac70\ub798 \ub0b4\uc5ed","\ub0a0\uc9dc","\uae08\uc561","\ucd9c\uae08","\ud655\uc778","\ubb38\uc758"],t.s)
A.cgJ=new B.c7("\uac70\ub798 \ub0b4\uc5ed\uc5d0\uc11c \ubaa8\ub974\ub294 \ucd9c\uae08\uc744 \ubc1c\uacac\ud55c \uc0c1\ud669\uc744 \uc124\uba85\ud574 \ubcf4\uc138\uc694.",A.hd0,"\uc624\ub298 \uacc4\uc88c \uac70\ub798 \ub0b4\uc5ed\uc744 \ud655\uc778\ud558\ub2e4\uac00 \uc81c\uac00 \uae30\uc5b5\ud558\uc9c0 \ubabb\ud558\ub294 \ucd9c\uae08 \ub0b4\uc5ed\uc744 \ud558\ub098 \ubc1c\uacac\ud588\uc2b5\ub2c8\ub2e4. \uac70\ub798 \uc2dc\uac04\uc740 \uc5b4\uc81c \uc624\ud6c4 3\uc2dc 20\ubd84 \uc815\ub3c4\uc774\uace0 \uae08\uc561\uc740 7\ub9cc \uc6d0\uc785\ub2c8\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc790\ub3d9\uc774\uccb4\uc778\uc9c0 \ud655\uc778\ud588\uc9c0\ub9cc \uc81c\uac00 \uc54c\uace0 \uc788\ub294 \uc815\uae30 \uacb0\uc81c\uc640 \uc77c\uce58\ud558\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \uac70\ub798\uba85\uc744 \ub2e4\uc2dc \ud655\uc778\ud558\uace0 \uad00\ub828 \uc815\ubcf4\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4. \uc81c\uac00 \uc9c1\uc811 \ud55c \uac70\ub798\uc778\uc9c0 \ud655\uc2e4\ud558\uc9c0 \uc54a\uc544\uc11c \uacf5\uc2dd \uace0\uac1d \uc9c0\uc6d0 \uacbd\ub85c\ub97c \ud1b5\ud574 \ud655\uc778 \uc808\ucc28\ub97c \ubb38\uc758\ud558\ub824\uace0 \ud569\ub2c8\ub2e4.")
A.i3l=s(["\ubaa8\ub974\ub294 \ubc88\ud638","\uae09\ud55c \uc694\uccad","\uc1a1\uae08","\uc9c1\uc811 \ud655\uc778","\uae30\uc874 \uc5f0\ub77d\ucc98","\uc911\ub2e8"],t.s)
A.chG=new B.c7("\uac00\uc871\uc744 \uc0ac\uce6d\ud574\uc11c \uc1a1\uae08\uc744 \uc694\uad6c\ud558\ub294 \ubb38\uc790\ub97c \ubc1b\uc558\uc744 \ub54c \uc5b4\ub5bb\uac8c \ub300\uc751\ud560\uc9c0 \ub9d0\ud574 \ubcf4\uc138\uc694.",A.i3l,"\ubaa8\ub974\ub294 \ubc88\ud638\uc5d0\uc11c \uac00\uc871\uc774\ub77c\uace0 \ud558\uba74\uc11c \uae09\ud558\uac8c \ub3c8\uc744 \ubcf4\ub0b4 \ub2ec\ub77c\ub294 \ubb38\uc790\ub97c \ubc1b\uc73c\uba74 \ubc14\ub85c \uc1a1\uae08\ud558\uc9c0 \uc54a\uaca0\uc2b5\ub2c8\ub2e4. \uc0c1\ub300\ubc29\uc774 \uc81c \uac00\uc871\uc758 \uc774\ub984\uc774\ub098 \uc77c\ubd80 \uc815\ubcf4\ub97c \uc54c\uace0 \uc788\ub2e4\uace0 \ud574\uc11c \ubc18\ub4dc\uc2dc \ubcf8\uc778\uc774\ub77c\uace0 \ubbff\uc744 \uc218\ub294 \uc5c6\uc2b5\ub2c8\ub2e4. \ubb38\uc790\uc5d0 \ub2f5\ud558\uba74\uc11c \ud655\uc778\ud558\uae30\ubcf4\ub2e4\ub294 \uc81c\uac00 \uc6d0\ub798 \uc54c\uace0 \uc788\ub358 \uc804\ud654\ubc88\ud638\ub85c \uc9c1\uc811 \uc5f0\ub77d\ud574\uc11c \uc0ac\uc2e4\uc744 \ud655\uc778\ud558\uaca0\uc2b5\ub2c8\ub2e4. \ud655\uc778\ub418\uae30 \uc804\uae4c\uc9c0\ub294 \uc1a1\uae08\uc774\ub098 \uac1c\uc778\uc815\ubcf4 \uc81c\uacf5\uc744 \ubaa8\ub450 \uc911\ub2e8\ud558\uaca0\uc2b5\ub2c8\ub2e4.")
A.h3n=s(["\ubc1c\uc2e0\uc790","\ub9c1\ud06c","\uacf5\uc2dd \uc571","\uac1c\uc778\uc815\ubcf4","\ud655\uc778"],t.s)
A.chy=new B.c7("\uc758\uc2ec\uc2a4\ub7ec\uc6b4 \uae08\uc735 \ubb38\uc790\ub97c \ubc1b\uc558\uc744 \ub54c \ub300\uc751 \ubc29\ubc95\uc744 \uc124\uba85\ud574 \ubcf4\uc138\uc694.",A.h3n,"\uae08\uc735 \uae30\uad00 \uc774\ub984\uc774 \uc801\ud600 \uc788\ub354\ub77c\ub3c4 \ubb38\uc790 \ub0b4\uc6a9\uc774 \uc774\uc0c1\ud558\uac70\ub098 \ub9c1\ud06c\uac00 \ud3ec\ud568\ub418\uc5b4 \uc788\uc73c\uba74 \ubc14\ub85c \ub204\ub974\uc9c0 \uc54a\uaca0\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \ubc1c\uc2e0\uc790\uac00 \uc815\ud655\ud55c\uc9c0 \ud655\uc778\ud558\uace0 \ubb38\uc790\uc5d0 \uc788\ub294 \ub9c1\ud06c\ub97c \uc0ac\uc6a9\ud558\ub294 \ub300\uc2e0 \ud3c9\uc18c \uc774\uc6a9\ud558\ub294 \uacf5\uc2dd \uc571\uc744 \uc9c1\uc811 \uc5f4\uc5b4 \uac19\uc740 \uc548\ub0b4\uac00 \uc788\ub294\uc9c0 \ud655\uc778\ud558\uaca0\uc2b5\ub2c8\ub2e4. \ud544\uc694\ud55c \uacbd\uc6b0\uc5d0\ub294 \uc81c\uac00 \uc54c\uace0 \uc788\ub294 \uacf5\uc2dd \uc5f0\ub77d\ucc98\ub97c \ud1b5\ud574 \ubb38\uc758\ud558\uaca0\uc2b5\ub2c8\ub2e4. \ucd9c\ucc98\uac00 \ud655\uc2e4\ud558\uc9c0 \uc54a\uc740 \uacf3\uc5d0\uc11c\ub294 \ube44\ubc00\ubc88\ud638\ub098 \uc778\uc99d \ubc88\ud638 \uac19\uc740 \uc911\uc694\ud55c \uc815\ubcf4\ub97c \uc785\ub825\ud558\uc9c0 \uc54a\uaca0\uc2b5\ub2c8\ub2e4.")
A.hSX=s(["\uac70\ub798 \ub0b4\uc5ed","\ube44\ubc00\ubc88\ud638","\uacf5\uc2dd \uacbd\ub85c","\uc1a1\uae08 \uc804 \ud655\uc778","\uae30\ub85d","\uc758\uc2ec \uc694\uccad"],t.s)
A.cgZ=new B.c7("\uc790\uc2e0\uc774 \uc2e4\ucc9c\ud560 \uc218 \uc788\ub294 \uae08\uc735 \uc704\ud5d8 \uad00\ub9ac \uc2b5\uad00\uc744 \ub9d0\ud574 \ubcf4\uc138\uc694.",A.hSX,"\uc800\ub294 \uae08\uc735 \uc704\ud5d8\uc744 \uc904\uc774\uae30 \uc704\ud574 \uba87 \uac00\uc9c0 \uc2b5\uad00\uc744 \ub9cc\ub4e4\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \uac70\ub798 \ub0b4\uc5ed\uc744 \uc815\uae30\uc801\uc73c\ub85c \ud655\uc778\ud574\uc11c \ubaa8\ub974\ub294 \ucd9c\uae08\uc774\ub098 \uc774\uc0c1 \uac70\ub798\uac00 \uc5c6\ub294\uc9c0 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uc1a1\uae08\ud558\uae30 \uc804\uc5d0\ub294 \uacc4\uc88c \ubc88\ud638, \uc608\uae08\uc8fc\uc640 \uae08\uc561\uc744 \ub2e4\uc2dc \ud655\uc778\ud558\uaca0\uc2b5\ub2c8\ub2e4. \ube44\ubc00\ubc88\ud638\uc640 \uc778\uc99d \ubc88\ud638 \uac19\uc740 \uc911\uc694\ud55c \uc815\ubcf4\ub294 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ud568\ubd80\ub85c \uc54c\ub824 \uc8fc\uc9c0 \uc54a\uaca0\uc2b5\ub2c8\ub2e4. \ub610\ud55c \ubb38\uc790\ub098 \uc804\ud654\ub85c \uae09\ud55c \uc694\uccad\uc744 \ubc1b\uc558\uc744 \ub54c\ub294 \ubc14\ub85c \ud589\ub3d9\ud558\uc9c0 \uc54a\uace0 \uacf5\uc2dd \uacbd\ub85c\ub098 \uae30\uc874 \uc5f0\ub77d\ucc98\ub97c \uc774\uc6a9\ud574 \ub2e4\uc2dc \ud655\uc778\ud558\uaca0\uc2b5\ub2c8\ub2e4. \ubb38\uc81c\uac00 \uc0dd\uae30\uba74 \ub098\uc911\uc5d0 \ud655\uc778\ud560 \uc218 \uc788\ub3c4\ub85d \uc2dc\uac04\uacfc \uac70\ub798 \ub0b4\uc6a9\uc744 \uae30\ub85d\ud558\ub294 \uc2b5\uad00\ub3c4 \ub9cc\ub4e4\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.")
A.hge=s([A.cgJ,A.chG,A.chy,A.cgZ],t.uf)
A.ieg=s(["\uac70\ub798 \uc0c1\ub300\ub97c \uc4f0\uc138\uc694.","\uacc4\uc88c \ubc88\ud638\uc640 \uc608\uae08\uc8fc\ub97c \uc4f0\uc138\uc694.","\uae08\uc561\uc744 \uc4f0\uc138\uc694.","\uacf5\uc2dd \uacbd\ub85c \ud655\uc778\uc744 \uc4f0\uc138\uc694.","\uac1c\uc778\uc815\ubcf4 \ubcf4\ud638\ub97c \uc4f0\uc138\uc694.","V-\uae30 \uc804\uc5d0\uc640 V-\ub294\uc9c0 \ud655\uc778\ud558\ub2e4\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cuf=new B.cN("\uc548\uc804\ud55c \uae08\uc735 \uac70\ub798\ub97c \uc704\ud574 \ud655\uc778\ud574\uc57c \ud560 \ub0b4\uc6a9\uc744 \uc368 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft nh\u1eefng n\u1ed9i dung c\u1ea7n ki\u1ec3m tra \u0111\u1ec3 th\u1ef1c hi\u1ec7n giao d\u1ecbch t\xe0i ch\xednh an to\xe0n.",A.ieg,"\uc548\uc804\ud558\uac8c \uae08\uc735 \uac70\ub798\ub97c \ud558\ub824\uba74 \uc1a1\uae08\uc774\ub098 \uacb0\uc81c\ub97c \ud558\uae30 \uc804\uc5d0 \uac70\ub798 \uc815\ubcf4\ub97c \ub2e4\uc2dc \ud655\uc778\ud558\ub294 \uc2b5\uad00\uc774 \ud544\uc694\ud569\ub2c8\ub2e4. \uba3c\uc800 \uacc4\uc88c \ubc88\ud638\uc640 \uc608\uae08\uc8fc\uac00 \ub9de\ub294\uc9c0 \ud655\uc778\ud558\uace0 \uae08\uc561\ub3c4 \ud55c \ubc88 \ub354 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \ucc98\uc74c \uac70\ub798\ud558\ub294 \uc0c1\ub300\uc774\uac70\ub098 \uac11\uc790\uae30 \uacc4\uc88c\uac00 \ubcc0\uacbd\ub410\ub2e4\ub294 \uc548\ub0b4\ub97c \ubc1b\uc558\ub2e4\uba74 \uae30\uc874\uc5d0 \uc54c\uace0 \uc788\ub358 \uc5f0\ub77d \ubc29\ubc95\uc744 \ud1b5\ud574 \ubcc0\uacbd \uc0ac\uc2e4\uc744 \ubcc4\ub3c4\ub85c \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \ubb38\uc790\ub098 \uc774\uba54\uc77c\uc5d0 \ud3ec\ud568\ub41c \ub9c1\ud06c\ub97c \ubc14\ub85c \uc0ac\uc6a9\ud558\uae30\ubcf4\ub2e4 \uacf5\uc2dd \uc571\uc774\ub098 \uacf5\uc2dd \uc0ac\uc774\ud2b8\ub97c \uc9c1\uc811 \uc774\uc6a9\ud558\ub294 \uac83\uc774 \uc548\uc804\ud569\ub2c8\ub2e4. \ub610\ud55c \ube44\ubc00\ubc88\ud638\uc640 \uc778\uc99d \ubc88\ud638 \uac19\uc740 \uc911\uc694\ud55c \uac1c\uc778\uc815\ubcf4\ub294 \ucd9c\ucc98\uac00 \ud655\uc2e4\ud558\uc9c0 \uc54a\uc740 \uc694\uccad\uc5d0 \uc81c\uacf5\ud558\uc9c0 \uc54a\ub3c4\ub85d \uc8fc\uc758\ud574\uc57c \ud569\ub2c8\ub2e4.","\u0110\u1ec3 th\u1ef1c hi\u1ec7n giao d\u1ecbch t\xe0i ch\xednh an to\xe0n, c\u1ea7n t\u1ea1o th\xf3i quen ki\u1ec3m tra l\u1ea1i th\xf4ng tin tr\u01b0\u1edbc khi chuy\u1ec3n ho\u1eb7c thanh to\xe1n. Tr\u01b0\u1edbc ti\xean n\xean x\xe1c nh\u1eadn s\u1ed1 t\xe0i kho\u1ea3n v\xe0 t\xean ch\u1ee7 t\xe0i kho\u1ea3n c\xf3 \u0111\xfang kh\xf4ng, \u0111\u1ed3ng th\u1eddi ki\u1ec3m tra l\u1ea1i s\u1ed1 ti\u1ec1n. N\u1ebfu l\xe0 b\xean giao d\u1ecbch l\u1ea7n \u0111\u1ea7u ho\u1eb7c nh\u1eadn th\xf4ng b\xe1o t\xe0i kho\u1ea3n \u0111\u1ed9t ng\u1ed9t thay \u0111\u1ed5i, c\u1ea7n x\xe1c minh ri\xeang vi\u1ec7c thay \u0111\u1ed5i th\xf4ng qua k\xeanh li\xean h\u1ec7 m\xecnh \u0111\xe3 bi\u1ebft t\u1eeb tr\u01b0\u1edbc. Thay v\xec s\u1eed d\u1ee5ng ngay link trong tin nh\u1eafn ho\u1eb7c email, s\u1eed d\u1ee5ng tr\u1ef1c ti\u1ebfp \u1ee9ng d\u1ee5ng ho\u1eb7c trang ch\xednh th\u1ee9c s\u1ebd an to\xe0n h\u01a1n. Ngo\xe0i ra c\u1ea7n ch\xfa \xfd kh\xf4ng cung c\u1ea5p nh\u1eefng th\xf4ng tin quan tr\u1ecdng nh\u01b0 m\u1eadt kh\u1ea9u v\xe0 m\xe3 x\xe1c th\u1ef1c cho y\xeau c\u1ea7u c\xf3 ngu\u1ed3n kh\xf4ng r\xf5.")
A.hhb=s(["\uae09\ud55c \uc694\uccad\uc744 \uc4f0\uc138\uc694.","\uc0ac\uce6d\uc744 \uc4f0\uc138\uc694.","\uc758\uc2ec \ub9c1\ud06c\ub97c \uc4f0\uc138\uc694.","\uacf5\uc2dd \uc5f0\ub77d\ucc98\ub97c \uc4f0\uc138\uc694.","\uac1c\uc778\uc815\ubcf4\ub97c \uc4f0\uc138\uc694.","V/A-(\uc73c)\u3139\uc218\ub85d\uacfc V-\ub294 \ub300\uc2e0\uc5d0\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cuP=new B.cN("\uae08\uc735 \uc0ac\uae30\ub97c \uc608\ubc29\ud558\uae30 \uc704\ud55c \ubc29\ubc95\uc744 \uc368 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft nh\u1eefng c\xe1ch ph\xf2ng ng\u1eeba l\u1eeba \u0111\u1ea3o t\xe0i ch\xednh.",A.hhb,"\uae08\uc735 \uc0ac\uae30\ub97c \uc608\ubc29\ud558\ub824\uba74 \uc0c1\ub300\ubc29\uc774 \uae09\ud558\uac8c \ud589\ub3d9\uc744 \uc694\uad6c\ud560\uc218\ub85d \ub354 \ucc28\ubd84\ud558\uac8c \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4. \uac00\uc871\uc774\ub098 \uae08\uc735 \uae30\uad00\uc744 \uc0ac\uce6d\ud558\uba74\uc11c \ub3c8\uc774\ub098 \uac1c\uc778\uc815\ubcf4\ub97c \uc694\uad6c\ud558\ub294 \uacbd\uc6b0\uac00 \uc788\uc744 \uc218 \uc788\uae30 \ub54c\ubb38\uc5d0 \uc0c1\ub300\ubc29\uc774 \uc77c\ubd80 \uac1c\uc778\uc815\ubcf4\ub97c \uc54c\uace0 \uc788\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \ubbff\uc5b4\uc11c\ub294 \uc548 \ub429\ub2c8\ub2e4. \ubb38\uc790\uc5d0 \ud3ec\ud568\ub41c \ub9c1\ud06c\ub97c \ubc14\ub85c \ub204\ub974\ub294 \ub300\uc2e0\uc5d0 \uc790\uc2e0\uc774 \ud3c9\uc18c \uc0ac\uc6a9\ud558\ub294 \uacf5\uc2dd \uc571\uc744 \uc9c1\uc811 \uc5f4\uc5b4 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \uc1a1\uae08 \uc694\uccad\uc774 \uac00\uc871\uc774\ub098 \uc9c0\uc778\uc5d0\uac8c\uc11c \uc628 \uac83\ucc98\ub7fc \ubcf4\uc774\ub354\ub77c\ub3c4 \uae30\uc874\uc5d0 \uc54c\uace0 \uc788\ub294 \uc5f0\ub77d\ucc98\ub85c \uc9c1\uc811 \ub2e4\uc2dc \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \ube44\ubc00\ubc88\ud638, \uc778\uc99d \ubc88\ud638\uc640 \uac19\uc740 \uc911\uc694\ud55c \uc815\ubcf4\ub294 \uc694\uccad\uc758 \ucd9c\ucc98\uc640 \ubaa9\uc801\uc744 \ucda9\ubd84\ud788 \ud655\uc778\ud558\uae30 \uc804\uc5d0\ub294 \uc81c\uacf5\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","\u0110\u1ec3 ph\xf2ng l\u1eeba \u0111\u1ea3o t\xe0i ch\xednh, \u0111\u1ed1i ph\u01b0\u01a1ng c\xe0ng y\xeau c\u1ea7u h\xe0nh \u0111\u1ed9ng g\u1ea5p th\xec c\xe0ng quan tr\u1ecdng ph\u1ea3i b\xecnh t\u0129nh x\xe1c minh. C\xf3 th\u1ec3 c\xf3 tr\u01b0\u1eddng h\u1ee3p m\u1ea1o danh ng\u01b0\u1eddi th\xe2n ho\u1eb7c t\u1ed5 ch\u1ee9c t\xe0i ch\xednh \u0111\u1ec3 y\xeau c\u1ea7u ti\u1ec1n ho\u1eb7c th\xf4ng tin c\xe1 nh\xe2n, v\xec v\u1eady kh\xf4ng n\xean tin ch\u1ec9 v\xec \u0111\u1ed1i ph\u01b0\u01a1ng bi\u1ebft m\u1ed9t ph\u1ea7n th\xf4ng tin c\u1ee7a m\xecnh. Thay v\xec nh\u1ea5n ngay \u0111\u01b0\u1eddng link trong tin nh\u1eafn, n\xean t\u1ef1 m\u1edf \u1ee9ng d\u1ee5ng ch\xednh th\u1ee9c m\xecnh v\u1eabn d\xf9ng \u0111\u1ec3 ki\u1ec3m tra. D\xf9 y\xeau c\u1ea7u chuy\u1ec3n ti\u1ec1n tr\xf4ng nh\u01b0 \u0111\u1ebfn t\u1eeb ng\u01b0\u1eddi th\xe2n ho\u1eb7c ng\u01b0\u1eddi quen, v\u1eabn c\u1ea7n x\xe1c minh l\u1ea1i qua k\xeanh li\xean h\u1ec7 \u0111\xe3 bi\u1ebft t\u1eeb tr\u01b0\u1edbc. Nh\u1eefng th\xf4ng tin quan tr\u1ecdng nh\u01b0 m\u1eadt kh\u1ea9u v\xe0 m\xe3 x\xe1c th\u1ef1c kh\xf4ng n\xean \u0111\u01b0\u1ee3c cung c\u1ea5p tr\u01b0\u1edbc khi x\xe1c minh \u0111\u1ea7y \u0111\u1ee7 ngu\u1ed3n v\xe0 m\u1ee5c \u0111\xedch y\xeau c\u1ea7u.")
A.hVP=s(["\uac70\ub798 \uc2dc\uac04\uacfc \uae08\uc561\uc744 \uc4f0\uc138\uc694.","\uac70\ub798 \ub0b4\uc5ed \ud655\uc778\uc744 \uc4f0\uc138\uc694.","\ubcf8\uc778\uc774 \ud55c \uac70\ub798\uc778\uc9c0 \ud655\uc778\ud558\uc138\uc694.","\ucd94\uac00 \ud589\ub3d9 \uc911\ub2e8\uc744 \uc4f0\uc138\uc694.","\uacf5\uc2dd \uacbd\ub85c \ubb38\uc758\ub97c \uc4f0\uc138\uc694.","\uae30\ub85d \ubcf4\uad00\uc744 \uc4f0\uc138\uc694.","V-(\uc73c)\u3139 \uac00\ub2a5\uc131\uc774 \uc788\ub2e4\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cul=new B.cN("\uc774\uc0c1 \uac70\ub798\ub97c \ubc1c\uacac\ud588\uc744 \ub54c\uc758 \ub300\uc751 \uacfc\uc815\uc744 \uc368 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft qu\xe1 tr\xecnh x\u1eed l\xfd khi ph\xe1t hi\u1ec7n giao d\u1ecbch b\u1ea5t th\u01b0\u1eddng.",A.hVP,"\uac70\ub798 \ub0b4\uc5ed\uc5d0\uc11c \uae30\uc5b5\ud558\uc9c0 \ubabb\ud558\ub294 \ucd9c\uae08\uc744 \ubc1c\uacac\ud558\uba74 \uba3c\uc800 \uac70\ub798 \uc2dc\uac04, \uae08\uc561\uacfc \uac70\ub798\uba85\uc744 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \uc790\ub3d9\uc774\uccb4\ub098 \uc774\uc804\uc5d0 \uc2e0\uccad\ud55c \uc11c\ube44\uc2a4 \ub54c\ubb38\uc5d0 \ucd9c\uae08\ub41c \uac83\uc778\uc9c0\ub3c4 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub798\ub3c4 \ubcf8\uc778\uc774 \ud558\uc9c0 \uc54a\uc740 \uac70\ub798\uc77c \uac00\ub2a5\uc131\uc774 \uc788\ub2e4\uba74 \uad00\ub828 \uc815\ubcf4\ub97c \uc815\ud655\ud558\uac8c \uae30\ub85d\ud558\uace0 \ucd94\uac00\ub85c \uc758\uc2ec\uc2a4\ub7ec\uc6b4 \ub9c1\ud06c\ub97c \ub204\ub974\uac70\ub098 \uac1c\uc778\uc815\ubcf4\ub97c \uc785\ub825\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \uadf8\ub2e4\uc74c \uc790\uc2e0\uc774 \uc54c\uace0 \uc788\ub294 \uacf5\uc2dd \uc571\uc774\ub098 \uacf5\uc2dd \uc5f0\ub77d\ucc98\ub97c \ud1b5\ud574 \ud574\ub2f9 \uac70\ub798\ub97c \uc5b4\ub5bb\uac8c \ud655\uc778\ud574\uc57c \ud558\ub294\uc9c0 \ubb38\uc758\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubb38\uc81c \uc0c1\ud669\uc5d0\uc11c\ub294 \ucd94\uce21\uc73c\ub85c \uacb0\ub860\uc744 \ub0b4\ub9ac\uae30\ubcf4\ub2e4 \ud655\uc778\ud55c \uc0ac\uc2e4\uacfc \uac70\ub798 \uae30\ub85d\uc744 \ub0a8\uaca8 \ub450\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","N\u1ebfu ph\xe1t hi\u1ec7n kho\u1ea3n ti\u1ec1n ra m\xecnh kh\xf4ng nh\u1edb trong l\u1ecbch s\u1eed giao d\u1ecbch, tr\u01b0\u1edbc ti\xean c\u1ea7n ki\u1ec3m tra th\u1eddi gian, s\u1ed1 ti\u1ec1n v\xe0 t\xean giao d\u1ecbch. C\u0169ng c\u1ea7n ki\u1ec3m tra xem c\xf3 ph\u1ea3i kho\u1ea3n t\u1ef1 \u0111\u1ed9ng ho\u1eb7c d\u1ecbch v\u1ee5 \u0111\xe3 \u0111\u0103ng k\xfd tr\u01b0\u1edbc \u0111\xf3 hay kh\xf4ng. N\u1ebfu v\u1eabn c\xf3 kh\u1ea3 n\u0103ng \u0111\xe2y l\xe0 giao d\u1ecbch m\xecnh kh\xf4ng th\u1ef1c hi\u1ec7n, n\xean ghi l\u1ea1i ch\xednh x\xe1c th\xf4ng tin li\xean quan v\xe0 kh\xf4ng ti\u1ebfp t\u1ee5c nh\u1ea5n link \u0111\xe1ng ng\u1edd ho\u1eb7c nh\u1eadp th\xf4ng tin c\xe1 nh\xe2n. Sau \u0111\xf3 c\xf3 th\u1ec3 h\u1ecfi qua \u1ee9ng d\u1ee5ng ho\u1eb7c k\xeanh li\xean h\u1ec7 ch\xednh th\u1ee9c m\xecnh bi\u1ebft \u0111\u1ec3 \u0111\u01b0\u1ee3c h\u01b0\u1edbng d\u1eabn c\xe1ch x\xe1c minh giao d\u1ecbch. Trong t\xecnh hu\u1ed1ng c\xf3 v\u1ea5n \u0111\u1ec1, \u0111i\u1ec1u quan tr\u1ecdng l\xe0 l\u01b0u l\u1ea1i nh\u1eefng s\u1ef1 th\u1eadt \u0111\xe3 x\xe1c nh\u1eadn v\xe0 l\u1ecbch s\u1eed giao d\u1ecbch thay v\xec k\u1ebft lu\u1eadn b\u1eb1ng suy \u0111o\xe1n.")
A.iNN=s([A.cuf,A.cuP,A.cul],t.l5)
