A.ixt=s(["\uadf8\ub0e5 \uacc4\uc18d \uc0dd\uc0b0\ud55c\ub2e4.","\ubd88\ub7c9 \uc81c\ud488\uc744 \ubc14\ub85c \ubc84\ub9b0\ub2e4.","\ud574\ub2f9 \uc81c\ud488\uc744 \uaca9\ub9ac\ud558\uace0 \uad00\ub828\uc790\uc5d0\uac8c \ubcf4\uace0\ud55c \ud6c4 \uac80\uc0ac \ubc94\uc704\ub97c \ud655\uc778\ud55c\ub2e4.","\uae30\ub85d\ud558\uc9c0 \uc54a\ub294\ub2e4."],t.s)
A.caV=new B.a7("\uac80\uc0ac \uc911 \ub3d9\uc77c\ud55c \ubd88\ub7c9\uc774 \uc5f0\uc18d\uc73c\ub85c \ubc1c\uacac\ub410\uc2b5\ub2c8\ub2e4. \uac00\uc7a5 \uc801\uc808\ud55c \uccab \ub300\uc751\uc740?",A.ixt,2,"\ud488\uc9c8")
A.hxW=s(["\uacbd\ud5d8\uc774 \ub9ce\uc740 \uc0ac\ub78c\uc758 \ub290\ub08c\ub9cc \ubbff\ub294\ub2e4.","\ubc1c\uc0dd \uc2dc\uac04, \uc791\uc5c5 \uc870\uac74, \uc124\ube44 \uc0c1\ud0dc\uc640 \uc0dd\uc0b0 \uae30\ub85d\uc744 \ud568\uaed8 \ud655\uc778\ud55c\ub2e4.","\ubd88\ub7c9\ud488\uc744 \ubaa8\ub450 \ubc84\ub9ac\uace0 \ub05d\ub0b8\ub2e4.","\uc6d0\uc778\uc744 \ucc3e\uae30 \uc804\uc5d0 \ub2f4\ub2f9\uc790\ub97c \ube44\ud310\ud55c\ub2e4."],t.s)
A.ccd=new B.a7("\ubd88\ub7c9 \uc6d0\uc778\uc744 \ubd84\uc11d\ud560 \ub54c \uac00\uc7a5 \uc801\uc808\ud55c \ubc29\ubc95\uc740?",A.hxW,1,"\uc6d0\uc778 \ubd84\uc11d")
A.h1O=s(["\ubc14\ub85c \ubb38\uc81c \ud574\uacb0 \uc644\ub8cc\ub77c\uace0 \uae30\ub85d\ud55c\ub2e4.","\uc774\uc804 \uae30\ub85d\uc744 \ubaa8\ub450 \uc0ad\uc81c\ud55c\ub2e4.","\uac80\uc0ac\ub97c \uc911\ub2e8\ud55c\ub2e4.","\uc77c\uc815 \uae30\uac04 \uacb0\uacfc\ub97c \ud655\uc778\ud574\uc11c \uac1c\uc120 \ud6a8\uacfc\uc640 \uc7ac\ubc1c \uc5ec\ubd80\ub97c \uac80\uc99d\ud55c\ub2e4."],t.s)
A.cd0=new B.a7("\uac1c\uc120\uc548\uc744 \uc801\uc6a9\ud55c \ub2e4\uc74c \uac00\uc7a5 \uc801\uc808\ud55c \ud589\ub3d9\uc740?",A.h1O,3,"\uac1c\uc120")
A.hBH=s(["\uacf5\ucc28","\ud68c\uc758","\uc5c5\ubb34\ub7c9","\uc778\uc218\uc778\uacc4"],t.s)
A.cbI=new B.a7("\uc81c\ud488\uc758 \ud5c8\uc6a9 \uac00\ub2a5\ud55c \uce58\uc218 \ucc28\uc774 \ubc94\uc704\ub97c \ubb34\uc5c7\uc774\ub77c\uace0 \ud569\ub2c8\uae4c?",A.hBH,0,"\uc5b4\ud718")
A.fBm=s(["\ubd88\ub7c9\uc740 \uc624\uc804\uc5d0\ub9cc \ubc1c\uc0dd\ud588\uc2b5\ub2c8\ub2e4.","\ubd88\ub7c9\ud488\uc744 \uc815\uc0c1 \uc81c\ud488\uacfc \ud568\uaed8 \ubcf4\uad00\ud588\uc2b5\ub2c8\ub2e4.","\uc124\ube44 \uc870\uac74 \ubcc0\uacbd \uc774\ud6c4 \ubd88\ub7c9\uc774 \uc9d1\uc911\ub410\uc2b5\ub2c8\ub2e4.","\ucd94\uac00 \uac80\uc0ac\ub97c \ud558\uc9c0 \uc54a\uae30\ub85c \ud588\uc2b5\ub2c8\ub2e4."],t.s)
A.cb5=new B.a7("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\uac80\uc0ac\ud300\uc740 \uc624\ud6c4 \uc0dd\uc0b0\ud488\uc5d0\uc11c \ub3d9\uc77c\ud55c \uade0\uc5f4 \ubd88\ub7c9\uc744 \uc5ec\ub7ec \uac1c \ubc1c\uacac\ud588\uc2b5\ub2c8\ub2e4. \ud574\ub2f9 \uc81c\ud488\uc744 \ubcc4\ub3c4 \uad6c\uc5ed\uc5d0 \uaca9\ub9ac\ud55c \ud6c4 \uc0dd\uc0b0 \uae30\ub85d\uc744 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4. \ud655\uc778 \uacb0\uacfc \uc624\ud6c4 \ub450 \uc2dc\uc5d0 \uc124\ube44 \uc870\uac74\uc774 \ubcc0\uacbd\ub41c \uc774\ud6c4 \uc0dd\uc0b0\ub41c \uc81c\ud488\uc5d0\uc11c \ubd88\ub7c9\uc774 \uc9d1\uc911\ub41c \uac83\uc73c\ub85c \ub098\ud0c0\ub0ac\uc2b5\ub2c8\ub2e4. \ud68c\uc0ac\ub294 \uc870\uac74\uc744 \uc6d0\ub798 \uae30\uc900\uc73c\ub85c \uc870\uc815\ud558\uace0 \ubcc0\uacbd \uc804\ud6c4 \uc81c\ud488\uc744 \ucd94\uac00 \uac80\uc0ac\ud558\uae30\ub85c \ud588\uc2b5\ub2c8\ub2e4.",A.fBm,2,"\uc77d\uae30")
A.i7_=s(["\ubb54\uac00 \uc774\uc0c1\ud574\uc694.","\uc624\ud6c4 \ub450 \uc2dc \uc774\ud6c4 \uc0dd\uc0b0\ud488 30\uac1c \uc911 \uc6a9\uc811 \uade0\uc5f4 \ubd88\ub7c9\uc774 4\uac1c \ubc1c\uacac\ub410\uc2b5\ub2c8\ub2e4.","\uc81c\ud488\uc774 \ubcc4\ub85c\uc608\uc694.","\uae30\uacc4\uac00 \ubb38\uc81c\uc778 \uac83 \uac19\uc544\uc694. \ud655\uc2e4\ud574\uc694."],t.s)
A.ceM=new B.a7("\ub2e4\uc74c \uc911 \uac00\uc7a5 \uc88b\uc740 \ud488\uc9c8 \ubb38\uc81c \ubcf4\uace0\ub294?",A.i7_,1,"\ubcf4\uace0")
A.i7G=s(["\ubd88\ub7c9\uc744 \ubc1c\uacac\ud558\uba74 \uc81c\ud488\uc744 \uad6c\ubd84\ud55c\ub2e4.","\uad00\ub828\uc790\uc5d0\uac8c \uc0c1\ud669\uc744 \uacf5\uc720\ud55c\ub2e4.","\uc6d0\uc778\uc744 \ud655\uc778\ud558\uace0 \uac1c\uc120 \ub300\ucc45\uc744 \uc801\uc6a9\ud55c\ub2e4.","\uc6d0\uc778\uc744 \ud655\uc778\ud558\uc9c0 \uc54a\uace0 \uac80\uc0ac\ub9cc \uacc4\uc18d\ud558\uba74 \ubaa8\ub4e0 \ubb38\uc81c\uac00 \ud574\uacb0\ub41c\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4."],t.s)
A.cf8=new B.a7("\ud488\uc9c8 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub294 \uc21c\uc11c\ub85c \uac00\uc7a5 \uc801\uc808\ud558\uc9c0 \uc54a\uc740 \uac83\uc740?",A.i7G,3,"\uc885\ud569")
A.fTh=s([A.ccp,A.ccX,A.cfl,A.cdV,A.cca,A.ccx,A.cec,A.cfq,A.caV,A.ccd,A.cd0,A.cbI,A.cb5,A.ceM,A.cf8],t.VX)
A.i8x=s(["\ubc1c\uacac \uc2dc\uac04","\uc81c\ud488","\ubd88\ub7c9 \uc720\ud615","\uc218\ub7c9","\uaca9\ub9ac","\ucd94\uac00 \ud655\uc778"],t.s)
A.chD=new B.c7("\uac80\uc0ac \uc911 \ubd88\ub7c9\uc744 \ubc1c\uacac\ud588\ub2e4\uace0 \uac00\uc815\ud558\uace0 \ud300\uc7a5\uc5d0\uac8c \ubcf4\uace0\ud574 \ubcf4\uc138\uc694.",A.i8x,"\ud300\uc7a5\ub2d8, \ud488\uc9c8 \ubb38\uc81c\ub97c \ubcf4\uace0\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4. \uc624\ud6c4 \ub450 \uc2dc \uc774\ud6c4 \uc0dd\uc0b0\ub41c \uc81c\ud488\uc744 \uac80\uc0ac\ud558\ub358 \uc911 \uc6a9\uc811 \ubd80\uc704\uc5d0 \uade0\uc5f4\uc774 \uc788\ub294 \uc81c\ud488\uc774 \ub124 \uac1c \ubc1c\uacac\ub410\uc2b5\ub2c8\ub2e4. \uac19\uc740 \uc720\ud615\uc758 \ubd88\ub7c9\uc774 \uc5f0\uc18d\uc73c\ub85c \ud655\uc778\ub3fc\uc11c \ud574\ub2f9 \uc2dc\uac04\ub300 \uc0dd\uc0b0\ud488\uc740 \uc815\uc0c1 \uc81c\ud488\uacfc \uc11e\uc774\uc9c0 \uc54a\ub3c4\ub85d \ubcc4\ub3c4\ub85c \uaca9\ub9ac\ud588\uc2b5\ub2c8\ub2e4. \ud604\uc7ac \uac19\uc740 \uc2dc\uac04\ub300\uc5d0 \uc0dd\uc0b0\ub41c \ub2e4\ub978 \uc81c\ud488\ub3c4 \ucd94\uac00\ub85c \ud655\uc778\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc0dd\uc0b0 \uae30\ub85d\uacfc \uc124\ube44 \uc870\uac74\ub3c4 \uac19\uc774 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4.")
A.hA1=s(["\ubc1c\uc0dd \uc2dc\uac04","\uc791\uc5c5\uc790","\uc124\ube44","\uc790\uc7ac","\uc791\uc5c5 \uc870\uac74","\uc0dd\uc0b0 \uae30\ub85d","\uce21\uc815 \uacb0\uacfc"],t.s)
A.cgW=new B.c7("\ubd88\ub7c9 \uc6d0\uc778\uc744 \ubd84\uc11d\ud558\uae30 \uc704\ud574 \ud655\uc778\ud574\uc57c \ud560 \ub0b4\uc6a9\uc744 \ub9d0\ud574 \ubcf4\uc138\uc694.",A.hA1,"\ubd88\ub7c9 \uc6d0\uc778\uc744 \ucc3e\uae30 \uc704\ud574\uc11c\ub294 \uba3c\uc800 \ubb38\uc81c\uac00 \uc5b8\uc81c\ubd80\ud130 \ubc1c\uc0dd\ud588\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \uadf8\ub2e4\uc74c \ubd88\ub7c9 \ubc1c\uc0dd \uc804\ud6c4\uc5d0 \uc791\uc5c5\uc790, \uc790\uc7ac, \uc124\ube44 \uc870\uac74\uc774\ub098 \uc791\uc5c5 \ubc29\ubc95\uc774 \ubcc0\uacbd\ub41c \uac83\uc774 \uc788\ub294\uc9c0 \ube44\uad50\ud574\uc57c \ud569\ub2c8\ub2e4. \uc124\ube44 \uc0c1\ud0dc\uc640 \uc0dd\uc0b0 \uae30\ub85d\ub3c4 \ud655\uc778\ud558\uace0 \uce21\uc815\uac12\uc774 \uc815\ud655\ud55c\uc9c0 \uce21\uc815 \uc7a5\ube44\ub3c4 \uc810\uac80\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \ud55c \uac00\uc9c0 \uc6d0\uc778\ub9cc \ubbf8\ub9ac \uc815\ud574 \ub193\uae30\ubcf4\ub2e4\ub294 \uc5ec\ub7ec \uac00\ub2a5\uc131\uc744 \ud655\uc778\ud55c \ud6c4 \ub370\uc774\ud130\ub97c \uadfc\uac70\ub85c \ud310\ub2e8\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.hHo=s(["\uc6d0\uc778","\uc791\uc5c5 \ud45c\uc900","\uc810\uac80","\uad50\uc721","\uae30\ub85d","\uc7ac\ubc1c \ubc29\uc9c0"],t.s)
A.chq=new B.c7("\uac19\uc740 \ubd88\ub7c9\uc758 \uc7ac\ubc1c\uc744 \ub9c9\uae30 \uc704\ud55c \uac1c\uc120 \ubc29\uc548\uc744 \uc81c\uc548\ud574 \ubcf4\uc138\uc694.",A.hHo,"\uc6d0\uc778 \ubd84\uc11d \uacb0\uacfc \uc791\uc5c5 \uc628\ub3c4\uac00 \uae30\uc900\ubcf4\ub2e4 \ub192\uc544\uc9c8 \ub54c \uc81c\ud488 \ubcc0\ud615\uc774 \ubc1c\uc0dd\ud558\ub294 \uac83\uc73c\ub85c \ud655\uc778\ub410\ub2e4\uace0 \uac00\uc815\ud558\uaca0\uc2b5\ub2c8\ub2e4. \uc7ac\ubc1c \ubc29\uc9c0\ub97c \uc704\ud574 \uba3c\uc800 \uc791\uc5c5 \ud45c\uc900\uc5d0 \ud5c8\uc6a9 \uc628\ub3c4 \ubc94\uc704\ub97c \uba85\ud655\ud558\uac8c \ud45c\uc2dc\ud574\uc57c \ud569\ub2c8\ub2e4. \uc791\uc5c5\uc790\uac00 \ud55c \uc2dc\uac04\ub9c8\ub2e4 \uc2e4\uc81c \uc628\ub3c4\ub97c \ud655\uc778\ud558\uace0 \uae30\ub85d\ud558\ub3c4\ub85d \ud558\ub294 \uac83\ub3c4 \uc88b\uaca0\uc2b5\ub2c8\ub2e4. \uae30\uc900\uc744 \ubc97\uc5b4\ub098\uba74 \uc989\uc2dc \uc791\uc5c5\uc744 \uc911\ub2e8\ud558\uace0 \ub2f4\ub2f9\uc790\uc5d0\uac8c \ubcf4\uace0\ud558\ub3c4\ub85d \ud574\uc57c \ud569\ub2c8\ub2e4. \ub610\ud55c \ubaa8\ub4e0 \uc791\uc5c5\uc790\uc5d0\uac8c \ubcc0\uacbd\ub41c \uae30\uc900\uc744 \uad50\uc721\ud558\uace0 \ud55c \ub2ec \ub3d9\uc548 \ubd88\ub7c9\ub960\uc744 \ud655\uc778\ud574\uc11c \uac1c\uc120 \ud6a8\uacfc\ub97c \uac80\uc99d\ud574\uc57c \ud569\ub2c8\ub2e4.")
A.fPX=s(["\uac1c\uc120 \uc804","\ubd88\ub7c9\ub960","\uac1c\uc120 \ub0b4\uc6a9","\uac1c\uc120 \ud6c4","\ud6a8\uacfc","\ucd94\uac00 \ud655\uc778"],t.s)
A.chx=new B.c7("\uac1c\uc120 \uc804\uacfc \uac1c\uc120 \ud6c4\uc758 \uacb0\uacfc\ub97c \ube44\uad50\ud574\uc11c \ubcf4\uace0\ud574 \ubcf4\uc138\uc694.",A.fPX,"\uac1c\uc120 \uc804\uc5d0\ub294 \ud574\ub2f9 \uacf5\uc815\uc758 \ud3c9\uade0 \ubd88\ub7c9\ub960\uc774 \uc57d 3\ud37c\uc13c\ud2b8\uc600\uc2b5\ub2c8\ub2e4. \uc6d0\uc778\uc744 \ubd84\uc11d\ud55c \uacb0\uacfc \uc791\uc5c5 \uc870\uac74 \uad00\ub9ac\uac00 \uc77c\uc815\ud558\uc9c0 \uc54a\uc740 \uac83\uc774 \uc8fc\uc694 \ubb38\uc81c\ub85c \ud655\uc778\ub3fc\uc11c \uc628\ub3c4 \uae30\uc900\uacfc \uc810\uac80 \uc8fc\uae30\ub97c \uc218\uc815\ud588\uc2b5\ub2c8\ub2e4. \uac1c\uc120 \ud6c4 2\uc8fc \ub3d9\uc548 \ud655\uc778\ud55c \uacb0\uacfc \ubd88\ub7c9\ub960\uc740 \uc57d 1\ud37c\uc13c\ud2b8\uae4c\uc9c0 \ub0ae\uc544\uc84c\uc2b5\ub2c8\ub2e4. \uac19\uc740 \uc720\ud615\uc758 \ubd88\ub7c9\ub3c4 \ud06c\uac8c \uc904\uc5c8\uc2b5\ub2c8\ub2e4. \ub2e4\ub9cc \uc544\uc9c1 \ud655\uc778 \uae30\uac04\uc774 \uc9e7\uae30 \ub54c\ubb38\uc5d0 \ud55c \ub2ec \uc815\ub3c4 \ub354 \ub370\uc774\ud130\ub97c \uc218\uc9d1\ud55c \ud6c4 \uac1c\uc120 \ud6a8\uacfc\ub97c \ucd5c\uc885\uc801\uc73c\ub85c \uac80\uc99d\ud558\ub294 \uac83\uc774 \uc88b\uaca0\uc2b5\ub2c8\ub2e4.")
A.hjw=s([A.chD,A.cgW,A.chq,A.chx],t.uf)
A.fZ8=s(["\ubd88\ub7c9 \ubc1c\uacac \uc0c1\ud669\uc744 \uc4f0\uc138\uc694.","\uc81c\ud488 \uaca9\ub9ac \ubc29\ubc95\uc744 \uc4f0\uc138\uc694.","\ubcf4\uace0 \ub0b4\uc6a9\uc744 \uc4f0\uc138\uc694.","\uc6d0\uc778 \ubd84\uc11d \ubc29\ubc95\uc744 \uc4f0\uc138\uc694.","\uac1c\uc120 \uc870\uce58\ub97c \uc4f0\uc138\uc694.","\uc7ac\ubc1c \ubc29\uc9c0\ub97c \uc4f0\uc138\uc694.","V-\uc9c0 \uc54a\ub3c4\ub85d \uc870\uce58\ud558\ub2e4\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cum=new B.cN("\ud488\uc9c8 \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud588\uc744 \ub54c \ucc98\ub9ac \uacfc\uc815\uc744 \uc368 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft quy tr\xecnh x\u1eed l\xfd khi ph\xe1t sinh v\u1ea5n \u0111\u1ec1 ch\u1ea5t l\u01b0\u1ee3ng.",A.fZ8,"\uc0dd\uc0b0 \ud604\uc7a5\uc5d0\uc11c \ubd88\ub7c9\uc774 \ubc1c\uacac\ub418\uba74 \uba3c\uc800 \ubb38\uc81c\uac00 \uc788\ub294 \uc81c\ud488\uc744 \uc815\uc0c1 \uc81c\ud488\uacfc \uad6c\ubd84\ud574\uc57c \ud569\ub2c8\ub2e4. \ubd88\ub7c9\ud488\uc774 \ub2e4\uc74c \uacf5\uc815\uc73c\ub85c \ub118\uc5b4\uac00\uc9c0 \uc54a\ub3c4\ub85d \ubcc4\ub3c4 \uad6c\uc5ed\uc5d0 \uaca9\ub9ac\ud558\uace0 \ubc1c\uacac \uc2dc\uac04, \uc81c\ud488 \ubc88\ud638, \ubd88\ub7c9 \uc720\ud615\uacfc \uc218\ub7c9\uc744 \uae30\ub85d\ud574\uc57c \ud569\ub2c8\ub2e4. \uadf8\ub2e4\uc74c \ub2f4\ub2f9\uc790\uc640 \uad00\ub828 \ubd80\uc11c\uc5d0 \uc0c1\ud669\uc744 \ubcf4\uace0\ud558\uace0 \uac19\uc740 \uc2dc\uac04\ub300\uc5d0 \uc0dd\uc0b0\ub41c \uc81c\ud488\uae4c\uc9c0 \uac80\uc0ac \ubc94\uc704\ub97c \ud655\uc778\ud569\ub2c8\ub2e4. \uc6d0\uc778 \ubd84\uc11d\uc744 \ud560 \ub54c\ub294 \uc124\ube44, \uc790\uc7ac, \uc791\uc5c5\uc790, \uc791\uc5c5 \ubc29\ubc95\uacfc \uc0dd\uc0b0 \uae30\ub85d\uc744 \ud568\uaed8 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \uc6d0\uc778\uc774 \ud655\uc778\ub418\uba74 \ud544\uc694\ud55c \uc870\uce58\ub97c \uc801\uc6a9\ud558\uace0 \uc77c\uc815 \uae30\uac04 \uac19\uc740 \ubb38\uc81c\uac00 \uc7ac\ubc1c\ud558\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \uac1c\uc120 \ud6a8\uacfc\uac00 \uac80\uc99d\ub418\uba74 \ubcc0\uacbd \ub0b4\uc6a9\uc744 \uc791\uc5c5 \ud45c\uc900\uc5d0\ub3c4 \ubc18\uc601\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","Khi ph\xe1t hi\u1ec7n h\xe0ng l\u1ed7i t\u1ea1i hi\u1ec7n tr\u01b0\u1eddng s\u1ea3n xu\u1ea5t, tr\u01b0\u1edbc ti\xean c\u1ea7n ph\xe2n bi\u1ec7t s\u1ea3n ph\u1ea9m c\xf3 v\u1ea5n \u0111\u1ec1 v\u1edbi s\u1ea3n ph\u1ea9m b\xecnh th\u01b0\u1eddng. C\u1ea7n c\xe1ch ly \u1edf khu v\u1ef1c ri\xeang \u0111\u1ec3 h\xe0ng l\u1ed7i kh\xf4ng chuy\u1ec3n sang c\xf4ng \u0111o\u1ea1n sau, \u0111\u1ed3ng th\u1eddi ghi l\u1ea1i th\u1eddi gian ph\xe1t hi\u1ec7n, m\xe3 s\u1ea3n ph\u1ea9m, lo\u1ea1i l\u1ed7i v\xe0 s\u1ed1 l\u01b0\u1ee3ng. Sau \u0111\xf3 b\xe1o t\xecnh h\xecnh cho ng\u01b0\u1eddi ph\u1ee5 tr\xe1ch v\xe0 b\u1ed9 ph\u1eadn li\xean quan, \u0111\u1ed3ng th\u1eddi x\xe1c nh\u1eadn ph\u1ea1m vi ki\u1ec3m tra \u0111\u1ebfn s\u1ea3n ph\u1ea9m s\u1ea3n xu\u1ea5t c\xf9ng th\u1eddi gian. Khi ph\xe2n t\xedch nguy\xean nh\xe2n c\u1ea7n ki\u1ec3m tra c\xf9ng l\xfac thi\u1ebft b\u1ecb, v\u1eadt li\u1ec7u, ng\u01b0\u1eddi thao t\xe1c, ph\u01b0\u01a1ng ph\xe1p l\xe0m vi\u1ec7c v\xe0 ghi ch\xe9p s\u1ea3n xu\u1ea5t. Khi x\xe1c nh\u1eadn \u0111\u01b0\u1ee3c nguy\xean nh\xe2n th\xec \xe1p d\u1ee5ng bi\u1ec7n ph\xe1p c\u1ea7n thi\u1ebft v\xe0 theo d\xf5i trong m\u1ed9t kho\u1ea3ng th\u1eddi gian xem c\xf9ng v\u1ea5n \u0111\u1ec1 c\xf3 t\xe1i di\u1ec5n kh\xf4ng. N\u1ebfu hi\u1ec7u qu\u1ea3 c\u1ea3i ti\u1ebfn \u0111\u01b0\u1ee3c ki\u1ec3m ch\u1ee9ng th\xec c\u1ea7n ph\u1ea3n \xe1nh n\u1ed9i dung thay \u0111\u1ed5i v\xe0o ti\xeau chu\u1ea9n thao t\xe1c.")
A.hhI=s(["\ud604\uc7ac \ubd88\ub7c9\ub960\uc744 \uc4f0\uc138\uc694.","\uc8fc\uc694 \ubd88\ub7c9 \uc720\ud615\uc744 \uc4f0\uc138\uc694.","\uc6d0\uc778\uc744 \ubd84\uc11d\ud558\uc138\uc694.","\uac1c\uc120 \ubc29\uc548\uc744 \uc81c\uc548\ud558\uc138\uc694.","\ud6a8\uacfc \ud655\uc778 \ubc29\ubc95\uc744 \uc4f0\uc138\uc694.","V-(\uc73c)\u3134 \uacb0\uacfc\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cup=new B.cN("\ubd88\ub7c9\ub960\uc744 \uc904\uc774\uae30 \uc704\ud55c \uac1c\uc120 \ud65c\ub3d9\uc5d0 \ub300\ud574 \uc368 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft v\u1ec1 ho\u1ea1t \u0111\u1ed9ng c\u1ea3i ti\u1ebfn nh\u1eb1m gi\u1ea3m t\u1ef7 l\u1ec7 l\u1ed7i.",A.hhI,"\ucd5c\uadfc \ud55c \ub2ec \ub3d9\uc548 \ud574\ub2f9 \uacf5\uc815\uc758 \ubd88\ub7c9\ub960\uc740 \ud3c9\uade0 3.5\ud37c\uc13c\ud2b8\uc600\uc73c\uba70 \uac00\uc7a5 \ub9ce\uc774 \ubc1c\uc0dd\ud55c \ubb38\uc81c\ub294 \uc81c\ud488 \ubcc0\ud615\uc774\uc5c8\uc2b5\ub2c8\ub2e4. \uc0dd\uc0b0 \uae30\ub85d\uc744 \ud655\uc778\ud55c \uacb0\uacfc \uc624\ud6c4 \uc2dc\uac04\ub300\uc5d0 \uc124\ube44 \uc628\ub3c4\uac00 \uc77c\uc815\ud558\uc9c0 \uc54a\uc558\uace0 \uadf8 \uc2dc\uac04\uc5d0 \uc0dd\uc0b0\ub41c \uc81c\ud488\uc5d0\uc11c \ubd88\ub7c9\uc774 \ub9ce\uc774 \ubc1c\uc0dd\ud588\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc628\ub3c4 \uad00\ub9ac \uae30\uc900\uc744 \ub2e4\uc2dc \uc815\ud558\uace0 \uc791\uc5c5\uc790\uac00 \ud55c \uc2dc\uac04\ub9c8\ub2e4 \uc2e4\uc81c \uc628\ub3c4\ub97c \uae30\ub85d\ud558\ub3c4\ub85d \uac1c\uc120\ud588\uc2b5\ub2c8\ub2e4. \ub610\ud55c \uae30\uc900\uc744 \ubc97\uc5b4\ub0a0 \uacbd\uc6b0 \uc989\uc2dc \ub2f4\ub2f9\uc790\uc5d0\uac8c \ubcf4\uace0\ud558\ub3c4\ub85d \ud588\uc2b5\ub2c8\ub2e4. \uac1c\uc120\uc548\uc744 2\uc8fc \ub3d9\uc548 \uc801\uc6a9\ud55c \uacb0\uacfc \ubd88\ub7c9\ub960\uc774 1.4\ud37c\uc13c\ud2b8\uae4c\uc9c0 \ub0ae\uc544\uc84c\uc2b5\ub2c8\ub2e4. \uc55e\uc73c\ub85c \ud55c \ub2ec \ub3d9\uc548 \ub370\uc774\ud130\ub97c \ub354 \ud655\uc778\ud574\uc11c \ud6a8\uacfc\uac00 \uc9c0\uc18d\ub418\ub294\uc9c0 \uac80\uc99d\ud560 \uacc4\ud68d\uc785\ub2c8\ub2e4.","Trong m\u1ed9t th\xe1ng g\u1ea7n \u0111\xe2y, t\u1ef7 l\u1ec7 l\u1ed7i trung b\xecnh c\u1ee7a c\xf4ng \u0111o\u1ea1n \u0111\xf3 l\xe0 3,5% v\xe0 v\u1ea5n \u0111\u1ec1 ph\xe1t sinh nhi\u1ec1u nh\u1ea5t l\xe0 bi\u1ebfn d\u1ea1ng s\u1ea3n ph\u1ea9m. K\u1ebft qu\u1ea3 ki\u1ec3m tra ghi ch\xe9p s\u1ea3n xu\u1ea5t cho th\u1ea5y nhi\u1ec7t \u0111\u1ed9 thi\u1ebft b\u1ecb kh\xf4ng \u1ed5n \u0111\u1ecbnh v\xe0o bu\u1ed5i chi\u1ec1u v\xe0 nhi\u1ec1u l\u1ed7i ph\xe1t sinh \u1edf s\u1ea3n ph\u1ea9m s\u1ea3n xu\u1ea5t trong th\u1eddi gian \u0111\xf3. V\xec v\u1eady ch\xfang t\xf4i \u0111\xe3 thi\u1ebft l\u1eadp l\u1ea1i ti\xeau chu\u1ea9n qu\u1ea3n l\xfd nhi\u1ec7t \u0111\u1ed9 v\xe0 y\xeau c\u1ea7u ng\u01b0\u1eddi thao t\xe1c ghi nhi\u1ec7t \u0111\u1ed9 th\u1ef1c t\u1ebf m\u1ed7i gi\u1edd. Ngo\xe0i ra khi v\u01b0\u1ee3t ti\xeau chu\u1ea9n ph\u1ea3i b\xe1o ng\u01b0\u1eddi ph\u1ee5 tr\xe1ch ngay. K\u1ebft qu\u1ea3 \xe1p d\u1ee5ng ph\u01b0\u01a1ng \xe1n c\u1ea3i ti\u1ebfn trong hai tu\u1ea7n cho th\u1ea5y t\u1ef7 l\u1ec7 l\u1ed7i gi\u1ea3m xu\u1ed1ng 1,4%. Ch\xfang t\xf4i d\u1ef1 \u0111\u1ecbnh theo d\xf5i th\xeam d\u1eef li\u1ec7u trong m\u1ed9t th\xe1ng \u0111\u1ec3 ki\u1ec3m ch\u1ee9ng hi\u1ec7u qu\u1ea3 c\xf3 \u0111\u01b0\u1ee3c duy tr\xec hay kh\xf4ng.")
A.iTI=s(["\uac80\uc0ac\uc758 \uc5ed\ud560\uc744 \uc124\uba85\ud558\uc138\uc694.","\uc6d0\uc778 \ubd84\uc11d\uc758 \ud544\uc694\uc131\uc744 \uc4f0\uc138\uc694.","\uc784\uc2dc \uc870\uce58\uc640 \uadfc\ubcf8 \uac1c\uc120\uc744 \ube44\uad50\ud558\uc138\uc694.","\uc7ac\ubc1c \ubc29\uc9c0\ub97c \uc124\uba85\ud558\uc138\uc694.","V-\ub294 \ud55c\uc744 \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cv5=new B.cN("\uac80\uc0ac\ub9cc\uc73c\ub85c \ud488\uc9c8 \ubb38\uc81c\ub97c \ud574\uacb0\ud560 \uc218 \uc5c6\ub294 \uc774\uc720\ub97c \uc368 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft t\u1ea1i sao ch\u1ec9 ki\u1ec3m tra th\xf4i kh\xf4ng th\u1ec3 gi\u1ea3i quy\u1ebft ho\xe0n to\xe0n v\u1ea5n \u0111\u1ec1 ch\u1ea5t l\u01b0\u1ee3ng.",A.iTI,"\uac80\uc0ac\ub294 \ubd88\ub7c9 \uc81c\ud488\uc744 \ubc1c\uacac\ud558\uace0 \uc815\uc0c1 \uc81c\ud488\uacfc \uad6c\ubd84\ud558\ub294 \ub370 \ub9e4\uc6b0 \uc911\uc694\ud569\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \uac80\uc0ac\ub9cc \ub9ce\uc774 \ud55c\ub2e4\uace0 \ud574\uc11c \ud488\uc9c8 \ubb38\uc81c\uac00 \uc644\uc804\ud788 \ud574\uacb0\ub418\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4. \ubd88\ub7c9\uc774 \ubc1c\uc0dd\ud558\ub294 \uc6d0\uc778\uc774 \uadf8\ub300\ub85c \ub0a8\uc544 \uc788\ub294 \ud55c \uac19\uc740 \ubb38\uc81c\ub294 \uacc4\uc18d \ubc1c\uc0dd\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc804\uc218 \uac80\uc0ac\ub97c \ud1b5\ud574 \uace0\uac1d\uc5d0\uac8c \ubd88\ub7c9\ud488\uc774 \uc804\ub2ec\ub418\ub294 \uac83\uc744 \uc904\uc77c \uc218\ub294 \uc788\uc9c0\ub9cc \uc0dd\uc0b0 \uacfc\uc815\uc5d0\uc11c\ub294 \uacc4\uc18d \ubd88\ub7c9\uc774 \ub9cc\ub4e4\uc5b4\uc9c8 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \ubd88\ub7c9\uc744 \ubc1c\uacac\ud55c \ud6c4\uc5d0\ub294 \uc0dd\uc0b0 \uc870\uac74, \uc124\ube44, \uc790\uc7ac\uc640 \uc791\uc5c5 \ubc29\ubc95\uc744 \ubd84\uc11d\ud574\uc11c \uadfc\ubcf8 \uc6d0\uc778\uc744 \ucc3e\uc544\uc57c \ud569\ub2c8\ub2e4. \uc6d0\uc778\uc744 \uc81c\uac70\ud558\uace0 \uc791\uc5c5 \ud45c\uc900\uacfc \uad00\ub9ac \ubc29\ubc95\uc744 \uac1c\uc120\ud574\uc57c \ubd88\ub7c9 \ubc1c\uc0dd \uc790\uccb4\ub97c \uc904\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9\uc73c\ub85c \uac1c\uc120 \ud6c4\uc5d0\ub3c4 \uc77c\uc815 \uae30\uac04 \uacb0\uacfc\ub97c \ud655\uc778\ud574\uc11c \uc7ac\ubc1c \ubc29\uc9c0 \ud6a8\uacfc\ub97c \uac80\uc99d\ud574\uc57c \ud569\ub2c8\ub2e4.","Ki\u1ec3m tra r\u1ea5t quan tr\u1ecdng \u0111\u1ec3 ph\xe1t hi\u1ec7n s\u1ea3n ph\u1ea9m l\u1ed7i v\xe0 ph\xe2n bi\u1ec7t v\u1edbi s\u1ea3n ph\u1ea9m \u0111\u1ea1t. Tuy nhi\xean kh\xf4ng ph\u1ea3i c\u1ee9 t\u0103ng ki\u1ec3m tra l\xe0 v\u1ea5n \u0111\u1ec1 ch\u1ea5t l\u01b0\u1ee3ng \u0111\u01b0\u1ee3c gi\u1ea3i quy\u1ebft ho\xe0n to\xe0n. Ch\u1eebng n\xe0o nguy\xean nh\xe2n g\xe2y l\u1ed7i v\u1eabn c\xf2n th\xec c\xf9ng v\u1ea5n \u0111\u1ec1 c\xf3 th\u1ec3 ti\u1ebfp t\u1ee5c x\u1ea3y ra. Ki\u1ec3m tra 100% c\xf3 th\u1ec3 gi\u1ea3m kh\u1ea3 n\u0103ng h\xe0ng l\u1ed7i \u0111\u1ebfn kh\xe1ch h\xe0ng, nh\u01b0ng trong qu\xe1 tr\xecnh s\u1ea3n xu\u1ea5t h\xe0ng l\u1ed7i v\u1eabn c\xf3 th\u1ec3 ti\u1ebfp t\u1ee5c \u0111\u01b0\u1ee3c t\u1ea1o ra. V\xec v\u1eady sau khi ph\xe1t hi\u1ec7n l\u1ed7i c\u1ea7n ph\xe2n t\xedch \u0111i\u1ec1u ki\u1ec7n s\u1ea3n xu\u1ea5t, thi\u1ebft b\u1ecb, v\u1eadt li\u1ec7u v\xe0 ph\u01b0\u01a1ng ph\xe1p thao t\xe1c \u0111\u1ec3 t\xecm nguy\xean nh\xe2n g\u1ed1c. Ch\u1ec9 khi lo\u1ea1i b\u1ecf nguy\xean nh\xe2n v\xe0 c\u1ea3i thi\u1ec7n ti\xeau chu\u1ea9n thao t\xe1c c\xf9ng ph\u01b0\u01a1ng ph\xe1p qu\u1ea3n l\xfd m\u1edbi c\xf3 th\u1ec3 gi\u1ea3m ch\xednh vi\u1ec7c ph\xe1t sinh l\u1ed7i. Cu\u1ed1i c\xf9ng sau c\u1ea3i ti\u1ebfn c\u0169ng ph\u1ea3i theo d\xf5i k\u1ebft qu\u1ea3 trong m\u1ed9t kho\u1ea3ng th\u1eddi gian \u0111\u1ec3 ki\u1ec3m ch\u1ee9ng hi\u1ec7u qu\u1ea3 ph\xf2ng t\xe1i di\u1ec5n.")
A.hkV=s([A.cum,A.cup,A.cv5],t.l5)
