A.chF=new B.c7("\ucc9c\uc7a5\uc5d0\uc11c \ub204\uc218\uac00 \ubc1c\uc0dd\ud55c \uc0c1\ud669\uc744 \uad00\ub9ac\uc2e4\uc5d0 \uc2e0\uace0\ud574 \ubcf4\uc138\uc694.",A.hZS,"\uc548\ub155\ud558\uc138\uc694. \uc624\ub298 \uc544\uce68\ubd80\ud130 \uac70\uc2e4 \ucc9c\uc7a5 \uc624\ub978\ucabd \ubd80\ubd84\uc5d0\uc11c \ubb3c\uc774 \uc0c8\uae30 \uc2dc\uc791\ud574\uc11c \uc5f0\ub77d\ub4dc\ub9bd\ub2c8\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc791\uc740 \uc5bc\ub8e9\ub9cc \uc788\uc5c8\ub294\ub370 \uc9c0\uae08\uc740 \uc816\uc740 \ubc94\uc704\uac00 \uc870\uae08 \ub113\uc5b4\uc84c\uace0 \uac00\ub054 \ubb3c\ubc29\uc6b8\ub3c4 \ub5a8\uc5b4\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ud604\uc7ac \uc0c1\ud0dc\ub97c \uc0ac\uc9c4\uacfc \uc601\uc0c1\uc73c\ub85c \ucc0d\uc5b4 \ub450\uc5c8\uc2b5\ub2c8\ub2e4. \uc704\uce35\uc774\ub098 \ubc30\uad00 \ubb38\uc81c\uc778\uc9c0 \uc81c\uac00 \uc815\ud655\ud788 \uc54c \uc218 \uc5c6\uc5b4\uc11c \uc810\uac80\uc744 \uc694\uccad\ub4dc\ub9ac\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \ud655\uc778 \uac00\ub2a5\ud55c \uc2dc\uac04\uc774 \uc5b8\uc81c\uc778\uc9c0 \uc54c\ub824 \uc8fc\uc2e4 \uc218 \uc788\uc744\uae4c\uc694?")
A.inp=s(["\uae30\uac04","\uc2dc\uac04\ub300","\uc18c\uc74c \uc885\ub958","\ubc18\ubcf5","\uc0dd\ud65c \uc601\ud5a5","\ud655\uc778 \uc694\uccad"],t.s)
A.chz=new B.c7("\uce35\uac04\uc18c\uc74c \ubb38\uc81c\ub97c \uac10\uc815\uc801\uc774\uc9c0 \uc54a\uac8c \uc124\uba85\ud574 \ubcf4\uc138\uc694.",A.inp,"\ucd5c\uadfc \uc77c\uc8fc\uc77c \uc815\ub3c4 \ubc24 11\uc2dc \uc774\ud6c4\uc5d0 \uc704\uce35\uc5d0\uc11c \ub6f0\uac70\ub098 \ubb34\uac70\uc6b4 \ubb3c\uac74\uc744 \ub044\ub294 \uac83 \uac19\uc740 \uc18c\ub9ac\uac00 \ubc18\ubcf5\ud574\uc11c \ub4e4\ub9ac\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ub9e4\uc77c \uadf8\ub7f0 \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc \uc77c\uc8fc\uc77c \ub3d9\uc548 \ub124 \ubc88 \uc815\ub3c4 \ubc1c\uc0dd\ud588\uace0 \ud55c \ubc88 \uc2dc\uc791\ud558\uba74 20\ubd84\uc5d0\uc11c 30\ubd84 \uc815\ub3c4 \uacc4\uc18d\ub410\uc2b5\ub2c8\ub2e4. \uc7a0\uc744 \uc790\ub294 \ub370 \uc5b4\ub824\uc6c0\uc774 \uc788\uc5b4\uc11c \ub0a0\uc9dc\uc640 \uc2dc\uac04\uc744 \uae30\ub85d\ud574 \ub450\uc5c8\uc2b5\ub2c8\ub2e4. \ub204\uad6c\uc758 \uc798\ubabb\uc774\ub77c\uace0 \ub2e8\uc815\ud558\ub824\ub294 \uac83\uc740 \uc544\ub2c8\uace0 \uac00\ub2a5\ud55c \ud574\uacb0 \ubc29\ubc95\uc774 \uc788\ub294\uc9c0 \uad00\ub9ac\uc2e4\uc5d0 \uba3c\uc800 \ud655\uc778\ud558\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.")
A.fEP=s(["\uc9c0\ub09c \uc218\ub9ac","\uc7ac\ubc1c","\uc870\uac74","\uc601\uc0c1","\uac19\uc740 \uc704\uce58","\uc7ac\uc810\uac80"],t.s)
A.cgM=new B.c7("\uc218\ub9ac \ud6c4 \ubb38\uc81c\uac00 \ub2e4\uc2dc \ubc1c\uc0dd\ud588\uc744 \ub54c \uc7ac\uc810\uac80\uc744 \uc694\uccad\ud574 \ubcf4\uc138\uc694.",A.fEP,"\uc9c0\ub09c\uc8fc\uc5d0 \uc2f1\ud06c\ub300 \uc544\ub798 \ub204\uc218 \ubb38\uc81c\ub97c \uc218\ub9ac\ud574 \uc8fc\uc168\ub294\ub370 \uac19\uc740 \ubb38\uc81c\uac00 \ub2e4\uc2dc \ubc1c\uc0dd\ud574\uc11c \uc5f0\ub77d\ub4dc\ub9bd\ub2c8\ub2e4. \ud3c9\uc18c\uc5d0\ub294 \uad1c\ucc2e\uc9c0\ub9cc \ubb3c\uc744 \ub9ce\uc774 \uc0ac\uc6a9\ud560 \ub54c\ub9c8\ub2e4 \uc544\ub798\ucabd \uc5f0\uacb0 \ubd80\ubd84\uc5d0\uc11c \ubb3c\uc774 \uc870\uae08\uc529 \uc0d9\ub2c8\ub2e4. \uc9c0\ub09c\ubc88\uacfc \uac70\uc758 \uac19\uc740 \uc704\uce58\uc774\uace0 \uc5b4\uc81c\ubd80\ud130 \ub2e4\uc2dc \ubc1c\uc0dd\ud588\uc2b5\ub2c8\ub2e4. \uc0c1\ud669\uc744 \ud655\uc778\ud560 \uc218 \uc788\ub3c4\ub85d \uc601\uc0c1\uc744 \ucc0d\uc5b4 \ub450\uc5c8\uc2b5\ub2c8\ub2e4. \ub2e8\uc21c\ud788 \ub2e6\ub294 \uac83\ubcf4\ub2e4 \uc6d0\uc778\uc744 \ub2e4\uc2dc \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc744 \uac83 \uac19\uc544\uc11c \uc7ac\uc810\uac80\uc744 \uc694\uccad\ub4dc\ub9ac\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.")
A.hST=s([A.cgG,A.chF,A.chz,A.cgM],t.uf)
A.iSt=s(["\ubb38\uc81c \uc704\uce58\ub97c \uc4f0\uc138\uc694.","\ubc1c\uc0dd \uc2dc\uc810\uc744 \uc4f0\uc138\uc694.","\uc99d\uc0c1\uc744 \uc4f0\uc138\uc694.","\ud604\uc7ac \uc0ac\uc6a9 \uac00\ub2a5 \uc5ec\ubd80\ub97c \uc4f0\uc138\uc694.","\uc0ac\uc9c4\uc774\ub098 \uae30\ub85d\uc744 \uc4f0\uc138\uc694.","\uc810\uac80 \uc694\uccad\uc744 \uc4f0\uc138\uc694.","V-\uae30 \uc2dc\uc791\ud558\ub2e4\uc640 V-\uc544/\uc5b4 \uc8fc\uc2e4 \uc218 \uc788\uc744\uae4c\uc694?\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cud=new B.cN("\uc9d1 \uc548 \uc2dc\uc124 \ubb38\uc81c\uac00 \uc0dd\uacbc\uc744 \ub54c \ubb38\uc81c\ub97c \uc804\ub2ec\ud558\ub294 \ubc29\ubc95\uc744 \uc368 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft c\xe1ch truy\u1ec1n \u0111\u1ea1t khi thi\u1ebft b\u1ecb/c\u01a1 s\u1edf v\u1eadt ch\u1ea5t trong nh\xe0 c\xf3 v\u1ea5n \u0111\u1ec1.",A.iSt,"\uc9d1 \uc548 \uc2dc\uc124\uc5d0 \ubb38\uc81c\uac00 \uc0dd\uacbc\uc744 \ub54c\ub294 \ub2e8\uc21c\ud788 \u201c\uace0\uc7a5 \ub0ac\ub2e4\u201d\uace0 \ub9d0\ud558\uae30\ubcf4\ub2e4 \ud604\uc7ac \uc0c1\ud669\uc744 \uad6c\uccb4\uc801\uc73c\ub85c \uc124\uba85\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc5b4\uc81c\ubd80\ud130 \ubcf4\uc77c\ub7ec\uac00 \uc791\ub3d9\ud558\uc9c0 \uc54a\uae30 \uc2dc\uc791\ud588\ub2e4\uba74 \uc5b8\uc81c\ubd80\ud130 \ubb38\uc81c\uac00 \uc0dd\uacbc\ub294\uc9c0\uc640 \ub09c\ubc29, \uc628\uc218 \uc911 \uc5b4\ub5a4 \uae30\ub2a5\uc774 \ub418\uc9c0 \uc54a\ub294\uc9c0 \uc124\uba85\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc624\ub958 \ud45c\uc2dc\ub098 \uc774\uc0c1\ud55c \uc18c\ub9ac\uac00 \uc788\ub2e4\uba74 \uadf8 \ub0b4\uc6a9\ub3c4 \uac19\uc774 \uc54c\ub824 \uc8fc\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \uc0ac\uc9c4\uc774\ub098 \uc601\uc0c1\uc744 \ucc0d\uc5b4 \ub450\uba74 \uc0c1\ub300\ubc29\uc774 \uc0c1\ud669\uc744 \uc774\ud574\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9\uc73c\ub85c \u201c\uac00\ub2a5\ud55c \uc2dc\uac04\uc5d0 \uc0c1\ud0dc\ub97c \ud655\uc778\ud574 \uc8fc\uc2e4 \uc218 \uc788\uc744\uae4c\uc694?\u201d\ucc98\ub7fc \ud544\uc694\ud55c \uc870\uce58\ub97c \uad6c\uccb4\uc801\uc73c\ub85c \uc694\uccad\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","Khi thi\u1ebft b\u1ecb trong nh\xe0 c\xf3 v\u1ea5n \u0111\u1ec1, thay v\xec ch\u1ec9 n\xf3i \u201cb\u1ecb h\u1ecfng\u201d, n\xean gi\u1ea3i th\xedch c\u1ee5 th\u1ec3 t\xecnh tr\u1ea1ng hi\u1ec7n t\u1ea1i. V\xed d\u1ee5 n\u1ebfu h\u1ec7 th\u1ed1ng s\u01b0\u1edfi b\u1eaft \u0111\u1ea7u kh\xf4ng ho\u1ea1t \u0111\u1ed9ng t\u1eeb h\xf4m qua, c\xf3 th\u1ec3 n\xf3i t\u1eeb khi n\xe0o v\u1ea5n \u0111\u1ec1 ph\xe1t sinh v\xe0 ch\u1ee9c n\u0103ng n\xe0o gi\u1eefa s\u01b0\u1edfi v\xe0 n\u01b0\u1edbc n\xf3ng kh\xf4ng ho\u1ea1t \u0111\u1ed9ng. N\u1ebfu c\xf3 b\xe1o l\u1ed7i ho\u1eb7c ti\u1ebfng b\u1ea5t th\u01b0\u1eddng c\u0169ng n\xean n\xf3i c\xf9ng. Ch\u1ee5p \u1ea3nh ho\u1eb7c video s\u1ebd gi\xfap \u0111\u1ed1i ph\u01b0\u01a1ng hi\u1ec3u t\xecnh tr\u1ea1ng h\u01a1n. Cu\u1ed1i c\xf9ng c\xf3 th\u1ec3 y\xeau c\u1ea7u c\u1ee5 th\u1ec3 h\xe0nh \u0111\u1ed9ng c\u1ea7n thi\u1ebft b\u1eb1ng c\xe2u nh\u01b0 \u201cAnh/ch\u1ecb c\xf3 th\u1ec3 ki\u1ec3m tra t\xecnh tr\u1ea1ng v\xe0o th\u1eddi gian ph\xf9 h\u1ee3p kh\xf4ng?\u201d.")
A.h0J=s(["\ubc18\ubcf5 \uc0c1\ud669\uc744 \uc4f0\uc138\uc694.","\uae30\ub85d\uc758 \ud544\uc694\uc131\uc744 \uc4f0\uc138\uc694.","\uc774\uc804 \uc218\ub9ac \ub0b4\uc6a9\uc744 \uc4f0\uc138\uc694.","\uc7ac\uc810\uac80 \uc694\uccad\uc744 \uc4f0\uc138\uc694.","\uc6d0\uc778 \ud655\uc778\uc744 \uc4f0\uc138\uc694.","V-(\uc73c)\u3134 \ud6c4\uc5d0\ub3c4\uacfc V-(\uc73c)\u3139 \ub54c\ub9c8\ub2e4\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cuy=new B.cN("\ubc18\ubcf5\ub418\ub294 \uc8fc\uac70 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub294 \ubc29\ubc95\uc5d0 \ub300\ud574 \uc368 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft c\xe1ch gi\u1ea3i quy\u1ebft v\u1ea5n \u0111\u1ec1 nh\xe0 \u1edf l\u1eb7p \u0111i l\u1eb7p l\u1ea1i.",A.h0J,"\uac19\uc740 \uc8fc\uac70 \ubb38\uc81c\uac00 \ubc18\ubcf5\ub420 \ub54c\ub294 \uadf8\ub54c\ub9c8\ub2e4 \uc784\uc2dc\ub85c \ud574\uacb0\ud558\uae30\ubcf4\ub2e4 \uc6d0\uc778\uc744 \ub2e4\uc2dc \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc2f1\ud06c\ub300\ub97c \uc218\ub9ac\ud55c \ud6c4\uc5d0\ub3c4 \ubb3c\uc744 \ub9ce\uc774 \uc0ac\uc6a9\ud560 \ub54c\ub9c8\ub2e4 \ub204\uc218\uac00 \ubc1c\uc0dd\ud55c\ub2e4\uba74 \uc9c0\ub09c \uc218\ub9ac \ub0a0\uc9dc\uc640 \ud604\uc7ac \ub204\uc218\uac00 \uc0dd\uae30\ub294 \uc870\uac74\uc744 \ud568\uaed8 \uae30\ub85d\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \uc0ac\uc9c4\uacfc \uc601\uc0c1\uc744 \ub0a8\uae30\uace0 \uc9c0\ub09c\ubc88\uacfc \uac19\uc740 \uc704\uce58\uc778\uc9c0\ub3c4 \ud655\uc778\ud558\uba74 \uc7ac\uc810\uac80\uc744 \uc694\uccad\ud560 \ub54c \uc0c1\ud669\uc744 \uc124\uba85\ud558\uae30 \uc27d\uc2b5\ub2c8\ub2e4. \ub610\ud55c \uc218\ub9ac \ud6c4\uc5d0\ub294 \ubc14\ub85c \ub05d\ub0ac\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \ub9d0\uace0 \uba70\uce60 \ub3d9\uc548 \uac19\uc740 \ubb38\uc81c\uac00 \uc7ac\ubc1c\ud558\uc9c0 \uc54a\ub294\uc9c0 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","Khi c\xf9ng v\u1ea5n \u0111\u1ec1 nh\xe0 \u1edf l\u1eb7p l\u1ea1i, thay v\xec m\u1ed7i l\u1ea7n ch\u1ec9 x\u1eed l\xfd t\u1ea1m th\u1eddi c\u1ea7n x\xe1c \u0111\u1ecbnh l\u1ea1i nguy\xean nh\xe2n. V\xed d\u1ee5 ngay c\u1ea3 sau khi s\u1eeda b\u1ed3n r\u1eeda, n\u1ebfu m\u1ed7i khi d\xf9ng nhi\u1ec1u n\u01b0\u1edbc l\u1ea1i b\u1ecb r\xf2 th\xec n\xean ghi c\u1ea3 ng\xe0y s\u1eeda l\u1ea7n tr\u01b0\u1edbc v\xe0 \u0111i\u1ec1u ki\u1ec7n hi\u1ec7n t\u1ea1i khi r\xf2 x\u1ea3y ra. L\u01b0u \u1ea3nh v\xe0 video, \u0111\u1ed3ng th\u1eddi x\xe1c nh\u1eadn c\xf3 c\xf9ng v\u1ecb tr\xed v\u1edbi l\u1ea7n tr\u01b0\u1edbc kh\xf4ng s\u1ebd gi\xfap gi\u1ea3i th\xedch d\u1ec5 h\u01a1n khi y\xeau c\u1ea7u ki\u1ec3m tra l\u1ea1i. Ngo\xe0i ra sau s\u1eeda kh\xf4ng n\xean ngh\u0129 \u0111\xe3 k\u1ebft th\xfac ngay m\xe0 n\xean ki\u1ec3m tra v\xe0i ng\xe0y xem c\xf9ng v\u1ea5n \u0111\u1ec1 c\xf3 t\xe1i di\u1ec5n kh\xf4ng.")
A.h1G=s(["\uacf5\uc6a9 \uacf5\uac04\uc744 \uc4f0\uc138\uc694.","\uc18c\uc74c\uc744 \uc4f0\uc138\uc694.","\uc4f0\ub808\uae30\uc640 \ubd84\ub9ac\ubc30\ucd9c\uc744 \uc4f0\uc138\uc694.","\uc2dc\uc124 \ubb38\uc81c\ub97c \uc4f0\uc138\uc694.","\uc774\uc6c3 \ubc30\ub824\ub97c \uc4f0\uc138\uc694.","\ubb38\uc81c \ud574\uacb0 \ubc29\ubc95\uc744 \uc4f0\uc138\uc694.","V-\ub3c4\ub85d \uc694\uccad\ud558\ub2e4\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cuN=new B.cN("\uc88b\uc740 \uc8fc\uac70 \ud658\uacbd\uc744 \uc720\uc9c0\ud558\uae30 \uc704\ud574 \ud544\uc694\ud55c \uc0dd\ud65c \ud0dc\ub3c4\uc5d0 \ub300\ud574 \uc368 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft v\u1ec1 th\xe1i \u0111\u1ed9 sinh ho\u1ea1t c\u1ea7n thi\u1ebft \u0111\u1ec3 duy tr\xec m\xf4i tr\u01b0\u1eddng s\u1ed1ng t\u1ed1t.",A.h1G,"\uc88b\uc740 \uc8fc\uac70 \ud658\uacbd\uc744 \uc720\uc9c0\ud558\ub824\uba74 \uc790\uc2e0\uc758 \uc9d1 \uc548\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ud568\uaed8 \uc0ac\uc6a9\ud558\ub294 \uacf5\uac04\ub3c4 \ubc30\ub824\ud574\uc57c \ud569\ub2c8\ub2e4. \ubcf5\ub3c4\ub098 \uacc4\ub2e8 \uac19\uc740 \uacf5\uc6a9 \uacf5\uac04\uc5d0 \uac1c\uc778 \ubb3c\uac74\uc744 \uc624\ub798 \ub450\uc9c0 \uc54a\uace0 \uac74\ubb3c\uc5d0\uc11c \uc815\ud55c \uc4f0\ub808\uae30\uc640 \ubd84\ub9ac\ubc30\ucd9c \ubc29\ubc95\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \ub2a6\uc740 \uc2dc\uac04\uc5d0\ub294 \ub2e4\ub978 \uc8fc\ubbfc\uc5d0\uac8c \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub294 \ud070 \uc18c\uc74c\uc744 \uc904\uc774\ub824\uace0 \ub178\ub825\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uc2dc\uc124\uc5d0 \ubb38\uc81c\uac00 \uc0dd\uae30\uba74 \uadf8\ub0e5 \ubc29\uce58\ud558\uae30\ubcf4\ub2e4 \uad00\ub9ac\uc2e4\uc774\ub098 \uad00\ub828\uc790\uc5d0\uac8c \uc815\ud655\ud55c \uc0c1\ud669\uc744 \uc54c\ub824\uc57c \ud569\ub2c8\ub2e4. \ubb38\uc81c\uac00 \ubc18\ubcf5\ub420 \uacbd\uc6b0\uc5d0\ub294 \ub204\uad6c\uc758 \uc798\ubabb\uc778\uc9c0 \uba3c\uc800 \ub530\uc9c0\uae30\ubcf4\ub2e4 \uc0c1\ud669\uc744 \uae30\ub85d\ud558\uace0 \uac19\uc740 \ubb38\uc81c\uac00 \ubc18\ubcf5\ub418\uc9c0 \uc54a\ub3c4\ub85d \ud544\uc694\ud55c \uc870\uce58\ub97c \uc694\uccad\ud558\ub294 \uac83\uc774 \ub354 \ud6a8\uacfc\uc801\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.","\u0110\u1ec3 duy tr\xec m\xf4i tr\u01b0\u1eddng s\u1ed1ng t\u1ed1t, kh\xf4ng ch\u1ec9 c\u1ea7n ch\xfa \xfd b\xean trong nh\xe0 m\xecnh m\xe0 c\xf2n ph\u1ea3i c\xe2n nh\u1eafc nh\u1eefng kh\xf4ng gian nhi\u1ec1u ng\u01b0\u1eddi c\xf9ng s\u1eed d\u1ee5ng. Kh\xf4ng n\xean \u0111\u1ec3 \u0111\u1ed3 c\xe1 nh\xe2n l\xe2u \u1edf h\xe0nh lang ho\u1eb7c c\u1ea7u thang v\xe0 n\xean ki\u1ec3m tra c\xe1ch \u0111\u1ed5 r\xe1c, ph\xe2n lo\u1ea1i r\xe1c do t\xf2a nh\xe0 quy \u0111\u1ecbnh. V\xe0o gi\u1edd mu\u1ed9n c\u0169ng c\u1ea7n c\u1ed1 gi\u1ea3m ti\u1ebfng \u1ed3n l\u1edbn c\xf3 th\u1ec3 \u1ea3nh h\u01b0\u1edfng c\u01b0 d\xe2n kh\xe1c. Khi c\u01a1 s\u1edf v\u1eadt ch\u1ea5t c\xf3 v\u1ea5n \u0111\u1ec1, thay v\xec b\u1ecf m\u1eb7c c\u1ea7n truy\u1ec1n \u0111\u1ea1t t\xecnh tr\u1ea1ng ch\xednh x\xe1c cho ban qu\u1ea3n l\xfd ho\u1eb7c ng\u01b0\u1eddi li\xean quan. N\u1ebfu v\u1ea5n \u0111\u1ec1 l\u1eb7p l\u1ea1i, t\xf4i ngh\u0129 ghi l\u1ea1i t\xecnh h\xecnh v\xe0 y\xeau c\u1ea7u bi\u1ec7n ph\xe1p \u0111\u1ec3 v\u1ea5n \u0111\u1ec1 kh\xf4ng t\xe1i di\u1ec5n s\u1ebd hi\u1ec7u qu\u1ea3 h\u01a1n vi\u1ec7c tranh c\xe3i l\u1ed7i c\u1ee7a ai tr\u01b0\u1edbc.")
A.ivA=s([A.cud,A.cuy,A.cuN],t.l5)
