A.chm=new B.c7("\ucd5c\uadfc \uc790\uc2e0\uc758 \uac74\uac15 \uc0c1\ud0dc\uc640 \uc0dd\ud65c \uc2b5\uad00\uc744 \uc124\uba85\ud574 \ubcf4\uc138\uc694.",A.fLn,"\ucd5c\uadfc\uc5d0\ub294 \uadfc\ubb34 \uc2dc\uac04\uc774 \ub2ec\ub77c\uc9c0\uba74\uc11c \uc218\uba74 \uc2dc\uac04\uc774 \uc870\uae08 \ubd88\uaddc\uce59\ud574\uc84c\uc2b5\ub2c8\ub2e4. \ud2b9\ud788 \uc57c\uac04 \uadfc\ubb34\ub97c \ud55c \ud6c4\uc5d0\ub294 \ub0ae\uc5d0 \uc624\ub798 \uc790\ub294 \ud3b8\uc774\ub77c \ub2e4\uc74c \ub0a0 \ub2e4\uc2dc \uc77c\ucc0d \uc790\uae30\uac00 \uc5b4\ub835\uc2b5\ub2c8\ub2e4. \uc2dd\uc0ac\ub3c4 \ubc14\uc060 \ub54c\ub294 \ub2a6\uac8c \ud558\ub294 \uacbd\uc6b0\uac00 \uc788\uace0 \ud53c\uace4\ud560 \ub54c \ucee4\ud53c\ub97c \uc790\uc8fc \ub9c8\uc2dc\ub294 \ud3b8\uc785\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc694\uc998\uc740 \uc218\uba74 \uc2dc\uac04\uacfc \uce74\ud398\uc778\uc744 \ub9c8\uc2e0 \uc2dc\uac04\uc744 \uae30\ub85d\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc6b0\uc120 \uc790\uae30 \uc804\uc5d0\ub294 \ud734\ub300\ud3f0\uc744 \ubcf4\ub294 \uc2dc\uac04\uc744 \uc904\uc774\uace0 \ud734\uc77c\uc5d0\ub3c4 \uae30\uc0c1 \uc2dc\uac04\uc774 \ub108\ubb34 \ub2ec\ub77c\uc9c0\uc9c0 \uc54a\ub3c4\ub85d \ud574 \ubcf4\ub824\uace0 \ud569\ub2c8\ub2e4.")
A.fKb=s(["\ud604\uc7ac \uc0c1\ud0dc","\uc5b8\uc81c\ubd80\ud130","\uc9d1\uc911\ub825","\uac00\ub2a5\ud55c \uc5c5\ubb34","\uc704\ud5d8 \uc791\uc5c5","\uc870\uc815 \uc694\uccad"],t.s)
A.cgF=new B.c7("\ubab8 \uc0c1\ud0dc \ub54c\ubb38\uc5d0 \uc5c5\ubb34 \uc870\uc815\uc774 \ud544\uc694\ud560 \ub54c \ud300\uc7a5\uc5d0\uac8c \ub9d0\ud574 \ubcf4\uc138\uc694.",A.fKb,"\ud300\uc7a5\ub2d8, \uc624\ub298 \uc5c5\ubb34\uc5d0 \ub300\ud574 \uc7a0\uae50 \ub9d0\uc500\ub4dc\ub9ac\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \uc624\ub298 \uc544\uce68\ubd80\ud130 \uc5b4\uc9c0\ub7ec\uc6b4 \ub290\ub08c\uc774 \uc788\uace0 \ud3c9\uc18c\ubcf4\ub2e4 \uc9d1\uc911\ud558\uae30 \uc5b4\ub824\uc6b4 \uc0c1\ud0dc\uc785\ub2c8\ub2e4. \ub2e8\uc21c\ud55c \uc815\ub9ac\ub098 \ud655\uc778 \uc5c5\ubb34\ub294 \ud560 \uc218 \uc788\uc9c0\ub9cc \ud604\uc7ac \uc0c1\ud0dc\uc5d0\uc11c \uc704\ud5d8\ud55c \uc124\ube44 \uc791\uc5c5\uc744 \ubb34\ub9ac\ud574\uc11c \ud558\ub294 \uac83\uc740 \uc88b\uc9c0 \uc54a\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \uc6b0\uc120 \uc7a0\uae50 \uc26c\uba74\uc11c \uc0c1\ud0dc\ub97c \ud655\uc778\ud558\uace0 \uac00\ub2a5\ud558\ub2e4\uba74 \uc624\ub298 \uc791\uc5c5 \uc21c\uc11c\ub97c \uc77c\ubd80 \uc870\uc815\ud560 \uc218 \uc788\uc744\uae4c\uc694? \uc0c1\ud0dc\uac00 \ub098\uc544\uc9c0\uba74 \ub2e4\uc2dc \ub9d0\uc500\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.")
A.hr5=s(["\ud604\uc7ac \uc2b5\uad00","\ubb38\uc81c","\uc791\uc740 \ubaa9\ud45c","\uae30\uac04","\uae30\ub85d","\uacb0\uacfc \ud655\uc778"],t.s)
A.chI=new B.c7("\ud55c \uac00\uc9c0 \uc0dd\ud65c \uc2b5\uad00\uc744 \uac1c\uc120\ud558\uae30 \uc704\ud55c \uacc4\ud68d\uc744 \ub9d0\ud574 \ubcf4\uc138\uc694.",A.hr5,"\uc81c\uac00 \uac00\uc7a5 \uba3c\uc800 \ubc14\uafb8\uace0 \uc2f6\uc740 \uc2b5\uad00\uc740 \uc790\uae30 \uc804\uc5d0 \ud734\ub300\ud3f0\uc744 \uc624\ub798 \ubcf4\ub294 \uac83\uc785\ub2c8\ub2e4. \ud53c\uace4\ud574\ub3c4 \uacc4\uc18d \uc601\uc0c1\uc744 \ubcf4\ub2e4 \ubcf4\ub2c8 \uc2e4\uc81c\ub85c \uc7a0\ub4dc\ub294 \uc2dc\uac04\uc774 \ub2a6\uc5b4\uc9c0\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc558\uc2b5\ub2c8\ub2e4. \ucc98\uc74c\ubd80\ud130 \ud734\ub300\ud3f0\uc744 \uc644\uc804\ud788 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uae30\ubcf4\ub2e4\ub294 \uc77c\ub2e8 2\uc8fc \ub3d9\uc548 \uc790\uae30 30\ubd84 \uc804\uc5d0\ub294 \ud734\ub300\ud3f0\uc744 \ubcf4\uc9c0 \uc54a\ub294 \uac83\uc744 \ubaa9\ud45c\ub85c \ud558\uaca0\uc2b5\ub2c8\ub2e4. \ub9e4\uc77c \uc7a0\ub4e0 \uc2dc\uac04\uacfc \ub2e4\uc74c \ub0a0 \ucee8\ub514\uc158\uc744 \uac04\ub2e8\ud788 \uae30\ub85d\ud55c \ud6c4 2\uc8fc \ub4a4\uc5d0 \ubcc0\ud654\uac00 \uc788\ub294\uc9c0 \ud655\uc778\ud558\uaca0\uc2b5\ub2c8\ub2e4.")
A.fW5=s(["\uad50\ub300 \uadfc\ubb34","\uc218\uba74","\uc2dd\uc0ac","\ud734\uc2dd","\uae30\ub85d","\ucee8\ub514\uc158"],t.s)
A.cgU=new B.c7("\uad50\ub300 \uadfc\ubb34 \uc911 \uac74\uac15 \uad00\ub9ac\ub97c \uc5b4\ub5bb\uac8c \ud560\uc9c0 \uc124\uba85\ud574 \ubcf4\uc138\uc694.",A.fW5,"\uad50\ub300 \uadfc\ubb34\ub97c \ud558\uba74 \ub9e4\uc77c \uac19\uc740 \uc2dc\uac04\uc5d0 \uc0dd\ud65c\ud558\uae30\ub294 \uc5b4\ub835\uc9c0\ub9cc \uac00\ub2a5\ud55c \ubc94\uc704 \uc548\uc5d0\uc11c \uc77c\uc815\ud55c \uae30\uc900\uc744 \ub9cc\ub4e4\ub824\uace0 \ud569\ub2c8\ub2e4. \uadfc\ubb34\uac00 \ubc14\ub014 \ub54c\ub9c8\ub2e4 \uc218\uba74 \uc2dc\uac04\uc744 \uae30\ub85d\ud558\uace0 \ub108\ubb34 \ubd80\uc871\ud574\uc9c0\uc9c0 \uc54a\ub3c4\ub85d \uc26c\ub294 \uc2dc\uac04\uc744 \uc870\uc815\ud558\uaca0\uc2b5\ub2c8\ub2e4. \ubc14\uc058\ub354\ub77c\ub3c4 \uc2dd\uc0ac\ub97c \uacc4\uc18d \uac70\ub974\uc9c0 \uc54a\uace0 \ubb3c\ub3c4 \ucc59\uaca8 \ub9c8\uc2dc\ub824\uace0 \ud569\ub2c8\ub2e4. \ub610\ud55c \ud53c\ub85c\uac00 \ub9ce\uc774 \uc313\uc774\uac70\ub098 \uc9d1\uc911\ub825\uc774 \ud06c\uac8c \ub5a8\uc5b4\uc9c0\ub294 \ub0a0\uc5d0\ub294 \ubb34\ub9ac\ud574\uc11c \uc704\ud5d8\ud55c \uc791\uc5c5\uc744 \ud558\uc9c0 \uc54a\ub3c4\ub85d \ud604\uc7ac \uc0c1\ud0dc\ub97c \uba3c\uc800 \ud655\uc778\ud558\uaca0\uc2b5\ub2c8\ub2e4.")
A.hCf=s([A.chm,A.cgF,A.chI,A.cgU],t.uf)
A.iQW=s(["\ud604\uc7ac \uc0dd\ud65c \uc2b5\uad00\uc744 \uc4f0\uc138\uc694.","\ubb38\uc81c\uc810\uc744 \uc4f0\uc138\uc694.","\uc218\uba74 \ub610\ub294 \uc2dd\uc2b5\uad00\uc744 \uc4f0\uc138\uc694.","\uc791\uc740 \ubaa9\ud45c\ub97c \uc815\ud558\uc138\uc694.","\uae30\ub85d \ubc29\ubc95\uc744 \uc4f0\uc138\uc694.","V-\ub2e4 \ubcf4\ub2c8\uc640 V-\uc9c0 \uc54a\ub3c4\ub85d\uc744 \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cuL=new B.cN("\uac74\uac15\ud55c \uc0dd\ud65c \uc2b5\uad00\uc744 \ub9cc\ub4e4\uae30 \uc704\ud55c \uc790\uc2e0\uc758 \uacc4\ud68d\uc744 \uc368 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft k\u1ebf ho\u1ea1ch x\xe2y d\u1ef1ng th\xf3i quen sinh ho\u1ea1t l\xe0nh m\u1ea1nh c\u1ee7a b\u1ea3n th\xe2n.",A.iQW,"\ucd5c\uadfc\uc5d0\ub294 \ud1f4\uadfc \ud6c4 \ud734\ub300\ud3f0\uc744 \uc624\ub798 \ubcf4\ub2e4 \ubcf4\ub2c8 \uc7a0\ub4dc\ub294 \uc2dc\uac04\uc774 \uacc4\uc18d \ub2a6\uc5b4\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc544\uce68\uc5d0 \ud53c\uace4\ud574\uc11c \uc2dd\uc0ac\ub97c \uac70\ub974\ub294 \ub0a0\ub3c4 \uc788\uace0 \uc624\ud6c4\uc5d0\ub294 \uc9d1\uc911\ub825\uc774 \ub5a8\uc5b4\uc9c0\ub294 \uacbd\uc6b0\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \ud55c\uaebc\ubc88\uc5d0 \ubaa8\ub4e0 \uc0dd\ud65c \uc2b5\uad00\uc744 \ubc14\uafb8\uae30\ubcf4\ub2e4 \uba3c\uc800 \uc218\uba74 \uc2b5\uad00\ubd80\ud130 \ubc14\uafb8\ub824\uace0 \ud569\ub2c8\ub2e4. \uc55e\uc73c\ub85c 2\uc8fc \ub3d9\uc548 \uc790\uae30 30\ubd84 \uc804\uc5d0\ub294 \ud734\ub300\ud3f0\uc744 \ubcf4\uc9c0 \uc54a\uace0 \uc218\uba74 \uc2dc\uac04\uc774 \ub108\ubb34 \ubd80\uc871\ud574\uc9c0\uc9c0 \uc54a\ub3c4\ub85d \uc77c\uc815\ud55c \uc2dc\uac04\uc5d0 \ub204\uc6cc \ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \ub9e4\uc77c \uc7a0\ub4e0 \uc2dc\uac04, \uc77c\uc5b4\ub09c \uc2dc\uac04\uacfc \ub2e4\uc74c \ub0a0 \ucee8\ub514\uc158\uc744 \uae30\ub85d\ud574\uc11c \uc2e4\uc81c\ub85c \ubcc0\ud654\uac00 \uc788\ub294\uc9c0 \ud655\uc778\ud560 \uacc4\ud68d\uc785\ub2c8\ub2e4.","G\u1ea7n \u0111\xe2y do s\u1eed d\u1ee5ng \u0111i\u1ec7n tho\u1ea1i l\xe2u sau gi\u1edd l\xe0m n\xean gi\u1edd ng\u1ee7 c\u1ee7a t\xf4i li\xean t\u1ee5c b\u1ecb mu\u1ed9n. C\xf3 nh\u1eefng ng\xe0y bu\u1ed5i s\xe1ng m\u1ec7t n\xean b\u1ecf b\u1eefa v\xe0 bu\u1ed5i chi\u1ec1u kh\u1ea3 n\u0103ng t\u1eadp trung gi\u1ea3m. V\xec v\u1eady thay v\xec thay \u0111\u1ed5i to\xe0n b\u1ed9 th\xf3i quen c\xf9ng l\xfac, tr\u01b0\u1edbc ti\xean t\xf4i mu\u1ed1n thay \u0111\u1ed5i th\xf3i quen ng\u1ee7. Trong hai tu\u1ea7n t\u1edbi t\xf4i s\u1ebd kh\xf4ng d\xf9ng \u0111i\u1ec7n tho\u1ea1i 30 ph\xfat tr\u01b0\u1edbc khi ng\u1ee7 v\xe0 c\u1ed1 n\u1eb1m ng\u1ee7 v\xe0o gi\u1edd t\u01b0\u01a1ng \u0111\u1ed1i \u1ed5n \u0111\u1ecbnh \u0111\u1ec3 th\u1eddi gian ng\u1ee7 kh\xf4ng b\u1ecb thi\u1ebfu qu\xe1 nhi\u1ec1u. T\xf4i d\u1ef1 \u0111\u1ecbnh ghi m\u1ed7i ng\xe0y gi\u1edd ng\u1ee7, gi\u1edd th\u1ee9c v\xe0 th\u1ec3 tr\u1ea1ng h\xf4m sau \u0111\u1ec3 ki\u1ec3m tra xem c\xf3 thay \u0111\u1ed5i th\u1ef1c s\u1ef1 kh\xf4ng.")
A.i97=s(["\uadfc\ubb34 \uc2dc\uac04 \ubcc0\ud654\ub97c \uc4f0\uc138\uc694.","\uc218\uba74\uc744 \uc4f0\uc138\uc694.","\uc2dd\uc0ac\ub97c \uc4f0\uc138\uc694.","\ud734\uc2dd\uc744 \uc4f0\uc138\uc694.","\ucee8\ub514\uc158 \ud655\uc778\uc744 \uc4f0\uc138\uc694.","V-(\uc73c)\u3139 \ub54c\ub9c8\ub2e4\uc640 V/A-\ub354\ub77c\ub3c4\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cua=new B.cN("\uad50\ub300 \uadfc\ubb34\ub97c \ud558\ub294 \uc0ac\ub78c\uc774 \uc0dd\ud65c \ub9ac\ub4ec\uc744 \uad00\ub9ac\ud558\ub294 \ubc29\ubc95\uc5d0 \ub300\ud574 \uc368 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft c\xe1ch ng\u01b0\u1eddi l\xe0m theo ca c\xf3 th\u1ec3 qu\u1ea3n l\xfd nh\u1ecbp sinh ho\u1ea1t.",A.i97,"\uad50\ub300 \uadfc\ubb34\ub97c \ud558\uba74 \uc8fc\uac04\uacfc \uc57c\uac04 \uc77c\uc815\uc774 \ubc14\ub014 \ub54c\ub9c8\ub2e4 \uc218\uba74 \uc2dc\uac04\uacfc \uc2dd\uc0ac \uc2dc\uac04\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub9e4\uc77c \uac19\uc740 \uc2dc\uac04\uc5d0 \uc0dd\ud65c\ud558\uae30\ub294 \uc5b4\ub835\ub354\ub77c\ub3c4 \uac00\ub2a5\ud55c \ubc94\uc704 \uc548\uc5d0\uc11c \uc790\uc2e0\ub9cc\uc758 \uae30\uc900\uc744 \ub9cc\ub4dc\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uadfc\ubb34 \uc77c\uc815\uc774 \ubc14\ub014 \ub54c\ub9c8\ub2e4 \uc218\uba74 \uc2dc\uac04\uc744 \uae30\ub85d\ud558\uace0 \ub108\ubb34 \ubd80\uc871\ud574\uc9c0\ub294 \ub0a0\uc774 \ubc18\ubcf5\ub418\uc9c0 \uc54a\ub294\uc9c0 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc5c5\ubb34\uac00 \ubc14\uc058\ub354\ub77c\ub3c4 \uc2dd\uc0ac\ub97c \uacc4\uc18d \uac70\ub974\uc9c0 \uc54a\uace0 \uc26c\ub294 \uc2dc\uac04\uc5d0\ub294 \uac00\ub2a5\ud55c \ud55c \ubab8\uc744 \uc26c\uac8c \ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \ub610\ud55c \ud53c\ub85c\uac00 \uc2ec\ud558\uac70\ub098 \uc9d1\uc911\ub825\uc774 \ub9ce\uc774 \ub5a8\uc5b4\uc9c0\ub294 \ub0a0\uc5d0\ub294 \ubb34\ub9ac\ud558\uc9c0 \uc54a\uace0 \uc790\uc2e0\uc758 \ucee8\ub514\uc158\uc744 \uba3c\uc800 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.","Khi l\xe0m theo ca, m\u1ed7i khi l\u1ecbch ca ng\xe0y v\xe0 ca \u0111\xeam thay \u0111\u1ed5i th\xec gi\u1edd ng\u1ee7 v\xe0 gi\u1edd \u0103n c\u0169ng c\xf3 th\u1ec3 thay \u0111\u1ed5i. D\xf9 kh\xf3 sinh ho\u1ea1t c\xf9ng gi\u1edd m\u1ed7i ng\xe0y, \u0111i\u1ec1u quan tr\u1ecdng l\xe0 t\u1ea1o ra nguy\xean t\u1eafc c\u1ee7a ri\xeang m\xecnh trong ph\u1ea1m vi c\xf3 th\u1ec3. V\xed d\u1ee5 m\u1ed7i khi l\u1ecbch l\xe0m thay \u0111\u1ed5i c\xf3 th\u1ec3 ghi th\u1eddi gian ng\u1ee7 v\xe0 ki\u1ec3m tra xem nh\u1eefng ng\xe0y thi\u1ebfu ng\u1ee7 qu\xe1 nhi\u1ec1u c\xf3 l\u1eb7p l\u1ea1i kh\xf4ng. D\xf9 c\xf4ng vi\u1ec7c b\u1eadn c\u0169ng kh\xf4ng n\xean li\xean t\u1ee5c b\u1ecf b\u1eefa v\xe0 trong gi\u1edd ngh\u1ec9 n\xean \u0111\u1ec3 c\u01a1 th\u1ec3 ngh\u1ec9 trong kh\u1ea3 n\u0103ng. Ngo\xe0i ra nh\u1eefng ng\xe0y m\u1ec7t nhi\u1ec1u ho\u1eb7c kh\u1ea3 n\u0103ng t\u1eadp trung gi\u1ea3m r\xf5 th\xec c\u1ea7n ki\u1ec3m tra th\u1ec3 tr\u1ea1ng tr\u01b0\u1edbc v\xe0 kh\xf4ng c\u1ed1 qu\xe1 s\u1ee9c.")
A.iQL=s(["\uc99d\uc0c1\uc744 \uc4f0\uc138\uc694.","\ubc1c\uc0dd \uc2dc\uc810\uc744 \uc4f0\uc138\uc694.","\ubc18\ubcf5 \uc5ec\ubd80\ub97c \uc4f0\uc138\uc694.","\uc545\ud654 \ub610\ub294 \ud638\uc804 \uc870\uac74\uc744 \uc4f0\uc138\uc694.","\uae30\ub85d\uc744 \uc4f0\uc138\uc694.","\ud544\uc694\ud55c \uacbd\uc6b0 \uc804\ubb38\uac00 \uc0c1\ub2f4\uc744 \uc4f0\uc138\uc694.","V/A-(\uc73c)\u3134/\ub294 \ub9cc\ud07c\uc744 \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cuC=new B.cN("\ubd88\ud3b8\ud55c \uc99d\uc0c1\uc774 \ubc18\ubcf5\ub420 \ub54c \uc5b4\ub5bb\uac8c \uad00\ub9ac\ud560\uc9c0 \uc368 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft c\xe1ch qu\u1ea3n l\xfd khi m\u1ed9t tri\u1ec7u ch\u1ee9ng kh\xf3 ch\u1ecbu l\u1eb7p l\u1ea1i.",A.iQL,"\ubd88\ud3b8\ud55c \uc99d\uc0c1\uc774 \ubc18\ubcf5\ub420 \ub54c\ub294 \uae30\uc5b5\uc5d0\ub9cc \uc758\uc874\ud558\uae30\ubcf4\ub2e4 \uc5b8\uc81c\ubd80\ud130 \uc5b4\ub5a4 \uc0c1\ud0dc\uac00 \ub098\ud0c0\ub0ac\ub294\uc9c0 \uae30\ub85d\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc5b4\uae68 \ud1b5\uc99d\uc774 \uc788\ub2e4\uba74 \ud558\ub8e8 \uc911 \uc5b8\uc81c \uc2ec\ud574\uc9c0\ub294\uc9c0, \ud2b9\uc815 \uc791\uc5c5\uc744 \ud560 \ub54c\ub9c8\ub2e4 \ubc18\ubcf5\ub418\ub294\uc9c0, \ud734\uc2dd \ud6c4\uc5d0\ub294 \ud638\uc804\ub418\ub294\uc9c0\ub97c \uc815\ub9ac\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubab8\uc744 \ub9ce\uc774 \uc0ac\uc6a9\ud558\ub294 \uc5c5\ubb34\uc778 \ub9cc\ud07c \uc790\uc2e0\uc758 \uc0c1\ud0dc \ubcc0\ud654\ub97c \ubb34\uc2dc\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4. \uc0dd\ud65c \uc2b5\uad00\uc744 \uc870\uc815\ud574\ub3c4 \uc99d\uc0c1\uc774 \uacc4\uc18d\ub418\uac70\ub098 \uc810\uc810 \uc545\ud654\ub41c\ub2e4\uba74 \ud63c\uc790 \uc6d0\uc778\uc744 \ub2e8\uc815\ud558\uae30\ubcf4\ub2e4 \uc815\ud655\ud55c \ud655\uc778\uc744 \uc704\ud574 \uc801\uc808\ud55c \uc804\ubb38\uac00\uc640 \uc0c1\ub2f4\ud558\ub294 \uac83\ub3c4 \uace0\ub824\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","Khi m\u1ed9t tri\u1ec7u ch\u1ee9ng kh\xf3 ch\u1ecbu l\u1eb7p l\u1ea1i, thay v\xec ch\u1ec9 d\u1ef1a v\xe0o tr\xed nh\u1edb, n\xean ghi l\u1ea1i t\xecnh tr\u1ea1ng n\xe0o xu\u1ea5t hi\u1ec7n t\u1eeb khi n\xe0o. V\xed d\u1ee5 n\u1ebfu \u0111au vai, c\xf3 th\u1ec3 t\u1ed5ng h\u1ee3p xem th\u1eddi \u0111i\u1ec3m n\xe0o trong ng\xe0y n\u1eb7ng h\u01a1n, c\xf3 l\u1eb7p l\u1ea1i m\u1ed7i khi l\xe0m m\u1ed9t c\xf4ng vi\u1ec7c c\u1ee5 th\u1ec3 hay kh\xf4ng v\xe0 sau khi ngh\u1ec9 c\xf3 \u0111\u1ee1 kh\xf4ng. V\xec l\xe0 c\xf4ng vi\u1ec7c s\u1eed d\u1ee5ng nhi\u1ec1u c\u01a1 th\u1ec3 n\xean \u0111i\u1ec1u quan tr\u1ecdng l\xe0 kh\xf4ng b\u1ecf qua nh\u1eefng thay \u0111\u1ed5i c\u1ee7a b\u1ea3n th\xe2n. N\u1ebfu \u0111\xe3 \u0111i\u1ec1u ch\u1ec9nh th\xf3i quen m\xe0 tri\u1ec7u ch\u1ee9ng v\u1eabn ti\u1ebfp t\u1ee5c ho\u1eb7c ng\xe0y c\xe0ng n\u1eb7ng, thay v\xec t\u1ef1 k\u1ebft lu\u1eadn nguy\xean nh\xe2n th\xec c\xf3 th\u1ec3 c\xe2n nh\u1eafc trao \u0111\u1ed5i v\u1edbi chuy\xean gia ph\xf9 h\u1ee3p \u0111\u1ec3 \u0111\u01b0\u1ee3c ki\u1ec3m tra ch\xednh x\xe1c.")
