A.chi=new B.c7("\ud68c\uc758\uc5d0\uc11c \uc5c5\ubb34 \uac1c\uc120 \ubc29\uc548\uc744 \uc81c\uc548\ud574 \ubcf4\uc138\uc694.",A.h3b,"\uc81c\uac00 \ubcf4\uae30\uc5d0\ub294 \ud604\uc7ac \uac00\uc7a5 \ud070 \ubb38\uc81c\ub294 \uac80\uc0ac \ub2e8\uacc4\uc5d0\uc11c \ub300\uae30 \uc2dc\uac04\uc774 \uae38\ub2e4\ub294 \uc810\uc785\ub2c8\ub2e4. \ucd5c\uadfc \uc77c\uc8fc\uc77c \uc790\ub8cc\ub97c \ud655\uc778\ud574 \ubcf4\ub2c8 \uc0dd\uc0b0 \uacf5\uc815\uc740 \uc815\uc0c1\uc801\uc73c\ub85c \uc9c4\ud589\ub418\uace0 \uc788\uc9c0\ub9cc \uac80\uc0ac \uc804 \ub300\uae30 \uc2dc\uac04\uc774 \uacc4\uc18d \ub298\uc5b4\ub098\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ubc14\ub85c \uc778\uc6d0\uc744 \ub298\ub9ac\uae30\ubcf4\ub2e4\ub294 \uba3c\uc800 \uac80\uc0ac \uc21c\uc11c\uc640 \uc791\uc5c5 \ubd84\ub2f4\uc744 \uc870\uc815\ud574 \ubcf4\ub294 \uac83\uc774 \uc5b4\ub5a8\uae4c\uc694? \ud55c \uac1c \ub77c\uc778\uc5d0\uc11c \uc77c\uc8fc\uc77c \ub3d9\uc548 \uc2dc\ud5d8 \uc801\uc6a9\ud55c \ud6c4 \ub300\uae30 \uc2dc\uac04\uc774 \uc5bc\ub9c8\ub098 \uc904\uc5b4\ub4dc\ub294\uc9c0 \ud655\uc778\ud558\uba74 \uc88b\uaca0\uc2b5\ub2c8\ub2e4.")
A.h4b=s(["\ub3d9\uc758","\ud558\uc9c0\ub9cc","\ubb38\uc81c\uc810","\uadfc\uac70","\ub300\uc548"],t.s)
A.chr=new B.c7("\ub3d9\ub8cc\uc758 \uc758\uacac\uc5d0 \ubd80\ubd84\uc801\uc73c\ub85c \ubc18\ub300\ud574 \ubcf4\uc138\uc694.",A.h4b,"\uc0dd\uc0b0 \uc18d\ub3c4\ub97c \ub192\uc5ec\uc57c \ud55c\ub2e4\ub294 \uc758\uacac\uc5d0\ub294 \uc800\ub3c4 \ub3d9\uc758\ud569\ub2c8\ub2e4. \ud604\uc7ac \ub0a9\uae30\uae4c\uc9c0 \uc2dc\uac04\uc774 \ub9ce\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \ub77c\uc778\uc758 \uc18d\ub3c4\ub97c \ub3d9\uc2dc\uc5d0 \ub192\uc774\ub294 \uac83\uc740 \ud488\uc9c8 \uce21\uba74\uc5d0\uc11c \uc704\ud5d8\ud560 \uc218 \uc788\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ucd5c\uadfc \uc18d\ub3c4\ub97c \ub192\uc600\uc744 \ub54c \ubd88\ub7c9\uc774 \uc99d\uac00\ud55c \uc0ac\ub840\ub3c4 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc804\uccb4 \ub77c\uc778\uc744 \ud55c\uaebc\ubc88\uc5d0 \ubcc0\uacbd\ud558\uae30\ubcf4\ub2e4\ub294 \ud55c \uac1c \ub77c\uc778\uc5d0\uc11c \uba3c\uc800 \uc2dc\ud5d8\ud558\uace0 \uacb0\uacfc\ub97c \ud655\uc778\ud55c \ud6c4 \ud655\ub300\ud558\ub294 \uac83\uc774 \uc88b\uaca0\uc2b5\ub2c8\ub2e4.")
A.i5r=s(["A \ubc29\uc548","B \ubc29\uc548","\uc7a5\uc810","\ub2e8\uc810","\ube44\uc6a9","\ud6a8\uacfc","\uc120\ud0dd"],t.s)
A.ch8=new B.c7("\ub450 \uac00\uc9c0 \ubc29\uc548\uc744 \ube44\uad50\ud574\uc11c \uc758\uacac\uc744 \ub9d0\ud574 \ubcf4\uc138\uc694.",A.i5r,"A \ubc29\uc548\uc740 \uae30\uc874 \uc124\ube44\ub97c \uadf8\ub300\ub85c \uc0ac\uc6a9\ud558\uae30 \ub54c\ubb38\uc5d0 \ucd94\uac00 \ube44\uc6a9\uc774 \uc801\ub2e4\ub294 \uc7a5\uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc791\uc5c5\uc790\uac00 \uc9c1\uc811 \ud655\uc778\ud574\uc57c \ud558\ub294 \ubd80\ubd84\uc774 \ub9ce\uc544\uc11c \uc2dc\uac04\uc774 \uc624\ub798 \uac78\ub9b4 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubc18\uba74\uc5d0 B \ubc29\uc548\uc740 \uc790\ub3d9\ud654 \uc124\ube44\ub97c \ucd94\uac00\ud574\uc57c \ud574\uc11c \ucd08\uae30 \ube44\uc6a9\uc740 \ub192\uc9c0\ub9cc \uc7a5\uae30\uc801\uc73c\ub85c \uac80\uc0ac \uc2dc\uac04\uc744 \uc904\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ud604\uc7ac \uc608\uc0b0\uc744 \uace0\ub824\ud558\uba74 \ubc14\ub85c B \ubc29\uc548\uc744 \uc801\uc6a9\ud558\uae30\ubcf4\ub2e4\ub294 A \ubc29\uc548\uc744 \uac1c\uc120\ud574\uc11c \uba3c\uc800 \uc0ac\uc6a9\ud558\uace0, \uc7a5\uae30\uc801\uc73c\ub85c \uc790\ub3d9\ud654 \uc124\ube44 \ub3c4\uc785\uc744 \uac80\ud1a0\ud558\ub294 \uac83\uc774 \ud604\uc2e4\uc801\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.")
A.h3q=s(["\uccab\uc9f8","\ub458\uc9f8","\ub2f4\ub2f9\uc790","\uae30\ud55c","\uacb0\uacfc","\ub2e4\uc74c \ud68c\uc758"],t.s)
A.ch_=new B.c7("\ud68c\uc758 \ub9c8\uc9c0\ub9c9\uc5d0 \uacb0\uc815 \uc0ac\ud56d\uc744 \uc815\ub9ac\ud574\uc11c \ub9d0\ud574 \ubcf4\uc138\uc694.",A.h3q,"\uadf8\ub7fc \uc624\ub298 \uacb0\uc815\ub41c \ub0b4\uc6a9\uc744 \uc815\ub9ac\ud558\uaca0\uc2b5\ub2c8\ub2e4. \uccab\uc9f8, \uc774\ubc88 \uc8fc\uc5d0\ub294 \uae30\uc874 \uc791\uc5c5 \uae30\uc900\uc744 \ubc14\ub85c \ubcc0\uacbd\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ub458\uc9f8, \uc0dd\uc0b0\ud300\uacfc \ud488\uc9c8\ud300\uc5d0\uc11c \ucd5c\uadfc \ud55c \ub2ec \ub370\uc774\ud130\ub97c \uac01\uac01 \uc815\ub9ac\ud569\ub2c8\ub2e4. \uc0dd\uc0b0 \uc790\ub8cc\ub294 \ubbfc\uc218 \uc528\uac00 \ub2f4\ub2f9\ud558\uace0 \ud488\uc9c8 \uc790\ub8cc\ub294 \uc81c\uac00 \uc900\ube44\ud558\uaca0\uc2b5\ub2c8\ub2e4. \uc790\ub8cc\ub294 \ubaa9\uc694\uc77c \uc624\ud6c4\uae4c\uc9c0 \uc644\ub8cc\ud558\uace0 \uae08\uc694\uc77c \uc624\uc804 \ud68c\uc758\uc5d0\uc11c \ub450 \uacb0\uacfc\ub97c \ube44\uad50\ud558\uaca0\uc2b5\ub2c8\ub2e4. \uadf8 \uacb0\uacfc\ub97c \ubc14\ud0d5\uc73c\ub85c \ub2e4\uc74c \uc8fc \uc801\uc6a9\ud560 \uac1c\uc120 \ubc29\uc548\uc744 \ucd5c\uc885 \uacb0\uc815\ud558\ub294 \uac83\uc73c\ub85c \ud558\uaca0\uc2b5\ub2c8\ub2e4.")
A.iac=s([A.chi,A.chr,A.ch8,A.ch_],t.uf)
A.ibn=s(["\uc0ac\uc2e4\uacfc \uc758\uacac\uc744 \uad6c\ubd84\ud558\ub294 \ubc29\ubc95\uc744 \uc4f0\uc138\uc694.","\uadfc\uac70\uc758 \uc911\uc694\uc131\uc744 \uc4f0\uc138\uc694.","\ubc18\ub300 \uc758\uacac\uc744 \ub9d0\ud558\ub294 \ubc29\ubc95\uc744 \uc4f0\uc138\uc694.","\ub300\uc548\uc744 \uc81c\uc2dc\ud558\ub294 \ubc29\ubc95\uc744 \uc4f0\uc138\uc694.","\ub2e4\ub978 \uc0ac\ub78c\uc758 \uc758\uacac\uc744 \ub4e3\ub294 \ud0dc\ub3c4\ub97c \uc4f0\uc138\uc694.","V-\uae30\ub294 \ud558\uc9c0\ub9cc\uacfc V-\uae30\ubcf4\ub2e4\ub294\uc744 \uc0ac\uc6a9\ud574 \ubcf4\uc138\uc694."],t.s)
A.cuk=new B.cN("\uc5c5\ubb34 \ud68c\uc758\uc5d0\uc11c \ud6a8\uacfc\uc801\uc73c\ub85c \uc758\uacac\uc744 \ub9d0\ud558\ub294 \ubc29\ubc95\uc5d0 \ub300\ud574 \uc368 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft v\u1ec1 c\xe1ch tr\xecnh b\xe0y \xfd ki\u1ebfn hi\u1ec7u qu\u1ea3 trong cu\u1ed9c h\u1ecdp c\xf4ng vi\u1ec7c.",A.ibn,"\uc5c5\ubb34 \ud68c\uc758\uc5d0\uc11c \uc790\uc2e0\uc758 \uc758\uacac\uc744 \uc798 \uc804\ub2ec\ud558\ub824\uba74 \uba3c\uc800 \uc0ac\uc2e4\uacfc \uac1c\uc778\uc801\uc778 \uc0dd\uac01\uc744 \uad6c\ubd84\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \ub2e8\uc21c\ud788 \uc790\uc2e0\uc758 \ub290\ub08c\ub9cc \ub9d0\ud558\uae30\ubcf4\ub2e4\ub294 \uad00\ub828 \uc790\ub8cc\ub098 \uc2e4\uc81c \uc0ac\ub840\ub97c \uadfc\uac70\ub85c \uc124\uba85\ud558\uba74 \uc758\uacac\uc758 \uc124\ub4dd\ub825\uc774 \ub192\uc544\uc9d1\ub2c8\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc758\uacac\uc5d0 \ubc18\ub300\ud560 \ub54c\ub3c4 \ubc14\ub85c \ud2c0\ub838\ub2e4\uace0 \ub9d0\ud558\ub294 \uac83\uc740 \uc88b\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc88b\uc740 \uc758\uacac\uc774\uae30\ub294 \ud558\uc9c0\ub9cc \ube44\uc6a9\uc774\ub098 \uc77c\uc815 \uce21\uba74\uc5d0\uc11c \uc5b4\ub824\uc6c0\uc774 \uc788\ub2e4\uace0 \uc124\uba85\ud55c \ud6c4 \ub2e4\ub978 \ub300\uc548\uc744 \uc81c\uc2dc\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \ub610\ud55c \uc790\uc2e0\uc758 \uc758\uacac\uc744 \ub9d0\ud558\ub294 \uac83\ub9cc\ud07c \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc124\uba85\uc744 \ub05d\uae4c\uc9c0 \ub4e3\uace0 \uc774\ud574\ud558\uc9c0 \ubabb\ud55c \ubd80\ubd84\uc744 \ub2e4\uc2dc \ud655\uc778\ud558\ub294 \ud0dc\ub3c4\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4.","\u0110\u1ec3 truy\u1ec1n \u0111\u1ea1t t\u1ed1t \xfd ki\u1ebfn trong cu\u1ed9c h\u1ecdp c\xf4ng vi\u1ec7c, tr\u01b0\u1edbc ti\xean c\u1ea7n ph\xe2n bi\u1ec7t s\u1ef1 th\u1eadt v\xe0 suy ngh\u0129 c\xe1 nh\xe2n. Thay v\xec ch\u1ec9 n\xf3i c\u1ea3m nh\u1eadn c\u1ee7a m\xecnh, n\u1ebfu gi\u1ea3i th\xedch d\u1ef1a tr\xean d\u1eef li\u1ec7u li\xean quan ho\u1eb7c tr\u01b0\u1eddng h\u1ee3p th\u1ef1c t\u1ebf th\xec s\u1ee9c thuy\u1ebft ph\u1ee5c c\u1ee7a \xfd ki\u1ebfn s\u1ebd cao h\u01a1n. Khi ph\u1ea3n \u0111\u1ed1i \xfd ki\u1ebfn c\u1ee7a ng\u01b0\u1eddi kh\xe1c c\u0169ng kh\xf4ng n\xean n\xf3i ngay r\u1eb1ng h\u1ecd sai. N\xean gi\u1ea3i th\xedch r\u1eb1ng \u0111\xfang l\xe0 \xfd ki\u1ebfn t\u1ed1t nh\u01b0ng c\xf3 kh\xf3 kh\u0103n v\u1ec1 chi ph\xed ho\u1eb7c l\u1ecbch tr\xecnh, sau \u0111\xf3 \u0111\u01b0a ra ph\u01b0\u01a1ng \xe1n thay th\u1ebf. Ngo\xe0i vi\u1ec7c tr\xecnh b\xe0y \xfd ki\u1ebfn c\u1ee7a m\xecnh, th\xe1i \u0111\u1ed9 nghe h\u1ebft l\u1eddi gi\u1ea3i th\xedch c\u1ee7a ng\u01b0\u1eddi kh\xe1c v\xe0 h\u1ecfi l\u1ea1i ph\u1ea7n ch\u01b0a hi\u1ec3u c\u0169ng r\u1ea5t quan tr\u1ecdng.")
A.hoU=s(["\ub450 \ubc29\uc548\uc758 \ub0b4\uc6a9\uc744 \uc124\uba85\ud558\uc138\uc694.","\uac01 \ubc29\uc548\uc758 \uc7a5\uc810\uc744 \uc4f0\uc138\uc694.","\uac01 \ubc29\uc548\uc758 \ub2e8\uc810\uc744 \uc4f0\uc138\uc694.","\ube44\uc6a9\uacfc \ud6a8\uacfc\ub97c \ube44\uad50\ud558\uc138\uc694.","\uc2e4\ud604 \uac00\ub2a5\uc131\uc744 \ud3c9\uac00\ud558\uc138\uc694.","V-(\uc73c)\u3134/\ub294 \ub370 \ube44\ud574\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cuq=new B.cN("\ub450 \uac00\uc9c0 \uc5c5\ubb34 \uac1c\uc120 \ubc29\uc548\uc744 \ube44\uad50\ud574\uc11c \uac00\uc7a5 \uc801\uc808\ud55c \ubc29\uc548\uc744 \uc120\ud0dd\ud574 \ubcf4\uc138\uc694.","H\xe3y so s\xe1nh hai ph\u01b0\u01a1ng \xe1n c\u1ea3i thi\u1ec7n c\xf4ng vi\u1ec7c v\xe0 ch\u1ecdn ph\u01b0\u01a1ng \xe1n ph\xf9 h\u1ee3p nh\u1ea5t.",A.hoU,"\ud604\uc7ac \uac80\uc0ac \uc2dc\uac04\uc744 \uc904\uc774\uae30 \uc704\ud55c \ubc29\ubc95\uc73c\ub85c \ub450 \uac00\uc9c0 \ubc29\uc548\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uccab \ubc88\uc9f8 \ubc29\uc548\uc740 \uac80\uc0ac \uc778\uc6d0\uc744 \ud55c \uba85 \ucd94\uac00\ud558\ub294 \uac83\uc774\uace0 \ub450 \ubc88\uc9f8 \ubc29\uc548\uc740 \uc77c\ubd80 \uac80\uc0ac \uacfc\uc815\uc744 \uc790\ub3d9\ud654\ud558\ub294 \uac83\uc785\ub2c8\ub2e4. \uc778\ub825\uc744 \ucd94\uac00\ud558\ub294 \ubc29\ubc95\uc740 \ubc14\ub85c \uc801\uc6a9\ud560 \uc218 \uc788\ub2e4\ub294 \uc7a5\uc810\uc774 \uc788\ub294 \ub370 \ube44\ud574 \ub9e4\ub2ec \uc778\uac74\ube44\uac00 \uacc4\uc18d \ubc1c\uc0dd\ud569\ub2c8\ub2e4. \uc790\ub3d9\ud654 \ubc29\ubc95\uc740 \ucd08\uae30 \ud22c\uc790 \ube44\uc6a9\uc774 \ub192\uc740 \ub370 \ube44\ud574 \ud55c\ubc88 \uc2dc\uc2a4\ud15c\uc744 \uad6c\ucd95\ud558\uba74 \uc7a5\uae30\uc801\uc73c\ub85c \ubc18\ubcf5 \uc5c5\ubb34\ub97c \uc904\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \ud604\uc7ac \ud68c\uc0ac\uc758 \uc608\uc0b0\uacfc \uc124\uce58 \uae30\uac04\uc744 \uace0\ub824\ud558\uba74 \uc790\ub3d9\ud654\ub97c \uc989\uc2dc \uc801\uc6a9\ud558\uae30\ub294 \uc5b4\ub835\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \ub2e8\uae30\uc801\uc73c\ub85c\ub294 \uc778\uc6d0\uc744 \uc870\uc815\ud558\uace0 \uc7a5\uae30\uc801\uc73c\ub85c \uc790\ub3d9\ud654\ub97c \uc900\ube44\ud558\ub294 \ubc29\ubc95\uc774 \uac00\uc7a5 \ud604\uc2e4\uc801\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.","Hi\u1ec7n c\xf3 th\u1ec3 ngh\u0129 \u0111\u1ebfn hai ph\u01b0\u01a1ng \xe1n \u0111\u1ec3 gi\u1ea3m th\u1eddi gian ki\u1ec3m tra. Ph\u01b0\u01a1ng \xe1n th\u1ee9 nh\u1ea5t l\xe0 b\u1ed5 sung m\u1ed9t ng\u01b0\u1eddi ki\u1ec3m tra, ph\u01b0\u01a1ng \xe1n th\u1ee9 hai l\xe0 t\u1ef1 \u0111\u1ed9ng h\xf3a m\u1ed9t ph\u1ea7n qu\xe1 tr\xecnh ki\u1ec3m tra. Ph\u01b0\u01a1ng ph\xe1p b\u1ed5 sung nh\xe2n l\u1ef1c c\xf3 \u01b0u \u0111i\u1ec3m l\xe0 c\xf3 th\u1ec3 \xe1p d\u1ee5ng ngay nh\u01b0ng chi ph\xed nh\xe2n c\xf4ng s\u1ebd ti\u1ebfp t\u1ee5c ph\xe1t sinh h\xe0ng th\xe1ng. Ph\u01b0\u01a1ng ph\xe1p t\u1ef1 \u0111\u1ed9ng h\xf3a c\xf3 chi ph\xed \u0111\u1ea7u t\u01b0 ban \u0111\u1ea7u cao nh\u01b0ng sau khi x\xe2y d\u1ef1ng h\u1ec7 th\u1ed1ng c\xf3 th\u1ec3 gi\u1ea3m c\xf4ng vi\u1ec7c l\u1eb7p l\u1ea1i v\u1ec1 l\xe2u d\xe0i. Tuy nhi\xean x\xe9t ng\xe2n s\xe1ch hi\u1ec7n t\u1ea1i v\xe0 th\u1eddi gian l\u1eafp \u0111\u1eb7t, kh\xf3 \xe1p d\u1ee5ng t\u1ef1 \u0111\u1ed9ng h\xf3a ngay. V\xec v\u1eady t\xf4i ngh\u0129 ng\u1eafn h\u1ea1n n\xean \u0111i\u1ec1u ch\u1ec9nh nh\xe2n l\u1ef1c v\xe0 d\xe0i h\u1ea1n chu\u1ea9n b\u1ecb t\u1ef1 \u0111\u1ed9ng h\xf3a l\xe0 th\u1ef1c t\u1ebf nh\u1ea5t.")
A.h4U=s(["\ud68c\uc758 \ubaa9\uc801\uc744 \uc4f0\uc138\uc694.","\uc548\uac74 \uc900\ube44\ub97c \uc4f0\uc138\uc694.","\uc758\uacac \uc870\uc728\uc744 \uc4f0\uc138\uc694.","\uacb0\uc815 \ubc29\ubc95\uc744 \uc4f0\uc138\uc694.","\ub2f4\ub2f9\uc790\uc640 \uae30\ud55c \ud655\uc778\uc744 \uc4f0\uc138\uc694.","\ud68c\uc758\ub85d\uc758 \ud544\uc694\uc131\uc744 \uc4f0\uc138\uc694."],t.s)
A.cur=new B.cN("\uc88b\uc740 \ud68c\uc758\ub97c \ub9cc\ub4e4\uae30 \uc704\ud574 \ud544\uc694\ud55c \uc870\uac74\uc5d0 \ub300\ud574 \uc368 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft v\u1ec1 nh\u1eefng \u0111i\u1ec1u ki\u1ec7n c\u1ea7n thi\u1ebft \u0111\u1ec3 c\xf3 m\u1ed9t cu\u1ed9c h\u1ecdp hi\u1ec7u qu\u1ea3.",A.h4U,"\uc88b\uc740 \ud68c\uc758\ub97c \uc704\ud574\uc11c\ub294 \uba3c\uc800 \ud68c\uc758\uc758 \ubaa9\uc801\uacfc \uc548\uac74\uc774 \uba85\ud655\ud574\uc57c \ud569\ub2c8\ub2e4. \ubaa9\uc801\uc774 \ubd88\ubd84\uba85\ud558\uba74 \uc5ec\ub7ec \uc774\uc57c\uae30\uac00 \ub098\uc624\ub354\ub77c\ub3c4 \uc2e4\uc81c \uacb0\ub860\uc73c\ub85c \uc774\uc5b4\uc9c0\uae30 \uc5b4\ub835\uc2b5\ub2c8\ub2e4. \ucc38\uc11d\uc790\ub4e4\uc740 \ud544\uc694\ud55c \uc790\ub8cc\ub97c \ubbf8\ub9ac \ud655\uc778\ud558\uace0 \uc790\uc2e0\uc758 \uc758\uacac\uacfc \uadfc\uac70\ub97c \uc900\ube44\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \ud68c\uc758 \uc911\uc5d0\ub294 \uc11c\ub85c \ub2e4\ub978 \uc758\uacac\uc774 \ub098\uc62c \uc218 \uc788\uc73c\ubbc0\ub85c \ud55c\ucabd \uc758\uacac\ub9cc \ubc14\ub85c \uc120\ud0dd\ud558\uae30\ubcf4\ub2e4\ub294 \uc7a5\ub2e8\uc810\uacfc \uc2e4\ud604 \uac00\ub2a5\uc131\uc744 \ube44\uad50\ud558\uba74\uc11c \ud569\uc758\uc810\uc744 \ucc3e\uc544\uc57c \ud569\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \uacb0\uc815\ub41c \ub0b4\uc6a9\uc744 \ub2e4\uc2dc \uc694\uc57d\ud558\uace0 \uac01 \uc5c5\ubb34\uc758 \ub2f4\ub2f9\uc790\uc640 \uc644\ub8cc \uae30\ud55c\uc744 \uc815\ud574\uc57c \ud569\ub2c8\ub2e4. \ub610\ud55c \ud68c\uc758\ub85d\uc744 \uc791\uc131\ud574\uc11c \uacb0\uc815 \uc0ac\ud56d\uc774 \ub204\ub77d\ub418\uac70\ub098 \ub2e4\ub974\uac8c \uc804\ub2ec\ub418\uc9c0 \uc54a\ub3c4\ub85d \ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\u0110\u1ec3 c\xf3 m\u1ed9t cu\u1ed9c h\u1ecdp t\u1ed1t, tr\u01b0\u1edbc ti\xean m\u1ee5c \u0111\xedch v\xe0 n\u1ed9i dung cu\u1ed9c h\u1ecdp ph\u1ea3i r\xf5 r\xe0ng. N\u1ebfu m\u1ee5c \u0111\xedch kh\xf4ng r\xf5 th\xec d\xf9 nhi\u1ec1u \xfd ki\u1ebfn \u0111\u01b0\u1ee3c \u0111\u01b0a ra c\u0169ng kh\xf3 d\u1eabn \u0111\u1ebfn k\u1ebft lu\u1eadn th\u1ef1c t\u1ebf. Ng\u01b0\u1eddi tham d\u1ef1 n\xean ki\u1ec3m tra tr\u01b0\u1edbc t\xe0i li\u1ec7u c\u1ea7n thi\u1ebft v\xe0 chu\u1ea9n b\u1ecb \xfd ki\u1ebfn c\xf9ng c\u0103n c\u1ee9 c\u1ee7a m\xecnh. Trong cu\u1ed9c h\u1ecdp c\xf3 th\u1ec3 c\xf3 c\xe1c \xfd ki\u1ebfn kh\xe1c nhau, v\xec v\u1eady thay v\xec ch\u1ecdn ngay m\u1ed9t ph\xeda c\u1ea7n so s\xe1nh \u01b0u nh\u01b0\u1ee3c \u0111i\u1ec3m v\xe0 t\xednh kh\u1ea3 thi \u0111\u1ec3 t\xecm \u0111i\u1ec3m th\u1ed1ng nh\u1ea5t. Cu\u1ed1i c\xf9ng c\u1ea7n t\xf3m t\u1eaft l\u1ea1i n\u1ed9i dung \u0111\xe3 quy\u1ebft \u0111\u1ecbnh v\xe0 x\xe1c \u0111\u1ecbnh ng\u01b0\u1eddi ph\u1ee5 tr\xe1ch c\xf9ng th\u1eddi h\u1ea1n cho t\u1eebng vi\u1ec7c. Ngo\xe0i ra c\u1ea7n vi\u1ebft bi\xean b\u1ea3n \u0111\u1ec3 n\u1ed9i dung quy\u1ebft \u0111\u1ecbnh kh\xf4ng b\u1ecb b\u1ecf s\xf3t ho\u1eb7c truy\u1ec1n \u0111\u1ea1t kh\xe1c \u0111i.")
A.fAs=s([A.cuk,A.cuq,A.cur],t.l5)
