A.cgV=new B.c7("\ud300\uc7a5\uc5d0\uac8c \uc790\uc2e0\uc758 \uac1c\uc120\uc810\uc744 \uad6c\uccb4\uc801\uc73c\ub85c \ubb3c\uc5b4\ubcf4\uc138\uc694.",A.fDF,"\ud300\uc7a5\ub2d8, \uc774\ubc88 \ud3c9\uac00 \ub0b4\uc6a9\uc744 \ubcf4\uace0 \uc81c\uac00 \uac1c\uc120\ud574\uc57c \ud560 \ubd80\ubd84\uc744 \ub354 \uc815\ud655\ud788 \uc54c\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \u201c\uc5c5\ubb34 \uc815\ub9ac\uac00 \uc870\uae08 \ubd80\uc871\ud558\ub2e4\u201d\ub294 \ub0b4\uc6a9\uc774 \uc788\uc5c8\ub294\ub370 \uad6c\uccb4\uc801\uc73c\ub85c \uc5b4\ub5a4 \uc0c1\ud669\uc744 \ub9d0\uc500\ud558\uc2dc\ub294\uc9c0 \uc54c\ub824 \uc8fc\uc2e4 \uc218 \uc788\uc744\uae4c\uc694? \ucd5c\uadfc \uc0ac\ub840\uac00 \uc788\uc73c\uba74 \uac19\uc774 \uc124\uba85\ud574 \uc8fc\uc2dc\uba74 \uc81c\uac00 \uc774\ud574\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub420 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \uadf8\ub9ac\uace0 \uac00\uc7a5 \uba3c\uc800 \uac1c\uc120\ud574\uc57c \ud560 \ud55c \uac00\uc9c0\ub97c \uc815\ud55c\ub2e4\uba74 \uc5b4\ub5a4 \ubd80\ubd84\ubd80\ud130 \uc2dc\uc791\ud558\ub294 \uac83\uc774 \uc88b\uc744\uc9c0\ub3c4 \uc870\uc5b8 \ubd80\ud0c1\ub4dc\ub9bd\ub2c8\ub2e4.")
A.hyN=s(["\uc798\ud55c \uc810","\uad6c\uccb4\uc801\uc778 \uc0ac\ub840","\uac1c\uc120\uc810","\uc601\ud5a5","\ubc29\ubc95"],t.s)
A.chR=new B.c7("\ud6c4\ubc30\uc5d0\uac8c \uc5c5\ubb34 \ud53c\ub4dc\ubc31\uc744 \ud574 \ubcf4\uc138\uc694.",A.hyN,"\uc624\ub298 \uc791\uc5c5\uc740 \uc804\uccb4\uc801\uc73c\ub85c \uc798\ud588\uc2b5\ub2c8\ub2e4. \ud2b9\ud788 \uc124\ube44\uc5d0\uc11c \uc774\uc0c1 \uc18c\uc74c\uc744 \ubc1c\uacac\ud588\uc744 \ub54c \ubc14\ub85c \uc791\uc5c5\uc744 \uba48\ucd94\uace0 \ubcf4\uace0\ud55c \uc810\uc774 \uc88b\uc558\uc2b5\ub2c8\ub2e4. \ub2e4\ub9cc \uac80\uc0ac \uacb0\uacfc\ub97c \uae30\ub85d\ud560 \ub54c \uc2dc\uac04\uacfc \uc218\ub7c9\uc774 \ube60\uc9c0\ub294 \uacbd\uc6b0\uac00 \ub450 \ubc88 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uc774\ub7f0 \ub0b4\uc6a9\uc774 \ub204\ub77d\ub418\uba74 \ub098\uc911\uc5d0 \ubb38\uc81c \uc6d0\uc778\uc744 \ud655\uc778\ud558\uae30 \uc5b4\ub824\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uac80\uc0ac \ud6c4 \ubc14\ub85c \uccb4\ud06c\ub9ac\uc2a4\ud2b8\ub97c \ud655\uc778\ud558\ub294 \uc2b5\uad00\uc744 \ub9cc\ub4e4\uba74 \ub3c4\uc6c0\uc774 \ub420 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \uc77c\uc8fc\uc77c \uc815\ub3c4 \ud574 \ubcf4\uace0 \ub2e4\uc2dc \uac19\uc774 \ud655\uc778\ud574 \ubd05\uc2dc\ub2e4.")
A.hPa=s(["\ud53c\ub4dc\ubc31","\ubb38\uc81c","\ud589\ub3d9","\uae30\uac04","\uce21\uc815","\uc7ac\ud655\uc778"],t.s)
A.chj=new B.c7("\ubc1b\uc740 \ud53c\ub4dc\ubc31\uc744 \uc5b4\ub5bb\uac8c \uac1c\uc120 \ud589\ub3d9\uc73c\ub85c \ubc14\uafc0\uc9c0 \uc124\uba85\ud574 \ubcf4\uc138\uc694.",A.hPa,"\uc800\ub294 \ubcf4\uace0 \ub0b4\uc6a9\uc774 \uae38\uace0 \ud575\uc2ec\uc774 \ub2a6\uac8c \ub098\uc628\ub2e4\ub294 \ud53c\ub4dc\ubc31\uc744 \ubc1b\uc558\ub2e4\uace0 \uac00\uc815\ud558\uaca0\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \ubaa8\ub4e0 \ubcf4\uace0\ub97c \uc2dc\uc791\ud558\uae30 \uc804\uc5d0 \uacb0\ub860, \uc6d0\uc778, \uc870\uce58 \uc138 \uac00\uc9c0\ub97c \uba54\ubaa8\ud558\uaca0\uc2b5\ub2c8\ub2e4. \ubcf4\uace0\ud560 \ub54c\ub294 \uacb0\ub860\uc744 \uba3c\uc800 \ub9d0\ud558\uace0 \uc0c1\ub300\ubc29\uc774 \ucd94\uac00 \ub0b4\uc6a9\uc744 \ubb3c\uc73c\uba74 \uc138\ubd80 \uc0ac\ud56d\uc744 \uc124\uba85\ud558\uaca0\uc2b5\ub2c8\ub2e4. \uc774 \ubc29\ubc95\uc744 \ud55c \ub2ec \ub3d9\uc548 \uc801\uc6a9\ud558\uace0 \ubcf4\uace0 \uc2dc\uac04\uc774 \uc5bc\ub9c8\ub098 \uc904\uc5c8\ub294\uc9c0 \ud655\uc778\ud558\uaca0\uc2b5\ub2c8\ub2e4. \uadf8 \ud6c4 \ud300\uc7a5\ub2d8\uaed8 \ub2e4\uc2dc \ud53c\ub4dc\ubc31\uc744 \uc694\uccad\ud574\uc11c \uc2e4\uc81c\ub85c \uac1c\uc120\ub410\ub294\uc9c0 \ud655\uc778\ud558\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.")
A.iJH=s([A.ch4,A.cgV,A.chR,A.chj],t.uf)
A.iu9=s(["\uac15\uc810\uc744 \ub450 \uac00\uc9c0 \uc4f0\uc138\uc694.","\uc2e4\uc81c \uc0ac\ub840\ub97c \uc4f0\uc138\uc694.","\uac1c\uc120\uc810\uc744 \ud55c\ub450 \uac00\uc9c0 \uc4f0\uc138\uc694.","\uac1c\uc120 \ubc29\ubc95\uc744 \uc4f0\uc138\uc694.","\ud655\uc778 \uae30\uac04\uc744 \uc815\ud558\uc138\uc694.","V/A-(\uc73c)\u3134/\ub294 \ud3b8\uc774\ub2e4\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cuI=new B.cN("\uc790\uc2e0\uc758 \uc5c5\ubb34 \uac15\uc810\uacfc \uac1c\uc120\uc810\uc5d0 \ub300\ud574 \uc368 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft v\u1ec1 \u0111i\u1ec3m m\u1ea1nh v\xe0 \u0111i\u1ec3m c\u1ea7n c\u1ea3i thi\u1ec7n trong c\xf4ng vi\u1ec7c c\u1ee7a b\u1ea3n th\xe2n.",A.iu9,"\uc81c \uac15\uc810\uc740 \ucc45\uc784\uac10\uacfc \ud604\uc7a5 \uc801\uc751\ub825\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uc800\ub294 \ub9e1\uc740 \uc5c5\ubb34\uac00 \uc788\uc73c\uba74 \uac00\ub2a5\ud55c \ud55c \ub05d\uae4c\uc9c0 \ud655\uc778\ud558\ub294 \ud3b8\uc774\uba70 \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud558\uba74 \uadf8\ub0e5 \ub118\uc5b4\uac00\uae30\ubcf4\ub2e4 \ub2f4\ub2f9\uc790\uc5d0\uac8c \ud655\uc778\ud558\ub824\uace0 \ud569\ub2c8\ub2e4. \uc0c8\ub85c\uc6b4 \uacf5\uc815\uc5d0 \ubc30\uce58\ub410\uc744 \ub54c\ub3c4 \uc791\uc5c5 \uc21c\uc11c\uc640 \uc911\uc694\ud55c \ub0b4\uc6a9\uc744 \uba54\ubaa8\ud558\uba74\uc11c \ube44\uad50\uc801 \ube68\ub9ac \uc801\uc751\ud588\uc2b5\ub2c8\ub2e4. \ubc18\uba74\uc5d0 \uc5ec\ub7ec \uc5c5\ubb34\uac00 \ub3d9\uc2dc\uc5d0 \ub4e4\uc5b4\uc624\uba74 \ubaa8\ub4e0 \uc77c\uc744 \ud63c\uc790 \ucc98\ub9ac\ud558\ub824\uace0 \ud558\ub294 \ud3b8\uc774\ub77c \ub3c4\uc6c0\uc744 \uc694\uccad\ud558\ub294 \uc2dc\uc810\uc774 \ub2a6\uc5b4\uc9c8 \ub54c\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uc55e\uc73c\ub85c\ub294 \uc5c5\ubb34\uac00 \uc77c\uc815 \uc218\uc900 \uc774\uc0c1 \uc313\uc774\uba74 \uc6b0\uc120\uc21c\uc704\ub97c \uc815\ud558\uace0 \ud544\uc694\ud55c \uacbd\uc6b0 \ubbf8\ub9ac \uc9c0\uc6d0\uc744 \uc694\uccad\ud558\ub824\uace0 \ud569\ub2c8\ub2e4. \ud55c \ub2ec \ub3d9\uc548 \uc5c5\ubb34 \ucc98\ub9ac \uc2dc\uac04\uacfc \uc9c0\uc5f0 \uac74\uc218\ub97c \uae30\ub85d\ud574\uc11c \uc2e4\uc81c\ub85c \uac1c\uc120\ub418\ub294\uc9c0 \ud655\uc778\ud560 \uacc4\ud68d\uc785\ub2c8\ub2e4.","T\xf4i ngh\u0129 \u0111i\u1ec3m m\u1ea1nh c\u1ee7a m\xecnh l\xe0 tinh th\u1ea7n tr\xe1ch nhi\u1ec7m v\xe0 kh\u1ea3 n\u0103ng th\xedch nghi t\u1ea1i hi\u1ec7n tr\u01b0\u1eddng. Khi c\xf3 c\xf4ng vi\u1ec7c \u0111\u01b0\u1ee3c giao t\xf4i c\xf3 xu h\u01b0\u1edbng ki\u1ec3m tra \u0111\u1ebfn c\xf9ng n\u1ebfu c\xf3 th\u1ec3, v\xe0 khi ph\xe1t sinh v\u1ea5n \u0111\u1ec1 t\xf4i c\u1ed1 x\xe1c nh\u1eadn v\u1edbi ng\u01b0\u1eddi ph\u1ee5 tr\xe1ch thay v\xec b\u1ecf qua. Khi \u0111\u01b0\u1ee3c b\u1ed1 tr\xed sang c\xf4ng \u0111o\u1ea1n m\u1edbi t\xf4i c\u0169ng ghi l\u1ea1i th\u1ee9 t\u1ef1 c\xf4ng vi\u1ec7c v\xe0 n\u1ed9i dung quan tr\u1ecdng n\xean th\xedch nghi t\u01b0\u01a1ng \u0111\u1ed1i nhanh. Ng\u01b0\u1ee3c l\u1ea1i khi nhi\u1ec1u vi\u1ec7c \u0111\u1ebfn c\xf9ng l\xfac t\xf4i c\xf3 xu h\u01b0\u1edbng c\u1ed1 t\u1ef1 x\u1eed l\xfd t\u1ea5t c\u1ea3 n\xean \u0111\xf4i khi th\u1eddi \u0111i\u1ec3m y\xeau c\u1ea7u h\u1ed7 tr\u1ee3 b\u1ecb mu\u1ed9n. T\u1eeb nay n\u1ebfu c\xf4ng vi\u1ec7c t\xedch t\u1ee5 v\u01b0\u1ee3t m\u1ed9t m\u1ee9c nh\u1ea5t \u0111\u1ecbnh t\xf4i s\u1ebd x\xe1c \u0111\u1ecbnh \u01b0u ti\xean v\xe0 khi c\u1ea7n s\u1ebd xin h\u1ed7 tr\u1ee3 tr\u01b0\u1edbc. T\xf4i d\u1ef1 \u0111\u1ecbnh ghi th\u1eddi gian x\u1eed l\xfd v\xe0 s\u1ed1 tr\u01b0\u1eddng h\u1ee3p ch\u1eadm trong m\u1ed9t th\xe1ng \u0111\u1ec3 ki\u1ec3m tra th\u1ef1c s\u1ef1 c\xf3 c\u1ea3i thi\u1ec7n hay kh\xf4ng.")
A.hRI=s(["\uad6c\uccb4\uc131\uc744 \uc4f0\uc138\uc694.","\uc0ac\uc2e4\uacfc \uadfc\uac70\ub97c \uc4f0\uc138\uc694.","\uc798\ud55c \uc810\uc744 \uc4f0\uc138\uc694.","\uac1c\uc120\uc810\uc744 \uc4f0\uc138\uc694.","\ud574\uacb0 \ubc29\ubc95\uc744 \uc4f0\uc138\uc694.","\ud6c4\uc18d \ud655\uc778\uc744 \uc4f0\uc138\uc694."],t.s)
A.cuT=new B.cN("\uc88b\uc740 \ud53c\ub4dc\ubc31\uc758 \uc870\uac74\uc5d0 \ub300\ud574 \uc368 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft v\u1ec1 nh\u1eefng \u0111i\u1ec1u ki\u1ec7n c\u1ee7a m\u1ed9t ph\u1ea3n h\u1ed3i t\u1ed1t.",A.hRI,"\uc88b\uc740 \ud53c\ub4dc\ubc31\uc740 \uc0c1\ub300\ubc29\uc744 \ud3c9\uac00\ud558\uac70\ub098 \ube44\ub09c\ud558\ub294 \ub9d0\uc774 \uc544\ub2c8\ub77c \uc5c5\ubb34\ub97c \ub354 \uc798\ud560 \uc218 \uc788\ub3c4\ub85d \ub3d5\ub294 \uc815\ubcf4\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ub530\ub77c\uc11c \u201c\uc77c\uc744 \ubabb\ud55c\ub2e4\u201d\ucc98\ub7fc \uc0ac\ub78c \uc804\uccb4\ub97c \ud310\ub2e8\ud558\uae30\ubcf4\ub2e4 \uc5b4\ub5a4 \uc0c1\ud669\uc5d0\uc11c \uc5b4\ub5a4 \ud589\ub3d9\uc774 \uc788\uc5c8\ub294\uc9c0 \uad6c\uccb4\uc801\uc73c\ub85c \uc124\uba85\ud574\uc57c \ud569\ub2c8\ub2e4. \uc798\ud55c \ubd80\ubd84\ub3c4 \ud568\uaed8 \uc774\uc57c\uae30\ud558\uba74 \uc0c1\ub300\ubc29\uc774 \uc5b4\ub5a4 \ud589\ub3d9\uc744 \uacc4\uc18d \uc720\uc9c0\ud574\uc57c \ud558\ub294\uc9c0 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uac1c\uc120\ud560 \ubd80\ubd84\uc744 \ub9d0\ud560 \ub54c\ub294 \uadf8 \ud589\ub3d9\uc774 \uc5c5\ubb34\uc5d0 \uc5b4\ub5a4 \uc601\ud5a5\uc744 \uc8fc\ub294\uc9c0 \uc124\uba85\ud558\uace0 \uac00\ub2a5\ud55c \ubc29\ubc95\ub3c4 \ud568\uaed8 \uc81c\uc548\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9\uc73c\ub85c \uc77c\uc815 \uae30\uac04\uc774 \uc9c0\ub09c \ud6c4 \uc2e4\uc81c\ub85c \ub2ec\ub77c\uc84c\ub294\uc9c0 \ub2e4\uc2dc \ud655\uc778\ud574\uc57c \ud53c\ub4dc\ubc31\uc774 \uc2e4\uc81c \uac1c\uc120\uc73c\ub85c \uc5f0\uacb0\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","T\xf4i ngh\u0129 ph\u1ea3n h\u1ed3i t\u1ed1t kh\xf4ng ph\u1ea3i l\u1eddi \u0111\xe1nh gi\xe1 hay ch\u1ec9 tr\xedch con ng\u01b0\u1eddi m\xe0 l\xe0 th\xf4ng tin gi\xfap ng\u01b0\u1eddi \u0111\xf3 l\xe0m c\xf4ng vi\u1ec7c t\u1ed1t h\u01a1n. V\xec v\u1eady thay v\xec \u0111\xe1nh gi\xe1 to\xe0n b\u1ed9 con ng\u01b0\u1eddi b\u1eb1ng nh\u1eefng c\xe2u nh\u01b0 \u201ckh\xf4ng bi\u1ebft l\xe0m vi\u1ec7c\u201d, c\u1ea7n gi\u1ea3i th\xedch c\u1ee5 th\u1ec3 h\xe0nh vi n\xe0o x\u1ea3y ra trong t\xecnh hu\u1ed1ng n\xe0o. N\u1ebfu n\xf3i c\u1ea3 ph\u1ea7n l\xe0m t\u1ed1t, \u0111\u1ed1i ph\u01b0\u01a1ng c\xf3 th\u1ec3 hi\u1ec3u h\xe0nh vi n\xe0o n\xean ti\u1ebfp t\u1ee5c duy tr\xec. Khi n\xf3i ph\u1ea7n c\u1ea7n c\u1ea3i thi\u1ec7n n\xean gi\u1ea3i th\xedch h\xe0nh vi \u0111\xf3 \u1ea3nh h\u01b0\u1edfng \u0111\u1ebfn c\xf4ng vi\u1ec7c th\u1ebf n\xe0o v\xe0 n\u1ebfu c\xf3 th\u1ec3 \u0111\u01b0a c\u1ea3 ph\u01b0\u01a1ng \xe1n. Cu\u1ed1i c\xf9ng sau m\u1ed9t kho\u1ea3ng th\u1eddi gian c\u1ea7n ki\u1ec3m tra l\u1ea1i xem c\xf3 thay \u0111\u1ed5i th\u1eadt kh\xf4ng th\xec ph\u1ea3n h\u1ed3i m\u1edbi c\xf3 th\u1ec3 k\u1ebft n\u1ed1i v\u1edbi c\u1ea3i thi\u1ec7n th\u1ef1c t\u1ebf.")
A.iWo=s(["\ud3c9\uac00 \ub0b4\uc6a9\uc744 \uc694\uc57d\ud558\uc138\uc694.","\uac15\uc810\uc744 \uc4f0\uc138\uc694.","\uac1c\uc120\uc810\uc744 \uc4f0\uc138\uc694.","\uad6c\uccb4\uc801\uc778 \ud589\ub3d9\uc744 \uc4f0\uc138\uc694.","\uae30\uac04\uacfc \uce21\uc815 \ubc29\ubc95\uc744 \uc4f0\uc138\uc694.","V-\ub3c4\ub85d \ub178\ub825\ud558\ub2e4\uc640 V-(\uc73c)\u3134 \ud6c4\ubd80\ud130\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cuW=new B.cN("\uc5c5\ubb34 \ud3c9\uac00 \uacb0\uacfc\ub97c \ubc1b\uc740 \ud6c4\uc758 \uac1c\uc120 \uacc4\ud68d\uc744 \uc791\uc131\ud574 \ubcf4\uc138\uc694.","H\xe3y vi\u1ebft k\u1ebf ho\u1ea1ch c\u1ea3i thi\u1ec7n sau khi nh\u1eadn k\u1ebft qu\u1ea3 \u0111\xe1nh gi\xe1 c\xf4ng vi\u1ec7c.",A.iWo,"\uc774\ubc88 \uc5c5\ubb34 \ud3c9\uac00\uc5d0\uc11c \ucc45\uc784\uac10\uacfc \ubb38\uc81c \ub300\uc751 \uc18d\ub3c4\ub294 \uc88b\uc740 \ud3c9\uac00\ub97c \ubc1b\uc558\uc9c0\ub9cc \ubcf4\uace0\uac00 \uae38\uace0 \uc6b0\uc120\uc21c\uc704\ub97c \uc815\ud558\ub294 \ubd80\ubd84\uc774 \ubd80\uc871\ud558\ub2e4\ub294 \ud53c\ub4dc\ubc31\uc744 \ubc1b\uc558\uc2b5\ub2c8\ub2e4. \uc55e\uc73c\ub85c\ub294 \uc5c5\ubb34 \uc2dc\uc791 \uc804\uc5d0 \ud574\uc57c \ud560 \uc77c\uc744 \uae34\uae09\ub3c4\uc640 \ub9c8\uac10 \uc2dc\uac04\uc5d0 \ub530\ub77c \uc815\ub9ac\ud558\ub3c4\ub85d \ub178\ub825\ud558\uaca0\uc2b5\ub2c8\ub2e4. \ub610\ud55c \ubcf4\uace0 \uc804\uc5d0\ub294 \uacb0\ub860, \uc6d0\uc778, \uc870\uce58 \ub0b4\uc6a9\uc744 \uc138 \uc904\ub85c \uba3c\uc800 \uc815\ub9ac\ud558\uaca0\uc2b5\ub2c8\ub2e4. \uccb4\ud06c\ub9ac\uc2a4\ud2b8\ub97c \uc0ac\uc6a9\ud55c \ud6c4\ubd80\ud130 \uae30\ub85d \ub204\ub77d\uc774 \uc904\uc5c8\ub358 \uacbd\ud5d8\uc774 \uc788\uae30 \ub54c\ubb38\uc5d0 \uc774\ubc88\uc5d0\ub3c4 \ud55c \ub2ec \ub3d9\uc548 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ubcc0\ud654\ub97c \uae30\ub85d\ud558\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \ud55c \ub2ec \ud6c4 \ucc98\ub9ac \uc9c0\uc5f0 \uac74\uc218\uc640 \ubcf4\uace0 \uc2dc\uac04\uc744 \ube44\uad50\ud55c \ub4a4 \ud300\uc7a5\ub2d8\uaed8 \ub2e4\uc2dc \ud53c\ub4dc\ubc31\uc744 \uc694\uccad\ud560 \uacc4\ud68d\uc785\ub2c8\ub2e4.","Trong \u0111\xe1nh gi\xe1 c\xf4ng vi\u1ec7c l\u1ea7n n\xe0y, t\xf4i \u0111\u01b0\u1ee3c \u0111\xe1nh gi\xe1 t\u1ed1t v\u1ec1 tinh th\u1ea7n tr\xe1ch nhi\u1ec7m v\xe0 t\u1ed1c \u0111\u1ed9 x\u1eed l\xfd v\u1ea5n \u0111\u1ec1, nh\u01b0ng nh\u1eadn ph\u1ea3n h\u1ed3i r\u1eb1ng b\xe1o c\xe1o d\xe0i v\xe0 ph\u1ea7n x\xe1c \u0111\u1ecbnh \u01b0u ti\xean c\xf2n thi\u1ebfu. T\u1eeb nay tr\u01b0\u1edbc khi b\u1eaft \u0111\u1ea7u c\xf4ng vi\u1ec7c t\xf4i s\u1ebd c\u1ed1 g\u1eafng s\u1eafp x\u1ebfp vi\u1ec7c c\u1ea7n l\xe0m d\u1ef1a tr\xean m\u1ee9c \u0111\u1ed9 kh\u1ea9n c\u1ea5p v\xe0 th\u1eddi h\u1ea1n. Ngo\xe0i ra tr\u01b0\u1edbc khi b\xe1o c\xe1o t\xf4i s\u1ebd t\xf3m t\u1eaft tr\u01b0\u1edbc ba d\xf2ng g\u1ed3m k\u1ebft lu\u1eadn, nguy\xean nh\xe2n v\xe0 x\u1eed l\xfd. V\xec t\xf4i t\u1eebng c\xf3 kinh nghi\u1ec7m vi\u1ec7c b\u1ecf s\xf3t ghi ch\xe9p gi\u1ea3m k\u1ec3 t\u1eeb sau khi d\xf9ng checklist, l\u1ea7n n\xe0y t\xf4i c\u0169ng mu\u1ed1n ghi l\u1ea1i thay \u0111\u1ed5i trong m\u1ed9t th\xe1ng theo c\xe1ch t\u01b0\u01a1ng t\u1ef1. Sau m\u1ed9t th\xe1ng t\xf4i s\u1ebd so s\xe1nh s\u1ed1 tr\u01b0\u1eddng h\u1ee3p x\u1eed l\xfd ch\u1eadm v\xe0 th\u1eddi gian b\xe1o c\xe1o r\u1ed3i xin tr\u01b0\u1edfng nh\xf3m ph\u1ea3n h\u1ed3i l\u1ea1i.")
