A.dd7=new B.a0("\uc678\uad6d\uc778 \uc8fc\ubbfc\uc758 \uc815\ucc29\uc744 \ub3d5\ub294 \ubc29\ubc95\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",A.ivf,1,"\uc815\ucc29\uc740 \uc5b8\uc5b4\ubfd0\ub9cc \uc544\ub2c8\ub77c \ud589\uc815, \ucde8\uc5c5, \uc8fc\uac70 \ub4f1 \ub2e4\uc591\ud55c \uc601\uc5ed\uacfc \uad00\ub828\uc774 \uc788\uc2b5\ub2c8\ub2e4.","\uc2e4\uc804","\uace0\uae09")
A.i2Y=s(["\ud655\uc778\ub418\uc9c0 \uc54a\uc740 \uc18c\ubb38","\uc9c1\uc811\uc801\uc778 \uad50\ub958\uc640 \uc815\ud655\ud55c \uc815\ubcf4","\ud2b9\uc815 \uc9d1\ub2e8\uc5d0 \ub300\ud55c \uc77c\ubc18\ud654","\ub2e4\ub978 \ubb38\ud654\uc640 \uc811\ucd09\ud558\uc9c0 \uc54a\ub294 \uac83"],t.s)
A.df6=new B.a0("\ud3b8\uacac\uc744 \uc904\uc774\ub294 \ub370 \uac00\uc7a5 \ub3c4\uc6c0\uc774 \ub418\ub294 \uac83\uc740?",A.i2Y,1,"\uc9c1\uc811\uc801\uc778 \uad50\ub958\uc640 \uc815\ud655\ud55c \uc815\ubcf4\ub294 \uace0\uc815\uad00\ub150\uacfc \ud3b8\uacac\uc744 \uc904\uc774\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc0ac\ud68c \uc774\ud574","\uc911\uc0c1")
