A.hJi=s(["\ub2e4\ubb38\ud654 \uc0ac\ud68c","\ubb38\ud654 \ub2e4\uc591\uc131","\uc774\uc8fc\ubbfc","\uc678\uad6d\uc778 \uc8fc\ubbfc","\uc0ac\ud68c \ud1b5\ud569","\uc815\ucc29","\uc801\uc751","\ubb38\ud654 \ucc28\uc774","\ud3b8\uacac","\ucc28\ubcc4","\uc0c1\ud638 \uc774\ud574","\ubb38\ud654 \uad50\ub958","\uc815\uccb4\uc131","\ud3ec\uc6a9\uc131"],t.s)
A.hMH=s(["-\uc744/\ub97c \ub9c9\ub860\ud558\uace0","-\ub294\uac00 \ud558\uba74","-\uc5d0 \ub530\ub77c","-\ub294 \ub370 \uc788\uc5b4\uc11c","-\ub2e4\uace0 \ud574\uc11c","-\uae30\ubcf4\ub2e4\ub294","-\ub294 \ubc18\uba74\uc5d0","-(\uc73c)\u3139\uc218\ub85d","-\uc744/\ub97c \uacc4\uae30\ub85c","-\ub294 \uacfc\uc815\uc5d0\uc11c","-\uc9c0 \uc54a\ub3c4\ub85d","-\uc5d0 \ub300\ud55c \uc774\ud574","-\ub294 \uacbd\ud5a5\uc774 \uc788\ub2e4","-(\uc73c)\u3139 \ud544\uc694\uac00 \uc788\ub2e4","-\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4"],t.s)
A.h80=s(["\ub2e4\ubb38\ud654 \uc0ac\ud68c\ub294 \uc11c\ub85c \ub2e4\ub978 \ubb38\ud654\uc801 \ubc30\uacbd\uc744 \uac00\uc9c4 \uc0ac\ub78c\ub4e4\uc774 \ud568\uaed8 \uc0b4\uc544\uac00\ub294 \uc0ac\ud68c\ub97c \uc758\ubbf8\ud55c\ub2e4.","\ubb38\ud654 \ub2e4\uc591\uc131\uc740 \uc5b8\uc5b4, \uc0dd\ud65c \ubc29\uc2dd, \uac00\uce58\uad00, \uc885\uad50, \uc74c\uc2dd \ub4f1 \uc5ec\ub7ec \ucc28\uc774\uc5d0\uc11c \ub098\ud0c0\ub0a0 \uc218 \uc788\ub2e4.","\uc678\uad6d\uc778\uc774 \uc0c8\ub85c\uc6b4 \uc0ac\ud68c\uc5d0 \uc815\ucc29\ud558\uae30 \uc704\ud574\uc11c\ub294 \uc5b8\uc5b4\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc0ac\ud68c \uc81c\ub3c4\uc640 \ubb38\ud654\uc5d0 \ub300\ud55c \uc774\ud574\ub3c4 \ud544\uc694\ud558\ub2e4.","\uc0ac\ud68c \ud1b5\ud569\uc740 \ud55c\ucabd\uc774 \uc790\uc2e0\uc758 \ubb38\ud654\ub97c \uc644\uc804\ud788 \ubc84\ub9ac\ub294 \uac83\uc744 \uc758\ubbf8\ud558\uc9c0 \uc54a\ub294\ub2e4.","\ubb38\ud654 \ucc28\uc774\uac00 \uc788\ub2e4\uace0 \ud574\uc11c \uc5b4\ub290 \ud55c \ubb38\ud654\uac00 \ub354 \uc6b0\uc6d4\ud558\ub2e4\uace0 \ubcfc \uc218\ub294 \uc5c6\ub2e4.","\ud3b8\uacac\uc740 \ucda9\ubd84\ud55c \uc815\ubcf4\ub098 \uacbd\ud5d8 \uc5c6\uc774 \ud2b9\uc815 \uc9d1\ub2e8\uc744 \ubbf8\ub9ac \ud310\ub2e8\ud558\ub294 \ud0dc\ub3c4\uc640 \uad00\ub828\uc774 \uc788\ub2e4.","\ucc28\ubcc4\uc740 \ucd9c\uc2e0 \uad6d\uac00\ub098 \uc5b8\uc5b4 \ub4f1\uacfc \uac19\uc740 \uc774\uc720\ub85c \ubd88\ub9ac\ud558\uac8c \ub300\uc6b0\ud558\ub294 \ubb38\uc81c\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\ub2e4.","\ub2e4\ubb38\ud654 \uac00\uc815\uc758 \uc790\ub140\ub294 \uc5ec\ub7ec \ubb38\ud654\uc801 \ubc30\uacbd\uc744 \ub3d9\uc2dc\uc5d0 \uacbd\ud5d8\ud560 \uc218 \uc788\ub2e4.","\ubb38\ud654 \uad50\ub958\uc640 \uc0c1\ud638 \uc774\ud574\ub294 \ubd88\ud544\uc694\ud55c \uc624\ud574\uc640 \uac08\ub4f1\uc744 \uc904\uc774\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4.","\ub2e4\uc591\uc131\uc744 \uc874\uc911\ud558\uba74\uc11c \uc0ac\ud68c \uad6c\uc131\uc6d0\uc5d0\uac8c \uacf5\uc815\ud55c \uae30\ud68c\ub97c \uc81c\uacf5\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4."],t.s)
A.HG=new B.fU(17,"\ubb38\ud654 \ub2e4\uc591\uc131\uacfc \ub2e4\ubb38\ud654 \uc0ac\ud68c","\u0110a d\u1ea1ng v\u0103n h\xf3a v\xe0 x\xe3 h\u1ed9i \u0111a v\u0103n h\xf3a",A.fB8,A.hyn,A.hjO,A.hFR,A.ih3,A.fUh,A.i0C,A.iKX,A.h6U,A.hJi,A.hMH,A.h80)
A.fFG=s(["H\u1ecdc t\u1eeb v\u1ef1ng n\xe2ng cao v\u1ec1 khoa h\u1ecdc, c\xf4ng ngh\u1ec7 v\xe0 nghi\xean c\u1ee9u ph\xe1t tri\u1ec3n.","Ph\xe2n bi\u1ec7t \uae30\ucd08 \uc5f0\uad6c, \uc751\uc6a9 \uc5f0\uad6c, \uc2e4\uc99d v\xe0 \uc0c1\uc6a9\ud654.","H\u1ecdc c\xe1ch n\xf3i v\u1ec1 k\u1ebft qu\u1ea3 nghi\xean c\u1ee9u v\xe0 \u0111\u1ea7u t\u01b0 R&D.","H\u1ecdc t\u1eeb v\u1ef1ng v\u1ec1 b\u1eb1ng s\xe1ng ch\u1ebf v\xe0 quy\u1ec1n s\u1edf h\u1eefu tr\xed tu\u1ec7.","H\u1ecdc c\xe1ch tr\xecnh b\xe0y vai tr\xf2 c\u1ee7a c\xf4ng ngh\u1ec7 ngu\u1ed3n v\xe0 c\xf4ng ngh\u1ec7 c\u1ed1t l\xf5i.","H\u1ecdc t\u1eeb v\u1ef1ng n\xe2ng cao v\u1ec1 ng\xe0nh b\xe1n d\u1eabn.","H\u1ecdc c\xe1ch n\xf3i v\u1ec1 v\u1eadt li\u1ec7u, linh ki\u1ec7n, thi\u1ebft b\u1ecb v\xe0 chu\u1ed7i cung \u1ee9ng.","H\u1ecdc t\u1eeb v\u1ef1ng v\u1ec1 c\xf4ng ngh\u1ec7 sinh h\u1ecdc v\xe0 ph\xe1t tri\u1ec3n thu\u1ed1c m\u1edbi.","H\u1ecdc c\xe1ch tr\xecnh b\xe0y nghi\xean c\u1ee9u l\xe2m s\xe0ng v\xe0 thi\u1ebft b\u1ecb y t\u1ebf.","H\u1ecdc t\u1eeb v\u1ef1ng v\u1ec1 robot, xe t\u1ef1 h\xe0nh v\xe0 c\u1ea3m bi\u1ebfn.","H\u1ecdc c\xe1ch n\xf3i v\u1ec1 c\xf4ng ngh\u1ec7 l\u01b0\u1ee3ng t\u1eed v\xe0 \u0111i\u1ec7n to\xe1n l\u01b0\u1ee3ng t\u1eed.","H\u1ecdc t\u1eeb v\u1ef1ng v\u1ec1 v\u1ec7 tinh, ph\u01b0\u01a1ng ti\u1ec7n ph\xf3ng v\xe0 ng\xe0nh c\xf4ng nghi\u1ec7p v\u0169 tr\u1ee5.","H\u1ecdc c\xe1ch tr\xecnh b\xe0y c\u1ea1nh tranh c\xf4ng ngh\u1ec7 gi\u1eefa c\xe1c qu\u1ed1c gia.","H\u1ecdc c\xe1ch n\xf3i v\u1ec1 ti\xeau chu\u1ea9n c\xf4ng ngh\u1ec7 v\xe0 ti\xeau chu\u1ea9n qu\u1ed1c t\u1ebf.","H\u1ecdc c\xe1ch tr\xecnh b\xe0y \u0111\u1ea1o \u0111\u1ee9c nghi\xean c\u1ee9u, \u0111\u1ea1o v\u0103n v\xe0 thao t\xfang d\u1eef li\u1ec7u.","Luy\u1ec7n n\xf3i v\xe0 vi\u1ebft TOPIK n\xe2ng cao v\u1ec1 \u0111\u1ed5i m\u1edbi c\xf4ng ngh\u1ec7 v\xe0 x\xe3 h\u1ed9i t\u01b0\u01a1ng lai."],t.s)
A.cTQ=new B.e("\uacfc\ud559\uae30\uc220\uc758 \ubc1c\uc804\uc740 \uc0b0\uc5c5 \uad6c\uc870\uc640 \uc0dd\ud65c \ubc29\uc2dd\uc744 \ubcc0\ud654\uc2dc\ud0a4\uace0 \uc788\uc2b5\ub2c8\ub2e4.","S\u1ef1 ph\xe1t tri\u1ec3n khoa h\u1ecdc c\xf4ng ngh\u1ec7 \u0111ang thay \u0111\u1ed5i c\u01a1 c\u1ea5u ng\xe0nh v\xe0 c\xe1ch s\u1ed1ng.")
