A.dhJ=new B.d_("\uc9c1\uc7a5 \uc0dd\ud65c\uc744 \ud558\uba74\uc11c \uac00\uc7a5 \ub9ce\uc774 \uc131\uc7a5\ud55c \ubd80\ubd84\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Trong qu\xe1 tr\xecnh \u0111i l\xe0m, ph\u1ea7n n\xe0o c\u1ee7a b\u1ea1n \u0111\xe3 ti\u1ebfn b\u1ed9 nhi\u1ec1u nh\u1ea5t?",A.hll,"\uc9c1\uc7a5 \uc0dd\ud65c\uc744 \ud558\uba74\uc11c \ubb38\uc81c \ud574\uacb0 \ub2a5\ub825\uc774 \uac00\uc7a5 \ub9ce\uc774 \uc131\uc7a5\ud588\uc2b5\ub2c8\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ubb38\uc81c\uac00 \uc0dd\uae30\uba74 \ub2f9\ud669\ud588\uc9c0\ub9cc \uacbd\ud5d8\uc774 \uc313\uc774\uba74\uc11c \uc6d0\uc778\uc744 \uba3c\uc800 \ud655\uc778\ud558\uace0 \ub300\uc751\ud558\uac8c \ub418\uc5c8\uc2b5\ub2c8\ub2e4.","Trong qu\xe1 tr\xecnh \u0111i l\xe0m, kh\u1ea3 n\u0103ng gi\u1ea3i quy\u1ebft v\u1ea5n \u0111\u1ec1 c\u1ee7a t\xf4i ti\u1ebfn b\u1ed9 nhi\u1ec1u nh\u1ea5t. Ban \u0111\u1ea7u khi c\xf3 v\u1ea5n \u0111\u1ec1 t\xf4i th\u01b0\u1eddng ho\u1ea3ng, nh\u01b0ng khi kinh nghi\u1ec7m t\u0103ng l\xean t\xf4i \u0111\xe3 bi\u1ebft ki\u1ec3m tra nguy\xean nh\xe2n tr\u01b0\u1edbc r\u1ed3i x\u1eed l\xfd.")
A.fZv=s(["\uac15\uc810","\ucc45\uc784\uac10","\uc57d\uc810","\ubcf4\uc644\ud558\ub2e4"],t.s)
A.dhG=new B.d_("\ubcf8\uc778\uc758 \uac15\uc810\uacfc \ubcf4\uc644\ud574\uc57c \ud560 \uc810\uc744 \ub9d0\ud574 \ubcf4\uc138\uc694.","H\xe3y n\xf3i v\u1ec1 \u0111i\u1ec3m m\u1ea1nh v\xe0 \u0111i\u1ec3m b\u1ea1n c\u1ea7n c\u1ea3i thi\u1ec7n.",A.fZv,"\uc81c \uac15\uc810\uc740 \ucc45\uc784\uac10\uc774 \uac15\ud558\ub2e4\ub294 \uac83\uc785\ub2c8\ub2e4. \ubc18\uba74\uc5d0 \uc544\uc9c1 \ud55c\uad6d\uc5b4\ub85c \ube60\ub974\uac8c \ubcf4\uace0\ud558\ub294 \uac83\uc774 \ubd80\uc871\ud574\uc11c \uacc4\uc18d \uc5f0\uc2b5\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.","\u0110i\u1ec3m m\u1ea1nh c\u1ee7a t\xf4i l\xe0 c\xf3 tinh th\u1ea7n tr\xe1ch nhi\u1ec7m cao. M\u1eb7t kh\xe1c, kh\u1ea3 n\u0103ng b\xe1o c\xe1o nhanh b\u1eb1ng ti\u1ebfng H\xe0n v\u1eabn c\xf2n thi\u1ebfu n\xean t\xf4i \u0111ang ti\u1ebfp t\u1ee5c luy\u1ec7n t\u1eadp.")
