A.irv=s(["\uc8fc\uac70 \uc120\ud638\ub3c4","\uc8fc\uac70 \ud574\uc9c0","\uc8fc\ud0dd \ubd80\ucc44","\uacc4\uc57d \uc18c\uc720\uad8c"],t.s)
A.ddQ=new B.a0("\u201cM\u1ee9c \u0111\u1ed9 \u01b0a th\xedch n\u01a1i c\u01b0 tr\xfa\u201d l\xe0:",A.irv,0,"\uc8fc\uac70 \uc120\ud638\ub3c4 = m\u1ee9c \u0111\u1ed9 \u01b0a th\xedch c\u01b0 tr\xfa.","\uc0ac\ud68c \uc5b4\ud718","\uace0\uae09")
