A.hti=s(["\uc0c1\ub300 \uc758\uacac\uc744 \ubb34\uc870\uac74 \ubb34\uc2dc\ud55c\ub2e4","\ucc2c\ubc18\ub9cc \ub9d0\ud558\uace0 \uadfc\uac70\ub294 \ub9d0\ud558\uc9c0 \uc54a\ub294\ub2e4","\uc0c1\ub300 \uc758\uacac\uc744 \uc778\uc815\ud558\uace0 \uadfc\uac70\ub97c \ub4e4\uc5b4 \uc790\uc2e0\uc758 \uc758\uacac\uc744 \ub9d0\ud55c\ub2e4","\uac10\uc815\uc801\uc73c\ub85c \uacb0\ub860\ubd80\ud130 \ub9d0\ud55c\ub2e4"],t.s)
A.dbv=new B.a0("\uc88b\uc740 \ud1a0\ub860 \ud0dc\ub3c4\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",A.hti,2,"\uace0\uae09 \ud1a0\ub860\uc5d0\uc11c\ub294 \uc0c1\ub300 \uc758\uacac\uc744 \uc874\uc911\ud558\uba74\uc11c \uadfc\uac70\ub97c \uc81c\uc2dc\ud558\ub294 \ud0dc\ub3c4\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.","\uc2e4\uc804 \ud1a0\ub860","\uace0\uae09")
A.hjB=s(["\ud544\uc694\uc131\ub9cc \ubcf8\ub2e4","\ud6a8\uacfc, \ube44\uc6a9, \ud615\ud3c9\uc131, \uc9c0\uc18d \uac00\ub2a5\uc131\uc744 \ud568\uaed8 \ubcf8\ub2e4","\ubc18\ub300 \uc758\uacac\uc740 \uc81c\uc678\ud55c\ub2e4","\ud1b5\uacc4\ub294 \ubcf4\uc9c0 \uc54a\ub294\ub2e4"],t.s)
A.dcU=new B.a0("\uc815\ucc45\uc744 \ud3c9\uac00\ud560 \ub54c \uace0\ub824\ud560 \ub0b4\uc6a9\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",A.hjB,1,"\uc815\ucc45 \ud3c9\uac00\ub294 \uc5ec\ub7ec \uc694\uc18c\ub97c \ud568\uaed8 \uace0\ub824\ud574\uc57c \ub354 \uade0\ud615 \uc788\uac8c \ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc815\ucc45 \uc774\ud574","\uace0\uae09")
A.h16=s(["\uac10\uc815 \ud45c\ud604\ub9cc \ubc18\ubcf5\ud55c\ub2e4","\ud604\uc0c1, \uc6d0\uc778, \uc601\ud5a5, \ud574\uacb0 \ubc29\uc548, \uacb0\ub860 \uc21c\uc11c\ub85c \uc815\ub9ac\ud55c\ub2e4","\uc608\uc2dc \uc5c6\uc774 \uc8fc\uc7a5\ub9cc \uc4f4\ub2e4","\ud55c \uac00\uc9c0 \uc6d0\uc778\ub9cc \ub2e8\uc815\ud55c\ub2e4"],t.s)
A.deR=new B.a0("\uc0ac\ud68c \ubb38\uc81c \uae00\uc4f0\uae30 \uad6c\uc870\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",A.h16,1,"TOPIK \uace0\uae09 \uc4f0\uae30\uc5d0\uc11c\ub294 \ub17c\ub9ac\uc801 \uad6c\uc870\uac00 \ub9e4\uc6b0 \uc911\uc694\ud569\ub2c8\ub2e4.","\uc4f0\uae30 \uc804\ub7b5","\uace0\uae09")
