A.iwL=s([A.dcC,A.df3,A.dbp,A.dfe,A.deK,A.dbg,A.dcV,A.det,A.dcx,A.dc8,A.dbV,A.dez,A.db7,A.dcM,A.ddC,A.dfg,A.dfq,A.dbT],t.yc)
A.hEl=s(["\ucd9c\ucc98","\uacf5\uc2dd \uc790\ub8cc","\ub0a0\uc9dc","\uc5ec\ub7ec \uc5b8\ub860\uc0ac","\uadfc\uac70","\uc0ac\uc2e4 \ud655\uc778"],t.s)
A.di3=new B.d_("\uc778\ud130\ub137\uc5d0\uc11c \ubcf8 \uc815\ubcf4\uac00 \uc0ac\uc2e4\uc778\uc9c0 \uc5b4\ub5bb\uac8c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\uae4c?","C\xf3 th\u1ec3 ki\u1ec3m tra th\xf4ng tin nh\xecn th\u1ea5y tr\xean Internet c\xf3 \u0111\xfang s\u1ef1 th\u1eadt hay kh\xf4ng b\u1eb1ng c\xe1ch n\xe0o?",A.hEl,"\uc778\ud130\ub137\uc5d0\uc11c \uc815\ubcf4\ub97c \ubd24\uc744 \ub54c\ub294 \uba3c\uc800 \ub204\uac00 \uc791\uc131\ud588\ub294\uc9c0\uc640 \ucd9c\ucc98\uac00 \uc5b4\ub514\uc778\uc9c0 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \ub610\ud55c \uc624\ub798\ub41c \uc815\ubcf4\uac00 \ub2e4\uc2dc \uacf5\uc720\ub418\ub294 \uacbd\uc6b0\ub3c4 \uc788\uae30 \ub54c\ubb38\uc5d0 \uc791\uc131 \ub0a0\uc9dc\ub3c4 \uc0b4\ud3b4\ubcfc \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uc911\uc694\ud55c \ub0b4\uc6a9\uc774\ub77c\uba74 \ud55c \uac00\uc9c0 \uac8c\uc2dc\ubb3c\ub9cc \ubbff\uae30\ubcf4\ub2e4 \uacf5\uc2dd \uae30\uad00\uc758 \uc790\ub8cc\ub098 \uc5ec\ub7ec \uc5b8\ub860\uc0ac\uc758 \ubcf4\ub3c4\ub97c \ube44\uad50\ud55c \ub4a4 \ud310\ub2e8\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","Khi nh\xecn th\u1ea5y th\xf4ng tin tr\xean Internet, tr\u01b0\u1edbc ti\xean c\u1ea7n ki\u1ec3m tra ai vi\u1ebft v\xe0 ngu\u1ed3n \u1edf \u0111\xe2u. Ngo\xe0i ra v\xec c\u0169ng c\xf3 tr\u01b0\u1eddng h\u1ee3p th\xf4ng tin c\u0169 \u0111\u01b0\u1ee3c chia s\u1ebb l\u1ea1i n\xean c\u1ea7n xem ng\xe0y \u0111\u0103ng. N\u1ebfu l\xe0 n\u1ed9i dung quan tr\u1ecdng, thay v\xec ch\u1ec9 tin m\u1ed9t b\xe0i \u0111\u0103ng th\xec n\xean so s\xe1nh t\xe0i li\u1ec7u c\u1ee7a c\u01a1 quan ch\xednh th\u1ee9c ho\u1eb7c b\xe0i \u0111\u01b0a tin c\u1ee7a nhi\u1ec1u c\u01a1 quan b\xe1o ch\xed r\u1ed3i m\u1edbi \u0111\xe1nh gi\xe1.")
A.fOD=s(["\uc815\ubcf4 \uacf5\uc720","\uc18d\ub3c4","\ud5c8\uc704 \uc815\ubcf4","\uc18c\ud1b5","\uc911\ub3c5","\uc5ec\ub860"],t.s)
A.dii=new B.d_("SNS\uc758 \uc7a5\uc810\uacfc \ub2e8\uc810\uc740 \ubb34\uc5c7\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\uae4c?","Theo b\u1ea1n \u01b0u \u0111i\u1ec3m v\xe0 nh\u01b0\u1ee3c \u0111i\u1ec3m c\u1ee7a m\u1ea1ng x\xe3 h\u1ed9i l\xe0 g\xec?",A.fOD,"SNS\uc758 \uac00\uc7a5 \ud070 \uc7a5\uc810\uc740 \ub204\uad6c\ub098 \ube60\ub974\uac8c \uc815\ubcf4\ub97c \uacf5\uc720\ud558\uace0 \ub2e4\ub978 \uc0ac\ub78c\uacfc \uc18c\ud1b5\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uae34\uae09\ud55c \uc0c1\ud669\uc5d0\uc11c\ub294 \ud544\uc694\ud55c \uc815\ubcf4\uac00 \ub9e4\uc6b0 \ube60\ub974\uac8c \uc804\ub2ec\ub420 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ubc18\uba74\uc5d0 \uc0ac\uc2e4\uc774 \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \uc815\ubcf4\ub3c4 \uac19\uc740 \uc18d\ub3c4\ub85c \ud655\uc0b0\ub420 \uc218 \uc788\uace0 \uc0ac\uc6a9 \uc2dc\uac04\uc774 \uc9c0\ub098\uce58\uac8c \uae38\uc5b4\uc9c0\uba74 \uc77c\uc0c1\uc0dd\ud65c\uc774\ub098 \uc218\uba74\uc5d0 \uc601\ud5a5\uc744 \uc904 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.","T\xf4i ngh\u0129 \u01b0u \u0111i\u1ec3m l\u1edbn nh\u1ea5t c\u1ee7a m\u1ea1ng x\xe3 h\u1ed9i l\xe0 b\u1ea5t k\u1ef3 ai c\u0169ng c\xf3 th\u1ec3 nhanh ch\xf3ng chia s\u1ebb th\xf4ng tin v\xe0 giao ti\u1ebfp v\u1edbi ng\u01b0\u1eddi kh\xe1c. Trong t\xecnh hu\u1ed1ng kh\u1ea9n c\u1ea5p, th\xf4ng tin c\u1ea7n thi\u1ebft c\u0169ng c\xf3 th\u1ec3 \u0111\u01b0\u1ee3c truy\u1ec1n \u0111i r\u1ea5t nhanh. Ng\u01b0\u1ee3c l\u1ea1i, th\xf4ng tin ch\u01b0a \u0111\u01b0\u1ee3c ki\u1ec3m ch\u1ee9ng c\u0169ng c\xf3 th\u1ec3 lan v\u1edbi t\u1ed1c \u0111\u1ed9 t\u01b0\u01a1ng t\u1ef1, v\xe0 n\u1ebfu th\u1eddi gian s\u1eed d\u1ee5ng qu\xe1 d\xe0i th\xec c\xf3 th\u1ec3 \u1ea3nh h\u01b0\u1edfng \u0111\u1ebfn cu\u1ed9c s\u1ed1ng h\xe0ng ng\xe0y ho\u1eb7c gi\u1ea5c ng\u1ee7.")
A.iT3=s(["\uc5b8\ub860\uc0ac","\ud50c\ub7ab\ud3fc","\uc774\uc6a9\uc790","\uc0ac\uc2e4 \ud655\uc778","\uad50\uc721","\ucc45\uc784"],t.s)
A.dil=new B.d_("\uac00\uc9dc \ub274\uc2a4 \ubb38\uc81c\ub97c \uc904\uc774\uae30 \uc704\ud574 \ub204\uac00 \ub178\ub825\ud574\uc57c \ud569\ub2c8\uae4c?","Ai c\u1ea7n n\u1ed7 l\u1ef1c \u0111\u1ec3 gi\u1ea3m v\u1ea5n \u0111\u1ec1 tin gi\u1ea3?",A.iT3,"\uac00\uc9dc \ub274\uc2a4 \ubb38\uc81c\ub294 \ud55c\ucabd\uc758 \ub178\ub825\ub9cc\uc73c\ub85c \ud574\uacb0\ud558\uae30 \uc5b4\ub835\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uc5b8\ub860\uc0ac\ub294 \uc815\ud655\ud55c \uc0ac\uc2e4 \ud655\uc778\uacfc \uc815\uc815\ubcf4\ub3c4\uc5d0 \ucc45\uc784\uc744 \uac00\uc838\uc57c \ud558\uace0 \ud50c\ub7ab\ud3fc\ub3c4 \ud5c8\uc704 \uc815\ubcf4\uac00 \uacfc\ub3c4\ud558\uac8c \ud655\uc0b0\ub418\uc9c0 \uc54a\ub3c4\ub85d \uad00\ub9ac\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uc774\uc6a9\uc790 \uc5ed\uc2dc \uc815\ubcf4\ub97c \ubc14\ub85c \uacf5\uc720\ud558\uae30\ubcf4\ub2e4 \ucd9c\ucc98\uc640 \uadfc\uac70\ub97c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \ud559\uad50\uc640 \uc0ac\ud68c\uc5d0\uc11c \ubbf8\ub514\uc5b4 \ub9ac\ud130\ub7ec\uc2dc \uad50\uc721\uc744 \uac15\ud654\ud558\ub294 \uac83\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4.","T\xf4i cho r\u1eb1ng v\u1ea5n \u0111\u1ec1 tin gi\u1ea3 kh\xf3 gi\u1ea3i quy\u1ebft ch\u1ec9 b\u1eb1ng n\u1ed7 l\u1ef1c c\u1ee7a m\u1ed9t ph\xeda. C\u01a1 quan b\xe1o ch\xed ph\u1ea3i c\xf3 tr\xe1ch nhi\u1ec7m trong ki\u1ec3m ch\u1ee9ng s\u1ef1 th\u1eadt v\xe0 \u0111\xednh ch\xednh, c\xf2n n\u1ec1n t\u1ea3ng c\u0169ng c\u1ea7n qu\u1ea3n l\xfd \u0111\u1ec3 th\xf4ng tin sai kh\xf4ng lan truy\u1ec1n qu\xe1 m\u1ee9c. Ng\u01b0\u1eddi d\xf9ng c\u0169ng c\u1ea7n ki\u1ec3m tra ngu\u1ed3n v\xe0 c\u0103n c\u1ee9 thay v\xec chia s\u1ebb ngay. Vi\u1ec7c t\u0103ng c\u01b0\u1eddng gi\xe1o d\u1ee5c n\u0103ng l\u1ef1c truy\u1ec1n th\xf4ng trong tr\u01b0\u1eddng h\u1ecdc v\xe0 x\xe3 h\u1ed9i c\u0169ng quan tr\u1ecdng.")
A.ils=s([A.di3,A.dii,A.dil],t.Gu)
A.hXa=s(["\uac00\uc9dc \ub274\uc2a4\uc758 \ud2b9\uc9d5\uc744 \uc124\uba85\ud558\uc138\uc694.","\ud655\uc0b0\ub418\ub294 \uc774\uc720\ub97c \uc4f0\uc138\uc694.","\uac1c\uc778\uacfc \uc0ac\ud68c\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc744 \uc124\uba85\ud558\uc138\uc694.","\uc774\uc6a9\uc790\uac00 \ud574\uc57c \ud560 \uc77c\uc744 \uc4f0\uc138\uc694.","\uc5b8\ub860\uacfc \ud50c\ub7ab\ud3fc\uc758 \uc5ed\ud560\uc744 \uc81c\uc548\ud558\uc138\uc694."],t.s)
A.dEx=new B.dX("\uac00\uc9dc \ub274\uc2a4\uac00 \uc0ac\ud68c\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uacfc \ud574\uacb0 \ubc29\uc548","\u1ea2nh h\u01b0\u1edfng c\u1ee7a tin gi\u1ea3 \u0111\u1ed1i v\u1edbi x\xe3 h\u1ed9i v\xe0 ph\u01b0\u01a1ng \xe1n gi\u1ea3i quy\u1ebft",A.hXa,"\uc778\ud130\ub137\uacfc SNS\uac00 \ubc1c\ub2ec\ud558\uba74\uc11c \ub204\uad6c\ub098 \uc27d\uac8c \uc815\ubcf4\ub97c \uc0dd\uc0b0\ud558\uace0 \uacf5\uc720\ud560 \uc218 \uc788\uac8c \ub418\uc5c8\uc2b5\ub2c8\ub2e4. \uc774\ub7ec\ud55c \ubcc0\ud654\ub294 \uc815\ubcf4 \uc811\uadfc\uc131\uc744 \ub192\uc600\uc9c0\ub9cc \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \uc815\ubcf4\uac00 \ube60\ub974\uac8c \ud655\uc0b0\ub418\ub294 \ubb38\uc81c\ub3c4 \ub9cc\ub4e4\uc5c8\uc2b5\ub2c8\ub2e4. \ud2b9\ud788 \uc790\uadf9\uc801\uc778 \uc81c\ubaa9\uc774\ub098 \uc0ac\ub78c\ub4e4\uc758 \ubd88\uc548\uc744 \uc774\uc6a9\ud55c \ud5c8\uc704 \uc815\ubcf4\ub294 \uc0ac\uc2e4\ubcf4\ub2e4 \ub354 \ube60\ub974\uac8c \ud37c\uc9c8 \uac00\ub2a5\uc131\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uac00\uc9dc \ub274\uc2a4\uac00 \ubc18\ubcf5\uc801\uc73c\ub85c \ud655\uc0b0\ub418\uba74 \uac1c\uc778\uc774 \uc798\ubabb\ub41c \ud310\ub2e8\uc744 \ud560 \uc218 \uc788\uc744 \ubfd0\ub9cc \uc544\ub2c8\ub77c \uc0ac\ud68c\uc801 \uac08\ub4f1\uacfc \ubd88\uc2e0\ub3c4 \ucee4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc774\uc6a9\uc790\ub294 \uc815\ubcf4\ub97c \uacf5\uc720\ud558\uae30 \uc804\uc5d0 \ucd9c\ucc98\uc640 \uadfc\uac70\ub97c \ud655\uc778\ud574\uc57c \ud558\uba70 \uc5b8\ub860\uacfc \ud50c\ub7ab\ud3fc\ub3c4 \uc0ac\uc2e4 \ud655\uc778\uacfc \uc798\ubabb\ub41c \uc815\ubcf4\uc758 \uc815\uc815\uc5d0 \ucc45\uc784\uc744 \uac00\uc838\uc57c \ud569\ub2c8\ub2e4.","V\u1edbi s\u1ef1 ph\xe1t tri\u1ec3n c\u1ee7a Internet v\xe0 m\u1ea1ng x\xe3 h\u1ed9i, b\u1ea5t k\u1ef3 ai c\u0169ng c\xf3 th\u1ec3 d\u1ec5 d\xe0ng t\u1ea1o v\xe0 chia s\u1ebb th\xf4ng tin. S\u1ef1 thay \u0111\u1ed5i n\xe0y l\xe0m t\u0103ng kh\u1ea3 n\u0103ng ti\u1ebfp c\u1eadn th\xf4ng tin nh\u01b0ng c\u0169ng t\u1ea1o ra v\u1ea5n \u0111\u1ec1 th\xf4ng tin ch\u01b0a \u0111\u01b0\u1ee3c x\xe1c minh lan truy\u1ec1n nhanh. \u0110\u1eb7c bi\u1ec7t, th\xf4ng tin gi\u1ea3 s\u1eed d\u1ee5ng ti\xeau \u0111\u1ec1 gi\u1eadt g\xe2n ho\u1eb7c l\u1ee3i d\u1ee5ng s\u1ef1 lo l\u1eafng c\u1ee7a con ng\u01b0\u1eddi \u0111\xf4i khi c\xf3 kh\u1ea3 n\u0103ng lan nhanh h\u01a1n s\u1ef1 th\u1eadt. N\u1ebfu tin gi\u1ea3 li\xean t\u1ee5c lan truy\u1ec1n, kh\xf4ng ch\u1ec9 c\xe1 nh\xe2n c\xf3 th\u1ec3 \u0111\u01b0a ra ph\xe1n \u0111o\xe1n sai m\xe0 xung \u0111\u1ed9t v\xe0 m\u1ea5t ni\u1ec1m tin trong x\xe3 h\u1ed9i c\u0169ng c\xf3 th\u1ec3 t\u0103ng. V\xec v\u1eady ng\u01b0\u1eddi d\xf9ng c\u1ea7n ki\u1ec3m tra ngu\u1ed3n v\xe0 c\u0103n c\u1ee9 tr\u01b0\u1edbc khi chia s\u1ebb, c\xf2n c\u01a1 quan b\xe1o ch\xed v\xe0 n\u1ec1n t\u1ea3ng c\u0169ng ph\u1ea3i c\xf3 tr\xe1ch nhi\u1ec7m ki\u1ec3m ch\u1ee9ng v\xe0 \u0111\xednh ch\xednh th\xf4ng tin sai.")
A.iwl=s(["\ub514\uc9c0\ud138 \uc815\ubcf4 \ud658\uacbd\uc758 \ud2b9\uc9d5\uc744 \uc124\uba85\ud558\uc138\uc694.","\ubbf8\ub514\uc5b4 \ub9ac\ud130\ub7ec\uc2dc\uc758 \uc758\ubbf8\ub97c \uc4f0\uc138\uc694.","\ucd94\ucc9c \uc54c\uace0\ub9ac\uc998\uc758 \uc601\ud5a5\uc744 \uc124\uba85\ud558\uc138\uc694.","\uac1c\uc778\uc774 \uac00\uc838\uc57c \ud560 \ud0dc\ub3c4\ub97c \uc4f0\uc138\uc694.","\uad50\uc721\uc758 \ud544\uc694\uc131\uc744 \uc81c\uc548\ud558\uc138\uc694."],t.s)
A.dE9=new B.dX("\ub514\uc9c0\ud138 \uc2dc\ub300\uc5d0 \ud544\uc694\ud55c \ubbf8\ub514\uc5b4 \ub9ac\ud130\ub7ec\uc2dc","N\u0103ng l\u1ef1c truy\u1ec1n th\xf4ng c\u1ea7n thi\u1ebft trong th\u1eddi \u0111\u1ea1i s\u1ed1",A.iwl,"\ub514\uc9c0\ud138 \uc2dc\ub300\uc5d0\ub294 \ub9e4\uc77c \ub9e4\uc6b0 \ub9ce\uc740 \uc815\ubcf4\uac00 \ub2e4\uc591\ud55c \ud50c\ub7ab\ud3fc\uc744 \ud1b5\ud574 \uc81c\uacf5\ub429\ub2c8\ub2e4. \ubb38\uc81c\ub294 \uc815\ubcf4\uc758 \uc591\uc774 \ub9ce\uc544\uc84c\ub2e4\uace0 \ud574\uc11c \ubaa8\ub4e0 \uc815\ubcf4\uc758 \uc9c8\uacfc \uc2e0\ub8b0\uc131\uc774 \ub192\uc544\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc785\ub2c8\ub2e4. \ud2b9\ud788 \ucd94\ucc9c \uc54c\uace0\ub9ac\uc998\uc740 \uc774\uc6a9\uc790\uc758 \uad00\uc2ec\uc0ac\uc5d0 \ub9de\ub294 \uc815\ubcf4\ub97c \ud3b8\ub9ac\ud558\uac8c \ubcf4\uc5ec \uc8fc\ub294 \ubc18\uba74\uc5d0 \ube44\uc2b7\ud55c \uc758\uacac\ub9cc \ubc18\ubcf5\uc801\uc73c\ub85c \uc811\ud558\uac8c \ub9cc\ub4e4 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \ud604\ub300 \uc0ac\ud68c\uc5d0\uc11c\ub294 \uc815\ubcf4\ub97c \ub2e8\uc21c\ud788 \uc18c\ube44\ud558\ub294 \ub2a5\ub825\ubcf4\ub2e4 \ucd9c\ucc98\uc640 \uadfc\uac70\ub97c \ud655\uc778\ud558\uace0 \ub2e4\ub978 \uad00\uc810\uacfc \ube44\uad50\ud558\ub294 \ubbf8\ub514\uc5b4 \ub9ac\ud130\ub7ec\uc2dc\uac00 \uc911\uc694\ud569\ub2c8\ub2e4. \uc774\ub7ec\ud55c \ub2a5\ub825\uc740 \uac1c\uc778\uc5d0\uac8c\ub9cc \ub9e1\uae30\uae30\ubcf4\ub2e4 \ud559\uad50\uc640 \uc0ac\ud68c \uad50\uc721\uc744 \ud1b5\ud574 \uc9c0\uc18d\uc801\uc73c\ub85c \uae38\ub7ec\uc57c \ud569\ub2c8\ub2e4.","Trong th\u1eddi \u0111\u1ea1i s\u1ed1, m\u1ed7i ng\xe0y m\u1ed9t l\u01b0\u1ee3ng th\xf4ng tin r\u1ea5t l\u1edbn \u0111\u01b0\u1ee3c cung c\u1ea5p qua nhi\u1ec1u n\u1ec1n t\u1ea3ng. V\u1ea5n \u0111\u1ec1 l\xe0 l\u01b0\u1ee3ng th\xf4ng tin t\u0103ng kh\xf4ng c\xf3 ngh\u0129a ch\u1ea5t l\u01b0\u1ee3ng v\xe0 \u0111\u1ed9 tin c\u1eady c\u1ee7a m\u1ecdi th\xf4ng tin \u0111\u1ec1u t\u0103ng. \u0110\u1eb7c bi\u1ec7t, thu\u1eadt to\xe1n \u0111\u1ec1 xu\u1ea5t thu\u1eadn ti\u1ec7n v\xec hi\u1ec3n th\u1ecb th\xf4ng tin ph\xf9 h\u1ee3p v\u1edbi s\u1edf th\xedch ng\u01b0\u1eddi d\xf9ng, nh\u01b0ng ng\u01b0\u1ee3c l\u1ea1i c\u0169ng c\xf3 th\u1ec3 khi\u1ebfn ng\u01b0\u1eddi d\xf9ng li\xean t\u1ee5c ti\u1ebfp x\xfac v\u1edbi c\xe1c \xfd ki\u1ebfn t\u01b0\u01a1ng t\u1ef1. V\xec v\u1eady trong x\xe3 h\u1ed9i hi\u1ec7n \u0111\u1ea1i, quan tr\u1ecdng h\u01a1n vi\u1ec7c ch\u1ec9 ti\xeau th\u1ee5 th\xf4ng tin l\xe0 n\u0103ng l\u1ef1c truy\u1ec1n th\xf4ng gi\xfap ki\u1ec3m tra ngu\u1ed3n, c\u0103n c\u1ee9 v\xe0 so s\xe1nh v\u1edbi c\xe1c g\xf3c nh\xecn kh\xe1c. N\u0103ng l\u1ef1c n\xe0y kh\xf4ng n\xean ch\u1ec9 giao cho c\xe1 nh\xe2n m\xe0 c\u1ea7n \u0111\u01b0\u1ee3c ph\xe1t tri\u1ec3n li\xean t\u1ee5c th\xf4ng qua gi\xe1o d\u1ee5c trong tr\u01b0\u1eddng h\u1ecdc v\xe0 x\xe3 h\u1ed9i.")
