A.ieL=s(["\ubbfc \uc528\ub294 \uc774\uc6c3\uc5d0\uac8c \uc0ac\uacfc\ud588\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \ub354 \ub2a6\uac8c \uccad\uc18c\ud558\uae30\ub85c \ud588\uc2b5\ub2c8\ub2e4.","\uc544\ub798\uce35\uc740 \uc804\ud600 \uc2dc\ub044\ub7fd\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \ubc14\ub85c \uc774\uc0ac\ud588\uc2b5\ub2c8\ub2e4."],t.s)
A.e3C=new B.T("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\ubbfc \uc528\ub294 \ubc24\ub2a6\uac8c \uccad\uc18c\uae30\ub97c \uc0ac\uc6a9\ud588\uc2b5\ub2c8\ub2e4. \uc544\ub798\uce35 \uc774\uc6c3\uc774 \uc2dc\ub044\ub7fd\ub2e4\uace0 \ud574\uc11c \ubbfc \uc528\ub294 \uc0ac\uacfc\ud558\uace0 \ub2e4\uc74c\ubd80\ud130 \ub2a6\uc740 \uc2dc\uac04\uc5d0\ub294 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uae30\ub85c \ud588\uc2b5\ub2c8\ub2e4.",A.ieL,0,"Min \u0111\xe3 xin l\u1ed7i v\xe0 quy\u1ebft \u0111\u1ecbnh ch\xfa \xfd h\u01a1n.")
A.fTn=s(["\ubaa8\ub4e0 \uc4f0\ub808\uae30\ub97c \ud55c \ubd09\ud22c\uc5d0 \ub123\uc2b5\ub2c8\ub2e4.","\uc4f0\ub808\uae30\ub97c \uc885\ub958\uc5d0 \ub530\ub77c \ub098\ub204\uc5b4 \ubc84\ub9bd\ub2c8\ub2e4.","\uc4f0\ub808\uae30\ub97c \ubcf5\ub3c4\uc5d0 \ubc84\ub9bd\ub2c8\ub2e4.","\uc7ac\ud65c\uc6a9\ud560 \ud544\uc694\uac00 \uc5c6\uc2b5\ub2c8\ub2e4."],t.s)
A.e52=new B.T("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\uc774 \uc544\ud30c\ud2b8\uc5d0\uc11c\ub294 \uc77c\ubc18\uc4f0\ub808\uae30\uc640 \uc74c\uc2dd\ubb3c\uc4f0\ub808\uae30\ub97c \ub098\ub204\uc5b4 \ubc84\ub824\uc57c \ud569\ub2c8\ub2e4. \uc7ac\ud65c\uc6a9\ud488\ub3c4 \uc885\ub958\ubcc4\ub85c \ubd84\ub9ac\ubc30\ucd9c\ud569\ub2c8\ub2e4.",A.fTn,1,"\u0110o\u1ea1n v\u0103n y\xeau c\u1ea7u ph\xe2n lo\u1ea1i r\xe1c.")
A.iCI=s(["\ud0dd\ubc30\uac00 \ubd84\uc2e4\ub418\uc5c8\uc2b5\ub2c8\ub2e4.","\uc606\uc9d1 \uc0ac\ub78c\uc774 \ubbfc \uc528\uc758 \ud0dd\ubc30\ub97c \ub300\uc2e0 \ubc1b\uc544 \uc92c\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\uac00 \ud0dd\ubc30\ub97c \ubc84\ub838\uc2b5\ub2c8\ub2e4.","\ud0dd\ubc30\uac00 \ubca0\ud2b8\ub0a8\uc73c\ub85c \uac14\uc2b5\ub2c8\ub2e4."],t.s)
A.e5q=new B.T("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\ubbfc \uc528\uc758 \ud0dd\ubc30\uac00 \uc606\uc9d1\uc73c\ub85c \uc798\ubabb \ubc30\ub2ec\ub418\uc5c8\uc2b5\ub2c8\ub2e4. \uc606\uc9d1 \uc0ac\ub78c\uc774 \ud0dd\ubc30\ub97c \ub300\uc2e0 \ubc1b\uc544 \ub450\uc5c8\ub2e4\uac00 \ubbfc \uc528\uc5d0\uac8c \uc804\ub2ec\ud588\uc2b5\ub2c8\ub2e4.",A.iCI,1,"H\xe0ng x\xf3m \u0111\xe3 nh\u1eadn h\u1ed9 b\u01b0u ki\u1ec7n.")
A.hts=s(["\ubbfc \uc528\ub294 \uc774\uc6c3\uc5d0\uac8c \ubbf8\ub9ac \uc54c\ub838\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \uc544\ubb34 \ub9d0\ub3c4 \ud558\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.","\uc218\ub9ac\ud560 \ub54c \uc804\ud600 \uc18c\ub9ac\uac00 \ub098\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \uad00\ub9ac\ube44\ub97c \ub0b4\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4."],t.s)
A.e3k=new B.T("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\ubbfc \uc528\ub294 \uc8fc\ub9d0\uc5d0 \uc9d1 \uc218\ub9ac\ub97c \ud558\ub824\uace0 \ud569\ub2c8\ub2e4. \uc18c\uc74c\uc774 \ub0a0 \uc218 \uc788\uc5b4\uc11c \uacf5\uc0ac \uc804\uc5d0 \uc774\uc6c3\uc5d0\uac8c \ubbf8\ub9ac \uc54c\ub824 \uc8fc\uc5c8\uc2b5\ub2c8\ub2e4.",A.hts,0,"Min \u0111\xe3 b\xe1o tr\u01b0\u1edbc v\xec vi\u1ec7c s\u1eeda c\xf3 th\u1ec3 g\xe2y ti\u1ebfng \u1ed3n.")
A.i6t=s(["\uc774\uc6c3\uacfc \ud568\uaed8 \uc0dd\ud65c\ud558\ub294 \ubc29\ubc95","\uc740\ud589 \uacc4\uc88c \ub9cc\ub4dc\ub294 \ubc29\ubc95","\ubcd1\uc6d0 \uc9c4\ub8cc\ubc1b\ub294 \ubc29\ubc95","\ud574\uc678\ub85c \uc18c\ud3ec \ubcf4\ub0b4\ub294 \ubc29\ubc95"],t.s)
A.e_b=new B.T("\ub2e4\uc74c\uc744 \uc77d\uace0 \uac00\uc7a5 \uc54c\ub9de\uc740 \uc81c\ubaa9\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\uacf5\ub3d9\uc8fc\ud0dd\uc5d0\uc11c\ub294 \ubc24\uc5d0 \uc18c\uc74c\uc744 \uc870\uc2ec\ud558\uace0 \uc4f0\ub808\uae30\ub97c \uc815\ud574\uc9c4 \ubc29\ubc95\uc73c\ub85c \ubc84\ub824\uc57c \ud569\ub2c8\ub2e4. \uacf5\ub3d9 \uacf5\uac04\uc5d0\uc11c\ub294 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ubd88\ud3b8\uc744 \uc8fc\uc9c0 \uc54a\ub3c4\ub85d \ud558\uace0 \ubb38\uc81c\uac00 \uc788\uc744 \ub54c\ub294 \uc815\uc911\ud558\uac8c \uc774\uc57c\uae30\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.",A.i6t,0,"\u0110o\u1ea1n v\u0103n n\xf3i v\u1ec1 c\xe1ch s\u1ed1ng c\xf9ng h\xe0ng x\xf3m trong nh\xe0 \u1edf chung.")
