A.e5r=new B.T("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\uc2e0\uccad\ud558\ub824\uba74 \uc2e0\uccad\uc11c\uc640 \uc2e0\ubd84\uc99d\uc774 \ud544\uc694\ud569\ub2c8\ub2e4. \uc2e0\uccad\uc11c\uc5d0 \uc774\ub984, \uc8fc\uc18c, \uc5f0\ub77d\ucc98\ub97c \uc4f0\uace0 \uc544\ub798\uc5d0 \uc11c\uba85\ud574 \uc8fc\uc138\uc694.",A.iaw,0,"\u0110o\u1ea1n v\u0103n n\xf3i c\u1ea7n \u0111\u01a1n \u0111\u0103ng k\xfd v\xe0 gi\u1ea5y t\u1edd t\xf9y th\xe2n.")
A.iyS=s(["\uc11c\ub958\uac00 \ubaa8\ub450 \uc644\ubcbd\ud588\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \ubd80\uc871\ud55c \uc11c\ub958\ub97c \ucd94\uac00\ub85c \uc900\ube44\ud574\uc57c \ud569\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \uc2e0\uccad\uc744 \uc774\ubbf8 \ucde8\uc18c\ud588\uc2b5\ub2c8\ub2e4.","\uc9c1\uc6d0\uc740 \uc11c\ub958\uac00 \ud544\uc694 \uc5c6\ub2e4\uace0 \ud588\uc2b5\ub2c8\ub2e4."],t.s)
A.e0f=new B.T("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\ubbfc \uc528\uac00 \uc81c\ucd9c\ud55c \uc11c\ub958\uc5d0\ub294 \ud55c \uac00\uc9c0\uac00 \ube60\uc838 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uc9c1\uc6d0\uc740 \ubd80\uc871\ud55c \uc11c\ub958\ub97c \uc900\ube44\ud574\uc11c \ub2e4\uc2dc \uc81c\ucd9c\ud574 \ub2ec\ub77c\uace0 \ud588\uc2b5\ub2c8\ub2e4.",A.iyS,1,"Min c\u1ea7n chu\u1ea9n b\u1ecb th\xeam gi\u1ea5y t\u1edd c\xf2n thi\u1ebfu.")
A.haC=s(["\ubbfc \uc528\ub294 \uc774\uc0ac \ud6c4 \ud544\uc694\ud55c \uc808\ucc28\ub97c \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \ud574\uc678\uc5ec\ud589\uc744 \uc608\uc57d\ud588\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \ubcd1\uc6d0\uc5d0\uc11c \uce58\ub8cc\ubc1b\uc558\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \ud68c\uc0ac\uc5d0 \uc785\uc0ac\ud588\uc2b5\ub2c8\ub2e4."],t.s)
A.e15=new B.T("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\ubbfc \uc528\ub294 \uc774\uc0ac\ud55c \ud6c4 \uc8fc\uc18c\uc640 \uad00\ub828\ub41c \ud589\uc815 \uc5c5\ubb34\ub97c \ud655\uc778\ud558\ub824\uace0 \uae30\uad00\uc5d0 \ubb38\uc758\ud588\uc2b5\ub2c8\ub2e4. \ud544\uc694\ud55c \uc808\ucc28\uc640 \uc11c\ub958\ub97c \uba3c\uc800 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.",A.haC,0,"\u0110o\u1ea1n v\u0103n n\xf3i v\u1ec1 vi\u1ec7c h\u1ecfi th\u1ee7 t\u1ee5c li\xean quan \u0111\u1ebfn \u0111\u1ecba ch\u1ec9 sau khi chuy\u1ec3n nh\xe0.")
A.hpm=s(["\uacf5\uacf5\uae30\uad00\uc5d0\uc11c \ubbfc\uc6d0 \uc5c5\ubb34 \ubcf4\uae30","\uc2dd\ub2f9\uc5d0\uc11c \uc74c\uc2dd \uc8fc\ubb38\ud558\uae30","\ud68c\uc0ac\uc5d0\uc11c \uc548\uc804\uad50\uc721 \ubc1b\uae30","\uc57d\uad6d\uc5d0\uc11c \uc57d \uc0ac\uae30"],t.s)
A.e_2=new B.T("\ub2e4\uc74c\uc744 \uc77d\uace0 \uac00\uc7a5 \uc54c\ub9de\uc740 \uc81c\ubaa9\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\ubbfc \uc528\ub294 \uacf5\uacf5\uae30\uad00\uc744 \ubc29\ubb38\ud558\uae30 \uc804\uc5d0 \uc6b4\uc601\uc2dc\uac04\uacfc \ud544\uc694\ud55c \uc11c\ub958\ub97c \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4. \uae30\uad00\uc5d0 \ub3c4\ucc29\ud55c \ud6c4 \ubc88\ud638\ud45c\ub97c \ubf51\uace0 \uc2e0\uccad\uc11c\ub97c \uc791\uc131\ud588\uc2b5\ub2c8\ub2e4. \uc790\uc2e0\uc758 \uc21c\uc11c\uac00 \ub418\uc790 \ucc3d\uad6c\uc5d0 \uc11c\ub958\ub97c \uc81c\ucd9c\ud588\uc2b5\ub2c8\ub2e4.",A.hpm,0,"\u0110o\u1ea1n v\u0103n m\xf4 t\u1ea3 tr\xecnh t\u1ef1 l\xe0m th\u1ee7 t\u1ee5c t\u1ea1i c\u01a1 quan c\xf4ng.")
