A.e3h=new B.T("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\ubbfc \uc528\ub294 \uc624\ub298 \ubab8\uc774 \uc544\ud30c\uc11c \ud68c\uc0ac\uc5d0 \uac00\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4. \ud68c\uc0ac\uc5d0 \ubbf8\ub9ac \uc804\ud654\ud55c \ud6c4 \ubcd1\uc6d0\uc5d0 \uac00\uc11c \uc9c4\ub8cc\ub97c \ubc1b\uc558\uc2b5\ub2c8\ub2e4.",A.iyk,0,"Min b\u1ecb \u1ed1m, b\xe1o c\xf4ng ty tr\u01b0\u1edbc r\u1ed3i \u0111i b\u1ec7nh vi\u1ec7n.")
A.hP8=s(["\ubbfc \uc528\ub294 \ud544\uc694\ud55c \uc11c\ub958\ub97c \uba3c\uc800 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \ubcd1\uc6d0 \uc608\uc57d\uc744 \ud588\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \uc6b0\uccb4\uad6d\uc5d0\uc11c \uc18c\ud3ec\ub97c \ubcf4\ub0c8\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \uc5ec\ud589 \uc911\uc785\ub2c8\ub2e4."],t.s)
A.e2S=new B.T("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\ubbfc \uc528\ub294 \uc774\uc0ac\ud55c \ud6c4 \uc8fc\ubbfc\uc13c\ud130\uc5d0 \ud544\uc694\ud55c \ud589\uc815 \uc5c5\ubb34\ub97c \ubb38\uc758\ud588\uc2b5\ub2c8\ub2e4. \ubc29\ubb38\ud558\uae30 \uc804\uc5d0 \ud544\uc694\ud55c \uc11c\ub958\ub97c \uba3c\uc800 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.",A.hP8,0,"Min \u0111\xe3 ki\u1ec3m tra tr\u01b0\u1edbc h\u1ed3 s\u01a1 c\u1ea7n thi\u1ebft.")
A.h5l=s(["\ubbfc \uc528\ub294 \uc548\uc804\ud558\uac8c \uc791\uc5c5\uc744 \uc911\ub2e8\ud588\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \uacc4\uc18d \uc791\uc5c5\ud588\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \uae30\uacc4\ub97c \uc9d1\uc73c\ub85c \uac00\uc838\uac14\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \uc544\ubb34\uc5d0\uac8c\ub3c4 \ub9d0\ud558\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4."],t.s)
A.e50=new B.T("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\uc791\uc5c5 \uc911 \uae30\uacc4\uc5d0\uc11c \uc774\uc0c1\ud55c \uc18c\ub9ac\uac00 \ub0ac\uc2b5\ub2c8\ub2e4. \ubbfc \uc528\ub294 \ubc14\ub85c \uc791\uc5c5\uc744 \uc911\ub2e8\ud558\uace0 \ud300\uc7a5\uc5d0\uac8c \uc0c1\ud669\uc744 \ubcf4\uace0\ud588\uc2b5\ub2c8\ub2e4.",A.h5l,0,"Min d\u1eebng c\xf4ng vi\u1ec7c v\xe0 b\xe1o c\xe1o khi m\xe1y c\xf3 d\u1ea5u hi\u1ec7u b\u1ea5t th\u01b0\u1eddng.")
A.iP_=s(["\ubbfc \uc528\ub294 \uc815\uc911\ud558\uac8c \ubb38\uc81c\ub97c \uc774\uc57c\uae30\ud588\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \ub354 \ud070 \uc18c\ub9ac\ub97c \ub0c8\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \uacbd\ucc30\uc11c\uc5d0\uc11c \uc77c\ud588\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \ubc14\ub85c \uc774\uc0ac\ud588\uc2b5\ub2c8\ub2e4."],t.s)
A.e1s=new B.T("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\uc704\uce35\uc5d0\uc11c \ubc24\ub2a6\uac8c \ud070 \uc18c\ub9ac\uac00 \uacc4\uc18d \ub4e4\ub838\uc2b5\ub2c8\ub2e4. \ubbfc \uc528\ub294 \ud654\ub97c \ub0b4\uc9c0 \uc54a\uace0 \uc815\uc911\ud558\uac8c \uc870\uc6a9\ud788 \ud574 \ub2ec\ub77c\uace0 \ubd80\ud0c1\ud588\uc2b5\ub2c8\ub2e4.",A.iP_,0,"Min gi\u1ea3i quy\u1ebft v\u1ea5n \u0111\u1ec1 v\u1edbi h\xe0ng x\xf3m b\u1eb1ng c\xe1ch n\xf3i l\u1ecbch s\u1ef1.")
A.iKn=s(["\ubbfc \uc528\ub294 \uc5ec\ud589 \uc804\uc5d0 \ud544\uc694\ud55c \uac83\uc744 \uc900\ube44\ud588\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \uc544\ubb34 \uacc4\ud68d\ub3c4 \uc138\uc6b0\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \ubcd1\uc6d0\uc5d0 \uc785\uc6d0\ud588\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \ud68c\uc0ac\uc5d0\uc11c \uc57c\uadfc\ud588\uc2b5\ub2c8\ub2e4."],t.s)
A.e02=new B.T("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\ubbfc \uc528\ub294 \ud734\uac00\uc5d0 \ubd80\uc0b0 \uc5ec\ud589\uc744 \uacc4\ud68d\ud588\uc2b5\ub2c8\ub2e4. \ucd9c\ubc1c\ud558\uae30 \uc804\uc5d0 \uae30\ucc28\ud45c\uc640 \ud638\ud154\uc744 \uc608\uc57d\ud558\uace0 \ub0a0\uc528\ub3c4 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.",A.iKn,0,"Min \u0111\xe3 chu\u1ea9n b\u1ecb v\xe9, kh\xe1ch s\u1ea1n v\xe0 ki\u1ec3m tra th\u1eddi ti\u1ebft.")
A.fUL=s(["\ud55c\uad6d \uc0dd\ud65c\uc5d0\uc11c\ub294 \uc0c1\ud669\uc5d0 \ub9de\ub294 \uc608\uc808\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\ubaa8\ub4e0 \uc0ac\ub78c\uc5d0\uac8c \ubc18\ub9d0\uc744 \ud574\uc57c \ud569\ub2c8\ub2e4.","\uacf5\uacf5\uc7a5\uc18c\uc5d0\uc11c\ub294 \ud070 \uc18c\ub9ac\ub85c \ub9d0\ud574\uc57c \ud569\ub2c8\ub2e4.","\ub2e4\ub978 \uc0ac\ub78c\uc744 \ubc30\ub824\ud560 \ud544\uc694\uac00 \uc5c6\uc2b5\ub2c8\ub2e4."],t.s)
A.e28=new B.T("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\ucc98\uc74c \ub9cc\ub09c \uc0ac\ub78c\uacfc \uc774\uc57c\uae30\ud560 \ub54c\ub294 \ubcf4\ud1b5 \uc874\ub313\ub9d0\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4. \uacf5\uacf5\uc7a5\uc18c\uc5d0\uc11c\ub294 \ud070 \uc18c\ub9ac\ub85c \uc774\uc57c\uae30\ud558\uc9c0 \uc54a\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc744 \ubc30\ub824\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.",A.fUL,0,"\u0110o\u1ea1n v\u0103n nh\u1ea5n m\u1ea1nh ph\xe9p l\u1ecbch s\u1ef1 ph\xf9 h\u1ee3p v\u1edbi t\xecnh hu\u1ed1ng.")
A.hs5=s(["\ubbfc \uc528\ub294 \uc4f0\ub808\uae30\ub97c \ubd84\ub9ac\ud574\uc11c \ubc84\ub838\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \uc4f0\ub808\uae30\ub97c \ubcf5\ub3c4\uc5d0 \ubc84\ub838\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \ubcd1\uc6d0\uc5d0 \uac14\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \uae30\ucc28\ud45c\ub97c \uc0c0\uc2b5\ub2c8\ub2e4."],t.s)
A.e5m=new B.T("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\ubbfc \uc528\ub294 \ub9c8\ud2b8\uc5d0\uc11c \uc7a5\uc744 \ubcf8 \ud6c4 \uc9d1\uc5d0 \uc654\uc2b5\ub2c8\ub2e4. \uc800\ub141\uc744 \uba39\uace0 \uc4f0\ub808\uae30\ub97c \uc885\ub958\ubcc4\ub85c \ub098\ub204\uc5b4 \uc815\ud574\uc9c4 \uacf3\uc5d0 \ubc84\ub838\uc2b5\ub2c8\ub2e4.",A.hs5,0,"Min \u0111\xe3 ph\xe2n lo\u1ea1i r\xe1c tr\u01b0\u1edbc khi b\u1ecf.")
A.hs_=s(["\ubbfc \uc528\ub294 \ub2a6\uc744 \uac83 \uac19\uc544\uc11c \ubbf8\ub9ac \uc5f0\ub77d\ud588\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \uc544\ubb34 \uc5f0\ub77d\ub3c4 \ud558\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \uc57d\uc18d\uc744 \uc78a\uc5c8\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \uce5c\uad6c\uc5d0\uac8c \ud654\ub97c \ub0c8\uc2b5\ub2c8\ub2e4."],t.s)
A.e2l=new B.T("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\ubbfc \uc528\ub294 \uc57d\uc18d \uc2dc\uac04\ubcf4\ub2e4 \ub2a6\uc744 \uac83 \uac19\uc544\uc11c \uce5c\uad6c\uc5d0\uac8c \ubbf8\ub9ac \uc804\ud654\ud588\uc2b5\ub2c8\ub2e4. \ub3c4\ucc29 \uc608\uc815 \uc2dc\uac04\uc744 \uc54c\ub824 \uc8fc\uace0 \ubbf8\uc548\ud558\ub2e4\uace0 \ub9d0\ud588\uc2b5\ub2c8\ub2e4.",A.hs_,0,"Min \u0111\xe3 b\xe1o tr\u01b0\u1edbc v\xec c\xf3 kh\u1ea3 n\u0103ng \u0111\u1ebfn mu\u1ed9n.")
A.iPz=s(["\ud55c\uad6d \uc0dd\ud65c\uc5d0 \ud544\uc694\ud55c \uc758\uc0ac\uc18c\ud1b5","\ud55c \uac00\uc9c0 \uc74c\uc2dd \ub9cc\ub4dc\ub294 \ubc29\ubc95","\uc6b4\ub3d9 \uacbd\uae30 \uaddc\uce59","\ud68c\uc0ac \uc81c\ud488 \uac00\uaca9"],t.s)
A.e46=new B.T("\ub2e4\uc74c\uc744 \uc77d\uace0 \uac00\uc7a5 \uc54c\ub9de\uc740 \uc81c\ubaa9\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\ud55c\uad6d\uc5d0\uc11c \uc0dd\ud65c\ud558\ub824\uba74 \uad50\ud1b5, \ubcd1\uc6d0, \uc740\ud589, \uacf5\uacf5\uae30\uad00 \ub4f1 \uc5ec\ub7ec \uacf3\uc744 \uc774\uc6a9\ud558\uac8c \ub429\ub2c8\ub2e4. \ubb38\uc81c\uac00 \uc0dd\uae30\uba74 \uc0c1\ud669\uc744 \uc815\ud655\ud558\uac8c \uc124\uba85\ud558\uace0 \ud544\uc694\ud55c \ub3c4\uc6c0\uc744 \uc694\uccad\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.",A.iPz,0,"\u0110o\u1ea1n v\u0103n n\xf3i v\u1ec1 giao ti\u1ebfp c\u1ea7n thi\u1ebft trong cu\u1ed9c s\u1ed1ng \u1edf H\xe0n Qu\u1ed1c.")
