A.eK4=new B.aO("-\uae30 \ub9c8\ub828\uc774\ub2e4","v\u1ed1n d\u0129 th\u01b0\u1eddng..., \u0111\u01b0\u01a1ng nhi\xean s\u1ebd...","\uc77c\ubc18\uc801\uc778 \uc0c1\ud669\uc5d0\uc11c \uc790\uc5f0\uc2a4\ub7fd\uac8c \uadf8\ub807\uac8c \ub418\uae30 \uc27d\uac70\ub098 \ub2f9\uc5f0\ud55c \uacb0\uacfc\uc784\uc744 \ub098\ud0c0\ub0c5\ub2c8\ub2e4.","\uc0c8\ub85c\uc6b4 \ud559\uad50\uc5d0 \uac00\uba74 \ucc98\uc74c\uc5d0\ub294 \uae34\uc7a5\ud558\uae30 \ub9c8\ub828\uc785\ub2c8\ub2e4.","Khi \u0111\u1ebfn tr\u01b0\u1eddng m\u1edbi th\xec l\xfac \u0111\u1ea7u \u0111\u01b0\u01a1ng nhi\xean th\u01b0\u1eddng s\u1ebd c\u0103ng th\u1eb3ng.")
A.eLv=new B.aO("-\uac8c \ub418\ub2e4","tr\u1edf n\xean, \u0111i \u0111\u1ebfn vi\u1ec7c...","\uc0c1\ud669\uc774\ub098 \ud658\uacbd\uc758 \ubcc0\ud654\ub85c \uc778\ud574 \uc5b4\ub5a4 \ud589\ub3d9\uc744 \ud558\uac70\ub098 \uc0c8\ub85c\uc6b4 \uc0c1\ud0dc\uac00 \ub428\uc744 \ub098\ud0c0\ub0c5\ub2c8\ub2e4.","\uc774\uc0ac\ub97c \ud558\uba74\uc11c \uc544\uc774\uac00 \ub2e4\ub978 \ud559\uad50\ub85c \uc804\ud559\ud558\uac8c \ub418\uc5c8\uc2b5\ub2c8\ub2e4.",u.ke)
A.eJl=new B.aO("-\uae30 \uc704\ud574\uc11c","\u0111\u1ec3...","\uc5b4\ub5a4 \ubaa9\uc801\uc744 \uc774\ub8e8\uae30 \uc704\ud574 \ud558\ub294 \ud589\ub3d9\uc744 \ub098\ud0c0\ub0bc \ub54c \uc0ac\uc6a9\ud569\ub2c8\ub2e4.","\ub300\ud559\uc5d0 \uc9c4\ud559\ud558\uae30 \uc704\ud574\uc11c \uc5f4\uc2ec\ud788 \uacf5\ubd80\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.",u.bE)
A.eLB=new B.aO("-\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4","vi\u1ec7c... l\xe0 quan tr\u1ecdng","\ud2b9\uc815 \ud589\ub3d9\uc774\ub098 \ud0dc\ub3c4\uc758 \uc911\uc694\uc131\uc744 \uc124\uba85\ud560 \ub54c \uc790\uc8fc \uc0ac\uc6a9\ud558\ub294 \ud45c\ud604\uc785\ub2c8\ub2e4.","\uc544\uc774\uc758 \ud559\uad50\uc0dd\ud65c\uc5d0 \ub300\ud574 \uc120\uc0dd\ub2d8\uacfc \uc790\uc8fc \uc18c\ud1b5\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","Vi\u1ec7c th\u01b0\u1eddng xuy\xean trao \u0111\u1ed5i v\u1edbi gi\xe1o vi\xean v\u1ec1 \u0111\u1eddi s\u1ed1ng h\u1ecdc \u0111\u01b0\u1eddng c\u1ee7a con l\xe0 r\u1ea5t quan tr\u1ecdng.")
