A.eMY=new B.aj('"\ud3c9\uc0dd\uad50\uc721"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?',A.h5S,0,'"\ud3c9\uc0dd\uad50\uc721"\uc740 \ud559\uad50 \uad50\uc721\uc774 \ub05d\ub09c \ub4a4\uc5d0\ub3c4 \uac1c\uc778\uc774 \ud544\uc694\uc5d0 \ub530\ub77c \uacc4\uc18d \ubc30\uc6b0\uace0 \uc131\uc7a5\ud558\ub294 \uad50\uc721\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4.')
A.irE=s(["\u2460 \uad00\uc2ec, \uc801\uc131, \ub2a5\ub825 \ub4f1\uc744 \ud568\uaed8 \uace0\ub824\ud55c\ub2e4","\u2461 \uc131\uc801\ub9cc \ubcf4\uace0 \ubb34\uc870\uac74 \uacb0\uc815\ud55c\ub2e4","\u2462 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc120\ud0dd\uc744 \uadf8\ub300\ub85c \ub530\ub77c \ud55c\ub2e4","\u2463 \uc544\ubb34 \uc815\ubcf4 \uc5c6\uc774 \uacb0\uc815\ud55c\ub2e4"],t.s)
A.eNt=new B.aj("\ud559\uc0dd\uc758 \uc9c4\ub85c\ub97c \uc120\ud0dd\ud560 \ub54c \uace0\ub824\ud558\uba74 \uc88b\uc740 \uac83\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.irE,0,"\uc9c4\ub85c \uc120\ud0dd\uc5d0\uc11c\ub294 \uc131\uc801\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc790\uc2e0\uc758 \uad00\uc2ec, \uc801\uc131, \ub2a5\ub825\uacfc \ubbf8\ub798 \uacc4\ud68d \ub4f1\uc744 \ud568\uaed8 \uace0\ub824\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.i57=s(["\u2460 \ub9c8\ub828\uc774\uc5d0\uc694","\u2461 \uc870\ucc28\uc608\uc694","\u2462 \uacb8\uc774\uc5d0\uc694","\u2463 \ub098\uba38\uc9c0\uc608\uc694"],t.s)
A.eOF=new B.aj("\ub2e4\uc74c \ub300\ud654\uc5d0 \ub4e4\uc5b4\uac08 \ud45c\ud604\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?\n\n\uac00: \uc544\uc774\uac00 \ub2e4\uc74c \ub2ec\uc5d0 \ub2e4\ub978 \ud559\uad50\ub85c \uc804\ud559\uc744 \uac00\uc694. \ub9ce\uc774 \uac71\uc815\ud558\ub124\uc694.\n\ub098: \uc0c8\ub85c\uc6b4 \ud559\uad50\uc5d0 \uac00\uba74 \ucc98\uc74c\uc5d0\ub294 \uae34\uc7a5\ud558\uae30______.",A.i57,0,'\uc0c8\ub85c\uc6b4 \ud658\uacbd\uc5d0\uc11c \ucc98\uc74c \uae34\uc7a5\ud558\ub294 \uac83\uc740 \uc77c\ubc18\uc801\uc73c\ub85c \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \ud604\uc0c1\uc774\ub77c\ub294 \ub73b\uc774\ubbc0\ub85c "-\uae30 \ub9c8\ub828\uc774\ub2e4"\uac00 \uac00\uc7a5 \uc54c\ub9de\uc2b5\ub2c8\ub2e4.')
A.iFN=s([A.ePg,A.eMJ,A.ePq,A.eO5,A.eOW,A.eON,A.eNE,A.eMY,A.eNt,A.eOF],t.Fo)
A.hGw=s(["\uad50\uc721 = gi\xe1o d\u1ee5c.","\uad50\uc721 \uc81c\ub3c4 = h\u1ec7 th\u1ed1ng gi\xe1o d\u1ee5c.","\uc758\ubb34\uad50\uc721 = gi\xe1o d\u1ee5c b\u1eaft bu\u1ed9c.","\uc720\uce58\uc6d0 = tr\u01b0\u1eddng m\u1eabu gi\xe1o.","\ucd08\ub4f1\ud559\uad50 = tr\u01b0\u1eddng ti\u1ec3u h\u1ecdc.","\uc911\ud559\uad50 = tr\u01b0\u1eddng trung h\u1ecdc c\u01a1 s\u1edf.","\uace0\ub4f1\ud559\uad50 = tr\u01b0\u1eddng trung h\u1ecdc ph\u1ed5 th\xf4ng.","\ub300\ud559\uad50 = tr\u01b0\u1eddng \u0111\u1ea1i h\u1ecdc.","\uc785\ud559\ud558\ub2e4 = nh\u1eadp h\u1ecdc.","\uc878\uc5c5\ud558\ub2e4 = t\u1ed1t nghi\u1ec7p.","\uc9c4\ud559\ud558\ub2e4 = h\u1ecdc ti\u1ebfp l\xean b\u1eadc cao h\u01a1n.","\uc804\ud559\ud558\ub2e4 = chuy\u1ec3n tr\u01b0\u1eddng.","\uc804\uacf5 = chuy\xean ng\xe0nh.","\uc218\uc5c5 = gi\u1edd h\u1ecdc.","\ud559\uae30 = h\u1ecdc k\u1ef3.","\ubc29\ud559 = k\u1ef3 ngh\u1ec9.","\uc131\uc801 = \u0111i\u1ec3m s\u1ed1 / th\xe0nh t\xedch h\u1ecdc t\u1eadp.","\uc2dc\ud5d8 = k\u1ef3 thi.","\uacfc\uc81c = b\xe0i t\u1eadp.","\uad50\uc0ac = gi\xe1o vi\xean.","\ud559\uc0dd = h\u1ecdc sinh / sinh vi\xean.","\ud559\ubd80\ubaa8 = ph\u1ee5 huynh h\u1ecdc sinh.","\ubcf4\ud638\uc790 = ng\u01b0\u1eddi gi\xe1m h\u1ed9.",u.eH,"\uc54c\ub9bc\uc7a5 = s\u1ed5/th\xf4ng b\xe1o li\xean l\u1ea1c c\u1ee7a tr\u01b0\u1eddng.","\ud559\uad50\uc0dd\ud65c = \u0111\u1eddi s\u1ed1ng h\u1ecdc \u0111\u01b0\u1eddng.","\uc0c1\ub2f4 = t\u01b0 v\u1ea5n / trao \u0111\u1ed5i.","\uc9c4\ub85c = \u0111\u1ecbnh h\u01b0\u1edbng t\u01b0\u01a1ng lai / ngh\u1ec1 nghi\u1ec7p.","\uc9c1\uc5c5\uad50\uc721 = gi\xe1o d\u1ee5c ngh\u1ec1 nghi\u1ec7p.","\ud3c9\uc0dd\uad50\uc721 = gi\xe1o d\u1ee5c su\u1ed1t \u0111\u1eddi.","(\uba85)\uc870\ucc28 = ngay c\u1ea3...","-\ub294 \uac83\uc870\ucc28 = ngay c\u1ea3 vi\u1ec7c...","-\uae30 \ub9c8\ub828\uc774\ub2e4 = v\u1ed1n th\u01b0\u1eddng / \u0111\u01b0\u01a1ng nhi\xean th\u01b0\u1eddng s\u1ebd...","-\uac8c \ub418\ub2e4 = tr\u1edf n\xean / \u0111i \u0111\u1ebfn vi\u1ec7c...","-\uae30 \uc704\ud574\uc11c = \u0111\u1ec3...","-\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4 = vi\u1ec7c... l\xe0 quan tr\u1ecdng.","\uc0c8\ub85c\uc6b4 \ud559\uad50\ub098 \uad50\uc721 \ud658\uacbd\uc5d0 \ub4e4\uc5b4\uac00\uba74 \ucc98\uc74c\uc5d0\ub294 \ub0af\uc124\uace0 \uae34\uc7a5\ud558\uae30 \ub9c8\ub828\uc785\ub2c8\ub2e4.","\uc790\ub140\uc758 \ud559\uad50\uc0dd\ud65c\uc744 \ub3d5\uae30 \uc704\ud574\uc11c\ub294 \uac00\uc815\ud1b5\uc2e0\ubb38\uacfc \ud559\uad50 \uc548\ub0b4\ub97c \uc798 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\ud559\uad50\uc0dd\ud65c\uc5d0 \ubb38\uc81c\uac00 \uc0dd\uae30\uba74 \ud559\uc0dd\uc758 \uc774\uc57c\uae30\ub97c \ub4e3\uace0 \ud544\uc694\ud55c \uacbd\uc6b0 \uad50\uc0ac\uc640 \uc0c1\ub2f4\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","\uc9c4\ub85c\ub97c \uc120\ud0dd\ud560 \ub54c\ub294 \uc131\uc801\ubfd0\ub9cc \uc544\ub2c8\ub77c \uad00\uc2ec, \uc801\uc131, \ub2a5\ub825\uacfc \ubbf8\ub798 \uacc4\ud68d\uc744 \ud568\uaed8 \uc0dd\uac01\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\uad50\uc721\uc740 \ud559\uad50\uc5d0\uc11c \ub05d\ub098\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc9c1\uc5c5\uad50\uc721\uacfc \ud3c9\uc0dd\uad50\uc721\uc744 \ud1b5\ud574 \uacc4\uc18d \uc774\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],t.s)
A.Kg=new B.hG(11,"\uad50\uc721 \uc81c\ub3c4","H\u1ec7 th\u1ed1ng gi\xe1o d\u1ee5c",A.i3D,A.fM5,A.hWl,A.hDy,A.iFN,A.hGw)
A.i9B=s(["\ud55c\uad6d\uc5d0\uc11c \uc0dd\ud65c\ud558\ub294 \uc774\ubbfc\uc790\uac00 \uacaa\uc744 \uc218 \uc788\ub294 \ub2e4\uc591\ud55c \uc0dd\ud65c \ubb38\uc81c\ub97c \uc774\ud574\ud569\ub2c8\ub2e4.","\uccb4\ub958, \ud589\uc815, \uc8fc\uac70, \uc9c1\uc7a5, \uc758\ub8cc, \uad50\uc721 \ub4f1 \uc774\ubbfc \uc0dd\ud65c\uacfc \uad00\ub828\ub41c \uae30\ubcf8\uc801\uc778 \ub0b4\uc6a9\uc744 \uc54c\uc544\ubd05\ub2c8\ub2e4.","\uccb4\ub958 \uc790\uaca9\uacfc \uccb4\ub958 \uae30\uac04 \ub4f1 \uc911\uc694\ud55c \uc815\ubcf4\ub97c \uc815\ud655\ud558\uac8c \ud655\uc778\ud558\ub294 \ud0dc\ub3c4\uac00 \ud544\uc694\ud558\ub2e4\ub294 \uc810\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\ud589\uc815 \uc5c5\ubb34\ub97c \ucc98\ub9ac\ud560 \ub54c \ud544\uc694\ud55c \uc11c\ub958\uc640 \uc808\ucc28\ub97c \ubbf8\ub9ac \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4\ub294 \uc810\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ud55c\uad6d\uc5b4\uc640 \ubb38\ud654 \ucc28\uc774 \ub54c\ubb38\uc5d0 \uc5b4\ub824\uc6c0\uc744 \uacaa\uc744 \uc218 \uc788\uc9c0\ub9cc \uc8fc\ubcc0 \uae30\uad00\uacfc \uc0ac\ub78c\uc758 \ub3c4\uc6c0\uc744 \uc774\uc6a9\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \uc54c\uc544\ubd05\ub2c8\ub2e4.","\uc9c1\uc7a5\uacfc \uc9c0\uc5ed\uc0ac\ud68c\uc5d0\uc11c \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uacfc \uc6d0\ud65c\ud558\uac8c \uc758\uc0ac\uc18c\ud1b5\ud558\uace0 \uc11c\ub85c\uc758 \ubb38\ud654\ub97c \uc874\uc911\ud558\ub294 \ud0dc\ub3c4\ub97c \ubc30\uc6c1\ub2c8\ub2e4.","\ud55c\uad6d \uc0ac\ud68c\uc5d0 \uc801\uc751\ud558\uba74\uc11c \uc790\uc2e0\uc758 \ubb38\ud654\uc640 \uc815\uccb4\uc131\ub3c4 \ud568\uaed8 \uc874\uc911\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\uc548\uc815\uc801\uc778 \uc774\ubbfc \uc0dd\ud65c\uc744 \uc704\ud574 \uc815\ud655\ud55c \uc815\ubcf4, \uc5b8\uc5b4 \ub2a5\ub825, \uc0ac\ud68c\uc801 \uad00\uacc4, \ucc45\uc784 \uc788\ub294 \uc0dd\ud65c \ud0dc\ub3c4\uac00 \uc911\uc694\ud558\ub2e4\ub294 \uc810\uc744 \ubc30\uc6c1\ub2c8\ub2e4."],t.s)
A.f2l=new B.A("\uc774\ubbfc","di c\u01b0, nh\u1eadp c\u01b0","\uc774\ubbfc \uc0dd\ud65c\uc744 \uc2dc\uc791\ud558\uba74 \uc0c8\ub85c\uc6b4 \ud658\uacbd\uc5d0 \uc801\uc751\ud558\ub294 \uc2dc\uac04\uc774 \ud544\uc694\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","Khi b\u1eaft \u0111\u1ea7u cu\u1ed9c s\u1ed1ng nh\u1eadp c\u01b0 c\xf3 th\u1ec3 c\u1ea7n th\u1eddi gian \u0111\u1ec3 th\xedch nghi v\u1edbi m\xf4i tr\u01b0\u1eddng m\u1edbi.")
A.f_y=new B.A("\uc774\ubbfc\uc790","ng\u01b0\u1eddi nh\u1eadp c\u01b0","\ud55c\uad6d\uc5d0\ub294 \ub2e4\uc591\ud55c \ub098\ub77c\uc5d0\uc11c \uc628 \uc774\ubbfc\uc790\ub4e4\uc774 \uc0b4\uace0 \uc788\uc2b5\ub2c8\ub2e4.","\u1ede H\xe0n Qu\u1ed1c c\xf3 nh\u1eefng ng\u01b0\u1eddi nh\u1eadp c\u01b0 \u0111\u1ebfn t\u1eeb nhi\u1ec1u qu\u1ed1c gia kh\xe1c nhau.")
A.eXH=new B.A("\uc815\ucc29\ud558\ub2e4","\u1ed5n \u0111\u1ecbnh cu\u1ed9c s\u1ed1ng, \u0111\u1ecbnh c\u01b0","\ud55c\uad6d\uc5d0 \uc815\ucc29\ud558\uae30 \uc704\ud574 \ud55c\uad6d\uc5b4\uc640 \uc0dd\ud65c \ubb38\ud654\ub97c \ubc30\uc6b0\uace0 \uc788\uc2b5\ub2c8\ub2e4.","T\xf4i \u0111ang h\u1ecdc ti\u1ebfng H\xe0n v\xe0 v\u0103n h\xf3a \u0111\u1eddi s\u1ed1ng \u0111\u1ec3 \u1ed5n \u0111\u1ecbnh cu\u1ed9c s\u1ed1ng \u1edf H\xe0n Qu\u1ed1c.")
A.eYN=new B.A("\uc815\ucc29","s\u1ef1 \u1ed5n \u0111\u1ecbnh cu\u1ed9c s\u1ed1ng, \u0111\u1ecbnh c\u01b0","\uc548\uc815\uc801\uc778 \uc815\ucc29\uc744 \uc704\ud574\uc11c\ub294 \uc8fc\uac70\uc640 \uc9c1\uc7a5\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4.","\u0110\u1ec3 \u1ed5n \u0111\u1ecbnh cu\u1ed9c s\u1ed1ng th\xec nh\xe0 \u1edf v\xe0 c\xf4ng vi\u1ec7c c\u0169ng quan tr\u1ecdng.")
A.eZf=new B.A("\uccb4\ub958","l\u01b0u tr\xfa, c\u01b0 tr\xfa","\ud55c\uad6d\uc5d0\uc11c \uccb4\ub958\ud558\ub294 \ub3d9\uc548 \uad00\ub828 \uaddc\uc815\uc744 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.","Trong th\u1eddi gian c\u01b0 tr\xfa \u1edf H\xe0n Qu\u1ed1c c\u1ea7n ki\u1ec3m tra c\xe1c quy \u0111\u1ecbnh li\xean quan.")
A.eWY=new B.A("\uccb4\ub958 \uc790\uaca9","t\u01b0 c\xe1ch l\u01b0u tr\xfa","\uc790\uc2e0\uc758 \uccb4\ub958 \uc790\uaca9\uacfc \uac00\ub2a5\ud55c \ud65c\ub3d9 \ubc94\uc704\ub97c \uc815\ud655\ud788 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\u0110i\u1ec1u quan tr\u1ecdng l\xe0 ki\u1ec3m tra ch\xednh x\xe1c t\u01b0 c\xe1ch l\u01b0u tr\xfa v\xe0 ph\u1ea1m vi ho\u1ea1t \u0111\u1ed9ng \u0111\u01b0\u1ee3c ph\xe9p c\u1ee7a m\xecnh.")
A.eXg=new B.A("\uccb4\ub958 \uae30\uac04","th\u1eddi h\u1ea1n l\u01b0u tr\xfa","\uccb4\ub958 \uae30\uac04\uc774 \uc5b8\uc81c\uae4c\uc9c0\uc778\uc9c0 \ubbf8\ub9ac \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.","T\xf4i \u0111\xe3 ki\u1ec3m tra tr\u01b0\u1edbc th\u1eddi h\u1ea1n l\u01b0u tr\xfa \u0111\u1ebfn khi n\xe0o.")
A.eX7=new B.A("\uccb4\ub958 \uae30\uac04\uc744 \uc5f0\uc7a5\ud558\ub2e4","gia h\u1ea1n th\u1eddi gian l\u01b0u tr\xfa","\ud544\uc694\ud55c \uc808\ucc28\ub97c \ud655\uc778\ud55c \ud6c4 \uccb4\ub958 \uae30\uac04 \uc5f0\uc7a5\uc744 \uc900\ube44\ud588\uc2b5\ub2c8\ub2e4.","Sau khi ki\u1ec3m tra th\u1ee7 t\u1ee5c c\u1ea7n thi\u1ebft, t\xf4i \u0111\xe3 chu\u1ea9n b\u1ecb gia h\u1ea1n th\u1eddi gian l\u01b0u tr\xfa.")
A.eVa=new B.A("\ubcc0\uacbd\ud558\ub2e4","thay \u0111\u1ed5i","\uc8fc\uc18c\ub098 \uc911\uc694\ud55c \uc815\ubcf4\uac00 \ubc14\ub00c\uba74 \ud544\uc694\ud55c \uc808\ucc28\ub97c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.","N\u1ebfu \u0111\u1ecba ch\u1ec9 ho\u1eb7c th\xf4ng tin quan tr\u1ecdng thay \u0111\u1ed5i th\xec c\u1ea7n ki\u1ec3m tra th\u1ee7 t\u1ee5c c\u1ea7n thi\u1ebft.")
