A.eRR=new B.a5("\uc9c0\uc218","\uc815\ubcf4\uac00 \ubc14\ub00c\uc5c8\uc744\uc9c0\ub3c4 \ubaa8\ub974\ub2c8\uae4c \uc911\uc694\ud55c \ub0b4\uc6a9\uc740 \uacf5\uc2dd \uc548\ub0b4\ub098 \ub2f4\ub2f9 \uae30\uad00\uc744 \ud1b5\ud574 \ub2e4\uc2dc \ud655\uc778\ud558\ub294 \uac8c \uc88b\uc544\uc694.","V\xec th\xf4ng tin c\xf3 th\u1ec3 \u0111\xe3 thay \u0111\u1ed5i n\xean n\u1ed9i dung quan tr\u1ecdng n\xean \u0111\u01b0\u1ee3c ki\u1ec3m tra l\u1ea1i qua h\u01b0\u1edbng d\u1eabn ch\xednh th\u1ee9c ho\u1eb7c c\u01a1 quan ph\u1ee5 tr\xe1ch.")
A.eSB=new B.a5("\ubbfc","\ud544\uc694\ud55c \uc11c\ub958\uac00 \ucd94\uac00\ub85c \uc788\uc744\uc9c0\ub3c4 \ubaa8\ub974\uaca0\ub124\uc694.","C\xf3 th\u1ec3 c\u0169ng c\xf3 th\xeam gi\u1ea5y t\u1edd c\u1ea7n thi\u1ebft nh\u1ec9.")
A.eR3=new B.a5("\uc9c0\uc218","\ub9de\uc544\uc694. \uc2e0\uccad\ud558\uae30 \uc804\uc5d0 \uc11c\ub958\uc640 \uc808\ucc28\ub97c \ud655\uc778\ud558\uba74 \ub2e4\uc2dc \ubc29\ubb38\ud558\ub294 \uc77c\uc744 \uc904\uc77c \uc218 \uc788\uc5b4\uc694.","\u0110\xfang v\u1eady. N\u1ebfu ki\u1ec3m tra gi\u1ea5y t\u1edd v\xe0 th\u1ee7 t\u1ee5c tr\u01b0\u1edbc khi \u0111\u0103ng k\xfd th\xec c\xf3 th\u1ec3 gi\u1ea3m vi\u1ec7c ph\u1ea3i quay l\u1ea1i.")
A.eR2=new B.a5("\ubbfc","\uc800\ub294 \ucc98\uc74c \ud55c\uad6d\uc5d0 \uc654\uc744 \ub54c \ud589\uc815 \uc5c5\ubb34\ub97c \ucc98\ub9ac\ud558\ub294 \ub370 \uc815\ub9d0 \uc5b4\ub824\uc6c0\uc774 \ub9ce\uc558\uc5b4\uc694.","Khi m\u1edbi \u0111\u1ebfn H\xe0n Qu\u1ed1c t\xf4i g\u1eb7p r\u1ea5t nhi\u1ec1u kh\xf3 kh\u0103n trong vi\u1ec7c x\u1eed l\xfd th\u1ee7 t\u1ee5c h\xe0nh ch\xednh.")
A.eRC=new B.a5("\uc9c0\uc218","\uc774\ubbfc \uc0dd\ud65c\uc744 \ucc98\uc74c \uc2dc\uc791\ud55c \uc0ac\ub78c\uce58\uace0 \uadf8\ub7f0 \uc5b4\ub824\uc6c0\uc744 \uacaa\uc9c0 \uc54a\ub294 \uc0ac\ub78c\uc740 \uac70\uc758 \uc5c6\uc744 \uac70\uc608\uc694.","H\u1ea7u nh\u01b0 kh\xf4ng c\xf3 ng\u01b0\u1eddi m\u1edbi b\u1eaft \u0111\u1ea7u cu\u1ed9c s\u1ed1ng nh\u1eadp c\u01b0 m\xe0 kh\xf4ng tr\u1ea3i qua nh\u1eefng kh\xf3 kh\u0103n nh\u01b0 v\u1eady.")
A.eSb=new B.a5("\ubbfc","\ud55c\uad6d\uc5b4\ub97c \uc870\uae08\uc529 \ubc30\uc6b0\ub2c8\uae4c \ud63c\uc790 \ud560 \uc218 \uc788\ub294 \uc77c\uc774 \ub9ce\uc544\uc84c\uc5b4\uc694.","Khi h\u1ecdc ti\u1ebfng H\xe0n t\u1eebng ch\xfat m\u1ed9t, nh\u1eefng vi\u1ec7c t\xf4i c\xf3 th\u1ec3 t\u1ef1 l\xe0m \u0111\xe3 nhi\u1ec1u h\u01a1n.")
A.eRk=new B.a5("\uc9c0\uc218","\uc5b8\uc5b4\ub97c \ubc30\uc6b0\ub294 \uac83\uc774 \uc815\ucc29\ud558\ub294 \ub370 \uc815\ub9d0 \ub3c4\uc6c0\uc774 \ub418\uc9c0\uc694.","H\u1ecdc ng\xf4n ng\u1eef th\u1ef1c s\u1ef1 gi\xfap \xedch cho vi\u1ec7c \u1ed5n \u0111\u1ecbnh cu\u1ed9c s\u1ed1ng.")
A.eUi=new B.a5("\ubbfc","\uc9c1\uc7a5\uc744 \uad6c\ud560 \ub54c\ub3c4 \ubaa8\ub974\ub294 \uac8c \ub9ce\uc558\uc5b4\uc694.","Khi t\xecm vi\u1ec7c t\xf4i c\u0169ng c\xf3 nhi\u1ec1u \u0111i\u1ec1u kh\xf4ng bi\u1ebft.")
A.eSV=new B.a5("\uc9c0\uc218","\uc77c\uc744 \uc2dc\uc791\ud558\uae30 \uc804\uc5d0\ub294 \uadfc\ub85c\uacc4\uc57d\uc11c\uc640 \uadfc\ub85c\uc870\uac74\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud574\uc694.","Tr\u01b0\u1edbc khi b\u1eaft \u0111\u1ea7u l\xe0m vi\u1ec7c, vi\u1ec7c ki\u1ec3m tra h\u1ee3p \u0111\u1ed3ng v\xe0 \u0111i\u1ec1u ki\u1ec7n lao \u0111\u1ed9ng r\u1ea5t quan tr\u1ecdng.")
A.eTT=new B.a5("\ubbfc","\ud63c\uc790 \ud574\uacb0\ud558\uae30 \uc5b4\ub824\uc6b4 \uc77c\uc774 \uc0dd\uae30\uba74 \uc5b4\ub514\uc5d0 \ubb3c\uc5b4\ubcf4\ub294 \uac83\uc774 \uc88b\uc544\uc694?","N\u1ebfu c\xf3 vi\u1ec7c kh\xf3 t\u1ef1 gi\u1ea3i quy\u1ebft th\xec n\xean h\u1ecfi \u1edf \u0111\xe2u?")
A.eU8=new B.a5("\uc9c0\uc218","\ubb38\uc81c\uc758 \uc885\ub958\uc5d0 \ub530\ub77c \uad00\ub828 \uae30\uad00\uc774\ub098 \uc9c0\uc6d0\uc13c\ud130\uc5d0 \ubb38\uc758\ud558\uace0 \ud544\uc694\ud55c \uacbd\uc6b0 \ud1b5\uc5ed \ub3c4\uc6c0\uc744 \ubc1b\uc544 \ubcf4\uc138\uc694.","T\xf9y lo\u1ea1i v\u1ea5n \u0111\u1ec1, h\xe3y li\xean h\u1ec7 c\u01a1 quan ho\u1eb7c trung t\xe2m h\u1ed7 tr\u1ee3 li\xean quan v\xe0 n\u1ebfu c\u1ea7n th\xec nh\u1eadn tr\u1ee3 gi\xfap phi\xean d\u1ecbch.")
A.eRO=new B.a5("\ubbfc","\uc55e\uc73c\ub85c \ud55c\uad6d \uc0ac\ud68c\uc5d0 \ub354 \uc798 \uc801\uc751\ud558\ub3c4\ub85d \ub178\ub825\ud574\uc57c\uaca0\uc5b4\uc694.","Sau n\xe0y t\xf4i s\u1ebd c\u1ed1 g\u1eafng th\xedch nghi t\u1ed1t h\u01a1n v\u1edbi x\xe3 h\u1ed9i H\xe0n Qu\u1ed1c.")
A.eTD=new B.a5("\uc9c0\uc218","\ub124. \ubaa8\ub4e0 \uac83\uc744 \ud63c\uc790 \ud574\uacb0\ud558\ub824\uace0 \ud558\uae30\ubcf4\ub2e4 \ud544\uc694\ud55c \uc815\ubcf4\ub97c \ucc3e\uace0 \uc8fc\ubcc0\uc758 \ub3c4\uc6c0\uc744 \uc774\uc6a9\ud558\ub294 \uac83\ub3c4 \uc911\uc694\ud574\uc694.","V\xe2ng. Thay v\xec c\u1ed1 t\u1ef1 gi\u1ea3i quy\u1ebft m\u1ecdi th\u1ee9, vi\u1ec7c t\xecm th\xf4ng tin c\u1ea7n thi\u1ebft v\xe0 s\u1eed d\u1ee5ng s\u1ef1 gi\xfap \u0111\u1ee1 xung quanh c\u0169ng r\u1ea5t quan tr\u1ecdng.")
