A.iIr=s(["\uc774\ubbfc = di c\u01b0 / nh\u1eadp c\u01b0.","\uc774\ubbfc\uc790 = ng\u01b0\u1eddi nh\u1eadp c\u01b0.","\uc815\ucc29\ud558\ub2e4 = \u1ed5n \u0111\u1ecbnh cu\u1ed9c s\u1ed1ng / \u0111\u1ecbnh c\u01b0.","\uccb4\ub958 = l\u01b0u tr\xfa.","\uccb4\ub958 \uc790\uaca9 = t\u01b0 c\xe1ch l\u01b0u tr\xfa.","\uccb4\ub958 \uae30\uac04 = th\u1eddi h\u1ea1n l\u01b0u tr\xfa.","\uccb4\ub958 \uae30\uac04\uc744 \uc5f0\uc7a5\ud558\ub2e4 = gia h\u1ea1n th\u1eddi gian l\u01b0u tr\xfa.","\ud589\uc815 \uc808\ucc28 = th\u1ee7 t\u1ee5c h\xe0nh ch\xednh.","\uc11c\ub958 = gi\u1ea5y t\u1edd / h\u1ed3 s\u01a1.","\uc2e0\uccad\ud558\ub2e4 = \u0111\u0103ng k\xfd / n\u1ed9p \u0111\u01a1n.","\uc2e0\uccad\uc11c = \u0111\u01a1n \u0111\u0103ng k\xfd.","\uc81c\ucd9c\ud558\ub2e4 = n\u1ed9p.","\ubc1c\uae09\ubc1b\ub2e4 = \u0111\u01b0\u1ee3c c\u1ea5p.","\uc99d\uba85\uc11c = gi\u1ea5y ch\u1ee9ng nh\u1eadn.","\uae30\uad00 = c\u01a1 quan.","\ubb38\uc758\ud558\ub2e4 = li\xean h\u1ec7 h\u1ecfi.","\ud1b5\uc5ed = phi\xean d\u1ecbch.","\uc0dd\ud65c \uc815\ubcf4 = th\xf4ng tin \u0111\u1eddi s\u1ed1ng.","\uc9c0\uc6d0 \uc81c\ub3c4 = ch\u1ebf \u0111\u1ed9 h\u1ed7 tr\u1ee3.","\uc8fc\uac70 = nh\xe0 \u1edf.","\uadfc\ub85c\uacc4\uc57d\uc11c = h\u1ee3p \u0111\u1ed3ng lao \u0111\u1ed9ng.","\uadfc\ub85c\uc870\uac74 = \u0111i\u1ec1u ki\u1ec7n lao \u0111\u1ed9ng.","\uc0ac\ud68c\ubcf4\ud5d8 = b\u1ea3o hi\u1ec3m x\xe3 h\u1ed9i.","\uc758\ub8cc\uae30\uad00 = c\u01a1 s\u1edf y t\u1ebf.","\uc790\ub140 \uad50\uc721 = gi\xe1o d\u1ee5c con c\xe1i.","\uc9c0\uc5ed\uc0ac\ud68c = c\u1ed9ng \u0111\u1ed3ng \u0111\u1ecba ph\u01b0\u01a1ng.","\uc0ac\ud68c\uc5d0 \uc801\uc751\ud558\ub2e4 = th\xedch nghi v\u1edbi x\xe3 h\u1ed9i.","\uc0ac\ud68c \uad6c\uc131\uc6d0 = th\xe0nh vi\xean x\xe3 h\u1ed9i.","-(\uc73c)\u3139\uc9c0\ub3c4 \ubaa8\ub974\ub2e4 = c\xf3 th\u1ec3 / bi\u1ebft \u0111\xe2u...","-\uc558/\uc5c8\uc744\uc9c0\ub3c4 \ubaa8\ub974\ub2e4 = c\xf3 th\u1ec3 \u0111\xe3...","(\uba85)\uce58\uace0 = x\xe9t trong / trong s\u1ed1...","(\uba85)\uce58\uace0 -\uc9c0 \uc54a\ub2e4 = h\u1ea7u nh\u01b0 kh\xf4ng c\xf3... n\xe0o m\xe0 kh\xf4ng...",u.cM,"-\ub3c4\ub85d \ub178\ub825\ud558\ub2e4 = c\u1ed1 g\u1eafng \u0111\u1ec3...","\uc774\ubbfc \uc0dd\ud65c\uc5d0\uc11c\ub294 \uccb4\ub958, \uc8fc\uac70, \uc9c1\uc7a5, \uc758\ub8cc, \uad50\uc721 \ub4f1 \uc5ec\ub7ec \ubd84\uc57c\uc758 \uc0dd\ud65c \uc815\ubcf4\uac00 \ud544\uc694\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ud589\uc815 \uc5c5\ubb34\ub97c \ucc98\ub9ac\ud558\uae30 \uc804\uc5d0\ub294 \ud544\uc694\ud55c \uc11c\ub958\uc640 \uc808\ucc28\ub97c \uacf5\uc2dd\uc801\uc778 \uc548\ub0b4\ub97c \ud1b5\ud574 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\uc9c1\uc7a5\uc5d0\uc11c\ub294 \uadfc\ub85c\uacc4\uc57d\uc11c\uc640 \uadfc\ub85c\uc870\uac74\uc744 \ud655\uc778\ud558\uace0 \ubaa8\ub974\ub294 \ub0b4\uc6a9\uc740 \uc815\ud655\ud558\uac8c \uc9c8\ubb38\ud558\ub294 \ud0dc\ub3c4\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.","\ud55c\uad6d\uc5b4\ub97c \ubc30\uc6b0\uace0 \uc9c0\uc5ed\uc0ac\ud68c \uc0ac\ub78c\ub4e4\uacfc \uc18c\ud1b5\ud558\uba74 \ud55c\uad6d \uc0ac\ud68c\uc5d0 \uc801\uc751\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ud63c\uc790 \ud574\uacb0\ud558\uae30 \uc5b4\ub824\uc6b4 \ubb38\uc81c\uac00 \uc0dd\uae30\uba74 \ubb38\uc81c\uc758 \uc885\ub958\uc5d0 \ub9de\ub294 \uae30\uad00\uc774\ub098 \uc9c0\uc6d0\uc13c\ud130\uc758 \ub3c4\uc6c0\uc744 \uc774\uc6a9\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","\uc774\ubbfc \uc0dd\ud65c\uc5d0 \uc801\uc751\ud55c\ub2e4\ub294 \uac83\uc740 \uc790\uc2e0\uc758 \ubb38\ud654\ub97c \ubc84\ub9ac\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc0c8\ub85c\uc6b4 \uc0ac\ud68c\ub97c \uc774\ud574\ud558\uba74\uc11c \uc11c\ub85c\uc758 \ubb38\ud654\ub97c \uc874\uc911\ud558\uba70 \uc0b4\uc544\uac00\ub294 \uac83\uc785\ub2c8\ub2e4."],t.s)
A.Kh=new B.hG(16,"\uc774\ubbfc \uc0dd\ud65c","Cu\u1ed9c s\u1ed1ng nh\u1eadp c\u01b0",A.i9B,A.hW1,A.hRj,A.hx0,A.iG9,A.iIr)
A.i0P=s(["\uc77c\uc0c1\uc0dd\ud65c\uacfc \uacbd\uc81c \ud65c\ub3d9\uc758 \uad00\uacc4\ub97c \uc774\ud574\ud569\ub2c8\ub2e4.","\uc18c\ub4dd, \uc9c0\ucd9c, \uc800\ucd95, \uc18c\ube44 \ub4f1 \uc0dd\ud65c \uc18d\uc5d0\uc11c \uc790\uc8fc \uc0ac\uc6a9\ud558\ub294 \uacbd\uc81c \uac1c\ub150\uc744 \uc54c\uc544\ubd05\ub2c8\ub2e4.","\uacc4\ud68d\uc801\uc778 \uc18c\ube44\uc640 \uac00\uacc4 \uad00\ub9ac\uc758 \uc911\uc694\uc131\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubb3c\uac00\uac00 \uc624\ub974\uac70\ub098 \ub0b4\ub824\uac08 \ub54c \uac00\uc815\uc0dd\ud65c\uc5d0 \uc5b4\ub5a4 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294\uc9c0 \uc54c\uc544\ubd05\ub2c8\ub2e4.","\uc740\ud589, \uce74\ub4dc, \ub300\ucd9c, \uc774\uc790 \ub4f1 \uae08\uc735\uc0dd\ud65c\uacfc \uad00\ub828\ub41c \uae30\ubcf8 \ud45c\ud604\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\ucda9\ub3d9\uad6c\ub9e4\ub97c \uc904\uc774\uace0 \ud544\uc694\ud55c \ubb3c\uac74\uc744 \ud569\ub9ac\uc801\uc73c\ub85c \uc120\ud0dd\ud558\ub294 \uc18c\ube44 \uc2b5\uad00\uc744 \uc54c\uc544\ubd05\ub2c8\ub2e4.","\uc18c\ub4dd\uc774 \ud55c\uc815\ub418\uc5b4 \uc788\uc73c\ubbc0\ub85c \uc6b0\uc120\uc21c\uc704\ub97c \uc815\ud574 \uc9c0\ucd9c\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4\ub294 \uc810\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\uacbd\uc81c \uc0c1\ud669\uc774 \ubcc0\ud560 \ub54c \uac00\uc815\uc758 \uc9c0\ucd9c \uacc4\ud68d\ub3c4 \ud568\uaed8 \uc870\uc815\ud560 \ud544\uc694\uac00 \uc788\ub2e4\ub294 \uc810\uc744 \ubc30\uc6c1\ub2c8\ub2e4."],t.s)
A.f1m=new B.A("\uacbd\uc81c","kinh t\u1ebf","\uacbd\uc81c \uc0c1\ud669\uc740 \uc0ac\ub78c\ub4e4\uc758 \uc0dd\ud65c\uc5d0 \ud070 \uc601\ud5a5\uc744 \uc90d\ub2c8\ub2e4.","T\xecnh h\xecnh kinh t\u1ebf \u1ea3nh h\u01b0\u1edfng l\u1edbn \u0111\u1ebfn cu\u1ed9c s\u1ed1ng c\u1ee7a con ng\u01b0\u1eddi.")
A.f_l=new B.A("\uacbd\uc81c\uc0dd\ud65c","\u0111\u1eddi s\u1ed1ng kinh t\u1ebf","\ud569\ub9ac\uc801\uc778 \uacbd\uc81c\uc0dd\ud65c\uc744 \uc704\ud574 \uc18c\ube44 \uacc4\ud68d\uc744 \uc138\uc6b0\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","\u0110\u1ec3 c\xf3 \u0111\u1eddi s\u1ed1ng kinh t\u1ebf h\u1ee3p l\xfd, n\xean l\u1eadp k\u1ebf ho\u1ea1ch chi ti\xeau.")
A.f2t=new B.A("\uc18c\ub4dd","thu nh\u1eadp","\ub9e4\ub2ec \uc77c\uc815\ud55c \uc18c\ub4dd\uc774 \ub4e4\uc5b4\uc635\ub2c8\ub2e4.","M\u1ed7i th\xe1ng t\xf4i c\xf3 m\u1ed9t kho\u1ea3n thu nh\u1eadp c\u1ed1 \u0111\u1ecbnh.")
A.eVt=new B.A("\uc9c0\ucd9c","chi ti\xeau","\uc774\ubc88 \ub2ec\uc5d0\ub294 \ubcd1\uc6d0\ube44 \ub54c\ubb38\uc5d0 \uc9c0\ucd9c\uc774 \ub298\uc5c8\uc2b5\ub2c8\ub2e4.","Th\xe1ng n\xe0y chi ti\xeau t\u0103ng do ti\u1ec1n vi\u1ec7n ph\xed.")
A.f0p=new B.A("\uc218\uc785","thu nh\u1eadp, kho\u1ea3n ti\u1ec1n v\xe0o","\uc218\uc785\ubcf4\ub2e4 \uc9c0\ucd9c\uc774 \ub9ce\uc73c\uba74 \uac00\uacc4 \uad00\ub9ac\uac00 \uc5b4\ub824\uc6cc\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","N\u1ebfu chi ti\xeau nhi\u1ec1u h\u01a1n thu nh\u1eadp th\xec vi\u1ec7c qu\u1ea3n l\xfd gia \u0111\xecnh c\xf3 th\u1ec3 tr\u1edf n\xean kh\xf3 kh\u0103n.")
A.eVf=new B.A("\uac00\uacc4","kinh t\u1ebf gia \u0111\xecnh, h\u1ed9 gia \u0111\xecnh","\uac00\uacc4 \uc9c0\ucd9c\uc744 \uc904\uc774\uae30 \uc704\ud574 \ubd88\ud544\uc694\ud55c \uc18c\ube44\ub97c \uc904\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.","\u0110\u1ec3 gi\u1ea3m chi ti\xeau gia \u0111\xecnh, t\xf4i \u0111ang c\u1eaft gi\u1ea3m nh\u1eefng kho\u1ea3n ti\xeau d\xf9ng kh\xf4ng c\u1ea7n thi\u1ebft.")
A.eYC=new B.A("\uac00\uacc4\ubd80","s\u1ed5 thu chi gia \u0111\xecnh","\ub9e4\uc77c \uac00\uacc4\ubd80\ub97c \uc4f0\uba74 \uc9c0\ucd9c \ub0b4\uc6a9\uc744 \uc27d\uac8c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","N\u1ebfu ghi s\u1ed5 thu chi m\u1ed7i ng\xe0y th\xec c\xf3 th\u1ec3 d\u1ec5 d\xe0ng ki\u1ec3m tra c\xe1c kho\u1ea3n chi.")
A.eWp=new B.A("\uc0dd\ud65c\ube44","chi ph\xed sinh ho\u1ea1t","\uc6d4\uae09\uc5d0\uc11c \uc0dd\ud65c\ube44\ub97c \uba3c\uc800 \uacc4\uc0b0\ud574 \ubd24\uc2b5\ub2c8\ub2e4.","T\xf4i \u0111\xe3 t\xednh chi ph\xed sinh ho\u1ea1t tr\u01b0\u1edbc t\u1eeb ti\u1ec1n l\u01b0\u01a1ng.")
A.eWS=new B.A("\uc8fc\uac70\ube44","chi ph\xed nh\xe0 \u1edf","\ub3c4\uc2dc\uc5d0\uc11c\ub294 \uc8fc\uac70\ube44\uac00 \ud070 \ubd80\ub2f4\uc774 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\u1ede th\xe0nh ph\u1ed1, chi ph\xed nh\xe0 \u1edf c\xf3 th\u1ec3 tr\u1edf th\xe0nh g\xe1nh n\u1eb7ng l\u1edbn.")
A.eX1=new B.A("\uad50\ud1b5\ube44","chi ph\xed giao th\xf4ng","\ub300\uc911\uad50\ud1b5\uc744 \uc774\uc6a9\ud558\uba74\uc11c \uad50\ud1b5\ube44\ub97c \uc904\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.","T\xf4i \u0111ang gi\u1ea3m chi ph\xed giao th\xf4ng b\u1eb1ng c\xe1ch s\u1eed d\u1ee5ng ph\u01b0\u01a1ng ti\u1ec7n c\xf4ng c\u1ed9ng.")
A.f_7=new B.A("\ud1b5\uc2e0\ube44","chi ph\xed vi\u1ec5n th\xf4ng","\ud734\ub300\uc804\ud654 \uc694\uae08\uc81c\ub97c \ubc14\uafd4\uc11c \ud1b5\uc2e0\ube44\ub97c \uc904\uc600\uc2b5\ub2c8\ub2e4.","T\xf4i \u0111\xe3 \u0111\u1ed5i g\xf3i c\u01b0\u1edbc \u0111i\u1ec7n tho\u1ea1i \u0111\u1ec3 gi\u1ea3m chi ph\xed vi\u1ec5n th\xf4ng.")
A.eYM=new B.A("\uad50\uc721\ube44","chi ph\xed gi\xe1o d\u1ee5c","\uc790\ub140\uac00 \ub9ce\uc73c\uba74 \uad50\uc721\ube44 \ubd80\ub2f4\uc774 \ucee4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","N\u1ebfu c\xf3 nhi\u1ec1u con th\xec g\xe1nh n\u1eb7ng chi ph\xed gi\xe1o d\u1ee5c c\xf3 th\u1ec3 t\u0103ng.")
A.eWX=new B.A("\uc800\ucd95\ud558\ub2e4","ti\u1ebft ki\u1ec7m ti\u1ec1n","\ubbf8\ub798\ub97c \uc704\ud574 \uc6d4\uae09\uc758 \uc77c\ubd80\ub97c \ub9e4\ub2ec \uc800\ucd95\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.","T\xf4i \u0111ang ti\u1ebft ki\u1ec7m m\u1ed9t ph\u1ea7n ti\u1ec1n l\u01b0\u01a1ng m\u1ed7i th\xe1ng cho t\u01b0\u01a1ng lai.")
A.eWm=new B.A("\uc800\ucd95","ti\u1ec1n ti\u1ebft ki\u1ec7m, vi\u1ec7c ti\u1ebft ki\u1ec7m","\uac11\uc790\uae30 \ud544\uc694\ud55c \ub3c8\uc774 \uc0dd\uae38 \uc218 \uc788\uc73c\ubbc0\ub85c \uc800\ucd95\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.","V\xec c\xf3 th\u1ec3 b\u1ea5t ng\u1edd c\u1ea7n ti\u1ec1n n\xean vi\u1ec7c ti\u1ebft ki\u1ec7m l\xe0 c\u1ea7n thi\u1ebft.")
A.eVG=new B.A("\uc608\uae08","ti\u1ec1n g\u1eedi ng\xe2n h\xe0ng","\uc740\ud589\uc5d0\uc11c \uc608\uae08 \uc0c1\ud488\uc744 \uc54c\uc544\ubd24\uc2b5\ub2c8\ub2e4.","T\xf4i \u0111\xe3 t\xecm hi\u1ec3u s\u1ea3n ph\u1ea9m ti\u1ec1n g\u1eedi \u1edf ng\xe2n h\xe0ng.")
A.f_P=new B.A("\ub300\ucd9c","kho\u1ea3n vay","\uc9d1\uc744 \uad6c\ud558\uae30 \uc704\ud574 \uc740\ud589 \ub300\ucd9c\uc744 \uc54c\uc544\ubcf4\uace0 \uc788\uc2b5\ub2c8\ub2e4.","T\xf4i \u0111ang t\xecm hi\u1ec3u kho\u1ea3n vay ng\xe2n h\xe0ng \u0111\u1ec3 t\xecm nh\xe0.")
A.eYj=new B.A("\uc774\uc790","l\xe3i su\u1ea5t, ti\u1ec1n l\xe3i","\ub300\ucd9c\uc744 \ubc1b\uc744 \ub54c\ub294 \uc774\uc790\ub3c4 \ud568\uaed8 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.","Khi vay ti\u1ec1n c\u1ea7n ki\u1ec3m tra c\u1ea3 l\xe3i su\u1ea5t.")
A.f_q=new B.A("\uae08\ub9ac","l\xe3i su\u1ea5t","\uae08\ub9ac\uac00 \uc624\ub974\uba74 \ub300\ucd9c \uc774\uc790 \ubd80\ub2f4\uc774 \ucee4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","N\u1ebfu l\xe3i su\u1ea5t t\u0103ng th\xec g\xe1nh n\u1eb7ng ti\u1ec1n l\xe3i vay c\xf3 th\u1ec3 t\u0103ng.")
A.f1_=new B.A("\ubb3c\uac00","m\u1ee9c gi\xe1 c\u1ea3","\uc694\uc998 \ubb3c\uac00\uac00 \uc62c\ub77c\uc11c \uc0dd\ud65c\ube44\uac00 \ub9ce\uc774 \ub4e4\uace0 \uc788\uc2b5\ub2c8\ub2e4.","D\u1ea1o n\xe0y gi\xe1 c\u1ea3 t\u0103ng n\xean chi ph\xed sinh ho\u1ea1t t\u1ed1n nhi\u1ec1u h\u01a1n.")
