A.eOT=new B.aj("\ud569\ub9ac\uc801\uc778 \uc18c\ube44 \ubc29\ubc95\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.iuL,0,"\ud569\ub9ac\uc801\uc778 \uc18c\ube44\ub294 \uc790\uc2e0\uc758 \uacbd\uc81c \uc0c1\ud669, \ubb3c\uac74\uc758 \ud544\uc694\uc131, \uac00\uaca9\uacfc \ud488\uc9c8 \ub4f1\uc744 \uc0dd\uac01\ud55c \ud6c4 \uad6c\ub9e4\ud558\ub294 \uac83\uc785\ub2c8\ub2e4.")
A.ifc=s(["\u2460 \uacc4\ud68d \uc5c6\uc774 \uc21c\uac04\uc801\uc778 \ub9c8\uc74c\uc73c\ub85c \ubb3c\uac74\uc744 \uc0ac\ub294 \uac83","\u2461 \ud544\uc694\ud55c \ubb3c\uac74\uc744 \uc624\ub798 \ube44\uad50\ud574\uc11c \uc0ac\ub294 \uac83","\u2462 \ub9e4\ub2ec \uc77c\uc815\ud55c \ub3c8\uc744 \uc800\ucd95\ud558\ub294 \uac83","\u2463 \uc0dd\ud65c\ube44 \uc608\uc0b0\uc744 \uc138\uc6b0\ub294 \uac83"],t.s)
A.eP0=new B.aj('"\ucda9\ub3d9\uad6c\ub9e4"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?',A.ifc,0,'"\ucda9\ub3d9\uad6c\ub9e4"\ub294 \ubbf8\ub9ac \uacc4\ud68d\ud558\uc9c0 \uc54a\uace0 \uc21c\uac04\uc801\uc778 \uac10\uc815\uc774\ub098 \uad11\uace0, \ud560\uc778 \ub4f1\uc5d0 \uc601\ud5a5\uc744 \ubc1b\uc544 \ubb3c\uac74\uc744 \uad6c\ub9e4\ud558\ub294 \uac83\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4.')
A.hRW=s(["\u2460 \uac19\uc740 \uc0dd\ud65c\uc744 \uc720\uc9c0\ud558\ub294 \ub370 \ub354 \ub9ce\uc740 \ub3c8\uc774 \ud544\uc694\ud560 \uc218 \uc788\ub2e4","\u2461 \ubaa8\ub4e0 \ubb3c\uac74\uc758 \uac00\uaca9\uc774 \ubc18\ub4dc\uc2dc \ub0b4\ub824\uac04\ub2e4","\u2462 \uac00\uc815\uc758 \uc9c0\ucd9c\uc774 \ubb34\uc870\uac74 \uc5c6\uc5b4\uc9c0\uac8c \ub41c\ub2e4","\u2463 \uc18c\ub4dd\uc774 \uc790\ub3d9\uc73c\ub85c \ub450 \ubc30\uac00 \ub41c\ub2e4"],t.s)
A.ePu=new B.aj("\ubb3c\uac00\uac00 \uc624\ub974\uba74 \ub098\ud0c0\ub0a0 \uc218 \uc788\ub294 \ubcc0\ud654\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.hRW,0,"\ubb3c\uac00\uac00 \uc0c1\uc2b9\ud558\uba74 \uac19\uc740 \uc0c1\ud488\uc774\ub098 \uc11c\ube44\uc2a4\ub97c \uc774\uc6a9\ud558\ub294 \ub370 \ub354 \ub9ce\uc740 \ube44\uc6a9\uc774 \ub4e4 \uc218 \uc788\uc5b4 \uc0dd\ud65c\ube44 \ubd80\ub2f4\uc774 \ucee4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.")
A.hx2=s(["\u2460 \uc774\uc790\uc640 \uc0c1\ud658 \uc870\uac74","\u2461 \uce5c\uad6c\uac00 \uc88b\uc544\ud558\ub294 \uc74c\uc2dd","\u2462 \ud559\uad50 \ubc29\ud559 \ub0a0\uc9dc","\u2463 \uc4f0\ub808\uae30 \ubc30\ucd9c \uc2dc\uac04\ub9cc"],t.s)
A.eMX=new B.aj("\ub300\ucd9c\uc744 \ubc1b\uc744 \ub54c \ud655\uc778\ud560 \ub0b4\uc6a9\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.hx2,0,"\ub300\ucd9c\uc740 \ub098\uc911\uc5d0 \uac1a\uc544\uc57c \ud558\ub294 \ub3c8\uc774\ubbc0\ub85c \uc774\uc790, \uc0c1\ud658 \uae30\uac04, \uc870\uac74 \ub4f1\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.h1u=s(["\u2460 \uac00\uacc4\ubd80\ub97c \uc4f0\uace0 \uc608\uc0b0\uc744 \uc815\ud55c\ub2e4","\u2461 \ubaa8\ub4e0 \uc18c\ube44 \ub0b4\uc6a9\uc744 \uae30\uc5b5\ud558\uc9c0 \uc54a\ub294\ub2e4","\u2462 \uc9c0\ucd9c \uacc4\ud68d \uc5c6\uc774 \ub3c8\uc744 \uc4f4\ub2e4","\u2463 \uc218\uc785\uc744 \ud655\uc778\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
A.eP1=new B.aj("\uc0dd\ud65c\ube44\ub97c \uad00\ub9ac\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub418\ub294 \ubc29\ubc95\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.h1u,0,"\uac00\uacc4\ubd80\uc640 \uc608\uc0b0\uc744 \uc774\uc6a9\ud558\uba74 \uc218\uc785\uacfc \uc9c0\ucd9c\uc744 \ud30c\uc545\ud558\uace0 \ubd88\ud544\uc694\ud55c \uc18c\ube44\ub97c \uc904\uc774\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.")
A.iP3=s(["\u2460 \uc740\ucee4\ub155","\u2461 \uc744 \uacb8","\u2462 \uc744 \ubed4\ud574\uc11c","\u2463 \ud558\ub294 \ucc99"],t.s)
A.ePh=new B.aj("\ub2e4\uc74c \ub300\ud654\uc5d0 \ub4e4\uc5b4\uac08 \ud45c\ud604\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?\n\n\uac00: \uc774\ubc88 \ub2ec\uc5d0\ub3c4 \uc800\ucd95\ud588\uc5b4\uc694?\n\ub098: \uc544\ub2c8\uc694. \ubcd1\uc6d0\ube44\uac00 \ub9ce\uc774 \ub4e4\uc5b4\uc11c \uc800\ucd95______ \uc0dd\ud65c\ube44\ub3c4 \ubd80\uc871\ud574\uc694.",A.iP3,0,'\uc800\ucd95\uc740 \ud558\uc9c0 \ubabb\ud588\uace0 \uadf8\ubcf4\ub2e4 \uae30\ubcf8\uc801\uc778 \uc0dd\ud65c\ube44\ub3c4 \ubd80\uc871\ud55c \uc0c1\ud669\uc774\ubbc0\ub85c "\uc800\ucd95\uc740\ucee4\ub155"\uc774 \uac00\uc7a5 \uc54c\ub9de\uc2b5\ub2c8\ub2e4.')
A.iSF=s([A.eO0,A.eMf,A.eOG,A.eNv,A.eOT,A.eP0,A.ePu,A.eMX,A.eP1,A.ePh],t.Fo)
A.iJL=s(["\uacbd\uc81c = kinh t\u1ebf.","\uc18c\ub4dd = thu nh\u1eadp.","\uc9c0\ucd9c = chi ti\xeau.","\uc218\uc785 = kho\u1ea3n ti\u1ec1n v\xe0o / thu nh\u1eadp.","\uac00\uacc4 = kinh t\u1ebf gia \u0111\xecnh.","\uac00\uacc4\ubd80 = s\u1ed5 thu chi gia \u0111\xecnh.","\uc0dd\ud65c\ube44 = chi ph\xed sinh ho\u1ea1t.","\uc8fc\uac70\ube44 = chi ph\xed nh\xe0 \u1edf.","\uad50\ud1b5\ube44 = chi ph\xed giao th\xf4ng.","\ud1b5\uc2e0\ube44 = chi ph\xed vi\u1ec5n th\xf4ng.","\uad50\uc721\ube44 = chi ph\xed gi\xe1o d\u1ee5c.","\uc800\ucd95\ud558\ub2e4 = ti\u1ebft ki\u1ec7m ti\u1ec1n.","\uc800\ucd95 = vi\u1ec7c/ti\u1ec1n ti\u1ebft ki\u1ec7m.","\uc608\uae08 = ti\u1ec1n g\u1eedi ng\xe2n h\xe0ng.","\ub300\ucd9c = kho\u1ea3n vay.","\uc774\uc790 = ti\u1ec1n l\xe3i.","\uae08\ub9ac = l\xe3i su\u1ea5t.","\ubb3c\uac00 = m\u1ee9c gi\xe1 c\u1ea3.","\uac00\uaca9 = gi\xe1.","\uc18c\ube44 = ti\xeau d\xf9ng.","\uc18c\ube44\uc790 = ng\u01b0\u1eddi ti\xeau d\xf9ng.","\ud569\ub9ac\uc801\uc778 \uc18c\ube44 = ti\xeau d\xf9ng h\u1ee3p l\xfd.","\ucda9\ub3d9\uad6c\ub9e4 = mua h\xe0ng b\u1ed1c \u0111\u1ed3ng.","\uc808\uc57d\ud558\ub2e4 = ti\u1ebft ki\u1ec7m.","\uc608\uc0b0 = ng\xe2n s\xe1ch.","\uacc4\ud68d\uc744 \uc138\uc6b0\ub2e4 = l\u1eadp k\u1ebf ho\u1ea1ch.","\uc6b0\uc120\uc21c\uc704 = th\u1ee9 t\u1ef1 \u01b0u ti\xean.","\ubd80\ub2f4 = g\xe1nh n\u1eb7ng.","-(\uc73c)\ubbc0\ub85c = v\xec / do..., th\u01b0\u1eddng d\xf9ng trong c\xe1ch gi\u1ea3i th\xedch kh\xe1 trang tr\u1ecdng.","-\ubbc0\ub85c = v\xec / do... \u1edf d\u1ea1ng ph\xf9 h\u1ee3p.",u.kU,"-\uae30\ub294\ucee4\ub155 = ch\u1eb3ng nh\u1eefng kh\xf4ng l\xe0m... m\xe0 c\xf2n...","-\uae30 \ub54c\ubb38\uc5d0 = b\u1edfi v\xec...","-\ub3c4\ub85d \ud558\ub2e4 = c\u1ed1 g\u1eafng / l\xe0m sao \u0111\u1ec3...","\uc18c\ub4dd\uc740 \ud55c\uc815\ub418\uc5b4 \uc788\uc73c\ubbc0\ub85c \uc790\uc2e0\uc758 \uacbd\uc81c \uc0c1\ud669\uc5d0 \ub9de\uac8c \uacc4\ud68d\uc801\uc73c\ub85c \uc18c\ube44\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\uac00\uacc4\ubd80\ub97c \uc4f0\uba74 \uc218\uc785\uacfc \uc9c0\ucd9c\uc758 \ud750\ub984\uc744 \uc27d\uac8c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ucda9\ub3d9\uad6c\ub9e4\ub97c \uc904\uc774\uace0 \ud544\uc694\ud55c \ubb3c\uac74\uc778\uc9c0 \ud655\uc778\ud55c \ub4a4 \uad6c\ub9e4\ud558\ub294 \uac83\uc774 \ud569\ub9ac\uc801\uc778 \uc18c\ube44\uc5d0 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.","\ubb3c\uac00\uac00 \uc624\ub974\uba74 \uc0dd\ud65c\ube44 \ubd80\ub2f4\uc774 \ucee4\uc9c8 \uc218 \uc788\uc73c\ubbc0\ub85c \uc9c0\ucd9c \uacc4\ud68d\uc744 \uc870\uc815\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.","\ub300\ucd9c\uc744 \uc774\uc6a9\ud560 \ub54c\ub294 \ud544\uc694\ud55c \uae08\uc561\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc774\uc790\uc640 \uc0c1\ud658 \uc870\uac74\ub3c4 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4."],t.s)
A.Ki=new B.hG(14,"\uc0dd\ud65c\uacfc \uacbd\uc81c","Cu\u1ed9c s\u1ed1ng v\xe0 kinh t\u1ebf",A.i0P,A.fRD,A.iNC,A.iTt,A.iSF,A.iJL)
A.iO_=s(["\uc815\ubcf4\ud654 \uc0ac\ud68c\uc758 \uc758\ubbf8\uc640 \ud2b9\uc9d5\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\uc778\ud130\ub137\uacfc \uc2a4\ub9c8\ud2b8\ud3f0\uc758 \ubc1c\ub2ec\ub85c \uc815\ubcf4\uc758 \uc0dd\uc0b0\uacfc \uc804\ub2ec \uc18d\ub3c4\uac00 \ub9e4\uc6b0 \ube68\ub77c\uc84c\ub2e4\ub294 \uc810\uc744 \uc54c\uc544\ubd05\ub2c8\ub2e4.","\uc628\ub77c\uc778 \uc1fc\ud551, \uc778\ud130\ub137 \ubc45\ud0b9, \ubaa8\ubc14\uc77c \uacb0\uc81c \ub4f1 \uc815\ubcf4 \uae30\uc220\uc774 \uc77c\uc0c1\uc0dd\ud65c\uc5d0 \uc5b4\ub5bb\uac8c \ud65c\uc6a9\ub418\ub294\uc9c0 \uc774\ud574\ud569\ub2c8\ub2e4.","\uc815\ubcf4\ud654 \uc0ac\ud68c\uc5d0\uc11c\ub294 \ud544\uc694\ud55c \uc815\ubcf4\ub97c \ube60\ub974\uac8c \ucc3e\uace0 \uc815\ud655\ud558\uac8c \ud310\ub2e8\ud558\ub294 \ub2a5\ub825\uc774 \uc911\uc694\ud558\ub2e4\ub294 \uc810\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uac1c\uc778\uc815\ubcf4 \uc720\ucd9c, \uc778\ud130\ub137 \uc0ac\uae30, \uc545\uc131 \ub313\uae00 \ub4f1 \uc815\ubcf4\ud654 \uc0ac\ud68c\uc5d0\uc11c \ubc1c\uc0dd\ud560 \uc218 \uc788\ub294 \ubb38\uc81c\ub97c \uc54c\uc544\ubd05\ub2c8\ub2e4.","\uac1c\uc778\uc815\ubcf4\uc640 \ube44\ubc00\ubc88\ud638\ub97c \uc548\uc804\ud558\uac8c \uad00\ub9ac\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc778\ud130\ub137 \uc815\ubcf4\ub97c \uadf8\ub300\ub85c \ubbff\uae30\ubcf4\ub2e4 \ucd9c\ucc98\uc640 \uc0ac\uc2e4 \uc5ec\ubd80\ub97c \ud655\uc778\ud558\ub294 \ud0dc\ub3c4\uac00 \ud544\uc694\ud558\ub2e4\ub294 \uc810\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\uc815\ubcf4 \uae30\uc220\uc744 \ud3b8\ub9ac\ud558\uac8c \uc774\uc6a9\ud558\uba74\uc11c\ub3c4 \ub2e4\ub978 \uc0ac\ub78c\uc744 \ubc30\ub824\ud558\uace0 \ucc45\uc784 \uc788\uac8c \uc0ac\uc6a9\ud558\ub294 \ud0dc\ub3c4\ub97c \uae30\ub985\ub2c8\ub2e4."],t.s)
A.f33=new B.A("\uc815\ubcf4\ud654 \uc0ac\ud68c","x\xe3 h\u1ed9i th\xf4ng tin","\ud604\ub300 \uc0ac\ud68c\ub294 \uc815\ubcf4\ub97c \ube60\ub974\uac8c \uc0dd\uc0b0\ud558\uace0 \uacf5\uc720\ud558\ub294 \uc815\ubcf4\ud654 \uc0ac\ud68c\uc785\ub2c8\ub2e4.","X\xe3 h\u1ed9i hi\u1ec7n \u0111\u1ea1i l\xe0 x\xe3 h\u1ed9i th\xf4ng tin, n\u01a1i th\xf4ng tin \u0111\u01b0\u1ee3c t\u1ea1o ra v\xe0 chia s\u1ebb nhanh ch\xf3ng.")
A.f__=new B.A("\uc815\ubcf4","th\xf4ng tin","\uc778\ud130\ub137\uc5d0\uc11c \ud544\uc694\ud55c \uc815\ubcf4\ub97c \uc27d\uac8c \ucc3e\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","C\xf3 th\u1ec3 d\u1ec5 d\xe0ng t\xecm th\xf4ng tin c\u1ea7n thi\u1ebft tr\xean Internet.")
A.f3h=new B.A("\uc815\ubcf4 \uae30\uc220","c\xf4ng ngh\u1ec7 th\xf4ng tin","\uc815\ubcf4 \uae30\uc220\uc758 \ubc1c\ub2ec\ub85c \uc0dd\ud65c\uc774 \ub9ce\uc774 \ud3b8\ub9ac\ud574\uc84c\uc2b5\ub2c8\ub2e4.","Nh\u1edd s\u1ef1 ph\xe1t tri\u1ec3n c\u1ee7a c\xf4ng ngh\u1ec7 th\xf4ng tin, cu\u1ed9c s\u1ed1ng \u0111\xe3 tr\u1edf n\xean ti\u1ec7n l\u1ee3i h\u01a1n nhi\u1ec1u.")
