A.f0I=new B.A("\ud574\uc678","n\u01b0\u1edbc ngo\xe0i, h\u1ea3i ngo\u1ea1i","\ub9ce\uc740 \uae30\uc5c5\uc774 \ud574\uc678 \uc2dc\uc7a5\uc5d0 \uc9c4\ucd9c\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.","Nhi\u1ec1u doanh nghi\u1ec7p \u0111ang ti\u1ebfn v\xe0o th\u1ecb tr\u01b0\u1eddng n\u01b0\u1edbc ngo\xe0i.")
A.eYf=new B.A("\ud574\uc678 \uc9c4\ucd9c","ti\u1ebfn ra th\u1ecb tr\u01b0\u1eddng n\u01b0\u1edbc ngo\xe0i","\ud55c\uad6d \uae30\uc5c5\uc758 \ud574\uc678 \uc9c4\ucd9c\uc774 \uacc4\uc18d \ub298\uace0 \uc788\uc2b5\ub2c8\ub2e4.","Vi\u1ec7c c\xe1c doanh nghi\u1ec7p H\xe0n Qu\u1ed1c ti\u1ebfn ra n\u01b0\u1edbc ngo\xe0i ti\u1ebfp t\u1ee5c gia t\u0103ng.")
A.f2p=new B.A("\ub2e4\uad6d\uc801 \uae30\uc5c5","doanh nghi\u1ec7p \u0111a qu\u1ed1c gia","\ub2e4\uad6d\uc801 \uae30\uc5c5\uc5d0\uc11c\ub294 \uc5ec\ub7ec \ub098\ub77c \ucd9c\uc2e0\uc758 \uc9c1\uc6d0\ub4e4\uc774 \ud568\uaed8 \uc77c\ud569\ub2c8\ub2e4.","Trong doanh nghi\u1ec7p \u0111a qu\u1ed1c gia, nh\xe2n vi\xean \u0111\u1ebfn t\u1eeb nhi\u1ec1u n\u01b0\u1edbc c\xf9ng l\xe0m vi\u1ec7c.")
A.eVW=new B.A("\uc678\uad6d\uc778 \uadfc\ub85c\uc790","lao \u0111\u1ed9ng n\u01b0\u1edbc ngo\xe0i","\ud55c\uad6d \uc0b0\uc5c5 \ud604\uc7a5\uc5d0\uc11c\ub294 \uc678\uad6d\uc778 \uadfc\ub85c\uc790\ub4e4\uc774 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.","T\u1ea1i c\xe1c c\u01a1 s\u1edf c\xf4ng nghi\u1ec7p H\xe0n Qu\u1ed1c, lao \u0111\u1ed9ng n\u01b0\u1edbc ngo\xe0i \u0111ang \u0111\xf3ng vai tr\xf2 quan tr\u1ecdng.")
A.f1Y=new B.A("\ub2e4\ubb38\ud654 \uc0ac\ud68c","x\xe3 h\u1ed9i \u0111a v\u0103n h\xf3a","\ud55c\uad6d \uc0ac\ud68c\ub3c4 \uc810\ucc28 \ub2e4\ubb38\ud654 \uc0ac\ud68c\ub85c \ubcc0\ud654\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.","X\xe3 h\u1ed9i H\xe0n Qu\u1ed1c c\u0169ng \u0111ang d\u1ea7n chuy\u1ec3n th\xe0nh x\xe3 h\u1ed9i \u0111a v\u0103n h\xf3a.")
A.eYz=new B.A("\ubb38\ud654\uc801 \ub2e4\uc591\uc131","s\u1ef1 \u0111a d\u1ea1ng v\u0103n h\xf3a","\uad6d\uc81c\ud654 \uc2dc\ub300\uc5d0\ub294 \ubb38\ud654\uc801 \ub2e4\uc591\uc131\uc744 \uc874\uc911\ud558\ub294 \ud0dc\ub3c4\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.","Trong th\u1eddi \u0111\u1ea1i qu\u1ed1c t\u1ebf h\xf3a, th\xe1i \u0111\u1ed9 t\xf4n tr\u1ecdng s\u1ef1 \u0111a d\u1ea1ng v\u0103n h\xf3a r\u1ea5t quan tr\u1ecdng.")
A.eWT=new B.A("\ubb38\ud654 \ucc28\uc774","kh\xe1c bi\u1ec7t v\u0103n h\xf3a","\ubb38\ud654 \ucc28\uc774\ub97c \uc774\ud574\ud558\uc9c0 \ubabb\ud558\uba74 \uc624\ud574\uac00 \uc0dd\uae38 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","N\u1ebfu kh\xf4ng hi\u1ec3u kh\xe1c bi\u1ec7t v\u0103n h\xf3a th\xec c\xf3 th\u1ec3 x\u1ea3y ra hi\u1ec3u l\u1ea7m.")
A.eW1=new B.A("\uac00\uce58\uad00","quan ni\u1ec7m gi\xe1 tr\u1ecb","\ub098\ub77c\ub9c8\ub2e4 \uc0ac\ub78c\ub4e4\uc758 \uac00\uce58\uad00\uc774 \ub2e4\ub97c \uc218 \uc788\uc2b5\ub2c8\ub2e4.","Quan ni\u1ec7m gi\xe1 tr\u1ecb c\u1ee7a con ng\u01b0\u1eddi c\xf3 th\u1ec3 kh\xe1c nhau t\xf9y t\u1eebng qu\u1ed1c gia.")
