A.eOr=new B.aj("\ubb38\ud654 \ucc28\uc774\ub97c \uc774\ud574______ \uc11c\ub85c \ub9ce\uc774 \ub300\ud654\ud574\uc57c \ud569\ub2c8\ub2e4.",A.ikZ,0,'\ubb38\ud654 \ucc28\uc774\ub97c \uc774\ud574\ud55c\ub2e4\ub294 \ubaa9\uc801\uc744 \ub098\ud0c0\ub0b4\ubbc0\ub85c "-\uae30 \uc704\ud574\uc11c"\uac00 \uc54c\ub9de\uc2b5\ub2c8\ub2e4.')
A.fYH=s(["\u2460 \uad6d\uac00 \uac04 \uad50\ub958 \uc99d\uac00","\u2461 \uc678\uad6d \uc0c1\ud488 \uc774\uc6a9 \uc99d\uac00","\u2462 \ub2e4\uc591\ud55c \ubb38\ud654\uc640\uc758 \uc811\ucd09 \uc99d\uac00","\u2463 \ubaa8\ub4e0 \uad6d\uac00\uac00 \uc11c\ub85c \uc644\uc804\ud788 \ub2e8\uc808\ub428"],t.s)
A.eNc=new B.aj("\uad6d\uc81c\ud654\uc758 \uc601\ud5a5\uc73c\ub85c \ubcf4\uae30 \uc5b4\ub824\uc6b4 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.fYH,3,"\uad6d\uc81c\ud654\ub294 \uad6d\uac00 \uac04 \uad00\uacc4\uac00 \ub354\uc6b1 \ud65c\ubc1c\ud574\uc9c0\uace0 \uae34\ubc00\ud574\uc9c0\ub294 \ud604\uc0c1\uc774\ubbc0\ub85c \uc644\uc804\ud55c \ub2e8\uc808\uacfc\ub294 \ubc18\ub300\uc785\ub2c8\ub2e4.")
A.hHt=s(["\u2460 \uc11c\ub85c \uc774\ud574\ud558\uc9c0 \ubabb\ud55c \ub0b4\uc6a9\uc744 \ub2e4\uc2dc \ud655\uc778\ud55c\ub2e4","\u2461 \ubaa8\ub974\ub294 \ub0b4\uc6a9\uc744 \uadf8\ub300\ub85c \ub118\uc5b4\uac04\ub2e4","\u2462 \uc0c1\ub300\ubc29\uc758 \ubb38\ud654\ub97c \ubb34\uc2dc\ud55c\ub2e4","\u2463 \uc790\uc2e0\uc758 \ubc29\uc2dd\ub9cc \uac15\uc694\ud55c\ub2e4"],t.s)
A.eMG=new B.aj("\uad6d\uc81c\uc801\uc778 \uc9c1\uc7a5\uc5d0\uc11c \uc6d0\ud65c\ud55c \uc758\uc0ac\uc18c\ud1b5\uc744 \uc704\ud574 \uac00\uc7a5 \ud544\uc694\ud55c \ud589\ub3d9\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.hHt,0,"\uc5b8\uc5b4\uc640 \ubb38\ud654\uac00 \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uacfc \uc77c\ud560 \ub54c\ub294 \ubaa8\ub974\ub294 \ub0b4\uc6a9\uc744 \ub2e4\uc2dc \ud655\uc778\ud558\uace0 \uc11c\ub85c\uc758 \ubb38\ud654\ub97c \uc874\uc911\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.iJd=s(["\u2460 \uc815\ub3c4\ub85c","\u2461 \ub358","\u2462 \ub290\ub77c\uace0","\u2463 \ub098\uba38\uc9c0"],t.s)
A.eMn=new B.aj("\ub2e4\uc74c \ub300\ud654\uc5d0 \ub4e4\uc5b4\uac08 \ud45c\ud604\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?\n\n\uac00: \ud55c\uad6d \ubb38\ud654\uac00 \ud574\uc678\uc5d0\uc11c\ub3c4 \ub9ce\uc774 \uc54c\ub824\uc84c\ub124\uc694.\n\ub098: \ub124. \ud574\uc678\uc5d0\uc11c\ub3c4 \ud55c\uad6d \uc74c\uc2dd\uc744 \uc27d\uac8c \ucc3e\uc744 \uc218 \uc788\uc744______ \uc720\uba85\ud574\uc84c\uc5b4\uc694.",A.iJd,0,'\ud55c\uad6d \uc74c\uc2dd\uc758 \uc720\uba85\ud55c \uc815\ub3c4\uac00 \ub9e4\uc6b0 \ud06c\ub2e4\ub294 \uc758\ubbf8\uc774\ubbc0\ub85c "-(\uc73c)\u3139 \uc815\ub3c4\ub85c"\uac00 \uac00\uc7a5 \uc790\uc5f0\uc2a4\ub7fd\uc2b5\ub2c8\ub2e4.')
