A.eKe=new B.aO("-\uac8c \ub418\ub2e4","tr\u1edf th\xe0nh, \u0111i \u0111\u1ebfn vi\u1ec7c...","\uc790\uc2e0\uc758 \uc758\ub3c4\ubcf4\ub2e4\ub294 \uc0c1\ud669\uc774\ub098 \ud658\uacbd\uc758 \ubcc0\ud654 \ub54c\ubb38\uc5d0 \uc0c8\ub85c\uc6b4 \uc0c1\ud0dc\uac00 \ub418\uac70\ub098 \uc5b4\ub5a4 \ud589\ub3d9\uc744 \ud558\uac8c \ub418\ub294 \uac83\uc744 \ub098\ud0c0\ub0c5\ub2c8\ub2e4.","\uc9c1\uc7a5 \ub54c\ubb38\uc5d0 \ub2e4\ub978 \uc9c0\uc5ed\uc5d0\uc11c \uac00\uc871\uacfc \ub5a8\uc5b4\uc838 \uc0b4\uac8c \ub418\uc5c8\uc5b4\uc694.","V\xec c\xf4ng vi\u1ec7c n\xean t\xf4i \u0111\xe3 \u0111i \u0111\u1ebfn vi\u1ec7c s\u1ed1ng xa gia \u0111\xecnh \u1edf khu v\u1ef1c kh\xe1c.")
A.eK1=new B.aO("-\uba74\uc11c","v\u1eeba... v\u1eeba..., trong khi...","\ub450 \uac00\uc9c0 \ud589\ub3d9\uc774\ub098 \uc0c1\ud0dc\uac00 \ub3d9\uc2dc\uc5d0 \uc774\ub8e8\uc5b4\uc9c8 \ub54c \uc0ac\uc6a9\ud569\ub2c8\ub2e4.","\ubd80\ubd80\uac00 \uc77c\uc744 \ud558\uba74\uc11c \ud568\uaed8 \uc544\uc774\ub97c \ud0a4\uc6b0\uace0 \uc788\uc2b5\ub2c8\ub2e4.","Hai v\u1ee3 ch\u1ed3ng v\u1eeba \u0111i l\xe0m v\u1eeba c\xf9ng nu\xf4i con.")
A.eKa=new B.aO("-\uae30 \ub54c\ubb38\uc5d0","b\u1edfi v\xec...","\uc5b4\ub5a4 \uc77c\uc758 \uc774\uc720\ub098 \uc6d0\uc778\uc744 \uc124\uba85\ud560 \ub54c \uc0ac\uc6a9\ud569\ub2c8\ub2e4.","\uac00\uc871 \uad6c\uc131\uc6d0\ub9c8\ub2e4 \uc0dd\uac01\uc774 \ub2e4\ub974\uae30 \ub54c\ubb38\uc5d0 \ub300\ud654\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.","V\xec m\u1ed7i th\xe0nh vi\xean gia \u0111\xecnh c\xf3 suy ngh\u0129 kh\xe1c nhau n\xean \u0111\u1ed1i tho\u1ea1i r\u1ea5t quan tr\u1ecdng.")
