A.eRz=new B.a5("\ubbfc","\ub124. \uae34\uc7a5\ud574\uc11c \ubc18\ub9d0\uc744 \ud558\uace0 \ub9d0\uc558\uc5b4\uc694.","V\xe2ng. V\xec c\u0103ng th\u1eb3ng n\xean cu\u1ed1i c\xf9ng t\xf4i l\u1ea1i n\xf3i b\u1eb1ng l\u1ed1i th\xe2n m\u1eadt.")
A.eSP=new B.a5("\uc9c0\uc218","\ubc14\ub85c \uc0ac\uacfc\ud588\uc5b4\uc694?","B\u1ea1n \u0111\xe3 xin l\u1ed7i ngay ch\u01b0a?")
A.eSv=new B.a5("\ubbfc",'\ub124. "\uc81c\uac00 \uc798 \ubab0\ub77c\uc11c \uc2e4\uc218\ud588\uc2b5\ub2c8\ub2e4. \uc8c4\uc1a1\ud569\ub2c8\ub2e4."\ub77c\uace0 \ub9d0\ud588\uc5b4\uc694.',"V\xe2ng. T\xf4i \u0111\xe3 n\xf3i: \u201cV\xec t\xf4i ch\u01b0a bi\u1ebft r\xf5 n\xean \u0111\xe3 s\u01a1 su\u1ea5t. T\xf4i xin l\u1ed7i.\u201d")
A.eQ9=new B.a5("\uc9c0\uc218","\uc798\ud588\uc5b4\uc694. \ud55c\uad6d\uc5b4\uc5d0\uc11c\ub294 \uc0c1\ub300\ubc29\uacfc\uc758 \uad00\uacc4\uc5d0 \ub530\ub77c \ub9d0\ud22c\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc5b4\uc694.","B\u1ea1n l\xe0m \u0111\xfang r\u1ed3i. Trong ti\u1ebfng H\xe0n c\xe1ch n\xf3i c\xf3 th\u1ec3 thay \u0111\u1ed5i t\xf9y quan h\u1ec7 v\u1edbi \u0111\u1ed1i ph\u01b0\u01a1ng.")
A.eRM=new B.a5("\ubbfc","\ud68c\uc0ac\uc5d0\uc11c\ub294 \ud638\uce6d\ub3c4 \uc5b4\ub824\uc6b4 \uac83 \uac19\uc544\uc694.","T\xf4i th\u1ea5y c\xe1ch x\u01b0ng h\xf4 trong c\xf4ng ty c\u0169ng kh\xf3.")
A.eRQ=new B.a5("\uc9c0\uc218",'\uc9c1\uae09\uc774 \uc788\uc73c\uba74 \ubcf4\ud1b5 "\uacfc\uc7a5\ub2d8", "\ud300\uc7a5\ub2d8"\ucc98\ub7fc \uc9c1\uae09\uc5d0 "\ub2d8"\uc744 \ubd99\uc5ec \ubd80\ub974\uae30\ub3c4 \ud574\uc694.',"N\u1ebfu c\xf3 ch\u1ee9c v\u1ee5 th\xec th\u01b0\u1eddng c\u0169ng g\u1ecdi nh\u01b0 \u201cqu\u1ea3n l\xfd-nim\u201d, \u201ctr\u01b0\u1edfng nh\xf3m-nim\u201d, t\u1ee9c th\xeam \ub2d8 v\xe0o ch\u1ee9c v\u1ee5.")
A.eTd=new B.a5("\ubbfc","\uc774\ub984\ub9cc \ubd80\ub974\uba74 \uc548 \ub3fc\uc694?","Kh\xf4ng th\u1ec3 ch\u1ec9 g\u1ecdi t\xean sao?")
A.eSj=new B.a5("\uc9c0\uc218","\uad00\uacc4\uc640 \ud68c\uc0ac \ubb38\ud654\uc5d0 \ub530\ub77c \ub2e4\ub974\ub2c8\uae4c \uc798 \ubaa8\ub974\uaca0\uc73c\uba74 \uba3c\uc800 \ud655\uc778\ud558\ub294 \uac8c \uc88b\uc544\uc694.","T\xf9y quan h\u1ec7 v\xe0 v\u0103n h\xf3a c\xf4ng ty n\xean n\u1ebfu kh\xf4ng r\xf5 th\xec t\u1ed1t nh\u1ea5t h\xe3y x\xe1c nh\u1eadn tr\u01b0\u1edbc.")
A.eUX=new B.a5("\ubbfc","\uc5c5\ubb34 \uc9c0\uc2dc\ub97c \uc798 \ubabb \uc54c\uc544\ub4e4\uc744 \ub54c\ub3c4 \uc788\ub294\ub370 \ub2e4\uc2dc \ubb3c\uc5b4\ubcf4\uae30\uac00 \uc870\uae08 \ubd80\ub2f4\uc2a4\ub7ec\uc6cc\uc694.","C\xf3 l\xfac t\xf4i kh\xf4ng hi\u1ec3u r\xf5 ch\u1ec9 th\u1ecb c\xf4ng vi\u1ec7c nh\u01b0ng l\u1ea1i h\u01a1i ng\u1ea1i h\u1ecfi l\u1ea1i.")
A.eSR=new B.a5("\uc9c0\uc218","\ubaa8\ub974\uba74\uc11c \uc544\ub294 \ucc99\ud558\ub294 \uac83\ubcf4\ub2e4 \ub2e4\uc2dc \ud655\uc778\ud558\ub294 \uac8c \ud6e8\uc52c \uc88b\uc544\uc694.","X\xe1c nh\u1eadn l\u1ea1i t\u1ed1t h\u01a1n r\u1ea5t nhi\u1ec1u so v\u1edbi kh\xf4ng bi\u1ebft m\xe0 gi\u1ea3 v\u1edd bi\u1ebft.")
A.eTl=new B.a5("\ubbfc",'"\uc81c\uac00 \uc774\ud574\ud55c \uac8c \ub9de\ub294\uc9c0 \ub2e4\uc2dc \ud655\uc778\ud574\ub3c4 \ub420\uae4c\uc694?"\ub77c\uace0 \ub9d0\ud558\uba74 \ub418\uaca0\ub124\uc694.',"V\u1eady t\xf4i c\xf3 th\u1ec3 n\xf3i: \u201cT\xf4i c\xf3 th\u1ec3 x\xe1c nh\u1eadn l\u1ea1i xem m\xecnh hi\u1ec3u nh\u01b0 v\u1eady c\xf3 \u0111\xfang kh\xf4ng?\u201d")
A.eQE=new B.a5("\uc9c0\uc218","\ub9de\uc544\uc694. \ud2b9\ud788 \uc9c1\uc7a5\uc5d0\uc11c\ub294 \uc815\ud655\ud558\uac8c \ub4e3\uace0 \uc804\ub2ec\ud558\uace0 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud574\uc694.","\u0110\xfang v\u1eady. \u0110\u1eb7c bi\u1ec7t trong c\xf4ng vi\u1ec7c, vi\u1ec7c nghe, truy\u1ec1n \u0111\u1ea1t v\xe0 x\xe1c nh\u1eadn ch\xednh x\xe1c r\u1ea5t quan tr\u1ecdng.")
