A.iUb=s(["\uc2e4\uc804 = th\u1ef1c chi\u1ebfn.","\ubb38\uc81c \uc720\ud615 = d\u1ea1ng c\xe2u h\u1ecfi.","\uc815\ub2f5 = \u0111\xe1p \xe1n \u0111\xfang.","\uc624\ub2f5 = \u0111\xe1p \xe1n sai.","\ud574\uc124 = gi\u1ea3i th\xedch \u0111\xe1p \xe1n.","\ubb38\ub9e5 = ng\u1eef c\u1ea3nh.","\uc0c1\ud669 = t\xecnh hu\u1ed1ng.","\ud310\ub2e8\ud558\ub2e4 = \u0111\xe1nh gi\xe1 / ph\xe1n \u0111o\xe1n.","\ud655\uc778\ud558\ub2e4 = x\xe1c nh\u1eadn.","\uc2e0\uace0\ud558\ub2e4 = tr\xecnh b\xe1o.","\ubcf4\ud638\uad6c = \u0111\u1ed3 b\u1ea3o h\u1ed9.","\uadfc\ub85c\uc870\uac74 = \u0111i\u1ec1u ki\u1ec7n lao \u0111\u1ed9ng.",u.eH,"\uc9c4\ub85c = \u0111\u1ecbnh h\u01b0\u1edbng ngh\u1ec1 nghi\u1ec7p.","\uacf5\uc57d = cam k\u1ebft tranh c\u1eed.","\ubd84\ub9ac\ubc30\ucd9c = ph\xe2n lo\u1ea1i r\xe1c.","\ucda9\ub3d9\uad6c\ub9e4 = mua h\xe0ng b\u1ed1c \u0111\u1ed3ng.","\uad8c\ub9ac = quy\u1ec1n.","\uc758\ubb34 = ngh\u0129a v\u1ee5.","\uccb4\ub958 \uc790\uaca9 = t\u01b0 c\xe1ch l\u01b0u tr\xfa.","\ud589\uc815 \uc808\ucc28 = th\u1ee7 t\u1ee5c h\xe0nh ch\xednh.","-\ub290\ub77c\uace0 = v\xec m\u1ea3i... n\xean...","-(\uc73c)\u3139\uc218\ub85d = c\xe0ng... c\xe0ng...",u.W,"-\ub294 \uc904 \uc54c\ub2e4 = t\u01b0\u1edfng r\u1eb1ng...","-(\uc73c)\u3139 \ubed4\ud558\ub2e4 = su\xfdt n\u1eefa...","-\uace0 \ub9d0\ub2e4 = cu\u1ed1i c\xf9ng/r\u1ed1t cu\u1ed9c \u0111\xe3...","-\uae30 \ub9c8\ub828\uc774\ub2e4 = v\u1ed1n d\u0129 th\u01b0\u1eddng...","-\uc9c0 \uc54a\ub294 \ud55c = n\u1ebfu kh\xf4ng / tr\u1eeb khi...","-(\uc73c)\ubbc0\ub85c = v\xec / do...","-(\uc73c)\u3139\uc9c0\ub3c4 \ubaa8\ub974\ub2e4 = c\xf3 th\u1ec3 / bi\u1ebft \u0111\xe2u...","\ubb38\ubc95 \ubb38\uc81c\ub294 \ube48\uce78 \ubc14\ub85c \uc55e\uc758 \ub2e8\uc5b4\ub9cc \ubcf4\uc9c0 \ub9d0\uace0 \ubb38\uc7a5 \uc804\uccb4\uc758 \uc758\ubbf8\ub97c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc0c1\ud669 \ubb38\uc81c\uc5d0\uc11c\ub294 \ud55c\uad6d \uc0dd\ud65c\uc5d0\uc11c \uc2e4\uc81c\ub85c \uac00\uc7a5 \uc548\uc804\ud558\uace0 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \ud589\ub3d9\uc774 \ubb34\uc5c7\uc778\uc9c0 \uc0dd\uac01\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc9c1\uc7a5\uc5d0\uc11c\ub294 \ubaa8\ub974\ub294 \uc791\uc5c5\uc744 \uc544\ub294 \ucc99\ud558\uc9c0 \ub9d0\uace0 \uc815\ud655\ud558\uac8c \ub2e4\uc2dc \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\uc0ac\uace0\ub098 \ud654\uc7ac \ub4f1 \uae34\uae09 \uc0c1\ud669\uc5d0\uc11c\ub294 \uc790\uc2e0\uc758 \uc548\uc804\uc744 \uba3c\uc800 \ud655\ubcf4\ud558\uace0 \ud544\uc694\ud55c \uae34\uae09 \uae30\uad00\uc5d0 \uc2e0\uace0\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc778\ud130\ub137\uacfc \ud589\uc815 \uc815\ubcf4\ub294 \ucd9c\ucc98\uc640 \ub0a0\uc9dc\ub97c \ud655\uc778\ud558\uace0 \uc911\uc694\ud55c \ub0b4\uc6a9\uc740 \uacf5\uc2dd \uc548\ub0b4\ub97c \ud1b5\ud574 \ub2e4\uc2dc \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","\uacbd\uc81c\uc0dd\ud65c\uc5d0\uc11c\ub294 \uc18c\ub4dd\uacfc \uc9c0\ucd9c\uc744 \ud30c\uc545\ud558\uace0 \ucda9\ub3d9\uad6c\ub9e4\ub97c \uc904\uc774\uba70 \uacc4\ud68d\uc801\uc73c\ub85c \uc18c\ube44\ud558\ub294 \uc2b5\uad00\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\ubc95\uacfc \uaddc\uce59\uc740 \ucc98\ubc8c\uc744 \ud53c\ud558\uae30 \uc704\ud574\uc11c\ub9cc\uc774 \uc544\ub2c8\ub77c \uc790\uc2e0\uacfc \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc548\uc804\uacfc \uad8c\ub9ac\ub97c \ubcf4\ud638\ud558\uae30 \uc704\ud574 \uc9c0\ucf1c\uc57c \ud569\ub2c8\ub2e4.","\uc624\ub2f5\uc740 \uadf8\ub0e5 \ub118\uc5b4\uac00\uc9c0 \ub9d0\uace0 \uc65c \ud2c0\ub838\ub294\uc9c0 \ud655\uc778\ud558\uba74 \uac19\uc740 \uc720\ud615\uc758 \ubb38\uc81c\ub97c \ub2e4\uc2dc \ud2c0\ub9b4 \uac00\ub2a5\uc131\uc744 \uc904\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4.","KIIP \uc2e4\uc804\uc5d0\uc11c\ub294 \uc5b4\ud718 + \ubb38\ubc95 + \ud55c\uad6d \uc0dd\ud65c \uc9c0\uc2dd\uc744 \ub530\ub85c \uc678\uc6b0\uae30\ubcf4\ub2e4 \ud558\ub098\uc758 \uc0c1\ud669\uc73c\ub85c \uc5f0\uacb0\ud574\uc11c \uae30\uc5b5\ud558\ub294 \uac83\uc774 \ud6a8\uacfc\uc801\uc785\ub2c8\ub2e4."],t.s)
A.Ko=new B.hG(19,"KIIP \uc2e4\uc804 \ubb38\uc81c","Luy\u1ec7n \u0111\u1ec1 th\u1ef1c chi\u1ebfn KIIP",A.iqr,A.iNE,A.h6a,A.iyO,A.iqk,A.iUb)
A.iPZ=s(["\ud658\uacbd \ubcf4\ud638\uc758 \uc758\ubbf8\uc640 \ud544\uc694\uc131\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ub300\uae30 \uc624\uc5fc, \uc218\uc9c8 \uc624\uc5fc, \uc4f0\ub808\uae30 \ubb38\uc81c \ub4f1 \ud604\ub300 \uc0ac\ud68c\uc758 \ud658\uacbd \ubb38\uc81c\ub97c \uc54c\uc544\ubd05\ub2c8\ub2e4.","\uc4f0\ub808\uae30 \ubd84\ub9ac\ubc30\ucd9c\uacfc \uc7ac\ud65c\uc6a9\uc774 \uc65c \uc911\uc694\ud55c\uc9c0 \uc774\ud574\ud569\ub2c8\ub2e4.","\uc77c\ud68c\uc6a9\ud488 \uc0ac\uc6a9\uc744 \uc904\uc774\uace0 \uc790\uc6d0\uc744 \uc808\uc57d\ud558\ub294 \uc0dd\ud65c \uc2b5\uad00\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc5d0\ub108\uc9c0 \uc808\uc57d\uacfc \ub300\uc911\uad50\ud1b5 \uc774\uc6a9\uc774 \ud658\uacbd \ubcf4\ud638\uc5d0 \ub3c4\uc6c0\uc774 \ub41c\ub2e4\ub294 \uc810\uc744 \uc54c\uc544\ubd05\ub2c8\ub2e4.","\ud658\uacbd \ubb38\uc81c\ub294 \uac1c\uc778\ubfd0\ub9cc \uc544\ub2c8\ub77c \uae30\uc5c5\uacfc \uc815\ubd80, \uad6d\uc81c \uc0ac\ud68c\uac00 \ud568\uaed8 \ud574\uacb0\ud574\uc57c \ud55c\ub2e4\ub294 \uc810\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\uc0dd\ud65c \uc18d \uc791\uc740 \uc2e4\ucc9c\uc774 \ud658\uacbd \ubcf4\ud638\uc5d0 \uc911\uc694\ud55c \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\ud604\uc7ac\uc758 \ud3b8\ub9ac\ud568\ubfd0\ub9cc \uc544\ub2c8\ub77c \ubbf8\ub798 \uc138\ub300\ub97c \uc0dd\uac01\ud558\ub294 \ucc45\uc784 \uc788\ub294 \ud0dc\ub3c4\ub97c \uae30\ub985\ub2c8\ub2e4."],t.s)
A.f1n=new B.A("\ud658\uacbd","m\xf4i tr\u01b0\u1eddng","\uae68\ub057\ud55c \ud658\uacbd\uc744 \uc9c0\ud0a4\uae30 \uc704\ud574 \ubaa8\ub450\uac00 \ub178\ub825\ud574\uc57c \ud569\ub2c8\ub2e4.","M\u1ecdi ng\u01b0\u1eddi c\u1ea7n n\u1ed7 l\u1ef1c \u0111\u1ec3 gi\u1eef g\xecn m\xf4i tr\u01b0\u1eddng s\u1ea1ch \u0111\u1eb9p.")
A.f0J=new B.A("\ud658\uacbd \ubcf4\ud638","b\u1ea3o v\u1ec7 m\xf4i tr\u01b0\u1eddng","\ud658\uacbd \ubcf4\ud638\ub97c \uc704\ud574 \uc77c\ud68c\uc6a9\ud488 \uc0ac\uc6a9\uc744 \uc904\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.","T\xf4i \u0111ang gi\u1ea3m s\u1eed d\u1ee5ng \u0111\u1ed3 d\xf9ng m\u1ed9t l\u1ea7n \u0111\u1ec3 b\u1ea3o v\u1ec7 m\xf4i tr\u01b0\u1eddng.")
A.eXv=new B.A("\ud658\uacbd \ubb38\uc81c","v\u1ea5n \u0111\u1ec1 m\xf4i tr\u01b0\u1eddng","\uae30\ud6c4 \ubcc0\ud654\ub294 \uc911\uc694\ud55c \ud658\uacbd \ubb38\uc81c \uc911 \ud558\ub098\uc785\ub2c8\ub2e4.","Bi\u1ebfn \u0111\u1ed5i kh\xed h\u1eadu l\xe0 m\u1ed9t trong nh\u1eefng v\u1ea5n \u0111\u1ec1 m\xf4i tr\u01b0\u1eddng quan tr\u1ecdng.")
A.eXT=new B.A("\uc624\uc5fc","\xf4 nhi\u1ec5m","\uacf5\uc7a5\uacfc \uc790\ub3d9\ucc28 \ub54c\ubb38\uc5d0 \ud658\uacbd \uc624\uc5fc\uc774 \uc2ec\ud574\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","Do nh\xe0 m\xe1y v\xe0 \xf4 t\xf4, \xf4 nhi\u1ec5m m\xf4i tr\u01b0\u1eddng c\xf3 th\u1ec3 tr\u1edf n\xean nghi\xeam tr\u1ecdng h\u01a1n.")
A.eXK=new B.A("\ub300\uae30 \uc624\uc5fc","\xf4 nhi\u1ec5m kh\xf4ng kh\xed","\ub300\uae30 \uc624\uc5fc\uc774 \uc2ec\ud55c \ub0a0\uc5d0\ub294 \uc57c\uc678 \ud65c\ub3d9\uc744 \uc904\uc774\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","V\xe0o nh\u1eefng ng\xe0y \xf4 nhi\u1ec5m kh\xf4ng kh\xed nghi\xeam tr\u1ecdng n\xean gi\u1ea3m ho\u1ea1t \u0111\u1ed9ng ngo\xe0i tr\u1eddi.")
A.f_k=new B.A("\uc218\uc9c8 \uc624\uc5fc","\xf4 nhi\u1ec5m ngu\u1ed3n n\u01b0\u1edbc","\uc0dd\ud65c \uc4f0\ub808\uae30\uc640 \ud3d0\uc218\uac00 \uc218\uc9c8 \uc624\uc5fc\uc758 \uc6d0\uc778\uc774 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","R\xe1c sinh ho\u1ea1t v\xe0 n\u01b0\u1edbc th\u1ea3i c\xf3 th\u1ec3 l\xe0 nguy\xean nh\xe2n g\xe2y \xf4 nhi\u1ec5m ngu\u1ed3n n\u01b0\u1edbc.")
A.eYt=new B.A("\ubbf8\uc138\uba3c\uc9c0","b\u1ee5i m\u1ecbn","\ubbf8\uc138\uba3c\uc9c0\uac00 \ub9ce\uc740 \ub0a0\uc5d0\ub294 \ub9c8\uc2a4\ud06c\ub97c \ucc29\uc6a9\ud558\uae30\ub3c4 \ud569\ub2c8\ub2e4.","V\xe0o ng\xe0y c\xf3 nhi\u1ec1u b\u1ee5i m\u1ecbn, ng\u01b0\u1eddi ta c\u0169ng th\u01b0\u1eddng \u0111eo kh\u1ea9u trang.")
A.eYI=new B.A("\uae30\ud6c4 \ubcc0\ud654","bi\u1ebfn \u0111\u1ed5i kh\xed h\u1eadu","\uae30\ud6c4 \ubcc0\ud654\ub85c \uc138\uacc4 \uc5ec\ub7ec \uc9c0\uc5ed\uc5d0\uc11c \uc774\uc0c1 \uae30\ud6c4\uac00 \ub098\ud0c0\ub098\uace0 \uc788\uc2b5\ub2c8\ub2e4.","Do bi\u1ebfn \u0111\u1ed5i kh\xed h\u1eadu, th\u1eddi ti\u1ebft b\u1ea5t th\u01b0\u1eddng \u0111ang xu\u1ea5t hi\u1ec7n \u1edf nhi\u1ec1u khu v\u1ef1c tr\xean th\u1ebf gi\u1edbi.")
A.eXN=new B.A("\uc9c0\uad6c \uc628\ub09c\ud654","s\u1ef1 n\xf3ng l\xean to\xe0n c\u1ea7u","\uc9c0\uad6c \uc628\ub09c\ud654\ub97c \uc904\uc774\uae30 \uc704\ud574 \uc628\uc2e4\uac00\uc2a4 \ubc30\ucd9c\uc744 \uc904\uc5ec\uc57c \ud569\ub2c8\ub2e4.","\u0110\u1ec3 gi\u1ea3m s\u1ef1 n\xf3ng l\xean to\xe0n c\u1ea7u c\u1ea7n gi\u1ea3m ph\xe1t th\u1ea3i kh\xed nh\xe0 k\xednh.")
A.f1q=new B.A("\uc628\uc2e4\uac00\uc2a4","kh\xed nh\xe0 k\xednh","\uc790\ub3d9\ucc28\uc640 \uc0b0\uc5c5 \ud65c\ub3d9\uc5d0\uc11c \uc628\uc2e4\uac00\uc2a4\uac00 \ubc1c\uc0dd\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","Kh\xed nh\xe0 k\xednh c\xf3 th\u1ec3 ph\xe1t sinh t\u1eeb \xf4 t\xf4 v\xe0 c\xe1c ho\u1ea1t \u0111\u1ed9ng c\xf4ng nghi\u1ec7p.")
