A.f0v=new B.A("\ubd84\ub9ac\ubc30\ucd9c","ph\xe2n lo\u1ea1i r\xe1c \u0111\u1ec3 b\u1ecf","\uc7ac\ud65c\uc6a9\ud488\uc740 \uc885\ub958\uc5d0 \ub530\ub77c \ubd84\ub9ac\ubc30\ucd9c\ud574\uc57c \ud569\ub2c8\ub2e4.","\u0110\u1ed3 t\xe1i ch\u1ebf c\u1ea7n \u0111\u01b0\u1ee3c ph\xe2n lo\u1ea1i theo t\u1eebng lo\u1ea1i khi b\u1ecf.")
A.f1j=new B.A("\uc7ac\ud65c\uc6a9","t\xe1i ch\u1ebf","\uc885\uc774\uc640 \ud50c\ub77c\uc2a4\ud2f1\uc740 \uc7ac\ud65c\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","Gi\u1ea5y v\xe0 nh\u1ef1a c\xf3 th\u1ec3 \u0111\u01b0\u1ee3c t\xe1i ch\u1ebf.")
A.f0d=new B.A("\uc7ac\ud65c\uc6a9\ud488","\u0111\u1ed3 c\xf3 th\u1ec3 t\xe1i ch\u1ebf","\uc7ac\ud65c\uc6a9\ud488\uc740 \uae68\ub057\ud558\uac8c \uc815\ub9ac\ud574\uc11c \ubc84\ub9ac\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","N\xean l\xe0m s\u1ea1ch v\xe0 s\u1eafp x\u1ebfp \u0111\u1ed3 t\xe1i ch\u1ebf tr\u01b0\u1edbc khi b\u1ecf.")
A.f1D=new B.A("\uc77c\ud68c\uc6a9\ud488","\u0111\u1ed3 d\xf9ng m\u1ed9t l\u1ea7n","\ud658\uacbd\uc744 \uc704\ud574 \uc77c\ud68c\uc6a9\ud488 \uc0ac\uc6a9\uc744 \uc904\uc774\ub294 \uc0ac\ub78c\uc774 \ub9ce\uc544\uc84c\uc2b5\ub2c8\ub2e4.","S\u1ed1 ng\u01b0\u1eddi gi\u1ea3m s\u1eed d\u1ee5ng \u0111\u1ed3 d\xf9ng m\u1ed9t l\u1ea7n v\xec m\xf4i tr\u01b0\u1eddng \u0111\xe3 t\u0103ng l\xean.")
A.eZx=new B.A("\uc7a5\ubc14\uad6c\ub2c8","t\xfai \u0111i ch\u1ee3, t\xfai mua s\u1eafm t\xe1i s\u1eed d\u1ee5ng","\ube44\ub2d0\ubd09\uc9c0 \ub300\uc2e0 \uc7a5\ubc14\uad6c\ub2c8\ub97c \uc0ac\uc6a9\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.","T\xf4i \u0111ang s\u1eed d\u1ee5ng t\xfai mua s\u1eafm thay cho t\xfai nilon.")
A.eVK=new B.A("\ud140\ube14\ub7ec","b\xecnh/c\u1ed1c c\xe1 nh\xe2n","\uc77c\ud68c\uc6a9 \ucef5 \ub300\uc2e0 \ud140\ube14\ub7ec\ub97c \uc0ac\uc6a9\ud569\ub2c8\ub2e4.","T\xf4i s\u1eed d\u1ee5ng c\u1ed1c c\xe1 nh\xe2n thay cho c\u1ed1c d\xf9ng m\u1ed9t l\u1ea7n.")
