A.fN4=s(["\u2460 \uc4f0\ub808\uae30\ub97c \uc885\ub958\uc5d0 \ub530\ub77c \uad6c\ubd84\ud574\uc11c \ubc84\ub9ac\ub294 \uac83","\u2461 \ubaa8\ub4e0 \uc4f0\ub808\uae30\ub97c \ud55c \ubd09\ud22c\uc5d0 \ub123\ub294 \uac83","\u2462 \uc4f0\ub808\uae30\ub97c \uc544\ubb34 \uacf3\uc5d0\ub098 \ubc84\ub9ac\ub294 \uac83","\u2463 \uc4f0\ub808\uae30\ub97c \uc9d1\uc5d0 \uacc4\uc18d \ubcf4\uad00\ud558\ub294 \uac83"],t.s)
A.eME=new B.aj('"\ubd84\ub9ac\ubc30\ucd9c"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?',A.fN4,0,'"\ubd84\ub9ac\ubc30\ucd9c"\uc740 \uc77c\ubc18 \uc4f0\ub808\uae30, \uc74c\uc2dd\ubb3c \uc4f0\ub808\uae30, \uc7ac\ud65c\uc6a9\ud488 \ub4f1\uc744 \uc815\ud574\uc9c4 \uc885\ub958\uc640 \ubc29\ubc95\uc5d0 \ub530\ub77c \ub098\ub204\uc5b4 \ubc84\ub9ac\ub294 \uac83\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4.')
A.hs9=s(["\u2460 \uc0ac\uc6a9\ud55c \uc790\uc6d0\uc774\ub098 \ubb3c\uac74\uc744 \ub2e4\uc2dc \uc774\uc6a9\ud560 \uc218 \uc788\uac8c \ud558\ub294 \uac83","\u2461 \ubaa8\ub4e0 \ubb3c\uac74\uc744 \ubc14\ub85c \ubc84\ub9ac\ub294 \uac83","\u2462 \ubb3c\uac74\uc744 \uc77c\ubd80\ub7ec \ub9dd\uac00\ub728\ub9ac\ub294 \uac83","\u2463 \uc804\uae30\ub97c \ub354 \ub9ce\uc774 \uc0ac\uc6a9\ud558\ub294 \uac83"],t.s)
A.ePb=new B.aj('"\uc7ac\ud65c\uc6a9"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?',A.hs9,0,'"\uc7ac\ud65c\uc6a9"\uc740 \uc774\ubbf8 \uc0ac\uc6a9\ud55c \ubb3c\uac74\uc774\ub098 \uc790\uc6d0\uc744 \ucc98\ub9ac\ud558\uc5ec \ub2e4\uc2dc \uc0ac\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d \ud558\ub294 \uac83\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4.')
