A.eMm=new B.aj("\uc77c\ud68c\uc6a9 \ucef5 \ub300\uc2e0 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \uac83\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.h14,0,"\uac1c\uc778 \ud140\ube14\ub7ec\ub97c \uc0ac\uc6a9\ud558\uba74 \uc77c\ud68c\uc6a9 \ucef5 \uc0ac\uc6a9\uc744 \uc904\uc774\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.")
A.h5Y=s(["\u2460 \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ud568\uaed8 \uc774\ub3d9\ud558\uc5ec \uc5d0\ub108\uc9c0 \uc18c\ube44\uc640 \ubc30\ucd9c\uc744 \uc904\uc774\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\uae30 \ub54c\ubb38\uc5d0","\u2461 \uc790\ub3d9\ucc28\ub97c \ub354 \ub9ce\uc774 \uc0ac\uc6a9\ud558\uae30 \ub54c\ubb38\uc5d0","\u2462 \uc4f0\ub808\uae30\ub97c \ub354 \ub9ce\uc774 \ub9cc\ub4e4\uae30 \ub54c\ubb38\uc5d0","\u2463 \uc804\uae30\ub97c \ubaa8\ub450 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uac8c \ud558\uae30 \ub54c\ubb38\uc5d0"],t.s)
A.eMD=new B.aj("\ub300\uc911\uad50\ud1b5 \uc774\uc6a9\uc774 \ud658\uacbd \ubcf4\ud638\uc5d0 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\ub294 \uc774\uc720\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.h5Y,0,"\ub300\uc911\uad50\ud1b5\uc740 \ub9ce\uc740 \uc0ac\ub78c\uc774 \ud568\uaed8 \uc774\ub3d9\ud560 \uc218 \uc788\uae30 \ub54c\ubb38\uc5d0 \uac1c\uc778 \ucc28\ub7c9 \uc774\uc6a9\uc744 \uc904\uc774\uace0 \uc5d0\ub108\uc9c0 \uc18c\ube44\uc640 \ubc30\ucd9c\uc744 \uc904\uc774\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.")
A.hIf=s(["\u2460 \uc55e\uc73c\ub85c \uc0b4\uc544\uac08 \ub2e4\uc74c \uc138\ub300\uc758 \uc0ac\ub78c\ub4e4","\u2461 \ud604\uc7ac \ud68c\uc0ac\uc758 \uc9c1\uc6d0\ub4e4\ub9cc","\u2462 \uacfc\uac70\uc5d0 \uc0b4\uc558\ub358 \uc0ac\ub78c\ub4e4","\u2463 \uc624\ub298 \uc5ec\ud589\ud558\ub294 \uc0ac\ub78c\ub4e4"],t.s)
A.eM8=new B.aj('"\ubbf8\ub798 \uc138\ub300"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?',A.hIf,0,'"\ubbf8\ub798 \uc138\ub300"\ub294 \uc55e\uc73c\ub85c \ud0dc\uc5b4\ub098\uac70\ub098 \uc0b4\uc544\uac08 \ub2e4\uc74c \uc138\ub300\uc758 \uc0ac\ub78c\ub4e4\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4.')
A.iop=s(["\u2460 \uac1c\uc778, \uae30\uc5c5, \uc815\ubd80 \ub4f1\uc774 \ud568\uaed8 \ub178\ub825\ud55c\ub2e4","\u2461 \ud658\uacbd \ubb38\uc81c\ub294 \uc544\ubb34\ub3c4 \uc2e0\uacbd \uc4f0\uc9c0 \uc54a\ub294\ub2e4","\u2462 \ubaa8\ub4e0 \ucc45\uc784\uc744 \ud55c \uc0ac\ub78c\uc5d0\uac8c\ub9cc \ub9e1\uae34\ub2e4","\u2463 \uc4f0\ub808\uae30 \ubb38\uc81c\ub97c \ubb34\uc2dc\ud55c\ub2e4"],t.s)
A.eNf=new B.aj("\ud658\uacbd \ubb38\uc81c\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud55c \ud0dc\ub3c4\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.iop,0,"\ud658\uacbd \ubb38\uc81c\ub294 \uac1c\uc778\uc758 \uc0dd\ud65c \uc2b5\uad00\ubfd0\ub9cc \uc544\ub2c8\ub77c \uae30\uc5c5 \ud65c\ub3d9\uacfc \uc81c\ub3c4\uc5d0\ub3c4 \uad00\ub828\ub418\ubbc0\ub85c \uc0ac\ud68c \uc804\uccb4\uc758 \ud611\ub825\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.hE4=s(["\u2460 \ud55c","\u2461 \ucc99","\u2462 \uacb8","\u2463 \uc815\ub3c4\ub85c"],t.s)
A.eNZ=new B.aj("\ub2e4\uc74c \ub300\ud654\uc5d0 \ub4e4\uc5b4\uac08 \ud45c\ud604\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?\n\n\uac00: \uc4f0\ub808\uae30 \ubb38\uc81c\uac00 \uacc4\uc18d \uc2ec\ud574\uc9c0\ub294 \uac83 \uac19\uc544\uc694.\n\ub098: \ub124. \uc0ac\ub78c\ub4e4\uc774 \uc0dd\ud65c \uc2b5\uad00\uc744 \ubc14\uafb8\uc9c0 \uc54a\ub294______ \ud574\uacb0\ud558\uae30 \uc5b4\ub824\uc6b8 \uac70\uc608\uc694.",A.hE4,0,'\ud2b9\uc815 \uc870\uac74\uc774 \ubc14\ub00c\uc9c0 \uc54a\uc73c\uba74 \ub4a4\uc758 \uacb0\uacfc\ub3c4 \ub2ec\ub77c\uc9c0\uae30 \uc5b4\ub835\ub2e4\ub294 \uc758\ubbf8\uc774\ubbc0\ub85c "-\uc9c0 \uc54a\ub294 \ud55c"\uc774 \uac00\uc7a5 \uc54c\ub9de\uc2b5\ub2c8\ub2e4.')
A.fQH=s([A.eME,A.ePb,A.eOE,A.eNB,A.ePk,A.eMm,A.eMD,A.eM8,A.eNf,A.eNZ],t.Fo)
A.fz7=s(["\ud658\uacbd = m\xf4i tr\u01b0\u1eddng.","\ud658\uacbd \ubcf4\ud638 = b\u1ea3o v\u1ec7 m\xf4i tr\u01b0\u1eddng.","\ud658\uacbd \ubb38\uc81c = v\u1ea5n \u0111\u1ec1 m\xf4i tr\u01b0\u1eddng.","\uc624\uc5fc = \xf4 nhi\u1ec5m.","\ub300\uae30 \uc624\uc5fc = \xf4 nhi\u1ec5m kh\xf4ng kh\xed.","\uc218\uc9c8 \uc624\uc5fc = \xf4 nhi\u1ec5m ngu\u1ed3n n\u01b0\u1edbc.","\ubbf8\uc138\uba3c\uc9c0 = b\u1ee5i m\u1ecbn.","\uae30\ud6c4 \ubcc0\ud654 = bi\u1ebfn \u0111\u1ed5i kh\xed h\u1eadu.","\uc9c0\uad6c \uc628\ub09c\ud654 = s\u1ef1 n\xf3ng l\xean to\xe0n c\u1ea7u.","\uc628\uc2e4\uac00\uc2a4 = kh\xed nh\xe0 k\xednh.","\uc0dd\ud65c \uc4f0\ub808\uae30 = r\xe1c sinh ho\u1ea1t.","\uc74c\uc2dd\ubb3c \uc4f0\ub808\uae30 = r\xe1c th\u1ef1c ph\u1ea9m.","\ubd84\ub9ac\ubc30\ucd9c = ph\xe2n lo\u1ea1i r\xe1c khi b\u1ecf.","\uc7ac\ud65c\uc6a9 = t\xe1i ch\u1ebf.","\uc7ac\ud65c\uc6a9\ud488 = \u0111\u1ed3 c\xf3 th\u1ec3 t\xe1i ch\u1ebf.","\uc77c\ud68c\uc6a9\ud488 = \u0111\u1ed3 d\xf9ng m\u1ed9t l\u1ea7n.","\uc7a5\ubc14\uad6c\ub2c8 = t\xfai mua s\u1eafm t\xe1i s\u1eed d\u1ee5ng.","\ud140\ube14\ub7ec = c\u1ed1c/b\xecnh c\xe1 nh\xe2n.","\uc790\uc6d0\uc744 \uc808\uc57d\ud558\ub2e4 = ti\u1ebft ki\u1ec7m t\xe0i nguy\xean.","\uc5d0\ub108\uc9c0\ub97c \uc808\uc57d\ud558\ub2e4 = ti\u1ebft ki\u1ec7m n\u0103ng l\u01b0\u1ee3ng.","\uc804\uae30\ub97c \uc544\ub07c\ub2e4 = ti\u1ebft ki\u1ec7m \u0111i\u1ec7n.","\ub300\uc911\uad50\ud1b5 = ph\u01b0\u01a1ng ti\u1ec7n giao th\xf4ng c\xf4ng c\u1ed9ng.","\uce5c\ud658\uacbd = th\xe2n thi\u1ec7n v\u1edbi m\xf4i tr\u01b0\u1eddng.","\uce5c\ud658\uacbd \uc81c\ud488 = s\u1ea3n ph\u1ea9m th\xe2n thi\u1ec7n v\u1edbi m\xf4i tr\u01b0\u1eddng.","\uc2e4\ucc9c\ud558\ub2e4 = th\u1ef1c hi\u1ec7n / th\u1ef1c h\xe0nh.","\ubbf8\ub798 \uc138\ub300 = th\u1ebf h\u1ec7 t\u01b0\u01a1ng lai.","-\uc9c0 \uc54a\ub294 \ud55c = tr\u1eeb khi / n\u1ebfu kh\xf4ng...","-\ub294 \ud55c = ch\u1eebng n\xe0o c\xf2n...","-\ub3c4\ub85d = \u0111\u1ec3 / sao cho...","-\ub3c4\ub85d \ub178\ub825\ud558\ub2e4 = c\u1ed1 g\u1eafng \u0111\u1ec3...","-\uae30 \uc704\ud574\uc11c = \u0111\u1ec3...","-\uc544/\uc5b4\uc57c \ud558\ub2e4 = ph\u1ea3i...","\uc4f0\ub808\uae30\ub294 \uc885\ub958\uc5d0 \ub530\ub77c \uc62c\ubc14\ub974\uac8c \ubd84\ub9ac\ubc30\ucd9c\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\uc77c\ud68c\uc6a9\ud488 \uc0ac\uc6a9\uc744 \uc904\uc774\uace0 \uc7ac\ud65c\uc6a9\uc744 \ud558\uba74 \uc790\uc6d0\uc744 \uc808\uc57d\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.","\ub300\uc911\uad50\ud1b5 \uc774\uc6a9\uacfc \uc5d0\ub108\uc9c0 \uc808\uc57d\ub3c4 \uc0dd\ud65c \uc18d\uc5d0\uc11c \uc2e4\ucc9c\ud560 \uc218 \uc788\ub294 \ud658\uacbd \ubcf4\ud638 \ubc29\ubc95\uc785\ub2c8\ub2e4.","\ud658\uacbd \ubb38\uc81c\ub294 \uac1c\uc778\ub9cc\uc758 \ubb38\uc81c\uac00 \uc544\ub2c8\ubbc0\ub85c \uae30\uc5c5, \uc815\ubd80, \uc0ac\ud68c\uac00 \ud568\uaed8 \ub178\ub825\ud574\uc57c \ud569\ub2c8\ub2e4.","\ud604\uc7ac\uc758 \ud3b8\ub9ac\ud568\ubfd0\ub9cc \uc544\ub2c8\ub77c \ubbf8\ub798 \uc138\ub300\ub97c \uc0dd\uac01\ud558\uba70 \ud658\uacbd\uc744 \ubcf4\ud638\ud558\ub294 \ud0dc\ub3c4\uac00 \ud544\uc694\ud569\ub2c8\ub2e4."],t.s)
A.Kp=new B.hG(13,"\ud658\uacbd \ubcf4\ud638","B\u1ea3o v\u1ec7 m\xf4i tr\u01b0\u1eddng",A.iPZ,A.j3W,A.fOO,A.fLz,A.fQH,A.fz7)
A.iVo=s(["1\uacfc\ubd80\ud130 8\uacfc\uae4c\uc9c0 \ubc30\uc6b4 \ud575\uc2ec \ub0b4\uc6a9\uc744 \uc885\ud569\uc801\uc73c\ub85c \ubcf5\uc2b5\ud569\ub2c8\ub2e4.","\ud55c\uad6d \uc0dd\ud65c \uc801\uc751, \uac00\uc871\uc758 \ubcc0\ud654, \uc0dd\ud65c \uc18d\uc758 \uacfc\ud559, \ud55c\uad6d\uc758 \uc758\ub840\ub97c \ub2e4\uc2dc \uc815\ub9ac\ud569\ub2c8\ub2e4.","\ubb38\ud654\uc720\uc0b0, \uad6d\uc81c\ud654 \uc2dc\ub300, \ud604\ub300\uc778\uc758 \uc9c8\ubcd1, \uc815\ubcf4\ud654 \uc0ac\ud68c\uc758 \ud575\uc2ec \uc5b4\ud718\ub97c \ubcf5\uc2b5\ud569\ub2c8\ub2e4.","\uac01 \ub2e8\uc6d0\uc5d0\uc11c \ubc30\uc6b4 \uc8fc\uc694 \ubb38\ubc95\uc744 \uc2e4\uc81c \ubb38\uc7a5 \uc18d\uc5d0\uc11c \ub2e4\uc2dc \ud655\uc778\ud569\ub2c8\ub2e4.","\ube44\uc2b7\ud55c \ubb38\ubc95\uc758 \uc758\ubbf8\uc640 \uc0ac\uc6a9 \uc0c1\ud669\uc744 \ube44\uad50\ud558\uc5ec \uc815\ud655\ud558\uac8c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d \uc5f0\uc2b5\ud569\ub2c8\ub2e4.","\uc0dd\ud65c, \uc9c1\uc7a5, \uac00\uc871, \uac74\uac15, \uc778\ud130\ub137 \ub4f1 \uc2e4\uc81c \ud55c\uad6d \uc0dd\ud65c\uc5d0\uc11c \uc790\uc8fc \ub9cc\ub098\ub294 \uc0c1\ud669\uc744 \uc5f0\uacb0\ud574\uc11c \ud559\uc2b5\ud569\ub2c8\ub2e4.","\ub2e8\uc21c\ud788 \ub2e8\uc5b4\ub97c \uc554\uae30\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc0c1\ud669\uc744 \ubcf4\uace0 \uc801\uc808\ud55c \ud45c\ud604\uc744 \uc120\ud0dd\ud558\ub294 \uc5f0\uc2b5\uc744 \ud569\ub2c8\ub2e4.","KIIP \uc2dc\ud5d8\uc5d0\uc11c \uc790\uc8fc \ub098\uc62c \uc218 \uc788\ub294 \uc5b4\ud718, \ubb38\ubc95, \ub0b4\uc6a9 \uc774\ud574 \ubb38\uc81c\ub97c \uc885\ud569\uc801\uc73c\ub85c \uc5f0\uc2b5\ud569\ub2c8\ub2e4."],t.s)
