A.fRd=s(["\ubb38\ud654\uc720\uc0b0 = di s\u1ea3n v\u0103n h\xf3a.","\uc720\ud615 \ubb38\ud654\uc720\uc0b0 = di s\u1ea3n v\u0103n h\xf3a h\u1eefu h\xecnh.","\ubb34\ud615 \ubb38\ud654\uc720\uc0b0 = di s\u1ea3n v\u0103n h\xf3a phi v\u1eadt th\u1ec3.","\uc804\ud1b5\ubb38\ud654 = v\u0103n h\xf3a truy\u1ec1n th\u1ed1ng.","\uc720\uc801 = di t\xedch.","\uc720\ubb3c = di v\u1eadt.","\uad81\uad90 = cung \u0111i\u1ec7n.","\uc0ac\ucc30 = ch\xf9a.","\ud55c\uc625 = nh\xe0 truy\u1ec1n th\u1ed1ng H\xe0n Qu\u1ed1c.","\ud55c\ubcf5 = trang ph\u1ee5c truy\u1ec1n th\u1ed1ng H\xe0n Qu\u1ed1c.","\uc804\ud1b5 \uc74c\uc2dd = m\xf3n \u0103n truy\u1ec1n th\u1ed1ng.","\uc804\ud1b5 \uacf5\uc5f0 = bi\u1ec3u di\u1ec5n truy\u1ec1n th\u1ed1ng.","\uc804\ud1b5 \uc74c\uc545 = \xe2m nh\u1ea1c truy\u1ec1n th\u1ed1ng.","\ubcf4\uc874\ud558\ub2e4 = b\u1ea3o t\u1ed3n.","\ubcf4\ud638\ud558\ub2e4 = b\u1ea3o v\u1ec7.","\ud6fc\uc190\ud558\ub2e4 = l\xe0m h\u01b0 h\u1ea1i.","\ubcf5\uc6d0\ud558\ub2e4 = ph\u1ee5c d\u1ef1ng / kh\xf4i ph\u1ee5c.","\uacc4\uc2b9\ud558\ub2e4 = k\u1ebf th\u1eeba.","\uc804\uc2b9\ud558\ub2e4 = l\u01b0u truy\u1ec1n.","\uac00\uce58 = gi\xe1 tr\u1ecb.","\uc5ed\uc0ac\uc801 \uac00\uce58 = gi\xe1 tr\u1ecb l\u1ecbch s\u1eed.","\uc0c1\uc9d5\ud558\ub2e4 = t\u01b0\u1ee3ng tr\u01b0ng.","\ub300\ud45c\ud558\ub2e4 = \u0111\u1ea1i di\u1ec7n / ti\xeau bi\u1ec3u.","\uc138\uacc4\ubb38\ud654\uc720\uc0b0 = di s\u1ea3n v\u0103n h\xf3a th\u1ebf gi\u1edbi.","\ub4f1\ub85d\ub418\ub2e4 = \u0111\u01b0\u1ee3c \u0111\u0103ng k\xfd / ghi danh.","\uad00\uad11 \uc790\uc6d0 = t\xe0i nguy\xean du l\u1ecbch.","\uc5bc\ub9c8\ub098 -\ub294\uc9c0 \ubaa8\ub974\ub2e4 = r\u1ea5t... / kh\xf4ng bi\u1ebft l\xe0... \u0111\u1ebfn m\u1ee9c n\xe0o.","\uc5bc\ub9c8\ub098 -(\uc73c)\u3134\uc9c0 \ubaa8\ub974\ub2e4 = nh\u1ea5n m\u1ea1nh m\u1ee9c \u0111\u1ed9 r\u1ea5t l\u1edbn c\u1ee7a t\xednh t\u1eeb.","-\ub4e0\uc9c0 = d\xf9... n\xe0o c\u0169ng / ho\u1eb7c... c\u0169ng \u0111\u01b0\u1ee3c.","(\uba85)\uc774\ub4e0\uc9c0 = d\xf9 l\xe0 danh t\u1eeb n\xe0o...","-\ub3c4\ub85d = \u0111\u1ec3 / sao cho...","-\uc544/\uc5b4 \uc624\ub2e4 = \u0111\xe3 ti\u1ebfp t\u1ee5c t\u1eeb qu\xe1 kh\u1ee9 cho \u0111\u1ebfn hi\u1ec7n t\u1ea1i.","\ubb38\ud654\uc720\uc0b0\uc740 \ud55c \uc0ac\ud68c\uc758 \uc5ed\uc0ac\uc640 \ubb38\ud654\ub97c \uc774\ud574\ud558\ub294 \ub370 \uc911\uc694\ud55c \uc790\ub8cc\uc785\ub2c8\ub2e4.","\uc720\ud615 \ubb38\ud654\uc720\uc0b0\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc804\ud1b5 \uc74c\uc545, \uae30\uc220, \uc758\uc2dd\uacfc \uac19\uc740 \ubb34\ud615 \ubb38\ud654\uc720\uc0b0\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4.","\ubb38\ud654\uc720\uc0b0\uc744 \uad00\uad11\uc5d0 \ud65c\uc6a9\ud558\ub354\ub77c\ub3c4 \ud6fc\uc190\ub418\uc9c0 \uc54a\ub3c4\ub85d \ubcf4\ud638\ud574\uc57c \ud569\ub2c8\ub2e4.","\ubb38\ud654\uc720\uc0b0\uc744 \ubcf4\uc874\ud558\uace0 \uacc4\uc2b9\ud558\ub294 \uac83\uc740 \ub2e4\uc74c \uc138\ub300\uc5d0 \uc5ed\uc0ac\uc640 \ubb38\ud654\ub97c \uc804\ub2ec\ud558\ub294 \uc911\uc694\ud55c \uc77c\uc785\ub2c8\ub2e4."],t.s)
A.Kr=new B.hG(5,"\ubb38\ud654\uc720\uc0b0","Di s\u1ea3n v\u0103n h\xf3a",A.fyQ,A.j4E,A.iqL,A.iNx,A.hWQ,A.fRd)
A.fWD=s(["\uc678\uad6d\uc778\uc774 \ud55c\uad6d\uc5d0\uc11c \uc0dd\ud65c\ud558\uba74\uc11c \uacaa\uc744 \uc218 \uc788\ub294 \ub2e4\uc591\ud55c \uc801\uc751 \ubb38\uc81c\ub97c \uc774\ud574\ud569\ub2c8\ub2e4.","\uc5b8\uc5b4, \uc74c\uc2dd, \uad50\ud1b5, \uc8fc\uac70, \uc9c1\uc7a5, \uc778\uac04\uad00\uacc4 \ub4f1 \ud55c\uad6d \uc0dd\ud65c\uc5d0\uc11c \uc790\uc8fc \uacaa\ub294 \uc5b4\ub824\uc6c0\uc744 \uc54c\uc544\ubd05\ub2c8\ub2e4.","\ud55c\uad6d \uc0dd\ud65c\uc5d0 \uc801\uc751\ud558\uae30 \uc704\ud574 \ud544\uc694\ud55c \uc815\ubcf4\uc640 \ub3c4\uc6c0\uc744 \uc5bb\ub294 \ubc29\ubc95\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\ud55c\uad6d\uc5b4 \uc2e4\ub825\uc774 \uc88b\uc544\uc9c8\uc218\ub85d \uc0dd\ud65c\uc774 \ud3b8\ub9ac\ud574\uc9c8 \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubb38\ud654 \ucc28\uc774\ub85c \uc778\ud574 \uc0dd\uae38 \uc218 \uc788\ub294 \uc624\ud574\uc640 \uac08\ub4f1\uc744 \uc904\uc774\ub294 \ubc29\ubc95\uc744 \uc54c\uc544\ubd05\ub2c8\ub2e4.","\uc5b4\ub824\uc6c0\uc774 \uc788\uc744 \ub54c \ud63c\uc790 \ud574\uacb0\ud558\ub824\uace0\ub9cc \ud558\uc9c0 \uc54a\uace0 \uc8fc\ubcc0 \uc0ac\ub78c\uc774\ub098 \uad00\ub828 \uae30\uad00\uc5d0 \ub3c4\uc6c0\uc744 \uc694\uccad\ud558\ub294 \ud0dc\ub3c4\ub97c \ubc30\uc6c1\ub2c8\ub2e4.","\ud55c\uad6d \uc0ac\ud68c\uc758 \uaddc\uce59\uacfc \uc0dd\ud65c \ubc29\uc2dd\uc744 \uc774\ud574\ud558\uba74\uc11c \uc790\uc2e0\uc758 \ubb38\ud654\ub3c4 \uc874\uc911\ud558\ub294 \ud0dc\ub3c4\ub97c \uae30\ub985\ub2c8\ub2e4.","\uc2dc\uac04\uc774 \uc9c0\ub098\uba74\uc11c \uc0c8\ub85c\uc6b4 \ud658\uacbd\uc5d0 \uc810\ucc28 \uc775\uc219\ud574\uc9c0\ub294 \uc801\uc751 \uacfc\uc815\uc744 \uc774\ud574\ud569\ub2c8\ub2e4."],t.s)
A.eZ1=new B.A("\uc801\uc751\ud558\ub2e4","th\xedch nghi","\ucc98\uc74c\uc5d0\ub294 \ud798\ub4e4\uc5c8\uc9c0\ub9cc \uc9c0\uae08\uc740 \ud55c\uad6d \uc0dd\ud65c\uc5d0 \ub9ce\uc774 \uc801\uc751\ud588\uc2b5\ub2c8\ub2e4.","Ban \u0111\u1ea7u r\u1ea5t kh\xf3 kh\u0103n nh\u01b0ng b\xe2y gi\u1edd t\xf4i \u0111\xe3 th\xedch nghi nhi\u1ec1u v\u1edbi cu\u1ed9c s\u1ed1ng \u1edf H\xe0n Qu\u1ed1c.")
A.eYS=new B.A("\uc801\uc751","s\u1ef1 th\xedch nghi","\uc0c8\ub85c\uc6b4 \ud658\uacbd\uc5d0 \uc801\uc751\ud558\ub294 \ub370 \uc2dc\uac04\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.","C\u1ea7n th\u1eddi gian \u0111\u1ec3 th\xedch nghi v\u1edbi m\xf4i tr\u01b0\u1eddng m\u1edbi.")
A.eVu=new B.A("\ud55c\uad6d \uc0dd\ud65c","cu\u1ed9c s\u1ed1ng \u1edf H\xe0n Qu\u1ed1c","\ud55c\uad6d \uc0dd\ud65c\uc744 \uc2dc\uc791\ud55c \uc9c0 \ubc8c\uc368 3\ub144\uc774 \ub418\uc5c8\uc2b5\ub2c8\ub2e4.","\u0110\xe3 3 n\u0103m k\u1ec3 t\u1eeb khi t\xf4i b\u1eaft \u0111\u1ea7u cu\u1ed9c s\u1ed1ng \u1edf H\xe0n Qu\u1ed1c.")
A.f_C=new B.A("\ubb38\ud654 \ucc28\uc774","kh\xe1c bi\u1ec7t v\u0103n h\xf3a","\ubb38\ud654 \ucc28\uc774 \ub54c\ubb38\uc5d0 \ucc98\uc74c\uc5d0\ub294 \uc774\ud574\ud558\uae30 \uc5b4\ub824\uc6b4 \uc77c\uc774 \ub9ce\uc558\uc2b5\ub2c8\ub2e4.","V\xec kh\xe1c bi\u1ec7t v\u0103n h\xf3a n\xean l\xfac \u0111\u1ea7u c\xf3 nhi\u1ec1u \u0111i\u1ec1u kh\xf3 hi\u1ec3u.")
A.eWl=new B.A("\ubb38\ud654 \ucda9\uaca9","s\u1ed1c v\u0103n h\xf3a","\ucc98\uc74c \ud55c\uad6d\uc5d0 \uc654\uc744 \ub54c \ubb38\ud654 \ucda9\uaca9\uc744 \uc870\uae08 \ubc1b\uc558\uc2b5\ub2c8\ub2e4.","Khi m\u1edbi \u0111\u1ebfn H\xe0n Qu\u1ed1c t\xf4i \u0111\xe3 h\u01a1i b\u1ecb s\u1ed1c v\u0103n h\xf3a.")
A.eZW=new B.A("\ub0af\uc124\ub2e4","xa l\u1ea1, kh\xf4ng quen","\ucc98\uc74c\uc5d0\ub294 \ud55c\uad6d \uc74c\uc2dd\uacfc \uc0dd\ud65c \ubc29\uc2dd\uc774 \ubaa8\ub450 \ub0af\uc124\uc5c8\uc2b5\ub2c8\ub2e4.","L\xfac \u0111\u1ea7u \u0111\u1ed3 \u0103n v\xe0 c\xe1ch sinh ho\u1ea1t \u1edf H\xe0n Qu\u1ed1c \u0111\u1ec1u r\u1ea5t xa l\u1ea1.")
