A.eM1=new B.aj("\ub2e4\uc74c \ub300\ud654\uc5d0 \ub4e4\uc5b4\uac08 \ud45c\ud604\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?\n\n\uac00: \uae30\uacc4 \uc0ac\uc6a9\ubc95\uc744 \uc815\ud655\ud788 \ubaa8\ub974\uaca0\uc5b4\uc694.\n\ub098: \uadf8\ub7ec\uba74 \uc544\ub294______ \ud558\uc9c0 \ub9d0\uace0 \ubc18\uc7a5\ub2d8\uaed8 \ub2e4\uc2dc \ubb3c\uc5b4\ubcf4\uc138\uc694.",A.fxi,0,'\uc2e4\uc81c\ub85c \ubaa8\ub974\uba74\uc11c \uc54c\uace0 \uc788\ub294 \uac83\ucc98\ub7fc \ud589\ub3d9\ud558\ub294 \uc758\ubbf8\uc774\ubbc0\ub85c "\uc544\ub294 \ucc99\ud558\ub2e4"\uac00 \uc54c\ub9de\uc2b5\ub2c8\ub2e4.')
A.i05=s(["\u2460 \uc5c8\ub354\ub2c8","\u2461 \ub290\ub77c\uace0","\u2462 \uce58\uace0","\u2463 \ucee4\ub155"],t.s)
A.eMZ=new B.aj("\ub2e4\uc74c \ub300\ud654\uc5d0 \ub4e4\uc5b4\uac08 \ud45c\ud604\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?\n\n\uac00: \ubab8\uc774 \ub9ce\uc774 \uc88b\uc544\uc84c\ub124\uc694.\n\ub098: \ub124. \uba70\uce60 \ud479 \uc26c______ \ud53c\ub85c\uac00 \ub9ce\uc774 \ud480\ub838\uc5b4\uc694.",A.i05,0,'\uc9c1\uc811 \ud734\uc2dd\uc744 \ucde8\ud55c \ub4a4 \ub098\ud0c0\ub09c \uacb0\uacfc\uc774\ubbc0\ub85c "-\uc558/\uc5c8\ub354\ub2c8"\uac00 \uc54c\ub9de\uc2b5\ub2c8\ub2e4.')
A.eLR=new B.aj("\ub2e4\uc74c \ub300\ud654\uc5d0 \ub4e4\uc5b4\uac08 \ud45c\ud604\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?\n\n\uac00: \uc0ac\uace0\uac00 \ud06c\uac8c \ub0ac\uc5b4\uc694?\n\ub098: \uc544\ub2c8\uc694. \ucc28\uac00 \uac11\uc790\uae30 \uba48\ucdb0\uc11c \ubd80\ub52a\ud790______ \ub2e4\ud589\ud788 \ud53c\ud588\uc5b4\uc694.",A.Lm,0,'\uc2e4\uc81c\ub85c \ubd80\ub52a\ud788\uc9c0\ub294 \uc54a\uc558\uc9c0\ub9cc \uac70\uc758 \uc0ac\uace0\uac00 \ub0a0 \uc0c1\ud669\uc774\uc5c8\uc73c\ubbc0\ub85c "-(\uc73c)\u3139 \ubed4\ud558\ub2e4"\uac00 \uc54c\ub9de\uc2b5\ub2c8\ub2e4.')
A.iK_=s(["\u2460 \uc8c4\uc1a1\ud558\uc9c0\ub9cc \uc791\uc5c5 \uc21c\uc11c\ub97c \ub2e4\uc2dc \ud55c\ubc88 \ud655\uc778\ud574\ub3c4 \ub420\uae4c\uc694?","\u2461 \uc798 \ubaa8\ub974\uc9c0\ub9cc \uadf8\ub0e5 \ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4.","\u2462 \ubb3c\uc5b4\ubcf4\uc9c0 \uc54a\uace0 \uc81c\uac00 \uc6d0\ud558\ub294 \ubc29\ubc95\uc73c\ub85c \ud558\uaca0\uc2b5\ub2c8\ub2e4.","\u2463 \uc544\ub294 \ucc99\ud558\uace0 \uc791\uc5c5\ud558\uaca0\uc2b5\ub2c8\ub2e4."],t.s)
A.eN3=new B.aj("\ub2e4\uc74c \uc0c1\ud669\uc5d0\uc11c \uac00\uc7a5 \uc801\uc808\ud55c \ub9d0\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\uc0c1\uc0ac\uc758 \uc124\uba85\uc744 \ub4e4\uc5c8\uc9c0\ub9cc \uc791\uc5c5 \uc21c\uc11c\ub97c \uc815\ud655\ud558\uac8c \uc774\ud574\ud558\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4.",A.iK_,0,"\uc791\uc5c5 \ub0b4\uc6a9\uc744 \uc815\ud655\ud788 \uc774\ud574\ud558\uc9c0 \ubabb\ud588\uc744 \ub54c\ub294 \uc815\uc911\ud558\uac8c \ub2e4\uc2dc \ud655\uc778\ud558\ub294 \uac83\uc774 \uac00\uc7a5 \uc548\uc804\ud558\uace0 \uc801\uc808\ud569\ub2c8\ub2e4.")
A.iY8=s(["\u2460 \uacf5\uc2dd \uc548\ub0b4\uc640 \ub2f4\ub2f9 \uae30\uad00\uc758 \ucd5c\uc2e0 \uc815\ubcf4\ub97c \ud655\uc778\ud55c\ub2e4","\u2461 \uac00\uc7a5 \uc624\ub798\ub41c \uae00\uc744 \uc120\ud0dd\ud55c\ub2e4","\u2462 \uc544\ubb34 \uae00\uc774\ub098 \ud558\ub098 \ubbff\ub294\ub2e4","\u2463 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uccb4\ub958 \uc790\uaca9\uacfc \uc790\uc2e0\uc758 \uc0c1\ud669\uc774 \uac19\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4"],t.s)
A.eOi=new B.aj("\ub2e4\uc74c \uc0c1\ud669\uc5d0\uc11c \uac00\uc7a5 \uc801\uc808\ud55c \ud589\ub3d9\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\uccb4\ub958\uc640 \uad00\ub828\ub41c \uc11c\ub958\ub97c \uc900\ube44\ud558\ub824\ub294\ub370 \uc778\ud130\ub137 \uae00\ub9c8\ub2e4 \ud544\uc694\ud55c \uc11c\ub958\uac00 \ub2e4\ub974\uac8c \uc801\ud600 \uc788\uc2b5\ub2c8\ub2e4.",A.iY8,0,"\uccb4\ub958\uc640 \ud589\uc815 \uc808\ucc28\ub294 \uac1c\uc778\uc758 \uc0c1\ud669\uacfc \uc2dc\uae30\uc5d0 \ub530\ub77c \ub2e4\ub97c \uc218 \uc788\uc73c\ubbc0\ub85c \uacf5\uc2dd\uc801\uc778 \ucd5c\uc2e0 \uc815\ubcf4\ub97c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.")
A.iM5=s(["\u2460 \ubc95\uacfc \uaddc\uce59\uc744 \uc9c0\ud0a4\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uad8c\ub9ac\ub97c \uc874\uc911\ud558\uba70 \ud544\uc694\ud55c \uc815\ubcf4\ub294 \uc815\ud655\ud558\uac8c \ud655\uc778\ud55c\ub2e4","\u2461 \uc790\uc2e0\uc5d0\uac8c \ud3b8\ub9ac\ud55c \uaddc\uce59\ub9cc \uc9c0\ud0a8\ub2e4","\u2462 \ub2e4\ub978 \uc0ac\ub78c\uc758 \ubb38\ud654\uc640 \uc758\uacac\uc740 \ubb34\uc2dc\ud55c\ub2e4","\u2463 \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \uc815\ubcf4\ub3c4 \ubc14\ub85c \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc804\ub2ec\ud55c\ub2e4"],t.s)
A.eP7=new B.aj("\ub2e4\uc74c \uc911 \ud55c\uad6d \uc0ac\ud68c\uc5d0\uc11c \ucc45\uc784 \uc788\uac8c \uc0dd\ud65c\ud558\ub294 \ud0dc\ub3c4\ub97c \uac00\uc7a5 \uc798 \uc124\uba85\ud55c \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.iM5,0,"\uc548\uc815\uc801\uc778 \uc0ac\ud68c\uc0dd\ud65c\uc744 \uc704\ud574\uc11c\ub294 \uaddc\uce59 \uc900\uc218, \ud0c0\uc778 \uc874\uc911, \uc815\ud655\ud55c \uc815\ubcf4 \ud655\uc778\uacfc \ucc45\uc784 \uc788\ub294 \ud589\ub3d9\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.iFg=s(["\u2460 \ud55c\uad6d \uc0ac\ud68c\uc758 \uc0dd\ud65c\xb7\ubb38\ud654\xb7\uc81c\ub3c4\ub97c \uc774\ud574\ud558\uace0 \uc2e4\uc81c \uc0c1\ud669\uc5d0\uc11c \uc801\uc808\ud558\uac8c \uc758\uc0ac\uc18c\ud1b5\ud558\uace0 \ud589\ub3d9\ud558\ub294 \ub2a5\ub825\uc744 \uae30\ub978\ub2e4","\u2461 \ubb38\ubc95 \ud615\ud0dc\ub9cc \uc678\uc6b0\uba74 \ub41c\ub2e4","\u2462 \uc2e4\uc81c \ud55c\uad6d \uc0dd\ud65c\uacfc\ub294 \uad00\uacc4\uc5c6\uc774 \ub2e8\uc5b4\ub9cc \uc554\uae30\ud55c\ub2e4","\u2463 \ud55c \uac00\uc9c0 \uc8fc\uc81c\ub9cc \uacf5\ubd80\ud558\uba74 \ub41c\ub2e4"],t.s)
A.ePC=new B.aj("\ub2e4\uc74c \uc911 KIIP 4\uc758 \uc804\uccb4 \ud559\uc2b5 \ubc29\ud5a5\uc744 \uac00\uc7a5 \uc798 \uc124\uba85\ud55c \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.iFg,0,"KIIP \ud559\uc2b5\uc5d0\uc11c\ub294 \uc5b8\uc5b4\ubfd0\ub9cc \uc544\ub2c8\ub77c \ud55c\uad6d \uc0ac\ud68c\uc758 \uc0dd\ud65c, \ubb38\ud654, \uc81c\ub3c4 \ub4f1\uc744 \uc774\ud574\ud558\uace0 \uc2e4\uc81c \uc0c1\ud669\uc5d0\uc11c \ud65c\uc6a9\ud558\ub294 \ub2a5\ub825\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.hN1=s([A.eOD,A.eQ3,A.eM2,A.eOm,A.eMt,A.ePF,A.eMV,A.eOd,A.eOH,A.eNo,A.ePp,A.eMp,A.eMx,A.eOQ,A.eNS,A.ePt,A.eNV,A.eLW,A.eN1,A.eOV,A.eN0,A.eOK,A.eNe,A.eO_,A.eLK,A.eO8,A.eN8,A.eOX,A.eMF,A.eOh,A.ePi,A.eOL,A.eOI,A.eP8,A.eNK,A.eN6,A.eM1,A.eMZ,A.eLR,A.eN3,A.eOi,A.eP7,A.ePC],t.Fo)
A.fLu=s(["1\uacfc \ud55c\uad6d \uc0dd\ud65c \uc801\uc751: \uc0c8\ub85c\uc6b4 \ud658\uacbd\uc758 \uc5b8\uc5b4\uc640 \ubb38\ud654\uc5d0 \uc801\uc751\ud558\ub294 \ubc29\ubc95\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","2\uacfc \uac00\uc871\uc758 \ubcc0\ud654: \ud604\ub300 \uc0ac\ud68c\uc758 \ub2e4\uc591\ud55c \uac00\uc871 \ud615\ud0dc\uc640 \uc5ed\ud560 \ubcc0\ud654\ub97c \uc774\ud574\ud569\ub2c8\ub2e4.","3\uacfc \uc0dd\ud65c \uc18d\uc758 \uacfc\ud559: \uacfc\ud559 \uae30\uc220\uacfc \uc77c\uc0c1\uc0dd\ud65c\uc758 \uad00\uacc4\ub97c \uc774\ud574\ud569\ub2c8\ub2e4.","4\uacfc \ud55c\uad6d\uc758 \uc758\ub840: \uacb0\ud63c\uc2dd, \uc7a5\ub840\uc2dd \ub4f1 \ud55c\uad6d\uc758 \uc8fc\uc694 \uc758\ub840\uc640 \uc608\uc808\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","5\uacfc \ubb38\ud654\uc720\uc0b0: \ubb38\ud654\uc720\uc0b0\uc758 \uac00\uce58\uc640 \ubcf4\uc874\uc758 \ud544\uc694\uc131\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","6\uacfc \uad6d\uc81c\ud654 \uc2dc\ub300: \uad6d\uc81c\ud654\uc640 \ub2e4\ubb38\ud654 \uc0ac\ud68c\uc5d0\uc11c \ud544\uc694\ud55c \ud0dc\ub3c4\ub97c \uc774\ud574\ud569\ub2c8\ub2e4.","7\uacfc \ud604\ub300\uc778\uc758 \uc9c8\ubcd1: \uac74\uac15\ud55c \uc0dd\ud65c \uc2b5\uad00\uacfc \uc9c8\ubcd1 \uc608\ubc29\uc758 \uc911\uc694\uc131\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","8\uacfc \uc815\ubcf4\ud654 \uc0ac\ud68c: \uc815\ubcf4 \ud65c\uc6a9\uacfc \uac1c\uc778\uc815\ubcf4 \ubcf4\ud638\uc758 \uc911\uc694\uc131\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","9\uacfc \uc0ac\uac74\uacfc \uc0ac\uace0: \uc0ac\uace0 \uc608\ubc29, \uc548\uc804, \uae34\uae09 \uc2e0\uace0\uc640 \uc801\uc808\ud55c \ub300\uc751 \ubc29\ubc95\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","10\uacfc \uc5b8\uc5b4\uc0dd\ud65c: \uc0c1\ud669\uacfc \uad00\uacc4\uc5d0 \ub9de\ub294 \ub9d0\ud22c, \ud638\uce6d, \uc815\ud655\ud55c \uc758\uc0ac\uc18c\ud1b5\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","11\uacfc \uad50\uc721 \uc81c\ub3c4: \ud55c\uad6d\uc758 \uad50\uc721\uacfc \ud559\uad50\uc0dd\ud65c, \uc9c4\ub85c\uc5d0 \uad00\ud55c \uae30\ubcf8 \ub0b4\uc6a9\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","12\uacfc \uc120\uac70\uc640 \ud22c\ud45c: \uc120\uac70, \ud22c\ud45c, \uc0ac\ud68c \ucc38\uc5ec\uc758 \uc758\ubbf8\ub97c \uc774\ud574\ud569\ub2c8\ub2e4.","13\uacfc \ud658\uacbd \ubcf4\ud638: \ubd84\ub9ac\ubc30\ucd9c, \uc7ac\ud65c\uc6a9, \uc5d0\ub108\uc9c0 \uc808\uc57d \ub4f1 \ud658\uacbd \ubcf4\ud638 \ubc29\ubc95\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","14\uacfc \uc0dd\ud65c\uacfc \uacbd\uc81c: \uc18c\ub4dd, \uc9c0\ucd9c, \uc800\ucd95\uacfc \uacc4\ud68d\uc801\uc778 \uc18c\ube44\ub97c \uc774\ud574\ud569\ub2c8\ub2e4.","15\uacfc \ubc95\uacfc \uc9c8\uc11c: \uad8c\ub9ac\uc640 \uc758\ubb34, \ubc95\uacfc \uaddc\uce59\uc758 \uc911\uc694\uc131\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","16\uacfc \uc774\ubbfc \uc0dd\ud65c: \uccb4\ub958, \ud589\uc815, \uc9c1\uc7a5, \uc9c0\uc5ed\uc0ac\ud68c \ub4f1 \uc774\ubbfc \uc0dd\ud65c\uc5d0 \ud544\uc694\ud55c \uae30\ubcf8 \ud0dc\ub3c4\ub97c \uc774\ud574\ud569\ub2c8\ub2e4.","-\ub290\ub77c\uace0 = v\xec m\u1ea3i... n\xean...","-(\uc73c)\u3139\uc218\ub85d = c\xe0ng... c\xe0ng...","-(\uc73c)\u3139 \ubfd0\ub9cc \uc544\ub2c8\ub77c = kh\xf4ng ch\u1ec9... m\xe0 c\xf2n...",u.W,"-\ub294 \uc904 \uc54c\ub2e4 = t\u01b0\u1edfng r\u1eb1ng...","-\uace4 \ud558\ub2e4 = th\u01b0\u1eddng hay...","-\ub354\ub2c8 = r\u1ed3i th\xec / th\u1ea5y r\u1eb1ng...","-(\uc73c)\u3134 \ub098\uba38\uc9c0 = v\xec qu\xe1... n\xean...","-\ub4e0\uc9c0 = d\xf9 / b\u1ea5t c\u1ee9...","-\ub358 = \u0111\xe3 t\u1eebng / \u0111ang... trong qu\xe1 kh\u1ee9.","-\ub418 = nh\u01b0ng / v\u1edbi \u0111i\u1ec1u ki\u1ec7n...","-\uc558/\uc5c8\ub354\ub2c8 = sau khi t\xf4i... th\xec...","-\ub294\ub2e4\uba74\uc11c\uc694? = nghe n\xf3i... ph\u1ea3i kh\xf4ng?","-(\uc73c)\u3139 \uacb8 -(\uc73c)\u3139 \uacb8 = v\u1eeba \u0111\u1ec3... v\u1eeba \u0111\u1ec3...","-(\uc73c)\u3139 \ubed4\ud558\ub2e4 = su\xfdt n\u1eefa...","-(\uc73c)\ub85c \uc778\ud574 = do / b\u1edfi v\xec...","-\uace0 \ub9d0\ub2e4 = cu\u1ed1i c\xf9ng / r\u1ed1t cu\u1ed9c...","-\ub294/-(\uc73c)\u3134 \ucc99\ud558\ub2e4 = gi\u1ea3 v\u1edd...","(\uba85)\uc870\ucc28 = ngay c\u1ea3...","-\uae30 \ub9c8\ub828\uc774\ub2e4 = v\u1ed1n d\u0129 th\u01b0\u1eddng...","-\ub098 \ubcf4\ub2e4 / -(\uc73c)\u3134\uac00 \ubcf4\ub2e4 = c\xf3 v\u1ebb / h\xecnh nh\u01b0...","(\uba85)\uc774\uc57c\ub9d0\ub85c = ch\xednh... m\u1edbi l\xe0...","-\uc9c0 \uc54a\ub294 \ud55c = n\u1ebfu kh\xf4ng / tr\u1eeb khi...","-\ub3c4\ub85d = \u0111\u1ec3 / sao cho...","-(\uc73c)\ubbc0\ub85c = v\xec / do...",u.kU,"-\ub2e4\uc2dc\ud53c = nh\u01b0 \u0111\xe3 bi\u1ebft / nh\u01b0 \u0111\xe3 th\u1ea5y...","-\ub294 \ubc95\uc774\ub2e4 = v\u1ed1n d\u0129 / th\u01b0\u1eddng l\xe0...","-(\uc73c)\u3139\uc9c0\ub3c4 \ubaa8\ub974\ub2e4 = c\xf3 th\u1ec3 / bi\u1ebft \u0111\xe2u...","(\uba85)\uce58\uace0 = x\xe9t trong / trong s\u1ed1...","\uc2dc\ud5d8\uc5d0\uc11c\ub294 \ubb38\uc81c\uc758 \uc77c\ubd80 \ub2e8\uc5b4\ub9cc \ubcf4\uace0 \ubc14\ub85c \ub2f5\uc744 \uace0\ub974\uc9c0 \ub9d0\uace0 \ubb38\uc7a5\uacfc \uc0c1\ud669 \uc804\uccb4\ub97c \uc77d\uc5b4\uc57c \ud569\ub2c8\ub2e4.","\ubb38\ubc95\uc740 \ud615\ud0dc\uc640 \ub73b\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \uc0c1\ud669\uc5d0\uc11c \uc0ac\uc6a9\ud558\ub294\uc9c0 \ud568\uaed8 \uae30\uc5b5\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc5b4\ud718\ub294 \ud55c\uad6d \uc0dd\ud65c\uc758 \uc2e4\uc81c \uc7a5\uba74\uacfc \uc5f0\uacb0\ud574\uc11c \uae30\uc5b5\ud558\uba74 \ub354 \uc624\ub798 \uae30\uc5b5\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc9c1\uc7a5\uc5d0\uc11c\ub294 \uc791\uc5c5 \uc9c0\uc2dc\ub97c \uc815\ud655\ud558\uac8c \uc774\ud574\ud558\uace0 \ubaa8\ub974\ub294 \ub0b4\uc6a9\uc740 \ubc18\ub4dc\uc2dc \ub2e4\uc2dc \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\uc0ac\uace0\uc640 \uae34\uae09 \uc0c1\ud669\uc5d0\uc11c\ub294 \uc790\uc2e0\uc758 \uc548\uc804\uc744 \uc6b0\uc120 \ud655\uc778\ud558\uace0 \ud544\uc694\ud55c \uae30\uad00\uc5d0 \uc2e0\uace0\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc778\ud130\ub137 \uc815\ubcf4\ub294 \ucd9c\ucc98\uc640 \ub0a0\uc9dc\ub97c \ud655\uc778\ud558\uace0 \uac1c\uc778\uc815\ubcf4\ub97c \uc548\uc804\ud558\uac8c \uad00\ub9ac\ud574\uc57c \ud569\ub2c8\ub2e4.","\ud589\uc815\uacfc \uccb4\ub958 \uad00\ub828 \uc815\ubcf4\ub294 \ubcc0\uacbd\ub420 \uc218 \uc788\uc73c\ubbc0\ub85c \uc911\uc694\ud55c \uc0ac\ud56d\uc740 \uacf5\uc2dd\uc801\uc778 \ucd5c\uc2e0 \uc548\ub0b4\ub97c \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\ubaa8\uc758\uace0\uc0ac\uc5d0\uc11c \ud2c0\ub9b0 \ubb38\uc81c\ub294 \uc815\ub2f5\ub9cc \uc678\uc6b0\uc9c0 \ub9d0\uace0 \ud2c0\ub9b0 \uc774\uc720\uc640 \uad00\ub828 \ub2e8\uc6d0\uc744 \ub2e4\uc2dc \ubcf5\uc2b5\ud574\uc57c \ud569\ub2c8\ub2e4.","KIIP 4\uc758 \ubaa9\ud45c\ub294 \ud55c\uad6d\uc5b4 \ubb38\ubc95\ub9cc \ubc30\uc6b0\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ud55c\uad6d \uc0ac\ud68c\ub97c \uc774\ud574\ud558\uace0 \uc2e4\uc81c \uc0dd\ud65c\uc5d0\uc11c \uc801\uc808\ud558\uac8c \ud589\ub3d9\ud558\uace0 \uc758\uc0ac\uc18c\ud1b5\ud558\ub294 \ub2a5\ub825\uc744 \uae30\ub974\ub294 \uac83\uc785\ub2c8\ub2e4."],t.s)
