A.j3A=s(["\uc758\ub840 = nghi l\u1ec5 / nghi th\u1ee9c.","\uc804\ud1b5 = truy\u1ec1n th\u1ed1ng.","\uad00\uc2b5 = phong t\u1ee5c, t\u1eadp qu\xe1n.","\uc608\uc808 = l\u1ec5 nghi, ph\xe9p l\u1ecbch s\u1ef1.","\ucd9c\uc0dd = s\u1ef1 ra \u0111\u1eddi.","\ub3cc = sinh nh\u1eadt m\u1ed9t tu\u1ed5i.","\ub3cc\uc794\uce58 = ti\u1ec7c th\xf4i n\xf4i.","\ub3cc\uc7a1\uc774 = nghi th\u1ee9c em b\xe9 ch\u1ecdn \u0111\u1ed3 trong ti\u1ec7c th\xf4i n\xf4i.","\uacb0\ud63c\uc2dd = l\u1ec5 c\u01b0\u1edbi.","\uc2e0\ub791 = ch\xfa r\u1ec3.","\uc2e0\ubd80 = c\xf4 d\xe2u.","\ud558\uac1d = kh\xe1ch d\u1ef1 \u0111\xe1m c\u01b0\u1edbi.","\ucd95\uc758\uae08 = ti\u1ec1n m\u1eebng c\u01b0\u1edbi.","\uc7a5\ub840\uc2dd = l\u1ec5 tang.","\uc7a5\ub840\uc2dd\uc7a5 = nh\xe0 tang l\u1ec5.","\uc870\ubb38\ud558\ub2e4 = \u0111i vi\u1ebfng v\xe0 chia bu\u1ed3n.","\uc870\uc758\uae08 = ti\u1ec1n ph\xfang vi\u1ebfng.","\uc0c1\uc8fc = ng\u01b0\u1eddi ch\u1ee7 tang.","\uc560\ub3c4\ud558\ub2e4 = t\u01b0\u1edfng ni\u1ec7m / chia bu\u1ed3n.","\uace0\uc778 = ng\u01b0\u1eddi \u0111\xe3 khu\u1ea5t.","\uba85\ubcf5\uc744 \ube4c\ub2e4 = c\u1ea7u mong ng\u01b0\u1eddi \u0111\xe3 khu\u1ea5t \u0111\u01b0\u1ee3c y\xean ngh\u1ec9.","\uc81c\uc0ac\ub97c \uc9c0\ub0b4\ub2e4 = l\xe0m l\u1ec5 c\xfang t\u1ed5 ti\xean.","\uac04\uc18c\ud654\ud558\ub2e4 = \u0111\u01a1n gi\u1ea3n h\xf3a.","-\ub354\ub2c8 = \u0111\xe3... r\u1ed3i sau \u0111\xf3 / d\u1ef1a tr\xean \u0111i\u1ec1u \u0111\xe3 tr\u1ef1c ti\u1ebfp quan s\xe1t ho\u1eb7c tr\u1ea3i nghi\u1ec7m.","-\uc558/\uc5c8\ub354\ub2c8 = sau khi t\xf4i l\xe0m... th\xec ph\xe1t hi\u1ec7n/k\u1ebft qu\u1ea3...","-(\uc73c)\u3134 \ub098\uba38\uc9c0 = v\xec qu\xe1... \u0111\u1ebfn m\u1ee9c...","-\ub294 \ubc14\ub78c\uc5d0 = v\xec m\u1ed9t vi\u1ec7c b\u1ea5t ng\u1edd n\xean d\u1eabn \u0111\u1ebfn k\u1ebft qu\u1ea3 th\u01b0\u1eddng kh\xf4ng thu\u1eadn l\u1ee3i.","-\uae30 \uc804\uc5d0 = tr\u01b0\u1edbc khi...","-\ub294 \uac83\uc774 \uc88b\ub2e4 = n\xean...","\uacb0\ud63c\uc2dd\uc5d0\uc11c\ub294 \ucd95\ud558\uc758 \ub9c8\uc74c\uc744 \ud45c\ud604\ud558\uace0 \uae30\ubcf8\uc801\uc778 \uc608\uc808\uc744 \uc9c0\ud0a4\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\uc7a5\ub840\uc2dd\uc5d0\uc11c\ub294 \uace0\uc778\uc744 \uc560\ub3c4\ud558\uace0 \uc720\uac00\uc871\uc744 \ubc30\ub824\ud558\ub294 \ud0dc\ub3c4\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.","\ud55c\uad6d\uc758 \uc804\ud1b5 \uc758\ub840\ub294 \uc2dc\ub300\uc758 \ubcc0\ud654\uc5d0 \ub530\ub77c \ud615\uc2dd\uc774 \ub2ec\ub77c\uc9c0\uace0 \uac04\uc18c\ud654\ub418\uae30\ub3c4 \ud569\ub2c8\ub2e4.","\ub098\ub77c\ub9c8\ub2e4 \uc758\ub840\uc758 \ubc29\uc2dd\uc740 \ub2e4\ub97c \uc218 \uc788\uc73c\ubbc0\ub85c \uc11c\ub85c\uc758 \ubb38\ud654\ub97c \uc874\uc911\ud558\ub294 \ud0dc\ub3c4\uac00 \ud544\uc694\ud569\ub2c8\ub2e4."],t.s)
A.Kv=new B.hG(4,"\ud55c\uad6d\uc758 \uc758\ub840","C\xe1c nghi l\u1ec5 c\u1ee7a H\xe0n Qu\u1ed1c",A.hrH,A.hCM,A.htR,A.izm,A.iCm,A.j3A)
A.iBf=s(["9\uacfc\ubd80\ud130 16\uacfc\uae4c\uc9c0 \ubc30\uc6b4 \ud575\uc2ec \ub0b4\uc6a9\uc744 \uc885\ud569\uc801\uc73c\ub85c \ubcf5\uc2b5\ud569\ub2c8\ub2e4.","\uc0ac\uac74\uacfc \uc0ac\uace0, \uc5b8\uc5b4\uc0dd\ud65c, \uad50\uc721 \uc81c\ub3c4, \uc120\uac70\uc640 \ud22c\ud45c\uc758 \uc8fc\uc694 \ub0b4\uc6a9\uc744 \ub2e4\uc2dc \uc815\ub9ac\ud569\ub2c8\ub2e4.","\ud658\uacbd \ubcf4\ud638, \uc0dd\ud65c\uacfc \uacbd\uc81c, \ubc95\uacfc \uc9c8\uc11c, \uc774\ubbfc \uc0dd\ud65c\uc758 \ud575\uc2ec \uc5b4\ud718\ub97c \ubcf5\uc2b5\ud569\ub2c8\ub2e4.","\uac01 \ub2e8\uc6d0\uc5d0\uc11c \ubc30\uc6b4 \uc8fc\uc694 \ubb38\ubc95\uc744 \uc2e4\uc81c \uc0dd\ud65c \ubb38\uc7a5 \uc18d\uc5d0\uc11c \ub2e4\uc2dc \ud655\uc778\ud569\ub2c8\ub2e4.","\uc0ac\uace0 \uc2e0\uace0, \uc9c1\uc7a5 \uc758\uc0ac\uc18c\ud1b5, \ud559\uad50\uc0dd\ud65c, \uacbd\uc81c\uc0dd\ud65c, \ud589\uc815 \uc5c5\ubb34 \ub4f1 \uc2e4\uc81c \uc0c1\ud669\uacfc \uc5f0\uacb0\ud558\uc5ec \ubcf5\uc2b5\ud569\ub2c8\ub2e4.","\ube44\uc2b7\ud574 \ubcf4\uc774\ub294 \ubb38\ubc95\uc758 \uc758\ubbf8\uc640 \uc0ac\uc6a9 \uc0c1\ud669\uc744 \uad6c\ubcc4\ud558\ub294 \uc5f0\uc2b5\uc744 \ud569\ub2c8\ub2e4.","KIIP \uc2dc\ud5d8\uc5d0\uc11c \ub098\uc62c \uc218 \uc788\ub294 \uc5b4\ud718, \ubb38\ubc95, \uc0c1\ud669 \ud310\ub2e8 \ubb38\uc81c\ub97c \uc885\ud569\uc801\uc73c\ub85c \uc5f0\uc2b5\ud569\ub2c8\ub2e4.","\ud55c\uad6d \uc0ac\ud68c\uc5d0\uc11c \uc548\uc804\ud558\uace0 \ucc45\uc784 \uc788\uac8c \uc0dd\ud65c\ud558\uae30 \uc704\ud574 \ud544\uc694\ud55c \ud0dc\ub3c4\uc640 \uc815\ubcf4\ub97c \ub2e4\uc2dc \ud655\uc778\ud569\ub2c8\ub2e4."],t.s)
