A.hEL=s(["\uc0ac\uac74 = s\u1ef1 vi\u1ec7c / v\u1ee5 vi\u1ec7c.","\uc0ac\uace0 = tai n\u1ea1n / s\u1ef1 c\u1ed1.","\uad50\ud1b5\uc0ac\uace0 = tai n\u1ea1n giao th\xf4ng.","\ud654\uc7ac = h\u1ecfa ho\u1ea1n.","\uc0b0\uc5c5\uc7ac\ud574 = tai n\u1ea1n lao \u0111\u1ed9ng.","\ubd84\uc2e4 = th\u1ea5t l\u1ea1c.","\ub3c4\ub09c = tr\u1ed9m c\u1eafp.","\ud53c\ud574 = thi\u1ec7t h\u1ea1i.","\ud53c\ud574\uc790 = n\u1ea1n nh\xe2n.","\uac00\ud574\uc790 = ng\u01b0\u1eddi g\xe2y h\u1ea1i / ng\u01b0\u1eddi g\xe2y tai n\u1ea1n.","\uc2e0\uace0\ud558\ub2e4 = tr\xecnh b\xe1o.","\uacbd\ucc30\uc11c = \u0111\u1ed3n c\u1ea3nh s\xe1t.","\uc18c\ubc29\uc11c = tr\u1ea1m c\u1ee9u h\u1ecfa.","\uc751\uae09 \uc0c1\ud669 = t\xecnh hu\u1ed1ng kh\u1ea9n c\u1ea5p.","\uad6c\uc870\ud558\ub2e4 = c\u1ee9u h\u1ed9.","\uc751\uae09 \ucc98\uce58 = s\u01a1 c\u1ee9u.","\ub300\ud53c\ud558\ub2e4 = s\u01a1 t\xe1n.","\ud604\uc7a5 = hi\u1ec7n tr\u01b0\u1eddng.","\ubaa9\uaca9\uc790 = nh\xe2n ch\u1ee9ng.","\uc99d\uac70 = b\u1eb1ng ch\u1ee9ng.","\uae30\ub85d\ud558\ub2e4 = ghi l\u1ea1i.","\ubcf4\ud5d8\ud68c\uc0ac = c\xf4ng ty b\u1ea3o hi\u1ec3m.","\uc548\uc804 \uc218\uce59 = quy t\u1eafc an to\xe0n.","\uc548\uc804\uc7a5\ube44 = thi\u1ebft b\u1ecb b\u1ea3o h\u1ed9.","\ubcf4\ud638\uad6c = \u0111\u1ed3 b\u1ea3o h\u1ed9.","\ubbf8\ub044\ub7fd\ub2e4 = tr\u01a1n tr\u01b0\u1ee3t.","-(\uc73c)\u3139 \ubed4\ud558\ub2e4 = su\xfdt n\u1eefa th\xec...","-(\uc73c)\ub85c \uc778\ud574 = do / b\u1edfi v\xec...","-\ub294 \ubc14\ub78c\uc5d0 = v\xec m\u1ed9t t\xecnh hu\u1ed1ng b\u1ea5t ng\u1edd n\xean...","-\uc790\ub9c8\uc790 = ngay sau khi...","-\uc9c0 \uc54a\ub3c4\ub85d = \u0111\u1ec3 kh\xf4ng...","-\uc544/\uc5b4\uc57c \ud558\ub2e4 = ph\u1ea3i...","\uad50\ud1b5\uc0ac\uace0, \ud654\uc7ac, \uc0b0\uc5c5\uc7ac\ud574 \ub4f1 \uc0ac\uace0\uac00 \ubc1c\uc0dd\ud588\uc744 \ub54c\ub294 \uba3c\uc800 \uc548\uc804\uc744 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.","\ud654\uc7ac\xb7\uad6c\uc870\xb7\uad6c\uae09\uc774 \ud544\uc694\ud55c \uae34\uae09 \uc0c1\ud669\uc5d0\uc11c\ub294 119, \uae34\uae09\ud55c \uacbd\ucc30 \ub3c4\uc6c0\uc774 \ud544\uc694\ud55c \uacbd\uc6b0\uc5d0\ub294 112\uc5d0 \uc2e0\uace0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc0ac\uace0\ub97c \uc2e0\uace0\ud560 \ub54c\ub294 \uc7a5\uc18c, \uc0ac\uace0 \uc0c1\ud669, \ub2e4\uce5c \uc0ac\ub78c\uc758 \uc0c1\ud0dc \ub4f1\uc744 \uac00\ub2a5\ud55c \uc815\ud655\ud558\uac8c \uc124\uba85\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\uc9c1\uc7a5\uc5d0\uc11c\ub294 \uc548\uc804\uc7a5\ube44\ub97c \ucc29\uc6a9\ud558\uace0 \uc791\uc5c5 \uc218\uce59\uc744 \uc9c0\ud0a4\ub294 \uac83\uc774 \uc0b0\uc5c5\uc7ac\ud574 \uc608\ubc29\uc5d0 \uc911\uc694\ud569\ub2c8\ub2e4.","\uc0ac\uace0\uac00 \ubc1c\uc0dd\ud55c \ud6c4\uc758 \ucc98\ub9ac\ub3c4 \uc911\uc694\ud558\uc9c0\ub9cc \uc0ac\uace0\uac00 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub3c4\ub85d \ubbf8\ub9ac \uc608\ubc29\ud558\ub294 \uac83\uc774 \uac00\uc7a5 \uc911\uc694\ud569\ub2c8\ub2e4."],t.s)
A.Ky=new B.hG(9,"\uc0ac\uac74\uacfc \uc0ac\uace0","S\u1ef1 c\u1ed1 v\xe0 tai n\u1ea1n",A.hKZ,A.iW2,A.fQW,A.fKJ,A.ilF,A.hEL)
A.fBV=s(["\uc6b0\ub9ac\uc758 \uc77c\uc0c1\uc0dd\ud65c \uc18d\uc5d0\uc11c \uacfc\ud559 \uae30\uc220\uc774 \uc5b4\ub5bb\uac8c \ud65c\uc6a9\ub418\uace0 \uc788\ub294\uc9c0 \uc774\ud574\ud569\ub2c8\ub2e4.","\uac00\uc804\uc81c\ud488, \uc2a4\ub9c8\ud2b8\ud3f0, \uad50\ud1b5, \uc758\ub8cc, \uc8fc\uac70 \ub4f1 \uc0dd\ud65c \uc18d \uacfc\ud559\uc758 \ub2e4\uc591\ud55c \uc0ac\ub840\ub97c \uc54c\uc544\ubd05\ub2c8\ub2e4.","\uacfc\ud559 \uae30\uc220\uc758 \ubc1c\ub2ec\uc774 \uc0dd\ud65c\uc744 \ub354 \ud3b8\ub9ac\ud558\uace0 \uc548\uc804\ud558\uac8c \ub9cc\ub4e0\ub2e4\ub294 \uc810\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\uae30\uc220\uc744 \uc0ac\uc6a9\ud560 \ub54c \ud3b8\ub9ac\ud568\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc548\uc804\uacfc \uc62c\ubc14\ub978 \uc0ac\uc6a9 \ubc29\ubc95\ub3c4 \uc911\uc694\ud558\ub2e4\ub294 \uc810\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uc0c8\ub85c\uc6b4 \uae30\uc220\uc774 \ub4f1\uc7a5\ud558\uba74\uc11c \uc6b0\ub9ac\uc758 \uc0dd\ud65c \ubc29\uc2dd\uacfc \uc758\uc0ac\uc18c\ud1b5 \ubc29\ubc95\uc774 \ubcc0\ud654\ud558\uace0 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\uacfc\ud559 \uae30\uc220\uc758 \uc7a5\uc810\uacfc \ud568\uaed8 \ubc1c\uc0dd\ud560 \uc218 \uc788\ub294 \ubb38\uc81c\uc810\ub3c4 \uc0dd\uac01\ud574 \ubd05\ub2c8\ub2e4.","\uc0dd\ud65c \uc18d \ubb38\uc81c\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud574 \uacfc\ud559\uc801 \uc6d0\ub9ac\uc640 \uae30\uc220\uc744 \ud65c\uc6a9\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\uae30\uc220\uc5d0 \uc9c0\ub098\uce58\uac8c \uc758\uc874\ud558\uc9c0 \uc54a\uace0 \ud544\uc694\ud55c \uc0c1\ud669\uc5d0 \uc801\uc808\ud558\uac8c \uc0ac\uc6a9\ud558\ub294 \ud0dc\ub3c4\ub97c \uae30\ub985\ub2c8\ub2e4."],t.s)
A.f2_=new B.A("\uacfc\ud559","khoa h\u1ecdc","\uacfc\ud559\uc740 \uc6b0\ub9ac\uc758 \uc0dd\ud65c\uacfc \uc544\uc8fc \ubc00\uc811\ud55c \uad00\uacc4\uac00 \uc788\uc2b5\ub2c8\ub2e4.","Khoa h\u1ecdc c\xf3 m\u1ed1i quan h\u1ec7 r\u1ea5t g\u1ea7n g\u0169i v\u1edbi cu\u1ed9c s\u1ed1ng c\u1ee7a ch\xfang ta.")
A.eZm=new B.A("\uacfc\ud559 \uae30\uc220","khoa h\u1ecdc k\u1ef9 thu\u1eadt, c\xf4ng ngh\u1ec7 khoa h\u1ecdc","\uacfc\ud559 \uae30\uc220\uc758 \ubc1c\ub2ec\ub85c \uc0dd\ud65c\uc774 \ud6e8\uc52c \ud3b8\ub9ac\ud574\uc84c\uc2b5\ub2c8\ub2e4.","Nh\u1edd s\u1ef1 ph\xe1t tri\u1ec3n c\u1ee7a khoa h\u1ecdc k\u1ef9 thu\u1eadt, cu\u1ed9c s\u1ed1ng \u0111\xe3 tr\u1edf n\xean ti\u1ec7n l\u1ee3i h\u01a1n nhi\u1ec1u.")
A.f0k=new B.A("\uae30\uc220","k\u1ef9 thu\u1eadt, c\xf4ng ngh\u1ec7","\uc0c8\ub85c\uc6b4 \uae30\uc220\uc774 \uacc4\uc18d \uac1c\ubc1c\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4.","C\xe1c c\xf4ng ngh\u1ec7 m\u1edbi \u0111ang li\xean t\u1ee5c \u0111\u01b0\u1ee3c ph\xe1t tri\u1ec3n.")
