A.eMa=new B.aj("\uacfc\ud559 \uae30\uc220\uc758 \ubc1c\ub2ec\ub85c \ub098\ud0c0\ub09c \ubcc0\ud654\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.j4o,0,"\uacfc\ud559 \uae30\uc220\uc758 \ubc1c\ub2ec\uc740 \uad50\ud1b5, \ud1b5\uc2e0, \uac00\uc804\uc81c\ud488, \uc758\ub8cc \ub4f1 \ub2e4\uc591\ud55c \ubd84\uc57c\uc5d0\uc11c \uc0dd\ud65c\uc744 \ud3b8\ub9ac\ud558\uac8c \ub9cc\ub4e4\uc5c8\uc2b5\ub2c8\ub2e4.")
A.hAZ=s(["\u2460 \uc904","\u2461 \uc218\ubc16\uc5d0","\u2462 \ubfd0\ub9cc \uc544\ub2c8\ub77c","\u2463 \ub290\ub77c\uace0"],t.s)
A.eNy=new B.aj("\ub2e4\uc74c \ub300\ud654\uc5d0 \ub4e4\uc5b4\uac08 \ud45c\ud604\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?\n\n\uac00: \uc2a4\ub9c8\ud2b8\ud3f0\uc73c\ub85c \uc9d1\uc5d0 \uc788\ub294 \uc5d0\uc5b4\ucee8\ub3c4 \ucf24 \uc218 \uc788\uc5b4\uc694?\n\ub098: \ub124.\n\uac00: \uc815\ub9d0\uc694? \uc800\ub294 \uadf8\ub7f0 \uae30\ub2a5\uc774 \uc788\ub294______ \ubab0\ub790\uc5b4\uc694.",A.hAZ,0,'\uc0c8\ub85c\uc6b4 \uc0ac\uc2e4\uc744 \uc804\uc5d0\ub294 \uc54c\uc9c0 \ubabb\ud588\ub2e4\ub294 \ub0b4\uc6a9\uc774\ubbc0\ub85c "\uc788\ub294 \uc904 \ubab0\ub790\uc5b4\uc694"\uac00 \uc790\uc5f0\uc2a4\ub7fd\uc2b5\ub2c8\ub2e4.')
