A.itk=s(["\uacfc\ud559 = khoa h\u1ecdc.","\uacfc\ud559 \uae30\uc220 = khoa h\u1ecdc k\u1ef9 thu\u1eadt / c\xf4ng ngh\u1ec7.","\uae30\uc220 = k\u1ef9 thu\u1eadt, c\xf4ng ngh\u1ec7.","\ubc1c\ub2ec\ud558\ub2e4 = ph\xe1t tri\u1ec3n.","\uac1c\ubc1c\ud558\ub2e4 = ph\xe1t tri\u1ec3n, nghi\xean c\u1ee9u ch\u1ebf t\u1ea1o.","\ubc1c\uba85\ud558\ub2e4 = ph\xe1t minh.","\ubc1c\uba85\ud488 = s\u1ea3n ph\u1ea9m ph\xe1t minh.","\uc6d0\ub9ac = nguy\xean l\xfd.","\uae30\ub2a5 = ch\u1ee9c n\u0103ng.","\uc791\ub3d9\ud558\ub2e4 = ho\u1ea1t \u0111\u1ed9ng, v\u1eadn h\xe0nh.","\uc790\ub3d9 = t\u1ef1 \u0111\u1ed9ng.","\uc13c\uc11c = c\u1ea3m bi\u1ebfn.","\uac10\uc9c0\ud558\ub2e4 = ph\xe1t hi\u1ec7n.","\uac00\uc804\uc81c\ud488 = \u0111\u1ed3 \u0111i\u1ec7n gia d\u1ee5ng.","\uc804\uc790\uc81c\ud488 = s\u1ea3n ph\u1ea9m \u0111i\u1ec7n t\u1eed.","\uc0ac\uc6a9 \uc124\uba85\uc11c = h\u01b0\u1edbng d\u1eabn s\u1eed d\u1ee5ng.","\uc804\ub825\uc744 \uc808\uc57d\ud558\ub2e4 = ti\u1ebft ki\u1ec7m \u0111i\u1ec7n n\u0103ng.","\ucda9\uc804\ud558\ub2e4 = s\u1ea1c.","\ubc30\ud130\ub9ac = pin.","\uace0\uc7a5 \ub098\ub2e4 = b\u1ecb h\u1ecfng.","\uc218\ub9ac\ud558\ub2e4 = s\u1eeda ch\u1eefa.","\uc548\uc804\uc7a5\uce58 = thi\u1ebft b\u1ecb an to\xe0n.","\uc608\ubc29\ud558\ub2e4 = ph\xf2ng ng\u1eeba.","\ud6a8\uc728\uc801\uc774\ub2e4 = hi\u1ec7u qu\u1ea3.","\uc758\uc874\ud558\ub2e4 = ph\u1ee5 thu\u1ed9c.","\ud65c\uc6a9\ud558\ub2e4 = t\u1eadn d\u1ee5ng / \u1ee9ng d\u1ee5ng.","\ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub2e4 = gi\u1ea3i quy\u1ebft v\u1ea5n \u0111\u1ec1.","-\ub294 \uc904 \uc54c\ub2e4 = t\u01b0\u1edfng r\u1eb1ng / bi\u1ebft r\u1eb1ng...","-\ub294 \uc904 \ubaa8\ub974\ub2e4 = kh\xf4ng bi\u1ebft r\u1eb1ng...","-(\uc73c)\u3134 \uc904 \uc54c\ub2e4 = t\u01b0\u1edfng r\u1eb1ng... \u0111\u1ed1i v\u1edbi tr\u1ea1ng th\xe1i ho\u1eb7c h\xe0nh \u0111\u1ed9ng \u0111\xe3 ho\xe0n th\xe0nh.","-\uace4 \ud558\ub2e4 = th\u01b0\u1eddng..., t\u1eebng th\u01b0\u1eddng...","-\uac8c \ub418\ub2e4 = tr\u1edf n\xean / \u0111i \u0111\u1ebfn vi\u1ec7c...","-\uae30 \uc704\ud574\uc11c = \u0111\u1ec3...","\uacfc\ud559 \uae30\uc220\uc740 \uc6b0\ub9ac\uc758 \uc0dd\ud65c\uc744 \ud3b8\ub9ac\ud558\uac8c \ub9cc\ub4e4\uc9c0\ub9cc \uc548\uc804\ud558\uac8c \uc0ac\uc6a9\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\uc804\uc790\uc81c\ud488\uc774 \uace0\uc7a5 \ub0ac\uc744 \ub54c\ub294 \ubb34\ub9ac\ud558\uac8c \ubd84\ud574\ud558\uc9c0 \ub9d0\uace0 \uc0ac\uc6a9 \uc124\uba85\uc11c\ub098 \uc11c\ube44\uc2a4\uc13c\ud130\ub97c \uc774\uc6a9\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","\uae30\uc220\uc744 \uc798 \ud65c\uc6a9\ud558\uba74 \uc0dd\ud65c\uc758 \uc5ec\ub7ec \ubb38\uc81c\ub97c \ub354 \ud6a8\uc728\uc801\uc73c\ub85c \ud574\uacb0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ud3b8\ub9ac\ud55c \uae30\uc220\uc774\ub77c\ub3c4 \uc9c0\ub098\uce58\uac8c \uc758\uc874\ud558\uc9c0 \uc54a\uace0 \ud544\uc694\ud55c \uc0c1\ud669\uc5d0 \uc801\uc808\ud558\uac8c \uc0ac\uc6a9\ud558\ub294 \ud0dc\ub3c4\uac00 \ud544\uc694\ud569\ub2c8\ub2e4."],t.s)
A.Kz=new B.hG(3,"\uc0dd\ud65c \uc18d\uc758 \uacfc\ud559","Khoa h\u1ecdc trong cu\u1ed9c s\u1ed1ng",A.fBV,A.h2e,A.j1e,A.iUB,A.iOB,A.itk)
A.KA=new B.z3(null)
A.hEx=s(["Hi\u1ec3u kh\xe1i ni\u1ec7m \uc758\ub840 trong v\u0103n h\xf3a H\xe0n Qu\u1ed1c.","Bi\u1ebft m\u1ed9t s\u1ed1 nghi l\u1ec5 quan tr\u1ecdng nh\u01b0 \ub3cc, \uacb0\ud63c\uc2dd, \uc7a5\ub840\uc2dd v\xe0 \uc81c\uc0ac.","H\u1ecdc t\u1eeb v\u1ef1ng li\xean quan \u0111\u1ebfn c\u01b0\u1edbi h\u1ecfi, tang l\u1ec5 v\xe0 nghi l\u1ec5 gia \u0111\xecnh.","Hi\u1ec3u r\u1eb1ng c\xe1ch th\u1ef1c hi\u1ec7n nghi l\u1ec5 c\xf3 th\u1ec3 kh\xe1c nhau t\xf9y gia \u0111\xecnh v\xe0 th\u1eddi \u0111\u1ea1i.","Bi\u1ebft m\u1ed9t s\u1ed1 c\xe1ch \u1ee9ng x\u1eed c\u01a1 b\u1ea3n khi tham d\u1ef1 \u0111\xe1m c\u01b0\u1edbi ho\u1eb7c tang l\u1ec5.","C\xf3 th\u1ec3 \u0111\u1ecdc hi\u1ec3u \u0111o\u1ea1n v\u0103n v\u1ec1 c\xe1c nghi l\u1ec5 trong \u0111\u1eddi s\u1ed1ng H\xe0n Qu\u1ed1c.","Luy\u1ec7n c\xe2u h\u1ecfi ki\u1ebfn th\u1ee9c x\xe3 h\u1ed9i li\xean quan \u0111\u1ebfn \uc758\ub840."],t.s)
A.ifs=s(["\uc758\ub840\ub294 \uc778\uc0dd\uc758 \uc911\uc694\ud55c \uc21c\uac04\uc774\ub098 \uac00\uc871\uc758 \uc911\uc694\ud55c \uc77c\uc744 \uae30\ub150\ud558\uac70\ub098 \uc758\ubbf8\ub97c \ub098\ud0c0\ub0b4\uae30 \uc704\ud574 \ud558\ub294 \ud589\uc0ac\uc640 \uc808\ucc28\ub97c \ub9d0\ud569\ub2c8\ub2e4.","\uc544\uc774\uc758 \uccab\ub3cc\uc744 \uae30\ub150\ud558\ub294 \ud589\uc0ac\ub97c \ub3cc\uc794\uce58\ub77c\uace0 \ud569\ub2c8\ub2e4.","\uacb0\ud63c\uc2dd\uc740 \ub450 \uc0ac\ub78c\uc774 \uacb0\ud63c\ud558\ub294 \uac83\uc744 \ucd95\ud558\ud558\ub294 \uc758\ub840\uc785\ub2c8\ub2e4.","\uc7a5\ub840\uc2dd\uc740 \uc0ac\ub78c\uc774 \uc138\uc0c1\uc744 \ub5a0\ub0ac\uc744 \ub54c \uace0\uc778\uc744 \ucd94\ubaa8\ud558\uace0 \uc720\uac00\uc871\uc744 \uc704\ub85c\ud558\uae30 \uc704\ud55c \uc758\ub840\uc785\ub2c8\ub2e4.","\uc77c\ubd80 \uac00\uc815\uc5d0\uc11c\ub294 \uc870\uc0c1\uc744 \uae30\ub9ac\ub294 \uc81c\uc0ac\ub97c \uc9c0\ub0b4\uae30\ub3c4 \ud569\ub2c8\ub2e4.","\ud604\ub300\uc5d0\ub294 \uc804\ud1b5\uc801\uc778 \ubc29\uc2dd\uacfc \ud604\ub300\uc801\uc778 \ubc29\uc2dd\uc774 \ud568\uaed8 \ub098\ud0c0\ub098\uae30\ub3c4 \ud569\ub2c8\ub2e4.","\uc758\ub840\uc758 \ubc29\uc2dd\uc740 \uc885\uad50, \uac00\uc871, \uc9c0\uc5ed, \uac1c\uc778\uc758 \uc120\ud0dd\uc5d0 \ub530\ub77c \ub2e4\ub97c \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ub2e4\ub978 \uc0ac\ub78c\uc758 \uac00\uc871\ubb38\ud654\uc640 \uc758\ub840 \ubc29\uc2dd\uc744 \uc874\uc911\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4."],t.s)
A.fhG=new B.p("\uc758\ub840","nghi l\u1ec5 / nghi th\u1ee9c","\uacb0\ud63c\uc2dd\uc740 \uc911\uc694\ud55c \uc758\ub840 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4.","\u0110\xe1m c\u01b0\u1edbi l\xe0 m\u1ed9t trong nh\u1eefng nghi l\u1ec5 quan tr\u1ecdng.")
A.fi6=new B.p("\ub3cc","sinh nh\u1eadt m\u1ed9t tu\u1ed5i","\uc544\uc774\uc758 \uccab \ubc88\uc9f8 \uc0dd\uc77c\uc744 \ub3cc\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4.","Sinh nh\u1eadt \u0111\u1ea7u ti\xean c\u1ee7a tr\u1ebb \u0111\u01b0\u1ee3c g\u1ecdi l\xe0 dol.")
