A.hp1=s(["\ubc95\uc744 \uc874\uc911\ud558\uace0 \uc2a4\uc2a4\ub85c \uc9c0\ud0a4\ub824\ub294 \ud0dc\ub3c4","\ubc95\uc744 \uc704\ubc18\ud558\ub824\ub294 \ud0dc\ub3c4","\ub2e4\ub978 \uc0ac\ub78c\uc758 \uad8c\ub9ac\ub97c \ubb34\uc2dc\ud558\ub294 \ud0dc\ub3c4","\uaddc\uce59\uc774 \ud544\uc694 \uc5c6\ub2e4\uace0 \uc0dd\uac01\ud558\ub294 \ud0dc\ub3c4"],t.s)
A.f5k=new B.G("\u201c\uc900\ubc95\uc758\uc2dd\u201d\uc758 \uc124\uba85\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Gi\u1ea3i th\xedch n\xe0o ph\xf9 h\u1ee3p v\u1edbi \uc900\ubc95\uc758\uc2dd?",A.hp1,0,"\uc900\ubc95\uc758\uc2dd l\xe0 th\xe1i \u0111\u1ed9 t\xf4n tr\u1ecdng v\xe0 t\u1ef1 gi\xe1c tu\xe2n th\u1ee7 ph\xe1p lu\u1eadt.")
A.fS4=s(["\uc0ac\ud68c \uc9c8\uc11c\uc640 \uc0ac\ub78c\ub4e4\uc758 \uad8c\ub9ac\ub97c \ubcf4\ud638\ud558\uae30 \uc704\ud574\uc11c","\ub2e4\ub978 \uc0ac\ub78c\uc744 \ubd88\ud3b8\ud558\uac8c \ud558\uae30 \uc704\ud574\uc11c","\ubaa8\ub4e0 \uc790\uc720\ub97c \uc5c6\uc560\uae30 \uc704\ud574\uc11c","\uc0ac\ub78c\ub4e4\uc744 \uc11c\ub85c \ubbff\uc9c0 \ubabb\ud558\uac8c \ud558\uae30 \uc704\ud574\uc11c"],t.s)
A.faM=new B.G("\ubc95\uc744 \uc9c0\ud0a4\ub294 \uc774\uc720\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","L\xfd do ph\xf9 h\u1ee3p \u0111\u1ec3 tu\xe2n th\u1ee7 ph\xe1p lu\u1eadt l\xe0 g\xec?",A.fS4,0,"Ph\xe1p lu\u1eadt g\xf3p ph\u1ea7n duy tr\xec tr\u1eadt t\u1ef1 v\xe0 b\u1ea3o v\u1ec7 quy\u1ec1n c\u1ee7a con ng\u01b0\u1eddi.")
A.fZt=s(["\uc0ac\uace0 \uc608\ubc29\uacfc \uc548\uc804\uc5d0 \ub3c4\uc6c0\uc774 \ub41c\ub2e4.","\uad50\ud1b5\uc0ac\uace0\uac00 \ub354 \ub9ce\uc544\uc9c4\ub2e4.","\ub2e4\ub978 \uc0ac\ub78c\uc758 \uc548\uc804\uc774 \ub354 \uc704\ud5d8\ud574\uc9c4\ub2e4.","\uad50\ud1b5\uc9c8\uc11c\uac00 \uc5c6\uc5b4\uc9c0\uac8c \ub41c\ub2e4."],t.s)
