A.fbz=new B.G("\ubc95\uc744 \uc704\ubc18\ud588\uc744 \ub54c \uc0dd\uae38 \uc218 \uc788\ub294 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110i\u1ec1u g\xec c\xf3 th\u1ec3 ph\xe1t sinh khi vi ph\u1ea1m ph\xe1p lu\u1eadt?",A.hhH,0,"Vi ph\u1ea1m ph\xe1p lu\u1eadt c\xf3 th\u1ec3 d\u1eabn \u0111\u1ebfn tr\xe1ch nhi\u1ec7m ph\xe1p l\xfd.")
A.iEF=s(["\ub2e4\ub978 \uc0ac\ub78c\uc758 \uad8c\ub9ac\ub3c4 \uc874\uc911\ud55c\ub2e4.","\ub2e4\ub978 \uc0ac\ub78c\uc758 \uad8c\ub9ac\ub294 \ubb34\uc2dc\ud55c\ub2e4.","\ubc95\uc744 \uc9c0\ud0ac \ud544\uc694\uac00 \uc5c6\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4.","\uc790\uc2e0\ub9cc \uc790\uc720\ub85c\uc6b0\uba74 \ub41c\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4."],t.s)
A.f7b=new B.G("\uc790\uc2e0\uc758 \uad8c\ub9ac\ub97c \ud589\uc0ac\ud560 \ub54c \ud544\uc694\ud55c \ud0dc\ub3c4\ub294 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Khi th\u1ef1c hi\u1ec7n quy\u1ec1n c\u1ee7a m\xecnh c\u1ea7n c\xf3 th\xe1i \u0111\u1ed9 n\xe0o?",A.iEF,0,"Quy\u1ec1n c\u1ee7a m\xecnh c\u1ea7n \u0111\u01b0\u1ee3c th\u1ef1c hi\u1ec7n trong khi t\xf4n tr\u1ecdng quy\u1ec1n c\u1ee7a ng\u01b0\u1eddi kh\xe1c.")
A.iBh=s(["\uad50\ud1b5\uc2e0\ud638\ub97c \uc9c0\ud0a8\ub2e4.","\uc4f0\ub808\uae30 \ubc30\ucd9c \uaddc\uce59\uc744 \uc9c0\ud0a8\ub2e4.","\uacc4\uc57d \ub0b4\uc6a9\uc744 \uc9c0\ud0a8\ub2e4.","\uc790\uc2e0\uc5d0\uac8c \ubd88\ud3b8\ud55c \ubc95\uc740 \ud56d\uc0c1 \ubb34\uc2dc\ud55c\ub2e4."],t.s)
A.f9u=new B.G("\uc900\ubc95\uc0dd\ud65c\uc758 \uc608\ub85c \uc54c\ub9de\uc9c0 \uc54a\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110\xe2u KH\xd4NG ph\u1ea3i v\xed d\u1ee5 ph\xf9 h\u1ee3p v\u1ec1 \u0111\u1eddi s\u1ed1ng tu\xe2n th\u1ee7 ph\xe1p lu\u1eadt?",A.iBh,3,"Kh\xf4ng th\u1ec3 t\xf9y \xfd b\u1ecf qua ph\xe1p lu\u1eadt ch\u1ec9 v\xec th\u1ea5y b\u1ea5t ti\u1ec7n.")
A.i2a=s(["\uc0ac\ud68c\uc801 \uc2e0\ub8b0\uac00 \ub192\uc544\uc9c8 \uc218 \uc788\ub2e4.","\ud56d\uc0c1 \ubd84\uc7c1\uc774 \ub354 \ub9ce\uc544\uc9c4\ub2e4.","\uc0ac\ud68c\uc758 \uc9c8\uc11c\uac00 \uc0ac\ub77c\uc9c4\ub2e4.","\ubaa8\ub4e0 \uc0ac\ub78c\uc758 \uad8c\ub9ac\uac00 \uc5c6\uc5b4\uc9c0\uac8c \ub41c\ub2e4."],t.s)
A.fai=new B.G("\uc0ac\ub78c\ub4e4\uc774 \uaddc\uce59\uc744 \uc798 \uc9c0\ud0ac \ub54c \ub098\ud0c0\ub0a0 \uc218 \uc788\ub294 \ud6a8\uacfc\ub294 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Hi\u1ec7u qu\u1ea3 n\xe0o c\xf3 th\u1ec3 xu\u1ea5t hi\u1ec7n khi m\u1ecdi ng\u01b0\u1eddi tu\xe2n th\u1ee7 t\u1ed1t quy t\u1eafc?",A.i2a,0,"Tu\xe2n th\u1ee7 c\xe1c quy t\u1eafc chung c\xf3 th\u1ec3 g\xf3p ph\u1ea7n t\u1ea1o s\u1ef1 tin t\u01b0\u1edfng trong x\xe3 h\u1ed9i.")
A.iE6=s(["\uc790\uc2e0\uc758 \uc790\uc720\uc640 \ud568\uaed8 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uad8c\ub9ac\ub3c4 \uc0dd\uac01\ud55c\ub2e4.","\uc790\uc2e0\uc758 \ud3b8\uc758\ub9cc \uc0dd\uac01\ud55c\ub2e4.","\uaddc\uce59\uc744 \uc804\ud600 \uc9c0\ud0a4\uc9c0 \uc54a\ub294\ub2e4.","\ub2e4\ub978 \uc0ac\ub78c\uc758 \uc548\uc804\uc744 \ubb34\uc2dc\ud55c\ub2e4."],t.s)
