A.hnl=s(["\ubbfc\uc0ac = v\u1ea5n \u0111\u1ec1 d\xe2n s\u1ef1 gi\u1eefa c\xe1c b\xean; \ud615\uc0ac = v\u1ea5n \u0111\u1ec1 li\xean quan \u0111\u1ebfn h\xe0nh vi ph\u1ea1m t\u1ed9i.","\uc2e0\uace0 v\xe0 \uace0\uc18c kh\xf4ng ho\xe0n to\xe0n gi\u1ed1ng nhau; \xfd ngh\u0129a v\xe0 th\u1ee7 t\u1ee5c ph\u1ee5 thu\u1ed9c t\xecnh hu\u1ed1ng ph\xe1p l\xfd.","\uacbd\ucc30, \uac80\ucc30, \ubc95\uc6d0 c\xf3 vai tr\xf2 kh\xe1c nhau trong h\u1ec7 th\u1ed1ng ph\xe1p lu\u1eadt.","\ubd84\uc7c1\uc774 \uc788\ub2e4\uace0 \ud574\uc11c \ubaa8\ub4e0 \uc0ac\uac74\uc774 \ubc94\uc8c4\uac00 \ub418\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.","\ud569\uc758 = c\xe1c b\xean \u0111\u1ea1t th\u1ecfa thu\u1eadn; \uc870\uc815 = s\u1eed d\u1ee5ng qu\xe1 tr\xecnh h\xf2a gi\u1ea3i/\u0111i\u1ec1u \u0111\xecnh.","\uc7ac\ud310 = t\xf2a \xe1n x\xe9t x\u1eed v\xe0 \u0111\u01b0a ra ph\xe1n quy\u1ebft theo ph\xe1p lu\u1eadt.","\uc99d\uac70 c\xf3 th\u1ec3 g\u1ed3m h\u1ee3p \u0111\u1ed3ng, h\xf3a \u0111\u01a1n, chuy\u1ec3n kho\u1ea3n, tin nh\u1eafn, \u1ea3nh v\xe0 c\xe1c t\xe0i li\u1ec7u li\xean quan.","\uc911\uc694\ud55c \uac70\ub798\ub294 \ub9d0\ub85c\ub9cc \uc57d\uc18d\ud558\uae30\ubcf4\ub2e4 \uae30\ub85d\uc744 \ub0a8\uae30\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4."],t.s)
A.hyt=s(["\ubc95 \uc9d1\ud589 \u2192 th\u1ef1c thi ph\xe1p lu\u1eadt.","\uacbd\ucc30 \u2192 \ubc94\uc8c4 \uc608\ubc29, \uc2e0\uace0 \uc811\uc218, \ud604\uc7a5 \ub300\uc751 \ub4f1.","\ubc95\uc6d0 \u2192 \uc7ac\ud310\uc744 \ud1b5\ud574 \ubc95\uc801 \ubd84\uc7c1\uc744 \ud310\ub2e8.","\ubbfc\uc0ac \ubd84\uc7c1 \u2192 \uacc4\uc57d, \ub3c8, \uc190\ud574\ubc30\uc0c1 \ub4f1\uacfc \uad00\ub828\ub41c \ubd84\uc7c1.","\ud615\uc0ac \uc0ac\uac74 \u2192 \ubc94\uc8c4\uc640 \uad00\ub828\ub41c \uc0ac\uac74.","\ud569\uc758 \u2192 th\u1ecfa thu\u1eadn gi\u1eefa c\xe1c b\xean.","\uc870\uc815 \u2192 h\xf2a gi\u1ea3i/\u0111i\u1ec1u \u0111\xecnh.","\uc7ac\ud310 \u2192 x\xe9t x\u1eed.","\uc99d\uac70 \u2192 ch\u1ee9ng c\u1ee9.","\uacc4\uc57d\uc11c, \uc601\uc218\uc99d, \uc774\uccb4 \ub0b4\uc5ed, \ubb38\uc790 \ub4f1\uc740 \uc99d\uac70\uac00 \ub420 \uc218 \uc788\ub2e4.","\ubd84\uc7c1\uc774 \ubc1c\uc0dd\ud558\uba74 \uc0c1\ud669\uc5d0 \ub530\ub77c \ub300\ud654, \ud569\uc758, \uc870\uc815, \uc7ac\ud310 \ub4f1\uc758 \ubc29\ubc95\uc744 \uc774\uc6a9\ud560 \uc218 \uc788\ub2e4."],t.s)
A.j0A=s(["\uc7ac\ud310\uc744 \ud1b5\ud574 \ubc95\uc801 \ubd84\uc7c1\uc744 \ud310\ub2e8\ud55c\ub2e4.","\uc740\ud589 \uacc4\uc88c\ub97c \ub9cc\ub4e0\ub2e4.","\ud68c\uc0ac \uc9c1\uc6d0\uc744 \ucc44\uc6a9\ud55c\ub2e4.","\uc0c1\ud488\uc744 \uc218\ucd9c\ud55c\ub2e4."],t.s)
A.f8Q=new B.G("\ubc95\uc6d0\uc758 \ub300\ud45c\uc801\uc778 \uc5ed\ud560\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Vai tr\xf2 ti\xeau bi\u1ec3u c\u1ee7a t\xf2a \xe1n l\xe0 g\xec?",A.j0A,0,"\ubc95\uc6d0\uc740 \uc7ac\ud310\uc744 \ud1b5\ud574 \ubc95\uc801 \ubd84\uc7c1\uacfc \uc0ac\uac74\uc744 \ud310\ub2e8\ud569\ub2c8\ub2e4.")
A.h0O=s(["\ubbfc\uc0ac","\uae30\uc0c1","\uad50\uc721","\uad00\uad11"],t.s)
A.f9V=new B.G("\uacc4\uc57d\uc774\ub098 \ub3c8 \ubb38\uc81c\ub85c \uac1c\uc778 \uc0ac\uc774\uc5d0 \uc0dd\uae34 \ubd84\uc7c1\uc740 \ubb34\uc5c7\uacfc \uad00\ub828\uc774 \uae4a\uc2b5\ub2c8\uae4c?","Tranh ch\u1ea5p gi\u1eefa c\xe1c c\xe1 nh\xe2n v\u1ec1 h\u1ee3p \u0111\u1ed3ng ho\u1eb7c ti\u1ec1n b\u1ea1c li\xean quan nhi\u1ec1u nh\u1ea5t \u0111\u1ebfn l\u0129nh v\u1ef1c n\xe0o?",A.h0O,0,"H\u1ee3p \u0111\u1ed3ng v\xe0 ti\u1ec1n b\u1ea1c th\u01b0\u1eddng li\xean quan \u0111\u1ebfn tranh ch\u1ea5p d\xe2n s\u1ef1.")
A.iSU=s(["\ud615\uc0ac \uc0ac\uac74","\ubb38\ud654 \ud589\uc0ac","\uae08\uc735 \uc0c1\ud488","\uad50\uc721 \uacfc\uc815"],t.s)
A.f5Q=new B.G("\uc808\ub3c4\ub098 \uc0ac\uae30\uc640 \uac19\uc774 \ubc94\uc8c4\uc640 \uad00\ub828\ub41c \uc0ac\uac74\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","V\u1ee5 vi\u1ec7c li\xean quan \u0111\u1ebfn t\u1ed9i ph\u1ea1m nh\u01b0 tr\u1ed9m c\u1eafp ho\u1eb7c l\u1eeba \u0111\u1ea3o l\xe0 g\xec?",A.iSU,0,"C\xe1c v\u1ee5 vi\u1ec7c li\xean quan \u0111\u1ebfn t\u1ed9i ph\u1ea1m c\xf3 th\u1ec3 l\xe0 v\u1ee5 \xe1n h\xecnh s\u1ef1.")
A.hER=s(["\ub300\ud654\ub97c \ud1b5\ud574 \ud574\uacb0\ud55c\ub2e4.","\uc870\uc815\uc744 \uc774\uc6a9\ud55c\ub2e4.","\uc7ac\ud310\uc744 \uc774\uc6a9\ud55c\ub2e4.","\uc0c1\ub300\ubc29\uc5d0\uac8c \ud3ed\ub825\uc744 \uc0ac\uc6a9\ud55c\ub2e4."],t.s)
A.f5W=new B.G("\ubd84\uc7c1\uc744 \ud574\uacb0\ud558\ub294 \ubc29\ubc95\uc73c\ub85c \uc54c\ub9de\uc9c0 \uc54a\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110\xe2u KH\xd4NG ph\u1ea3i c\xe1ch ph\xf9 h\u1ee3p \u0111\u1ec3 gi\u1ea3i quy\u1ebft tranh ch\u1ea5p?",A.hER,3,"S\u1eed d\u1ee5ng b\u1ea1o l\u1ef1c kh\xf4ng ph\u1ea3i c\xe1ch gi\u1ea3i quy\u1ebft tranh ch\u1ea5p ph\xf9 h\u1ee3p.")
