A.f6R=new B.G("\ub450 \ub2f9\uc0ac\uc790\uac00 \uc11c\ub85c \uc758\uacac\uc744 \uc870\uc815\ud558\uc5ec \ubb38\uc81c \ud574\uacb0\uc5d0 \ub3d9\uc758\ud558\ub294 \uac83\uc740?","Hai b\xean \u0111i\u1ec1u ch\u1ec9nh \xfd ki\u1ebfn v\xe0 \u0111\u1ed3ng \xfd gi\u1ea3i quy\u1ebft v\u1ea5n \u0111\u1ec1 \u0111\u01b0\u1ee3c g\u1ecdi l\xe0 g\xec?",A.hi5,0,"\ud569\uc758 = \u0111\u1ea1t \u0111\u01b0\u1ee3c th\u1ecfa thu\u1eadn.")
A.iB5=s(["\uacc4\uc57d\uc11c\uc640 \uacc4\uc88c\uc774\uccb4 \ub0b4\uc5ed","\uc0c1\uad00\uc5c6\ub294 \uad11\uace0\ub9cc","\uce5c\uad6c\uc758 \ucde8\ubbf8","\ub0a0\uc528 \uc815\ubcf4\ub9cc"],t.s)
A.f8K=new B.G("\ubd84\uc7c1\uc774 \ubc1c\uc0dd\ud588\uc744 \ub54c \uc99d\uac70\uac00 \ub420 \uc218 \uc788\ub294 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Th\u1ee9 n\xe0o c\xf3 th\u1ec3 l\xe0 ch\u1ee9ng c\u1ee9 khi x\u1ea3y ra tranh ch\u1ea5p?",A.iB5,0,"H\u1ee3p \u0111\u1ed3ng v\xe0 l\u1ecbch s\u1eed chuy\u1ec3n kho\u1ea3n c\xf3 th\u1ec3 gi\xfap ch\u1ee9ng minh giao d\u1ecbch.")
A.hUt=s(["\uacbd\ucc30 \ub4f1 \uad00\ub828 \uae30\uad00\uc5d0 \ub3c4\uc6c0\uc744 \uc694\uccad\ud55c\ub2e4.","\ubaa8\ub4e0 \uc99d\uac70\ub97c \ubc14\ub85c \ubc84\ub9b0\ub2e4.","\ubb34\uc870\uac74 \ud63c\uc790 \ud574\uacb0\ud55c\ub2e4.","\uc0ac\uac74\uc744 \uc228\uae30\uae30\ub9cc \ud55c\ub2e4."],t.s)
A.f8E=new B.G("\ubc94\uc8c4 \ud53c\ud574\ub97c \uc785\uc5c8\uc744 \ub54c \ud560 \uc218 \uc788\ub294 \ud589\ub3d9\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740?","H\xe0nh \u0111\u1ed9ng ph\xf9 h\u1ee3p khi b\u1ecb thi\u1ec7t h\u1ea1i do t\u1ed9i ph\u1ea1m l\xe0 g\xec?",A.hUt,0,"Ng\u01b0\u1eddi b\u1ecb h\u1ea1i c\xf3 th\u1ec3 y\xeau c\u1ea7u c\u1ea3nh s\xe1t ho\u1eb7c c\u01a1 quan li\xean quan h\u1ed7 tr\u1ee3.")
A.hut=s(["\uacc4\uc57d\uacfc \uacb0\uc81c \uad00\ub828 \uc790\ub8cc\ub97c \ubcf4\uad00\ud55c\ub2e4.","\ubaa8\ub4e0 \ub0b4\uc6a9\uc744 \ub9d0\ub85c\ub9cc \uc57d\uc18d\ud55c\ub2e4.","\uc601\uc218\uc99d\uc744 \ubc14\ub85c \ubc84\ub9b0\ub2e4.","\uc0c1\ub300\ubc29 \uc815\ubcf4\ub97c \uc804\ud600 \ud655\uc778\ud558\uc9c0 \uc54a\ub294\ub2e4."],t.s)
A.f4V=new B.G("\uc911\uc694\ud55c \uac70\ub798\ub97c \ud560 \ub54c \ubc14\ub78c\uc9c1\ud55c \ud589\ub3d9\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","H\xe0nh \u0111\u1ed9ng ph\xf9 h\u1ee3p khi th\u1ef1c hi\u1ec7n giao d\u1ecbch quan tr\u1ecdng l\xe0 g\xec?",A.hut,0,"N\xean gi\u1eef c\xe1c t\xe0i li\u1ec7u v\u1ec1 h\u1ee3p \u0111\u1ed3ng v\xe0 thanh to\xe1n.")
A.fOa=s(["\uc870\uc815\uc774\ub098 \uc7ac\ud310","\ud3ed\ub825","\ud611\ubc15","\uc99d\uac70 \uc0ad\uc81c"],t.s)
A.f9c=new B.G("\ub2f9\uc0ac\uc790\ub07c\ub9ac \ud574\uacb0\ud558\uae30 \uc5b4\ub824\uc6b8 \ub54c \uc774\uc6a9\ud560 \uc218 \uc788\ub294 \ubc29\ubc95\uc740?","Khi c\xe1c b\xean kh\xf3 t\u1ef1 gi\u1ea3i quy\u1ebft c\xf3 th\u1ec3 s\u1eed d\u1ee5ng ph\u01b0\u01a1ng ph\xe1p n\xe0o?",A.fOa,0,"C\xf3 th\u1ec3 s\u1eed d\u1ee5ng h\xf2a gi\u1ea3i ho\u1eb7c x\xe9t x\u1eed t\xf9y theo t\xecnh hu\u1ed1ng.")
A.iTg=s(["\ubd84\uc7c1\uc774 \uc0dd\uae30\uba74 \uad00\ub828 \uc790\ub8cc\ub97c \ubcf4\uad00\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4.","\ubaa8\ub4e0 \ubd84\uc7c1\uc740 \ubc18\ub4dc\uc2dc \ubc94\uc8c4\uc774\ub2e4.","\uacc4\uc57d\uc11c\ub294 \ubd84\uc7c1\uacfc \uc544\ubb34 \uad00\uacc4\uac00 \uc5c6\ub2e4.","\ubc95\uc801 \ubb38\uc81c\uac00 \ubcf5\uc7a1\ud574\ub3c4 \uc0c1\ub2f4\uc744 \ubc1b\uc744 \ud544\uc694\uac00 \uc5c6\ub2e4."],t.s)
A.fc3=new B.G("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung ph\xf9 h\u1ee3p v\u1edbi b\xe0i \u0111\u1ecdc.",A.iTg,0,"Gi\u1eef t\xe0i li\u1ec7u v\xe0 ch\u1ee9ng c\u1ee9 li\xean quan l\xe0 \u0111i\u1ec1u quan tr\u1ecdng khi x\u1ea3y ra tranh ch\u1ea5p.")
A.hKs=s([A.f8Q,A.f9V,A.f5Q,A.f5W,A.f6R,A.f8K,A.f8E,A.f4V,A.f9c,A.fc3],t.h)
A.htb=s(["\ubc95 \uc9d1\ud589 = th\u1ef1c thi ph\xe1p lu\u1eadt.","\ubd84\uc7c1 = tranh ch\u1ea5p.","\uacbd\ucc30 = c\u1ea3nh s\xe1t.","\uac80\ucc30 = c\u01a1 quan c\xf4ng t\u1ed1.","\ubc95\uc6d0 = t\xf2a \xe1n.","\ubbfc\uc0ac = d\xe2n s\u1ef1.","\ud615\uc0ac = h\xecnh s\u1ef1.","\uc7ac\ud310 = x\xe9t x\u1eed.","\ud569\uc758 = th\u1ecfa thu\u1eadn.","\uc870\uc815 = h\xf2a gi\u1ea3i.","\uc99d\uac70 = ch\u1ee9ng c\u1ee9.","\uc190\ud574\ubc30\uc0c1 = b\u1ed3i th\u01b0\u1eddng thi\u1ec7t h\u1ea1i.","\ubd84\uc7c1\uc774 \uc0dd\uae30\uba74 \uba3c\uc800 \uc0c1\ud669\uacfc \uc790\ub8cc\ub97c \uc815\ud655\ud788 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\uacc4\uc57d\uc11c, \uc601\uc218\uc99d, \uc774\uccb4 \ub0b4\uc5ed, \ubb38\uc790 \ub4f1\uc758 \uc790\ub8cc\ub97c \ubcf4\uad00\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","\ubcf5\uc7a1\ud55c \ubc95\ub960 \ubb38\uc81c\ub294 \uad00\ub828 \uae30\uad00\uc774\ub098 \uc804\ubb38\uac00\uc5d0\uac8c \uc0c1\ub2f4\ubc1b\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],t.s)
A.f3y=new B.dk(33,"\ubc95","\ubc95 \uc9d1\ud589\uacfc \ubd84\uc7c1 \ud574\uacb0","Th\u1ef1c thi ph\xe1p lu\u1eadt v\xe0 gi\u1ea3i quy\u1ebft tranh ch\u1ea5p",A.fTR,A.hOA,A.hVo,A.hF8,"\ubd84\uc7c1\uc774 \uc0dd\uae30\uba74 \uc5b4\ub5bb\uac8c \ud574\uc57c \ud560\uae4c?","\uc0ac\ub78c\ub4e4\uc774 \ud568\uaed8 \uc0dd\ud65c\ud558\ub2e4 \ubcf4\uba74 \uc5ec\ub7ec \uac00\uc9c0 \ubd84\uc7c1\uc774 \uc0dd\uae38 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ubb3c\uac74\uc744 \uc0ac\uace0\ud30c\ub294 \uacfc\uc815\uc5d0\uc11c \ubb38\uc81c\uac00 \uc0dd\uae30\uac70\ub098 \ub3c8\uc744 \ube4c\ub824 \uc900 \ud6c4 \ub3cc\ub824\ubc1b\uc9c0 \ubabb\ud558\ub294 \uacbd\uc6b0, \uacc4\uc57d \ub0b4\uc6a9\uc5d0 \ub300\ud55c \uc758\uacac\uc774 \ub2e4\ub978 \uacbd\uc6b0 \ub4f1\uc774 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc774\ucc98\ub7fc \uac1c\uc778\uc774\ub098 \ud68c\uc0ac \uc0ac\uc774\uc5d0\uc11c \ub3c8, \uacc4\uc57d, \uc190\ud574\ubc30\uc0c1 \ub4f1\uacfc \uad00\ub828\ud558\uc5ec \ubc1c\uc0dd\ud558\ub294 \ubb38\uc81c\ub294 \ubbfc\uc0ac \ubd84\uc7c1\uc774 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ubc18\uba74 \ud3ed\ud589, \uc808\ub3c4, \uc0ac\uae30 \ub4f1 \ubc94\uc8c4\uc640 \uad00\ub828\ub41c \ubb38\uc81c\ub294 \ud615\uc0ac \uc0ac\uac74\uc73c\ub85c \ucc98\ub9ac\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ubc94\uc8c4 \ud53c\ud574\ub97c \uc785\uac70\ub098 \uc704\ud5d8\ud55c \uc0c1\ud669\uc774 \ubc1c\uc0dd\ud55c \uacbd\uc6b0\uc5d0\ub294 \uacbd\ucc30 \ub4f1 \uad00\ub828 \uae30\uad00\uc5d0 \ub3c4\uc6c0\uc744 \uc694\uccad\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ubd84\uc7c1\uc774 \uc0dd\uacbc\ub2e4\uace0 \ud574\uc11c \ud56d\uc0c1 \ubc14\ub85c \uc7ac\ud310\uc744 \ud574\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4. \uba3c\uc800 \uc0c1\ub300\ubc29\uacfc \ub300\ud654\ud558\uc5ec \ubb38\uc81c\ub97c \ud574\uacb0\ud558\uac70\ub098 \uc11c\ub85c \ud569\uc758\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ub2f9\uc0ac\uc790\ub07c\ub9ac \ud574\uacb0\ud558\uae30 \uc5b4\ub824\uc6b4 \uacbd\uc6b0\uc5d0\ub294 \uc911\ub9bd\uc801\uc778 \uae30\uad00\uc774\ub098 \uc81c\ub3c4\ub97c \uc774\uc6a9\ud558\uc5ec \uc870\uc815\uc744 \uc2dc\ub3c4\ud560 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub798\ub3c4 \ud574\uacb0\ub418\uc9c0 \uc54a\uc73c\uba74 \ubc95\uc6d0\uc758 \uc7ac\ud310\uc744 \ud1b5\ud574 \ud310\ub2e8\uc744 \ubc1b\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ubd84\uc7c1\uc744 \ud574\uacb0\ud560 \ub54c\uc5d0\ub294 \uc99d\uac70\uac00 \uc911\uc694\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uacc4\uc57d\uc11c, \uc601\uc218\uc99d, \uacc4\uc88c\uc774\uccb4 \ub0b4\uc5ed, \ubb38\uc790 \uba54\uc2dc\uc9c0, \uc0ac\uc9c4 \ub4f1\uc740 \uc0ac\uc2e4\uad00\uacc4\ub97c \ud655\uc778\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ub530\ub77c\uc11c \uc911\uc694\ud55c \uac70\ub798\ub098 \uc57d\uc18d\uc744 \ud560 \ub54c\uc5d0\ub294 \ub0b4\uc6a9\uc744 \uae30\ub85d\uc73c\ub85c \ub0a8\uae30\uace0 \uad00\ub828 \uc790\ub8cc\ub97c \ubcf4\uad00\ud558\ub294 \uc2b5\uad00\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.\n\n\ubc95\ub960 \ubb38\uc81c\uac00 \ubcf5\uc7a1\ud558\uac70\ub098 \uc5b4\ub5bb\uac8c \ub300\uc751\ud574\uc57c \ud560\uc9c0 \ubaa8\ub974\ub294 \uacbd\uc6b0\uc5d0\ub294 \ud63c\uc790 \ud310\ub2e8\ud558\uae30\ubcf4\ub2e4 \uad00\ub828 \uae30\uad00\uc774\ub098 \ubc95\ub960 \uc804\ubb38\uac00\uc5d0\uac8c \uc0c1\ub2f4\uc744 \ubc1b\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.\n","Khi m\u1ecdi ng\u01b0\u1eddi s\u1ed1ng c\xf9ng nhau, c\xf3 th\u1ec3 ph\xe1t sinh nhi\u1ec1u lo\u1ea1i tranh ch\u1ea5p.\n\nV\xed d\u1ee5, c\xf3 th\u1ec3 x\u1ea3y ra v\u1ea5n \u0111\u1ec1 trong qu\xe1 tr\xecnh mua b\xe1n h\xe0ng h\xf3a, cho ng\u01b0\u1eddi kh\xe1c vay ti\u1ec1n nh\u01b0ng kh\xf4ng \u0111\u01b0\u1ee3c tr\u1ea3 l\u1ea1i, ho\u1eb7c hai b\xean c\xf3 \xfd ki\u1ebfn kh\xe1c nhau v\u1ec1 n\u1ed9i dung h\u1ee3p \u0111\u1ed3ng.\n\nNh\u1eefng v\u1ea5n \u0111\u1ec1 li\xean quan \u0111\u1ebfn ti\u1ec1n b\u1ea1c, h\u1ee3p \u0111\u1ed3ng hay b\u1ed3i th\u01b0\u1eddng thi\u1ec7t h\u1ea1i x\u1ea3y ra gi\u1eefa c\xe1 nh\xe2n ho\u1eb7c doanh nghi\u1ec7p c\xf3 th\u1ec3 tr\u1edf th\xe0nh tranh ch\u1ea5p d\xe2n s\u1ef1.\n\nNg\u01b0\u1ee3c l\u1ea1i, c\xe1c v\u1ea5n \u0111\u1ec1 li\xean quan \u0111\u1ebfn h\xe0nh vi ph\u1ea1m t\u1ed9i nh\u01b0 h\xe0nh hung, tr\u1ed9m c\u1eafp ho\u1eb7c l\u1eeba \u0111\u1ea3o c\xf3 th\u1ec3 \u0111\u01b0\u1ee3c x\u1eed l\xfd nh\u01b0 v\u1ee5 \xe1n h\xecnh s\u1ef1.\n\nN\u1ebfu b\u1ecb thi\u1ec7t h\u1ea1i do t\u1ed9i ph\u1ea1m ho\u1eb7c g\u1eb7p t\xecnh hu\u1ed1ng nguy hi\u1ec3m, c\xf3 th\u1ec3 y\xeau c\u1ea7u c\u1ea3nh s\xe1t ho\u1eb7c c\u01a1 quan li\xean quan h\u1ed7 tr\u1ee3.\n\nKh\xf4ng ph\u1ea3i c\u1ee9 x\u1ea3y ra tranh ch\u1ea5p l\xe0 lu\xf4n ph\u1ea3i l\u1eadp t\u1ee9c \u0111\u01b0a ra t\xf2a. Tr\u01b0\u1edbc ti\xean c\xe1c b\xean c\xf3 th\u1ec3 \u0111\u1ed1i tho\u1ea1i \u0111\u1ec3 gi\u1ea3i quy\u1ebft v\u1ea5n \u0111\u1ec1 ho\u1eb7c \u0111\u1ea1t th\u1ecfa thu\u1eadn.\n\nN\u1ebfu c\xe1c b\xean kh\xf3 t\u1ef1 gi\u1ea3i quy\u1ebft, c\xf3 th\u1ec3 th\u1eed s\u1eed d\u1ee5ng c\u01a1 quan ho\u1eb7c c\u01a1 ch\u1ebf trung l\u1eadp \u0111\u1ec3 h\xf2a gi\u1ea3i. N\u1ebfu v\u1eabn kh\xf4ng gi\u1ea3i quy\u1ebft \u0111\u01b0\u1ee3c, c\xf3 th\u1ec3 y\xeau c\u1ea7u t\xf2a \xe1n \u0111\u01b0a ra ph\xe1n quy\u1ebft th\xf4ng qua x\xe9t x\u1eed.\n\nKhi gi\u1ea3i quy\u1ebft tranh ch\u1ea5p, ch\u1ee9ng c\u1ee9 c\xf3 th\u1ec3 r\u1ea5t quan tr\u1ecdng. H\u1ee3p \u0111\u1ed3ng, h\xf3a \u0111\u01a1n, l\u1ecbch s\u1eed chuy\u1ec3n kho\u1ea3n, tin nh\u1eafn v\xe0 h\xecnh \u1ea3nh c\xf3 th\u1ec3 gi\xfap x\xe1c \u0111\u1ecbnh s\u1ef1 vi\u1ec7c.\n\nV\xec v\u1eady khi th\u1ef1c hi\u1ec7n giao d\u1ecbch ho\u1eb7c th\u1ecfa thu\u1eadn quan tr\u1ecdng, n\xean l\u01b0u l\u1ea1i n\u1ed9i dung b\u1eb1ng v\u0103n b\u1ea3n v\xe0 gi\u1eef c\xe1c t\xe0i li\u1ec7u li\xean quan.\n\nN\u1ebfu v\u1ea5n \u0111\u1ec1 ph\xe1p l\xfd ph\u1ee9c t\u1ea1p ho\u1eb7c kh\xf4ng bi\u1ebft n\xean x\u1eed l\xfd nh\u01b0 th\u1ebf n\xe0o, thay v\xec t\u1ef1 ph\xe1n \u0111o\xe1n m\u1ed9t m\xecnh, n\xean nh\u1eadn t\u01b0 v\u1ea5n t\u1eeb c\u01a1 quan li\xean quan ho\u1eb7c chuy\xean gia ph\xe1p lu\u1eadt.\n","\uc911\uace0\uac70\ub798 \ubd84\uc7c1 \uc0c1\ub2f4\ud558\uae30","\uc548: \uc548\ub155\ud558\uc138\uc694. \uc911\uace0\ub85c \ubb3c\uac74\uc744 \uc0c0\ub294\ub370 \ubb38\uc81c\uac00 \uc0dd\uacbc\uc5b4\uc694.\n\n\uc0c1\ub2f4\uc6d0: \uc5b4\ub5a4 \ubb38\uc81c\uac00 \uc788\uc5c8\ub098\uc694?\n\n\uc548: \ud310\ub9e4\uc790\uac00 \uc815\uc0c1 \uc81c\ud488\uc774\ub77c\uace0 \ud588\ub294\ub370 \ubc1b\uc544 \ubcf4\ub2c8\uae4c \uace0\uc7a5\uc774 \ub098 \uc788\uc5c8\uc5b4\uc694.\n\n\uc0c1\ub2f4\uc6d0: \ud310\ub9e4\uc790\uc5d0\uac8c \uc5f0\ub77d\ud574 \ubcf4\uc168\ub098\uc694?\n\n\uc548: \ub124. \ud658\ubd88\ud574 \ub2ec\ub77c\uace0 \ud588\ub294\ub370 \uc5f0\ub77d\uc744 \ubc1b\uc9c0 \uc54a\uc544\uc694.\n\n\uc0c1\ub2f4\uc6d0: \uac70\ub798\ud560 \ub54c \uc8fc\uace0\ubc1b\uc740 \uba54\uc2dc\uc9c0\uc640 \uc1a1\uae08 \ub0b4\uc5ed\uc774 \uc788\uc2b5\ub2c8\uae4c?\n\n\uc548: \ub124. \ubb38\uc790 \uba54\uc2dc\uc9c0\ud558\uace0 \uacc4\uc88c\uc774\uccb4 \ub0b4\uc5ed\uc774 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc0c1\ub2f4\uc6d0: \uadf8\ub7f0 \uc790\ub8cc\ub294 \uc798 \ubcf4\uad00\ud558\uc138\uc694. \uc0ac\uc2e4\uad00\uacc4\ub97c \ud655\uc778\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc548: \ubc14\ub85c \uacbd\ucc30\uc5d0 \uc2e0\uace0\ud574\uc57c \ud558\ub098\uc694?\n\n\uc0c1\ub2f4\uc6d0: \uad6c\uccb4\uc801\uc778 \uc0c1\ud669\uc5d0 \ub530\ub77c \ub300\uc751 \ubc29\ubc95\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc0ac\uae30\uac00 \uc758\uc2ec\ub418\ub294 \uacbd\uc6b0\uc5d0\ub294 \uad00\ub828 \uae30\uad00\uc5d0 \uc0c1\ub2f4\ud558\uac70\ub098 \uc2e0\uace0\ub97c \uac80\ud1a0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc548: \ub3c8\uc744 \ub3cc\ub824\ubc1b\ub294 \ubb38\uc81c\ub294 \uc5b4\ub5bb\uac8c \ud574\uc57c \ud574\uc694?\n\n\uc0c1\ub2f4\uc6d0: \ub2f9\uc0ac\uc790 \uac04 \ud569\uc758\uac00 \ub418\uc9c0 \uc54a\uc73c\uba74 \ubbfc\uc0ac\uc801\uc778 \ud574\uacb0 \ubc29\ubc95\uc774\ub098 \ubd84\uc7c1\uc870\uc815 \uc808\ucc28\ub97c \uc54c\uc544\ubcfc \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc548: \uc0dd\uac01\ubcf4\ub2e4 \ubcf5\uc7a1\ud558\ub124\uc694.\n\n\uc0c1\ub2f4\uc6d0: \ub124. \uadf8\ub798\uc11c \uc911\uc694\ud55c \uac70\ub798\uc5d0\uc11c\ub294 \uacc4\uc57d \ub0b4\uc6a9\uc774\ub098 \ub300\ud654 \uae30\ub85d, \uacb0\uc81c \uc790\ub8cc\ub97c \ubcf4\uad00\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.\n","An: Xin ch\xe0o. T\xf4i mua m\u1ed9t m\xf3n \u0111\u1ed3 c\u0169 nh\u01b0ng x\u1ea3y ra v\u1ea5n \u0111\u1ec1.\n\nNh\xe2n vi\xean t\u01b0 v\u1ea5n: C\xf3 v\u1ea5n \u0111\u1ec1 g\xec v\u1eady?\n\nAn: Ng\u01b0\u1eddi b\xe1n n\xf3i s\u1ea3n ph\u1ea9m ho\u1ea1t \u0111\u1ed9ng b\xecnh th\u01b0\u1eddng nh\u01b0ng khi nh\u1eadn th\xec n\xf3 \u0111\xe3 h\u1ecfng.\n\nNh\xe2n vi\xean: Anh \u0111\xe3 li\xean l\u1ea1c v\u1edbi ng\u01b0\u1eddi b\xe1n ch\u01b0a?\n\nAn: R\u1ed3i. T\xf4i y\xeau c\u1ea7u ho\xe0n ti\u1ec1n nh\u01b0ng h\u1ecd kh\xf4ng tr\u1ea3 l\u1eddi.\n\nNh\xe2n vi\xean: Anh c\xf3 tin nh\u1eafn trao \u0111\u1ed5i v\xe0 l\u1ecbch s\u1eed chuy\u1ec3n ti\u1ec1n kh\xf4ng?\n\nAn: C\xf3. T\xf4i c\xf3 tin nh\u1eafn v\xe0 l\u1ecbch s\u1eed chuy\u1ec3n kho\u1ea3n.\n\nNh\xe2n vi\xean: H\xe3y gi\u1eef k\u1ef9 c\xe1c t\xe0i li\u1ec7u \u0111\xf3. Ch\xfang c\xf3 th\u1ec3 gi\xfap x\xe1c \u0111\u1ecbnh s\u1ef1 vi\u1ec7c.\n\nAn: T\xf4i c\xf3 ph\u1ea3i b\xe1o c\u1ea3nh s\xe1t ngay kh\xf4ng?\n\nNh\xe2n vi\xean: C\xe1ch x\u1eed l\xfd c\xf3 th\u1ec3 kh\xe1c nhau t\xf9y t\xecnh hu\u1ed1ng c\u1ee5 th\u1ec3. N\u1ebfu nghi ng\u1edd l\u1eeba \u0111\u1ea3o, anh c\xf3 th\u1ec3 t\u01b0 v\u1ea5n v\u1edbi c\u01a1 quan li\xean quan ho\u1eb7c xem x\xe9t vi\u1ec7c tr\xecnh b\xe1o.\n\nAn: C\xf2n v\u1ea5n \u0111\u1ec1 l\u1ea5y l\u1ea1i ti\u1ec1n th\xec sao?\n\nNh\xe2n vi\xean: N\u1ebfu hai b\xean kh\xf4ng th\u1ec3 th\u1ecfa thu\u1eadn, c\u0169ng c\xf3 th\u1ec3 t\xecm hi\u1ec3u c\xe1c bi\u1ec7n ph\xe1p gi\u1ea3i quy\u1ebft d\xe2n s\u1ef1 ho\u1eb7c th\u1ee7 t\u1ee5c h\xf2a gi\u1ea3i tranh ch\u1ea5p.\n\nAn: Ph\u1ee9c t\u1ea1p h\u01a1n t\xf4i ngh\u0129.\n\nNh\xe2n vi\xean: V\xe2ng. V\xec th\u1ebf trong nh\u1eefng giao d\u1ecbch quan tr\u1ecdng, vi\u1ec7c gi\u1eef n\u1ed9i dung th\u1ecfa thu\u1eadn, l\u1ecbch s\u1eed tr\xf2 chuy\u1ec7n v\xe0 t\xe0i li\u1ec7u thanh to\xe1n r\u1ea5t quan tr\u1ecdng.\n",A.hnl,A.hyt,A.hKs,A.htb)
A.fwI=s(["Hi\u1ec3u m\u1ed9t s\u1ed1 lo\u1ea1i h\xecnh nh\xe0 \u1edf th\u01b0\u1eddng g\u1eb7p t\u1ea1i H\xe0n Qu\u1ed1c.","H\u1ecdc t\u1eeb v\u1ef1ng nh\u01b0 \uc544\ud30c\ud2b8, \ub2e8\ub3c5\uc8fc\ud0dd, \uc6d0\ub8f8, \uc804\uc138 v\xe0 \uc6d4\uc138.","Hi\u1ec3u m\u1ed9t s\u1ed1 \u0111\u1eb7c \u0111i\u1ec3m sinh ho\u1ea1t trong nh\xe0 c\u1ee7a ng\u01b0\u1eddi H\xe0n.","Bi\u1ebft v\u0103n h\xf3a c\u1edfi gi\xe0y tr\u01b0\u1edbc khi v\xe0o kh\xf4ng gian sinh ho\u1ea1t trong nh\xe0.","Hi\u1ec3u vai tr\xf2 c\u1ee7a \uc628\ub3cc v\xe0 h\u1ec7 th\u1ed1ng s\u01b0\u1edfi s\xe0n.","Bi\u1ebft m\u1ed9t s\u1ed1 quy t\u1eafc khi s\u1ed1ng trong nh\xe0 \u1edf t\u1eadp th\u1ec3.","Luy\u1ec7n \u0111\u1ecdc hi\u1ec3u v\xe0 c\xe2u h\u1ecfi ki\u1ebfn th\u1ee9c x\xe3 h\u1ed9i v\u1ec1 v\u0103n h\xf3a nh\xe0 \u1edf."],t.s)
A.idq=s(["\ud55c\uad6d\uc5d0\ub294 \uc544\ud30c\ud2b8, \ub2e8\ub3c5\uc8fc\ud0dd, \ube4c\ub77c, \uc6d0\ub8f8 \ub4f1 \ub2e4\uc591\ud55c \ud615\ud0dc\uc758 \uc8fc\ud0dd\uc774 \uc788\uc2b5\ub2c8\ub2e4.","\ub3c4\uc2dc\uc5d0\uc11c\ub294 \uc544\ud30c\ud2b8\uc5d0\uc11c \uc0dd\ud65c\ud558\ub294 \uc0ac\ub78c\uc744 \ub9ce\uc774 \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ud55c\uad6d\uc5d0\uc11c\ub294 \uc9d1 \uc548\uc5d0 \ub4e4\uc5b4\uac08 \ub54c \uc2e0\ubc1c\uc744 \ubc97\ub294 \ubb38\ud654\uac00 \uc77c\ubc18\uc801\uc785\ub2c8\ub2e4.","\uc628\ub3cc \ubb38\ud654\uc758 \uc601\ud5a5\uc73c\ub85c \ubc14\ub2e5\uc5d0\uc11c \uc0dd\ud65c\ud558\ub294 \ubaa8\uc2b5\ub3c4 \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc544\ud30c\ud2b8\uc640 \uac19\uc740 \uacf5\ub3d9\uc8fc\ud0dd\uc5d0\uc11c\ub294 \uc774\uc6c3\uc744 \ubc30\ub824\ud558\ub294 \uc0dd\ud65c \ud0dc\ub3c4\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.","\ub2a6\uc740 \uc2dc\uac04\uc5d0 \ud070 \uc18c\uc74c\uc744 \ub0b4\uc9c0 \uc54a\ub3c4\ub85d \uc8fc\uc758\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","\uc4f0\ub808\uae30\ub294 \uc9c0\uc5ed\uc758 \uaddc\uce59\uc5d0 \ub530\ub77c \ubd84\ub9ac\ubc30\ucd9c\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc9d1\uc744 \uad6c\ud560 \ub54c\uc5d0\ub294 \uc704\uce58, \ubcf4\uc99d\uae08, \uc6d4\uc138, \uad00\ub9ac\ube44, \uad50\ud1b5 \ub4f1\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4."],t.s)
