A.f8q=new B.G("\u201c\ubcf4\uc99d\uae08\u201d\uc758 \ub73b\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\xdd ngh\u0129a \u0111\xfang c\u1ee7a \ubcf4\uc99d\uae08 l\xe0 g\xec?",A.hoA,0,"\ubcf4\uc99d\uae08 l\xe0 kho\u1ea3n ti\u1ec1n \u0111\u1eb7t c\u1ecdc li\xean quan \u0111\u1ebfn h\u1ee3p \u0111\u1ed3ng.")
