A.f8o=new B.G("\ub9e4\ub2ec \ub0b4\ub294 \uc9d1\uc138\uc640 \uac00\uc7a5 \uad00\ub828\uc774 \uc788\ub294 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","T\u1eeb n\xe0o li\xean quan nh\u1ea5t \u0111\u1ebfn ti\u1ec1n thu\xea nh\xe0 tr\u1ea3 h\xe0ng th\xe1ng?",A.fzS,0,"\uc6d4\uc138 l\xe0 ti\u1ec1n thu\xea nh\xe0 \u0111\u01b0\u1ee3c tr\u1ea3 theo th\xe1ng.")
