A.fmy=new B.p("\uc2dc\uccad","t\xf2a th\u1ecb ch\xednh / ch\xednh quy\u1ec1n th\xe0nh ph\u1ed1","\uc2dc\uccad\uc740 \uc2dc\uc758 \ud589\uc815 \uc5c5\ubb34\ub97c \ub2f4\ub2f9\ud569\ub2c8\ub2e4.","T\xf2a th\u1ecb ch\xednh ph\u1ee5 tr\xe1ch c\xf4ng vi\u1ec7c h\xe0nh ch\xednh c\u1ee7a th\xe0nh ph\u1ed1.")
A.fsU=new B.p("\uad6c\uccad","v\u0103n ph\xf2ng qu\u1eadn","\uad6c\uccad\uc5d0\uc11c \uc9c0\uc5ed \uad00\ub828 \ud589\uc815 \uc815\ubcf4\ub97c \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.","T\xf4i \u0111\xe3 ki\u1ec3m tra th\xf4ng tin h\xe0nh ch\xednh c\u1ee7a \u0111\u1ecba ph\u01b0\u01a1ng t\u1ea1i v\u0103n ph\xf2ng qu\u1eadn.")
