A.fb1=new B.G("\uc601\uc720\uc544\ub97c \ub3cc\ubcf4\ub294 \ub300\ud45c\uc801\uc778 \uae30\uad00\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","C\u01a1 s\u1edf ti\xeau bi\u1ec3u ch\u0103m s\xf3c tr\u1ebb nh\u1ecf l\xe0 g\xec?",A.fRz,0,"\uc5b4\ub9b0\uc774\uc9d1 l\xe0 m\u1ed9t c\u01a1 s\u1edf ti\xeau bi\u1ec3u cung c\u1ea5p d\u1ecbch v\u1ee5 ch\u0103m s\xf3c tr\u1ebb.")
