A.f61=new B.G("\uc5b4\ub9b0\uc774\uc9d1\uc744 \uc120\ud0dd\ud560 \ub54c \ud655\uc778\ud560 \ub0b4\uc6a9\uc73c\ub85c \uc54c\ub9de\uc9c0 \uc54a\uc740 \uac83\uc740?","\u0110\xe2u KH\xd4NG ph\u1ea3i n\u1ed9i dung c\u1ea7n quan t\xe2m khi l\u1ef1a ch\u1ecdn nh\xe0 tr\u1ebb?",A.fSg,3,"T\u1ed1c \u0111\u1ed9 ch\u1ea1y c\u1ee7a t\xe0u \u0111i\u1ec7n ng\u1ea7m kh\xf4ng li\xean quan \u0111\u1ebfn vi\u1ec7c l\u1ef1a ch\u1ecdn nh\xe0 tr\u1ebb.")
A.hVd=s(["\ubcf4\uc721\uae30\uad00\uc5d0 \uc54c\ub824 \uc900\ub2e4.","\uc544\ubb34\uc5d0\uac8c\ub3c4 \ub9d0\ud558\uc9c0 \uc54a\ub294\ub2e4.","\ubb34\uc870\uac74 \ub4f1\uc6d0\uc2dc\ud0a8\ub2e4.","\uc778\ud130\ub137\uc5d0\ub9cc \uae00\uc744 \uc62c\ub9b0\ub2e4."],t.s)
A.f62=new B.G("\uc544\uc774\uc758 \uac74\uac15 \uc0c1\ud0dc\uac00 \ub2ec\ub77c\uc84c\uc744 \ub54c \uc5b4\ub5bb\uac8c \ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\uae4c?","Khi t\xecnh tr\u1ea1ng s\u1ee9c kh\u1ecfe c\u1ee7a tr\u1ebb thay \u0111\u1ed5i th\xec n\xean l\xe0m g\xec?",A.hVd,0,"N\xean th\xf4ng b\xe1o cho c\u01a1 s\u1edf ch\u0103m s\xf3c tr\u1ebb \u0111\u1ec3 h\u1ecd c\xf3 th\u1ec3 ch\u0103m s\xf3c ph\xf9 h\u1ee3p.")
