A.f9e=new B.G("\u201c\ubcf4\ud638\uc790\u201d\uc758 \ub73b\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\xdd ngh\u0129a \u0111\xfang c\u1ee7a \ubcf4\ud638\uc790 l\xe0 g\xec?",A.hRu,0,"\ubcf4\ud638\uc790 l\xe0 ng\u01b0\u1eddi ch\u1ecbu tr\xe1ch nhi\u1ec7m b\u1ea3o v\u1ec7 v\xe0 ch\u0103m s\xf3c.")
A.fCW=s(["\uc11c\ub85c \uc815\ubcf4\ub97c \ub098\ub204\uace0 \ud611\ub825\ud55c\ub2e4.","\uc11c\ub85c \ub300\ud654\ud558\uc9c0 \uc54a\ub294\ub2e4.","\uc544\uc774\uc5d0 \ub300\ud55c \uc815\ubcf4\ub97c \uc228\uae34\ub2e4.","\uc11c\ub85c \uc544\ubb34 \uad00\uacc4\uac00 \uc5c6\ub2e4."],t.s)
A.f4y=new B.G("\uac00\uc815\uacfc \ubcf4\uc721\uae30\uad00\uc758 \uad00\uacc4\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","M\u1ed1i quan h\u1ec7 ph\xf9 h\u1ee3p nh\u1ea5t gi\u1eefa gia \u0111\xecnh v\xe0 c\u01a1 s\u1edf ch\u0103m s\xf3c tr\u1ebb l\xe0 g\xec?",A.fCW,0,"Gia \u0111\xecnh v\xe0 c\u01a1 s\u1edf ch\u0103m s\xf3c tr\u1ebb n\xean chia s\u1ebb th\xf4ng tin v\xe0 h\u1ee3p t\xe1c.")
A.j5t=s(["\uae30\uad00\uc774\ub098 \uc2dc\uc124\uc774 \uc6b4\uc601\ub418\ub294 \uc2dc\uac04","\uc544\uc774\uc758 \ud0a4","\ubd80\ubaa8\uc758 \uc6d4\uae09","\uc9d1\uc758 \uac00\uaca9"],t.s)
A.fbZ=new B.G("\u201c\uc6b4\uc601\uc2dc\uac04\u201d\uc758 \ub73b\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\uc6b4\uc601\uc2dc\uac04 c\xf3 ngh\u0129a l\xe0 g\xec?",A.j5t,0,"\uc6b4\uc601\uc2dc\uac04 l\xe0 kho\u1ea3ng th\u1eddi gian m\u1ed9t c\u01a1 s\u1edf ho\u1ea1t \u0111\u1ed9ng.")
A.fN0=s(["\ubcf4\uc721\uc740 \uc544\uc774\uc758 \uc131\uc7a5\uacfc \uad00\uacc4\uac00 \uc5c6\ub2e4.","\uac00\uc815\uacfc \ubcf4\uc721\uae30\uad00\uc774 \ud611\ub825\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4.","\uc5b4\ub9b0\uc774\uc9d1\uc5d0\uc11c\ub294 \uc544\uc774\ub97c \ub3cc\ubcf4\uc9c0 \uc54a\ub294\ub2e4.","\ubcf4\ud638\uc790\ub294 \uc544\uc774\uc758 \uac74\uac15 \uc815\ubcf4\ub97c \uc54c\ub824 \uc904 \ud544\uc694\uac00 \uc5c6\ub2e4."],t.s)
A.f5_=new B.G("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung ph\xf9 h\u1ee3p v\u1edbi b\xe0i \u0111\u1ecdc.",A.fN0,1,"B\xe0i \u0111\u1ecdc nh\u1ea5n m\u1ea1nh r\u1eb1ng s\u1ef1 h\u1ee3p t\xe1c gi\u1eefa gia \u0111\xecnh v\xe0 c\u01a1 s\u1edf ch\u0103m s\xf3c tr\u1ebb r\u1ea5t quan tr\u1ecdng.")
