A.ilK=s(["\uc815\ub2f9 = \u0111\u1ea3ng ch\xednh tr\u1ecb; \uc815\ubd80 = ch\xednh ph\u1ee7. Hai kh\xe1i ni\u1ec7m n\xe0y kh\xf4ng gi\u1ed1ng nhau.",u.f5,"\uc720\uad8c\uc790 = ng\u01b0\u1eddi c\xf3 quy\u1ec1n b\u1ecf phi\u1ebfu.","\ud6c4\ubcf4\uc790 = ng\u01b0\u1eddi \u1ee9ng c\u1eed.","\uacf5\uc57d = l\u1eddi cam k\u1ebft/ch\xednh s\xe1ch \u0111\u01b0a ra trong qu\xe1 tr\xecnh tranh c\u1eed.","\uc5ec\ub860 = \xfd ki\u1ebfn chung/d\u01b0 lu\u1eadn x\xe3 h\u1ed9i; \uac1c\uc778 \uc758\uacac = \xfd ki\u1ebfn c\u1ee7a m\u1ed9t c\xe1 nh\xe2n.","\uc815\uce58 \ucc38\uc5ec kh\xf4ng ch\u1ec9 c\xf3 b\u1ecf phi\u1ebfu m\xe0 c\xf2n c\xf3 nhi\u1ec1u h\xecnh th\u1ee9c tham gia h\u1ee3p ph\xe1p kh\xe1c.","\uc5b8\ub860\uc740 \uc815\ubcf4\ub97c \uc804\ub2ec\ud558\uc9c0\ub9cc ng\u01b0\u1eddi h\u1ecdc c\u0169ng c\u1ea7n ki\u1ec3m tra v\xe0 so s\xe1nh th\xf4ng tin.","\ud569\uc758 = \u0111\u1ea1t \u0111\u1ed3ng thu\u1eadn; \uc870\uc815 = \u0111i\u1ec1u ch\u1ec9nh c\xe1c \xfd ki\u1ebfn ho\u1eb7c l\u1ee3i \xedch kh\xe1c nhau."],t.s)
A.h6J=s(["\uc815\uce58\uacfc\uc815 \u2192 qu\xe1 tr\xecnh c\xe1c \xfd ki\u1ebfn v\xe0 y\xeau c\u1ea7u x\xe3 h\u1ed9i \u0111\u01b0\u1ee3c ph\u1ea3n \xe1nh v\xe0o quy\u1ebft \u0111\u1ecbnh ch\xednh tr\u1ecb.","\uc815\ub2f9 \u2192 \u0111\u1ea3ng ch\xednh tr\u1ecb.","\uc120\uac70 \u2192 ph\u01b0\u01a1ng th\u1ee9c quan tr\u1ecdng \u0111\u1ec3 l\u1ef1a ch\u1ecdn \u0111\u1ea1i di\u1ec7n.","\uc720\uad8c\uc790 \u2192 c\u1eed tri.","\ud6c4\ubcf4\uc790 \u2192 \u1ee9ng c\u1eed vi\xean.","\uacf5\uc57d \u2192 cam k\u1ebft tranh c\u1eed.","\uc2dc\ubbfc\uc740 \ub2e4\uc591\ud55c \ubc29\ubc95\uc73c\ub85c \uc815\uce58\uc640 \uc0ac\ud68c\uc5d0 \ucc38\uc5ec\ud560 \uc218 \uc788\ub2e4.","\uc5b8\ub860\uc740 \uc815\uce58\uc640 \uc0ac\ud68c \uc815\ubcf4\ub97c \uc804\ub2ec\ud558\ub294 \uc5ed\ud560\uc744 \ud55c\ub2e4.","\uc815\ubd80\uc640 \uad6d\ud68c\ub294 \ub2e4\uc591\ud55c \uc758\uacac\uc744 \uac80\ud1a0\ud574 \uc815\ucc45\uacfc \ubc95\ub960\uc5d0 \ubc18\uc601\ud560 \uc218 \uc788\ub2e4.","\ubbfc\uc8fc\uc8fc\uc758\uc5d0\uc11c\ub294 \ud1a0\ub860, \uc870\uc815, \ud569\uc758\uac00 \uc911\uc694\ud558\ub2e4.","\uc815\uce58 \ucc38\uc5ec\ub294 \ubc95\uacfc \uc808\ucc28\ub97c \uc874\uc911\ud558\uba74\uc11c \uc774\ub8e8\uc5b4\uc838\uc57c \ud55c\ub2e4."],t.s)
