A.i8T=s(["\uc120\uac70\uc5d0 \ucc38\uc5ec\ud55c\ub2e4.","\uc758\uacac\uc744 \uc81c\uc2dc\ud55c\ub2e4.","\ubc95\uc5d0 \ub530\ub77c \uccad\uc6d0\ud55c\ub2e4.","\ub2e4\ub978 \uc0ac\ub78c\uc758 \ud22c\ud45c\ub97c \uac15\uc81c\ub85c \ubc14\uafbc\ub2e4."],t.s)
A.f9g=new B.G("\uc815\uce58 \ucc38\uc5ec\uc758 \ubc29\ubc95\uc73c\ub85c \uc54c\ub9de\uc9c0 \uc54a\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110\xe2u KH\xd4NG ph\u1ea3i l\xe0 h\xecnh th\u1ee9c tham gia ch\xednh tr\u1ecb ph\xf9 h\u1ee3p?",A.i8T,3,"\xc9p bu\u1ed9c ng\u01b0\u1eddi kh\xe1c thay \u0111\u1ed5i l\xe1 phi\u1ebfu kh\xf4ng ph\u1ea3i h\xecnh th\u1ee9c tham gia d\xe2n ch\u1ee7 ph\xf9 h\u1ee3p.")
A.hpa=s(["\uc815\uce58\uc640 \uc0ac\ud68c\uc5d0 \uad00\ud55c \uc815\ubcf4\ub97c \uc804\ub2ec\ud55c\ub2e4.","\ubaa8\ub4e0 \ubc95\ub960\uc744 \uc9c1\uc811 \ub9cc\ub4e0\ub2e4.","\ubaa8\ub4e0 \uc7ac\ud310\uc744 \ub2f4\ub2f9\ud55c\ub2e4.","\ub300\ud1b5\ub839\uc744 \ud63c\uc790 \uc120\ucd9c\ud55c\ub2e4."],t.s)
A.f9K=new B.G("\uc5b8\ub860\uc758 \uc5ed\ud560\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110\xe2u l\xe0 vai tr\xf2 ph\xf9 h\u1ee3p c\u1ee7a truy\u1ec1n th\xf4ng?",A.hpa,0,"\uc5b8\ub860 c\xf3 vai tr\xf2 cung c\u1ea5p th\xf4ng tin v\u1ec1 ch\xednh tr\u1ecb v\xe0 x\xe3 h\u1ed9i.")
A.i3W=s(["\ud1a0\ub860\ud558\uace0 \uc870\uc815\ud558\uc5ec \ud569\uc758\ub97c \ucc3e\ub294\ub2e4.","\ub2e4\ub978 \uc758\uacac\uc744 \ubaa8\ub450 \ubb34\uc2dc\ud55c\ub2e4.","\ud798\uc73c\ub85c \uc790\uc2e0\uc758 \uc758\uacac\ub9cc \ub530\ub974\uac8c \ud55c\ub2e4.","\ub300\ud654\ub97c \ud558\uc9c0 \uc54a\ub294\ub2e4."],t.s)
A.fc1=new B.G("\uc11c\ub85c \ub2e4\ub978 \uc758\uacac\uc774 \ucda9\ub3cc\ud560 \ub54c \ubbfc\uc8fc\uc801\uc778 \ubc29\ubc95\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740?","Khi c\xe1c \xfd ki\u1ebfn kh\xe1c nhau xung \u0111\u1ed9t, c\xe1ch d\xe2n ch\u1ee7 ph\xf9 h\u1ee3p l\xe0 g\xec?",A.i3W,0,"Th\u1ea3o lu\u1eadn, \u0111i\u1ec1u ch\u1ec9nh v\xe0 t\xecm \u0111\u1ed3ng thu\u1eadn l\xe0 y\u1ebfu t\u1ed1 quan tr\u1ecdng c\u1ee7a qu\xe1 tr\xecnh d\xe2n ch\u1ee7.")
A.hdx=s(["\ud6c4\ubcf4\uc790\uc758 \uc815\ucc45\uacfc \uacf5\uc57d\uc744 \ud655\uc778\ud55c\ub2e4.","\uc544\ubb34 \uc815\ubcf4\ub3c4 \ud655\uc778\ud558\uc9c0 \uc54a\ub294\ub2e4.","\ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ud22c\ud45c\ub97c \uac15\uc694\ud55c\ub2e4.","\uac70\uc9d3 \uc815\ubcf4\ub9cc \ubcf4\uace0 \uacb0\uc815\ud55c\ub2e4."],t.s)
A.f9A=new B.G("\uc120\uac70\uc5d0\uc11c \ubc14\ub78c\uc9c1\ud55c \uc720\uad8c\uc790\uc758 \ud0dc\ub3c4\ub294 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Th\xe1i \u0111\u1ed9 ph\xf9 h\u1ee3p c\u1ee7a c\u1eed tri trong b\u1ea7u c\u1eed l\xe0 g\xec?",A.hdx,0,"C\u1eed tri n\xean xem x\xe9t ch\xednh s\xe1ch v\xe0 cam k\u1ebft c\u1ee7a \u1ee9ng c\u1eed vi\xean.")
A.hcS=s(["\uc815\uce58 \ucc38\uc5ec\ub294 \uc120\uac70\uc5d0\ub9cc \ud55c\uc815\ub41c\ub2e4.","\uad6d\ubbfc\uc758 \uc758\uacac\uacfc \uc694\uad6c\uac00 \uc815\uce58\uacfc\uc815\uc5d0 \ubc18\uc601\ub418\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4.","\uc815\ub2f9\uc740 \uc815\ucc45\uc744 \uc81c\uc2dc\ud558\uc9c0 \uc54a\ub294\ub2e4.","\ubbfc\uc8fc\uc8fc\uc758\uc5d0\uc11c\ub294 \uc11c\ub85c \ub2e4\ub978 \uc758\uacac\uc744 \uc870\uc815\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4."],t.s)
A.faK=new B.G("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung ph\xf9 h\u1ee3p v\u1edbi b\xe0i \u0111\u1ecdc.",A.hcS,1,"Trong n\u1ec1n d\xe2n ch\u1ee7, vi\u1ec7c \xfd ki\u1ebfn v\xe0 nguy\u1ec7n v\u1ecdng c\u1ee7a ng\u01b0\u1eddi d\xe2n \u0111\u01b0\u1ee3c ph\u1ea3n \xe1nh v\xe0o qu\xe1 tr\xecnh ch\xednh tr\u1ecb r\u1ea5t quan tr\u1ecdng.")
A.i5N=s([A.f6a,A.fc4,A.fa1,A.f91,A.fay,A.f9g,A.f9K,A.fc1,A.f9A,A.faK],t.h)
A.hyl=s(["\uc815\uce58\uacfc\uc815 = qu\xe1 tr\xecnh ch\xednh tr\u1ecb.","\uc815\ub2f9 = \u0111\u1ea3ng ch\xednh tr\u1ecb.","\uc120\uac70 = b\u1ea7u c\u1eed.","\ud22c\ud45c = b\u1ecf phi\u1ebfu.","\uc720\uad8c\uc790 = c\u1eed tri.","\ud6c4\ubcf4\uc790 = \u1ee9ng c\u1eed vi\xean.","\uacf5\uc57d = cam k\u1ebft tranh c\u1eed.","\uc5ec\ub860 = d\u01b0 lu\u1eadn.","\uc5b8\ub860 = truy\u1ec1n th\xf4ng/b\xe1o ch\xed.","\uccad\uc6d0 = ki\u1ebfn ngh\u1ecb.","\ud569\uc758 = \u0111\u1ed3ng thu\u1eadn.","\uad6d\ubbfc\uc740 \uc120\uac70\ubfd0\ub9cc \uc544\ub2c8\ub77c \ub2e4\uc591\ud55c \ubc29\ubc95\uc73c\ub85c \uc0ac\ud68c\uc5d0 \ucc38\uc5ec\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ubbfc\uc8fc\uc801\uc778 \uc815\uce58\uacfc\uc815\uc5d0\uc11c\ub294 \ud1a0\ub860, \uc870\uc815, \ud569\uc758\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.","\uc815\uce58 \ucc38\uc5ec\ub294 \ubc95\uacfc \uc808\ucc28\ub97c \uc874\uc911\ud558\uba74\uc11c \ucc45\uc784 \uc788\uac8c \ud574\uc57c \ud569\ub2c8\ub2e4."],t.s)
A.f3D=new B.dk(23,"\uc815\uce58","\ud55c\uad6d\uc758 \uc815\uce58\uacfc\uc815","Qu\xe1 tr\xecnh ch\xednh tr\u1ecb \u1edf H\xe0n Qu\u1ed1c",A.hZg,A.j5w,A.fQv,A.iWJ,"\uad6d\ubbfc\uc758 \uc758\uacac\uc774 \uc815\ucc45\uc774 \ub418\uae30\uae4c\uc9c0","\ubbfc\uc8fc\uc8fc\uc758 \uc0ac\ud68c\uc5d0\uc11c\ub294 \uad6d\ubbfc\uc758 \ub2e4\uc591\ud55c \uc758\uacac\uacfc \uc694\uad6c\uac00 \uc815\uce58\uacfc\uc815\uc5d0 \ubc18\uc601\ub418\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.\n\n\uad6d\ubbfc\uc740 \uc120\uac70\ub97c \ud1b5\ud574 \ub300\ud1b5\ub839\uc774\ub098 \uad6d\ud68c\uc758\uc6d0 \ub4f1 \uc790\uc2e0\uc758 \ub300\ud45c\uc790\ub97c \uc120\ud0dd\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc120\uac70\uc5d0 \ucc38\uc5ec\ud558\ub294 \uc720\uad8c\uc790\ub294 \ud6c4\ubcf4\uc790\uc758 \uc815\ucc45\uacfc \uacf5\uc57d\uc744 \uc0b4\ud3b4\ubcf4\uace0 \uc790\uc2e0\uc758 \uc0dd\uac01\uc5d0 \ub530\ub77c \ud22c\ud45c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc815\ub2f9\ub3c4 \uc815\uce58\uacfc\uc815\uc5d0\uc11c \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4. \uc815\ub2f9\uc740 \ube44\uc2b7\ud55c \uc815\uce58\uc801 \uc0dd\uac01\uc744 \uac00\uc9c4 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc778 \uc870\uc9c1\uc774\uba70 \ub2e4\uc591\ud55c \uc815\ucc45\uc744 \uad6d\ubbfc\uc5d0\uac8c \uc81c\uc2dc\ud569\ub2c8\ub2e4.\n\n\uc2dc\ubbfc\uc740 \uc120\uac70\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc5ec\ub7ec \ubc29\ubc95\uc73c\ub85c \uc0ac\ud68c \ubb38\uc81c\uc5d0 \ucc38\uc5ec\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc790\uc2e0\uc758 \uc758\uacac\uc744 \uad00\ub828 \uae30\uad00\uc5d0 \uc804\ub2ec\ud558\uac70\ub098 \uccad\uc6d0\uc744 \ud560 \uc218 \uc788\uace0 \ubc95\uc774 \uc815\ud55c \ubc94\uc704 \uc548\uc5d0\uc11c \uc9d1\ud68c \ub4f1\uc5d0 \ucc38\uc5ec\ud558\uae30\ub3c4 \ud569\ub2c8\ub2e4.\n\n\uc5b8\ub860\uc740 \uc815\uce58\uc640 \uc0ac\ud68c\uc5d0 \uad00\ud55c \uc815\ubcf4\ub97c \uad6d\ubbfc\uc5d0\uac8c \uc804\ub2ec\ud558\uace0 \uc5ec\ub7ec \uc758\uacac\uc744 \uc18c\uac1c\ud558\ub294 \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4.\n\n\uc815\ubd80\uc640 \uad6d\ud68c\ub294 \uad6d\ubbfc\uc758 \uc694\uad6c, \uc0ac\ud68c \uc0c1\ud669, \uc804\ubb38\uac00 \uc758\uacac \ub4f1 \uc5ec\ub7ec \ub0b4\uc6a9\uc744 \uac80\ud1a0\ud558\uba74\uc11c \uc815\ucc45\uacfc \ubc95\ub960\uc744 \ub9cc\ub4e4\uac70\ub098 \uc218\uc815\ud569\ub2c8\ub2e4.\n\n\uc774 \uacfc\uc815\uc5d0\uc11c\ub294 \uc11c\ub85c \ub2e4\ub978 \uc774\ud574\uad00\uacc4\uc640 \uc758\uacac\uc774 \ucda9\ub3cc\ud560 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \ucda9\ubd84\ud55c \ud1a0\ub860\uacfc \uc870\uc815\uc744 \ud1b5\ud574 \ud569\uc758\ub97c \ucc3e\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.\n\n\ubbfc\uc8fc\uc801\uc778 \uc815\uce58\uacfc\uc815\uc774 \uc798 \uc774\ub8e8\uc5b4\uc9c0\uae30 \uc704\ud574\uc11c\ub294 \uad6d\ubbfc\ub3c4 \uc815\ud655\ud55c \uc815\ubcf4\ub97c \ud655\uc778\ud558\uace0 \ubc95\uacfc \uc808\ucc28\ub97c \uc874\uc911\ud558\uba74\uc11c \ucc45\uc784 \uc788\uac8c \ucc38\uc5ec\ud574\uc57c \ud569\ub2c8\ub2e4.\n","Trong x\xe3 h\u1ed9i d\xe2n ch\u1ee7, vi\u1ec7c c\xe1c \xfd ki\u1ebfn v\xe0 nguy\u1ec7n v\u1ecdng \u0111a d\u1ea1ng c\u1ee7a ng\u01b0\u1eddi d\xe2n \u0111\u01b0\u1ee3c ph\u1ea3n \xe1nh v\xe0o qu\xe1 tr\xecnh ch\xednh tr\u1ecb l\xe0 \u0111i\u1ec1u quan tr\u1ecdng.\n\nNg\u01b0\u1eddi d\xe2n c\xf3 th\u1ec3 l\u1ef1a ch\u1ecdn \u0111\u1ea1i di\u1ec7n c\u1ee7a m\xecnh nh\u01b0 T\u1ed5ng th\u1ed1ng ho\u1eb7c ngh\u1ecb s\u0129 Qu\u1ed1c h\u1ed9i th\xf4ng qua b\u1ea7u c\u1eed. C\u1eed tri tham gia b\u1ea7u c\u1eed c\xf3 th\u1ec3 xem x\xe9t ch\xednh s\xe1ch v\xe0 cam k\u1ebft c\u1ee7a c\xe1c \u1ee9ng c\u1eed vi\xean r\u1ed3i b\u1ecf phi\u1ebfu theo suy ngh\u0129 c\u1ee7a m\xecnh.\n\nC\xe1c \u0111\u1ea3ng ch\xednh tr\u1ecb c\u0169ng \u0111\xf3ng vai tr\xf2 quan tr\u1ecdng trong qu\xe1 tr\xecnh ch\xednh tr\u1ecb. \u0110\u1ea3ng ch\xednh tr\u1ecb l\xe0 t\u1ed5 ch\u1ee9c g\u1ed3m nh\u1eefng ng\u01b0\u1eddi c\xf3 quan \u0111i\u1ec3m ch\xednh tr\u1ecb t\u01b0\u01a1ng t\u1ef1 v\xe0 \u0111\u01b0a ra nhi\u1ec1u ch\xednh s\xe1ch cho ng\u01b0\u1eddi d\xe2n.\n\nNg\u01b0\u1eddi d\xe2n c\xf3 th\u1ec3 tham gia c\xe1c v\u1ea5n \u0111\u1ec1 x\xe3 h\u1ed9i b\u1eb1ng nhi\u1ec1u c\xe1ch kh\xe1c ngo\xe0i b\u1ea7u c\u1eed. H\u1ecd c\xf3 th\u1ec3 g\u1eedi \xfd ki\u1ebfn \u0111\u1ebfn c\u01a1 quan li\xean quan, g\u1eedi ki\u1ebfn ngh\u1ecb ho\u1eb7c tham gia c\xe1c cu\u1ed9c t\u1eadp h\u1ee3p trong ph\u1ea1m vi ph\xe1p lu\u1eadt quy \u0111\u1ecbnh.\n\nTruy\u1ec1n th\xf4ng c\xf3 vai tr\xf2 cung c\u1ea5p th\xf4ng tin v\u1ec1 ch\xednh tr\u1ecb v\xe0 x\xe3 h\u1ed9i cho ng\u01b0\u1eddi d\xe2n c\u0169ng nh\u01b0 gi\u1edbi thi\u1ec7u nhi\u1ec1u quan \u0111i\u1ec3m kh\xe1c nhau.\n\nCh\xednh ph\u1ee7 v\xe0 Qu\u1ed1c h\u1ed9i xem x\xe9t nhi\u1ec1u y\u1ebfu t\u1ed1 nh\u01b0 nguy\u1ec7n v\u1ecdng c\u1ee7a ng\u01b0\u1eddi d\xe2n, t\xecnh h\xecnh x\xe3 h\u1ed9i v\xe0 \xfd ki\u1ebfn chuy\xean gia \u0111\u1ec3 x\xe2y d\u1ef1ng ho\u1eb7c s\u1eeda \u0111\u1ed5i ch\xednh s\xe1ch v\xe0 ph\xe1p lu\u1eadt.\n\nTrong qu\xe1 tr\xecnh n\xe0y, nh\u1eefng l\u1ee3i \xedch v\xe0 \xfd ki\u1ebfn kh\xe1c nhau c\xf3 th\u1ec3 xung \u0111\u1ed9t. V\xec v\u1eady, vi\u1ec7c t\xecm ki\u1ebfm s\u1ef1 \u0111\u1ed3ng thu\u1eadn th\xf4ng qua th\u1ea3o lu\u1eadn v\xe0 \u0111i\u1ec1u ch\u1ec9nh \u0111\u1ea7y \u0111\u1ee7 l\xe0 r\u1ea5t quan tr\u1ecdng.\n\n\u0110\u1ec3 qu\xe1 tr\xecnh ch\xednh tr\u1ecb d\xe2n ch\u1ee7 ho\u1ea1t \u0111\u1ed9ng t\u1ed1t, ng\u01b0\u1eddi d\xe2n c\u0169ng c\u1ea7n ki\u1ec3m tra th\xf4ng tin ch\xednh x\xe1c, t\xf4n tr\u1ecdng ph\xe1p lu\u1eadt v\xe0 th\u1ee7 t\u1ee5c, \u0111\u1ed3ng th\u1eddi tham gia m\u1ed9t c\xe1ch c\xf3 tr\xe1ch nhi\u1ec7m.\n","\uc120\uac70\uc5d0\uc11c \ud6c4\ubcf4\uc790 \ube44\uad50\ud558\uae30","\uc548: \ubbfc\uc218 \uc528, \uc120\uac70\ud560 \ub54c \ud6c4\ubcf4\uc790\ub294 \uc5b4\ub5bb\uac8c \uc120\ud0dd\ud574\uc694?\n\n\ubbfc\uc218: \uc800\ub294 \uba3c\uc800 \ud6c4\ubcf4\uc790\uc758 \uc815\ucc45\uacfc \uacf5\uc57d\uc744 \ud655\uc778\ud574\uc694.\n\n\uc548: \uacf5\uc57d\uc774 \ubb50\uc608\uc694?\n\n\ubbfc\uc218: \ud6c4\ubcf4\uc790\uac00 \uc120\uac70\uc5d0\uc11c \uad6d\ubbfc\uc5d0\uac8c \uc57d\uc18d\ud558\ub294 \uc815\ucc45\uc774\ub098 \uacc4\ud68d\uc774\uc5d0\uc694.\n\n\uc548: \uc778\ud130\ub137\uc5d0 \uc815\ubcf4\uac00 \uc815\ub9d0 \ub9ce\uc740\ub370 \ubb34\uc5c7\uc744 \ubbff\uc5b4\uc57c \ud560\uc9c0 \uc5b4\ub835\ub354\ub77c\uace0\uc694.\n\n\ubbfc\uc218: \ub9de\uc544\uc694. \uadf8\ub798\uc11c \ud55c \uacf3\uc758 \uc815\ubcf4\ub9cc \ubcf4\uc9c0 \ub9d0\uace0 \uc5ec\ub7ec \uc790\ub8cc\ub97c \ube44\uad50\ud558\ub294 \uac83\uc774 \uc88b\uc544\uc694.\n\n\uc548: \uc815\ub2f9\uc758 \uc815\ucc45\ub3c4 \ud655\uc778\ud574\uc57c\uaca0\ub124\uc694.\n\n\ubbfc\uc218: \ub124. \ud6c4\ubcf4\uc790\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc815\ub2f9\uc774 \uc5b4\ub5a4 \uc815\ucc45\uc744 \uac00\uc9c0\uace0 \uc788\ub294\uc9c0\ub3c4 \ubcfc \uc218 \uc788\uc5b4\uc694.\n\n\uc548: \ud22c\ud45c\uac00 \ub05d\ub098\uba74 \uc2dc\ubbfc\uc758 \uc5ed\ud560\ub3c4 \ub05d\ub098\ub294 \uac74\uac00\uc694?\n\n\ubbfc\uc218: \uc544\ub2c8\uc694. \uc0ac\ud68c \ubb38\uc81c\uc5d0 \uad00\uc2ec\uc744 \uac00\uc9c0\uace0 \uc758\uacac\uc744 \ud45c\ud604\ud558\ub294 \uac83\ub3c4 \uc911\uc694\ud574\uc694.\n\n\uc548: \uc815\uce58 \ucc38\uc5ec\uc5d0\ub294 \uc5ec\ub7ec \ubc29\ubc95\uc774 \uc788\uad70\uc694.\n\n\ubbfc\uc218: \ub9de\uc544\uc694. \ub2e4\ub9cc \ubc95\uacfc \uc808\ucc28\ub97c \uc9c0\ud0a4\uba74\uc11c \ucc45\uc784 \uc788\uac8c \ucc38\uc5ec\ud574\uc57c \ud574\uc694.\n","An: Minsu, khi b\u1ea7u c\u1eed anh ch\u1ecdn \u1ee9ng c\u1eed vi\xean nh\u01b0 th\u1ebf n\xe0o?\n\nMinsu: Tr\u01b0\u1edbc ti\xean t\xf4i ki\u1ec3m tra ch\xednh s\xe1ch v\xe0 cam k\u1ebft c\u1ee7a \u1ee9ng c\u1eed vi\xean.\n\nAn: \uacf5\uc57d l\xe0 g\xec?\n\nMinsu: L\xe0 ch\xednh s\xe1ch ho\u1eb7c k\u1ebf ho\u1ea1ch m\xe0 \u1ee9ng c\u1eed vi\xean h\u1ee9a v\u1edbi ng\u01b0\u1eddi d\xe2n trong b\u1ea7u c\u1eed.\n\nAn: Tr\xean Internet c\xf3 qu\xe1 nhi\u1ec1u th\xf4ng tin n\xean t\xf4i th\u1ea5y kh\xf3 bi\u1ebft n\xean tin g\xec.\n\nMinsu: \u0110\xfang v\u1eady. V\xec th\u1ebf t\u1ed1t nh\u1ea5t kh\xf4ng ch\u1ec9 xem th\xf4ng tin t\u1eeb m\u1ed9t n\u01a1i m\xe0 n\xean so s\xe1nh nhi\u1ec1u ngu\u1ed3n.\n\nAn: V\u1eady c\u0169ng c\u1ea7n xem ch\xednh s\xe1ch c\u1ee7a \u0111\u1ea3ng \u0111\xfang kh\xf4ng?\n\nMinsu: \u0110\xfang. Ngo\xe0i \u1ee9ng c\u1eed vi\xean, c\xf3 th\u1ec3 xem \u0111\u1ea3ng \u0111\xf3 c\xf3 nh\u1eefng ch\xednh s\xe1ch g\xec.\n\nAn: Sau khi b\u1ecf phi\u1ebfu th\xec vai tr\xf2 c\u1ee7a ng\u01b0\u1eddi d\xe2n k\u1ebft th\xfac \xe0?\n\nMinsu: Kh\xf4ng. Quan t\xe2m \u0111\u1ebfn v\u1ea5n \u0111\u1ec1 x\xe3 h\u1ed9i v\xe0 th\u1ec3 hi\u1ec7n \xfd ki\u1ebfn c\u0169ng r\u1ea5t quan tr\u1ecdng.\n\nAn: V\u1eady c\xf3 nhi\u1ec1u c\xe1ch \u0111\u1ec3 tham gia ch\xednh tr\u1ecb.\n\nMinsu: \u0110\xfang v\u1eady. Tuy nhi\xean c\u1ea7n tham gia c\xf3 tr\xe1ch nhi\u1ec7m v\xe0 tu\xe2n th\u1ee7 ph\xe1p lu\u1eadt, th\u1ee7 t\u1ee5c.\n",A.ilK,A.h6J,A.i5N,A.hyl)
A.iRb=s(["Hi\u1ec3u c\xe1c h\xecnh th\u1ee9c gia \u0111\xecnh ph\u1ed5 bi\u1ebfn trong x\xe3 h\u1ed9i H\xe0n Qu\u1ed1c.","Ph\xe2n bi\u1ec7t \ub300\uac00\uc871, \ud575\uac00\uc871 v\xe0 1\uc778 \uac00\uad6c.","H\u1ecdc t\u1eeb v\u1ef1ng v\u1ec1 th\xe0nh vi\xean v\xe0 quan h\u1ec7 gia \u0111\xecnh.","Hi\u1ec3u s\u1ef1 thay \u0111\u1ed5i c\u1ee7a gia \u0111\xecnh H\xe0n Qu\u1ed1c theo x\xe3 h\u1ed9i hi\u1ec7n \u0111\u1ea1i.","C\xf3 th\u1ec3 \u0111\u1ecdc v\xe0 tr\u1ea3 l\u1eddi c\xe2u h\u1ecfi v\u1ec1 gia \u0111\xecnh.","Bi\u1ebft c\xe1ch d\xf9ng c\xe1c c\xe2u ti\u1ebfng H\xe0n th\u01b0\u1eddng g\u1eb7p khi n\xf3i v\u1ec1 gia \u0111\xecnh."],t.s)
