A.ipk=s(["\ub300\uac00\uc871 = gia \u0111\xecnh nhi\u1ec1u th\u1ebf h\u1ec7.","\ud575\uac00\uc871 = gia \u0111\xecnh h\u1ea1t nh\xe2n, ch\u1ee7 y\u1ebfu g\u1ed3m cha m\u1eb9 v\xe0 con c\xe1i.","1\uc778 \uac00\uad6c = h\u1ed9 gia \u0111\xecnh c\xf3 m\u1ed9t ng\u01b0\u1eddi sinh s\u1ed1ng.","1\uc778 \uac00\uad6c kh\xf4ng nh\u1ea5t thi\u1ebft c\xf3 ngh\u0129a l\xe0 ng\u01b0\u1eddi ch\u01b0a k\u1ebft h\xf4n.","\ubd80\ubd80 = v\u1ee3 ch\u1ed3ng; \ubd80\ubaa8 = cha m\u1eb9; \uc790\ub140 = con c\xe1i.","\uac00\uc0ac trong b\xe0i n\xe0y c\xf3 ngh\u0129a l\xe0 vi\u1ec7c nh\xe0.","\uc721\uc544 = ch\u0103m s\xf3c v\xe0 nu\xf4i d\u1ea1y con.","\ub9de\ubc8c\uc774 = c\u1ea3 v\u1ee3 v\xe0 ch\u1ed3ng c\xf9ng \u0111i l\xe0m."],t.s)
A.fHU=s(["\ub300\uac00\uc871 \u2192 nhi\u1ec1u th\u1ebf h\u1ec7 s\u1ed1ng c\xf9ng nhau.","\ud575\uac00\uc871 \u2192 cha m\u1eb9 v\xe0 con c\xe1i l\xe0 trung t\xe2m.","1\uc778 \uac00\uad6c \u2192 h\u1ed9 gia \u0111\xecnh m\u1ed9t ng\u01b0\u1eddi.","\ub9de\ubc8c\uc774 \u2192 c\u1ea3 v\u1ee3 v\xe0 ch\u1ed3ng c\xf9ng \u0111i l\xe0m.","\uac00\uc0ac \u2192 vi\u1ec7c nh\xe0.","\uc721\uc544 \u2192 ch\u0103m s\xf3c, nu\xf4i d\u1ea1y con.","\uc0b0\uc5c5\ud654\uc640 \ub3c4\uc2dc\ud654 \u2192 c\xf3 li\xean quan \u0111\u1ebfn s\u1ef1 thay \u0111\u1ed5i h\xecnh th\u1ee9c gia \u0111\xecnh.","Gia \u0111\xecnh H\xe0n Qu\u1ed1c hi\u1ec7n \u0111\u1ea1i ng\xe0y c\xe0ng \u0111a d\u1ea1ng.","T\xf4n tr\u1ecdng v\xe0 chia s\u1ebb tr\xe1ch nhi\u1ec7m l\xe0 y\u1ebfu t\u1ed1 quan tr\u1ecdng trong gia \u0111\xecnh."],t.s)
