A.f7k=new B.G("\uc678\uad6d\uc5d0\uc11c \ud544\uc694\ud55c \uc0c1\ud488\uc744 \ub4e4\uc5ec\uc624\ub294 \uac83\uc744 \ubb34\uc5c7\uc774\ub77c\uace0 \ud569\ub2c8\uae4c?","Vi\u1ec7c \u0111\u01b0a h\xe0ng h\xf3a c\u1ea7n thi\u1ebft t\u1eeb n\u01b0\u1edbc ngo\xe0i v\xe0o g\u1ecdi l\xe0 g\xec?",A.fYU,0,"\uc218\uc785 = nh\u1eadp kh\u1ea9u.")
A.hsz=s(["\uc720\uc5d4","\ud55c \ud68c\uc0ac","\ud55c \ud559\uad50","\uc544\ud30c\ud2b8 \uad00\ub9ac\uc0ac\ubb34\uc18c"],t.s)
A.fbo=new B.G("\ub2e4\uc74c \uc911 \ub300\ud45c\uc801\uc778 \uad6d\uc81c\uae30\uad6c\ub294 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110\xe2u l\xe0 m\u1ed9t t\u1ed5 ch\u1ee9c qu\u1ed1c t\u1ebf ti\xeau bi\u1ec3u?",A.hsz,0,"\uc720\uc5d4 l\xe0 m\u1ed9t t\u1ed5 ch\u1ee9c qu\u1ed1c t\u1ebf ti\xeau bi\u1ec3u.")
