A.f9l=new B.G("\ud55c\uad6d\uc774 \ud574\uc678\uc5d0\uc11c \uc218\uc785\ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc740 \uac83\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740?","\u0110\xe2u l\xe0 th\u1ee9 H\xe0n Qu\u1ed1c th\u01b0\u1eddng c\u1ea7n nh\u1eadp kh\u1ea9u t\u1eeb n\u01b0\u1edbc ngo\xe0i?",A.fX1,0,"Nguy\xean v\u1eadt li\u1ec7u v\xe0 n\u0103ng l\u01b0\u1ee3ng l\xe0 nh\u1eefng m\u1eb7t h\xe0ng c\xf3 th\u1ec3 c\u1ea7n nh\u1eadp kh\u1ea9u.")
A.fQS=s(["\uc218\ucd9c\uc774 \uc601\ud5a5\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4.","\ud55c\uad6d \uacbd\uc81c\uc5d0\ub294 \uc808\ub300 \uc601\ud5a5\uc774 \uc5c6\ub2e4.","\ubaa8\ub4e0 \uc218\uc785 \uac00\uaca9\uc774 \ud56d\uc0c1 \uac19\uc544\uc9c4\ub2e4.","\ubaa8\ub4e0 \uae30\uc5c5\uc758 \ub9e4\ucd9c\uc774 \uc790\ub3d9\uc73c\ub85c \uc99d\uac00\ud55c\ub2e4."],t.s)
A.f9E=new B.G("\uc138\uacc4\uacbd\uc81c\uac00 \uc5b4\ub824\uc6cc\uc9c0\uba74 \ud55c\uad6d\uc5d0 \uc5b4\ub5a4 \uc601\ud5a5\uc774 \uc788\uc744 \uc218 \uc788\uc2b5\ub2c8\uae4c?","N\u1ebfu kinh t\u1ebf th\u1ebf gi\u1edbi g\u1eb7p kh\xf3 kh\u0103n th\xec H\xe0n Qu\u1ed1c c\xf3 th\u1ec3 ch\u1ecbu \u1ea3nh h\u01b0\u1edfng n\xe0o?",A.fQS,0,"Khi nhu c\u1ea7u qu\u1ed1c t\u1ebf gi\u1ea3m, xu\u1ea5t kh\u1ea9u c\u1ee7a H\xe0n Qu\u1ed1c c\xf3 th\u1ec3 b\u1ecb \u1ea3nh h\u01b0\u1edfng.")
A.ic6=s(["\ud55c\uad6d\uc740 \uc218\ucd9c\uacfc \uc218\uc785\uc744 \ud1b5\ud574 \uc138\uacc4\uacbd\uc81c\uc640 \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4.","FTA\ub294 \ubb34\uc5ed\uc744 \uc644\uc804\ud788 \uc911\ub2e8\ud558\uae30 \uc704\ud55c \ud611\uc815\uc774\ub2e4.","\ud658\uc728\uc740 \uc218\ucd9c\uc785\uacfc \uc544\ubb34 \uad00\uacc4\uac00 \uc5c6\ub2e4.","\uc138\uacc4\uc2dc\uc7a5\uc5d0\uc11c\ub294 \uae30\uc5c5 \uac04 \uacbd\uc7c1\uc774 \uc5c6\ub2e4."],t.s)
A.f8_=new B.G("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung ph\xf9 h\u1ee3p v\u1edbi b\xe0i \u0111\u1ecdc.",A.ic6,0,"Xu\u1ea5t nh\u1eadp kh\u1ea9u l\xe0 m\u1ed9t trong nh\u1eefng y\u1ebfu t\u1ed1 k\u1ebft n\u1ed1i kinh t\u1ebf H\xe0n Qu\u1ed1c v\u1edbi kinh t\u1ebf th\u1ebf gi\u1edbi.")
A.fY6=s([A.faz,A.fav,A.f6P,A.f4P,A.faI,A.f4N,A.f9W,A.f9l,A.f9E,A.f8_],t.h)
A.hHs=s(["\ud55c\uad6d \uacbd\uc81c\ub294 \uc138\uacc4\uacbd\uc81c\uc640 \ubc00\uc811\ud558\uac8c \uc5f0\uacb0\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.","\ubb34\uc5ed = th\u01b0\u01a1ng m\u1ea1i.","\uc218\ucd9c = xu\u1ea5t kh\u1ea9u.","\uc218\uc785 = nh\u1eadp kh\u1ea9u.","\ubc18\ub3c4\uccb4 = ch\u1ea5t b\xe1n d\u1eabn.","\uc6d0\uc790\uc7ac = nguy\xean v\u1eadt li\u1ec7u.","\ud658\uc728 = t\u1ef7 gi\xe1.","FTA = \uc790\uc720\ubb34\uc5ed\ud611\uc815.","\uad00\uc138 = thu\u1ebf quan.","\uc138\uacc4\uc2dc\uc7a5\uc5d0\uc11c\ub294 \uacbd\uc7c1\ub825\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\uae30\uc220\uacfc \ud488\uc9c8\uc740 \uae30\uc5c5 \uacbd\uc7c1\ub825\uc744 \ub192\uc774\ub294 \uc911\uc694\ud55c \uc694\uc18c\uc785\ub2c8\ub2e4.","\uc138\uacc4\uacbd\uc81c\uc758 \ubcc0\ud654\ub294 \ud55c\uad6d\uc758 \uc218\ucd9c\uacfc \uae30\uc5c5 \ud65c\ub3d9\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],t.s)
A.f3G=new B.dk(26,"\uacbd\uc81c","\ud55c\uad6d \uacbd\uc81c\uc640 \uc138\uacc4","Kinh t\u1ebf H\xe0n Qu\u1ed1c v\xe0 th\u1ebf gi\u1edbi",A.fBM,A.j4Z,A.fPm,A.iVt,"\uc138\uacc4\uc640 \uc5f0\uacb0\ub41c \ud55c\uad6d \uacbd\uc81c","\uc624\ub298\ub0a0 \ud55c\uad6d \uacbd\uc81c\ub294 \uc138\uacc4 \uc5ec\ub7ec \ub098\ub77c\uc758 \uacbd\uc81c\uc640 \ubc00\uc811\ud558\uac8c \uc5f0\uacb0\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ud55c\uad6d\uc740 \uc790\ub3d9\ucc28, \ubc18\ub3c4\uccb4, \uc804\uc790\uc81c\ud488, \uc120\ubc15 \ub4f1 \ub2e4\uc591\ud55c \uc81c\ud488\uc744 \ud574\uc678\uc2dc\uc7a5\uc5d0 \uc218\ucd9c\ud569\ub2c8\ub2e4. \ubc18\ub300\ub85c \uad6d\ub0b4 \uc0b0\uc5c5\uacfc \uc0dd\ud65c\uc5d0 \ud544\uc694\ud55c \uc6d0\uc790\uc7ac, \uc5d0\ub108\uc9c0, \uc0c1\ud488 \ub4f1\uc744 \uc678\uad6d\uc5d0\uc11c \uc218\uc785\ud558\uae30\ub3c4 \ud569\ub2c8\ub2e4.\n\n\ub530\ub77c\uc11c \uc138\uacc4\uacbd\uc81c\uc758 \ubcc0\ud654\ub294 \ud55c\uad6d \uacbd\uc81c\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub2e4\ub978 \ub098\ub77c\uc758 \uacbd\uc81c\uac00 \uc5b4\ub824\uc6cc\uc838 \ud55c\uad6d \uc81c\ud488\uc5d0 \ub300\ud55c \uc218\uc694\uac00 \uac10\uc18c\ud558\uba74 \uc218\ucd9c \uae30\uc5c5\uc774 \uc601\ud5a5\uc744 \ubc1b\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ud658\uc728\ub3c4 \uc911\uc694\ud55c \uc694\uc18c\uc785\ub2c8\ub2e4. \ud658\uc728\uc774 \ubcc0\ud558\uba74 \ud574\uc678\uc5d0\uc11c \ud310\ub9e4\ud558\ub294 \uc81c\ud488\uc758 \uac00\uaca9\uc774\ub098 \uc678\uad6d\uc5d0\uc11c \uc218\uc785\ud558\ub294 \uc0c1\ud488\uc758 \uac00\uaca9\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\n\n\uad6d\uac00\ub4e4\uc740 \ubb34\uc5ed\uc744 \ud655\ub300\ud558\uae30 \uc704\ud574 \uc790\uc720\ubb34\uc5ed\ud611\uc815\uc744 \uccb4\uacb0\ud558\uae30\ub3c4 \ud569\ub2c8\ub2e4. \uc790\uc720\ubb34\uc5ed\ud611\uc815\uc740 FTA\ub77c\uace0 \ud558\uba70 \uad6d\uac00 \uac04 \uc0c1\ud488\uacfc \uc11c\ube44\uc2a4\uc758 \uac70\ub798\ub97c \ub354 \ud65c\ubc1c\ud558\uac8c \ud558\uae30 \uc704\ud55c \ud611\uc815\uc785\ub2c8\ub2e4.\n\n\uc138\uacc4\uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc5ec\ub7ec \ub098\ub77c\uc758 \uae30\uc5c5\uc774 \uacbd\uc7c1\ud569\ub2c8\ub2e4. \ub530\ub77c\uc11c \ud55c\uad6d \uae30\uc5c5\ub4e4\ub3c4 \uae30\uc220\uc744 \uac1c\ubc1c\ud558\uace0 \uc81c\ud488\uc758 \ud488\uc9c8\uc744 \ub192\uc774\uba70 \uacbd\uc7c1\ub825\uc744 \uac15\ud654\ud558\ub824\uace0 \ub178\ub825\ud569\ub2c8\ub2e4.\n\n\uc138\uacc4\ud654\uac00 \uc9c4\ud589\ub418\uba74\uc11c \ud55c \ub098\ub77c\uc758 \uacbd\uc81c \uc0c1\ud669\uc774 \ub2e4\ub978 \ub098\ub77c\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\ub3c4 \ucee4\uc84c\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \ud55c\uad6d \uacbd\uc81c\ub97c \uc774\ud574\ud558\uae30 \uc704\ud574\uc11c\ub294 \uad6d\ub0b4 \uacbd\uc81c\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc138\uacc4\uacbd\uc81c\uc758 \ubcc0\ud654\ub3c4 \ud568\uaed8 \uc0b4\ud3b4\ubcfc \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.\n","Ng\xe0y nay, n\u1ec1n kinh t\u1ebf H\xe0n Qu\u1ed1c c\xf3 m\u1ed1i li\xean h\u1ec7 ch\u1eb7t ch\u1ebd v\u1edbi n\u1ec1n kinh t\u1ebf c\u1ee7a nhi\u1ec1u qu\u1ed1c gia tr\xean th\u1ebf gi\u1edbi.\n\nH\xe0n Qu\u1ed1c xu\u1ea5t kh\u1ea9u nhi\u1ec1u s\u1ea3n ph\u1ea9m nh\u01b0 \xf4 t\xf4, ch\u1ea5t b\xe1n d\u1eabn, s\u1ea3n ph\u1ea9m \u0111i\u1ec7n t\u1eed v\xe0 t\xe0u bi\u1ec3n ra th\u1ecb tr\u01b0\u1eddng qu\u1ed1c t\u1ebf. Ng\u01b0\u1ee3c l\u1ea1i, n\u01b0\u1edbc n\xe0y c\u0169ng nh\u1eadp kh\u1ea9u nguy\xean v\u1eadt li\u1ec7u, n\u0103ng l\u01b0\u1ee3ng v\xe0 h\xe0ng h\xf3a c\u1ea7n thi\u1ebft cho s\u1ea3n xu\u1ea5t v\xe0 \u0111\u1eddi s\u1ed1ng.\n\nV\xec v\u1eady nh\u1eefng thay \u0111\u1ed5i c\u1ee7a kinh t\u1ebf th\u1ebf gi\u1edbi c\xf3 th\u1ec3 \u1ea3nh h\u01b0\u1edfng \u0111\u1ebfn kinh t\u1ebf H\xe0n Qu\u1ed1c. N\u1ebfu n\u1ec1n kinh t\u1ebf c\u1ee7a m\u1ed9t qu\u1ed1c gia kh\xe1c g\u1eb7p kh\xf3 kh\u0103n v\xe0 nhu c\u1ea7u \u0111\u1ed1i v\u1edbi s\u1ea3n ph\u1ea9m H\xe0n Qu\u1ed1c gi\u1ea3m, c\xe1c doanh nghi\u1ec7p xu\u1ea5t kh\u1ea9u c\xf3 th\u1ec3 b\u1ecb \u1ea3nh h\u01b0\u1edfng.\n\nT\u1ef7 gi\xe1 c\u0169ng l\xe0 m\u1ed9t y\u1ebfu t\u1ed1 quan tr\u1ecdng. Khi t\u1ef7 gi\xe1 thay \u0111\u1ed5i, gi\xe1 s\u1ea3n ph\u1ea9m b\xe1n \u1edf n\u01b0\u1edbc ngo\xe0i ho\u1eb7c gi\xe1 h\xe0ng h\xf3a nh\u1eadp kh\u1ea9u c\xf3 th\u1ec3 thay \u0111\u1ed5i.\n\nC\xe1c qu\u1ed1c gia c\u0169ng c\xf3 th\u1ec3 k\xfd k\u1ebft hi\u1ec7p \u0111\u1ecbnh th\u01b0\u01a1ng m\u1ea1i t\u1ef1 do \u0111\u1ec3 m\u1edf r\u1ed9ng th\u01b0\u01a1ng m\u1ea1i. Hi\u1ec7p \u0111\u1ecbnh th\u01b0\u01a1ng m\u1ea1i t\u1ef1 do g\u1ecdi l\xe0 FTA v\xe0 nh\u1eb1m th\xfac \u0111\u1ea9y giao d\u1ecbch h\xe0ng h\xf3a v\xe0 d\u1ecbch v\u1ee5 gi\u1eefa c\xe1c qu\u1ed1c gia.\n\nTr\xean th\u1ecb tr\u01b0\u1eddng th\u1ebf gi\u1edbi, doanh nghi\u1ec7p c\u1ee7a nhi\u1ec1u qu\u1ed1c gia c\u1ea1nh tranh v\u1edbi nhau. V\xec v\u1eady c\xe1c doanh nghi\u1ec7p H\xe0n Qu\u1ed1c c\u0169ng n\u1ed7 l\u1ef1c ph\xe1t tri\u1ec3n c\xf4ng ngh\u1ec7, n\xe2ng cao ch\u1ea5t l\u01b0\u1ee3ng s\u1ea3n ph\u1ea9m v\xe0 t\u0103ng s\u1ee9c c\u1ea1nh tranh.\n\nKhi to\xe0n c\u1ea7u h\xf3a ph\xe1t tri\u1ec3n, \u1ea3nh h\u01b0\u1edfng c\u1ee7a t\xecnh h\xecnh kinh t\u1ebf m\u1ed9t n\u01b0\u1edbc \u0111\u1ed1i v\u1edbi c\xe1c n\u01b0\u1edbc kh\xe1c c\u0169ng t\u0103ng l\xean. V\xec v\u1eady \u0111\u1ec3 hi\u1ec3u kinh t\u1ebf H\xe0n Qu\u1ed1c, c\u1ea7n xem x\xe9t kh\xf4ng ch\u1ec9 kinh t\u1ebf trong n\u01b0\u1edbc m\xe0 c\u1ea3 nh\u1eefng thay \u0111\u1ed5i c\u1ee7a kinh t\u1ebf th\u1ebf gi\u1edbi.\n","\ud658\uc728\uacfc \uc218\ucd9c\uc5d0 \ub300\ud574 \uc774\uc57c\uae30\ud558\uae30","\uc548: \ubbfc\uc218 \uc528, \ub274\uc2a4\uc5d0\uc11c \ud658\uc728 \uc774\uc57c\uae30\uac00 \uc790\uc8fc \ub098\uc624\ub294\ub370 \uc65c \uadf8\ub807\uac8c \uc911\uc694\ud574\uc694?\n\n\ubbfc\uc218: \ud55c\uad6d\uc740 \uc218\ucd9c\uacfc \uc218\uc785\uc744 \ub9ce\uc774 \ud558\uae30 \ub54c\ubb38\uc5d0 \ud658\uc728\uc758 \uc601\ud5a5\uc744 \ubc1b\uc744 \uc218 \uc788\uc5b4\uc694.\n\n\uc548: \ud658\uc728\uc774 \ubc14\ub00c\uba74 \uc81c\ud488 \uac00\uaca9\ub3c4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc5b4\uc694?\n\n\ubbfc\uc218: \ub124. \ud574\uc678\uc5d0\uc11c \ud310\ub9e4\ud558\uac70\ub098 \uc678\uad6d\uc5d0\uc11c \ubb3c\uac74\uc744 \uc218\uc785\ud560 \ub54c \uac00\uaca9\uc5d0 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc5b4\uc694.\n\n\uc548: \ud55c\uad6d\uc740 \uc5b4\ub5a4 \uc81c\ud488\uc744 \ub9ce\uc774 \uc218\ucd9c\ud574\uc694?\n\n\ubbfc\uc218: \uc790\ub3d9\ucc28, \ubc18\ub3c4\uccb4, \uc804\uc790\uc81c\ud488, \uc120\ubc15 \uac19\uc740 \uc5ec\ub7ec \uc81c\ud488\uc744 \uc218\ucd9c\ud574\uc694.\n\n\uc548: \uadf8\ub7ec\uba74 \ud544\uc694\ud55c \uac83\uc740 \uc678\uad6d\uc5d0\uc11c \uc218\uc785\ud558\uace0\uc694?\n\n\ubbfc\uc218: \ub9de\uc544\uc694. \uc6d0\uc790\uc7ac\uc640 \uc5d0\ub108\uc9c0 \ub4f1\ub3c4 \uc218\uc785\ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc544\uc694.\n\n\uc548: FTA\ub77c\ub294 \ub9d0\ub3c4 \ub274\uc2a4\uc5d0\uc11c \ub9ce\uc774 \ub4e4\uc5c8\uc5b4\uc694.\n\n\ubbfc\uc218: \uc790\uc720\ubb34\uc5ed\ud611\uc815\uc774\uc5d0\uc694. \uad6d\uac00 \uac04 \ubb34\uc5ed\uc744 \ub354 \ud65c\ubc1c\ud558\uac8c \ud558\uae30 \uc704\ud55c \ud611\uc815\uc774\uc5d0\uc694.\n\n\uc548: \uc138\uacc4\uacbd\uc81c\uac00 \ud55c\uad6d \uacbd\uc81c\uc640 \uc815\ub9d0 \uac00\uae4c\uc774 \uc5f0\uacb0\ub418\uc5b4 \uc788\uad70\uc694.\n\n\ubbfc\uc218: \ub9de\uc544\uc694. \uadf8\ub798\uc11c \ub2e4\ub978 \ub098\ub77c\uc758 \uacbd\uc81c \uc0c1\ud669\ub3c4 \uc911\uc694\ud558\uac8c \uc0b4\ud3b4\ubd10\uc57c \ud574\uc694.\n","An: Minsu, tr\xean tin t\u1ee9c t\xf4i th\u01b0\u1eddng nghe n\xf3i v\u1ec1 t\u1ef7 gi\xe1. T\u1ea1i sao n\xf3 quan tr\u1ecdng v\u1eady?\n\nMinsu: V\xec H\xe0n Qu\u1ed1c xu\u1ea5t nh\u1eadp kh\u1ea9u nhi\u1ec1u n\xean c\xf3 th\u1ec3 ch\u1ecbu \u1ea3nh h\u01b0\u1edfng c\u1ee7a t\u1ef7 gi\xe1.\n\nAn: Khi t\u1ef7 gi\xe1 thay \u0111\u1ed5i th\xec gi\xe1 s\u1ea3n ph\u1ea9m c\u0169ng c\xf3 th\u1ec3 thay \u0111\u1ed5i \xe0?\n\nMinsu: \u0110\xfang. Khi b\xe1n h\xe0ng \u1edf n\u01b0\u1edbc ngo\xe0i ho\u1eb7c nh\u1eadp h\xe0ng t\u1eeb n\u01b0\u1edbc ngo\xe0i, gi\xe1 c\u1ea3 c\xf3 th\u1ec3 b\u1ecb \u1ea3nh h\u01b0\u1edfng.\n\nAn: H\xe0n Qu\u1ed1c xu\u1ea5t kh\u1ea9u nhi\u1ec1u s\u1ea3n ph\u1ea9m g\xec?\n\nMinsu: Nhi\u1ec1u s\u1ea3n ph\u1ea9m nh\u01b0 \xf4 t\xf4, ch\u1ea5t b\xe1n d\u1eabn, \u0111i\u1ec7n t\u1eed v\xe0 t\xe0u bi\u1ec3n.\n\nAn: V\xe0 nh\u1eefng th\u1ee9 c\u1ea7n thi\u1ebft th\xec nh\u1eadp kh\u1ea9u t\u1eeb n\u01b0\u1edbc ngo\xe0i?\n\nMinsu: \u0110\xfang v\u1eady. Nguy\xean v\u1eadt li\u1ec7u v\xe0 n\u0103ng l\u01b0\u1ee3ng c\u0169ng th\u01b0\u1eddng \u0111\u01b0\u1ee3c nh\u1eadp kh\u1ea9u.\n\nAn: T\xf4i c\u0169ng th\u01b0\u1eddng nghe t\u1eeb FTA tr\xean tin t\u1ee9c.\n\nMinsu: \u0110\xf3 l\xe0 hi\u1ec7p \u0111\u1ecbnh th\u01b0\u01a1ng m\u1ea1i t\u1ef1 do, nh\u1eb1m th\xfac \u0111\u1ea9y th\u01b0\u01a1ng m\u1ea1i gi\u1eefa c\xe1c qu\u1ed1c gia.\n\nAn: Kinh t\u1ebf th\u1ebf gi\u1edbi th\u1eadt s\u1ef1 li\xean k\u1ebft r\u1ea5t g\u1ea7n v\u1edbi kinh t\u1ebf H\xe0n Qu\u1ed1c nh\u1ec9.\n\nMinsu: \u0110\xfang v\u1eady. V\xec th\u1ebf c\u0169ng c\u1ea7n ch\xfa \xfd \u0111\u1ebfn t\xecnh h\xecnh kinh t\u1ebf c\u1ee7a c\xe1c n\u01b0\u1edbc kh\xe1c.\n",A.hYi,A.fRE,A.fY6,A.hHs)
A.hiG=s(["Hi\u1ec3u qu\xe1 tr\xecnh t\xecm vi\u1ec7c v\xe0 xin vi\u1ec7c c\u01a1 b\u1ea3n \u1edf H\xe0n Qu\u1ed1c.","Bi\u1ebft c\xe1c t\u1eeb v\u1ef1ng quan tr\u1ecdng nh\u01b0 \uad6c\uc778, \uad6c\uc9c1, \ucc44\uc6a9, \uc9c0\uc6d0 v\xe0 \uba74\uc811.","Bi\u1ebft c\xe1ch \u0111\u1ecdc th\xf4ng tin tuy\u1ec3n d\u1ee5ng c\u01a1 b\u1ea3n.","Hi\u1ec3u vai tr\xf2 c\u1ee7a \uc774\ub825\uc11c v\xe0 \uc790\uae30\uc18c\uac1c\uc11c.","Bi\u1ebft nh\u1eefng n\u1ed9i dung c\u1ea7n ki\u1ec3m tra tr\u01b0\u1edbc khi k\xfd \uadfc\ub85c\uacc4\uc57d\uc11c.","Bi\u1ebft m\u1ed9t s\u1ed1 c\xe1ch h\u1ecfi v\u1ec1 l\u01b0\u01a1ng, th\u1eddi gian l\xe0m vi\u1ec7c v\xe0 \u0111i\u1ec1u ki\u1ec7n l\xe0m vi\u1ec7c.","Luy\u1ec7n h\u1ed9i tho\u1ea1i th\u1ef1c t\u1ebf khi \u1ee9ng tuy\u1ec3n v\xe0 ph\u1ecfng v\u1ea5n xin vi\u1ec7c."],t.s)
A.io9=s(["\uc77c\uc790\ub9ac\ub97c \ucc3e\ub294 \uac83\uc744 \uad6c\uc9c1\uc774\ub77c\uace0 \ud558\uace0 \uc0ac\ub78c\uc744 \uad6c\ud558\ub294 \uac83\uc744 \uad6c\uc778\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4.","\ud68c\uc0ac\uac00 \uc9c1\uc6d0\uc744 \ubf51\ub294 \uac83\uc744 \ucc44\uc6a9\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4.","\uad6c\uc9c1\uc790\ub294 \ucc44\uc6a9\uacf5\uace0\ub97c \ud655\uc778\ud55c \ud6c4 \ud68c\uc0ac\uc5d0 \uc9c0\uc6d0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ucde8\uc5c5\uc744 \uc900\ube44\ud560 \ub54c\uc5d0\ub294 \uc774\ub825\uc11c\uc640 \uc790\uae30\uc18c\uac1c\uc11c\ub97c \uc791\uc131\ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.","\uc11c\ub958\uc804\ud615\uc5d0 \ud569\uaca9\ud558\uba74 \uba74\uc811\uc744 \ubcf4\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.","\uba74\uc811\uc5d0\uc11c\ub294 \uacbd\ub825, \uc5c5\ubb34 \ub2a5\ub825, \uc9c0\uc6d0 \ub3d9\uae30 \ub4f1\uc5d0 \uad00\ud55c \uc9c8\ubb38\uc744 \ubc1b\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ucde8\uc5c5\uc774 \uacb0\uc815\ub418\uba74 \uadfc\ub85c\uacc4\uc57d\uc11c\ub97c \uc791\uc131\ud558\uace0 \uadfc\ubb34\uc870\uac74\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\uadfc\ub85c\uacc4\uc57d\uc11c\uc5d0\uc11c\ub294 \uc784\uae08, \uadfc\ub85c\uc2dc\uac04, \ud734\uc77c, \uc5c5\ubb34 \ub0b4\uc6a9 \ub4f1 \uc911\uc694\ud55c \uc870\uac74\uc744 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.","\ucc44\uc6a9\uc815\ubcf4\ub97c \ud655\uc778\ud560 \ub54c\uc5d0\ub294 \ud68c\uc0ac\uc640 \uadfc\ubb34\uc870\uac74\uc774 \ubbff\uc744 \ub9cc\ud55c\uc9c0 \ud655\uc778\ud558\ub294 \uac83\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4."],t.s)
