A.h3F=s(["\uad6c\uc9c1 = ng\u01b0\u1eddi lao \u0111\u1ed9ng t\xecm vi\u1ec7c; \uad6c\uc778 = c\xf4ng ty t\xecm ng\u01b0\u1eddi.","\ucc44\uc6a9 = tuy\u1ec3n d\u1ee5ng; \uc9c0\uc6d0 = \u1ee9ng tuy\u1ec3n.","\uc9c0\uc6d0\uc790 = \u1ee9ng vi\xean; \ucc44\uc6a9 \ub2f4\ub2f9\uc790 = ng\u01b0\u1eddi ph\u1ee5 tr\xe1ch tuy\u1ec3n d\u1ee5ng.","\uc774\ub825\uc11c = CV/s\u01a1 y\u1ebfu l\xfd l\u1ecbch; \uc790\uae30\uc18c\uac1c\uc11c = b\u1ea3n t\u1ef1 gi\u1edbi thi\u1ec7u.","\uacbd\ub825 = kinh nghi\u1ec7m ngh\u1ec1 nghi\u1ec7p; \uc2e0\uc785 = ng\u01b0\u1eddi m\u1edbi.","\uc11c\ub958\uc804\ud615 = v\xf2ng x\xe9t h\u1ed3 s\u01a1; \uba74\uc811 = ph\u1ecfng v\u1ea5n.","\ud569\uaca9 = \u0111\u1ed7/tr\xfang tuy\u1ec3n; \ubd88\ud569\uaca9 = kh\xf4ng \u0111\u1ed7.","\uadfc\ub85c\uacc4\uc57d\uc11c\ub294 \uc77c\uc744 \uc2dc\uc791\ud558\uae30 \uc804\uc5d0 \uc911\uc694\ud55c \uadfc\ub85c\uc870\uac74\uc744 \ud655\uc778\ud558\uae30 \uc704\ud55c \ubb38\uc11c\uc785\ub2c8\ub2e4.","\uae09\uc5ec\ub9cc \ubcf4\uc9c0 \ub9d0\uace0 \uadfc\ub85c\uc2dc\uac04, \uc5c5\ubb34 \ub0b4\uc6a9, \ud734\uc77c, \uadfc\ubb34 \uc7a5\uc18c \ub4f1\ub3c4 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4."],t.s)
A.iUj=s(["\uad6c\uc9c1 \u2192 t\xecm vi\u1ec7c.","\uad6c\uc778 \u2192 tuy\u1ec3n/t\xecm ng\u01b0\u1eddi lao \u0111\u1ed9ng.","\ucc44\uc6a9 \u2192 tuy\u1ec3n d\u1ee5ng.","\ucc44\uc6a9\uacf5\uace0 \u2192 tin tuy\u1ec3n d\u1ee5ng.","\uc9c0\uc6d0\ud558\ub2e4 \u2192 \u1ee9ng tuy\u1ec3n.","\uc774\ub825\uc11c \u2192 CV.","\uc790\uae30\uc18c\uac1c\uc11c \u2192 b\u1ea3n t\u1ef1 gi\u1edbi thi\u1ec7u.","\uacbd\ub825 \u2192 kinh nghi\u1ec7m l\xe0m vi\u1ec7c.","\uc11c\ub958\uc804\ud615 \u2192 v\xf2ng x\xe9t h\u1ed3 s\u01a1.","\uba74\uc811 \u2192 ph\u1ecfng v\u1ea5n.","\uadfc\ub85c\uacc4\uc57d\uc11c \u2192 h\u1ee3p \u0111\u1ed3ng lao \u0111\u1ed9ng.","\uc784\uae08 \u2192 ti\u1ec1n l\u01b0\u01a1ng.","\uadfc\ub85c\uc2dc\uac04 \u2192 th\u1eddi gian l\xe0m vi\u1ec7c.","\uadfc\ub85c\uacc4\uc57d\uc11c\ub97c \uc791\uc131\ud560 \ub54c \uc784\uae08, \uadfc\ub85c\uc2dc\uac04, \ud734\uc77c, \uc5c5\ubb34 \ub4f1\uc744 \ud655\uc778\ud574\uc57c \ud55c\ub2e4."],t.s)
