A.f7o=new B.G("\uadfc\ub85c\uacc4\uc57d\uc11c\uc5d0\uc11c \ud655\uc778\ud574\uc57c \ud560 \ub0b4\uc6a9\uc73c\ub85c \uc54c\ub9de\uc9c0 \uc54a\uc740 \uac83\uc740?","\u0110\xe2u KH\xd4NG ph\u1ea3i n\u1ed9i dung c\u01a1 b\u1ea3n c\u1ea7n ki\u1ec3m tra trong h\u1ee3p \u0111\u1ed3ng lao \u0111\u1ed9ng?",A.i3a,3,"M\xf3n \u0103n y\xeau th\xedch c\u1ee7a gi\xe1m \u0111\u1ed1c kh\xf4ng ph\u1ea3i \u0111i\u1ec1u ki\u1ec7n lao \u0111\u1ed9ng.")
A.hpx=s(["\uc784\uae08\uacfc \uadfc\ub85c\uc2dc\uac04, \uc5c5\ubb34 \ub0b4\uc6a9\uc744 \ud568\uaed8 \ud655\uc778\ud55c\ub2e4.","\uc6d4\uae09\ub9cc \ubcf4\uace0 \ub2e4\ub978 \uc870\uac74\uc740 \uc804\ud600 \ubcf4\uc9c0 \uc54a\ub294\ub2e4.","\ucc44\uc6a9\uacf5\uace0\ub97c \uc77d\uc9c0 \uc54a\ub294\ub2e4.","\uacc4\uc57d \ub0b4\uc6a9\uc744 \ud655\uc778\ud558\uc9c0 \uc54a\ub294\ub2e4."],t.s)
A.f5Y=new B.G("\ucde8\uc5c5\ud560 \ud68c\uc0ac\ub97c \uc120\ud0dd\ud560 \ub54c \ubc14\ub78c\uc9c1\ud55c \ubc29\ubc95\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","C\xe1ch ph\xf9 h\u1ee3p khi l\u1ef1a ch\u1ecdn c\xf4ng ty \u0111\u1ec3 xin vi\u1ec7c l\xe0 g\xec?",A.hpx,0,"N\xean ki\u1ec3m tra t\u1ed5ng th\u1ec3 ti\u1ec1n l\u01b0\u01a1ng, th\u1eddi gian v\xe0 n\u1ed9i dung c\xf4ng vi\u1ec7c.")
A.iLs=s(["\ucde8\uc5c5 \uc804\uc5d0 \ucc44\uc6a9\uacf5\uace0\uc640 \uadfc\ub85c\uc870\uac74\uc744 \uc790\uc138\ud788 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\ub2e4.","\uadfc\ub85c\uacc4\uc57d\uc11c\ub294 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4.","\uc774\ub825\uc11c\uc5d0\ub294 \uc544\ubb34 \ub0b4\uc6a9\ub3c4 \uc4f0\uc9c0 \uc54a\ub294\ub2e4.","\uba74\uc811\uc5d0\uc11c\ub294 \uc5c5\ubb34 \uacbd\ud5d8\uc744 \uc808\ub300 \ubb3b\uc9c0 \uc54a\ub294\ub2e4."],t.s)
A.fa6=new B.G("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung ph\xf9 h\u1ee3p v\u1edbi b\xe0i \u0111\u1ecdc.",A.iLs,0,"Tr\u01b0\u1edbc khi xin vi\u1ec7c n\xean ki\u1ec3m tra k\u1ef9 tin tuy\u1ec3n d\u1ee5ng v\xe0 c\xe1c \u0111i\u1ec1u ki\u1ec7n l\xe0m vi\u1ec7c.")
