A.h_c=s(["\ucd08\ub4f1\ud559\uad50 = ti\u1ec3u h\u1ecdc.","\uc911\ud559\uad50 = trung h\u1ecdc c\u01a1 s\u1edf.","\uace0\ub4f1\ud559\uad50 = trung h\u1ecdc ph\u1ed5 th\xf4ng.","\ub300\ud559\uad50 = \u0111\u1ea1i h\u1ecdc.","\uc785\ud559 = nh\u1eadp h\u1ecdc; \uc878\uc5c5 = t\u1ed1t nghi\u1ec7p.","\uc9c4\ud559\ud558\ub2e4 = h\u1ecdc l\xean c\u1ea5p cao h\u01a1n.","\uad50\uc0ac = gi\xe1o vi\xean; \ud559\uc0dd = h\u1ecdc sinh/sinh vi\xean; \ud559\ubd80\ubaa8 = ph\u1ee5 huynh.","\uc218\uc5c5 = gi\u1edd h\u1ecdc; \uacfc\ubaa9 = m\xf4n h\u1ecdc.","\uc758\ubb34\uad50\uc721 = gi\xe1o d\u1ee5c b\u1eaft bu\u1ed9c, kh\xf4ng c\xf3 ngh\u0129a l\xe0 m\u1ecdi c\u1ea5p h\u1ecdc \u0111\u1ec1u b\u1eaft bu\u1ed9c."],t.s)
A.hUh=s(["\ucd08\ub4f1\ud559\uad50 \u2192 ti\u1ec3u h\u1ecdc.","\uc911\ud559\uad50 \u2192 trung h\u1ecdc c\u01a1 s\u1edf.","\uace0\ub4f1\ud559\uad50 \u2192 trung h\u1ecdc ph\u1ed5 th\xf4ng.","\ub300\ud559\uad50 \u2192 \u0111\u1ea1i h\u1ecdc.","\uc785\ud559 \u2192 nh\u1eadp h\u1ecdc.","\uc878\uc5c5 \u2192 t\u1ed1t nghi\u1ec7p.","\uc9c4\ud559 \u2192 h\u1ecdc l\xean.","\ucd08\ub4f1\ud559\uad50\uc640 \uc911\ud559\uad50 \uacfc\uc815\uc740 \uc758\ubb34\uad50\uc721\uc5d0 \ud3ec\ud568\ub41c\ub2e4.","\uad50\uc0ac\ub294 \ud559\uc0dd\uc758 \ud559\uc2b5\uacfc \uc0dd\ud65c\uc744 \uc9c0\ub3c4\ud55c\ub2e4.","\ud559\uc0dd\uc740 \ud559\uad50 \uaddc\uce59\uc744 \uc9c0\ud0a4\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc744 \uc874\uc911\ud574\uc57c \ud55c\ub2e4.","\ud559\ubd80\ubaa8\uc640 \ud559\uad50\uc758 \uc18c\ud1b5\ub3c4 \uc911\uc694\ud558\ub2e4."],t.s)
