A.f92=new B.G("\uc0c1\ud488\uc5d0 \ubb38\uc81c\uac00 \uc788\uc744 \ub54c \ud655\uc778\ud558\uba74 \uc88b\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Khi s\u1ea3n ph\u1ea9m c\xf3 v\u1ea5n \u0111\u1ec1 n\xean ki\u1ec3m tra \u0111i\u1ec1u g\xec?",A.iXg,0,"N\xean ki\u1ec3m tra \u0111i\u1ec1u ki\u1ec7n \u0111\u1ed5i v\xe0 ho\xe0n ti\u1ec1n.")
A.fYf=s(["\ube44\ubc00\ubc88\ud638\ub97c \ud568\ubd80\ub85c \uc54c\ub824 \uc8fc\uc9c0 \uc54a\ub294\ub2e4.","\ubaa8\ub974\ub294 \uc0ac\ub78c\uc5d0\uac8c \uacc4\uc88c\uc815\ubcf4\ub97c \ubaa8\ub450 \ubcf4\ub0b8\ub2e4.","\uc778\uc99d\ubc88\ud638\ub97c \ub204\uad6c\uc5d0\uac8c\ub098 \uc54c\ub824 \uc900\ub2e4.","\uac1c\uc778\uc815\ubcf4\ub97c \uc778\ud130\ub137\uc5d0 \ubaa8\ub450 \uacf5\uac1c\ud55c\ub2e4."],t.s)
A.f89=new B.G("\uac1c\uc778\uc815\ubcf4\ub97c \ubcf4\ud638\ud558\ub294 \ubc29\ubc95\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","C\xe1ch n\xe0o ph\xf9 h\u1ee3p \u0111\u1ec3 b\u1ea3o v\u1ec7 th\xf4ng tin c\xe1 nh\xe2n?",A.fYf,0,"Kh\xf4ng t\xf9y ti\u1ec7n cung c\u1ea5p m\u1eadt kh\u1ea9u ho\u1eb7c th\xf4ng tin quan tr\u1ecdng cho ng\u01b0\u1eddi kh\xe1c.")
