A.f4j=new B.G("\ubd84\uc7c1\uc774 \ubc1c\uc0dd\ud588\uc744 \ub54c \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\ub294 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Th\u1ee9 n\xe0o c\xf3 th\u1ec3 gi\xfap \xedch khi x\u1ea3y ra tranh ch\u1ea5p?",A.hpP,0,"H\u1ee3p \u0111\u1ed3ng v\xe0 h\xf3a \u0111\u01a1n c\xf3 th\u1ec3 gi\xfap x\xe1c \u0111\u1ecbnh n\u1ed9i dung giao d\u1ecbch.")
A.fE1=s(["\ub0b4\uc6a9\uc744 \uc790\uc138\ud788 \ud655\uc778\ud55c\ub2e4.","\uacc4\uc57d\uc11c\ub97c \uc77d\uc9c0 \uc54a\ub294\ub2e4.","\uc870\uac74\uc744 \uc804\ud600 \ud655\uc778\ud558\uc9c0 \uc54a\ub294\ub2e4.","\ube48 \uacc4\uc57d\uc11c\uc5d0 \uba3c\uc800 \uc11c\uba85\ud55c\ub2e4."],t.s)
A.fbf=new B.G("\uacc4\uc57d\uc11c\uc5d0 \uc11c\uba85\ud558\uae30 \uc804\uc5d0 \ud574\uc57c \ud560 \uc77c\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Tr\u01b0\u1edbc khi k\xfd h\u1ee3p \u0111\u1ed3ng c\u1ea7n l\xe0m g\xec?",A.fE1,0,"Tr\u01b0\u1edbc khi k\xfd ph\u1ea3i ki\u1ec3m tra k\u1ef9 n\u1ed9i dung h\u1ee3p \u0111\u1ed3ng.")
A.hdf=s(["\uad00\ub828 \uae30\uad00\uc774\ub098 \uc804\ubb38\uac00\uc5d0\uac8c \uc0c1\ub2f4\ud55c\ub2e4.","\ud655\uc778\ud558\uc9c0 \uc54a\uace0 \ub9c8\uc74c\ub300\ub85c \ucc98\ub9ac\ud55c\ub2e4.","\ubaa8\ub4e0 \uc790\ub8cc\ub97c \ubc84\ub9b0\ub2e4.","\uc0c1\ub300\ubc29\uc5d0\uac8c \ud3ed\ub825\uc744 \uc0ac\uc6a9\ud55c\ub2e4."],t.s)
A.f63=new B.G("\ubc95\ub960 \ubb38\uc81c\uac00 \ubcf5\uc7a1\ud560 \ub54c \ubc14\ub78c\uc9c1\ud55c \ud589\ub3d9\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Khi v\u1ea5n \u0111\u1ec1 ph\xe1p l\xfd ph\u1ee9c t\u1ea1p, h\xe0nh \u0111\u1ed9ng ph\xf9 h\u1ee3p l\xe0 g\xec?",A.hdf,0,"N\u1ebfu v\u1ea5n \u0111\u1ec1 ph\u1ee9c t\u1ea1p c\xf3 th\u1ec3 nh\u1eadn t\u01b0 v\u1ea5n t\u1eeb c\u01a1 quan ho\u1eb7c chuy\xean gia.")
A.j10=s(["\uc0dd\ud65c \uc18d\uc5d0\uc11c\ub3c4 \uacc4\uc57d\uacfc \uac1c\uc778\uc815\ubcf4 \ubcf4\ud638 \ub4f1 \ubc95\ub960 \uc9c0\uc2dd\uc774 \ud544\uc694\ud558\ub2e4.","\ubc95\uc740 \ubc94\uc8c4 \uc0ac\uac74\uc5d0\ub9cc \ud544\uc694\ud558\ub2e4.","\uc911\uc694\ud55c \uacc4\uc57d\ub3c4 \ub9d0\ub85c\ub9cc \ud558\uba74 \uac00\uc7a5 \uc548\uc804\ud558\ub2e4.","\uc601\uc218\uc99d\uacfc \uacc4\uc57d\uc11c\ub294 \ubcf4\uad00\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4."],t.s)
A.f7X=new B.G("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung ph\xf9 h\u1ee3p v\u1edbi b\xe0i \u0111\u1ecdc.",A.j10,0,"Ph\xe1p lu\u1eadt li\xean quan \u0111\u1ebfn r\u1ea5t nhi\u1ec1u ho\u1ea1t \u0111\u1ed9ng h\u1eb1ng ng\xe0y nh\u01b0 thu\xea nh\xe0, mua h\xe0ng v\xe0 b\u1ea3o v\u1ec7 th\xf4ng tin c\xe1 nh\xe2n.")
A.fL3=s([A.f53,A.f4J,A.f4h,A.f56,A.f92,A.f89,A.f4j,A.fbf,A.f63,A.f7X],t.h)
A.h3h=s(["\uc0dd\ud65c\ubc95\ub960 = ph\xe1p lu\u1eadt trong \u0111\u1eddi s\u1ed1ng.","\uacc4\uc57d = h\u1ee3p \u0111\u1ed3ng/th\u1ecfa thu\u1eadn.","\uacc4\uc57d\uc11c = v\u0103n b\u1ea3n h\u1ee3p \u0111\u1ed3ng.","\uc784\ub300\uc778 = b\xean cho thu\xea.","\uc784\ucc28\uc778 = b\xean thu\xea.","\ubcf4\uc99d\uae08 = ti\u1ec1n \u0111\u1eb7t c\u1ecdc.","\uc6d4\uc138 = ti\u1ec1n thu\xea h\u1eb1ng th\xe1ng.","\uc18c\ube44\uc790 \ubcf4\ud638 = b\u1ea3o v\u1ec7 ng\u01b0\u1eddi ti\xeau d\xf9ng.","\uac1c\uc778\uc815\ubcf4 = th\xf4ng tin c\xe1 nh\xe2n.","\ubd84\uc7c1 = tranh ch\u1ea5p.","\uc99d\uac70 = ch\u1ee9ng c\u1ee9.","\uacc4\uc57d \uc804\uc5d0 \uc911\uc694\ud55c \uc870\uac74\uc744 \uc790\uc138\ud788 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.","\uacc4\uc57d\uc11c, \uc601\uc218\uc99d, \uacb0\uc81c \uae30\ub85d \ub4f1\uc744 \ubcf4\uad00\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","\uac1c\uc778\uc815\ubcf4\ub97c \uc548\uc804\ud558\uac8c \uad00\ub9ac\ud574\uc57c \ud569\ub2c8\ub2e4.","\ubc95\uc801\uc778 \ubb38\uc81c\uac00 \ubcf5\uc7a1\ud558\uba74 \uad00\ub828 \uae30\uad00\uc774\ub098 \uc804\ubb38\uac00\uc5d0\uac8c \uc0c1\ub2f4\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],t.s)
A.f3N=new B.dk(34,"\ubc95","\ud55c\uad6d\uc758 \uc0dd\ud65c\ubc95\ub960","Ph\xe1p lu\u1eadt trong \u0111\u1eddi s\u1ed1ng \u1edf H\xe0n Qu\u1ed1c",A.idk,A.hRP,A.iP5,A.hrv,"\uc0dd\ud65c \uc18d\uc5d0\uc11c \ubc95\uc744 \uc54c\uc544\uc57c \ud558\ub294 \uc774\uc720","\ubc95\uc740 \uc7ac\ud310\uc774\ub098 \ubc94\uc8c4\uc640 \uad00\ub828\ub41c \uacbd\uc6b0\uc5d0\ub9cc \ud544\uc694\ud55c \uac83\uc774 \uc544\ub2d9\ub2c8\ub2e4. \uc6b0\ub9ac\ub294 \uc77c\uc0c1\uc0dd\ud65c\uc5d0\uc11c\ub3c4 \uc5ec\ub7ec \uac00\uc9c0 \ubc95\uc801\uc778 \uad00\uacc4\ub97c \ub9fa\uc73c\uba70 \uc0b4\uc544\uac11\ub2c8\ub2e4.\n\n\uc608\ub97c \ub4e4\uc5b4 \uc9d1\uc744 \ube4c\ub9b4 \ub54c\uc5d0\ub294 \uc784\ub300\ucc28 \uacc4\uc57d\uc744 \ud569\ub2c8\ub2e4. \uc774\ub54c \ubcf4\uc99d\uae08, \uc6d4\uc138, \uacc4\uc57d\uae30\uac04, \uad00\ub9ac\ube44 \ub4f1 \uc911\uc694\ud55c \uc870\uac74\uc744 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.\n\n\ucde8\uc5c5\ud560 \ub54c\uc5d0\ub294 \uadfc\ub85c\uacc4\uc57d\uc744 \ud558\uace0 \ubb3c\uac74\uc774\ub098 \uc11c\ube44\uc2a4\ub97c \uc774\uc6a9\ud560 \ub54c\uc5d0\ub294 \uc18c\ube44\uc790\ub85c\uc11c \uac70\ub798\ub97c \ud558\uac8c \ub429\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uc0c1\ud669\uc5d0\uc11c\ub3c4 \uacc4\uc57d \ub0b4\uc6a9\uacfc \uc870\uac74\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.\n\n\uc911\uc694\ud55c \uacc4\uc57d\uc744 \ub9d0\ub85c\ub9cc \uc57d\uc18d\ud558\uba74 \ub098\uc911\uc5d0 \uc11c\ub85c \uae30\uc5b5\ud558\ub294 \ub0b4\uc6a9\uc774 \ub2ec\ub77c \ubd84\uc7c1\uc774 \uc0dd\uae38 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uac00\ub2a5\ud55c \uacbd\uc6b0 \uacc4\uc57d\uc11c\ub97c \uc791\uc131\ud558\uace0 \uc790\uc2e0\ub3c4 \ud55c \ubd80\ub97c \ubcf4\uad00\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.\n\n\ubb3c\uac74\uc744 \uad6c\uc785\ud560 \ub54c\uc5d0\ub294 \uac00\uaca9, \ud488\uc9c8, \uad50\ud658\uc774\ub098 \ud658\ubd88 \uc870\uac74 \ub4f1\uc744 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \uac70\ub798 \ud6c4\uc5d0\ub294 \uc601\uc218\uc99d\uc774\ub098 \uacb0\uc81c \uae30\ub85d\uc744 \ubcf4\uad00\ud558\uba74 \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud588\uc744 \ub54c \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc778\ud130\ub137\uacfc \uc2a4\ub9c8\ud2b8\ud3f0\uc744 \ub9ce\uc774 \uc0ac\uc6a9\ud558\ub294 \uc694\uc998\uc5d0\ub294 \uac1c\uc778\uc815\ubcf4 \ubcf4\ud638\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4. \uc8fc\ubbfc\ub4f1\ub85d\ubc88\ud638\ub098 \uacc4\uc88c\uc815\ubcf4, \ube44\ubc00\ubc88\ud638 \ub4f1 \uc911\uc694\ud55c \uc815\ubcf4\ub97c \ud568\ubd80\ub85c \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc54c\ub824 \uc8fc\uc9c0 \uc54a\uc544\uc57c \ud569\ub2c8\ub2e4.\n\n\uc0dd\ud65c \uc911 \ubc95\uc801\uc778 \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud558\uba74 \uac10\uc815\uc801\uc73c\ub85c \ud574\uacb0\ud558\uae30\ubcf4\ub2e4 \uba3c\uc800 \uc0ac\uc2e4\uad00\uacc4\uc640 \uad00\ub828 \uc790\ub8cc\ub97c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.\n\n\ud63c\uc790 \ud574\uacb0\ud558\uae30 \uc5b4\ub824\uc6b4 \ubb38\uc81c\ub77c\uba74 \uacf5\uacf5\uae30\uad00, \uc0c1\ub2f4\uae30\uad00 \ub610\ub294 \ubc95\ub960 \uc804\ubb38\uac00\uc758 \ub3c4\uc6c0\uc744 \ubc1b\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc0dd\ud65c\ubc95\ub960\uc744 \uc54c\uace0 \uc788\ub2e4\ub294 \uac83\uc740 \ubaa8\ub4e0 \ubc95\uc744 \uc678\uc6b0\ub294 \uac83\uc744 \uc758\ubbf8\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc790\uc2e0\uc758 \uc0dd\ud65c\uacfc \uad00\ub828\ub41c \uae30\ubcf8\uc801\uc778 \uad8c\ub9ac\uc640 \uc758\ubb34\ub97c \uc54c\uace0 \ubb38\uc81c\uac00 \uc0dd\uacbc\uc744 \ub54c \uc801\uc808\ud55c \ub3c4\uc6c0\uc744 \ucc3e\uc744 \uc218 \uc788\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.\n","Ph\xe1p lu\u1eadt kh\xf4ng ch\u1ec9 c\u1ea7n thi\u1ebft trong nh\u1eefng tr\u01b0\u1eddng h\u1ee3p li\xean quan \u0111\u1ebfn x\xe9t x\u1eed ho\u1eb7c t\u1ed9i ph\u1ea1m. Trong \u0111\u1eddi s\u1ed1ng h\u1eb1ng ng\xe0y, ch\xfang ta c\u0169ng s\u1ed1ng trong nhi\u1ec1u m\u1ed1i quan h\u1ec7 ph\xe1p l\xfd kh\xe1c nhau.\n\nV\xed d\u1ee5, khi thu\xea nh\xe0 s\u1ebd k\xfd h\u1ee3p \u0111\u1ed3ng thu\xea. Khi \u0111\xf3 c\u1ea7n ki\u1ec3m tra nh\u1eefng \u0111i\u1ec1u ki\u1ec7n quan tr\u1ecdng nh\u01b0 ti\u1ec1n \u0111\u1eb7t c\u1ecdc, ti\u1ec1n thu\xea h\u1eb1ng th\xe1ng, th\u1eddi h\u1ea1n h\u1ee3p \u0111\u1ed3ng v\xe0 ph\xed qu\u1ea3n l\xfd.\n\nKhi \u0111i l\xe0m s\u1ebd c\xf3 quan h\u1ec7 h\u1ee3p \u0111\u1ed3ng lao \u0111\u1ed9ng, c\xf2n khi s\u1eed d\u1ee5ng h\xe0ng h\xf3a ho\u1eb7c d\u1ecbch v\u1ee5 ch\xfang ta th\u1ef1c hi\u1ec7n giao d\u1ecbch v\u1edbi t\u01b0 c\xe1ch ng\u01b0\u1eddi ti\xeau d\xf9ng. Trong nh\u1eefng t\xecnh hu\u1ed1ng n\xe0y c\u0169ng c\u1ea7n ki\u1ec3m tra n\u1ed9i dung v\xe0 \u0111i\u1ec1u ki\u1ec7n giao d\u1ecbch.\n\nN\u1ebfu m\u1ed9t h\u1ee3p \u0111\u1ed3ng quan tr\u1ecdng ch\u1ec9 \u0111\u01b0\u1ee3c th\u1ecfa thu\u1eadn b\u1eb1ng l\u1eddi, sau n\xe0y m\u1ed7i b\xean c\xf3 th\u1ec3 nh\u1edb kh\xe1c nhau v\xe0 tranh ch\u1ea5p c\xf3 th\u1ec3 ph\xe1t sinh. V\xec v\u1eady n\u1ebfu c\xf3 th\u1ec3, n\xean l\u1eadp h\u1ee3p \u0111\u1ed3ng b\u1eb1ng v\u0103n b\u1ea3n v\xe0 gi\u1eef l\u1ea1i m\u1ed9t b\u1ea3n.\n\nKhi mua h\xe0ng c\u1ea7n ki\u1ec3m tra gi\xe1, ch\u1ea5t l\u01b0\u1ee3ng c\u0169ng nh\u01b0 \u0111i\u1ec1u ki\u1ec7n \u0111\u1ed5i ho\u1eb7c ho\xe0n ti\u1ec1n. Sau giao d\u1ecbch, vi\u1ec7c gi\u1eef h\xf3a \u0111\u01a1n ho\u1eb7c l\u1ecbch s\u1eed thanh to\xe1n c\xf3 th\u1ec3 h\u1eefu \xedch n\u1ebfu ph\xe1t sinh v\u1ea5n \u0111\u1ec1.\n\nNg\xe0y nay Internet v\xe0 \u0111i\u1ec7n tho\u1ea1i th\xf4ng minh \u0111\u01b0\u1ee3c s\u1eed d\u1ee5ng nhi\u1ec1u n\xean vi\u1ec7c b\u1ea3o v\u1ec7 th\xf4ng tin c\xe1 nh\xe2n c\u0169ng r\u1ea5t quan tr\u1ecdng. Kh\xf4ng n\xean t\xf9y ti\u1ec7n cung c\u1ea5p nh\u1eefng th\xf4ng tin quan tr\u1ecdng nh\u01b0 s\u1ed1 \u0111\u1ecbnh danh, th\xf4ng tin t\xe0i kho\u1ea3n hay m\u1eadt kh\u1ea9u cho ng\u01b0\u1eddi kh\xe1c.\n\nN\u1ebfu ph\xe1t sinh v\u1ea5n \u0111\u1ec1 ph\xe1p l\xfd trong cu\u1ed9c s\u1ed1ng, thay v\xec x\u1eed l\xfd theo c\u1ea3m x\xfac, tr\u01b0\u1edbc ti\xean c\u1ea7n x\xe1c \u0111\u1ecbnh s\u1ef1 vi\u1ec7c v\xe0 ki\u1ec3m tra c\xe1c t\xe0i li\u1ec7u li\xean quan.\n\nN\u1ebfu v\u1ea5n \u0111\u1ec1 kh\xf3 t\u1ef1 gi\u1ea3i quy\u1ebft, c\xf3 th\u1ec3 t\xecm s\u1ef1 h\u1ed7 tr\u1ee3 t\u1eeb c\u01a1 quan c\xf4ng, c\u01a1 quan t\u01b0 v\u1ea5n ho\u1eb7c chuy\xean gia ph\xe1p lu\u1eadt.\n\nBi\u1ebft ph\xe1p lu\u1eadt \u0111\u1eddi s\u1ed1ng kh\xf4ng c\xf3 ngh\u0129a l\xe0 ph\u1ea3i thu\u1ed9c t\u1ea5t c\u1ea3 c\xe1c lu\u1eadt. \u0110i\u1ec1u quan tr\u1ecdng l\xe0 hi\u1ec3u nh\u1eefng quy\u1ec1n v\xe0 ngh\u0129a v\u1ee5 c\u01a1 b\u1ea3n li\xean quan \u0111\u1ebfn cu\u1ed9c s\u1ed1ng c\u1ee7a m\xecnh v\xe0 bi\u1ebft t\xecm s\u1ef1 tr\u1ee3 gi\xfap ph\xf9 h\u1ee3p khi x\u1ea3y ra v\u1ea5n \u0111\u1ec1.\n","\uc9d1 \uacc4\uc57d \uc804\uc5d0 \ud655\uc778\ud558\uae30","\uc548: \uc548\ub155\ud558\uc138\uc694. \uc774 \uc9d1\uc744 \uacc4\uc57d\ud558\uace0 \uc2f6\uc740\ub370 \uba87 \uac00\uc9c0 \ud655\uc778\ud558\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.\n\n\uc911\uac1c\uc778: \ub124. \ubb34\uc5c7\uc774 \uad81\uae08\ud558\uc138\uc694?\n\n\uc548: \ubcf4\uc99d\uae08\ud558\uace0 \uc6d4\uc138\uac00 \uc5bc\ub9c8\uc608\uc694?\n\n\uc911\uac1c\uc778: \ubcf4\uc99d\uae08\uc740 500\ub9cc \uc6d0\uc774\uace0 \uc6d4\uc138\ub294 50\ub9cc \uc6d0\uc785\ub2c8\ub2e4.\n\n\uc548: \uad00\ub9ac\ube44\ub294 \ub530\ub85c \ub0b4\uc57c \ud558\ub098\uc694?\n\n\uc911\uac1c\uc778: \ub124. \uad00\ub9ac\ube44\ub294 \ubcc4\ub3c4\uc785\ub2c8\ub2e4. \uacc4\uc57d\uc11c\uc5d0 \uc790\uc138\ud55c \ub0b4\uc6a9\uc744 \uc801\uc5b4 \ub4dc\ub9b4\uac8c\uc694.\n\n\uc548: \uacc4\uc57d\uae30\uac04\uc740 \uc5bc\ub9c8\ub098 \ub3fc\uc694?\n\n\uc911\uac1c\uc778: \uacc4\uc57d\uc11c\uc5d0 \uc815\ud574\uc9c4 \uae30\uac04\uc744 \ud655\uc778\ud558\uc2dc\uba74 \ub429\ub2c8\ub2e4.\n\n\uc548: \uc9d1\uc5d0 \ubb38\uc81c\uac00 \uc0dd\uae30\uba74 \ub204\uad6c\uc5d0\uac8c \uc5f0\ub77d\ud574\uc57c \ud574\uc694?\n\n\uc911\uac1c\uc778: \uc784\ub300\uc778\uc774\ub098 \uad00\ub9ac \ub2f4\ub2f9\uc790\uc5d0\uac8c \uc5f0\ub77d\ud558\uc2dc\uba74 \ub429\ub2c8\ub2e4.\n\n\uc548: \uacc4\uc57d\ud558\uae30 \uc804\uc5d0 \uc9d1 \uc0c1\ud0dc\ub3c4 \ud655\uc778\ud558\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.\n\n\uc911\uac1c\uc778: \ub124. \uc2dc\uc124 \uc0c1\ud0dc\ub97c \uac19\uc774 \ud655\uc778\ud574 \ubcf4\uc2dc\uc8e0.\n\n\uc548: \uacc4\uc57d\uc11c\uc5d0 \uc11c\uba85\ud558\uae30 \uc804\uc5d0 \ub0b4\uc6a9\uc744 \ub2e4\uc2dc \uc77d\uc5b4 \ubd10\ub3c4 \ub418\uc9c0\uc694?\n\n\uc911\uac1c\uc778: \ubb3c\ub860\uc785\ub2c8\ub2e4. \ubcf4\uc99d\uae08, \uc6d4\uc138, \uad00\ub9ac\ube44\uc640 \ub2e4\ub978 \uc870\uac74\uc744 \ubaa8\ub450 \ud655\uc778\ud55c \ud6c4 \uc11c\uba85\ud558\uc138\uc694.\n\n\uc548: \uacc4\uc57d\uc11c \uc0ac\ubcf8\ub3c4 \ubc1b\uc744 \uc218 \uc788\uc9c0\uc694?\n\n\uc911\uac1c\uc778: \ub124. \uacc4\uc57d \ud6c4\uc5d0\ub294 \ubcf8\uc778\uc758 \uacc4\uc57d\uc11c\ub97c \uc798 \ubcf4\uad00\ud558\uc2dc\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.\n","An: Xin ch\xe0o. T\xf4i mu\u1ed1n thu\xea c\u0103n nh\xe0 n\xe0y nh\u01b0ng mu\u1ed1n ki\u1ec3m tra v\xe0i \u0111i\u1ec1u.\n\nM\xf4i gi\u1edbi: V\xe2ng. Anh mu\u1ed1n h\u1ecfi g\xec?\n\nAn: Ti\u1ec1n \u0111\u1eb7t c\u1ecdc v\xe0 ti\u1ec1n thu\xea h\u1eb1ng th\xe1ng l\xe0 bao nhi\xeau?\n\nM\xf4i gi\u1edbi: Ti\u1ec1n \u0111\u1eb7t c\u1ecdc l\xe0 5 tri\u1ec7u won v\xe0 ti\u1ec1n thu\xea l\xe0 500 ngh\xecn won m\u1ed7i th\xe1ng.\n\nAn: Ph\xed qu\u1ea3n l\xfd ph\u1ea3i tr\u1ea3 ri\xeang \xe0?\n\nM\xf4i gi\u1edbi: V\xe2ng. Ph\xed qu\u1ea3n l\xfd ri\xeang. N\u1ed9i dung chi ti\u1ebft s\u1ebd \u0111\u01b0\u1ee3c ghi trong h\u1ee3p \u0111\u1ed3ng.\n\nAn: Th\u1eddi h\u1ea1n h\u1ee3p \u0111\u1ed3ng l\xe0 bao l\xe2u?\n\nM\xf4i gi\u1edbi: Anh c\xf3 th\u1ec3 ki\u1ec3m tra th\u1eddi h\u1ea1n \u0111\u01b0\u1ee3c quy \u0111\u1ecbnh trong h\u1ee3p \u0111\u1ed3ng.\n\nAn: N\u1ebfu c\u0103n nh\xe0 x\u1ea3y ra v\u1ea5n \u0111\u1ec1 th\xec t\xf4i ph\u1ea3i li\xean h\u1ec7 v\u1edbi ai?\n\nM\xf4i gi\u1edbi: Anh c\xf3 th\u1ec3 li\xean h\u1ec7 ch\u1ee7 nh\xe0 ho\u1eb7c ng\u01b0\u1eddi ph\u1ee5 tr\xe1ch qu\u1ea3n l\xfd.\n\nAn: Tr\u01b0\u1edbc khi k\xfd t\xf4i c\u0169ng mu\u1ed1n ki\u1ec3m tra t\xecnh tr\u1ea1ng c\u0103n nh\xe0.\n\nM\xf4i gi\u1edbi: V\xe2ng. Ch\xfang ta h\xe3y c\xf9ng ki\u1ec3m tra t\xecnh tr\u1ea1ng c\xe1c thi\u1ebft b\u1ecb.\n\nAn: T\xf4i c\xf3 th\u1ec3 \u0111\u1ecdc l\u1ea1i h\u1ee3p \u0111\u1ed3ng tr\u01b0\u1edbc khi k\xfd \u0111\xfang kh\xf4ng?\n\nM\xf4i gi\u1edbi: T\u1ea5t nhi\xean. H\xe3y ki\u1ec3m tra ti\u1ec1n \u0111\u1eb7t c\u1ecdc, ti\u1ec1n thu\xea, ph\xed qu\u1ea3n l\xfd v\xe0 c\xe1c \u0111i\u1ec1u ki\u1ec7n kh\xe1c tr\u01b0\u1edbc khi k\xfd.\n\nAn: T\xf4i c\u0169ng \u0111\u01b0\u1ee3c nh\u1eadn m\u1ed9t b\u1ea3n h\u1ee3p \u0111\u1ed3ng \u0111\xfang kh\xf4ng?\n\nM\xf4i gi\u1edbi: V\xe2ng. Sau khi k\xfd, n\xean gi\u1eef k\u1ef9 b\u1ea3n h\u1ee3p \u0111\u1ed3ng c\u1ee7a m\xecnh.\n",A.iZd,A.i7C,A.fL3,A.h3h)
A.h3c=s(["Bi\u1ebft m\u1ed9t s\u1ed1 danh lam du l\u1ecbch ti\xeau bi\u1ec3u c\u1ee7a c\xe1c v\xf9ng t\u1ea1i H\xe0n Qu\u1ed1c.","Hi\u1ec3u m\u1ed1i li\xean h\u1ec7 gi\u1eefa \u0111\u1eb7c \u0111i\u1ec3m \u0111\u1ecba ph\u01b0\u01a1ng v\xe0 s\u1ef1 ph\xe1t tri\u1ec3n du l\u1ecbch.","Bi\u1ebft m\u1ed9t s\u1ed1 l\u1ec5 h\u1ed9i \u0111\u1ecba ph\u01b0\u01a1ng n\u1ed5i ti\u1ebfng c\u1ee7a H\xe0n Qu\u1ed1c.","Hi\u1ec3u vai tr\xf2 c\u1ee7a l\u1ec5 h\u1ed9i trong vi\u1ec7c qu\u1ea3ng b\xe1 v\u0103n h\xf3a v\xe0 kinh t\u1ebf \u0111\u1ecba ph\u01b0\u01a1ng.","Ph\xe2n bi\u1ec7t \uad00\uad11\uba85\uc18c, \ubb38\ud654\uc720\uc0b0, \uc9c0\uc5ed\ucd95\uc81c v\xe0 \ud2b9\uc0b0\ubb3c.","Bi\u1ebft c\xe1ch t\xecm hi\u1ec3u th\xf4ng tin v\u1ec1 th\u1eddi gian, \u0111\u1ecba \u0111i\u1ec3m v\xe0 ch\u01b0\u01a1ng tr\xecnh l\u1ec5 h\u1ed9i.","Hi\u1ec3u r\u1eb1ng th\u1eddi gian t\u1ed5 ch\u1ee9c l\u1ec5 h\u1ed9i c\xf3 th\u1ec3 thay \u0111\u1ed5i t\xf9y t\u1eebng n\u0103m.","Luy\u1ec7n c\xe1c c\xe2u h\u1ecfi n\u1ed1i \uc9c0\uc5ed + \uad00\uad11\uc9c0 + \ucd95\uc81c th\u01b0\u1eddng g\u1eb7p trong KIIP."],t.s)
A.iyY=s(["\ud55c\uad6d\uc758 \uac01 \uc9c0\uc5ed\uc5d0\ub294 \uc790\uc5f0\ud658\uacbd\uacfc \uc5ed\uc0ac, \ubb38\ud654\ub97c \ubcf4\uc5ec \uc8fc\ub294 \ub2e4\uc591\ud55c \uad00\uad11\uba85\uc18c\uac00 \uc788\uc2b5\ub2c8\ub2e4.","\uc11c\uc6b8\uc5d0\ub294 \uacbd\ubcf5\uad81\uacfc \uac19\uc740 \uad81\uad90\uacfc \ub2e4\uc591\ud55c \ubb38\ud654\uc2dc\uc124\uc774 \uc788\uc2b5\ub2c8\ub2e4.","\uacbd\uc8fc\uc5d0\ub294 \ubd88\uad6d\uc0ac\uc640 \uac19\uc740 \uc2e0\ub77c \uc2dc\ub300\uc758 \ubb38\ud654\uc720\uc0b0\uc774 \ub9ce\uc774 \uc788\uc2b5\ub2c8\ub2e4.","\ubd80\uc0b0\uc740 \ud574\uc6b4\ub300\uc640 \uac19\uc740 \ud574\ubcc0 \uad00\uad11\uc9c0\uc640 \ud56d\uad6c\ub3c4\uc2dc\uc758 \ud2b9\uc9d5\uc73c\ub85c \uc798 \uc54c\ub824\uc838 \uc788\uc2b5\ub2c8\ub2e4.","\uc81c\uc8fc\ub3c4\ub294 \ud55c\ub77c\uc0b0, \ud574\uc548, \uc624\ub984 \ub4f1 \ub3c5\ud2b9\ud55c \uc790\uc5f0\uacbd\uad00\uc73c\ub85c \uc720\uba85\ud569\ub2c8\ub2e4.","\uc9c0\uc5ed\ucd95\uc81c\ub294 \uc9c0\uc5ed\uc758 \uc5ed\uc0ac, \ubb38\ud654, \uc790\uc5f0\ud658\uacbd, \ud2b9\uc0b0\ubb3c \ub4f1\uc744 \uc8fc\uc81c\ub85c \uc5f4\ub9ac\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.","\ubcf4\ub839\uba38\ub4dc\ucd95\uc81c\ub294 \ucda9\uccad\ub0a8\ub3c4 \ubcf4\ub839\uacfc \uad00\ub828\ub41c \ub300\ud45c\uc801\uc778 \uc9c0\uc5ed\ucd95\uc81c\ub85c \uc54c\ub824\uc838 \uc788\uc2b5\ub2c8\ub2e4.","\uc548\ub3d9\uad6d\uc81c\ud0c8\ucda4\ud398\uc2a4\ud2f0\ubc8c\uc740 \ud0c8\ucda4\uacfc \uc804\ud1b5\ubb38\ud654\ub97c \uccb4\ud5d8\ud560 \uc218 \uc788\ub294 \ucd95\uc81c\ub85c \uc798 \uc54c\ub824\uc838 \uc788\uc2b5\ub2c8\ub2e4.","\uc9c4\uc8fc\ub0a8\uac15\uc720\ub4f1\ucd95\uc81c\ub294 \uacbd\uc0c1\ub0a8\ub3c4 \uc9c4\uc8fc\uc758 \ub300\ud45c\uc801\uc778 \ucd95\uc81c \uc911 \ud558\ub098\uc785\ub2c8\ub2e4.","\ud654\ucc9c\uc0b0\ucc9c\uc5b4\ucd95\uc81c\ub294 \uac15\uc6d0 \uc9c0\uc5ed\uc758 \uaca8\uc6b8 \uad00\uad11\uacfc \uad00\ub828\ud558\uc5ec \uc798 \uc54c\ub824\uc838 \uc788\uc2b5\ub2c8\ub2e4.","\uc9c0\uc5ed\ucd95\uc81c\ub294 \uad00\uad11\uac1d\uc744 \uc720\uce58\ud558\uace0 \uc9c0\uc5ed\uacbd\uc81c\ub97c \ud65c\uc131\ud654\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ucd95\uc81c\uc758 \uc815\ud655\ud55c \uac1c\ucd5c \uae30\uac04\uacfc \ud504\ub85c\uadf8\ub7a8\uc740 \ud574\ub9c8\ub2e4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc73c\ubbc0\ub85c \ubc29\ubb38 \uc804\uc5d0 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4."],t.s)
