A.f9k=new B.G("\uc9c0\uc5ed\ucd95\uc81c\uac00 \uc9c0\uc5ed\uacbd\uc81c\uc5d0 \ub3c4\uc6c0\uc774 \ub418\ub294 \uc774\uc720\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","T\u1ea1i sao l\u1ec5 h\u1ed9i \u0111\u1ecba ph\u01b0\u01a1ng c\xf3 th\u1ec3 gi\xfap kinh t\u1ebf \u0111\u1ecba ph\u01b0\u01a1ng?",A.hNN,0,"Kh\xe1ch du l\u1ecbch c\xf3 th\u1ec3 t\u0103ng ti\xeau d\xf9ng t\u1ea1i c\xe1c c\u01a1 s\u1edf v\xe0 s\u1ea3n ph\u1ea9m \u0111\u1ecba ph\u01b0\u01a1ng.")
A.hvm=s(["\uac1c\ucd5c \uae30\uac04\uacfc \ud504\ub85c\uadf8\ub7a8","\uc61b\ub0a0 \uc77c\uc815\ub9cc","\ub2e4\ub978 \ub098\ub77c\uc758 \ub0a0\uc528\ub9cc","\ud655\uc778\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4."],t.s)
A.f8k=new B.G("\ucd95\uc81c\uc5d0 \uac00\uae30 \uc804\uc5d0 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Tr\u01b0\u1edbc khi \u0111i l\u1ec5 h\u1ed9i n\xean ki\u1ec3m tra \u0111i\u1ec1u g\xec?",A.hvm,0,"\ucd95\uc81c \uc77c\uc815\uacfc \ud504\ub85c\uadf8\ub7a8\uc740 \ud574\ub9c8\ub2e4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc73c\ubbc0\ub85c \ubbf8\ub9ac \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.")
A.iIU=s(["\uad00\uad11\uc744 \ubc1c\uc804\uc2dc\ud0a4\uba74\uc11c \uc790\uc5f0\uacfc \ubb38\ud654\uc720\uc0b0\uc744 \ubcf4\ud638\ud558\ub294 \uac83\ub3c4 \uc911\uc694\ud558\ub2e4.","\uc9c0\uc5ed\ucd95\uc81c\ub294 \uc9c0\uc5ed\uacbd\uc81c\uc640 \uc544\ubb34 \uad00\uacc4\uac00 \uc5c6\ub2e4.","\ubaa8\ub4e0 \ucd95\uc81c\ub294 \ub9e4\ub144 \uac19\uc740 \ub0a0\uc5d0 \uc5f4\ub9b0\ub2e4.","\ud55c\uad6d\uc758 \ubaa8\ub4e0 \uc9c0\uc5ed\uc5d0\ub294 \ub611\uac19\uc740 \uad00\uad11\uba85\uc18c\uac00 \uc788\ub2e4."],t.s)
A.f5d=new B.G("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung ph\xf9 h\u1ee3p v\u1edbi b\xe0i \u0111\u1ecdc.",A.iIU,0,"Ph\xe1t tri\u1ec3n du l\u1ecbch c\u1ea7n \u0111i c\xf9ng v\u1edbi b\u1ea3o v\u1ec7 m\xf4i tr\u01b0\u1eddng t\u1ef1 nhi\xean v\xe0 di s\u1ea3n v\u0103n h\xf3a.")
A.fBN=s([A.f5n,A.f7q,A.f6d,A.fa5,A.faO,A.f6A,A.fbA,A.f9k,A.f8k,A.f5d],t.h)
A.hIQ=s(["\uad00\uad11\uba85\uc18c = danh lam / \u0111i\u1ec3m du l\u1ecbch n\u1ed5i ti\u1ebfng.","\uc9c0\uc5ed\ucd95\uc81c = l\u1ec5 h\u1ed9i \u0111\u1ecba ph\u01b0\u01a1ng.","\uc11c\uc6b8 \u2192 \uacbd\ubcf5\uad81.","\uacbd\uc8fc \u2192 \ubd88\uad6d\uc0ac + \uc2e0\ub77c \ubb38\ud654\uc720\uc0b0.","\ubd80\uc0b0 \u2192 \ud574\uc6b4\ub300.","\uc81c\uc8fc \u2192 \ud55c\ub77c\uc0b0 + \uc790\uc5f0\uacbd\uad00.","\ubcf4\ub839 \u2192 \uba38\ub4dc\ucd95\uc81c.","\uc548\ub3d9 \u2192 \ud0c8\ucda4\ucd95\uc81c.","\uc9c4\uc8fc \u2192 \ub0a8\uac15\uc720\ub4f1\ucd95\uc81c.","\ud654\ucc9c \u2192 \uc0b0\ucc9c\uc5b4\ucd95\uc81c.","\uc9c0\uc5ed\ucd95\uc81c\ub294 \uc9c0\uc5ed\uc758 \ubb38\ud654\uc640 \ud2b9\uc0b0\ubb3c\uc744 \ud64d\ubcf4\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uad00\uad11\uac1d \uc99d\uac00\ub294 \uc9c0\uc5ed\uacbd\uc81c \ud65c\uc131\ud654\uc5d0 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc9c0\uc5ed\ucd95\uc81c\uc5d0\uc11c\ub294 \uc9c0\uc5ed\ubb38\ud654\ub97c \uc9c1\uc811 \uccb4\ud5d8\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uad00\uad11\uac1d\uc774 \ub108\ubb34 \ub9ce\uc73c\uba74 \uad50\ud1b5\xb7\uc4f0\ub808\uae30\xb7\ud658\uacbd \ubb38\uc81c\uac00 \uc0dd\uae38 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.","\uad00\uad11\uc790\uc6d0\uacfc \ubb38\ud654\uc720\uc0b0\uc744 \ubcf4\ud638\ud558\uba74\uc11c \uad00\uad11\uc744 \ubc1c\uc804\uc2dc\ud0a4\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\ucd95\uc81c \uc77c\uc815\uc740 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc73c\ubbc0\ub85c \ubc29\ubb38 \uc804 \uacf5\uc2dd \uc815\ubcf4\ub97c \ud655\uc778\ud569\ub2c8\ub2e4."],t.s)
A.f3O=new B.dk(48,"\uc9c0\ub9ac","\uc9c0\uc5ed\uc758 \uad00\uad11\uba85\uc18c\uc640 \ucd95\uc81c","Danh lam du l\u1ecbch v\xe0 l\u1ec5 h\u1ed9i c\u1ee7a c\xe1c v\xf9ng",A.h3c,A.iyY,A.hUd,A.hba,"\uc9c0\uc5ed\uc758 \ud2b9\uc9d5\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uad00\uad11\uba85\uc18c\uc640 \ucd95\uc81c","\ud55c\uad6d\uc5d0\ub294 \uc9c0\uc5ed\ub9c8\ub2e4 \uc790\uc5f0\ud658\uacbd\uacfc \uc5ed\uc0ac, \ubb38\ud654\uac00 \ub2e4\ub974\uae30 \ub54c\ubb38\uc5d0 \ub2e4\uc591\ud55c \uad00\uad11\uba85\uc18c\uac00 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc11c\uc6b8\uc5d0\uc11c\ub294 \uacbd\ubcf5\uad81\uacfc \uac19\uc740 \uad81\uad90\uc744 \ud1b5\ud574 \uc870\uc120 \uc2dc\ub300\uc758 \uc5ed\uc0ac\uc640 \ubb38\ud654\ub97c \uacbd\ud5d8\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub610\ud55c \ubc15\ubb3c\uad00, \uacf5\uc5f0\uc7a5, \uc804\ud1b5\uc2dc\uc7a5 \ub4f1 \ub2e4\uc591\ud55c \uad00\uad11\uc2dc\uc124\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uacbd\uc8fc\ub294 \uc2e0\ub77c\uc758 \uc218\ub3c4\uc600\ub358 \uc9c0\uc5ed\uc73c\ub85c \ubd88\uad6d\uc0ac\uc640 \uac19\uc740 \ub9ce\uc740 \ubb38\ud654\uc720\uc0b0\uc774 \ub0a8\uc544 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \ud55c\uad6d\uc758 \uc5ed\uc0ac\uc640 \uc804\ud1b5\ubb38\ud654\ub97c \uc54c\uace0 \uc2f6\uc740 \uc0ac\ub78c\ub4e4\uc774 \ub9ce\uc774 \ubc29\ubb38\ud569\ub2c8\ub2e4.\n\n\ubd80\uc0b0\uc740 \ubc14\ub2e4\uc640 \ud56d\uad6c\uac00 \ubc1c\ub2ec\ud55c \ub3c4\uc2dc\uc785\ub2c8\ub2e4. \ud574\uc6b4\ub300\uc640 \uac19\uc740 \ud574\ubcc0\uc740 \ub9ce\uc740 \uc0ac\ub78c\ub4e4\uc774 \ucc3e\ub294 \ub300\ud45c\uc801\uc778 \uad00\uad11\uc9c0\uc785\ub2c8\ub2e4.\n\n\uc81c\uc8fc\ub3c4\ub294 \ud654\uc0b0 \ud65c\ub3d9\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc9c4 \uc12c\uc73c\ub85c \ud55c\ub77c\uc0b0, \uc624\ub984, \ud574\uc548 \ub4f1 \ub3c5\ud2b9\ud55c \uc790\uc5f0\uacbd\uad00\uc744 \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uad00\uad11\uba85\uc18c\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc9c0\uc5ed\ucd95\uc81c\ub3c4 \uc9c0\uc5ed\uc744 \uc774\ud574\ud558\ub294 \uc88b\uc740 \ubc29\ubc95\uc785\ub2c8\ub2e4.\n\n\uc9c0\uc5ed\ucd95\uc81c\ub294 \uadf8 \uc9c0\uc5ed\uc758 \uc790\uc5f0\ud658\uacbd, \uc5ed\uc0ac, \uc804\ud1b5\ubb38\ud654, \uc74c\uc2dd\uc774\ub098 \ud2b9\uc0b0\ubb3c \ub4f1\uc744 \uc8fc\uc81c\ub85c \uc5f4\ub9ac\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.\n\n\uc608\ub97c \ub4e4\uc5b4 \ucda9\uccad\ub0a8\ub3c4 \ubcf4\ub839\uc5d0\uc11c\ub294 \uba38\ub4dc\ub97c \uc8fc\uc81c\ub85c \ud55c \ucd95\uc81c\uac00 \uc798 \uc54c\ub824\uc838 \uc788\uc2b5\ub2c8\ub2e4. \uc548\ub3d9\uc5d0\uc11c\ub294 \ud0c8\ucda4\uacfc \uc804\ud1b5\ubb38\ud654\ub97c \uc911\uc2ec\uc73c\ub85c \ud55c \ucd95\uc81c\uac00 \uc5f4\ub9bd\ub2c8\ub2e4.\n\n\uacbd\uc0c1\ub0a8\ub3c4 \uc9c4\uc8fc\uc5d0\uc11c\ub294 \ub0a8\uac15 \uc8fc\ubcc0\uc758 \uc544\ub984\ub2e4\uc6b4 \uc720\ub4f1\uc744 \ubcfc \uc218 \uc788\ub294 \ucd95\uc81c\uac00 \uc798 \uc54c\ub824\uc838 \uc788\uc2b5\ub2c8\ub2e4. \uac15\uc6d0 \uc9c0\uc5ed\uc758 \ud654\ucc9c\uc5d0\uc11c\ub294 \uaca8\uc6b8\uc758 \uc790\uc5f0\ud658\uacbd\uc744 \uc774\uc6a9\ud55c \uc0b0\ucc9c\uc5b4\ucd95\uc81c\uac00 \uc720\uba85\ud569\ub2c8\ub2e4.\n\n\uc774\ub7ec\ud55c \ucd95\uc81c\uc5d0\ub294 \uc9c0\uc5ed \uc8fc\ubbfc\ubfd0 \uc544\ub2c8\ub77c \ub2e4\ub978 \uc9c0\uc5ed\uc774\ub098 \uc678\uad6d\uc5d0\uc11c \uc628 \uad00\uad11\uac1d\ub4e4\ub3c4 \ucc38\uc5ec\ud569\ub2c8\ub2e4.\n\n\uc9c0\uc5ed\ucd95\uc81c\uc5d0 \uad00\uad11\uac1d\uc774 \ub9ce\uc774 \ucc3e\uc544\uc624\uba74 \uc219\ubc15, \uc74c\uc2dd\uc810, \uad50\ud1b5, \ud2b9\uc0b0\ubb3c \ud310\ub9e4 \ub4f1 \uc5ec\ub7ec \ubd84\uc57c\uc758 \uc18c\ube44\uac00 \ub298\uc5b4\ub0a0 \uc218 \uc788\uae30 \ub54c\ubb38\uc5d0 \uc9c0\uc5ed\uacbd\uc81c\uc5d0\ub3c4 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ub610\ud55c \ucd95\uc81c\ub294 \uc9c0\uc5ed\uc758 \ubb38\ud654\uc640 \ud2b9\uc0c9\uc744 \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uc54c\ub9ac\ub294 \ud64d\ubcf4 \uc5ed\ud560\ub3c4 \ud569\ub2c8\ub2e4.\n\n\uadf8\ub7ec\ub098 \uad00\uad11\uac1d\uc774 \ub108\ubb34 \ub9ce\uc774 \ubab0\ub9ac\uba74 \uad50\ud1b5 \ud63c\uc7a1, \uc4f0\ub808\uae30, \uc790\uc5f0\ud658\uacbd \ud6fc\uc190 \ub4f1\uc758 \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud560 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ub530\ub77c\uc11c \uc9c0\uc5ed\uc758 \uad00\uad11\uc790\uc6d0\uc744 \uc798 \ubcf4\ud638\ud558\uba74\uc11c \uad00\uad11\uc0b0\uc5c5\uc744 \uc9c0\uc18d\uc801\uc73c\ub85c \ubc1c\uc804\uc2dc\ud0a4\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.\n\n\ucd95\uc81c\ub294 \ub9e4\ub144 \uac1c\ucd5c \uc2dc\uae30\uc640 \ud504\ub85c\uadf8\ub7a8\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc73c\ubbc0\ub85c \uc2e4\uc81c \ubc29\ubb38\ud560 \ub54c\uc5d0\ub294 \uacf5\uc2dd \uc815\ubcf4\ub97c \ubbf8\ub9ac \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.\n","H\xe0n Qu\u1ed1c c\xf3 nhi\u1ec1u danh lam du l\u1ecbch kh\xe1c nhau b\u1edfi m\xf4i tr\u01b0\u1eddng t\u1ef1 nhi\xean, l\u1ecbch s\u1eed v\xe0 v\u0103n h\xf3a c\u1ee7a t\u1eebng v\xf9ng kh\xf4ng gi\u1ed1ng nhau.\n\nT\u1ea1i Seoul, du kh\xe1ch c\xf3 th\u1ec3 tr\u1ea3i nghi\u1ec7m l\u1ecbch s\u1eed v\xe0 v\u0103n h\xf3a Joseon th\xf4ng qua c\xe1c cung \u0111i\u1ec7n nh\u01b0 Gyeongbokgung. Ngo\xe0i ra c\xf2n c\xf3 nhi\u1ec1u c\u01a1 s\u1edf du l\u1ecbch nh\u01b0 b\u1ea3o t\xe0ng, nh\xe0 bi\u1ec3u di\u1ec5n v\xe0 ch\u1ee3 truy\u1ec1n th\u1ed1ng.\n\nGyeongju t\u1eebng l\xe0 kinh \u0111\xf4 c\u1ee7a Silla n\xean c\xf2n l\u01b0u gi\u1eef nhi\u1ec1u di s\u1ea3n v\u0103n h\xf3a nh\u01b0 Bulguksa. V\xec v\u1eady, c\xf3 nhi\u1ec1u ng\u01b0\u1eddi mu\u1ed1n t\xecm hi\u1ec3u l\u1ecbch s\u1eed v\xe0 v\u0103n h\xf3a truy\u1ec1n th\u1ed1ng H\xe0n Qu\u1ed1c t\u1edbi \u0111\xe2y.\n\nBusan l\xe0 th\xe0nh ph\u1ed1 ph\xe1t tri\u1ec3n d\u1ef1a tr\xean bi\u1ec3n v\xe0 c\u1ea3ng. Nh\u1eefng b\xe3i bi\u1ec3n nh\u01b0 Haeundae l\xe0 c\xe1c \u0111\u1ecba \u0111i\u1ec3m du l\u1ecbch ti\xeau bi\u1ec3u \u0111\u01b0\u1ee3c nhi\u1ec1u ng\u01b0\u1eddi t\xecm \u0111\u1ebfn.\n\nJeju l\xe0 h\xf2n \u0111\u1ea3o \u0111\u01b0\u1ee3c h\xecnh th\xe0nh t\u1eeb ho\u1ea1t \u0111\u1ed9ng n\xfai l\u1eeda. T\u1ea1i \u0111\xe2y c\xf3 th\u1ec3 th\u1ea5y nh\u1eefng c\u1ea3nh quan t\u1ef1 nhi\xean \u0111\u1ed9c \u0111\xe1o nh\u01b0 Hallasan, c\xe1c \u0111\u1ed3i n\xfai l\u1eeda oreum v\xe0 b\u1edd bi\u1ec3n.\n\nKh\xf4ng ch\u1ec9 c\xe1c danh lam, l\u1ec5 h\u1ed9i \u0111\u1ecba ph\u01b0\u01a1ng c\u0169ng l\xe0 m\u1ed9t c\xe1ch t\u1ed1t \u0111\u1ec3 hi\u1ec3u t\u1eebng v\xf9ng.\n\nL\u1ec5 h\u1ed9i \u0111\u1ecba ph\u01b0\u01a1ng th\u01b0\u1eddng \u0111\u01b0\u1ee3c t\u1ed5 ch\u1ee9c v\u1edbi ch\u1ee7 \u0111\u1ec1 li\xean quan \u0111\u1ebfn m\xf4i tr\u01b0\u1eddng t\u1ef1 nhi\xean, l\u1ecbch s\u1eed, v\u0103n h\xf3a truy\u1ec1n th\u1ed1ng, m\xf3n \u0103n hay \u0111\u1eb7c s\u1ea3n c\u1ee7a ch\xednh khu v\u1ef1c \u0111\xf3.\n\nV\xed d\u1ee5, t\u1ea1i Boryeong thu\u1ed9c Chungcheong Nam c\xf3 l\u1ec5 h\u1ed9i n\u1ed5i ti\u1ebfng l\u1ea5y b\xf9n l\xe0m ch\u1ee7 \u0111\u1ec1. T\u1ea1i Andong c\xf3 l\u1ec5 h\u1ed9i t\u1eadp trung v\xe0o m\xfaa m\u1eb7t n\u1ea1 v\xe0 v\u0103n h\xf3a truy\u1ec1n th\u1ed1ng.\n\n\u1ede Jinju thu\u1ed9c Gyeongsang Nam c\xf3 l\u1ec5 h\u1ed9i n\u1ed5i ti\u1ebfng v\u1edbi nh\u1eefng chi\u1ebfc \u0111\xe8n l\u1ed3ng \u0111\u1eb9p b\xean s\xf4ng Namgang. T\u1ea1i Hwacheon thu\u1ed9c v\xf9ng Gangwon, l\u1ec5 h\u1ed9i c\xe1 m\xf9a \u0111\xf4ng c\u0169ng \u0111\u01b0\u1ee3c nhi\u1ec1u ng\u01b0\u1eddi bi\u1ebft \u0111\u1ebfn.\n\nKh\xf4ng ch\u1ec9 ng\u01b0\u1eddi d\xe2n \u0111\u1ecba ph\u01b0\u01a1ng m\xe0 kh\xe1ch t\u1eeb c\xe1c v\xf9ng kh\xe1c v\xe0 kh\xe1ch n\u01b0\u1edbc ngo\xe0i c\u0169ng tham gia nh\u1eefng l\u1ec5 h\u1ed9i n\xe0y.\n\nKhi nhi\u1ec1u kh\xe1ch du l\u1ecbch t\u1edbi tham d\u1ef1, chi ti\xeau cho nh\xe0 ngh\u1ec9, nh\xe0 h\xe0ng, giao th\xf4ng v\xe0 \u0111\u1eb7c s\u1ea3n \u0111\u1ecba ph\u01b0\u01a1ng c\xf3 th\u1ec3 t\u0103ng l\xean, t\u1eeb \u0111\xf3 g\xf3p ph\u1ea7n th\xfac \u0111\u1ea9y kinh t\u1ebf \u0111\u1ecba ph\u01b0\u01a1ng.\n\nL\u1ec5 h\u1ed9i c\u0169ng c\xf3 vai tr\xf2 qu\u1ea3ng b\xe1 v\u0103n h\xf3a v\xe0 n\xe9t ri\xeang c\u1ee7a m\u1ed9t v\xf9ng t\u1edbi nhi\u1ec1u ng\u01b0\u1eddi h\u01a1n.\n\nTuy nhi\xean, n\u1ebfu qu\xe1 nhi\u1ec1u kh\xe1ch t\u1eadp trung c\xf9ng l\xfac th\xec c\u0169ng c\xf3 th\u1ec3 ph\xe1t sinh c\xe1c v\u1ea5n \u0111\u1ec1 nh\u01b0 \xf9n t\u1eafc giao th\xf4ng, r\xe1c th\u1ea3i v\xe0 t\u1ed5n h\u1ea1i m\xf4i tr\u01b0\u1eddng t\u1ef1 nhi\xean.\n\nV\xec v\u1eady, \u0111i\u1ec1u quan tr\u1ecdng l\xe0 v\u1eeba b\u1ea3o v\u1ec7 t\u1ed1t t\xe0i nguy\xean du l\u1ecbch \u0111\u1ecba ph\u01b0\u01a1ng v\u1eeba ph\xe1t tri\u1ec3n ng\xe0nh du l\u1ecbch m\u1ed9t c\xe1ch b\u1ec1n v\u1eefng.\n\nTh\u1eddi gian v\xe0 ch\u01b0\u01a1ng tr\xecnh l\u1ec5 h\u1ed9i c\xf3 th\u1ec3 thay \u0111\u1ed5i theo t\u1eebng n\u0103m, v\xec v\u1eady khi th\u1ef1c s\u1ef1 t\u1edbi tham d\u1ef1 n\xean ki\u1ec3m tra th\xf4ng tin ch\xednh th\u1ee9c tr\u01b0\u1edbc.\n","\uc9c0\uc5ed\ucd95\uc81c \uc5ec\ud589 \uacc4\ud68d\ud558\uae30","\uc548: \ubbfc\uc218 \uc528, \ud55c\uad6d\uc5d0\uc11c \uc9c0\uc5ed\ucd95\uc81c\uc5d0 \ud55c \ubc88 \uac00 \ubcf4\uace0 \uc2f6\uc5b4\uc694.\n\n\ubbfc\uc218: \uc88b\uc544\uc694. \uc5b4\ub5a4 \uac83\uc744 \uc88b\uc544\ud558\uc138\uc694?\n\n\uc548: \uc804\ud1b5\ubb38\ud654\ub97c \uc9c1\uc811 \uccb4\ud5d8\ud558\uace0 \uc2f6\uc5b4\uc694.\n\n\ubbfc\uc218: \uadf8\ub7ec\uba74 \uc548\ub3d9\uc758 \ud0c8\ucda4 \uad00\ub828 \ucd95\uc81c\ub97c \uc54c\uc544\ubcf4\ub294 \uac83\ub3c4 \uc88b\uc544\uc694.\n\n\uc548: \ubc14\ub2e4 \uadfc\ucc98\uc5d0\uc11c \uc990\uae38 \uc218 \uc788\ub294 \ucd95\uc81c\ub3c4 \uc788\uc5b4\uc694?\n\n\ubbfc\uc218: \ubcf4\ub839\uc758 \uba38\ub4dc\ucd95\uc81c\ub3c4 \uc798 \uc54c\ub824\uc838 \uc788\uc5b4\uc694.\n\n\uc548: \uc57c\uacbd\uc774\ub098 \uc544\ub984\ub2e4\uc6b4 \ub4f1\uc744 \ubcf4\uace0 \uc2f6\uc73c\uba74\uc694?\n\n\ubbfc\uc218: \uc9c4\uc8fc\uc758 \ub0a8\uac15\uc720\ub4f1\ucd95\uc81c\ub97c \uc54c\uc544\ubcf4\uc138\uc694.\n\n\uc548: \uaca8\uc6b8\uc5d0\ub294 \uc5b4\ub5a4 \ucd95\uc81c\uac00 \uc788\uc5b4\uc694?\n\n\ubbfc\uc218: \uac15\uc6d0 \uc9c0\uc5ed\uc758 \ud654\ucc9c\uc0b0\ucc9c\uc5b4\ucd95\uc81c\uac00 \uaca8\uc6b8\ucd95\uc81c\ub85c \uc798 \uc54c\ub824\uc838 \uc788\uc5b4\uc694.\n\n\uc548: \ucd95\uc81c\ub294 \ud56d\uc0c1 \uac19\uc740 \ub0a0\uc9dc\uc5d0 \uc5f4\ub824\uc694?\n\n\ubbfc\uc218: \uc544\ub2c8\uc694. \uac1c\ucd5c \uae30\uac04\uc774\ub098 \ud504\ub85c\uadf8\ub7a8\uc740 \ud574\ub9c8\ub2e4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc5b4\uc694.\n\n\uc548: \uadf8\ub7ec\uba74 \uac00\uae30 \uc804\uc5d0 \uc778\ud130\ub137\uc5d0\uc11c \ud655\uc778\ud574\uc57c\uaca0\ub124\uc694.\n\n\ubbfc\uc218: \ub124. \uacf5\uc2dd \ud648\ud398\uc774\uc9c0\ub098 \uc9c0\uc5ed \uad00\uad11 \uc815\ubcf4\ub97c \ud655\uc778\ud558\ub294 \uac8c \uc88b\uc544\uc694.\n\n\uc548: \ucd95\uc81c\uac00 \uc9c0\uc5ed\uacbd\uc81c\uc5d0\ub3c4 \ub3c4\uc6c0\uc774 \ub418\ub098\uc694?\n\n\ubbfc\uc218: \ub124. \uad00\uad11\uac1d\uc774 \uc624\uba74 \uc219\ubc15\uc774\ub098 \uc74c\uc2dd, \uad50\ud1b5, \ud2b9\uc0b0\ubb3c \uc18c\ube44\uac00 \ub298\uc5b4\ub0a0 \uc218 \uc788\uc5b4\uc694.\n\n\uc548: \uadf8\ub7f0\ub370 \uc0ac\ub78c\uc774 \ub108\ubb34 \ub9ce\uc73c\uba74 \ubb38\uc81c\ub3c4 \uc0dd\uae38 \uac83 \uac19\uc544\uc694.\n\n\ubbfc\uc218: \ub9de\uc544\uc694. \uadf8\ub798\uc11c \uad00\uad11\uc744 \ubc1c\uc804\uc2dc\ud0a4\uba74\uc11c \uc790\uc5f0\uacfc \ubb38\ud654\uc720\uc0b0\uc744 \ubcf4\ud638\ud558\ub294 \uac83\ub3c4 \uc911\uc694\ud574\uc694.\n","An: Minsu, t\xf4i mu\u1ed1n th\u1eed tham d\u1ef1 m\u1ed9t l\u1ec5 h\u1ed9i \u0111\u1ecba ph\u01b0\u01a1ng \u1edf H\xe0n Qu\u1ed1c.\n\nMinsu: \u0110\u01b0\u1ee3c ch\u1ee9. Anh th\xedch lo\u1ea1i n\xe0o?\n\nAn: T\xf4i mu\u1ed1n tr\u1ef1c ti\u1ebfp tr\u1ea3i nghi\u1ec7m v\u0103n h\xf3a truy\u1ec1n th\u1ed1ng.\n\nMinsu: V\u1eady c\xf3 th\u1ec3 t\xecm hi\u1ec3u l\u1ec5 h\u1ed9i m\xfaa m\u1eb7t n\u1ea1 \u1edf Andong.\n\nAn: C\xf3 l\u1ec5 h\u1ed9i n\xe0o c\xf3 th\u1ec3 vui ch\u01a1i g\u1ea7n bi\u1ec3n kh\xf4ng?\n\nMinsu: L\u1ec5 h\u1ed9i b\xf9n Boryeong c\u0169ng r\u1ea5t n\u1ed5i ti\u1ebfng.\n\nAn: N\u1ebfu mu\u1ed1n xem c\u1ea3nh \u0111\xeam v\xe0 nh\u1eefng chi\u1ebfc \u0111\xe8n \u0111\u1eb9p th\xec sao?\n\nMinsu: H\xe3y t\xecm hi\u1ec3u l\u1ec5 h\u1ed9i \u0111\xe8n l\u1ed3ng Namgang \u1edf Jinju.\n\nAn: M\xf9a \u0111\xf4ng c\xf3 l\u1ec5 h\u1ed9i n\xe0o?\n\nMinsu: L\u1ec5 h\u1ed9i c\xe1 \u1edf Hwacheon, Gangwon kh\xe1 n\u1ed5i ti\u1ebfng nh\u01b0 m\u1ed9t l\u1ec5 h\u1ed9i m\xf9a \u0111\xf4ng.\n\nAn: L\u1ec5 h\u1ed9i lu\xf4n t\u1ed5 ch\u1ee9c v\xe0o c\xf9ng m\u1ed9t ng\xe0y \xe0?\n\nMinsu: Kh\xf4ng. Th\u1eddi gian v\xe0 ch\u01b0\u01a1ng tr\xecnh c\xf3 th\u1ec3 thay \u0111\u1ed5i m\u1ed7i n\u0103m.\n\nAn: V\u1eady tr\u01b0\u1edbc khi \u0111i ph\u1ea3i ki\u1ec3m tra tr\xean m\u1ea1ng nh\u1ec9.\n\nMinsu: V\xe2ng. T\u1ed1t nh\u1ea5t n\xean ki\u1ec3m tra trang ch\xednh th\u1ee9c ho\u1eb7c th\xf4ng tin du l\u1ecbch c\u1ee7a \u0111\u1ecba ph\u01b0\u01a1ng.\n\nAn: L\u1ec5 h\u1ed9i c\u0169ng gi\xfap kinh t\u1ebf \u0111\u1ecba ph\u01b0\u01a1ng \xe0?\n\nMinsu: V\xe2ng. Khi kh\xe1ch du l\u1ecbch t\u1edbi, ti\xeau d\xf9ng cho ch\u1ed7 \u1edf, \u0103n u\u1ed1ng, giao th\xf4ng v\xe0 \u0111\u1eb7c s\u1ea3n c\xf3 th\u1ec3 t\u0103ng.\n\nAn: Nh\u01b0ng n\u1ebfu qu\xe1 \u0111\xf4ng ng\u01b0\u1eddi th\xec c\u0169ng c\xf3 th\u1ec3 c\xf3 v\u1ea5n \u0111\u1ec1.\n\nMinsu: \u0110\xfang. V\xec v\u1eady v\u1eeba ph\xe1t tri\u1ec3n du l\u1ecbch v\u1eeba b\u1ea3o v\u1ec7 thi\xean nhi\xean v\xe0 di s\u1ea3n v\u0103n h\xf3a l\xe0 r\u1ea5t quan tr\u1ecdng.\n",A.iyi,A.hHa,A.fBN,A.hIQ)
A.fGI=s(["Bi\u1ebft t\xean ch\xednh th\u1ee9c c\u1ee7a H\xe0n Qu\u1ed1c: \ub300\ud55c\ubbfc\uad6d.","Bi\u1ebft qu\u1ed1c k\u1ef3 c\u1ee7a H\xe0n Qu\u1ed1c l\xe0 \ud0dc\uadf9\uae30.","Hi\u1ec3u c\u1ea5u t\u1ea1o c\u01a1 b\u1ea3n c\u1ee7a \ud0dc\uadf9\uae30.","Bi\u1ebft qu\u1ed1c ca \uc560\uad6d\uac00.","Bi\u1ebft \ubb34\uad81\ud654 l\xe0 lo\xe0i hoa t\u01b0\u1ee3ng tr\u01b0ng cho H\xe0n Qu\u1ed1c.","Bi\u1ebft \uc11c\uc6b8 l\xe0 th\u1ee7 \u0111\xf4 c\u1ee7a \ub300\ud55c\ubbfc\uad6d.","C\xf3 th\u1ec3 tr\u1ea3 l\u1eddi c\xe1c c\xe2u h\u1ecfi c\u01a1 b\u1ea3n v\u1ec1 bi\u1ec3u t\u01b0\u1ee3ng qu\u1ed1c gia."],t.s)
A.hPX=s(["\ub300\ud55c\ubbfc\uad6d\uc740 \ud55c\uad6d\uc758 \uacf5\uc2dd \uad6d\ud638\uc785\ub2c8\ub2e4.","\ub300\ud55c\ubbfc\uad6d\uc758 \uc218\ub3c4\ub294 \uc11c\uc6b8\uc785\ub2c8\ub2e4.","\ub300\ud55c\ubbfc\uad6d\uc758 \uad6d\uae30\ub294 \ud0dc\uadf9\uae30\uc785\ub2c8\ub2e4.","\ud0dc\uadf9\uae30\uc758 \ubc14\ud0d5\uc740 \ud770\uc0c9\uc785\ub2c8\ub2e4.","\ud0dc\uadf9\uae30\uc758 \uac00\uc6b4\ub370\uc5d0\ub294 \ud0dc\uadf9 \ubb38\uc591\uc774 \uc788\uc2b5\ub2c8\ub2e4.","\ud0dc\uadf9\uae30\uc5d0\ub294 \uac74, \uace4, \uac10, \ub9ac \ub124 \uac1c\uc758 \uad18\uac00 \uc788\uc2b5\ub2c8\ub2e4.","\ub300\ud55c\ubbfc\uad6d\uc758 \uad6d\uac00\ub294 \uc560\uad6d\uac00\uc785\ub2c8\ub2e4.","\ubb34\uad81\ud654\ub294 \ud55c\uad6d\uc744 \uc0c1\uc9d5\ud558\ub294 \uaf43\uc73c\ub85c \ub110\ub9ac \uc54c\ub824\uc838 \uc788\uc2b5\ub2c8\ub2e4."],t.s)
