A.fuc=new B.p("\uc870\uc120","\u0111\xf3ng t\xe0u / ng\xe0nh \u0111\xf3ng t\xe0u","\ud55c\uad6d\uc758 \uc870\uc120 \uc0b0\uc5c5\uc740 \uc138\uacc4 \uc2dc\uc7a5\uacfc \ubc00\uc811\ud55c \uad00\uacc4\uac00 \uc788\uc2b5\ub2c8\ub2e4.","Ng\xe0nh \u0111\xf3ng t\xe0u H\xe0n Qu\u1ed1c c\xf3 quan h\u1ec7 ch\u1eb7t ch\u1ebd v\u1edbi th\u1ecb tr\u01b0\u1eddng th\u1ebf gi\u1edbi.")
A.fom=new B.p("\uc804\uc790\uc0b0\uc5c5","ng\xe0nh \u0111i\u1ec7n t\u1eed","\uc804\uc790\uc0b0\uc5c5\ub3c4 \ud55c\uad6d\uc758 \uc911\uc694\ud55c \uc0b0\uc5c5 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4.","Ng\xe0nh \u0111i\u1ec7n t\u1eed c\u0169ng l\xe0 m\u1ed9t trong nh\u1eefng ng\xe0nh quan tr\u1ecdng c\u1ee7a H\xe0n Qu\u1ed1c.")
A.fmx=new B.p("\uc0dd\ud65c\uc218\uc900","m\u1ee9c s\u1ed1ng","\uacbd\uc81c\uc131\uc7a5\uacfc \ud568\uaed8 \uad6d\ubbfc\uc758 \uc0dd\ud65c\uc218\uc900\ub3c4 \ub192\uc544\uc84c\uc2b5\ub2c8\ub2e4.","C\xf9ng v\u1edbi t\u0103ng tr\u01b0\u1edfng kinh t\u1ebf, m\u1ee9c s\u1ed1ng c\u1ee7a ng\u01b0\u1eddi d\xe2n c\u0169ng \u0111\u01b0\u1ee3c n\xe2ng cao.")
