A.j5z=s(["\uad8c\ub9ac = quy\u1ec1n; \uad8c\ub9ac \uce68\ud574 = h\xe0nh vi/t\xecnh tr\u1ea1ng quy\u1ec1n b\u1ecb x\xe2m ph\u1ea1m.","\ud53c\ud574 = thi\u1ec7t h\u1ea1i; \ud53c\ud574\uc790 = ng\u01b0\u1eddi b\u1ecb h\u1ea1i.","\ucc28\ubcc4 = ph\xe2n bi\u1ec7t \u0111\u1ed1i x\u1eed; \ubaa8\ub4e0 \ucc28\uc774\uac00 \uace7 \ubd88\ubc95\uc801\uc778 \ucc28\ubcc4\uc744 \uc758\ubbf8\ud558\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.","\uac1c\uc778\uc815\ubcf4\uc640 \uc0ac\uc0dd\ud65c\uc740 \uad00\ub828\uc774 \uc788\uc9c0\ub9cc \uc644\uc804\ud788 \uac19\uc740 \uac1c\ub150\uc740 \uc544\ub2d9\ub2c8\ub2e4.","\uc784\uae08\uccb4\ubd88\uc740 \uadfc\ub85c\uc790\uc758 \uad8c\ub9ac \ubb38\uc81c\uc640 \uad00\ub828\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uad8c\ub9ac\ub97c \uce68\ud574\ubc1b\uc558\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uac10\uc815\uc801\uc778 \ub300\uc751\ubcf4\ub2e4 \uc0ac\uc2e4\uacfc \uc790\ub8cc\ub97c \uba3c\uc800 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","\uc99d\uac70\uac00 \ub420 \uc218 \uc788\ub294 \uc790\ub8cc\ub294 \uc0ac\uac74\uc758 \uc885\ub958\uc5d0 \ub530\ub77c \ub2e4\ub97c \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc790\uc2e0\uc758 \uad8c\ub9ac\ub97c \uc8fc\uc7a5\ud560 \ub54c\uc5d0\ub3c4 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uad8c\ub9ac\ub97c \uce68\ud574\ud558\uba74 \uc548 \ub429\ub2c8\ub2e4."],t.s)
A.iJN=s(["\uad8c\ub9ac \u2192 quy\u1ec1n.","\uce68\ud574 \u2192 x\xe2m ph\u1ea1m.","\uad8c\ub9ac \uce68\ud574 \u2192 quy\u1ec1n b\u1ecb x\xe2m ph\u1ea1m.","\ud53c\ud574\uc790 \u2192 ng\u01b0\u1eddi b\u1ecb h\u1ea1i.","\ucc28\ubcc4 \u2192 ph\xe2n bi\u1ec7t \u0111\u1ed1i x\u1eed.","\uac1c\uc778\uc815\ubcf4 \u2192 th\xf4ng tin c\xe1 nh\xe2n.","\uc784\uae08\uccb4\ubd88 \u2192 n\u1ee3/ch\u1eadm tr\u1ea3 l\u01b0\u01a1ng.","\uc99d\uac70 \u2192 ch\u1ee9ng c\u1ee9.","\uad8c\ub9ac \uce68\ud574\uac00 \uc758\uc2ec\ub418\uba74 \uc0ac\uc2e4\uad00\uacc4\uc640 \uad00\ub828 \uc790\ub8cc\ub97c \ud655\uc778\ud55c\ub2e4.","\ubb38\uc790, \uc0ac\uc9c4, \uacc4\uc57d\uc11c, \uc601\uc218\uc99d \ub4f1\uc740 \uc0c1\ud669\uc5d0 \ub530\ub77c \uc790\ub8cc\uac00 \ub420 \uc218 \uc788\ub2e4.","\ud63c\uc790 \ud574\uacb0\ud558\uae30 \uc5b4\ub824\uc6b0\uba74 \uad00\ub828 \uae30\uad00\uc5d0 \uc0c1\ub2f4\ud560 \uc218 \uc788\ub2e4.","\uc790\uc2e0\uc758 \uad8c\ub9ac\uc640 \ud568\uaed8 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uad8c\ub9ac\ub3c4 \uc874\uc911\ud574\uc57c \ud55c\ub2e4."],t.s)
A.h4p=s(["\ub2e4\ub978 \uc0ac\ub78c\uc758 \uad8c\ub9ac\ub97c \ubd80\ub2f9\ud558\uac8c \ud574\uce58\ub294 \uac83","\ub2e4\ub978 \uc0ac\ub78c\uc744 \ub3c4\uc640\uc8fc\ub294 \uac83","\uc740\ud589\uc5d0 \ub3c8\uc744 \uc800\ucd95\ud558\ub294 \uac83","\uc0c1\ud488\uc744 \uc218\ucd9c\ud558\ub294 \uac83"],t.s)
A.f7C=new B.G("\u201c\uad8c\ub9ac \uce68\ud574\u201d\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\xdd ngh\u0129a ph\xf9 h\u1ee3p nh\u1ea5t c\u1ee7a \u201cx\xe2m ph\u1ea1m quy\u1ec1n l\u1ee3i\u201d l\xe0 g\xec?",A.h4p,0,"\uad8c\ub9ac \uce68\ud574 l\xe0 vi\u1ec7c x\xe2m h\u1ea1i kh\xf4ng ch\xednh \u0111\xe1ng \u0111\u1ebfn quy\u1ec1n c\u1ee7a ng\u01b0\u1eddi kh\xe1c.")
A.hwJ=s(["\uc0ac\uc2e4\uad00\uacc4\uc640 \uad00\ub828 \uc790\ub8cc\ub97c \ud655\uc778\ud55c\ub2e4.","\ubaa8\ub4e0 \uc790\ub8cc\ub97c \ubc84\ub9b0\ub2e4.","\ubc14\ub85c \ud3ed\ub825\uc744 \uc0ac\uc6a9\ud55c\ub2e4.","\uc544\ubb34 \ub0b4\uc6a9\ub3c4 \ud655\uc778\ud558\uc9c0 \uc54a\ub294\ub2e4."],t.s)
A.f9O=new B.G("\uad8c\ub9ac \uce68\ud574\uac00 \uc758\uc2ec\ub420 \ub54c \uba3c\uc800 \ud560 \uc77c\ub85c \uc54c\ub9de\uc740 \uac83\uc740?","Khi nghi ng\u1edd quy\u1ec1n l\u1ee3i b\u1ecb x\xe2m ph\u1ea1m, vi\u1ec7c n\xean l\xe0m tr\u01b0\u1edbc ti\xean l\xe0 g\xec?",A.hwJ,0,"Tr\u01b0\u1edbc ti\xean c\u1ea7n x\xe1c \u0111\u1ecbnh s\u1ef1 vi\u1ec7c v\xe0 ki\u1ec3m tra t\xe0i li\u1ec7u li\xean quan.")
