A.fbk=new B.G("\uac1c\uc778\uc815\ubcf4\ub97c \ubcf4\ud638\ud558\ub294 \ud589\ub3d9\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","H\xe0nh \u0111\u1ed9ng n\xe0o ph\xf9 h\u1ee3p \u0111\u1ec3 b\u1ea3o v\u1ec7 th\xf4ng tin c\xe1 nh\xe2n?",A.fRv,0,"Kh\xf4ng n\xean t\xf9y ti\u1ec7n cung c\u1ea5p th\xf4ng tin c\xe1 nh\xe2n quan tr\u1ecdng.")
