A.igz=s(["\uc0bc\uad8c\ubd84\ub9bd = tam quy\u1ec1n ph\xe2n l\u1eadp.","\uc785\ubc95 = l\u1eadp ph\xe1p.","\ud589\uc815 = h\xe0nh ph\xe1p.","\uc0ac\ubc95 = t\u01b0 ph\xe1p.","\uc785\ubc95\ubd80\uc758 \ub300\ud45c \uae30\uad00 = \uad6d\ud68c.","\ud589\uc815\ubd80\ub294 \ubc95\ub960\uacfc \uc815\ucc45\uc744 \uc9d1\ud589\ud569\ub2c8\ub2e4.","\ub300\ud1b5\ub839\uc740 \ud589\uc815\ubd80\ub97c \uc774\ub044\ub294 \uc911\uc694\ud55c \uad6d\uac00\uae30\uad00\uc785\ub2c8\ub2e4.","\uc0ac\ubc95\ubd80\uc758 \ub300\ud45c \uae30\uad00 = \ubc95\uc6d0.","\ubc95\uc6d0\uc740 \uc7ac\ud310\uc744 \ud1b5\ud574 \ubc95\uc744 \uc801\uc6a9\ud569\ub2c8\ub2e4.","\ud5cc\ubc95\uc7ac\ud310\uc18c\ub294 \ud5cc\ubc95\uacfc \uad00\ub828\ub41c \uc911\uc694\ud55c \ubb38\uc81c\ub97c \ud310\ub2e8\ud569\ub2c8\ub2e4.","\uc0bc\uad8c\ubd84\ub9bd\uc740 \uad6d\uac00 \uad8c\ub825\uc774 \ud55c \uae30\uad00\uc5d0 \uc9d1\uc911\ub418\ub294 \uac83\uc744 \ub9c9\ub294 \ub370 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4."],t.s)
A.f3V=new B.dk(21,"\uc815\uce58","\ud55c\uad6d\uc758 \uc815\uce58\uc81c\ub3c4","Ch\u1ebf \u0111\u1ed9 ch\xednh tr\u1ecb c\u1ee7a H\xe0n Qu\u1ed1c",A.hnp,A.iyT,A.hZ0,A.fWr,"\ub300\ud55c\ubbfc\uad6d\uc758 \uc0bc\uad8c\ubd84\ub9bd","\ub300\ud55c\ubbfc\uad6d\uc5d0\uc11c\ub294 \uad6d\uac00\uc758 \uad8c\ub825\uc744 \ud55c \uae30\uad00\uc774 \ubaa8\ub450 \uac00\uc9c0\uc9c0 \uc54a\ub3c4\ub85d \uc785\ubc95, \ud589\uc815, \uc0ac\ubc95\uc73c\ub85c \ub098\ub204\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uc6d0\ub9ac\ub97c \uc0bc\uad8c\ubd84\ub9bd\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4.\n\n\uc785\ubc95\ubd80\uc758 \ub300\ud45c\uc801\uc778 \uae30\uad00\uc740 \uad6d\ud68c\uc785\ub2c8\ub2e4. \uad6d\ud68c\ub294 \ubc95\ub960\uc744 \ub9cc\ub4e4\uace0 \uad6d\uac00\uc758 \uc911\uc694\ud55c \ubb38\uc81c\ub97c \uc2ec\uc758\ud558\ub294 \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4.\n\n\ud589\uc815\ubd80\ub294 \uad6d\ud68c\uc5d0\uc11c \ub9cc\ub4e4\uc5b4\uc9c4 \ubc95\ub960\uc744 \ubc14\ud0d5\uc73c\ub85c \uad6d\uac00\uc758 \uc815\ucc45\uc744 \ub9cc\ub4e4\uace0 \uc2e4\uc81c\ub85c \uc9d1\ud589\ud569\ub2c8\ub2e4. \ub300\ud1b5\ub839\uc740 \ud589\uc815\ubd80\ub97c \uc774\ub044\ub294 \uc911\uc694\ud55c \uad6d\uac00\uae30\uad00\uc785\ub2c8\ub2e4.\n\n\uc0ac\ubc95\ubd80\uc758 \ub300\ud45c\uc801\uc778 \uae30\uad00\uc740 \ubc95\uc6d0\uc785\ub2c8\ub2e4. \ubc95\uc6d0\uc740 \ubc95\ub960\uc5d0 \ub530\ub77c \uc7ac\ud310\uc744 \ud558\uace0 \ubd84\uc7c1\uc744 \ud574\uacb0\ud558\ub294 \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4.\n\n\ub610\ud55c \ub300\ud55c\ubbfc\uad6d\uc5d0\ub294 \ud5cc\ubc95\uc7ac\ud310\uc18c\uac00 \uc788\uc2b5\ub2c8\ub2e4. \ud5cc\ubc95\uc7ac\ud310\uc18c\ub294 \ud5cc\ubc95\uacfc \uad00\ub828\ub41c \uc911\uc694\ud55c \ubb38\uc81c\ub97c \ud310\ub2e8\ud569\ub2c8\ub2e4.\n\n\uc785\ubc95\ubd80, \ud589\uc815\ubd80, \uc0ac\ubc95\ubd80\uac00 \uc11c\ub85c \ub3c5\ub9bd\uc801\uc778 \uc5ed\ud560\uc744 \ud558\uba74\uc11c\ub3c4 \uc11c\ub85c \uacac\uc81c\ud558\ub294 \uc774\uc720\ub294 \uad6d\uac00 \uad8c\ub825\uc774 \ud55c \uae30\uad00\uc5d0 \uc9c0\ub098\uce58\uac8c \uc9d1\uc911\ub418\ub294 \uac83\uc744 \ub9c9\uae30 \uc704\ud574\uc11c\uc785\ub2c8\ub2e4.\n\n\uc774\ub7ec\ud55c \uad8c\ub825 \ubd84\ub9bd\uc740 \uad6d\ubbfc\uc758 \uc790\uc720\uc640 \uad8c\ub9ac\ub97c \ubcf4\ud638\ud558\uace0 \ubbfc\uc8fc\uc8fc\uc758\ub97c \uc720\uc9c0\ud558\ub294 \ub370 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4.\n","\u1ede H\xe0n Qu\u1ed1c, quy\u1ec1n l\u1ef1c nh\xe0 n\u01b0\u1edbc \u0111\u01b0\u1ee3c chia th\xe0nh l\u1eadp ph\xe1p, h\xe0nh ph\xe1p v\xe0 t\u01b0 ph\xe1p \u0111\u1ec3 m\u1ed9t c\u01a1 quan kh\xf4ng n\u1eafm to\xe0n b\u1ed9 quy\u1ec1n l\u1ef1c. Nguy\xean t\u1eafc n\xe0y \u0111\u01b0\u1ee3c g\u1ecdi l\xe0 tam quy\u1ec1n ph\xe2n l\u1eadp.\n\nC\u01a1 quan ti\xeau bi\u1ec3u c\u1ee7a nh\xe1nh l\u1eadp ph\xe1p l\xe0 Qu\u1ed1c h\u1ed9i. Qu\u1ed1c h\u1ed9i c\xf3 vai tr\xf2 x\xe2y d\u1ef1ng lu\u1eadt v\xe0 xem x\xe9t c\xe1c v\u1ea5n \u0111\u1ec1 quan tr\u1ecdng c\u1ee7a qu\u1ed1c gia.\n\nC\u01a1 quan h\xe0nh ph\xe1p x\xe2y d\u1ef1ng v\xe0 th\u1ef1c thi c\xe1c ch\xednh s\xe1ch c\u1ee7a nh\xe0 n\u01b0\u1edbc d\u1ef1a tr\xean ph\xe1p lu\u1eadt. T\u1ed5ng th\u1ed1ng l\xe0 c\u01a1 quan quan tr\u1ecdng l\xe3nh \u0111\u1ea1o nh\xe1nh h\xe0nh ph\xe1p.\n\nC\u01a1 quan ti\xeau bi\u1ec3u c\u1ee7a nh\xe1nh t\u01b0 ph\xe1p l\xe0 t\xf2a \xe1n. T\xf2a \xe1n ti\u1ebfn h\xe0nh x\xe9t x\u1eed theo ph\xe1p lu\u1eadt v\xe0 gi\u1ea3i quy\u1ebft c\xe1c tranh ch\u1ea5p.\n\nNgo\xe0i ra, H\xe0n Qu\u1ed1c c\xf2n c\xf3 T\xf2a \xe1n Hi\u1ebfn ph\xe1p. T\xf2a \xe1n Hi\u1ebfn ph\xe1p xem x\xe9t nh\u1eefng v\u1ea5n \u0111\u1ec1 quan tr\u1ecdng li\xean quan \u0111\u1ebfn Hi\u1ebfn ph\xe1p.\n\nL\xfd do l\u1eadp ph\xe1p, h\xe0nh ph\xe1p v\xe0 t\u01b0 ph\xe1p c\xf3 vai tr\xf2 \u0111\u1ed9c l\u1eadp nh\u01b0ng \u0111\u1ed3ng th\u1eddi ki\u1ec3m so\xe1t l\u1eabn nhau l\xe0 \u0111\u1ec3 ng\u0103n quy\u1ec1n l\u1ef1c nh\xe0 n\u01b0\u1edbc t\u1eadp trung qu\xe1 m\u1ee9c v\xe0o m\u1ed9t c\u01a1 quan.\n\nVi\u1ec7c ph\xe2n chia quy\u1ec1n l\u1ef1c nh\u01b0 v\u1eady \u0111\xf3ng vai tr\xf2 quan tr\u1ecdng trong vi\u1ec7c b\u1ea3o v\u1ec7 t\u1ef1 do, quy\u1ec1n c\u1ee7a ng\u01b0\u1eddi d\xe2n v\xe0 duy tr\xec n\u1ec1n d\xe2n ch\u1ee7.\n","\uc0bc\uad8c\ubd84\ub9bd \uc774\ud574\ud558\uae30","\uc548: \ubbfc\uc218 \uc528, \uc0bc\uad8c\ubd84\ub9bd\uc774\ub77c\ub294 \ub9d0\uc774 \uc870\uae08 \uc5b4\ub824\uc6cc\uc694.\n\n\ubbfc\uc218: \uc27d\uac8c \ub9d0\ud558\uba74 \uad6d\uac00\uc758 \uad8c\ub825\uc744 \uc138 \ubd80\ubd84\uc73c\ub85c \ub098\ub204\ub294 \uac70\uc608\uc694.\n\n\uc548: \uc5b4\ub5a4 \uc138 \ubd80\ubd84\uc774\uc5d0\uc694?\n\n\ubbfc\uc218: \uc785\ubc95, \ud589\uc815, \uc0ac\ubc95\uc774\uc5d0\uc694.\n\n\uc548: \uc785\ubc95\uc740 \ub204\uac00 \ub2f4\ub2f9\ud574\uc694?\n\n\ubbfc\uc218: \ub300\ud45c\uc801\uc778 \uae30\uad00\uc740 \uad6d\ud68c\uc608\uc694. \ubc95\ub960\uc744 \ub9cc\ub4dc\ub294 \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4.\n\n\uc548: \uadf8\ub7ec\uba74 \ud589\uc815\ubd80\ub294\uc694?\n\n\ubbfc\uc218: \ubc95\uacfc \uc815\ucc45\uc744 \uc2e4\uc81c\ub85c \uc9d1\ud589\ud569\ub2c8\ub2e4. \ub300\ud1b5\ub839\uc774 \ud589\uc815\ubd80\ub97c \uc774\ub04c\uc5b4\uc694.\n\n\uc548: \uc0ac\ubc95\ubd80\ub294 \ubc95\uc6d0\uc774\uc9c0\uc694?\n\n\ubbfc\uc218: \ub9de\uc544\uc694. \ubc95\uc6d0\uc740 \uc7ac\ud310\uc744 \ud1b5\ud574 \ubc95\uc744 \uc801\uc6a9\ud558\uace0 \ubd84\uc7c1\uc744 \ud574\uacb0\ud569\ub2c8\ub2e4.\n\n\uc548: \uc65c \uc774\ub807\uac8c \uad8c\ub825\uc744 \ub098\ub204\ub294 \uac70\uc608\uc694?\n\n\ubbfc\uc218: \ud55c \uae30\uad00\uc5d0 \uad8c\ub825\uc774 \ub108\ubb34 \ub9ce\uc774 \uc9d1\uc911\ub418\ub294 \uac83\uc744 \ub9c9\uae30 \uc704\ud574\uc11c\uc608\uc694.\n\n\uc548: \uadf8\ub7ec\ub2c8\uae4c \uc11c\ub85c \uc5ed\ud560\uc744 \ub098\ub204\uace0 \uacac\uc81c\ud558\ub294 \uac70\uad70\uc694.\n\n\ubbfc\uc218: \ub9de\uc544\uc694. \uadf8\uac83\uc774 \ubbfc\uc8fc\uc8fc\uc758\uc5d0\uc11c \uc911\uc694\ud55c \uc6d0\ub9ac \uc911 \ud558\ub098\uc608\uc694.\n","An: Minsu, t\u1eeb tam quy\u1ec1n ph\xe2n l\u1eadp h\u01a1i kh\xf3 hi\u1ec3u.\n\nMinsu: N\xf3i \u0111\u01a1n gi\u1ea3n l\xe0 chia quy\u1ec1n l\u1ef1c nh\xe0 n\u01b0\u1edbc th\xe0nh ba ph\u1ea7n.\n\nAn: Ba ph\u1ea7n n\xe0o v\u1eady?\n\nMinsu: L\u1eadp ph\xe1p, h\xe0nh ph\xe1p v\xe0 t\u01b0 ph\xe1p.\n\nAn: Ai ph\u1ee5 tr\xe1ch l\u1eadp ph\xe1p?\n\nMinsu: C\u01a1 quan ti\xeau bi\u1ec3u l\xe0 Qu\u1ed1c h\u1ed9i. Qu\u1ed1c h\u1ed9i c\xf3 vai tr\xf2 x\xe2y d\u1ef1ng lu\u1eadt.\n\nAn: V\u1eady h\xe0nh ph\xe1p th\xec sao?\n\nMinsu: H\xe0nh ph\xe1p th\u1ef1c thi lu\u1eadt v\xe0 ch\xednh s\xe1ch. T\u1ed5ng th\u1ed1ng l\xe3nh \u0111\u1ea1o nh\xe1nh h\xe0nh ph\xe1p.\n\nAn: C\xf2n t\u01b0 ph\xe1p l\xe0 t\xf2a \xe1n \u0111\xfang kh\xf4ng?\n\nMinsu: \u0110\xfang v\u1eady. T\xf2a \xe1n \xe1p d\u1ee5ng ph\xe1p lu\u1eadt th\xf4ng qua x\xe9t x\u1eed v\xe0 gi\u1ea3i quy\u1ebft tranh ch\u1ea5p.\n\nAn: T\u1ea1i sao ph\u1ea3i chia quy\u1ec1n l\u1ef1c nh\u01b0 v\u1eady?\n\nMinsu: \u0110\u1ec3 ng\u0103n qu\xe1 nhi\u1ec1u quy\u1ec1n l\u1ef1c t\u1eadp trung v\xe0o m\u1ed9t c\u01a1 quan.\n\nAn: V\u1eady t\u1ee9c l\xe0 c\xe1c c\u01a1 quan chia s\u1ebb vai tr\xf2 v\xe0 ki\u1ec3m so\xe1t l\u1eabn nhau.\n\nMinsu: \u0110\xfang v\u1eady. \u0110\xf3 l\xe0 m\u1ed9t trong nh\u1eefng nguy\xean t\u1eafc quan tr\u1ecdng c\u1ee7a n\u1ec1n d\xe2n ch\u1ee7.\n",A.isR,A.ibP,A.hn6,A.igz)
A.h5u=s(["Hi\u1ec3u kh\xe1i ni\u1ec7m \ub300\uc911\ubb38\ud654 v\xe0 \ud55c\ub958.","Bi\u1ebft m\u1ed9t s\u1ed1 l\u0129nh v\u1ef1c v\u0103n h\xf3a \u0111\u1ea1i ch\xfang H\xe0n Qu\u1ed1c nh\u01b0 \uc74c\uc545, \ub4dc\ub77c\ub9c8, \uc601\ud654 v\xe0 \uc6f9\ud230.","H\u1ecdc t\u1eeb v\u1ef1ng th\u01b0\u1eddng g\u1eb7p khi n\xf3i v\u1ec1 n\u1ed9i dung v\u0103n h\xf3a.","Hi\u1ec3u \u1ea3nh h\u01b0\u1edfng c\u1ee7a Internet v\xe0 SNS \u0111\u1ed1i v\u1edbi vi\u1ec7c truy\u1ec1n b\xe1 v\u0103n h\xf3a H\xe0n Qu\u1ed1c.","Bi\u1ebft r\u1eb1ng v\u0103n h\xf3a \u0111\u1ea1i ch\xfang c\xf3 th\u1ec3 \u1ea3nh h\u01b0\u1edfng \u0111\u1ebfn du l\u1ecbch, ti\xeau d\xf9ng v\xe0 h\xecnh \u1ea3nh qu\u1ed1c gia.","Hi\u1ec3u t\u1ea7m quan tr\u1ecdng c\u1ee7a vi\u1ec7c t\xf4n tr\u1ecdng b\u1ea3n quy\u1ec1n.","Luy\u1ec7n \u0111\u1ecdc hi\u1ec3u v\xe0 c\xe2u h\u1ecfi ki\u1ebfn th\u1ee9c x\xe3 h\u1ed9i v\u1ec1 v\u0103n h\xf3a \u0111\u1ea1i ch\xfang."],t.s)
A.iHk=s(["\ub300\uc911\ubb38\ud654\ub294 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uc27d\uac8c \uc811\ud558\uace0 \uc990\uae30\ub294 \ubb38\ud654\uc785\ub2c8\ub2e4.","\ud55c\uad6d\uc758 \uc74c\uc545, \ub4dc\ub77c\ub9c8, \uc601\ud654, \uc608\ub2a5, \uc6f9\ud230 \ub4f1\uc740 \ub300\ud45c\uc801\uc778 \ub300\uc911\ubb38\ud654 \ucf58\ud150\uce20\uc785\ub2c8\ub2e4.","\ud55c\uad6d\uc758 \ub300\uc911\ubb38\ud654\uac00 \ud574\uc678\uc5d0\uc11c \uc778\uae30\ub97c \uc5bb\ub294 \ud604\uc0c1\uc744 \ud55c\ub958\ub77c\uace0 \ubd80\ub974\uae30\ub3c4 \ud569\ub2c8\ub2e4.","\uc778\ud130\ub137\uacfc SNS\uc758 \ubc1c\ub2ec\ub85c \ud55c\uad6d\uc758 \ubb38\ud654 \ucf58\ud150\uce20\uac00 \uc138\uacc4 \uc5ec\ub7ec \uc9c0\uc5ed\uc5d0 \ube60\ub974\uac8c \uc54c\ub824\uc9c8 \uc218 \uc788\uac8c \ub418\uc5c8\uc2b5\ub2c8\ub2e4.","\ub300\uc911\ubb38\ud654\ub294 \ud55c\uad6d\uc5b4 \ud559\uc2b5, \uad00\uad11, \uc74c\uc2dd, \ud654\uc7a5\ud488 \ub4f1 \ub2e4\ub978 \ubd84\uc57c\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ubb38\ud654 \ucf58\ud150\uce20\ub97c \uc774\uc6a9\ud560 \ub54c\uc5d0\ub294 \uc800\uc791\uad8c\uc744 \uc874\uc911\ud558\ub294 \ud0dc\ub3c4\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.","\ub300\uc911\ubb38\ud654\ub294 \uc2dc\ub300\uc640 \uae30\uc220\uc758 \ubcc0\ud654\uc5d0 \ub530\ub77c \uacc4\uc18d \uc0c8\ub85c\uc6b4 \ud615\ud0dc\ub85c \ubc1c\uc804\ud569\ub2c8\ub2e4."],t.s)
A.fmm=new B.p("\ub300\uc911\ubb38\ud654","v\u0103n h\xf3a \u0111\u1ea1i ch\xfang","\ud55c\uad6d\uc758 \ub300\uc911\ubb38\ud654\ub294 \uc5ec\ub7ec \ub098\ub77c\uc5d0\uc11c \uad00\uc2ec\uc744 \ubc1b\uace0 \uc788\uc2b5\ub2c8\ub2e4.","V\u0103n h\xf3a \u0111\u1ea1i ch\xfang H\xe0n Qu\u1ed1c \u0111ang nh\u1eadn \u0111\u01b0\u1ee3c s\u1ef1 quan t\xe2m \u1edf nhi\u1ec1u qu\u1ed1c gia.")
A.fou=new B.p("\ud55c\ub958","l\xe0n s\xf3ng H\xe0n Qu\u1ed1c / Hallyu","\ud55c\ub958\ub97c \ud1b5\ud574 \ud55c\uad6d \ubb38\ud654\uc5d0 \uad00\uc2ec\uc744 \uac16\ub294 \uc0ac\ub78c\uc774 \ub9ce\uc544\uc84c\uc2b5\ub2c8\ub2e4.","Th\xf4ng qua l\xe0n s\xf3ng H\xe0n Qu\u1ed1c, s\u1ed1 ng\u01b0\u1eddi quan t\xe2m \u0111\u1ebfn v\u0103n h\xf3a H\xe0n Qu\u1ed1c \u0111\xe3 t\u0103ng l\xean.")
A.fh_=new B.p("\ucf58\ud150\uce20","n\u1ed9i dung / content","\uc778\ud130\ub137\uc5d0\uc11c \ub2e4\uc591\ud55c \ubb38\ud654 \ucf58\ud150\uce20\ub97c \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.","C\xf3 th\u1ec3 xem nhi\u1ec1u n\u1ed9i dung v\u0103n h\xf3a kh\xe1c nhau tr\xean Internet.")
A.fmS=new B.p("\ub300\uc911\uc74c\uc545","nh\u1ea1c \u0111\u1ea1i ch\xfang","\ud55c\uad6d\uc758 \ub300\uc911\uc74c\uc545\uc744 \uc88b\uc544\ud558\ub294 \uc678\uad6d\uc778\uc774 \ub9ce\uc2b5\ub2c8\ub2e4.","C\xf3 nhi\u1ec1u ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i th\xedch nh\u1ea1c \u0111\u1ea1i ch\xfang H\xe0n Qu\u1ed1c.")
