A.feT=new B.a8("\uae40\uad6c\ub294 \ub300\ud55c\ubbfc\uad6d \uc784\uc2dc\uc815\ubd80\uc758 \uc8fc\uc694 \uc9c0\ub3c4\uc790\ub85c \ud65c\ub3d9\ud588\uc2b5\ub2c8\ub2e4.","Kim Gu ho\u1ea1t \u0111\u1ed9ng v\u1edbi t\u01b0 c\xe1ch m\u1ed9t trong nh\u1eefng nh\xe0 l\xe3nh \u0111\u1ea1o ch\xednh c\u1ee7a Ch\xednh ph\u1ee7 L\xe2m th\u1eddi.","N(\uc73c)\ub85c \ud65c\ub3d9\ud558\ub2e4 = ho\u1ea1t \u0111\u1ed9ng v\u1edbi t\u01b0 c\xe1ch N.")
A.ffm=new B.a8("\uc548\ucc3d\ud638\ub294 \uad50\uc721\uc744 \ud1b5\ud574 \ubbfc\uc871\uc758 \ud798\uc744 \ud0a4\uc6b0\ub824\uace0 \ud588\uc2b5\ub2c8\ub2e4.","Ahn Chang-ho c\u1ed1 g\u1eafng n\xe2ng cao s\u1ee9c m\u1ea1nh d\xe2n t\u1ed9c th\xf4ng qua gi\xe1o d\u1ee5c.","-\uc744/\ub97c \ud1b5\ud574 = th\xf4ng qua. -(\uc73c)\ub824\uace0 \ud558\ub2e4 = c\u1ed1 \u0111\u1ecbnh l\xe0m/\u0111\u1ecbnh l\xe0m.")
A.ffr=new B.a8("\uc724\ubd09\uae38\uc740 1932\ub144 \uc0c1\ud558\uc774\uc5d0\uc11c \uc758\uac70\ub97c \uc77c\uc73c\ucf30\uc2b5\ub2c8\ub2e4.","Yun Bong-gil th\u1ef1c hi\u1ec7n h\xe0nh \u0111\u1ed9ng \u0111\u1ea5u tranh t\u1ea1i Th\u01b0\u1ee3ng H\u1ea3i v\xe0o n\u0103m 1932.","\uc758\uac70\ub97c \uc77c\uc73c\ud0a4\ub2e4 = th\u1ef1c hi\u1ec7n h\xe0nh \u0111\u1ed9ng \u0111\u1ea5u tranh v\xec ch\xednh ngh\u0129a.")
A.ffx=new B.a8("\ub3c5\ub9bd\uc6b4\ub3d9\uc740 \ud55c \uac00\uc9c0 \ubc29\ubc95\uc774 \uc544\ub2c8\ub77c \uc5ec\ub7ec \ud615\ud0dc\ub85c \uc774\ub8e8\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.","Phong tr\xe0o \u0111\u1ed9c l\u1eadp kh\xf4ng ch\u1ec9 di\u1ec5n ra theo m\u1ed9t c\xe1ch m\xe0 c\xf3 nhi\u1ec1u h\xecnh th\u1ee9c kh\xe1c nhau.","\ud55c \uac00\uc9c0 = m\u1ed9t lo\u1ea1i; \uc5ec\ub7ec \ud615\ud0dc = nhi\u1ec1u h\xecnh th\u1ee9c.")
A.iE7=s([A.ffF,A.fdU,A.feT,A.ffm,A.ffr,A.ffx],t.B)
A.iVw=s(["\uc548\uc911\uadfc \u2192 1909\ub144, \ud558\uc5bc\ube48, \uc774\ud1a0 \ud788\ub85c\ubd80\ubbf8.","\uc720\uad00\uc21c \u2192 1919\ub144 3\xb71 \uc6b4\ub3d9\uacfc \uc544\uc6b0\ub0b4 \uc7a5\ud130 \ub9cc\uc138\uc6b4\ub3d9.","\uae40\uad6c \u2192 \ub300\ud55c\ubbfc\uad6d \uc784\uc2dc\uc815\ubd80\uc758 \uc8fc\uc694 \uc9c0\ub3c4\uc790, \ud638\ub294 \ubc31\ubc94.","\uc548\ucc3d\ud638 \u2192 \uad50\uc721, \uc778\uc7ac \uc591\uc131, \ud765\uc0ac\ub2e8.","\uc724\ubd09\uae38 \u2192 1932\ub144, \uc911\uad6d \uc0c1\ud558\uc774 \ud6d9\ucee4\uc6b0\uacf5\uc6d0 \uc758\uac70.","\uc548\uc911\uadfc\uacfc \uc724\ubd09\uae38\uc744 \ud63c\ub3d9\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc548\uc911\uadfc\uc740 \ud558\uc5bc\ube48, \uc724\ubd09\uae38\uc740 \uc0c1\ud558\uc774\uc640 \uc5f0\uacb0\ud569\ub2c8\ub2e4.","3\xb71 \uc6b4\ub3d9 \u2192 1919\ub144. \uad11\ubcf5 \u2192 1945\ub144.","\uc720\uad00\uc21c\uc740 3\xb71 \uc6b4\ub3d9\uacfc \uad00\ub828\ub41c \ub300\ud45c\uc801\uc778 \uc5ec\uc131 \ub3c5\ub9bd\uc6b4\ub3d9\uac00\uc785\ub2c8\ub2e4.","\uae40\uad6c\uc640 \uc138\uc885\ub300\uc655\uc744 \ud63c\ub3d9\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uae40\uad6c\ub294 \ub3c5\ub9bd\uc6b4\ub3d9, \uc138\uc885\uc740 \ud6c8\ubbfc\uc815\uc74c\uacfc \uc5f0\uacb0\ud569\ub2c8\ub2e4.","\ub3c5\ub9bd\uc6b4\ub3d9\uc740 \ubb34\uc7a5\ud22c\uc7c1\ubfd0 \uc544\ub2c8\ub77c \ub9cc\uc138\uc6b4\ub3d9, \uad50\uc721, \uc678\uad50 \ub4f1 \ub2e4\uc591\ud55c \ud615\ud0dc\ub85c \uc774\ub8e8\uc5b4\uc84c\uc2b5\ub2c8\ub2e4."],t.s)
A.fCw=s(["\uc548\uc911\uadfc \u2192 1909\ub144 \ud558\uc5bc\ube48.","\uc548\uc911\uadfc \u2192 \uc774\ud1a0 \ud788\ub85c\ubd80\ubbf8 \uc800\uaca9.","\uc720\uad00\uc21c \u2192 3\xb71 \uc6b4\ub3d9.","\uc720\uad00\uc21c \u2192 \uc544\uc6b0\ub0b4 \uc7a5\ud130 \ub9cc\uc138\uc6b4\ub3d9.","\uae40\uad6c \u2192 \ubc31\ubc94.","\uae40\uad6c \u2192 \ub300\ud55c\ubbfc\uad6d \uc784\uc2dc\uc815\ubd80.","\uc548\ucc3d\ud638 \u2192 \uad50\uc721\uacfc \uc778\uc7ac \uc591\uc131.","\uc548\ucc3d\ud638 \u2192 \ud765\uc0ac\ub2e8.","\uc724\ubd09\uae38 \u2192 1932\ub144.","\uc724\ubd09\uae38 \u2192 \uc0c1\ud558\uc774 \ud6d9\ucee4\uc6b0\uacf5\uc6d0 \uc758\uac70.","\ub3c5\ub9bd\uc6b4\ub3d9 \u2192 \ub9cc\uc138\uc6b4\ub3d9, \uad50\uc721, \uc678\uad50, \ubb34\uc7a5\ud22c\uc7c1 \ub4f1 \ub2e4\uc591\ud55c \ud615\ud0dc.","\uc778\ubb3c + \uc5f0\ub3c4 + \uc7a5\uc18c + \ud65c\ub3d9\uc744 \ud568\uaed8 \uc5f0\uacb0\ud574\uc11c \uae30\uc5b5\ud55c\ub2e4."],t.s)
