A.iVk=s(["\uc804\ud1b5\uc2dc\uc7a5 = ch\u1ee3 truy\u1ec1n th\u1ed1ng; \ub300\ud615\ub9c8\ud2b8 = si\xeau th\u1ecb l\u1edbn.","\ud3b8\uc758\uc810 = c\u1eeda h\xe0ng ti\u1ec7n l\u1ee3i; \ubc31\ud654\uc810 = trung t\xe2m b\xe1ch h\xf3a.","\ud560\uc778 = gi\u1ea3m gi\xe1; \ud589\uc0ac c\xf3 th\u1ec3 ch\u1ec9 ch\u01b0\u01a1ng tr\xecnh khuy\u1ebfn m\xe3i ho\u1eb7c s\u1ef1 ki\u1ec7n.","\uacb0\uc81c\ud558\ub2e4 = thanh to\xe1n; \uacc4\uc0b0\ud558\ub2e4 c\u0169ng th\u01b0\u1eddng \u0111\u01b0\u1ee3c d\xf9ng khi thanh to\xe1n t\u1ea1i c\u1eeda h\xe0ng.","\uad50\ud658 = \u0111\u1ed5i sang s\u1ea3n ph\u1ea9m kh\xe1c; \ud658\ubd88 = tr\u1ea3 h\xe0ng v\xe0 nh\u1eadn l\u1ea1i ti\u1ec1n theo \u0111i\u1ec1u ki\u1ec7n \xe1p d\u1ee5ng.","\uc601\uc218\uc99d = h\xf3a \u0111\u01a1n/bi\xean lai mua h\xe0ng.","\uc720\ud1b5\uae30\ud55c v\xe0 \uc18c\ube44\uae30\ud55c l\xe0 c\xe1c kh\xe1i ni\u1ec7m kh\xe1c nhau, n\xean c\u1ea7n \u0111\u1ecdc \u0111\xfang th\xf4ng tin \u0111\u01b0\u1ee3c ghi tr\xean s\u1ea3n ph\u1ea9m.","\uc6d0\uc0b0\uc9c0 = n\u01a1i xu\u1ea5t x\u1ee9 c\u1ee7a s\u1ea3n ph\u1ea9m.","\uac00\uaca9\uc774 \uc2f8\ub2e4\uace0 \ud574\uc11c \ud56d\uc0c1 \uc88b\uc740 \uc0c1\ud488\uc778 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4. Gi\xe1 r\u1ebb kh\xf4ng \u0111\u1ed3ng ngh\u0129a l\xfac n\xe0o c\u0169ng t\u1ed1t.","\uad6c\ub9e4 \uc804\uc5d0 \uac00\uaca9, \ud488\uc9c8, \ud544\uc694\uc131\uc744 \ud568\uaed8 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4."],t.s)
A.fVS=s(["\uc804\ud1b5\uc2dc\uc7a5 \u2192 ch\u1ee3 truy\u1ec1n th\u1ed1ng.","\ub300\ud615\ub9c8\ud2b8 \u2192 si\xeau th\u1ecb l\u1edbn.","\ud3b8\uc758\uc810 \u2192 c\u1eeda h\xe0ng ti\u1ec7n l\u1ee3i.","\uc628\ub77c\uc778 \uc1fc\ud551 \u2192 mua s\u1eafm tr\u1ef1c tuy\u1ebfn.","\ud560\uc778 \u2192 gi\u1ea3m gi\xe1.","\uacb0\uc81c \u2192 thanh to\xe1n.","\uc601\uc218\uc99d \u2192 h\xf3a \u0111\u01a1n.","\uad50\ud658 \u2192 \u0111\u1ed5i h\xe0ng.","\ud658\ubd88 \u2192 ho\xe0n ti\u1ec1n.","\uc6d0\uc0b0\uc9c0 \u2192 xu\u1ea5t x\u1ee9.","\ud488\uc9c8 \u2192 ch\u1ea5t l\u01b0\u1ee3ng.","\uc18c\ube44\uc790 \u2192 ng\u01b0\u1eddi ti\xeau d\xf9ng.","\ubb3c\uac74\uc744 \uc0b4 \ub54c \uac00\uaca9\ubfd0 \uc544\ub2c8\ub77c \ud488\uc9c8\uacfc \uc0c1\ud488 \uc815\ubcf4\ub97c \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4.","\ud569\ub9ac\uc801\uc778 \uc18c\ube44\ub97c \uc704\ud574 \ud544\uc694\ud55c \ubb3c\uac74\uc778\uc9c0 \uba3c\uc800 \uc0dd\uac01\ud558\ub294 \uac83\uc774 \uc88b\ub2e4."],t.s)
