A.fbd=new B.G("\uc2dd\ud488\uc744 \uc0b4 \ub54c \ud655\uc778\ud558\uba74 \uc88b\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Khi mua th\u1ef1c ph\u1ea9m n\xean ki\u1ec3m tra \u0111i\u1ec1u g\xec?",A.i5M,0,"Khi mua th\u1ef1c ph\u1ea9m n\xean ki\u1ec3m tra th\u1eddi h\u1ea1n v\xe0 th\xf4ng tin s\u1ea3n ph\u1ea9m.")
A.h0x=s(["\uc5ec\ub7ec \uc0c1\ud488\uc758 \uac00\uaca9\uacfc \uc815\ubcf4\ub97c \ube44\uad50\ud558\uae30 \ud3b8\ub9ac\ud558\ub2e4.","\ubc18\ub4dc\uc2dc \uc2dc\uc7a5\uc5d0 \uc9c1\uc811 \uac00\uc57c \ud55c\ub2e4.","\uc0c1\ud488 \uac00\uaca9\uc744 \uc808\ub300 \ud655\uc778\ud560 \uc218 \uc5c6\ub2e4.","\uc778\ud130\ub137\uc744 \uc0ac\uc6a9\ud560 \uc218 \uc5c6\ub2e4."],t.s)
A.f8h=new B.G("\uc628\ub77c\uc778 \uc1fc\ud551\uc758 \ud2b9\uc9d5\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110\u1eb7c \u0111i\u1ec3m ph\xf9 h\u1ee3p c\u1ee7a mua s\u1eafm tr\u1ef1c tuy\u1ebfn l\xe0 g\xec?",A.h0x,0,"Mua s\u1eafm tr\u1ef1c tuy\u1ebfn gi\xfap vi\u1ec7c so s\xe1nh gi\xe1 v\xe0 th\xf4ng tin s\u1ea3n ph\u1ea9m thu\u1eadn ti\u1ec7n.")
A.iiM=s(["\ud544\uc694\uc131\uacfc \uac00\uaca9, \ud488\uc9c8\uc744 \ud655\uc778\ud55c \ud6c4 \uc0b0\ub2e4.","\ud544\uc694\ud558\uc9c0 \uc54a\uc544\ub3c4 \ubb34\uc870\uac74 \uc0b0\ub2e4.","\uac00\uaca9\uc744 \uc804\ud600 \ud655\uc778\ud558\uc9c0 \uc54a\ub294\ub2e4.","\ubaa8\ub4e0 \uc0c1\ud488\uc744 \ucda9\ub3d9\uc801\uc73c\ub85c \uc0b0\ub2e4."],t.s)
A.f9I=new B.G("\ud569\ub9ac\uc801\uc778 \uc18c\ube44 \ubc29\ubc95\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110\xe2u l\xe0 c\xe1ch ti\xeau d\xf9ng h\u1ee3p l\xfd?",A.iiM,0,"Ti\xeau d\xf9ng h\u1ee3p l\xfd c\u1ea7n c\xe2n nh\u1eafc nhu c\u1ea7u, gi\xe1 v\xe0 ch\u1ea5t l\u01b0\u1ee3ng.")
A.i2d=s(["\ud55c\uad6d\uc5d0\uc11c\ub294 \uc5ec\ub7ec \ud615\ud0dc\uc758 \uc2dc\uc7a5\uacfc \uc1fc\ud551 \ubc29\ubc95\uc744 \uc774\uc6a9\ud560 \uc218 \uc788\ub2e4.","\uc628\ub77c\uc778\uc73c\ub85c\ub294 \uc0c1\ud488\uc744 \uc0b4 \uc218 \uc5c6\ub2e4.","\uad50\ud658\ud560 \ub54c \uad6c\ub9e4 \uae30\ub85d\uc740 \uc804\ud600 \ud544\uc694\ud558\uc9c0 \uc54a\ub2e4.","\uc0c1\ud488\uc744 \uc0b4 \ub54c \uac00\uaca9\ub9cc \ud655\uc778\ud558\uba74 \ub41c\ub2e4."],t.s)
A.fb0=new B.G("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung \u0111\xfang v\u1edbi b\xe0i \u0111\u1ecdc.",A.i2d,0,"\u1ede H\xe0n Qu\u1ed1c c\xf3 nhi\u1ec1u h\xecnh th\u1ee9c mua s\u1eafm nh\u01b0 ch\u1ee3 truy\u1ec1n th\u1ed1ng, si\xeau th\u1ecb v\xe0 mua s\u1eafm tr\u1ef1c tuy\u1ebfn.")
