A.iL5=s(["\uad50\ud1b5 \ud63c\uc7a1\uacfc \ub192\uc740 \uc8fc\uac70\ube44","\uc0ac\ub78c\uc774 \uc804\ud600 \uc5c6\ub294 \ubb38\uc81c","\uad50\ud1b5\uc2dc\uc124\uc774 \ud544\uc694 \uc5c6\ub294 \ubb38\uc81c","\ub18d\ucd0c \uc778\uad6c\uac00 \uc218\ub3c4\uad8c\ubcf4\ub2e4 \ud56d\uc0c1 \ub9ce\uc740 \ubb38\uc81c"],t.s)
A.fbL=new B.G("\uc218\ub3c4\uad8c\uc5d0 \uc778\uad6c\uac00 \ub9ce\uc774 \uc9d1\uc911\ub418\uc5b4 \ub098\ud0c0\ub0a0 \uc218 \uc788\ub294 \ubb38\uc81c\ub294?","V\u1ea5n \u0111\u1ec1 n\xe0o c\xf3 th\u1ec3 xu\u1ea5t hi\u1ec7n do d\xe2n s\u1ed1 t\u1eadp trung nhi\u1ec1u \u1edf v\xf9ng th\u1ee7 \u0111\xf4?",A.iL5,0,"D\xe2n s\u1ed1 t\u1eadp trung c\xf3 th\u1ec3 g\xe2y \xf9n t\u1eafc v\xe0 t\u0103ng g\xe1nh n\u1eb7ng nh\xe0 \u1edf.")
A.hvx=s(["\uade0\ud615 \ubc1c\uc804","\uc218\ub3c4\uad8c\uc5d0 \ubaa8\ub4e0 \uae30\ub2a5\uc744 \ub354 \uc9d1\uc911\ud55c\ub2e4.","\uc9c0\ubc29\uc758 \uad50\ud1b5\uc2dc\uc124\uc744 \uc5c6\uc564\ub2e4.","\uc9c0\uc5ed \uad50\ub958\ub97c \uc904\uc778\ub2e4."],t.s)
A.f7J=new B.G("\uc9c0\uc5ed \uac04 \uaca9\ucc28\ub97c \uc904\uc774\uae30 \uc704\ud574 \ud544\uc694\ud55c \uac83\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740?","\u0110i\u1ec1u g\xec c\u1ea7n thi\u1ebft \u0111\u1ec3 gi\u1ea3m ch\xeanh l\u1ec7ch gi\u1eefa c\xe1c khu v\u1ef1c?",A.hvx,0,"\uade0\ud615 \ubc1c\uc804\uc740 \uc5ec\ub7ec \uc9c0\uc5ed\uc774 \ud568\uaed8 \ubc1c\uc804\ud558\ub3c4\ub85d \ud558\ub294 \uac83\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4.")
A.hqp=s(["\uc218\ub3c4\uad8c\uc5d0\ub294 \ub9ce\uc740 \uc77c\uc790\ub9ac\uc640 \uad50\uc721\xb7\ubb38\ud654\uc2dc\uc124\uc774 \ubaa8\uc5ec \uc788\ub2e4.","\uc218\ub3c4\uad8c\uc740 \uc11c\uc6b8 \ud55c \uacf3\ub9cc \uc758\ubbf8\ud55c\ub2e4.","\uc778\ucc9c\uc740 \ubc14\ub2e4\uc640 \uc811\ud558\uc9c0 \uc54a\ub294\ub2e4.","\uacbd\uae30\ub3c4\uc640 \uc11c\uc6b8 \uc0ac\uc774\uc5d0\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc774\ub3d9\uc774 \uac70\uc758 \uc5c6\ub2e4."],t.s)
A.f8L=new B.G("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung ph\xf9 h\u1ee3p v\u1edbi b\xe0i \u0111\u1ecdc.",A.hqp,0,"V\xf9ng th\u1ee7 \u0111\xf4 t\u1eadp trung nhi\u1ec1u vi\u1ec7c l\xe0m v\xe0 c\u01a1 s\u1edf gi\xe1o d\u1ee5c, v\u0103n h\xf3a.")
A.ige=s([A.f5J,A.f7v,A.f4b,A.fa_,A.f4d,A.f83,A.fbG,A.fbL,A.f7J,A.f8L],t.h)
A.hDD=s(["\uc218\ub3c4\uad8c = \uc11c\uc6b8\ud2b9\ubcc4\uc2dc + \uc778\ucc9c\uad11\uc5ed\uc2dc + \uacbd\uae30\ub3c4.","\uc11c\uc6b8 = th\u1ee7 \u0111\xf4 c\u1ee7a H\xe0n Qu\u1ed1c.","\uc11c\uc6b8 = trung t\xe2m quan tr\u1ecdng v\u1ec1 ch\xednh tr\u1ecb, kinh t\u1ebf v\xe0 v\u0103n h\xf3a.","\ud55c\uac15 = con s\xf4ng ti\xeau bi\u1ec3u ch\u1ea3y qua Seoul.","\uc778\ucc9c = th\xe0nh ph\u1ed1 ti\u1ebfp gi\xe1p bi\u1ec3n T\xe2y.","\uc778\ucc9c = c\u1ea3ng bi\u1ec3n + s\xe2n bay qu\u1ed1c t\u1ebf.","\uc778\ucc9c\uad6d\uc81c\uacf5\ud56d = c\u1eeda ng\xf5 giao th\xf4ng qu\u1ed1c t\u1ebf quan tr\u1ecdng.","\uacbd\uae30\ub3c4 = khu v\u1ef1c r\u1ed9ng l\u1edbn xung quanh Seoul v\xe0 Incheon.","\uc218\ub3c4\uad8c = m\u1ea1ng l\u01b0\u1edbi t\xe0u \u0111i\u1ec7n ng\u1ea7m, xe bu\xfdt v\xe0 \u0111\u01b0\u1eddng s\u1eaft ph\xe1t tri\u1ec3n.","\ucd9c\ud1f4\uadfc = \u0111i l\xe0m v\xe0 tan l\xe0m.","\uc218\ub3c4\uad8c \uc9d1\uc911 = t\u1eadp trung d\xe2n s\u1ed1 v\xe0 nhi\u1ec1u ch\u1ee9c n\u0103ng kinh t\u1ebf.","\uad50\ud1b5 \ud63c\uc7a1 \xb7 \uc8fc\uac70\ube44 = nh\u1eefng v\u1ea5n \u0111\u1ec1 c\xf3 th\u1ec3 xu\u1ea5t hi\u1ec7n \u1edf v\xf9ng th\u1ee7 \u0111\xf4.","\uade0\ud615 \ubc1c\uc804 = ph\xe1t tri\u1ec3n c\xe2n b\u1eb1ng gi\u1eefa v\xf9ng th\u1ee7 \u0111\xf4 v\xe0 c\xe1c \u0111\u1ecba ph\u01b0\u01a1ng."],t.s)
A.f43=new B.dk(45,"\uc9c0\ub9ac","\uc218\ub3c4\uad8c","V\xf9ng th\u1ee7 \u0111\xf4 H\xe0n Qu\u1ed1c",A.hJ3,A.hIV,A.hGe,A.iMX,"\ub300\ud55c\ubbfc\uad6d\uc758 \uc218\ub3c4\uad8c","\uc218\ub3c4\uad8c\uc740 \uc11c\uc6b8\ud2b9\ubcc4\uc2dc, \uc778\ucc9c\uad11\uc5ed\uc2dc, \uacbd\uae30\ub3c4\ub97c \ud3ec\ud568\ud558\ub294 \uc9c0\uc5ed\uc785\ub2c8\ub2e4.\n\n\uc11c\uc6b8\uc740 \ub300\ud55c\ubbfc\uad6d\uc758 \uc218\ub3c4\uc785\ub2c8\ub2e4. \uad6d\ud68c\uc640 \uc5ec\ub7ec \uad6d\uac00\uae30\uad00\uc774 \uc788\uc73c\uba70 \uae30\uc5c5, \ub300\ud559, \ubcd1\uc6d0, \ubb38\ud654\uc2dc\uc124 \ub4f1 \ub2e4\uc591\ud55c \uae30\ub2a5\uc774 \ubaa8\uc5ec \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc11c\uc6b8\uc758 \uc911\uc2ec\uc5d0\ub294 \ud55c\uac15\uc774 \ud750\ub985\ub2c8\ub2e4. \ud55c\uac15 \uc8fc\ubcc0\uc5d0\ub294 \uacf5\uc6d0\uacfc \ub3c4\ub85c, \uc8fc\uac70\uc9c0\uc5ed \ub4f1\uc774 \ubc1c\ub2ec\ud574 \uc788\uc73c\uba70 \uc11c\uc6b8 \uc0ac\ub78c\ub4e4\uc758 \uc0dd\ud65c\uacfc \ubc00\uc811\ud55c \uad00\uacc4\uac00 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc778\ucc9c\uc740 \uc11c\uc6b8\uc758 \uc11c\ucabd\uc5d0 \uc704\uce58\ud558\uba70 \uc11c\ud574\uc640 \uc811\ud574 \uc788\uc2b5\ub2c8\ub2e4. \uc778\ucc9c\uc5d0\ub294 \ud56d\uad6c\uac00 \ubc1c\ub2ec\ud574 \uc788\uc5b4 \uc624\ub7ab\ub3d9\uc548 \uad6d\uc81c\uad50\ub958\uc758 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud574 \uc654\uc2b5\ub2c8\ub2e4.\n\n\ub610\ud55c \uc778\ucc9c\uad6d\uc81c\uacf5\ud56d\uc774 \uc788\uc5b4 \ud55c\uad6d\uacfc \uc138\uacc4 \uc5ec\ub7ec \uc9c0\uc5ed\uc744 \uc5f0\uacb0\ud558\ub294 \uc911\uc694\ud55c \uad00\ubb38 \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4.\n\n\uacbd\uae30\ub3c4\ub294 \uc11c\uc6b8\uacfc \uc778\ucc9c \uc8fc\ubcc0\uc758 \ub113\uc740 \uc9c0\uc5ed\uc744 \ucc28\uc9c0\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc218\uc6d0, \uc131\ub0a8, \uace0\uc591, \uc6a9\uc778 \ub4f1 \ub9ce\uc740 \ub3c4\uc2dc\uac00 \uc788\uc73c\uba70 \uc0b0\uc5c5\uc2dc\uc124\uacfc \uc8fc\uac70\uc9c0\uc5ed\ub3c4 \ub9ce\uc774 \ubc1c\ub2ec\ud588\uc2b5\ub2c8\ub2e4.\n\n\uc11c\uc6b8\uc5d0\uc11c \uc77c\ud558\uc9c0\ub9cc \uacbd\uae30\ub3c4\ub098 \uc778\ucc9c\uc5d0 \uc0ac\ub294 \uc0ac\ub78c\ub3c4 \ub9ce\uae30 \ub54c\ubb38\uc5d0 \uc218\ub3c4\uad8c\uc5d0\uc11c\ub294 \ub9e4\uc77c \ub9ce\uc740 \uc0ac\ub78c\uc774 \uc9c0\uc5ed\uc744 \uc624\uac00\uba70 \ucd9c\ud1f4\uadfc\ud569\ub2c8\ub2e4.\n\n\uc774\ub97c \uc9c0\uc6d0\ud558\uae30 \uc704\ud574 \uc218\ub3c4\uad8c\uc5d0\ub294 \uc9c0\ud558\ucca0, \ubc84\uc2a4, \ucca0\ub3c4, \uace0\uc18d\ub3c4\ub85c \ub4f1 \ub2e4\uc591\ud55c \uad50\ud1b5\ub9dd\uc774 \ubc1c\ub2ec\ud574 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc218\ub3c4\uad8c\uc5d0\ub294 \uc77c\uc790\ub9ac\uc640 \uad50\uc721\uc2dc\uc124, \ubb38\ud654\uc2dc\uc124 \ub4f1\uc774 \ub9ce\uc774 \ubaa8\uc5ec \uc788\ub2e4\ub294 \uc7a5\uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \ub9ce\uc740 \uc778\uad6c\uc640 \uae30\ub2a5\uc774 \uc9d1\uc911\ub418\uba74\uc11c \uad50\ud1b5 \ud63c\uc7a1, \ub192\uc740 \uc8fc\uac70\ube44, \ud658\uacbd \ubb38\uc81c \ub4f1\ub3c4 \ubc1c\uc0dd\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ud55c\ud3b8 \uc218\ub3c4\uad8c\uc5d0 \uc778\uad6c\uc640 \uacbd\uc81c \uae30\ub2a5\uc774 \uc9c0\ub098\uce58\uac8c \uc9d1\uc911\ub418\uba74 \uc9c0\ubc29\uc758 \uc778\uad6c \uac10\uc18c\uc640 \uc9c0\uc5ed \uac04 \uaca9\ucc28 \ubb38\uc81c\uac00 \ucee4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ub530\ub77c\uc11c \uc218\ub3c4\uad8c\uacfc \uc9c0\ubc29\uc774 \uac01\uc790\uc758 \uc7a5\uc810\uc744 \uc0b4\ub9ac\uba74\uc11c \ud568\uaed8 \ubc1c\uc804\ud560 \uc218 \uc788\ub3c4\ub85d \uade0\ud615 \ubc1c\uc804\uc744 \uc774\ub8e8\ub294 \uac83\ub3c4 \uc911\uc694\ud55c \uacfc\uc81c\uc785\ub2c8\ub2e4.\n","V\xf9ng th\u1ee7 \u0111\xf4 H\xe0n Qu\u1ed1c bao g\u1ed3m Seoul, Incheon v\xe0 t\u1ec9nh Gyeonggi.\n\nSeoul l\xe0 th\u1ee7 \u0111\xf4 c\u1ee7a H\xe0n Qu\u1ed1c. T\u1ea1i \u0111\xe2y c\xf3 Qu\u1ed1c h\u1ed9i, nhi\u1ec1u c\u01a1 quan nh\xe0 n\u01b0\u1edbc, doanh nghi\u1ec7p, tr\u01b0\u1eddng \u0111\u1ea1i h\u1ecdc, b\u1ec7nh vi\u1ec7n, c\u01a1 s\u1edf v\u0103n h\xf3a v\xe0 nhi\u1ec1u ch\u1ee9c n\u0103ng kh\xe1c t\u1eadp trung.\n\nS\xf4ng H\xe0n ch\u1ea3y qua trung t\xe2m Seoul. Xung quanh s\xf4ng c\xf3 nhi\u1ec1u c\xf4ng vi\xean, \u0111\u01b0\u1eddng s\xe1 v\xe0 khu d\xe2n c\u01b0, v\xec v\u1eady con s\xf4ng c\xf3 quan h\u1ec7 m\u1eadt thi\u1ebft v\u1edbi \u0111\u1eddi s\u1ed1ng c\u1ee7a ng\u01b0\u1eddi d\xe2n Seoul.\n\nIncheon n\u1eb1m ph\xeda t\xe2y Seoul v\xe0 ti\u1ebfp gi\xe1p bi\u1ec3n T\xe2y. Th\xe0nh ph\u1ed1 c\xf3 c\u1ea3ng bi\u1ec3n ph\xe1t tri\u1ec3n v\xe0 t\u1eeb l\xe2u gi\u1eef vai tr\xf2 quan tr\u1ecdng trong giao l\u01b0u qu\u1ed1c t\u1ebf.\n\nIncheon c\u0169ng c\xf3 s\xe2n bay qu\u1ed1c t\u1ebf, \u0111\xf3ng vai tr\xf2 nh\u01b0 m\u1ed9t c\u1eeda ng\xf5 quan tr\u1ecdng k\u1ebft n\u1ed1i H\xe0n Qu\u1ed1c v\u1edbi nhi\u1ec1u khu v\u1ef1c tr\xean th\u1ebf gi\u1edbi.\n\nGyeonggi-do l\xe0 m\u1ed9t khu v\u1ef1c r\u1ed9ng l\u1edbn n\u1eb1m xung quanh Seoul v\xe0 Incheon. T\u1ec9nh c\xf3 nhi\u1ec1u th\xe0nh ph\u1ed1 nh\u01b0 Suwon, Seongnam, Goyang v\xe0 Yongin, \u0111\u1ed3ng th\u1eddi c\xf3 nhi\u1ec1u khu c\xf4ng nghi\u1ec7p v\xe0 khu d\xe2n c\u01b0.\n\nC\xf3 nhi\u1ec1u ng\u01b0\u1eddi l\xe0m vi\u1ec7c t\u1ea1i Seoul nh\u01b0ng sinh s\u1ed1ng \u1edf Gyeonggi-do ho\u1eb7c Incheon, v\xec v\u1eady m\u1ed7i ng\xe0y c\xf3 r\u1ea5t nhi\u1ec1u ng\u01b0\u1eddi di chuy\u1ec3n gi\u1eefa c\xe1c khu v\u1ef1c \u0111\u1ec3 \u0111i l\xe0m.\n\n\u0110\u1ec3 h\u1ed7 tr\u1ee3 vi\u1ec7c n\xe0y, v\xf9ng th\u1ee7 \u0111\xf4 c\xf3 m\u1ea1ng l\u01b0\u1edbi giao th\xf4ng ph\xe1t tri\u1ec3n g\u1ed3m t\xe0u \u0111i\u1ec7n ng\u1ea7m, xe bu\xfdt, \u0111\u01b0\u1eddng s\u1eaft v\xe0 \u0111\u01b0\u1eddng cao t\u1ed1c.\n\nV\xf9ng th\u1ee7 \u0111\xf4 c\xf3 \u01b0u \u0111i\u1ec3m l\xe0 t\u1eadp trung nhi\u1ec1u vi\u1ec7c l\xe0m, c\u01a1 s\u1edf gi\xe1o d\u1ee5c v\xe0 v\u0103n h\xf3a. Tuy nhi\xean vi\u1ec7c d\xe2n s\u1ed1 v\xe0 nhi\u1ec1u ch\u1ee9c n\u0103ng t\u1eadp trung qu\xe1 l\u1edbn c\u0169ng c\xf3 th\u1ec3 g\xe2y \xf9n t\u1eafc giao th\xf4ng, chi ph\xed nh\xe0 \u1edf cao v\xe0 c\xe1c v\u1ea5n \u0111\u1ec1 m\xf4i tr\u01b0\u1eddng.\n\nNgo\xe0i ra, n\u1ebfu d\xe2n s\u1ed1 v\xe0 ho\u1ea1t \u0111\u1ed9ng kinh t\u1ebf t\u1eadp trung qu\xe1 m\u1ee9c v\xe0o v\xf9ng th\u1ee7 \u0111\xf4 th\xec c\xe1c \u0111\u1ecba ph\u01b0\u01a1ng kh\xe1c c\xf3 th\u1ec3 g\u1eb7p v\u1ea5n \u0111\u1ec1 gi\u1ea3m d\xe2n s\u1ed1 v\xe0 ch\xeanh l\u1ec7ch khu v\u1ef1c.\n\nV\xec v\u1eady, ph\xe1t tri\u1ec3n c\xe2n b\u1eb1ng \u0111\u1ec3 v\xf9ng th\u1ee7 \u0111\xf4 v\xe0 c\xe1c \u0111\u1ecba ph\u01b0\u01a1ng c\xf9ng ph\xe1t huy th\u1ebf m\u1ea1nh c\u1ee7a m\xecnh c\u0169ng l\xe0 m\u1ed9t nhi\u1ec7m v\u1ee5 quan tr\u1ecdng.\n","\uc218\ub3c4\uad8c\uc5d0\uc11c \uc0dd\ud65c\ud558\uae30","\uc548: \ubbfc\uc218 \uc528, \uc218\ub3c4\uad8c\uc774\ub77c\uace0 \ud558\uba74 \uc11c\uc6b8\ub9cc \ub9d0\ud558\ub294 \uac70\uc608\uc694?\n\n\ubbfc\uc218: \uc544\ub2c8\uc694. \uc11c\uc6b8\ud2b9\ubcc4\uc2dc\uc640 \uc778\ucc9c\uad11\uc5ed\uc2dc, \uacbd\uae30\ub3c4\ub97c \ubaa8\ub450 \ud3ec\ud568\ud574\uc694.\n\n\uc548: \uacbd\uae30\ub3c4\uc5d0 \uc0b4\uba74\uc11c \uc11c\uc6b8\ub85c \ucd9c\uadfc\ud558\ub294 \uc0ac\ub78c\ub3c4 \ub9ce\uc9c0\uc694?\n\n\ubbfc\uc218: \ub124. \uadf8\ub798\uc11c \uc544\uce68\uacfc \uc800\ub141 \ucd9c\ud1f4\uadfc \uc2dc\uac04\uc5d0\ub294 \uc0ac\ub78c\uc774 \uc815\ub9d0 \ub9ce\uc544\uc694.\n\n\uc548: \uc9c0\ud558\ucca0 \ub178\uc120\ub3c4 \uc11c\ub85c \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5b4\uc11c \ud3b8\ub9ac\ud55c \uac83 \uac19\uc544\uc694.\n\n\ubbfc\uc218: \ub9de\uc544\uc694. \uc218\ub3c4\uad8c\uc740 \uc9c0\ud558\ucca0\uacfc \ubc84\uc2a4 \uac19\uc740 \ub300\uc911\uad50\ud1b5\uc774 \uc798 \ubc1c\ub2ec\ud574 \uc788\uc5b4\uc694.\n\n\uc548: \uc778\ucc9c\uc740 \uc5b4\ub5a4 \ud2b9\uc9d5\uc774 \uc788\uc5b4\uc694?\n\n\ubbfc\uc218: \ud56d\uad6c\ub3c4 \uc788\uace0 \uc778\ucc9c\uad6d\uc81c\uacf5\ud56d\ub3c4 \uc788\uc5b4\uc11c \uad6d\uc81c\uad50\ub958\uc640 \uad50\ud1b5\uc5d0\uc11c \uc911\uc694\ud55c \ub3c4\uc2dc\uc608\uc694.\n\n\uc548: \uc11c\uc6b8\uc5d0\ub294 \ud55c\uac15\uc774 \uc788\uc9c0\uc694?\n\n\ubbfc\uc218: \ub124. \ud55c\uac15\uc740 \uc11c\uc6b8\uc744 \uac00\ub85c\uc9c8\ub7ec \ud750\ub974\ub294 \ub300\ud45c\uc801\uc778 \uac15\uc774\uc5d0\uc694.\n\n\uc548: \uc218\ub3c4\uad8c\uc5d0 \uc0ac\ub78c\uc774 \ub9ce\uc774 \uc0ac\ub294 \uc774\uc720\ub294 \ubb34\uc5c7\uc77c\uae4c\uc694?\n\n\ubbfc\uc218: \uc77c\uc790\ub9ac, \uad50\uc721, \ubb38\ud654\uc2dc\uc124 \ub4f1\uc774 \ub9ce\uc774 \ubaa8\uc5ec \uc788\ub294 \uac83\ub3c4 \uc911\uc694\ud55c \uc774\uc720\uc608\uc694.\n\n\uc548: \uc88b\uc740 \uc810\ub9cc \uc788\ub294 \uac74 \uc544\ub2c8\uaca0\ub124\uc694.\n\n\ubbfc\uc218: \uadf8\ub807\uc8e0. \uad50\ud1b5 \ud63c\uc7a1\uc774\ub098 \uc8fc\uac70\ube44 \uac19\uc740 \ubb38\uc81c\ub3c4 \uc788\uc5b4\uc694.\n\n\uc548: \uadf8\ub798\uc11c \uc9c0\ubc29\uacfc \uade0\ud615 \uc788\uac8c \ubc1c\uc804\ud574\uc57c \ud55c\ub2e4\uace0 \ud558\ub294\uad70\uc694.\n\n\ubbfc\uc218: \ub9de\uc544\uc694. \uc9c0\uc5ed \uac04\uc758 \uaca9\ucc28\ub97c \uc904\uc774\ub294 \uac83\ub3c4 \uc911\uc694\ud55c \ubb38\uc81c\uc608\uc694.\n","An: Minsu, khi n\xf3i v\xf9ng th\u1ee7 \u0111\xf4 c\xf3 ph\u1ea3i ch\u1ec9 n\xf3i Seoul kh\xf4ng?\n\nMinsu: Kh\xf4ng. N\xf3 bao g\u1ed3m Seoul, Incheon v\xe0 Gyeonggi-do.\n\nAn: C\xf3 nhi\u1ec1u ng\u01b0\u1eddi s\u1ed1ng \u1edf Gyeonggi-do nh\u01b0ng \u0111i l\xe0m t\u1ea1i Seoul \u0111\xfang kh\xf4ng?\n\nMinsu: V\xe2ng. V\xec v\u1eady v\xe0o gi\u1edd \u0111i l\xe0m v\xe0 tan l\xe0m bu\u1ed5i s\xe1ng v\xe0 bu\u1ed5i t\u1ed1i c\xf3 r\u1ea5t nhi\u1ec1u ng\u01b0\u1eddi di chuy\u1ec3n.\n\nAn: T\xf4i th\u1ea5y c\xe1c tuy\u1ebfn t\xe0u \u0111i\u1ec7n ng\u1ea7m \u0111\u01b0\u1ee3c k\u1ebft n\u1ed1i v\u1edbi nhau n\xean kh\xe1 thu\u1eadn ti\u1ec7n.\n\nMinsu: \u0110\xfang. V\xf9ng th\u1ee7 \u0111\xf4 c\xf3 giao th\xf4ng c\xf4ng c\u1ed9ng nh\u01b0 t\xe0u \u0111i\u1ec7n ng\u1ea7m v\xe0 xe bu\xfdt r\u1ea5t ph\xe1t tri\u1ec3n.\n\nAn: Incheon c\xf3 \u0111\u1eb7c \u0111i\u1ec3m g\xec?\n\nMinsu: C\xf3 c\u1ea3 c\u1ea3ng bi\u1ec3n v\xe0 s\xe2n bay qu\u1ed1c t\u1ebf Incheon n\xean \u0111\xe2y l\xe0 th\xe0nh ph\u1ed1 quan tr\u1ecdng v\u1ec1 giao th\xf4ng v\xe0 giao l\u01b0u qu\u1ed1c t\u1ebf.\n\nAn: Seoul c\xf3 s\xf4ng H\xe0n \u0111\xfang kh\xf4ng?\n\nMinsu: V\xe2ng. S\xf4ng H\xe0n l\xe0 con s\xf4ng ti\xeau bi\u1ec3u ch\u1ea3y ngang qua Seoul.\n\nAn: T\u1ea1i sao c\xf3 nhi\u1ec1u ng\u01b0\u1eddi sinh s\u1ed1ng t\u1ea1i v\xf9ng th\u1ee7 \u0111\xf4?\n\nMinsu: M\u1ed9t l\xfd do quan tr\u1ecdng l\xe0 n\u01a1i \u0111\xe2y t\u1eadp trung nhi\u1ec1u vi\u1ec7c l\xe0m, c\u01a1 s\u1edf gi\xe1o d\u1ee5c v\xe0 v\u0103n h\xf3a.\n\nAn: Ch\u1eafc c\u0169ng kh\xf4ng ch\u1ec9 c\xf3 \u01b0u \u0111i\u1ec3m.\n\nMinsu: \u0110\xfang. C\u0169ng c\xf3 c\xe1c v\u1ea5n \u0111\u1ec1 nh\u01b0 \xf9n t\u1eafc giao th\xf4ng v\xe0 chi ph\xed nh\xe0 \u1edf.\n\nAn: V\xec v\u1eady m\u1edbi n\xf3i c\u1ea7n ph\xe1t tri\u1ec3n c\xe2n b\u1eb1ng v\u1edbi c\xe1c \u0111\u1ecba ph\u01b0\u01a1ng nh\u1ec9.\n\nMinsu: \u0110\xfang. Gi\u1ea3m ch\xeanh l\u1ec7ch gi\u1eefa c\xe1c khu v\u1ef1c c\u0169ng l\xe0 m\u1ed9t v\u1ea5n \u0111\u1ec1 quan tr\u1ecdng.\n",A.hH1,A.h4v,A.ige,A.hDD)
A.hI5=s(["Hi\u1ec3u m\u1ed9t s\u1ed1 gi\xe1 tr\u1ecb truy\u1ec1n th\u1ed1ng trong x\xe3 h\u1ed9i H\xe0n Qu\u1ed1c.","Hi\u1ec3u c\xe1c kh\xe1i ni\u1ec7m \uc608\uc808, \ud6a8, \uc815 v\xe0 \uacf5\ub3d9\uccb4 \uc758\uc2dd.","Hi\u1ec3u \xfd ngh\u0129a c\u1ee7a \uc5f0\uace0 v\xe0 c\xe1c t\u1eeb \ud608\uc5f0, \uc9c0\uc5f0, \ud559\uc5f0.","Bi\u1ebft m\u1eb7t t\xedch c\u1ef1c v\xe0 h\u1ea1n ch\u1ebf c\u1ee7a c\xe1c m\u1ed1i quan h\u1ec7 th\xe2n quen.","Hi\u1ec3u s\u1ef1 thay \u0111\u1ed5i t\u1eeb x\xe3 h\u1ed9i coi tr\u1ecdng quan h\u1ec7 sang x\xe3 h\u1ed9i coi tr\u1ecdng c\xf4ng b\u1eb1ng v\xe0 n\u0103ng l\u1ef1c.","Bi\u1ebft c\xe1ch \u1ee9ng x\u1eed ph\xf9 h\u1ee3p trong quan h\u1ec7 gi\u1eefa ng\u01b0\u1eddi v\u1edbi ng\u01b0\u1eddi.","Luy\u1ec7n \u0111\u1ecdc hi\u1ec3u v\xe0 c\xe2u h\u1ecfi ki\u1ebfn th\u1ee9c x\xe3 h\u1ed9i li\xean quan \u0111\u1ebfn v\u0103n h\xf3a v\xe0 gi\xe1 tr\u1ecb x\xe3 h\u1ed9i."],t.s)
A.iJc=s(["\ud55c\uad6d\uc758 \uc804\ud1b5\uc801\uc778 \uac00\uce58\uc5d0\ub294 \uac00\uc871\uc744 \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud558\ub294 \ud0dc\ub3c4\uc640 \uc5b4\ub978\uc744 \uc874\uc911\ud558\ub294 \uc608\uc808 \ub4f1\uc774 \uc788\uc2b5\ub2c8\ub2e4.","\ud6a8\ub294 \ubd80\ubaa8\ub97c \uc874\uc911\ud558\uace0 \ubcf4\uc0b4\ud53c\ub294 \ud0dc\ub3c4\uc640 \uad00\ub828\uc774 \uc788\uc2b5\ub2c8\ub2e4.","\uc815\uc740 \uc624\ub79c \uad00\uacc4 \uc18d\uc5d0\uc11c \uc0dd\uae30\ub294 \uce5c\ubc00\uac10\uacfc \ub530\ub73b\ud55c \ub9c8\uc74c\uc744 \ud45c\ud604\ud560 \ub54c \uc790\uc8fc \uc0ac\uc6a9\ud558\ub294 \ub9d0\uc785\ub2c8\ub2e4.","\uacf5\ub3d9\uccb4 \uc758\uc2dd\uc740 \uc790\uc2e0\ubfd0\ub9cc \uc544\ub2c8\ub77c \ud568\uaed8 \uc0dd\ud65c\ud558\ub294 \uc0ac\ub78c\ub4e4\uc744 \uc0dd\uac01\ud558\ub294 \ud0dc\ub3c4\uc640 \uad00\ub828\uc774 \uc788\uc2b5\ub2c8\ub2e4.","\uc5f0\uace0\ub294 \uac00\uc871, \uace0\ud5a5, \ud559\uad50 \ub4f1\uc73c\ub85c \ub9fa\uc5b4\uc9c4 \uad00\uacc4\ub97c \uc758\ubbf8\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ud608\uc5f0\uc740 \uac00\uc871\uc774\ub098 \uce5c\uc871 \uad00\uacc4, \uc9c0\uc5f0\uc740 \uac19\uc740 \uc9c0\uc5ed\uacfc \uad00\ub828\ub41c \uad00\uacc4, \ud559\uc5f0\uc740 \uac19\uc740 \ud559\uad50\uc640 \uad00\ub828\ub41c \uad00\uacc4\uc785\ub2c8\ub2e4.","\uc5f0\uace0\ub97c \ud1b5\ud574 \uc11c\ub85c \ub3d5\ub294 \uac83\uc740 \uae0d\uc815\uc801\uc778 \uc5ed\ud560\uc744 \ud560 \uc218 \uc788\uc9c0\ub9cc \uc9c0\ub098\uce58\uac8c \uc5f0\uace0\ub9cc\uc744 \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud558\uba74 \uacf5\uc815\uc131\uc744 \ud574\uce60 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ud604\ub300 \uc0ac\ud68c\uc5d0\uc11c\ub294 \uac1c\uc778\uc758 \ub2a5\ub825\uacfc \uacf5\uc815\ud55c \uc808\ucc28\ub97c \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud558\ub294 \ud0dc\ub3c4\ub3c4 \ub9e4\uc6b0 \uc911\uc694\ud569\ub2c8\ub2e4."],t.s)
