A.fct=new B.a8("\ud55c\uad6d\uc5d0\uc11c\ub294 \uc804\ud1b5\uc801\uc73c\ub85c \uac00\uc871\uacfc \uacf5\ub3d9\uccb4\ub97c \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud574 \uc654\uc2b5\ub2c8\ub2e4.","Trong truy\u1ec1n th\u1ed1ng H\xe0n Qu\u1ed1c, gia \u0111\xecnh v\xe0 c\u1ed9ng \u0111\u1ed3ng \u0111\xe3 \u0111\u01b0\u1ee3c coi tr\u1ecdng.","-\uc544/\uc5b4 \uc624\ub2e4 = m\u1ed9t h\xe0nh \u0111\u1ed9ng ho\u1eb7c tr\u1ea1ng th\xe1i \u0111\xe3 ti\u1ebfp di\u1ec5n \u0111\u1ebfn hi\u1ec7n t\u1ea1i.")
A.fce=new B.a8("\ud6a8\ub294 \ubd80\ubaa8\ub97c \uc874\uc911\ud558\uace0 \ubcf4\uc0b4\ud53c\ub294 \ud0dc\ub3c4\uc640 \uad00\ub828\uc774 \uc788\uc2b5\ub2c8\ub2e4.",u.E,"-\uc640/\uacfc \uad00\ub828\uc774 \uc788\ub2e4 = c\xf3 li\xean quan \u0111\u1ebfn.")
A.fdi=new B.a8("\uc624\ub7ab\ub3d9\uc548 \ud568\uaed8 \uc9c0\ub0b4\ub2e4 \ubcf4\uba74 \uc11c\ub85c \uc815\uc774 \ub4e4\uae30\ub3c4 \ud569\ub2c8\ub2e4.","Khi \u1edf c\xf9ng nhau l\xe2u ng\xe0y, \u0111\xf4i khi m\u1ecdi ng\u01b0\u1eddi s\u1ebd n\u1ea3y sinh t\xecnh c\u1ea3m g\u1eafn b\xf3.","-\ub2e4 \ubcf4\uba74 = n\u1ebfu/c\u1ee9 l\xe0m l\xe2u th\xec. \uc815\uc774 \ub4e4\ub2e4 = tr\u1edf n\xean g\u1eafn b\xf3.")
A.fgr=new B.a8("\ud608\uc5f0, \uc9c0\uc5f0, \ud559\uc5f0 \ub4f1\uc744 \uc5f0\uace0 \uad00\uacc4\ub77c\uace0 \ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","Quan h\u1ec7 huy\u1ebft th\u1ed1ng, qu\xea qu\xe1n v\xe0 tr\u01b0\u1eddng h\u1ecdc c\xf3 th\u1ec3 \u0111\u01b0\u1ee3c g\u1ecdi l\xe0 c\xe1c quan h\u1ec7 \uc5f0\uace0.","-(\uc774)\ub77c\uace0 \ud560 \uc218 \uc788\ub2e4 = c\xf3 th\u1ec3 g\u1ecdi l\xe0.")
A.ffN=new B.a8("\uc5f0\uace0\ub9cc\uc744 \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud558\uba74 \uacf5\uc815\uc131\uc744 \ud574\uce60 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","N\u1ebfu ch\u1ec9 coi tr\u1ecdng c\xe1c m\u1ed1i quan h\u1ec7 th\xe2n quen th\xec c\xf3 th\u1ec3 l\xe0m t\u1ed5n h\u1ea1i t\xednh c\xf4ng b\u1eb1ng.","-\ub9cc = ch\u1ec9. \ud574\uce58\ub2e4 = l\xe0m t\u1ed5n h\u1ea1i.")
A.fg2=new B.a8("\ud604\ub300 \uc0ac\ud68c\uc5d0\uc11c\ub294 \uad00\uacc4\ubfd0\ub9cc \uc544\ub2c8\ub77c \uac1c\uc778\uc758 \ub2a5\ub825\uacfc \uacf5\uc815\ud55c \uc808\ucc28\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4.","Trong x\xe3 h\u1ed9i hi\u1ec7n \u0111\u1ea1i, kh\xf4ng ch\u1ec9 quan h\u1ec7 m\xe0 n\u0103ng l\u1ef1c c\xe1 nh\xe2n v\xe0 quy tr\xecnh c\xf4ng b\u1eb1ng c\u0169ng quan tr\u1ecdng.","N\ubfd0\ub9cc \uc544\ub2c8\ub77c = kh\xf4ng ch\u1ec9 N m\xe0 c\xf2n.")
