A.fbj=new B.G("\uc5f0\uace0 \uad00\uacc4\uc758 \uae0d\uc815\uc801\uc778 \uc5ed\ud560\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110\xe2u l\xe0 m\u1ed9t vai tr\xf2 t\xedch c\u1ef1c c\u1ee7a c\xe1c m\u1ed1i quan h\u1ec7 g\u1eafn k\u1ebft?",A.inI,0,"Quan h\u1ec7 gi\u1eefa con ng\u01b0\u1eddi c\xf3 th\u1ec3 gi\xfap m\u1ecdi ng\u01b0\u1eddi h\u1ed7 tr\u1ee3 nhau v\xe0 x\xe2y d\u1ef1ng l\xf2ng tin.")
A.fPT=s(["\uacf5\uc815\uc131\uc774 \uc57d\ud574\uc9c8 \uc218 \uc788\ub2e4.","\ubaa8\ub4e0 \uc0ac\ub78c\uc758 \ub2a5\ub825\uc774 \ub192\uc544\uc9c4\ub2e4.","\uad50\ud1b5\uc774 \uc88b\uc544\uc9c4\ub2e4.","\uc8fc\uac70\ube44\uac00 \ub0ae\uc544\uc9c4\ub2e4."],t.s)
A.f7U=new B.G("\uc5f0\uace0\ub97c \uc9c0\ub098\uce58\uac8c \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud560 \ub54c \uc0dd\uae38 \uc218 \uc788\ub294 \ubb38\uc81c\ub294 \ubb34\uc5c7\uc785\ub2c8\uae4c?","V\u1ea5n \u0111\u1ec1 n\xe0o c\xf3 th\u1ec3 ph\xe1t sinh khi qu\xe1 coi tr\u1ecdng quan h\u1ec7?",A.fPT,0,"Qu\xe1 \u01b0u ti\xean quan h\u1ec7 c\xf3 th\u1ec3 l\xe0m gi\u1ea3m t\xednh c\xf4ng b\u1eb1ng.")
A.ia6=s(["\ub2a5\ub825\uacfc \uacf5\uc815\ud55c \uae30\uc900\uc73c\ub85c \ud3c9\uac00\ud55c\ub2e4.","\uac19\uc740 \uace0\ud5a5 \uc0ac\ub78c\ub9cc \ubf51\ub294\ub2e4.","\uce5c\ucc99\uc744 \uba3c\uc800 \ubf51\ub294\ub2e4.","\uac19\uc740 \ud559\uad50 \ucd9c\uc2e0\ub9cc \ubf51\ub294\ub2e4."],t.s)
A.f6l=new B.G("\ucc44\uc6a9\uc5d0\uc11c \uac00\uc7a5 \ubc14\ub78c\uc9c1\ud55c \ud0dc\ub3c4\ub294 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Th\xe1i \u0111\u1ed9 ph\xf9 h\u1ee3p nh\u1ea5t trong tuy\u1ec3n d\u1ee5ng l\xe0 g\xec?",A.ia6,0,"Tuy\u1ec3n d\u1ee5ng n\xean d\u1ef1a tr\xean n\u0103ng l\u1ef1c v\xe0 ti\xeau chu\u1ea9n c\xf4ng b\u1eb1ng.")
A.hiS=s(["\uc5f0\uace0 \uad00\uacc4\ub294 \uc5b8\uc81c\ub098 \ub098\uc05c \uac83\uc774\ub2e4.","\ud608\uc5f0\uc740 \uac19\uc740 \ud559\uad50\ub97c \ub098\uc628 \uc0ac\ub78c\uc758 \uad00\uacc4\uc774\ub2e4.","\uc88b\uc740 \uc778\uac04\uad00\uacc4\ub97c \uc720\uc9c0\ud558\uba74\uc11c \uacf5\uc815\uc131\ub3c4 \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4.","\ud604\ub300 \uc0ac\ud68c\uc5d0\uc11c\ub294 \uac1c\uc778\uc758 \ub2a5\ub825\uc774 \uc804\ud600 \uc911\uc694\ud558\uc9c0 \uc54a\ub2e4."],t.s)
A.fao=new B.G("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung ph\xf9 h\u1ee3p v\u1edbi b\xe0i \u0111\u1ecdc.",A.hiS,2,"B\xe0i \u0111\u1ecdc nh\u1ea5n m\u1ea1nh c\u1ea7n duy tr\xec quan h\u1ec7 t\u1ed1t nh\u01b0ng \u0111\u1ed3ng th\u1eddi t\xf4n tr\u1ecdng n\u0103ng l\u1ef1c v\xe0 t\xednh c\xf4ng b\u1eb1ng.")
A.hki=s([A.f8f,A.f4g,A.f4o,A.f7T,A.fbx,A.f8y,A.fbj,A.f7U,A.f6l,A.fao],t.h)
A.ih4=s(["\ud6a8 = l\xf2ng hi\u1ebfu th\u1ea3o.","\uc608\uc808 = l\u1ec5 nghi v\xe0 ph\xe9p \u1ee9ng x\u1eed.","\uc815 = t\xecnh c\u1ea3m g\u1eafn b\xf3.","\uacf5\ub3d9\uccb4 \uc758\uc2dd = \xfd th\u1ee9c c\u1ed9ng \u0111\u1ed3ng.","\uc5f0\uace0 = m\u1ed1i li\xean h\u1ec7 gi\u1eefa ng\u01b0\u1eddi v\u1edbi ng\u01b0\u1eddi.","\ud608\uc5f0 = quan h\u1ec7 huy\u1ebft th\u1ed1ng.","\uc9c0\uc5f0 = quan h\u1ec7 qu\xea qu\xe1n/\u0111\u1ecba ph\u01b0\u01a1ng.","\ud559\uc5f0 = quan h\u1ec7 tr\u01b0\u1eddng h\u1ecdc.","\uc778\ub9e5 = m\u1ea1ng l\u01b0\u1edbi quan h\u1ec7 c\xe1 nh\xe2n.","\uacf5\uc815\uc131 = t\xednh c\xf4ng b\u1eb1ng.","\uc5f0\uace0 \uad00\uacc4\ub294 \uc11c\ub85c \ub3d5\uace0 \uc2e0\ub8b0\ub97c \uc313\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ud558\uc9c0\ub9cc \uc5f0\uace0\ub9cc\uc73c\ub85c \uc0ac\ub78c\uc744 \ud3c9\uac00\ud558\uba74 \uacf5\uc815\uc131\uc744 \ud574\uce60 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ud604\ub300 \uc0ac\ud68c\uc5d0\uc11c\ub294 \uc778\uac04\uad00\uacc4\uc640 \ud568\uaed8 \ub2a5\ub825\uacfc \uacf5\uc815\ud55c \uc808\ucc28\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4."],t.s)
A.f44=new B.dk(19,"\ubb38\ud654","\ud55c\uad6d\uc758 \uc804\ud1b5 \uac00\uce58\uc640 \uc5f0\uace0","Gi\xe1 tr\u1ecb truy\u1ec1n th\u1ed1ng v\xe0 c\xe1c m\u1ed1i quan h\u1ec7 g\u1eafn k\u1ebft \u1edf H\xe0n Qu\u1ed1c",A.hI5,A.iJc,A.iFO,A.fWC,"\uc804\ud1b5\uc801\uc778 \uac00\uce58\uc640 \ubcc0\ud654\ud558\ub294 \uc0ac\ud68c","\ud55c\uad6d \uc0ac\ud68c\uc5d0\uc11c\ub294 \uc804\ud1b5\uc801\uc73c\ub85c \uac00\uc871\uc744 \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud558\uace0 \uc5b4\ub978\uc744 \uc874\uc911\ud558\ub294 \ubb38\ud654\uac00 \ubc1c\ub2ec\ud574 \uc654\uc2b5\ub2c8\ub2e4.\n\n\ubd80\ubaa8\ub97c \uc874\uc911\ud558\uace0 \ubcf4\uc0b4\ud53c\ub294 \ud0dc\ub3c4\uc640 \uad00\ub828\ub41c \ud6a8\ub3c4 \uc911\uc694\ud55c \uc804\ud1b5 \uac00\uce58 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4. \ub610\ud55c \uc624\ub79c \uc2dc\uac04 \ud568\uaed8 \uc0dd\ud65c\ud558\uba74\uc11c \uc0dd\uae30\ub294 \ub530\ub73b\ud55c \uac10\uc815\uc774\ub098 \uce5c\ubc00\uac10\uc744 \ud45c\ud604\ud560 \ub54c '\uc815'\uc774\ub77c\ub294 \ub9d0\uc744 \uc0ac\uc6a9\ud558\uae30\ub3c4 \ud569\ub2c8\ub2e4.\n\n\uc0ac\ub78c\ub4e4\uc774 \ud568\uaed8 \uc0b4\uc544\uac00\uae30 \uc704\ud574\uc11c\ub294 \ub2e4\ub978 \uc0ac\ub78c\uc744 \ubc30\ub824\ud558\uace0 \uacf5\ub3d9\uccb4\ub97c \uc0dd\uac01\ud558\ub294 \ud0dc\ub3c4\ub3c4 \ud544\uc694\ud569\ub2c8\ub2e4.\n\n\ud55c\ud3b8 \ud55c\uad6d \uc0ac\ud68c\uc5d0\uc11c\ub294 \uac00\uc871, \uace0\ud5a5, \ud559\uad50 \ub4f1\uc744 \ud1b5\ud574 \uc0ac\ub78c \uc0ac\uc774\uc5d0 \ud2b9\ubcc4\ud55c \uad00\uacc4\uac00 \ud615\uc131\ub418\uae30\ub3c4 \ud569\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uad00\uacc4\ub97c \uc5f0\uace0\ub77c\uace0 \ud45c\ud604\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uac00\uc871\uc774\ub098 \uce5c\uc871\uc744 \ud1b5\ud574 \ub9cc\ub4e4\uc5b4\uc9c4 \uad00\uacc4\ub97c \ud608\uc5f0, \uac19\uc740 \uc9c0\uc5ed\uc774\ub098 \uace0\ud5a5\uc744 \uc911\uc2ec\uc73c\ub85c \ud55c \uad00\uacc4\ub97c \uc9c0\uc5f0, \uac19\uc740 \ud559\uad50\ub97c \uc911\uc2ec\uc73c\ub85c \ud55c \uad00\uacc4\ub97c \ud559\uc5f0\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4.\n\n\uc774\ub7ec\ud55c \uad00\uacc4\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc11c\ub85c \ub3c4\uc6c0\uc744 \uc8fc\uace0 \uc2e0\ub8b0\ub97c \ud615\uc131\ud558\ub294 \ub370 \uae0d\uc815\uc801\uc778 \uc5ed\ud560\uc744 \ud560 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uadf8\ub7ec\ub098 \ucde8\uc5c5\uc774\ub098 \ud3c9\uac00\uc640 \uac19\uc774 \uacf5\uc815\ud55c \ud310\ub2e8\uc774 \ud544\uc694\ud55c \uc0c1\ud669\uc5d0\uc11c \uac1c\uc778\uc758 \ub2a5\ub825\ubcf4\ub2e4 \uc5f0\uace0\ub97c \ub354 \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud55c\ub2e4\uba74 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ubd88\uacf5\uc815\ud55c \uacb0\uacfc\ub97c \uac00\uc838\uc62c \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ub530\ub77c\uc11c \ud604\ub300 \uc0ac\ud68c\uc5d0\uc11c\ub294 \uc88b\uc740 \uc778\uac04\uad00\uacc4\ub97c \uc720\uc9c0\ud558\uba74\uc11c\ub3c4 \ub2a5\ub825\uacfc \uacf5\uc815\ud55c \uc808\ucc28\ub97c \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud558\ub294 \ud0dc\ub3c4\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.\n","Trong x\xe3 h\u1ed9i H\xe0n Qu\u1ed1c, t\u1eeb truy\u1ec1n th\u1ed1ng \u0111\xe3 ph\xe1t tri\u1ec3n v\u0103n h\xf3a coi tr\u1ecdng gia \u0111\xecnh v\xe0 t\xf4n tr\u1ecdng ng\u01b0\u1eddi l\u1edbn tu\u1ed5i.\n\nL\xf2ng hi\u1ebfu th\u1ea3o, li\xean quan \u0111\u1ebfn th\xe1i \u0111\u1ed9 t\xf4n tr\u1ecdng v\xe0 ch\u0103m s\xf3c cha m\u1eb9, c\u0169ng l\xe0 m\u1ed9t trong nh\u1eefng gi\xe1 tr\u1ecb truy\u1ec1n th\u1ed1ng quan tr\u1ecdng. Ngo\xe0i ra, t\u1eeb \u201c\uc815\u201d th\u01b0\u1eddng \u0111\u01b0\u1ee3c s\u1eed d\u1ee5ng \u0111\u1ec3 di\u1ec5n t\u1ea3 t\xecnh c\u1ea3m \u1ea5m \xe1p ho\u1eb7c s\u1ef1 g\u1eafn b\xf3 h\xecnh th\xe0nh khi m\u1ecdi ng\u01b0\u1eddi s\u1ed1ng c\xf9ng nhau trong th\u1eddi gian d\xe0i.\n\n\u0110\u1ec3 m\u1ecdi ng\u01b0\u1eddi c\xf3 th\u1ec3 c\xf9ng chung s\u1ed1ng, th\xe1i \u0111\u1ed9 quan t\xe2m \u0111\u1ebfn ng\u01b0\u1eddi kh\xe1c v\xe0 \xfd th\u1ee9c v\u1ec1 c\u1ed9ng \u0111\u1ed3ng c\u0169ng c\u1ea7n thi\u1ebft.\n\nM\u1eb7t kh\xe1c, trong x\xe3 h\u1ed9i H\xe0n Qu\u1ed1c, nh\u1eefng m\u1ed1i quan h\u1ec7 \u0111\u1eb7c bi\u1ec7t gi\u1eefa con ng\u01b0\u1eddi c\xf3 th\u1ec3 \u0111\u01b0\u1ee3c h\xecnh th\xe0nh th\xf4ng qua gia \u0111\xecnh, qu\xea h\u01b0\u01a1ng ho\u1eb7c tr\u01b0\u1eddng h\u1ecdc. Nh\u1eefng m\u1ed1i li\xean h\u1ec7 n\xe0y c\xf3 th\u1ec3 \u0111\u01b0\u1ee3c g\u1ecdi l\xe0 \uc5f0\uace0.\n\nQuan h\u1ec7 h\xecnh th\xe0nh qua gia \u0111\xecnh ho\u1eb7c h\u1ecd h\xe0ng g\u1ecdi l\xe0 \ud608\uc5f0, quan h\u1ec7 d\u1ef1a tr\xean c\xf9ng khu v\u1ef1c ho\u1eb7c qu\xea h\u01b0\u01a1ng g\u1ecdi l\xe0 \uc9c0\uc5f0, c\xf2n quan h\u1ec7 d\u1ef1a tr\xean c\xf9ng tr\u01b0\u1eddng h\u1ecdc g\u1ecdi l\xe0 \ud559\uc5f0.\n\nNh\u1eefng m\u1ed1i quan h\u1ec7 n\xe0y c\xf3 th\u1ec3 c\xf3 vai tr\xf2 t\xedch c\u1ef1c trong vi\u1ec7c m\u1ecdi ng\u01b0\u1eddi gi\xfap \u0111\u1ee1 nhau v\xe0 x\xe2y d\u1ef1ng l\xf2ng tin.\n\nTuy nhi\xean, trong nh\u1eefng t\xecnh hu\u1ed1ng c\u1ea7n \u0111\xe1nh gi\xe1 c\xf4ng b\u1eb1ng nh\u01b0 tuy\u1ec3n d\u1ee5ng ho\u1eb7c \u0111\xe1nh gi\xe1 n\u0103ng l\u1ef1c, n\u1ebfu coi tr\u1ecdng quan h\u1ec7 h\u01a1n n\u0103ng l\u1ef1c c\xe1 nh\xe2n th\xec c\xf3 th\u1ec3 d\u1eabn \u0111\u1ebfn k\u1ebft qu\u1ea3 kh\xf4ng c\xf4ng b\u1eb1ng cho ng\u01b0\u1eddi kh\xe1c.\n\nV\xec v\u1eady trong x\xe3 h\u1ed9i hi\u1ec7n \u0111\u1ea1i, c\u1ea7n v\u1eeba duy tr\xec c\xe1c m\u1ed1i quan h\u1ec7 t\u1ed1t v\u1eeba coi tr\u1ecdng n\u0103ng l\u1ef1c v\xe0 quy tr\xecnh c\xf4ng b\u1eb1ng.\n","\ud68c\uc0ac\uc5d0\uc11c \uacf5\uc815\ud558\uac8c \ud3c9\uac00\ud558\uae30","\uc548: \ubbfc\uc218 \uc528, \uc774\ubc88\uc5d0 \uc0c8 \uc9c1\uc6d0\uc744 \ubf51\ub294\ub2e4\uace0 \ub4e4\uc5c8\uc5b4\uc694.\n\n\ubbfc\uc218: \ub124. \uc9c0\uc6d0\uc790\uac00 \uaf64 \ub9ce\ub2e4\uace0 \ud574\uc694.\n\n\uc548: \uc544\ub294 \uc0ac\ub78c\uc744 \ucd94\ucc9c\ud558\ub294 \uc9c1\uc6d0\ub3c4 \uc788\uaca0\ub124\uc694.\n\n\ubbfc\uc218: \ucd94\ucc9c\ud560 \uc218\ub294 \uc788\uc9c0\ub9cc \ucc44\uc6a9\uc740 \uacf5\uc815\ud558\uac8c \ud574\uc57c\uaca0\uc9c0\uc694.\n\n\uc548: \ub9de\uc544\uc694. \uc544\ub294 \uc0ac\ub78c\uc774\ub77c\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \ubf51\uc73c\uba74 \ubb38\uc81c\uac00 \ub420 \uc218 \uc788\uc744 \uac83 \uac19\uc544\uc694.\n\n\ubbfc\uc218: \ub124. \uacbd\ub825\uc774\ub098 \ub2a5\ub825 \uac19\uc740 \uae30\uc900\uc73c\ub85c \ud3c9\uac00\ud574\uc57c \ud569\ub2c8\ub2e4.\n\n\uc548: \ud55c\uad6d\uc5d0\uc11c\ub294 \ud608\uc5f0\uc774\ub098 \ud559\uc5f0\uc774\ub77c\ub294 \ub9d0\ub3c4 \uc790\uc8fc \ub4e3\ub294 \uac83 \uac19\uc544\uc694.\n\n\ubbfc\uc218: \uc0ac\ub78c \uc0ac\uc774\uc758 \uad00\uacc4\ub97c \uc124\uba85\ud560 \ub54c \uc0ac\uc6a9\ud558\ub294 \ub9d0\uc774\uc5d0\uc694.\n\n\uc548: \uc778\uac04\uad00\uacc4 \uc790\uccb4\ub294 \ub098\uc05c \uac83\uc774 \uc544\ub2c8\uc9c0\uc694?\n\n\ubbfc\uc218: \ubb3c\ub860\uc774\uc8e0. \uc11c\ub85c \ub3d5\uace0 \uc2e0\ub8b0\ub97c \uc313\ub294 \uac83\uc740 \uc88b\uc740 \uc77c\uc774\uc5d0\uc694.\n\n\uc548: \ud558\uc9c0\ub9cc \uacf5\uc815\ud55c \ud310\ub2e8\uc774 \ud544\uc694\ud55c \uc0c1\ud669\uc5d0\uc11c\ub294 \uc5f0\uace0\ub9cc \ubcf4\uace0 \uacb0\uc815\ud558\uba74 \uc548 \ub418\uaca0\ub124\uc694.\n\n\ubbfc\uc218: \ub9de\uc544\uc694. \uad00\uacc4\uc640 \uacf5\uc815\uc131\uc744 \uc798 \uad6c\ubd84\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.\n","An: Minsu, t\xf4i nghe n\xf3i l\u1ea7n n\xe0y c\xf4ng ty tuy\u1ec3n nh\xe2n vi\xean m\u1edbi.\n\nMinsu: V\xe2ng. Nghe n\xf3i c\xf3 kh\xe1 nhi\u1ec1u \u1ee9ng vi\xean.\n\nAn: Ch\u1eafc c\u0169ng c\xf3 nh\xe2n vi\xean gi\u1edbi thi\u1ec7u ng\u01b0\u1eddi quen nh\u1ec9.\n\nMinsu: C\xf3 th\u1ec3 gi\u1edbi thi\u1ec7u, nh\u01b0ng vi\u1ec7c tuy\u1ec3n d\u1ee5ng ph\u1ea3i \u0111\u01b0\u1ee3c th\u1ef1c hi\u1ec7n c\xf4ng b\u1eb1ng.\n\nAn: \u0110\xfang v\u1eady. N\u1ebfu ch\u1ec9 tuy\u1ec3n v\xec \u0111\xf3 l\xe0 ng\u01b0\u1eddi quen th\xec c\xf3 th\u1ec3 ph\xe1t sinh v\u1ea5n \u0111\u1ec1.\n\nMinsu: V\xe2ng. C\u1ea7n \u0111\xe1nh gi\xe1 d\u1ef1a tr\xean ti\xeau chu\u1ea9n nh\u01b0 kinh nghi\u1ec7m v\xe0 n\u0103ng l\u1ef1c.\n\nAn: \u1ede H\xe0n Qu\u1ed1c t\xf4i c\u0169ng th\u01b0\u1eddng nghe c\xe1c t\u1eeb nh\u01b0 \ud608\uc5f0 hay \ud559\uc5f0.\n\nMinsu: \u0110\xf3 l\xe0 nh\u1eefng t\u1eeb d\xf9ng khi n\xf3i v\u1ec1 c\xe1c m\u1ed1i quan h\u1ec7 gi\u1eefa ng\u01b0\u1eddi v\u1edbi ng\u01b0\u1eddi.\n\nAn: B\u1ea3n th\xe2n c\xe1c m\u1ed1i quan h\u1ec7 kh\xf4ng ph\u1ea3i l\xe0 \u0111i\u1ec1u x\u1ea5u \u0111\xfang kh\xf4ng?\n\nMinsu: T\u1ea5t nhi\xean. Gi\xfap \u0111\u1ee1 nhau v\xe0 x\xe2y d\u1ef1ng l\xf2ng tin l\xe0 \u0111i\u1ec1u t\u1ed1t.\n\nAn: Nh\u01b0ng trong t\xecnh hu\u1ed1ng c\u1ea7n \u0111\xe1nh gi\xe1 c\xf4ng b\u1eb1ng th\xec kh\xf4ng n\xean ch\u1ec9 nh\xecn v\xe0o quan h\u1ec7 \u0111\u1ec3 quy\u1ebft \u0111\u1ecbnh.\n\nMinsu: \u0110\xfang v\u1eady. Ph\xe2n bi\u1ec7t r\xf5 quan h\u1ec7 c\xe1 nh\xe2n v\xe0 t\xednh c\xf4ng b\u1eb1ng l\xe0 \u0111i\u1ec1u quan tr\u1ecdng.\n",A.hVZ,A.hc1,A.hki,A.ih4)
A.h_s=s(["Hi\u1ec3u c\xe1c c\u01a1 s\u1edf y t\u1ebf th\u01b0\u1eddng g\u1eb7p \u1edf H\xe0n Qu\u1ed1c.","Bi\u1ebft t\u1eeb v\u1ef1ng c\u1ea7n thi\u1ebft khi \u0111i b\u1ec7nh vi\u1ec7n v\xe0 nh\xe0 thu\u1ed1c.","Hi\u1ec3u c\xe1c kh\xe1i ni\u1ec7m \uc9c4\ub8cc, \ucc98\ubc29\uc804, \uc57d\uad6d v\xe0 \uc751\uae09\uc2e4.","Bi\u1ebft c\xe1ch m\xf4 t\u1ea3 m\u1ed9t s\u1ed1 tri\u1ec7u ch\u1ee9ng c\u01a1 b\u1ea3n b\u1eb1ng ti\u1ebfng H\xe0n.","Hi\u1ec3u c\xe1ch x\u1eed l\xfd c\u01a1 b\u1ea3n khi x\u1ea3y ra t\xecnh hu\u1ed1ng kh\u1ea9n c\u1ea5p.","Bi\u1ebft s\u1ed1 119 d\xf9ng cho c\u1ee9u h\u1ecfa v\xe0 c\u1ea5p c\u1ee9u, 112 d\xf9ng \u0111\u1ec3 li\xean h\u1ec7 c\u1ea3nh s\xe1t.","Luy\u1ec7n \u0111\u1ecdc hi\u1ec3u v\xe0 c\xe2u h\u1ecfi v\u1ec1 y t\u1ebf v\xe0 an to\xe0n trong \u0111\u1eddi s\u1ed1ng."],t.s)
A.h_b=s(["\uc544\ud50c \ub54c\uc5d0\ub294 \uc99d\uc0c1\uc5d0 \ub530\ub77c \ubcd1\uc6d0\uc774\ub098 \uc758\uc6d0\uc744 \uc774\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc9c4\ub8cc\ub97c \ubc1b\uc740 \ud6c4 \uc758\uc0ac\uc758 \ucc98\ubc29\uc5d0 \ub530\ub77c \uc57d\uc744 \ubcf5\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ucc98\ubc29\uc804\uc774 \uc788\uc73c\uba74 \uc57d\uad6d\uc5d0\uc11c \ucc98\ubc29\ub41c \uc57d\uc744 \ubc1b\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc751\uae09\ud658\uc790\ub294 \uc751\uae09\uc2e4\uc744 \uc774\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ud654\uc7ac\ub098 \uc751\uae09\ud658\uc790\uac00 \ubc1c\uc0dd\ud55c \uacbd\uc6b0\uc5d0\ub294 119\uc5d0 \uc2e0\uace0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ubc94\uc8c4\ub098 \uacbd\ucc30\uc758 \ub3c4\uc6c0\uc774 \ud544\uc694\ud55c \uae34\uae09 \uc0c1\ud669\uc5d0\uc11c\ub294 112\uc5d0 \uc2e0\uace0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc0ac\uace0\ub97c \uc608\ubc29\ud558\uae30 \uc704\ud574 \ud3c9\uc18c\uc5d0 \uc548\uc804\uc218\uce59\uc744 \uc9c0\ud0a4\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\uae34\uae09 \uc0c1\ud669\uc5d0\uc11c\ub294 \ub2f9\ud669\ud558\uc9c0 \ub9d0\uace0 \uc790\uc2e0\uc758 \uc704\uce58\uc640 \uc0c1\ud669\uc744 \uc815\ud655\ud558\uac8c \uc54c\ub824 \uc8fc\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4."],t.s)
