A.iLv=s(["\ubcd1\uc6d0 = b\u1ec7nh vi\u1ec7n; \uc57d\uad6d = nh\xe0 thu\u1ed1c.","\uc9c4\ub8cc = kh\xe1m/\u0111i\u1ec1u tr\u1ecb y t\u1ebf; \ucc98\ubc29\uc804 = \u0111\u01a1n thu\u1ed1c.","\uc751\uae09\uc2e4 = ph\xf2ng c\u1ea5p c\u1ee9u.","\uc99d\uc0c1 = tri\u1ec7u ch\u1ee9ng; \uc9c8\ubcd1 = b\u1ec7nh.","\ubcf5\uc6a9\ud558\ub2e4 th\u01b0\u1eddng d\xf9ng cho vi\u1ec7c u\u1ed1ng ho\u1eb7c s\u1eed d\u1ee5ng thu\u1ed1c.","119 li\xean quan \u0111\u1ebfn c\u1ee9u h\u1ecfa v\xe0 c\u1ea5p c\u1ee9u; 112 li\xean quan \u0111\u1ebfn c\u1ea3nh s\xe1t.","\uc2e0\uace0\ud558\ub2e4 = b\xe1o cho c\u01a1 quan ch\u1ee9c n\u0103ng; \uc608\uc57d\ud558\ub2e4 = \u0111\u1eb7t l\u1ecbch tr\u01b0\u1edbc.","\ub300\ud53c\ud558\ub2e4 = r\u1eddi kh\u1ecfi khu v\u1ef1c nguy hi\u1ec3m \u0111\u1ec3 \u0111\u1ebfn n\u01a1i an to\xe0n."],t.s)
A.idX=s(["\uc758\ub8cc\uae30\uad00 \u2192 c\u01a1 s\u1edf y t\u1ebf.","\ubcd1\uc6d0 \u2022 \uc758\uc6d0 \u2192 n\u01a1i kh\xe1m ch\u1eefa b\u1ec7nh.","\uc57d\uad6d \u2192 nh\xe0 thu\u1ed1c.","\uc9c4\ub8cc \u2192 kh\xe1m v\xe0 \u0111i\u1ec1u tr\u1ecb.","\ucc98\ubc29\uc804 \u2192 \u0111\u01a1n thu\u1ed1c.","\uc751\uae09\uc2e4 \u2192 ph\xf2ng c\u1ea5p c\u1ee9u.","119 \u2192 c\u1ee9u h\u1ecfa v\xe0 c\u1ea5p c\u1ee9u.","112 \u2192 c\u1ea3nh s\xe1t.","\ud654\uc7ac \u2192 h\u1ecfa ho\u1ea1n.","\ub300\ud53c\ud558\ub2e4 \u2192 s\u01a1 t\xe1n.","\uc548\uc804\uc218\uce59 \u2192 quy t\u1eafc an to\xe0n.","\uc751\uae09\uc0c1\ud669\uc5d0\uc11c\ub294 \uc704\uce58\uc640 \uc0c1\ud669\uc744 \uc815\ud655\ud558\uac8c \uc54c\ub9ac\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4."],t.s)
