A.jJg=new B.aT("\ubb38\uc81c","v\u1ea5n \u0111\u1ec1","\ubb38\uc81c\uac00 \uc0dd\uae30\uba74 \ubc14\ub85c \ud574\uacb0\ud574\uc57c \ud569\ub2c8\ub2e4.","N\u1ebfu x\u1ea3y ra v\u1ea5n \u0111\u1ec1 th\xec ph\u1ea3i gi\u1ea3i quy\u1ebft ngay.","-(\uc73c)\uba74","\uc791\uc5c5 \uc911\uc5d0 \ubb38\uc81c\uac00 \uc0dd\uae30\uba74 \uad00\ub9ac\uc790\uc5d0\uac8c \ubc14\ub85c \uc54c\ub824 \uc8fc\uc138\uc694.","N\u1ebfu x\u1ea3y ra v\u1ea5n \u0111\u1ec1 trong l\xfac l\xe0m vi\u1ec7c th\xec h\xe3y b\xe1o ngay cho qu\u1ea3n l\xfd.")
A.jIg=new B.aT("\uc6d0\uc778","nguy\xean nh\xe2n","\uc0ac\uace0\uc758 \uc6d0\uc778\uc744 \uc815\ud655\ud788 \uc870\uc0ac\ud574\uc57c \ud569\ub2c8\ub2e4.","Ph\u1ea3i \u0111i\u1ec1u tra ch\xednh x\xe1c nguy\xean nh\xe2n c\u1ee7a tai n\u1ea1n.","-\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4","\ubd88\ub7c9\uc758 \uc6d0\uc778\uc744 \uc815\ud655\ud788 \ucc3e\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","Vi\u1ec7c t\xecm ch\xednh x\xe1c nguy\xean nh\xe2n c\u1ee7a s\u1ea3n ph\u1ea9m l\u1ed7i l\xe0 r\u1ea5t quan tr\u1ecdng.")
A.jHI=new B.aT("\ubc1c\uc0dd\ud558\ub2e4","ph\xe1t sinh, x\u1ea3y ra","\uc791\uc5c5 \uc911\uc5d0 \uc791\uc740 \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud588\uc2b5\ub2c8\ub2e4.","M\u1ed9t v\u1ea5n \u0111\u1ec1 nh\u1ecf \u0111\xe3 x\u1ea3y ra trong l\xfac l\xe0m vi\u1ec7c.","-(\uc73c)\uba74","\ubd88\ub7c9\uc774 \ubc1c\uc0dd\ud558\uba74 \uc791\uc5c5\uc744 \uba48\ucd94\uace0 \ubc14\ub85c \ubcf4\uace0\ud574 \uc8fc\uc138\uc694.","N\u1ebfu ph\xe1t sinh s\u1ea3n ph\u1ea9m l\u1ed7i th\xec h\xe3y d\u1eebng c\xf4ng vi\u1ec7c v\xe0 b\xe1o ngay.")
A.jIC=new B.aT("\ud574\uacb0\ud558\ub2e4","gi\u1ea3i quy\u1ebft","\ubb38\uc81c\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud574 \uc5ec\ub7ec \ubc29\ubc95\uc744 \ucc3e\uc544\ubcf4\uc558\uc2b5\ub2c8\ub2e4.","T\xf4i \u0111\xe3 th\u1eed t\xecm nhi\u1ec1u c\xe1ch \u0111\u1ec3 gi\u1ea3i quy\u1ebft v\u1ea5n \u0111\u1ec1.","-\uc544/\uc5b4 \ubcf4\ub2e4","\uba3c\uc800 \uc6d0\uc778\uc744 \ud655\uc778\ud55c \ud6c4 \ubb38\uc81c\ub97c \ud574\uacb0\ud574 \ubcf4\uc138\uc694.","Tr\u01b0\u1edbc ti\xean h\xe3y ki\u1ec3m tra nguy\xean nh\xe2n r\u1ed3i th\u1eed gi\u1ea3i quy\u1ebft v\u1ea5n \u0111\u1ec1.")
