A.jZK=new B.dL(22,"\ubb38\ubc95 \u2022 Ng\u1eef ph\xe1p so s\xe1nh","(   )\uc5d0 \ub4e4\uc5b4\uac08 \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.",u.B,"\uc9c0\uc5ed \uc8fc\ubbfc\ub4e4\uacfc \uc790\uc8fc \uc774\uc57c\uae30\ub97c (   ) \uc11c\ub85c\uc758 \ubb38\ud654\ub97c \ub354 \uc798 \uc774\ud574\ud558\uac8c \ub429\ub2c8\ub2e4.",A.i2c,"\ub098\ub20c\uc218\ub85d","\u201c-(\uc73c)\u3139\uc218\ub85d\u201d th\u1ec3 hi\u1ec7n m\u1ee9c \u0111\u1ed9 t\u0103ng d\u1ea7n: c\xe0ng th\u01b0\u1eddng xuy\xean tr\xf2 chuy\u1ec7n th\xec c\xe0ng hi\u1ec3u v\u0103n h\xf3a c\u1ee7a nhau.")
A.hhZ=s(["\uc774\ub3d9 \ub3c4\uc11c\uad00\uc740 \ub9e4\uc77c \uac19\uc740 \uc7a5\uc18c\ub9cc \ubc29\ubb38\ud55c\ub2e4.","\uc8fc\ubbfc\ub4e4\uc740 \uc774\ub3d9 \ub3c4\uc11c\uad00\uc5d0\uc11c \ucc45\uc744 \ubc18\ub0a9\ud560 \uc218 \uc5c6\ub2e4.","\uc6d0\ud558\ub294 \ucc45\uc774 \uc5c6\uc744 \ub54c \ub2e4\uc74c \ubc29\ubb38 \uc804\uc5d0 \uc2e0\uccad\ud560 \uc218 \uc788\ub2e4.","\uc774\ub3d9 \ub3c4\uc11c\uad00\uc5d0\ub294 \ud55c\uad6d\uc5b4\ub85c \ub41c \ucc45\ub9cc \uc900\ube44\ub418\uc5b4 \uc788\ub2e4."],t.s)
A.jZD=new B.dL(23,"\uc77d\uae30 \u2022 \u0110\u1ecdc hi\u1ec3u d\xe0i","\uc774 \uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung \u0111\xfang v\u1edbi \u0111o\u1ea1n v\u0103n.","\uc6b0\ub9ac \uc9c0\uc5ed \ub3c4\uc11c\uad00\uc740 \ub3c4\uc11c\uad00\uc744 \ubc29\ubb38\ud558\uae30 \uc5b4\ub824\uc6b4 \uc8fc\ubbfc\ub4e4\uc744 \uc704\ud574 \uc774\ub3d9 \ub3c4\uc11c\uad00\uc744 \uc6b4\uc601\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub3d9 \ub3c4\uc11c\uad00 \ucc28\ub7c9\uc740 \ub9e4\uc8fc \uc815\ud574\uc9c4 \uc694\uc77c\uc5d0 \ub18d\ucd0c \ub9c8\uc744\uacfc \ubcf5\uc9c0\uad00\uc744 \ubc29\ubb38\ud569\ub2c8\ub2e4. \uc8fc\ubbfc\ub4e4\uc740 \ud604\uc7a5\uc5d0\uc11c \ucc45\uc744 \ube4c\ub9ac\uac70\ub098 \ubc18\ub0a9\ud560 \uc218 \uc788\uace0, \uc6d0\ud558\ub294 \ucc45\uc774 \uc5c6\uc73c\uba74 \ub2e4\uc74c \ubc29\ubb38 \uc804\uc5d0 \ubbf8\ub9ac \uc2e0\uccad\ud560 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ucd5c\uadfc\uc5d0\ub294 \ud070 \uae00\uc790 \ucc45\uacfc \uc5ec\ub7ec \uc5b8\uc5b4\ub85c \ub41c \uc0dd\ud65c \uc548\ub0b4 \uc790\ub8cc\ub3c4 \ub298\ub838\uc2b5\ub2c8\ub2e4.",A.hhZ,"\uc6d0\ud558\ub294 \ucc45\uc774 \uc5c6\uc744 \ub54c \ub2e4\uc74c \ubc29\ubb38 \uc804\uc5d0 \uc2e0\uccad\ud560 \uc218 \uc788\ub2e4.","N\u1ebfu kh\xf4ng c\xf3 cu\u1ed1n s\xe1ch mong mu\u1ed1n, c\u01b0 d\xe2n c\xf3 th\u1ec3 \u0111\u0103ng k\xfd tr\u01b0\u1edbc l\u1ea7n xe th\u01b0 vi\u1ec7n gh\xe9 th\u0103m ti\u1ebfp theo.")
A.hSz=s(["\ud55c\uae00","\ud55c\ubcf5","\ud55c\uc625","\ud310\uc18c\ub9ac"],t.s)
A.k_0=new B.dL(24,"\uc5ed\uc0ac\xb7\ubb38\ud654 \u2022 L\u1ecbch s\u1eed v\xe0 v\u0103n h\xf3a","\ub2e4\uc74c \uc124\uba85\uc5d0 \ud574\ub2f9\ud558\ub294 \uac83\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.",u.g,"\uc870\uc120 \uc2dc\ub300\uc5d0 \ubc31\uc131\ub4e4\uc774 \uc790\uc2e0\uc758 \uc0dd\uac01\uc744 \uc27d\uac8c \uae00\ub85c \ud45c\ud604\ud560 \uc218 \uc788\ub3c4\ub85d \ub9cc\ub4e4\uc5b4\uc84c\uc2b5\ub2c8\ub2e4. \uae00\uc790\uc758 \ubaa8\uc591\uc740 \ubc1c\uc74c \uae30\uad00\uacfc \ud558\ub298, \ub545, \uc0ac\ub78c\uc758 \ubaa8\uc2b5\uc744 \uae30\ubcf8\uc73c\ub85c \uc0bc\uc558\uc2b5\ub2c8\ub2e4.",A.hSz,"\ud55c\uae00","Ph\u1ea7n m\xf4 t\u1ea3 n\xf3i v\u1ec1 Hangeul, h\u1ec7 ch\u1eef \u0111\u01b0\u1ee3c t\u1ea1o ra d\u01b0\u1edbi th\u1eddi Joseon \u0111\u1ec3 ng\u01b0\u1eddi d\xe2n d\u1ec5 h\u1ecdc v\xe0 th\u1ec3 hi\u1ec7n suy ngh\u0129 b\u1eb1ng ch\u1eef vi\u1ebft.")
A.hdq=s(["\uc8fc\ubb38 \ub0b4\uc5ed\uacfc \uc81c\ud488 \uc0c1\ud0dc\ub97c \ud655\uc778\ud560 \uc218 \uc788\ub294 \uc790\ub8cc\ub97c \uc900\ube44\ud55c\ub2e4.","\uc81c\ud488\uc744 \uc9c1\uc811 \ubd84\ud574\ud55c \ud6c4 \ud310\ub9e4\uc790\uc5d0\uac8c \ubcf4\ub0b8\ub2e4.","\ubb38\uc81c\uac00 \uc788\uc9c0\ub9cc \ud310\ub9e4\uc790\uc5d0\uac8c \uc54c\ub9ac\uc9c0 \uc54a\uace0 \uacc4\uc18d \uc0ac\uc6a9\ud55c\ub2e4.","\uc8fc\ubb38\ud55c \uc0ac\uc774\ud2b8\uc640 \uad00\uacc4\uc5c6\ub294 \uac00\uac8c\uc5d0 \uad50\ud658\uc744 \uc694\uad6c\ud55c\ub2e4."],t.s)
A.k_1=new B.dL(25,"\uc18c\ube44 \uc0dd\ud65c \u2022 T\xecnh hu\u1ed1ng ti\xeau d\xf9ng","\ub2e4\uc74c \uc0c1\ud669\uc5d0\uc11c \uac00\uc7a5 \uc54c\ub9de\uc740 \ud589\ub3d9\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn c\xe1ch x\u1eed l\xfd ph\xf9 h\u1ee3p nh\u1ea5t trong t\xecnh hu\u1ed1ng sau.","\uc628\ub77c\uc778\uc73c\ub85c \uc8fc\ubb38\ud55c \uc804\uae30 \uc8fc\uc804\uc790\ub97c \ubc1b\uc544 \uc0ac\uc6a9\ud574 \ubcf4\ub2c8 \uc804\uc6d0\uc774 \uacc4\uc18d \uaebc\uc84c\uc2b5\ub2c8\ub2e4. \ud310\ub9e4\uc790\uc5d0\uac8c \uc81c\ud488\uc758 \ubb38\uc81c\ub97c \uc124\uba85\ud558\uace0 \uad50\ud658\uc744 \uc694\uccad\ud558\ub824\uace0 \ud569\ub2c8\ub2e4.",A.hdq,"\uc8fc\ubb38 \ub0b4\uc5ed\uacfc \uc81c\ud488 \uc0c1\ud0dc\ub97c \ud655\uc778\ud560 \uc218 \uc788\ub294 \uc790\ub8cc\ub97c \uc900\ube44\ud55c\ub2e4.","Khi y\xeau c\u1ea7u \u0111\u1ed5i s\u1ea3n ph\u1ea9m l\u1ed7i, n\xean chu\u1ea9n b\u1ecb th\xf4ng tin \u0111\u01a1n h\xe0ng v\xe0 t\xe0i li\u1ec7u th\u1ec3 hi\u1ec7n t\xecnh tr\u1ea1ng s\u1ea3n ph\u1ea9m \u0111\u1ec3 trao \u0111\u1ed5i v\u1edbi ng\u01b0\u1eddi b\xe1n.")
A.iOH=s(["\uace0\ucce4\uc2b5\ub2c8\ub2e4","\ud3ec\uae30\ud588\uc2b5\ub2c8\ub2e4","\uc228\uacbc\uc2b5\ub2c8\ub2e4","\uad6c\ubd84\ud588\uc2b5\ub2c8\ub2e4"],t.s)
A.jZR=new B.dL(26,"\uc5b4\ud718 \u2022 T\u1eeb v\u1ef1ng ch\xednh s\xe1ch","\ubc11\uc904 \uce5c \ub9d0\uacfc \uc758\ubbf8\uac00 \uac00\uc7a5 \ube44\uc2b7\ud55c \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.",u.o,"\uc2dc\ub294 \uc8fc\ubbfc\ub4e4\uc758 \uc758\uacac\uc744 \ubc18\uc601\ud574 \uae30\uc874 \uad50\ud1b5 \ub300\ucc45\uc758 \ubd80\uc871\ud55c \uc810\uc744 \ubcf4\uc644\ud588\uc2b5\ub2c8\ub2e4.",A.iOH,"\uace0\ucce4\uc2b5\ub2c8\ub2e4","\u201c\ubd80\uc871\ud55c \uc810\uc744 \ubcf4\uc644\ud558\ub2e4\u201d ngh\u0129a l\xe0 b\u1ed5 sung v\xe0 s\u1eeda ch\u1eefa nh\u1eefng \u0111i\u1ec3m c\xf2n thi\u1ebfu s\xf3t.")
